/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2014_SEED = {"dse/writing/part-b/2014/Q2":[{"front":"give old equipment a second life","meaning":"讓舊設備重獲新生","examples":[{"en":"The school hopes to give old equipment a second life.","zh":"學校希望讓舊設備重獲新生。"},{"en":"To give old equipment a second life means to reuse it in a new place instead of throwing it away.","zh":"讓舊設備重獲新生，是指把它放到新地方重新使用，而不是丟棄。"},{"en":"A school can give old computers a second life by using them in a homework room.","zh":"學校可以把舊電腦放在功課室使用，讓它們重獲新生。"},{"en":"Giving old equipment a second life reduces waste and helps people who lack resources.","zh":"讓舊設備重獲新生可以減少浪費，並幫助缺乏資源的人。"},{"en":"This phrase shows that something old can still have value if it is safe and useful.","zh":"這個短語顯示，只要安全和有用，舊東西仍然有價值。"}],"source":"2014 Q2.pdf","sourcePage":1},{"front":"Dear Manager","meaning":"經理鈞鑒","examples":[{"en":"A formal request letter may begin with “Dear Manager”.","zh":"正式請求信可以以「經理鈞鑒」開始。"},{"en":"Dear Manager is a polite greeting used when writing formally to the manager of an organisation.","zh":"「經理鈞鑒」是正式寫信給機構經理時使用的禮貌稱呼。"},{"en":"A student may write “Dear Manager” when asking a fitness centre for support.","zh":"學生向健身中心請求支援時，可能會寫「經理鈞鑒」。"},{"en":"This greeting shows respect even when the writer does not know the manager’s name.","zh":"即使作者不知道經理姓名，這個稱呼也能表示尊重。"},{"en":"It is more suitable for a formal request than a casual greeting.","zh":"它比隨意問候更適合正式請求信。"}],"source":"2014 Q2.pdf","sourcePage":1},{"front":"request for donation","meaning":"捐贈請求","examples":[{"en":"The letter is a request for donation of old fitness equipment.","zh":"這封信是一封請求捐贈舊健身設備的信。"},{"en":"A request for donation is a formal or polite appeal asking someone to give items, money, or support.","zh":"捐贈請求是禮貌或正式地請求別人提供物品、金錢或支援。"},{"en":"A school may send a request for donation when it needs books for a reading corner.","zh":"學校需要圖書角書本時，可能會發出捐贈請求。"},{"en":"A good request for donation explains the need, the benefit, and how the donation will be used.","zh":"好的捐贈請求會解釋需要、好處，以及捐贈會如何被使用。"},{"en":"This phrase shows that the writer is asking for help respectfully, not demanding it.","zh":"這個短語顯示作者是在尊重地求助，而不是命令別人。"}],"source":"2014 Q2.pdf","sourcePage":1},{"front":"old fitness equipment","meaning":"舊健身設備","examples":[{"en":"The school is asking for old fitness equipment.","zh":"學校正在請求舊健身設備。"},{"en":"Old fitness equipment means exercise machines or tools that have been used before but may still work safely.","zh":"舊健身設備是指已被使用過但可能仍能安全運作的運動器材或工具。"},{"en":"Old fitness equipment can include exercise bikes, mats, benches, and light dumbbells.","zh":"舊健身設備可以包括健身單車、墊、健身椅和輕量啞鈴。"},{"en":"If old fitness equipment is safe, it can help students exercise without expensive facilities.","zh":"如果舊健身設備安全，它可以幫助學生不用昂貴設施也能運動。"},{"en":"This phrase focuses on reuse rather than waste.","zh":"這個短語著重重用，而不是浪費。"}],"source":"2014 Q2.pdf","sourcePage":1},{"front":"write on behalf of","meaning":"代表……寫信","examples":[{"en":"I am writing on behalf of the Sports Club.","zh":"我代表體育學會寫信。"},{"en":"To write on behalf of someone means to write as their representative.","zh":"代表某人或某組織寫信，是指以他們的代表身份寫信。"},{"en":"A class monitor may write on behalf of classmates to request more library time.","zh":"班長可能代表同學寫信，請求更多圖書館使用時間。"},{"en":"Writing on behalf of a club shows that the request comes from a group, not just one person.","zh":"代表學會寫信顯示請求來自一個群體，而不只是個人。"},{"en":"This phrase is useful in formal letters from organisations or student groups.","zh":"這個短語適用於機構或學生組織的正式信件。"}],"source":"2014 Q2.pdf","sourcePage":1},{"front":"Sports Club","meaning":"體育學會","examples":[{"en":"The Sports Club hopes to build a fitness corner for students.","zh":"體育學會希望為學生建立健身角。"},{"en":"A Sports Club is a school group that organises sports activities and promotes exercise.","zh":"體育學會是籌辦體育活動並推廣運動的學校組織。"},{"en":"A Sports Club may arrange training sessions, competitions, and health campaigns.","zh":"體育學會可能安排訓練時段、比賽和健康推廣活動。"},{"en":"Students join a Sports Club to improve fitness, teamwork, and discipline.","zh":"學生加入體育學會，是為了改善體能、團隊合作和紀律。"},{"en":"This phrase names the group responsible for the request.","zh":"這個短語指出提出請求的組織。"}],"source":"2014 Q2.pdf","sourcePage":1},{"front":"understand that","meaning":"得悉","examples":[{"en":"We understand that your fitness centre is being renovated.","zh":"我們得悉貴健身中心正在翻新。"},{"en":"Understand that means know or have been informed that something is true.","zh":"得悉是指知道或獲告知某事是真實的。"},{"en":"We understand that the library will close early during renovation.","zh":"我們得悉圖書館在翻新期間會提早關閉。"},{"en":"This phrase sounds polite because it shows the writer has considered the receiver’s situation.","zh":"這個短語聽起來有禮貌，因為它顯示作者已考慮收信人的情況。"},{"en":"It often introduces the reason behind a request.","zh":"它常用來引出請求背後的原因。"}],"source":"2014 Q2.pdf","sourcePage":1},{"front":"fitness centre","meaning":"健身中心","examples":[{"en":"Your fitness centre may soon replace some existing equipment.","zh":"貴健身中心可能很快會更換一些現有設備。"},{"en":"A fitness centre is a place where people exercise using machines, weights, classes, or training facilities.","zh":"健身中心是人們使用機器、重量、課堂或訓練設施做運動的地方。"},{"en":"A fitness centre may have treadmills, exercise bikes, yoga rooms, and strength-training areas.","zh":"健身中心可能有跑步機、健身單車、瑜伽室和肌力訓練區。"},{"en":"When a fitness centre upgrades equipment, some older items may still be useful elsewhere.","zh":"當健身中心升級設備時，一些舊物品在其他地方仍可能有用。"},{"en":"This phrase refers to the organisation being asked for a donation.","zh":"這個短語指被請求捐贈的機構。"}],"source":"2014 Q2.pdf","sourcePage":1},{"front":"be renovated","meaning":"正在翻新","examples":[{"en":"The fitness centre is being renovated.","zh":"健身中心正在翻新。"},{"en":"To be renovated means to be repaired, improved, or redesigned.","zh":"正在翻新是指正在被維修、改善或重新設計。"},{"en":"A school hall may be renovated with new lights, flooring, and seats.","zh":"學校禮堂可能透過更換燈光、地板和座椅來翻新。"},{"en":"When a place is renovated, old equipment may be removed to make room for new items.","zh":"當一個地方正在翻新時，舊設備可能會被移走，以騰出空間給新物品。"},{"en":"This phrase explains why useful equipment may become available.","zh":"這個短語解釋為何有用設備可能變得可供使用。"}],"source":"2014 Q2.pdf","sourcePage":1},{"front":"existing equipment","meaning":"現有設備","examples":[{"en":"Some of your existing equipment may soon be replaced.","zh":"貴中心一些現有設備可能很快會被更換。"},{"en":"Existing equipment means the machines or tools that are currently being used.","zh":"現有設備是指目前正在使用的機器或工具。"},{"en":"A gym’s existing equipment may include bikes, mats, benches, and weights.","zh":"健身室的現有設備可能包括單車、墊、健身椅和重物。"},{"en":"Existing equipment may look old but still be safe and serviceable.","zh":"現有設備可能看起來舊，但仍然安全和可使用。"},{"en":"This phrase helps identify the items that could be donated.","zh":"這個短語幫助指出可能被捐贈的物品。"}],"source":"2014 Q2.pdf","sourcePage":1},{"front":"be replaced","meaning":"被更換","examples":[{"en":"Some existing equipment may soon be replaced.","zh":"一些現有設備可能很快會被更換。"},{"en":"To be replaced means to be taken away and exchanged for something newer or different.","zh":"被更換是指被移走，並由更新或不同的東西代替。"},{"en":"Old classroom chairs may be replaced when a school buys new furniture.","zh":"當學校購買新家具時，舊課室椅子可能會被更換。"},{"en":"Equipment that is replaced is not always useless; it may still serve another community.","zh":"被更換的設備不一定沒有用；它仍可能服務另一個社群。"},{"en":"This phrase shows how renovation can create a chance for donation.","zh":"這個短語顯示翻新如何創造捐贈機會。"}],"source":"2014 Q2.pdf","sourcePage":2},{"front":"clearing space for","meaning":"騰出空間給","examples":[{"en":"Renovation usually means clearing space for something newer.","zh":"翻新通常代表騰出空間給更新的東西。"},{"en":"Clearing space for something means removing old items so there is room for a new use or object.","zh":"騰出空間給某物，是指移走舊物品，好讓新用途或新物件有位置。"},{"en":"A classroom may clear space for a reading corner by moving unused desks away.","zh":"課室可以透過移走不用的書桌，騰出空間給閱讀角。"},{"en":"A gym clearing space for new machines may still have old equipment that others can use.","zh":"健身室騰出空間給新機器時，仍可能有舊設備可供別人使用。"},{"en":"This phrase links physical removal with a new opportunity.","zh":"這個短語把實體移走與新機會連接起來。"}],"source":"2014 Q2.pdf","sourcePage":2},{"front":"create an opportunity to","meaning":"創造機會去","examples":[{"en":"Renovation can create an opportunity to reuse old equipment.","zh":"翻新可以創造機會去重用舊設備。"},{"en":"To create an opportunity to do something means to make it possible for that action to happen.","zh":"創造機會去做某事，是指使該行動有可能發生。"},{"en":"A school fair can create an opportunity to raise money for new books.","zh":"學校嘉年華可以創造機會去為新書籌款。"},{"en":"Renovation creates an opportunity when items are no longer needed but still usable.","zh":"當物品不再需要但仍可使用時，翻新就創造了機會。"},{"en":"This phrase shows how change can lead to a useful new action.","zh":"這個短語顯示改變如何帶來有用的新行動。"}],"source":"2014 Q2.pdf","sourcePage":2},{"front":"useful resources","meaning":"有用資源","examples":[{"en":"Old equipment can still be useful resources for students.","zh":"舊設備對學生來說仍可以是有用資源。"},{"en":"Useful resources are things that help people learn, work, practise, or solve problems.","zh":"有用資源是幫助人學習、工作、練習或解決問題的東西。"},{"en":"Old tablets can be useful resources in a classroom if they still work safely.","zh":"如果舊平板電腦仍能安全運作，它們可以成為課室中的有用資源。"},{"en":"Fitness equipment becomes a useful resource when students can train with it regularly.","zh":"當學生能定期用健身設備訓練時，設備就成為有用資源。"},{"en":"This phrase focuses on what an item can still do, not how new it looks.","zh":"這個短語著重物品仍能做甚麼，而不是它看起來有多新。"}],"source":"2014 Q2.pdf","sourcePage":2},{"front":"a second life","meaning":"第二生命；重新使用的機會","examples":[{"en":"Safe equipment can be given a second life at our school.","zh":"安全設備可以在我們學校獲得第二生命。"},{"en":"A second life means a new chance to be used after something seems old or no longer needed.","zh":"第二生命是指某物看似舊或不再需要後，獲得重新使用的新機會。"},{"en":"Old library shelves can have a second life as storage for art materials.","zh":"舊圖書館書架可以作為美術材料儲物架，得到第二生命。"},{"en":"Giving equipment a second life saves money and reduces waste.","zh":"給設備第二生命可以節省金錢並減少浪費。"},{"en":"This phrase suggests renewal, reuse, and continued value.","zh":"這個短語表示更新、重用和持續價值。"}],"source":"2014 Q2.pdf","sourcePage":2},{"front":"I would be grateful if","meaning":"如能……，我將不勝感激","examples":[{"en":"I would be grateful if your centre could consider a donation.","zh":"如貴中心能考慮捐贈，我將不勝感激。"},{"en":"I would be grateful if is a polite formal way to ask someone to do something.","zh":"如能……，我將不勝感激，是禮貌正式地請求別人做某事的說法。"},{"en":"I would be grateful if you could reply before Friday.","zh":"如你能在星期五前回覆，我將不勝感激。"},{"en":"This phrase sounds respectful because it does not pressure the receiver.","zh":"這個短語聽起來尊重，因為它不向收信人施壓。"},{"en":"It is useful in request letters, emails, and formal applications.","zh":"它適用於請求信、電郵和正式申請。"}],"source":"2014 Q2.pdf","sourcePage":2},{"front":"consider donating","meaning":"考慮捐贈","examples":[{"en":"Please consider donating safe, serviceable equipment to our school.","zh":"請考慮向我們學校捐贈安全而仍可使用的設備。"},{"en":"To consider donating means to think seriously about giving something to help others.","zh":"考慮捐贈是指認真思考是否給予某物來幫助別人。"},{"en":"A shop may consider donating unsold books to a community centre.","zh":"商店可能考慮把未售出的書捐贈給社區中心。"},{"en":"Asking someone to consider donating sounds polite because the final choice remains theirs.","zh":"請別人考慮捐贈聽起來有禮貌，因為最終選擇仍在對方手上。"},{"en":"This phrase invites generosity without sounding demanding.","zh":"這個短語邀請慷慨行動，而不顯得強求。"}],"source":"2014 Q2.pdf","sourcePage":2},{"front":"safe, serviceable equipment","meaning":"安全而仍可使用的設備","examples":[{"en":"We would accept only safe, serviceable equipment.","zh":"我們只會接受安全而仍可使用的設備。"},{"en":"Safe, serviceable equipment means equipment that is not dangerous and still works properly.","zh":"安全而仍可使用的設備，是指不危險並仍能正常運作的設備。"},{"en":"A school should check that donated exercise bikes are safe and serviceable before students use them.","zh":"學校應在學生使用前，檢查捐贈健身單車是否安全和仍可使用。"},{"en":"Equipment may be old but still serviceable if it has no serious damage.","zh":"設備可能舊，但如果沒有嚴重損壞，仍然可以使用。"},{"en":"This phrase shows that safety matters more than accepting everything.","zh":"這個短語顯示安全比接受所有東西更重要。"}],"source":"2014 Q2.pdf","sourcePage":2},{"front":"build a purposeful fitness corner","meaning":"建立有明確用途的健身角","examples":[{"en":"The donation would help us build a purposeful fitness corner.","zh":"這項捐贈會幫助我們建立有明確用途的健身角。"},{"en":"To build a purposeful fitness corner means to create a small exercise area with clear aims and proper use.","zh":"建立有明確用途的健身角，是指創造一個有清晰目標和正確使用方式的小型運動區。"},{"en":"A school can build a purposeful fitness corner for stretching, strength training, and stress relief.","zh":"學校可以建立有明確用途的健身角，用於拉筋、肌力訓練和減壓。"},{"en":"Such a corner works best when equipment, rules, and supervision are planned together.","zh":"當設備、規則和監督一起規劃時，這樣的健身角最有效。"},{"en":"This phrase shows that the school wants a meaningful facility, not random storage.","zh":"這個短語顯示學校想要有意義的設施，而不是隨便存放器材。"}],"source":"2014 Q2.pdf","sourcePage":2},{"front":"such a donation","meaning":"這樣的捐贈","examples":[{"en":"Such a donation would improve our sports facilities.","zh":"這樣的捐贈會改善我們的體育設施。"},{"en":"Such a donation means this kind of gift or support just mentioned.","zh":"這樣的捐贈是指剛才提到的這類禮物或支援。"},{"en":"Such a donation could help students who cannot afford private gym membership.","zh":"這樣的捐贈可以幫助負擔不起私人健身室會籍的學生。"},{"en":"A writer uses this phrase to refer back to the requested donation without repeating details.","zh":"作者使用這個短語來指回請求中的捐贈，而不用重複細節。"},{"en":"It helps connect the request with its expected benefits.","zh":"它幫助把請求與預期好處連接起來。"}],"source":"2014 Q2.pdf","sourcePage":2},{"front":"not merely","meaning":"不只是","examples":[{"en":"The donation would not merely improve our sports facilities.","zh":"這項捐贈不只是改善我們的體育設施。"},{"en":"Not merely means not only or not just one simple thing.","zh":"不只是是指不僅僅是一件簡單事情。"},{"en":"A school garden does not merely look beautiful; it also teaches students about nature.","zh":"學校花園不只是看起來美麗，也教學生認識自然。"},{"en":"This phrase prepares readers for a larger or deeper benefit.","zh":"這個短語為更大或更深層的好處作鋪墊。"},{"en":"It helps show that the donation has more than one purpose.","zh":"它幫助顯示捐贈有不只一個目的。"}],"source":"2014 Q2.pdf","sourcePage":3},{"front":"improve our sports facilities","meaning":"改善我們的體育設施","examples":[{"en":"The donation would improve our sports facilities.","zh":"這項捐贈會改善我們的體育設施。"},{"en":"To improve our sports facilities means to make the school’s exercise spaces and equipment better.","zh":"改善我們的體育設施，是指令學校的運動空間和設備變得更好。"},{"en":"Adding mats and resistance bands can improve sports facilities for beginners.","zh":"加入墊和阻力帶可以改善給初學者使用的體育設施。"},{"en":"Better facilities allow more students to exercise safely and regularly.","zh":"更好的設施讓更多學生能安全和定期運動。"},{"en":"This phrase explains the direct practical benefit of the donation.","zh":"這個短語解釋捐贈的直接實際好處。"}],"source":"2014 Q2.pdf","sourcePage":3},{"front":"allow your centre to demonstrate","meaning":"讓貴中心展示","examples":[{"en":"The donation would allow your centre to demonstrate community leadership.","zh":"這項捐贈會讓貴中心展示社區領導作用。"},{"en":"To allow your centre to demonstrate something means to give it a chance to show that quality through action.","zh":"讓貴中心展示某種特質，是指給它機會透過行動顯示那種特質。"},{"en":"Donating equipment would allow a business to demonstrate care for local students.","zh":"捐贈設備會讓企業展示對本地學生的關心。"},{"en":"Public generosity lets an organisation prove its values, not just advertise them.","zh":"公開的慷慨行動讓機構證明價值，而不只是宣傳價值。"},{"en":"This phrase connects the donation with the donor’s reputation and values.","zh":"這個短語把捐贈與捐贈者的聲譽和價值連接起來。"}],"source":"2014 Q2.pdf","sourcePage":3},{"front":"community leadership","meaning":"社區領導作用","examples":[{"en":"The donation would demonstrate community leadership.","zh":"這項捐贈會展示社區領導作用。"},{"en":"Community leadership means taking responsible action that helps and guides the local community.","zh":"社區領導作用是指採取負責任行動，幫助和引導本地社區。"},{"en":"A business shows community leadership when it supports youth programmes or public health activities.","zh":"企業支援青年計劃或公共健康活動時，就是展示社區領導作用。"},{"en":"Community leadership builds trust because people see the organisation helping beyond profit.","zh":"社區領導作用能建立信任，因為人們看見機構在盈利以外作出幫助。"},{"en":"This phrase presents donation as responsible local action.","zh":"這個短語把捐贈呈現為負責任的本地行動。"}],"source":"2014 Q2.pdf","sourcePage":3},{"front":"environmental responsibility","meaning":"環保責任","examples":[{"en":"Reusing equipment would show environmental responsibility.","zh":"重用設備會顯示環保責任。"},{"en":"Environmental responsibility means acting in ways that reduce waste and protect nature.","zh":"環保責任是指以減少浪費和保護自然的方式行動。"},{"en":"A company shows environmental responsibility when it repairs items instead of throwing them away.","zh":"公司修理物品而不是丟棄時，就是顯示環保責任。"},{"en":"Donating usable equipment reduces waste and extends the life of resources.","zh":"捐贈可用設備可以減少浪費，並延長資源壽命。"},{"en":"This phrase links practical reuse with care for the environment.","zh":"這個短語把實際重用與關心環境連接起來。"}],"source":"2014 Q2.pdf","sourcePage":3},{"front":"care for young people","meaning":"關心年輕人","examples":[{"en":"The donation would show care for young people in the district.","zh":"這項捐贈會顯示對區內年輕人的關心。"},{"en":"Care for young people means concern for their health, growth, safety, and future.","zh":"關心年輕人是指關注他們的健康、成長、安全和未來。"},{"en":"A local business shows care for young people by supporting school activities.","zh":"本地企業支援學校活動時，就是顯示對年輕人的關心。"},{"en":"When young people receive useful resources, they feel valued by the community.","zh":"當年輕人得到有用資源時，他們會感到被社區重視。"},{"en":"This phrase gives the donation a human and social meaning.","zh":"這個短語賦予捐贈人性和社會意義。"}],"source":"2014 Q2.pdf","sourcePage":3},{"front":"in the district","meaning":"在區內","examples":[{"en":"The donation would benefit young people in the district.","zh":"這項捐贈會惠及區內年輕人。"},{"en":"In the district means in the local area or neighbourhood being discussed.","zh":"在區內是指在正在討論的本地區域或社區之中。"},{"en":"A sports programme in the district can serve students from nearby schools.","zh":"區內的體育計劃可以服務附近學校的學生。"},{"en":"Businesses in the district often understand local needs better than distant organisations.","zh":"區內企業通常比遙遠機構更了解本地需要。"},{"en":"This phrase places the benefit within a specific community.","zh":"這個短語把好處放在特定社區之中。"}],"source":"2014 Q2.pdf","sourcePage":3},{"front":"to begin with","meaning":"首先","examples":[{"en":"To begin with, the donation would make exercise more accessible.","zh":"首先，這項捐贈會令運動更容易接觸。"},{"en":"To begin with introduces the first reason or first point in an explanation.","zh":"首先是用來引出解釋中的第一個理由或觀點。"},{"en":"To begin with, students need safe equipment before they can train properly.","zh":"首先，學生需要安全設備，才能好好訓練。"},{"en":"Writers use this phrase to organise an argument clearly.","zh":"作者使用這個短語來清楚組織論點。"},{"en":"It signals that more reasons may follow.","zh":"它表示之後可能還有更多理由。"}],"source":"2014 Q2.pdf","sourcePage":3},{"front":"make regular exercise more accessible","meaning":"令恆常運動更容易接觸","examples":[{"en":"The donation would make regular exercise more accessible to students.","zh":"這項捐贈會令學生更容易接觸恆常運動。"},{"en":"To make regular exercise more accessible means to make it easier for students to exercise often.","zh":"令恆常運動更容易接觸，是指令學生更容易經常做運動。"},{"en":"A fitness corner makes regular exercise more accessible because students can train at school.","zh":"健身角令恆常運動更容易接觸，因為學生可以在學校訓練。"},{"en":"If exercise is accessible, more students can build healthy habits without extra cost.","zh":"如果運動容易接觸，更多學生可以不用額外花費也能建立健康習慣。"},{"en":"This phrase links equipment with equal opportunity for health.","zh":"這個短語把設備與健康上的平等機會連接起來。"}],"source":"2014 Q2.pdf","sourcePage":3},{"front":"students who need it most","meaning":"最需要它的學生","examples":[{"en":"The fitness corner would help students who need exercise most.","zh":"健身角會幫助最需要運動的學生。"},{"en":"Students who need it most are the students who would benefit most from the support.","zh":"最需要它的學生，是指從支援中得益最多的學生。"},{"en":"Students who cannot afford private gyms may be among those who need it most.","zh":"負擔不起私人健身室的學生可能是最需要它的人之一。"},{"en":"A good school programme should reach students who need it most, not only those already confident.","zh":"好的學校計劃應接觸最需要它的學生，而不只是已經有信心的學生。"},{"en":"This phrase focuses on fairness and targeted support.","zh":"這個短語著重公平和針對性支援。"}],"source":"2014 Q2.pdf","sourcePage":3},{"front":"at present","meaning":"目前","examples":[{"en":"At present, our school hall and playground are heavily used.","zh":"目前，我們的禮堂和操場使用率很高。"},{"en":"At present means now or at the current time.","zh":"目前是指現在或當前時間。"},{"en":"At present, many students have no quiet place to train after school.","zh":"目前，許多學生放學後沒有安靜地方訓練。"},{"en":"Writers use this phrase to describe the current problem before suggesting a solution.","zh":"作者使用這個短語，在提出解決方法前描述現時問題。"},{"en":"It helps show why action is needed now.","zh":"它幫助顯示為何現在需要行動。"}],"source":"2014 Q2.pdf","sourcePage":4},{"front":"school hall and playground","meaning":"禮堂和操場","examples":[{"en":"The school hall and playground are heavily used.","zh":"禮堂和操場使用率很高。"},{"en":"The school hall and playground are shared spaces used for assemblies, sports, activities, and student gatherings.","zh":"禮堂和操場是用於早會、運動、活動和學生聚集的共享空間。"},{"en":"A school hall may be used for exams, talks, performances, and indoor activities.","zh":"禮堂可能用作考試、講座、表演和室內活動。"},{"en":"When the hall and playground are always busy, students need another exercise space.","zh":"當禮堂和操場總是繁忙時，學生需要另一個運動空間。"},{"en":"This phrase shows the pressure on existing school facilities.","zh":"這個短語顯示現有學校設施所承受的壓力。"}],"source":"2014 Q2.pdf","sourcePage":4},{"front":"heavily used","meaning":"使用率很高","examples":[{"en":"Our school facilities are heavily used after class.","zh":"我們的學校設施在課後使用率很高。"},{"en":"Heavily used means used very often or by many people.","zh":"使用率很高，是指被很多人或很頻密地使用。"},{"en":"A library printer is heavily used when students queue for it every lunch break.","zh":"如果學生每個午休都要排隊使用圖書館打印機，它就是使用率很高。"},{"en":"Heavily used facilities may not be available to everyone who needs them.","zh":"使用率很高的設施未必能供所有有需要的人使用。"},{"en":"This phrase explains why extra equipment or space may be necessary.","zh":"這個短語解釋為何額外設備或空間可能是必要的。"}],"source":"2014 Q2.pdf","sourcePage":4},{"front":"school teams","meaning":"校隊","examples":[{"en":"Students who are not members of school teams need a place to train.","zh":"不是校隊成員的學生也需要地方訓練。"},{"en":"School teams are official groups of students who represent the school in sports competitions.","zh":"校隊是代表學校參加體育比賽的正式學生隊伍。"},{"en":"Basketball, football, athletics, and swimming teams can all be school teams.","zh":"籃球隊、足球隊、田徑隊和游泳隊都可以是校隊。"},{"en":"Students outside school teams may still need exercise for health and confidence.","zh":"校隊以外的學生仍可能為健康和信心而需要運動。"},{"en":"This phrase helps show that sports facilities should serve more than elite athletes.","zh":"這個短語幫助顯示體育設施不應只服務精英運動員。"}],"source":"2014 Q2.pdf","sourcePage":4},{"front":"find themselves with nowhere suitable to train","meaning":"發現自己沒有合適地方訓練","examples":[{"en":"Some students find themselves with nowhere suitable to train after class.","zh":"一些學生課後發現自己沒有合適地方訓練。"},{"en":"To find themselves with nowhere suitable to train means to realise they have no proper place for exercise practice.","zh":"發現自己沒有合適地方訓練，是指意識到自己沒有適當地方進行運動練習。"},{"en":"A beginner may find themselves with nowhere suitable to train if the playground is always booked.","zh":"如果操場總是被預訂，初學者可能發現自己沒有合適地方訓練。"},{"en":"This situation can stop students from building regular exercise habits.","zh":"這種情況可能阻止學生建立恆常運動習慣。"},{"en":"The phrase shows a practical barrier, not a lack of interest.","zh":"這個短語顯示的是實際障礙，而不是缺乏興趣。"}],"source":"2014 Q2.pdf","sourcePage":4},{"front":"after class","meaning":"課後","examples":[{"en":"Many students need a place to train after class.","zh":"許多學生課後需要地方訓練。"},{"en":"After class means after lessons have finished for the day.","zh":"課後是指一天的課堂結束之後。"},{"en":"Students may practise sports after class because lunchtime is too short.","zh":"學生可能在課後練習運動，因為午膳時間太短。"},{"en":"After-class activities help students relax, build skills, and meet friends.","zh":"課後活動幫助學生放鬆、建立技能和結識朋友。"},{"en":"This phrase places the training need in a normal school routine.","zh":"這個短語把訓練需要放在正常校園日常之中。"}],"source":"2014 Q2.pdf","sourcePage":4},{"front":"exercise bikes","meaning":"健身單車","examples":[{"en":"A few exercise bikes would help students train safely.","zh":"幾部健身單車會幫助學生安全訓練。"},{"en":"Exercise bikes are stationary bicycles used indoors for fitness training.","zh":"健身單車是在室內使用、用於體能訓練的固定單車。"},{"en":"Students can use exercise bikes to improve stamina without needing a large sports ground.","zh":"學生可以使用健身單車改善耐力，而不需要大型運動場。"},{"en":"Exercise bikes are useful for low-impact training because they reduce pressure on the knees.","zh":"健身單車對低撞擊訓練有用，因為它減少膝蓋壓力。"},{"en":"This equipment can support beginners and students recovering from minor injuries.","zh":"這種設備可以支援初學者和正在從輕傷中康復的學生。"}],"source":"2014 Q2.pdf","sourcePage":4},{"front":"yoga mats","meaning":"瑜伽墊","examples":[{"en":"Yoga mats could support stretching and warm-ups.","zh":"瑜伽墊可以支援拉筋和熱身。"},{"en":"Yoga mats are soft mats used for floor exercises, stretching, and balance activities.","zh":"瑜伽墊是用於地面運動、拉筋和平衡活動的軟墊。"},{"en":"Students can use yoga mats to stretch safely without lying directly on a hard floor.","zh":"學生可以使用瑜伽墊安全拉筋，而不用直接躺在硬地上。"},{"en":"Yoga mats make warm-ups more comfortable and hygienic.","zh":"瑜伽墊令熱身更舒適和衛生。"},{"en":"This simple equipment can support many kinds of fitness activities.","zh":"這種簡單設備可以支援多種健身活動。"}],"source":"2014 Q2.pdf","sourcePage":4},{"front":"resistance bands","meaning":"阻力帶","examples":[{"en":"Resistance bands are useful for basic strength training.","zh":"阻力帶對基礎肌力訓練很有用。"},{"en":"Resistance bands are stretchy exercise bands that create resistance when pulled.","zh":"阻力帶是有彈性的運動帶，拉動時會產生阻力。"},{"en":"Beginners can use resistance bands to train arms, shoulders, legs, and core muscles safely.","zh":"初學者可以使用阻力帶安全訓練手臂、肩膀、腿部和核心肌肉。"},{"en":"Resistance bands are easy to store and suitable for small school spaces.","zh":"阻力帶容易存放，適合細小學校空間。"},{"en":"This equipment helps students build strength without heavy machines.","zh":"這種設備幫助學生不用大型器械也能建立力量。"}],"source":"2014 Q2.pdf","sourcePage":4},{"front":"benches","meaning":"健身椅；長凳","examples":[{"en":"Benches would make the fitness corner more practical.","zh":"健身椅會令健身角更實用。"},{"en":"Benches are long seats or training supports used for sitting, resting, or exercise.","zh":"健身椅或長凳是用於坐下、休息或運動的長形座椅或訓練支撐。"},{"en":"In a fitness corner, benches can support step exercises, stretching, or light weight training.","zh":"在健身角中，健身椅可以支援踏步運動、拉筋或輕量重量訓練。"},{"en":"Benches also give students a safe place to rest between activities.","zh":"長凳也給學生在活動之間安全休息的地方。"},{"en":"This word can refer to simple seating or useful training equipment.","zh":"這個詞可以指簡單座椅，也可以指有用訓練器材。"}],"source":"2014 Q2.pdf","sourcePage":4},{"front":"light dumbbells","meaning":"輕量啞鈴","examples":[{"en":"Light dumbbells would help beginners train safely.","zh":"輕量啞鈴會幫助初學者安全訓練。"},{"en":"Light dumbbells are small hand weights that are not too heavy for basic strength training.","zh":"輕量啞鈴是不太重、用於基礎肌力訓練的小型手持重量。"},{"en":"Beginners can use light dumbbells to learn correct movement before lifting heavier weights.","zh":"初學者可以先用輕量啞鈴學習正確動作，再舉較重重量。"},{"en":"Light dumbbells reduce injury risk when students are still learning technique.","zh":"當學生仍在學習技巧時，輕量啞鈴能減少受傷風險。"},{"en":"This equipment is useful because it allows gradual progress.","zh":"這種設備有用，因為它容許逐步進步。"}],"source":"2014 Q2.pdf","sourcePage":5},{"front":"immediately change that","meaning":"立即改變這種情況","examples":[{"en":"A few pieces of equipment would immediately change that.","zh":"幾件設備會立即改變這種情況。"},{"en":"Immediately change that means quickly improve the problem just described.","zh":"立即改變這種情況，是指快速改善剛才描述的問題。"},{"en":"Adding three exercise bikes would immediately change the lack of training space for some students.","zh":"加入三部健身單車，可以立即改變一些學生缺乏訓練空間的情況。"},{"en":"A small donation can immediately change a situation if the need is simple and clear.","zh":"如果需要簡單清楚，小小捐贈也可以立即改變情況。"},{"en":"This phrase shows that even limited help can have a fast effect.","zh":"這個短語顯示即使有限幫助也可以有快速效果。"}],"source":"2014 Q2.pdf","sourcePage":5},{"front":"instead of treating fitness as","meaning":"而不是把健身視為","examples":[{"en":"We should not treat fitness as something only private-gym users can enjoy.","zh":"我們不應把健身視為只有私人健身室使用者才能享受的東西。"},{"en":"Instead of treating fitness as means not seeing exercise in that limited or unfair way.","zh":"而不是把健身視為某物，是指不要用那種有限或不公平的方式看待運動。"},{"en":"Schools should treat fitness as a basic need instead of treating it as a luxury.","zh":"學校應把健身視為基本需要，而不是把它視為奢侈品。"},{"en":"This phrase challenges a narrow view of who deserves access to exercise.","zh":"這個短語挑戰誰值得接觸運動的狹窄看法。"},{"en":"It helps argue that fitness should be shared more fairly.","zh":"它幫助論證健身應更公平地共享。"}],"source":"2014 Q2.pdf","sourcePage":5},{"front":"available only to","meaning":"只提供給","examples":[{"en":"Fitness should not be available only to students who can afford private gyms.","zh":"健身不應只提供給負擔得起私人健身室的學生。"},{"en":"Available only to means limited to a particular group and not open to everyone.","zh":"只提供給某些人，是指只限特定群體，而不是向所有人開放。"},{"en":"Good sports facilities should not be available only to students on school teams.","zh":"良好體育設施不應只提供給校隊學生。"},{"en":"If exercise is available only to wealthy students, health opportunities become unfair.","zh":"如果運動只提供給富裕學生，健康機會就會變得不公平。"},{"en":"This phrase highlights unequal access.","zh":"這個短語突出不平等的使用權。"}],"source":"2014 Q2.pdf","sourcePage":5},{"front":"afford private gyms","meaning":"負擔得起私人健身室","examples":[{"en":"Not every student can afford private gyms.","zh":"不是每個學生都負擔得起私人健身室。"},{"en":"To afford private gyms means to have enough money to pay for gym membership or use.","zh":"負擔得起私人健身室，是指有足夠金錢支付健身室會籍或使用費。"},{"en":"Some students cannot afford private gyms because their families must spend money on rent and food first.","zh":"有些學生負擔不起私人健身室，因為家庭必須先支付租金和食物開支。"},{"en":"School fitness facilities matter because they help students who cannot pay for private options.","zh":"學校健身設施很重要，因為它幫助無法支付私人選項的學生。"},{"en":"This phrase connects exercise access with family income.","zh":"這個短語把運動機會與家庭收入連接起來。"}],"source":"2014 Q2.pdf","sourcePage":5},{"front":"open supervised sessions","meaning":"開設有監督的活動時段","examples":[{"en":"The school could open supervised lunchtime and after-school sessions.","zh":"學校可以開設午膳時間和課後的有監督活動時段。"},{"en":"To open supervised sessions means to provide activity times watched and guided by responsible adults or trained students.","zh":"開設有監督的活動時段，是指提供由負責任成人或受訓學生看管和指導的活動時間。"},{"en":"A school may open supervised sessions so students can use equipment safely.","zh":"學校可以開設有監督時段，讓學生安全使用設備。"},{"en":"Supervised sessions reduce risk because someone checks behaviour and technique.","zh":"有監督的時段能減少風險，因為有人檢查行為和技巧。"},{"en":"This phrase shows that the school plans safe and organised use.","zh":"這個短語顯示學校計劃安全而有組織地使用設備。"}],"source":"2014 Q2.pdf","sourcePage":5},{"front":"lunchtime sessions","meaning":"午膳時間活動","examples":[{"en":"Students could join lunchtime sessions in the fitness corner.","zh":"學生可以參加健身角的午膳時間活動。"},{"en":"Lunchtime sessions are organised activities held during the lunch break.","zh":"午膳時間活動是在午飯休息期間舉行的有組織活動。"},{"en":"A short lunchtime session may allow students to stretch, cycle, or practise basic strength exercises.","zh":"短暫的午膳時間活動可以讓學生拉筋、踩健身單車或練習基礎肌力。"},{"en":"Lunchtime sessions help students exercise even if they are busy after school.","zh":"午膳時間活動幫助課後繁忙的學生也能運動。"},{"en":"This phrase shows how facilities can fit into a normal school day.","zh":"這個短語顯示設施如何融入正常上學日。"}],"source":"2014 Q2.pdf","sourcePage":5},{"front":"after-school sessions","meaning":"課後活動","examples":[{"en":"After-school sessions would give students more chances to exercise.","zh":"課後活動會給學生更多運動機會。"},{"en":"After-school sessions are organised activities held after lessons end.","zh":"課後活動是在課堂結束後舉行的有組織活動。"},{"en":"Students may attend after-school sessions to train, relax, or learn correct exercise techniques.","zh":"學生可能參加課後活動來訓練、放鬆或學習正確運動技巧。"},{"en":"After-school sessions are useful because students have more time than during lunch.","zh":"課後活動有用，因為學生比午膳時間有更多時間。"},{"en":"This phrase describes a practical way to make facilities available.","zh":"這個短語描述讓設施可供使用的實際方法。"}],"source":"2014 Q2.pdf","sourcePage":5},{"front":"students preparing for examinations","meaning":"準備考試的學生","examples":[{"en":"Students preparing for examinations may benefit from stress-relief exercise.","zh":"準備考試的學生可能受惠於減壓運動。"},{"en":"Students preparing for examinations are students studying for important tests or public exams.","zh":"準備考試的學生是正在為重要測驗或公開試溫習的學生。"},{"en":"Such students may feel pressure from revision, grades, and family expectations.","zh":"這些學生可能因溫習、成績和家庭期望而感到壓力。"},{"en":"Short exercise sessions can help them rest their minds and return to study more calmly.","zh":"短暫運動時段可以幫助他們讓大腦休息，並更冷靜地回到學習。"},{"en":"This phrase shows that fitness can support academic well-being too.","zh":"這個短語顯示健身也可以支援學業上的身心健康。"}],"source":"2014 Q2.pdf","sourcePage":5},{"front":"recover from minor injuries","meaning":"從輕傷中康復","examples":[{"en":"Some students are recovering from minor injuries.","zh":"一些學生正在從輕傷中康復。"},{"en":"To recover from minor injuries means to heal from small physical harms such as sprains or strains.","zh":"從輕傷中康復，是指由扭傷或拉傷等小型身體傷害中復原。"},{"en":"A student recovering from a minor knee injury may need gentle cycling instead of running.","zh":"正從膝蓋輕傷中康復的學生，可能需要溫和踩單車，而不是跑步。"},{"en":"Safe equipment can help students recover gradually under teacher guidance.","zh":"安全設備可以在老師指導下幫助學生逐步康復。"},{"en":"This phrase shows that exercise can support careful healing, not only competition.","zh":"這個短語顯示運動不只支援比賽，也支援小心康復。"}],"source":"2014 Q2.pdf","sourcePage":5},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, proper equipment would make training safer.","zh":"更重要的是，合適設備會令訓練更安全。"},{"en":"More importantly introduces a point that matters even more than the previous one.","zh":"更重要的是，用來引出比前一點更重要的觀點。"},{"en":"A fitness corner is useful; more importantly, it must be safe for beginners.","zh":"健身角很有用；更重要的是，它必須對初學者安全。"},{"en":"Writers use this phrase to move from a benefit to a stronger reason.","zh":"作者使用這個短語，由一個好處轉到更有力的理由。"},{"en":"It signals that the next idea deserves special attention.","zh":"它表示下一個想法值得特別注意。"}],"source":"2014 Q2.pdf","sourcePage":6},{"front":"proper equipment","meaning":"合適設備","examples":[{"en":"Proper equipment would make training safer and more systematic.","zh":"合適設備會令訓練更安全和更有系統。"},{"en":"Proper equipment means suitable, safe, and appropriate tools for the activity.","zh":"合適設備是指適合、安全並符合活動需要的工具。"},{"en":"Students need proper equipment before learning strength training, or they may use unsafe methods.","zh":"學生在學習肌力訓練前需要合適設備，否則可能使用不安全方法。"},{"en":"Proper equipment helps teachers organise training with clear steps.","zh":"合適設備幫助老師以清晰步驟組織訓練。"},{"en":"This phrase shows that the quality and suitability of equipment matter.","zh":"這個短語顯示設備的質素和適合程度很重要。"}],"source":"2014 Q2.pdf","sourcePage":6},{"front":"safer and more systematic","meaning":"更安全和更有系統","examples":[{"en":"The donation would make training safer and more systematic.","zh":"這項捐贈會令訓練更安全和更有系統。"},{"en":"Safer and more systematic means less risky and more organised.","zh":"更安全和更有系統，是指風險較低，而且更有組織。"},{"en":"Training becomes safer and more systematic when students follow warm-up, exercise, and cool-down steps.","zh":"當學生跟隨熱身、運動和緩和步驟時，訓練會變得更安全和更有系統。"},{"en":"Proper equipment and teacher guidance help students avoid random or dangerous exercise.","zh":"合適設備和老師指導幫助學生避免隨意或危險運動。"},{"en":"This phrase connects safety with good planning.","zh":"這個短語把安全與良好規劃連接起來。"}],"source":"2014 Q2.pdf","sourcePage":6},{"front":"senior Sports Club members","meaning":"體育學會高年級成員","examples":[{"en":"Senior Sports Club members could teach juniors how to use the equipment.","zh":"體育學會高年級成員可以教導低年級學生如何使用設備。"},{"en":"Senior Sports Club members are older or more experienced students in the Sports Club.","zh":"體育學會高年級成員是體育學會中年紀較大或經驗較多的學生。"},{"en":"Senior members can model safe exercise habits for younger students.","zh":"高年級成員可以為年幼學生示範安全運動習慣。"},{"en":"Giving senior members responsibility helps them develop leadership.","zh":"給予高年級成員責任，有助他們培養領導能力。"},{"en":"This phrase shows peer support within the school community.","zh":"這個短語顯示學校社群中的同儕支援。"}],"source":"2014 Q2.pdf","sourcePage":6},{"front":"guided by Physical Education teachers","meaning":"由體育老師指導","examples":[{"en":"Senior members would be guided by Physical Education teachers.","zh":"高年級成員會由體育老師指導。"},{"en":"Guided by Physical Education teachers means supervised and advised by trained PE staff.","zh":"由體育老師指導，是指由受過訓練的體育教師監督和提供建議。"},{"en":"Students can lead warm-ups safely when guided by Physical Education teachers.","zh":"在體育老師指導下，學生可以安全帶領熱身。"},{"en":"Teacher guidance helps prevent wrong technique and careless use of equipment.","zh":"老師指導有助防止錯誤技巧和粗心使用設備。"},{"en":"This phrase shows that student leadership would still have adult support.","zh":"這個短語顯示學生領導仍會有成人支援。"}],"source":"2014 Q2.pdf","sourcePage":6},{"front":"Physical Education teachers","meaning":"體育老師","examples":[{"en":"Physical Education teachers would supervise the use of equipment.","zh":"體育老師會監督設備的使用。"},{"en":"Physical Education teachers are teachers who teach sport, exercise, fitness, and health-related skills.","zh":"體育老師是教授運動、鍛煉、體能和健康相關技能的教師。"},{"en":"PE teachers know how to organise safe warm-ups, training, and injury prevention.","zh":"體育老師知道如何組織安全熱身、訓練和預防受傷。"},{"en":"Their supervision can make donated equipment safer for student use.","zh":"他們的監督可以令捐贈設備更安全地供學生使用。"},{"en":"This phrase identifies the adults responsible for training safety.","zh":"這個短語指出負責訓練安全的成年人。"}],"source":"2014 Q2.pdf","sourcePage":6},{"front":"teach juniors how to","meaning":"教導低年級學生如何","examples":[{"en":"Senior members could teach juniors how to warm up properly.","zh":"高年級成員可以教導低年級學生如何正確熱身。"},{"en":"To teach juniors how to do something means to show younger students the correct method.","zh":"教導低年級學生如何做某事，是指向年幼學生展示正確方法。"},{"en":"Older students may teach juniors how to stretch, record progress, and use dumbbells safely.","zh":"高年級學生可能教導低年級學生如何拉筋、記錄進度和安全使用啞鈴。"},{"en":"Teaching juniors helps build a caring and responsible club culture.","zh":"教導低年級學生有助建立關懷和負責任的學會文化。"},{"en":"This phrase shows learning passed from experienced students to newer ones.","zh":"這個短語顯示由有經驗學生向新學生傳授學習。"}],"source":"2014 Q2.pdf","sourcePage":6},{"front":"warm up","meaning":"熱身","examples":[{"en":"Students should learn how to warm up before exercise.","zh":"學生應學會運動前如何熱身。"},{"en":"To warm up means to prepare the body for exercise with gentle movement.","zh":"熱身是指透過溫和活動讓身體為運動作準備。"},{"en":"Students may warm up by walking, stretching lightly, or moving their joints.","zh":"學生可以透過步行、輕度拉筋或活動關節來熱身。"},{"en":"Warming up can reduce injury risk and help muscles work better.","zh":"熱身可以減少受傷風險，並幫助肌肉更好運作。"},{"en":"This phrase describes an important first step in safe training.","zh":"這個短語描述安全訓練的重要第一步。"}],"source":"2014 Q2.pdf","sourcePage":6},{"front":"stretch","meaning":"拉筋","examples":[{"en":"Students should learn how to stretch safely.","zh":"學生應學會如何安全拉筋。"},{"en":"To stretch means to gently lengthen muscles or move joints to improve flexibility.","zh":"拉筋是指溫和伸展肌肉或活動關節，以改善柔軟度。"},{"en":"A runner may stretch calves and thighs after warming up.","zh":"跑步者熱身後可能拉伸小腿和大腿。"},{"en":"Stretching too hard can cause injury, so correct technique matters.","zh":"拉筋過度可能造成受傷，所以正確技巧很重要。"},{"en":"This phrase describes a simple but important part of exercise.","zh":"這個短語描述運動中簡單但重要的一部分。"}],"source":"2014 Q2.pdf","sourcePage":6},{"front":"record progress","meaning":"記錄進度","examples":[{"en":"Students could learn to record progress during training.","zh":"學生可以學習在訓練期間記錄進度。"},{"en":"To record progress means to write down improvements, results, or changes over time.","zh":"記錄進度是指寫下隨時間出現的改善、結果或變化。"},{"en":"A student may record progress by noting cycling time, repetitions, or stretching ability.","zh":"學生可以透過記下踩單車時間、次數或拉筋能力來記錄進度。"},{"en":"Recording progress helps students see improvement that may otherwise feel slow.","zh":"記錄進度幫助學生看見原本可能感覺緩慢的改善。"},{"en":"This habit builds discipline and motivation.","zh":"這個習慣建立紀律和動力。"}],"source":"2014 Q2.pdf","sourcePage":6},{"front":"use equipment responsibly","meaning":"負責任地使用設備","examples":[{"en":"Students should learn to use equipment responsibly.","zh":"學生應學會負責任地使用設備。"},{"en":"To use equipment responsibly means to handle it safely, carefully, and according to rules.","zh":"負責任地使用設備，是指安全、小心並按照規則處理設備。"},{"en":"Students use dumbbells responsibly when they choose suitable weights and return them after use.","zh":"學生選擇合適重量並在使用後放回啞鈴，就是負責任地使用。"},{"en":"Responsible use prevents injuries and keeps equipment available for others.","zh":"負責任使用可以防止受傷，並保持設備可供其他人使用。"},{"en":"This phrase shows that access must come with care.","zh":"這個短語顯示使用權必須伴隨關懷。"}],"source":"2014 Q2.pdf","sourcePage":7},{"front":"in this way","meaning":"這樣一來","examples":[{"en":"In this way, old machines would not sit forgotten in a storeroom.","zh":"這樣一來，舊機器就不會被遺忘在儲物室。"},{"en":"In this way means by using the method just described.","zh":"這樣一來，是指透過剛才描述的方法。"},{"en":"Students could label and record donated items; in this way, the equipment would be managed properly.","zh":"學生可以為捐贈物品貼標籤和記錄；這樣一來，設備就能被妥善管理。"},{"en":"This phrase connects a plan with its positive result.","zh":"這個短語把計劃與正面結果連接起來。"},{"en":"It helps explain how an action will solve a problem.","zh":"它幫助解釋行動如何解決問題。"}],"source":"2014 Q2.pdf","sourcePage":7},{"front":"sit forgotten in a storeroom","meaning":"被遺忘在儲物室","examples":[{"en":"Old machines would not sit forgotten in a storeroom.","zh":"舊機器不會被遺忘在儲物室。"},{"en":"To sit forgotten in a storeroom means to be left unused and ignored in a storage room.","zh":"被遺忘在儲物室，是指被放在儲物室中不使用和不理會。"},{"en":"Old sports mats may sit forgotten in a storeroom if no one plans how to use them.","zh":"如果沒有人規劃如何使用，舊運動墊可能被遺忘在儲物室。"},{"en":"Donation prevents useful equipment from being wasted in storage.","zh":"捐贈可以防止有用設備在儲存中被浪費。"},{"en":"This phrase creates an image of resources losing value because no one uses them.","zh":"這個短語營造出資源因沒有人使用而失去價值的畫面。"}],"source":"2014 Q2.pdf","sourcePage":7},{"front":"help students build discipline","meaning":"幫助學生建立紀律","examples":[{"en":"The equipment would help students build discipline.","zh":"這些設備會幫助學生建立紀律。"},{"en":"To help students build discipline means to support them in developing regular effort, self-control, and responsibility.","zh":"幫助學生建立紀律，是指支援他們培養持續努力、自制力和責任感。"},{"en":"A training log can help students build discipline by showing whether they practise regularly.","zh":"訓練記錄可以透過顯示學生是否定期練習，幫助他們建立紀律。"},{"en":"Exercise equipment builds discipline when students learn to train safely and consistently.","zh":"當學生學會安全而持續訓練時，運動設備就能建立紀律。"},{"en":"This phrase links fitness with character development.","zh":"這個短語把健身與品格發展連接起來。"}],"source":"2014 Q2.pdf","sourcePage":7},{"front":"healthier routines","meaning":"更健康的日常習慣","examples":[{"en":"Students could build confidence and healthier routines.","zh":"學生可以建立信心和更健康的日常習慣。"},{"en":"Healthier routines are regular habits that support better physical and mental well-being.","zh":"更健康的日常習慣是支援更好身心健康的定期習慣。"},{"en":"Exercising twice a week after school can become part of a healthier routine.","zh":"每星期放學後運動兩次，可以成為更健康日常習慣的一部分。"},{"en":"Healthier routines help students manage stress, sleep better, and feel stronger.","zh":"更健康的日常習慣幫助學生管理壓力、睡得更好和感覺更強壯。"},{"en":"This phrase shows that the goal is long-term habit, not one-time activity.","zh":"這個短語顯示目標是長遠習慣，而不是一次性活動。"}],"source":"2014 Q2.pdf","sourcePage":7},{"front":"enrich the wider school community","meaning":"豐富整個學校群體","examples":[{"en":"The donation would enrich the wider school community.","zh":"這項捐贈會豐富整個學校群體。"},{"en":"To enrich the wider school community means to make school life better for many groups, not only one club.","zh":"豐富整個學校群體，是指令許多群體的學校生活變得更好，而不只是某個學會。"},{"en":"Fitness equipment can enrich the school community by supporting PE lessons, clubs, and health programmes.","zh":"健身設備可以透過支援體育課、學會和健康計劃來豐富學校群體。"},{"en":"A useful donation enriches school life when students of different ages can benefit.","zh":"當不同年級學生都能受惠時，有用的捐贈就豐富了學校生活。"},{"en":"This phrase shows that the impact reaches beyond the Sports Club.","zh":"這個短語顯示影響超越體育學會。"}],"source":"2014 Q2.pdf","sourcePage":7},{"front":"look after oneself and one another","meaning":"照顧自己和彼此","examples":[{"en":"Sport teaches students to look after themselves and one another.","zh":"運動教導學生照顧自己和彼此。"},{"en":"To look after oneself and one another means to care for personal health while also supporting others.","zh":"照顧自己和彼此，是指關心個人健康，同時支援別人。"},{"en":"Students look after themselves by warming up and look after one another by reminding friends to exercise safely.","zh":"學生透過熱身照顧自己，也透過提醒朋友安全運動來照顧彼此。"},{"en":"Team activities teach care because one person’s safety can affect the whole group.","zh":"團隊活動教人關懷，因為一個人的安全會影響整個群體。"},{"en":"This phrase connects sport with responsibility and kindness.","zh":"這個短語把運動與責任和善意連接起來。"}],"source":"2014 Q2.pdf","sourcePage":7},{"front":"donated equipment","meaning":"捐贈設備","examples":[{"en":"Donated equipment could support many school programmes.","zh":"捐贈設備可以支援許多學校計劃。"},{"en":"Donated equipment is equipment given freely by a person or organisation to help others.","zh":"捐贈設備是個人或機構免費給予以幫助別人的設備。"},{"en":"Donated equipment may include bikes, mats, ropes, bands, and benches.","zh":"捐贈設備可能包括單車、墊、跳繩、阻力帶和健身椅。"},{"en":"If managed well, donated equipment can serve students for years.","zh":"如果管理得好，捐贈設備可以服務學生多年。"},{"en":"This phrase highlights the practical value of the gift.","zh":"這個短語突出禮物的實際價值。"}],"source":"2014 Q2.pdf","sourcePage":7},{"front":"organise a programme","meaning":"舉辦計劃","examples":[{"en":"We could organise a “Healthy Start” programme before school.","zh":"我們可以在上學前舉辦「健康起步」計劃。"},{"en":"To organise a programme means to plan and run a set of activities for a clear purpose.","zh":"舉辦計劃是指為清晰目的而規劃和推行一系列活動。"},{"en":"A Sports Club may organise a programme to teach safe stretching and basic strength training.","zh":"體育學會可能舉辦計劃，教導安全拉筋和基礎肌力訓練。"},{"en":"Organising a programme helps equipment be used regularly instead of randomly.","zh":"舉辦計劃有助設備被定期使用，而不是隨意使用。"},{"en":"This phrase shows planning, structure, and responsibility.","zh":"這個短語顯示規劃、結構和責任。"}],"source":"2014 Q2.pdf","sourcePage":7},{"front":"Healthy Start programme","meaning":"健康起步計劃","examples":[{"en":"A “Healthy Start” programme could encourage students to exercise before school.","zh":"「健康起步」計劃可以鼓勵學生在上學前運動。"},{"en":"A Healthy Start programme is a planned activity that helps students begin the day with movement and good habits.","zh":"健康起步計劃是幫助學生以活動和好習慣開始一天的有計劃活動。"},{"en":"Such a programme might include light cycling, stretching, and breathing exercises.","zh":"這樣的計劃可能包括輕鬆踩單車、拉筋和呼吸練習。"},{"en":"A Healthy Start programme can help students feel more awake and focused in class.","zh":"健康起步計劃可以幫助學生在課堂上更清醒和專注。"},{"en":"This phrase gives the fitness corner a positive and practical purpose.","zh":"這個短語給健身角正面而實際的用途。"}],"source":"2014 Q2.pdf","sourcePage":7},{"front":"stress-relief fitness session","meaning":"減壓健身活動","examples":[{"en":"The school could offer stress-relief fitness sessions during examinations.","zh":"學校可以在考試期間提供減壓健身活動。"},{"en":"A stress-relief fitness session is a short exercise activity designed to reduce pressure and tension.","zh":"減壓健身活動是為減少壓力和緊張而設的短暫運動活動。"},{"en":"Students may join a stress-relief session to stretch, breathe slowly, and move gently.","zh":"學生可能參加減壓活動來拉筋、慢慢呼吸和溫和活動。"},{"en":"Such sessions are useful during exams because students often sit and worry for long hours.","zh":"這類活動在考試期間有用，因為學生常長時間坐着和憂慮。"},{"en":"This phrase connects exercise with emotional well-being.","zh":"這個短語把運動與情緒健康連接起來。"}],"source":"2014 Q2.pdf","sourcePage":8},{"front":"during examinations","meaning":"考試期間","examples":[{"en":"Students may need stress relief during examinations.","zh":"學生在考試期間可能需要減壓。"},{"en":"During examinations means in the period when tests or exams are taking place.","zh":"考試期間是指測驗或考試正在進行的時期。"},{"en":"During examinations, students may sleep less and feel more pressure.","zh":"考試期間，學生可能睡得較少並感到更多壓力。"},{"en":"Short exercise sessions during examinations can help students manage stress.","zh":"考試期間的短暫運動時段可以幫助學生管理壓力。"},{"en":"This phrase identifies a time when support is especially needed.","zh":"這個短語指出特別需要支援的時間。"}],"source":"2014 Q2.pdf","sourcePage":8},{"front":"basic strength-training workshops","meaning":"基礎肌力訓練工作坊","examples":[{"en":"The equipment could support basic strength-training workshops.","zh":"這些設備可以支援基礎肌力訓練工作坊。"},{"en":"Basic strength-training workshops are short lessons that teach safe beginner exercises for building muscle strength.","zh":"基礎肌力訓練工作坊是教授初學者安全增強肌力動作的短課程。"},{"en":"A workshop may show students how to use resistance bands and light dumbbells correctly.","zh":"工作坊可能教學生如何正確使用阻力帶和輕量啞鈴。"},{"en":"These workshops can prevent injury by teaching technique before heavy training.","zh":"這些工作坊透過在重訓前教授技巧，可以防止受傷。"},{"en":"This phrase shows that donated equipment can support education, not just exercise.","zh":"這個短語顯示捐贈設備可以支援教育，而不只是運動。"}],"source":"2014 Q2.pdf","sourcePage":8},{"front":"take…, for example","meaning":"以……為例","examples":[{"en":"Take an exercise bike, for example.","zh":"以健身單車為例。"},{"en":"Take something for example means using one case to explain a wider point clearly.","zh":"以……為例，是指用一個例子清楚解釋更大的觀點。"},{"en":"Take a yoga mat, for example: it can support stretching, warm-ups, and rehabilitation.","zh":"以瑜伽墊為例：它可以支援拉筋、熱身和復康。"},{"en":"This phrase helps a writer move from general claims to a concrete example.","zh":"這個短語幫助作者由一般主張轉向具體例子。"},{"en":"Examples make a request more convincing because readers can imagine the use.","zh":"例子令請求更有說服力，因為讀者可以想像用途。"}],"source":"2014 Q2.pdf","sourcePage":8},{"front":"commercial gym","meaning":"商業健身室","examples":[{"en":"An older bike may seem modest in a commercial gym.","zh":"較舊的單車在商業健身室中可能顯得普通。"},{"en":"A commercial gym is a fitness business where customers pay to use exercise facilities.","zh":"商業健身室是顧客付費使用運動設施的健身企業。"},{"en":"A commercial gym may replace equipment often to attract paying members.","zh":"商業健身室可能經常更換設備，以吸引付費會員。"},{"en":"Equipment that looks ordinary in a commercial gym may still be valuable in a school.","zh":"在商業健身室看起來普通的設備，在學校仍可能很有價值。"},{"en":"This phrase contrasts a business setting with a student community setting.","zh":"這個短語對比商業環境與學生社群環境。"}],"source":"2014 Q2.pdf","sourcePage":8},{"front":"seem modest beside","meaning":"在……旁邊顯得普通","examples":[{"en":"An older bike may seem modest beside the latest model.","zh":"較舊的單車在最新型號旁邊可能顯得普通。"},{"en":"To seem modest beside something means to look simple or less impressive compared with something newer or better-looking.","zh":"在某物旁邊顯得普通，是指與更新或更吸引的東西比較時，看起來簡單或不太突出。"},{"en":"An old laptop may seem modest beside a new tablet, but it can still help students type essays.","zh":"舊手提電腦在新平板旁邊可能顯得普通，但仍可以幫助學生打文章。"},{"en":"Modest-looking equipment may still be safe, useful, and meaningful.","zh":"看起來普通的設備仍可能安全、有用和有意義。"},{"en":"This phrase reminds readers not to judge value only by appearance.","zh":"這個短語提醒讀者不要只用外觀判斷價值。"}],"source":"2014 Q2.pdf","sourcePage":8},{"front":"the latest model","meaning":"最新型號","examples":[{"en":"The latest model may make older equipment look less impressive.","zh":"最新型號可能令舊設備看起來沒那麼出色。"},{"en":"The latest model means the newest version of a product.","zh":"最新型號是指產品的最新版本。"},{"en":"A gym may buy the latest model of an exercise bike to attract customers.","zh":"健身室可能購買最新型號的健身單車來吸引顧客。"},{"en":"The latest model is not always necessary for students who only need safe basic training.","zh":"對只需要安全基礎訓練的學生來說，最新型號不一定必要。"},{"en":"This phrase helps compare newness with usefulness.","zh":"這個短語幫助比較新穎程度與實用性。"}],"source":"2014 Q2.pdf","sourcePage":8},{"front":"in our school, however","meaning":"然而，在我們學校","examples":[{"en":"In our school, however, an older bike could become very useful.","zh":"然而，在我們學校，較舊的單車可以變得非常有用。"},{"en":"In our school, however introduces a contrast between another place and the school’s situation.","zh":"然而，在我們學校，用來引出另一個地方與學校情況之間的對比。"},{"en":"In a commercial gym, an old mat may be unwanted; in our school, however, it could support warm-ups.","zh":"在商業健身室，舊墊可能沒有人要；然而，在我們學校，它可以支援熱身。"},{"en":"This phrase shows that value changes according to context.","zh":"這個短語顯示價值會隨語境改變。"},{"en":"It helps explain why the donation would matter to students.","zh":"它幫助解釋為何捐贈對學生重要。"}],"source":"2014 Q2.pdf","sourcePage":8},{"front":"a shy Form One student","meaning":"害羞的中一學生","examples":[{"en":"A shy Form One student might use the bike to begin exercising.","zh":"害羞的中一學生可能使用單車開始運動。"},{"en":"A shy Form One student is a quiet first-year secondary student who may feel nervous in public activities.","zh":"害羞的中一學生是安靜、在公開活動中可能感到緊張的中學一年級學生。"},{"en":"Such a student may prefer an exercise bike because it feels simple and private.","zh":"這樣的學生可能較喜歡健身單車，因為它感覺簡單和較私密。"},{"en":"A fitness corner can help shy students start moving without embarrassment.","zh":"健身角可以幫助害羞學生不用尷尬地開始活動身體。"},{"en":"This phrase makes the benefit personal and easy to imagine.","zh":"這個短語令好處變得個人化和容易想像。"}],"source":"2014 Q2.pdf","sourcePage":8},{"front":"not embarrassing but empowering","meaning":"不是尷尬，而是令人有力量","examples":[{"en":"Exercise can feel not embarrassing but empowering.","zh":"運動可以感覺不是尷尬，而是令人有力量。"},{"en":"Not embarrassing but empowering means something does not cause shame; instead, it gives confidence and strength.","zh":"不是尷尬，而是令人有力量，是指某事不會帶來羞愧，反而給人信心和力量。"},{"en":"A beginner-friendly fitness corner can make exercise feel not embarrassing but empowering.","zh":"適合初學者的健身角，可以令運動感覺不是尷尬，而是令人有力量。"},{"en":"When students feel safe, trying exercise becomes a source of confidence.","zh":"當學生感到安全時，嘗試運動會成為信心來源。"},{"en":"This phrase contrasts shame with personal growth.","zh":"這個短語對比羞愧與個人成長。"}],"source":"2014 Q2.pdf","sourcePage":8},{"front":"ordinary equipment","meaning":"普通設備","examples":[{"en":"Even ordinary equipment could support useful training.","zh":"即使普通設備也可以支援有用訓練。"},{"en":"Ordinary equipment means simple, common, or not especially expensive equipment.","zh":"普通設備是指簡單、常見或不特別昂貴的設備。"},{"en":"Skipping ropes and mats are ordinary equipment, but they can support warm-ups well.","zh":"跳繩和墊是普通設備，但它們可以很好地支援熱身。"},{"en":"Ordinary equipment becomes valuable when students use it safely and regularly.","zh":"當學生安全而定期使用時，普通設備會變得有價值。"},{"en":"This phrase reminds readers that usefulness does not always require luxury.","zh":"這個短語提醒讀者，有用不一定需要豪華。"}],"source":"2014 Q2.pdf","sourcePage":9},{"front":"skipping ropes","meaning":"跳繩","examples":[{"en":"Skipping ropes could support warm-ups and fitness training.","zh":"跳繩可以支援熱身和體能訓練。"},{"en":"Skipping ropes are ropes used for jumping exercises.","zh":"跳繩是用於跳躍運動的繩子。"},{"en":"Students can use skipping ropes to improve coordination, stamina, and rhythm.","zh":"學生可以用跳繩改善協調、耐力和節奏感。"},{"en":"Skipping ropes are cheap, easy to store, and useful for group warm-ups.","zh":"跳繩便宜、容易存放，並適合小組熱身。"},{"en":"This equipment supports active movement in a small space.","zh":"這種設備在細小空間中支援活躍活動。"}],"source":"2014 Q2.pdf","sourcePage":9},{"front":"medicine balls","meaning":"藥球","examples":[{"en":"Medicine balls can be used for strength and conditioning exercises.","zh":"藥球可用於力量和體能訓練。"},{"en":"Medicine balls are weighted balls used in fitness training.","zh":"藥球是健身訓練中使用的加重球。"},{"en":"Students may use medicine balls for core exercises, throwing drills, or partner activities.","zh":"學生可能用藥球進行核心訓練、拋擲練習或雙人活動。"},{"en":"Medicine balls help build strength when used with proper technique and supervision.","zh":"在正確技巧和監督下使用時，藥球能幫助建立力量。"},{"en":"This equipment can make training more varied and practical.","zh":"這種設備可以令訓練更多樣和實用。"}],"source":"2014 Q2.pdf","sourcePage":9},{"front":"support warm-ups","meaning":"支援熱身","examples":[{"en":"Ordinary equipment could support warm-ups for athletics.","zh":"普通設備可以支援田徑熱身。"},{"en":"To support warm-ups means to help prepare the body before stronger exercise begins.","zh":"支援熱身是指在較強運動開始前，幫助身體作準備。"},{"en":"Mats, ropes, and bands can support warm-ups by helping students move safely.","zh":"墊、跳繩和阻力帶可以透過幫助學生安全活動來支援熱身。"},{"en":"Good warm-up support reduces injury risk and improves readiness.","zh":"良好的熱身支援能減少受傷風險並提升準備程度。"},{"en":"This phrase shows how simple equipment can serve an important training purpose.","zh":"這個短語顯示簡單設備如何服務重要訓練目的。"}],"source":"2014 Q2.pdf","sourcePage":9},{"front":"athletics","meaning":"田徑","examples":[{"en":"Mats and skipping ropes could support warm-ups for athletics.","zh":"墊和跳繩可以支援田徑熱身。"},{"en":"Athletics refers to sports such as running, jumping, and throwing.","zh":"田徑是指跑步、跳躍和投擲等運動。"},{"en":"Students in athletics need warm-ups to prepare their legs, arms, and joints.","zh":"田徑學生需要熱身來準備腿部、手臂和關節。"},{"en":"Basic equipment can support athletics even without expensive machines.","zh":"即使沒有昂貴機器，基礎設備也可以支援田徑。"},{"en":"This word connects the donation with school sports training.","zh":"這個詞把捐贈與學校體育訓練連接起來。"}],"source":"2014 Q2.pdf","sourcePage":9},{"front":"conditioning for basketball players","meaning":"籃球員的體能訓練","examples":[{"en":"The equipment could support conditioning for basketball players.","zh":"這些設備可以支援籃球員的體能訓練。"},{"en":"Conditioning for basketball players means fitness training that improves strength, stamina, speed, and movement for basketball.","zh":"籃球員的體能訓練是改善籃球所需力量、耐力、速度和動作的健身訓練。"},{"en":"Basketball players may use resistance bands and medicine balls for conditioning.","zh":"籃球員可能使用阻力帶和藥球進行體能訓練。"},{"en":"Good conditioning helps players jump, defend, and move safely during games.","zh":"良好體能訓練幫助球員在比賽中跳躍、防守和安全移動。"},{"en":"This phrase shows how equipment supports sport-specific preparation.","zh":"這個短語顯示設備如何支援特定運動準備。"}],"source":"2014 Q2.pdf","sourcePage":9},{"front":"rehabilitation exercises","meaning":"復康運動","examples":[{"en":"Some equipment could support rehabilitation exercises.","zh":"一些設備可以支援復康運動。"},{"en":"Rehabilitation exercises are gentle exercises that help someone recover after injury or illness.","zh":"復康運動是幫助人在受傷或生病後康復的溫和運動。"},{"en":"A student with a minor ankle injury may do rehabilitation exercises before returning to running.","zh":"有輕微腳踝傷的學生可能在重新跑步前做復康運動。"},{"en":"Such exercises should be guided by teachers or professionals to avoid further injury.","zh":"這類運動應由老師或專業人士指導，以避免再次受傷。"},{"en":"This phrase shows that fitness equipment can support recovery as well as training.","zh":"這個短語顯示健身設備既可支援訓練，也可支援康復。"}],"source":"2014 Q2.pdf","sourcePage":9},{"front":"be advised to avoid","meaning":"被建議避免","examples":[{"en":"Some students are advised to avoid high-impact sports.","zh":"一些學生被建議避免高撞擊運動。"},{"en":"To be advised to avoid something means to be told by someone knowledgeable not to do it.","zh":"被建議避免某事，是指被有知識的人告知不要做某事。"},{"en":"A doctor may advise a student to avoid running while a knee injury heals.","zh":"醫生可能建議學生在膝蓋傷勢康復時避免跑步。"},{"en":"Students advised to avoid high-impact sports may still need safe low-impact exercise.","zh":"被建議避免高撞擊運動的學生，仍可能需要安全低撞擊運動。"},{"en":"This phrase shows a recommendation made for safety or health reasons.","zh":"這個短語顯示基於安全或健康理由作出的建議。"}],"source":"2014 Q2.pdf","sourcePage":9},{"front":"high-impact sports","meaning":"高撞擊運動","examples":[{"en":"Students with minor injuries may need to avoid high-impact sports.","zh":"有輕傷的學生可能需要避免高撞擊運動。"},{"en":"High-impact sports are activities that place strong pressure on joints through jumping, running, or sudden movement.","zh":"高撞擊運動是透過跳躍、跑步或突然動作對關節造成較大壓力的活動。"},{"en":"Basketball and sprinting can be high-impact sports because they involve quick stops and jumps.","zh":"籃球和短跑可以是高撞擊運動，因為它們涉及急停和跳躍。"},{"en":"Students recovering from injury may choose cycling or stretching instead of high-impact sports.","zh":"正在康復的學生可能選擇踩單車或拉筋，而不是高撞擊運動。"},{"en":"This phrase helps explain why gentler fitness equipment is useful.","zh":"這個短語幫助解釋為何較溫和的健身設備有用。"}],"source":"2014 Q2.pdf","sourcePage":9},{"front":"the more…, the more likely…","meaning":"越……，就越有可能……","examples":[{"en":"The more chances students have to move safely, the more likely they are to exercise regularly.","zh":"學生越有機會安全活動身體，就越有可能定期運動。"},{"en":"The more A, the more likely B means when A increases, B becomes more probable.","zh":"「越A，就越有可能B」意思是A增加時，B發生的可能性也增加。"},{"en":"The more support beginners receive, the more likely they are to keep exercising.","zh":"初學者得到的支援越多，就越有可能持續運動。"},{"en":"This structure shows a clear cause-and-effect relationship.","zh":"這個句式顯示清晰的因果關係。"},{"en":"It is useful for explaining how better access can change habits.","zh":"它適合解釋更好的使用機會如何改變習慣。"}],"source":"2014 Q2.pdf","sourcePage":9},{"front":"move safely","meaning":"安全地活動身體","examples":[{"en":"Students need more chances to move safely.","zh":"學生需要更多安全地活動身體的機會。"},{"en":"To move safely means to exercise or use the body without unnecessary risk of injury.","zh":"安全地活動身體，是指在沒有不必要受傷風險的情況下運動或使用身體。"},{"en":"Students move safely when they warm up, use correct technique, and follow instructions.","zh":"當學生熱身、使用正確技巧和跟隨指示時，就是安全地活動身體。"},{"en":"Safe movement is especially important for beginners and students recovering from injury.","zh":"對初學者和正在康復的學生來說，安全活動尤其重要。"},{"en":"This phrase connects physical activity with protection and care.","zh":"這個短語把身體活動與保護和關懷連接起來。"}],"source":"2014 Q2.pdf","sourcePage":10},{"front":"see exercise as a habit rather than a punishment","meaning":"把運動視為習慣，而不是懲罰","examples":[{"en":"Students should see exercise as a habit rather than a punishment.","zh":"學生應把運動視為習慣，而不是懲罰。"},{"en":"To see exercise as a habit rather than a punishment means to view it as a normal healthy routine, not something unpleasant.","zh":"把運動視為習慣，而不是懲罰，是指把它看作正常健康日常，而不是令人不快的事。"},{"en":"Short friendly sessions can help students see exercise as a habit rather than a punishment.","zh":"短而友善的活動時段可以幫助學生把運動視為習慣，而不是懲罰。"},{"en":"When exercise feels safe and manageable, students are more likely to continue.","zh":"當運動感覺安全和可處理時，學生更可能持續下去。"},{"en":"This phrase changes the emotional meaning of fitness.","zh":"這個短語改變健身的情感意義。"}],"source":"2014 Q2.pdf","sourcePage":10},{"front":"benefit meaningfully from","meaning":"從……中有實質得益","examples":[{"en":"Your fitness centre would benefit meaningfully from this donation.","zh":"貴健身中心會從這項捐贈中有實質得益。"},{"en":"To benefit meaningfully from something means to gain real and important value from it.","zh":"從某事中有實質得益，是指從中得到真實而重要的價值。"},{"en":"A business can benefit meaningfully from community service when local families trust it more.","zh":"當本地家庭更信任企業時，企業可以從社區服務中有實質得益。"},{"en":"The centre would gain reputation, goodwill, and stronger community ties from the donation.","zh":"貴中心會從捐贈中得到聲譽、善意和更強社區連繫。"},{"en":"This phrase shows that giving can also bring real benefits to the giver.","zh":"這個短語顯示給予也能為給予者帶來實際好處。"}],"source":"2014 Q2.pdf","sourcePage":10},{"front":"act of generosity","meaning":"慷慨之舉","examples":[{"en":"The donation would be an act of generosity.","zh":"這項捐贈會是一個慷慨之舉。"},{"en":"An act of generosity is a kind action in which someone gives time, money, or resources to help others.","zh":"慷慨之舉是某人給予時間、金錢或資源來幫助別人的善意行動。"},{"en":"Donating usable equipment to a school is an act of generosity because it supports students without profit.","zh":"向學校捐贈可用設備是一個慷慨之舉，因為它不為盈利地支援學生。"},{"en":"Such an act can inspire others to share resources too.","zh":"這樣的行動可以啟發其他人也分享資源。"},{"en":"This phrase gives moral value to the donation.","zh":"這個短語賦予捐贈道德價值。"}],"source":"2014 Q2.pdf","sourcePage":10},{"front":"strengthen your reputation","meaning":"提升貴中心聲譽","examples":[{"en":"The donation would strengthen your reputation as a responsible local business.","zh":"這項捐贈會提升貴中心作為負責任本地企業的聲譽。"},{"en":"To strengthen your reputation means to make people respect or trust you more.","zh":"提升聲譽是指令人們更尊重或信任你。"},{"en":"A company strengthens its reputation when it helps schools and community groups sincerely.","zh":"公司真誠幫助學校和社區組織時，會提升自己的聲譽。"},{"en":"Public donations can strengthen reputation because people see values in action.","zh":"公開捐贈可以提升聲譽，因為人們看見價值被付諸行動。"},{"en":"This phrase connects social responsibility with public trust.","zh":"這個短語把社會責任與公眾信任連接起來。"}],"source":"2014 Q2.pdf","sourcePage":10},{"front":"responsible local business","meaning":"負責任的本地企業","examples":[{"en":"Your centre would be seen as a responsible local business.","zh":"貴中心會被視為負責任的本地企業。"},{"en":"A responsible local business is a company that cares about the community where it operates.","zh":"負責任的本地企業是關心自己營運所在地區社群的公司。"},{"en":"A responsible local business supports local students, reduces waste, and treats neighbours fairly.","zh":"負責任的本地企業會支援本地學生、減少浪費和公平對待鄰里。"},{"en":"People trust local businesses more when they contribute to community well-being.","zh":"當本地企業為社區福祉作出貢獻時，人們會更信任它們。"},{"en":"This phrase presents the donor as part of the neighbourhood, not only the market.","zh":"這個短語把捐贈者呈現為社區一分子，而不只是市場一員。"}],"source":"2014 Q2.pdf","sourcePage":10},{"front":"acknowledge your donation","meaning":"鳴謝貴方捐贈","examples":[{"en":"We would acknowledge your donation on our school noticeboard.","zh":"我們會在學校告示板上鳴謝貴方捐贈。"},{"en":"To acknowledge your donation means to publicly thank or recognise the support given.","zh":"鳴謝貴方捐贈，是指公開感謝或承認所得到的支援。"},{"en":"A school may acknowledge a donation by naming the donor in a newsletter.","zh":"學校可能透過在通訊中列出捐贈者姓名來鳴謝捐贈。"},{"en":"Acknowledgement shows gratitude and lets others know who helped the community.","zh":"鳴謝表示感激，也讓其他人知道誰幫助了社區。"},{"en":"This phrase assures the donor that their contribution will be recognised.","zh":"這個短語向捐贈者保證其貢獻會被認可。"}],"source":"2014 Q2.pdf","sourcePage":10},{"front":"school noticeboard","meaning":"學校告示板","examples":[{"en":"The donation could be acknowledged on our school noticeboard.","zh":"這項捐贈可以在我們的學校告示板上被鳴謝。"},{"en":"A school noticeboard is a board where announcements, notices, and information are displayed.","zh":"學校告示板是展示公告、通告和資訊的板。"},{"en":"Students may check the school noticeboard for club activities and competition results.","zh":"學生可能查看學校告示板，了解學會活動和比賽結果。"},{"en":"Thanking a donor on the noticeboard lets the whole school see the contribution.","zh":"在告示板上感謝捐贈者，可以讓全校看見這份貢獻。"},{"en":"This phrase describes a simple public way to share information.","zh":"這個短語描述分享資訊的簡單公開方式。"}],"source":"2014 Q2.pdf","sourcePage":10},{"front":"newsletter","meaning":"通訊","examples":[{"en":"We would acknowledge the donation in our newsletter.","zh":"我們會在通訊中鳴謝這項捐贈。"},{"en":"A newsletter is a regular written update sent to members, parents, students, or the community.","zh":"通訊是定期發給成員、家長、學生或社區的書面更新。"},{"en":"A school newsletter may include news about events, achievements, and donations.","zh":"學校通訊可能包括活動、成就和捐贈消息。"},{"en":"Mentioning the donation in a newsletter helps parents and students understand its value.","zh":"在通訊中提及捐贈，有助家長和學生理解其價值。"},{"en":"This phrase shows another formal way to recognise support.","zh":"這個短語顯示另一種正式認可支援的方式。"}],"source":"2014 Q2.pdf","sourcePage":10},{"front":"annual Sports Day","meaning":"每年一度的陸運會","examples":[{"en":"The donation could be acknowledged at our annual Sports Day.","zh":"這項捐贈可以在我們每年一度的陸運會上被鳴謝。"},{"en":"An annual Sports Day is a school sports event held once every year.","zh":"每年一度的陸運會是學校每年舉行一次的體育活動。"},{"en":"Students may take part in races, relays, and team events on annual Sports Day.","zh":"學生可能在陸運會中參加賽跑、接力和團體項目。"},{"en":"Thanking a donor at Sports Day connects the donation with student fitness and school spirit.","zh":"在陸運會感謝捐贈者，能把捐贈與學生健身和學校精神連接起來。"},{"en":"This phrase names a suitable public occasion for appreciation.","zh":"這個短語指出一個適合公開致謝的場合。"}],"source":"2014 Q2.pdf","sourcePage":10},{"front":"with your permission","meaning":"如蒙允許","examples":[{"en":"With your permission, we would place a thank-you sign near the fitness corner.","zh":"如蒙允許，我們會在健身角附近放置感謝牌。"},{"en":"With your permission means only if you agree or allow it.","zh":"如蒙允許，是指只有在你同意或批准的情況下。"},{"en":"With your permission, the school may mention your company’s name in the newsletter.","zh":"如蒙允許，學校可以在通訊中提及貴公司名稱。"},{"en":"This phrase sounds respectful because it does not assume agreement.","zh":"這個短語聽起來尊重，因為它沒有假設對方同意。"},{"en":"It is useful when asking to do something involving the other person’s name or image.","zh":"當請求做涉及對方名稱或形象的事情時，這個短語很有用。"}],"source":"2014 Q2.pdf","sourcePage":11},{"front":"thank-you sign","meaning":"感謝牌","examples":[{"en":"A small thank-you sign could be placed near the fitness corner.","zh":"一塊小感謝牌可以放在健身角附近。"},{"en":"A thank-you sign is a notice that publicly expresses gratitude to someone.","zh":"感謝牌是公開向某人表達感激的告示。"},{"en":"A school may place a thank-you sign beside donated books or equipment.","zh":"學校可能在捐贈書本或設備旁放置感謝牌。"},{"en":"A thank-you sign recognises the donor while reminding students to value the gift.","zh":"感謝牌既認可捐贈者，也提醒學生珍惜禮物。"},{"en":"This phrase describes a visible and respectful form of appreciation.","zh":"這個短語描述一種可見而尊重的感謝方式。"}],"source":"2014 Q2.pdf","sourcePage":11},{"front":"near the fitness corner","meaning":"在健身角附近","examples":[{"en":"The thank-you sign would be placed near the fitness corner.","zh":"感謝牌會放在健身角附近。"},{"en":"Near the fitness corner means close to the area where students exercise.","zh":"在健身角附近，是指靠近學生運動的區域。"},{"en":"A notice near the fitness corner can remind students of safety rules.","zh":"健身角附近的告示可以提醒學生安全規則。"},{"en":"Placing the sign nearby connects the donor directly with the benefit students receive.","zh":"把牌放在附近，能把捐贈者直接與學生得到的好處連接起來。"},{"en":"This phrase gives a clear location for recognition.","zh":"這個短語給出清晰的致謝位置。"}],"source":"2014 Q2.pdf","sourcePage":11},{"front":"not only a fitness brand, but a neighbour","meaning":"不只是一個健身品牌，而是一位鄰里","examples":[{"en":"People would see not only a fitness brand, but a neighbour who cares.","zh":"人們會看見貴中心不只是一個健身品牌，而是一位關心社區的鄰里。"},{"en":"Not only a fitness brand, but a neighbour means the centre would be seen as more than a business; it would be seen as part of the community.","zh":"不只是一個健身品牌，而是一位鄰里，是指中心不只被視為企業，也被視為社區一分子。"},{"en":"A shop becomes a caring neighbour when it supports local students and families.","zh":"當商店支援本地學生和家庭時，它就成為關心人的鄰里。"},{"en":"This phrase helps the donor imagine a warmer public image.","zh":"這個短語幫助捐贈者想像更溫暖的公眾形象。"},{"en":"It connects business identity with human care.","zh":"它把商業身份與人情關懷連接起來。"}],"source":"2014 Q2.pdf","sourcePage":11},{"front":"be willing to invest in","meaning":"願意投放資源於","examples":[{"en":"Your centre would be seen as willing to invest in young people.","zh":"貴中心會被視為願意投放資源於年輕人。"},{"en":"To be willing to invest in someone means to spend time, money, or resources to support their future.","zh":"願意投放資源於某人，是指花時間、金錢或資源支援他們的未來。"},{"en":"A company invests in young people when it offers training, scholarships, or useful equipment.","zh":"公司提供培訓、獎學金或有用設備時，就是投放資源於年輕人。"},{"en":"Investing in students can strengthen the community for years.","zh":"投放資源於學生可以多年來強化社區。"},{"en":"This phrase presents donation as a long-term social contribution.","zh":"這個短語把捐贈呈現為長遠社會貢獻。"}],"source":"2014 Q2.pdf","sourcePage":11},{"front":"well-being","meaning":"身心健康","examples":[{"en":"The donation would support the well-being of the next generation.","zh":"這項捐贈會支援下一代的身心健康。"},{"en":"Well-being means a person’s physical, mental, and emotional health and quality of life.","zh":"身心健康是指一個人的身體、心理和情緒健康，以及生活質素。"},{"en":"Exercise supports well-being by improving fitness, sleep, mood, and confidence.","zh":"運動透過改善體能、睡眠、心情和信心來支援身心健康。"},{"en":"Schools care about well-being when they provide safe spaces for students to move and rest.","zh":"學校提供安全空間讓學生活動和休息時，就是關心身心健康。"},{"en":"This word is broader than health because it includes how people feel and live.","zh":"這個詞比健康更廣，因為它包括人的感受和生活方式。"}],"source":"2014 Q2.pdf","sourcePage":11},{"front":"the next generation","meaning":"下一代","examples":[{"en":"The fitness corner would benefit the next generation.","zh":"健身角會惠及下一代。"},{"en":"The next generation means young people who will become the adults of the future.","zh":"下一代是指將來會成為成年人的年輕人。"},{"en":"Schools invest in the next generation by supporting students’ learning, health, and character.","zh":"學校透過支援學生的學習、健康和品格來投放資源於下一代。"},{"en":"Helping the next generation creates benefits that may last for many years.","zh":"幫助下一代可以創造持續多年的好處。"},{"en":"This phrase gives the donation a future-looking meaning.","zh":"這個短語賦予捐贈面向未來的意義。"}],"source":"2014 Q2.pdf","sourcePage":11},{"front":"reduce unnecessary waste","meaning":"減少不必要的浪費","examples":[{"en":"The donation would reduce unnecessary waste.","zh":"這項捐贈會減少不必要的浪費。"},{"en":"To reduce unnecessary waste means to avoid throwing away things that can still be used.","zh":"減少不必要的浪費，是指避免丟棄仍可使用的東西。"},{"en":"Donating old desks reduces waste if another school can use them safely.","zh":"如果另一所學校能安全使用舊書桌，捐贈它們就能減少浪費。"},{"en":"Reducing waste helps the environment and saves resources.","zh":"減少浪費有助環境並節省資源。"},{"en":"This phrase explains the environmental benefit of reuse.","zh":"這個短語解釋重用的環保好處。"}],"source":"2014 Q2.pdf","sourcePage":11},{"front":"send usable equipment away","meaning":"把可用設備送走","examples":[{"en":"Donation is better than sending usable equipment away.","zh":"捐贈比把可用設備送走更好。"},{"en":"To send usable equipment away means to remove equipment that still works, often for storage, disposal, or transport elsewhere.","zh":"把可用設備送走，是指移走仍可運作的設備，通常送去儲存、棄置或其他地方。"},{"en":"A gym may send usable equipment away during renovation if it has no further need for it.","zh":"健身室在翻新期間如果不再需要設備，可能會把可用設備送走。"},{"en":"Donating it keeps value in the community instead of treating it as rubbish.","zh":"捐贈可以把價值留在社區，而不是把它當成垃圾。"},{"en":"This phrase contrasts wasteful removal with meaningful reuse.","zh":"這個短語對比浪費式移走與有意義重用。"}],"source":"2014 Q2.pdf","sourcePage":11},{"front":"during renovation","meaning":"在翻新期間","examples":[{"en":"The equipment could be donated during renovation.","zh":"設備可以在翻新期間被捐贈。"},{"en":"During renovation means while a place is being repaired, improved, or redesigned.","zh":"在翻新期間，是指一個地方正在維修、改善或重新設計的時候。"},{"en":"During renovation, a fitness centre may remove old machines to make room for new ones.","zh":"在翻新期間，健身中心可能移走舊機器以騰出空間給新機器。"},{"en":"Donation during renovation can make the upgrade more sustainable.","zh":"翻新期間進行捐贈可以令升級更可持續。"},{"en":"This phrase identifies the practical timing for the request.","zh":"這個短語指出請求的實際時間。"}],"source":"2014 Q2.pdf","sourcePage":11},{"front":"improvement does not have to come at the cost of sustainability","meaning":"改善不必以犧牲可持續性為代價","examples":[{"en":"The centre could show that improvement does not have to come at the cost of sustainability.","zh":"貴中心可以顯示改善不必以犧牲可持續性為代價。"},{"en":"This means a place can upgrade itself without creating unnecessary waste or environmental harm.","zh":"這意思是一個地方可以升級自己，而不製造不必要浪費或環境傷害。"},{"en":"A school can buy new computers while donating old usable ones, showing improvement does not require waste.","zh":"學校購買新電腦時捐贈可用舊電腦，就能顯示改善不必造成浪費。"},{"en":"Renovation is more responsible when useful items are reused instead of discarded.","zh":"當有用物品被重用而不是丟棄時，翻新會更負責任。"},{"en":"This phrase balances progress with environmental care.","zh":"這個短語平衡進步與環保關懷。"}],"source":"2014 Q2.pdf","sourcePage":12},{"front":"come at the cost of","meaning":"以……為代價","examples":[{"en":"Progress should not come at the cost of sustainability.","zh":"進步不應以可持續性為代價。"},{"en":"To come at the cost of something means to achieve one thing by harming or losing another.","zh":"以某事為代價，是指透過傷害或失去另一樣東西來達成某事。"},{"en":"Better facilities should not come at the cost of creating piles of waste.","zh":"更好的設施不應以製造大量廢物為代價。"},{"en":"A decision is wiser when improvement does not come at the cost of community value.","zh":"當改善不以社區價值為代價時，決定會更明智。"},{"en":"This phrase shows a trade-off that should be avoided.","zh":"這個短語顯示應避免的取捨。"}],"source":"2014 Q2.pdf","sourcePage":12},{"front":"sustainability","meaning":"可持續發展","examples":[{"en":"Donation can show a commitment to sustainability.","zh":"捐贈可以顯示對可持續發展的承諾。"},{"en":"Sustainability means using resources in a way that protects the environment and future needs.","zh":"可持續發展是指以保護環境和未來需要的方式使用資源。"},{"en":"Reusing equipment supports sustainability because fewer usable items are thrown away.","zh":"重用設備支援可持續發展，因為較少可用物品被丟棄。"},{"en":"Schools teach sustainability when students see old resources being used responsibly.","zh":"當學生看見舊資源被負責任地使用時，學校就在教導可持續發展。"},{"en":"This word connects today’s choices with tomorrow’s environment.","zh":"這個詞把今天的選擇與明天的環境連接起來。"}],"source":"2014 Q2.pdf","sourcePage":12},{"front":"surplus","meaning":"多餘物資","examples":[{"en":"One person’s surplus can become another community’s resource.","zh":"一個人的多餘物資可以成為另一個社群的資源。"},{"en":"Surplus means extra things that are no longer needed by one person or organisation.","zh":"多餘物資是指某人或某機構不再需要的額外東西。"},{"en":"A gym’s surplus mats may become useful equipment for a school club.","zh":"健身室多出的墊可能成為學校學會的有用設備。"},{"en":"Surplus should not be wasted if it is safe and someone else can use it.","zh":"如果多餘物資安全且別人可以使用，就不應被浪費。"},{"en":"This word helps explain why donation makes sense.","zh":"這個詞幫助解釋為何捐贈合理。"}],"source":"2014 Q2.pdf","sourcePage":12},{"front":"another community’s resource","meaning":"另一個社群的資源","examples":[{"en":"Your surplus could become another community’s resource.","zh":"貴中心的多餘物資可以成為另一個社群的資源。"},{"en":"Another community’s resource means something no longer needed by one group becomes useful to another group.","zh":"另一個社群的資源，是指一個群體不再需要的東西，變成另一個群體有用的東西。"},{"en":"Old sports equipment from a gym can become a school community’s resource.","zh":"健身室的舊運動設備可以成為學校社群的資源。"},{"en":"This idea turns waste into shared value.","zh":"這個想法把浪費轉化成共享價值。"},{"en":"The phrase shows how donation connects different parts of a neighbourhood.","zh":"這個短語顯示捐贈如何連接社區不同部分。"}],"source":"2014 Q2.pdf","sourcePage":12},{"front":"choose donation over disposal","meaning":"選擇捐贈而不是棄置","examples":[{"en":"Your centre could choose donation over disposal.","zh":"貴中心可以選擇捐贈而不是棄置。"},{"en":"To choose donation over disposal means to give usable items away instead of throwing them out.","zh":"選擇捐贈而不是棄置，是指把可用物品送給別人，而不是丟掉。"},{"en":"A company chooses donation over disposal when it sends old chairs to a community centre.","zh":"公司把舊椅子送到社區中心時，就是選擇捐贈而不是棄置。"},{"en":"Choosing donation over disposal reduces waste and helps people directly.","zh":"選擇捐贈而不是棄置可以減少浪費並直接幫助別人。"},{"en":"This phrase presents donation as the better moral and practical choice.","zh":"這個短語把捐贈呈現為更好的道德和實際選擇。"}],"source":"2014 Q2.pdf","sourcePage":12},{"front":"disposal","meaning":"棄置","examples":[{"en":"Donation is more meaningful than disposal.","zh":"捐贈比棄置更有意義。"},{"en":"Disposal means getting rid of something, often by throwing it away.","zh":"棄置是指處理掉某物，通常是丟棄。"},{"en":"Disposal may be necessary for broken equipment, but usable items should be considered for donation.","zh":"壞掉設備可能需要棄置，但可用物品應考慮捐贈。"},{"en":"Choosing disposal too quickly can waste resources that others need.","zh":"太快選擇棄置可能浪費別人需要的資源。"},{"en":"This word contrasts with reuse, repair, and donation.","zh":"這個詞與重用、修理和捐贈形成對比。"}],"source":"2014 Q2.pdf","sourcePage":12},{"front":"turn…into…","meaning":"把……變成……","examples":[{"en":"The centre could turn a renovation decision into an example of responsibility.","zh":"貴中心可以把一個翻新決定變成負責任的例子。"},{"en":"To turn A into B means to change one thing into another thing with a new meaning or result.","zh":"把A變成B，是指把一件事轉化成帶有新意義或結果的另一件事。"},{"en":"A school can turn old uniforms into emergency clothing for students in need.","zh":"學校可以把舊校服變成供有需要學生使用的應急衣物。"},{"en":"Donation turns a normal upgrade into a community contribution.","zh":"捐贈把普通升級變成社區貢獻。"},{"en":"This phrase shows transformation from a practical action to a meaningful one.","zh":"這個短語顯示由實際行動到有意義行動的轉化。"}],"source":"2014 Q2.pdf","sourcePage":12},{"front":"a practical renovation decision","meaning":"實際的翻新決定","examples":[{"en":"Donation would turn a practical renovation decision into something meaningful.","zh":"捐贈會把實際的翻新決定變成有意義的事情。"},{"en":"A practical renovation decision is a useful choice made during repair or improvement work.","zh":"實際的翻新決定是在維修或改善工程中作出的實用選擇。"},{"en":"Replacing old machines is a practical renovation decision when a gym updates its facilities.","zh":"當健身室更新設施時，更換舊機器是一個實際的翻新決定。"},{"en":"The decision becomes more meaningful if old usable machines help students.","zh":"如果可用舊機器能幫助學生，這個決定就變得更有意義。"},{"en":"This phrase shows how ordinary management choices can carry social value.","zh":"這個短語顯示普通管理選擇也可以帶有社會價值。"}],"source":"2014 Q2.pdf","sourcePage":12},{"front":"a public example of social responsibility","meaning":"履行社會責任的公開例子","examples":[{"en":"The donation would become a public example of social responsibility.","zh":"這項捐贈會成為履行社會責任的公開例子。"},{"en":"A public example of social responsibility is a visible action that shows care for society.","zh":"履行社會責任的公開例子，是顯示關心社會的可見行動。"},{"en":"A company becomes a public example of social responsibility when it helps schools and reduces waste.","zh":"公司幫助學校和減少浪費時，就成為履行社會責任的公開例子。"},{"en":"Such examples can encourage other businesses to support the community too.","zh":"這類例子可以鼓勵其他企業也支援社區。"},{"en":"This phrase presents the donation as something others can learn from.","zh":"這個短語把捐贈呈現為其他人可以學習的行動。"}],"source":"2014 Q2.pdf","sourcePage":12},{"front":"for safety reasons","meaning":"基於安全理由","examples":[{"en":"For safety reasons, we would only accept suitable equipment.","zh":"基於安全理由，我們只會接受合適設備。"},{"en":"For safety reasons means because safety must be protected.","zh":"基於安全理由，是指因為安全必須受到保護。"},{"en":"For safety reasons, students should not use damaged machines.","zh":"基於安全理由，學生不應使用損壞的機器。"},{"en":"This phrase explains why the school cannot accept every donated item.","zh":"這個短語解釋為何學校不能接受每一件捐贈物品。"},{"en":"It shows that care and responsibility are part of the request.","zh":"它顯示關懷和責任是請求的一部分。"}],"source":"2014 Q2.pdf","sourcePage":13},{"front":"only accept equipment that","meaning":"只接受……的設備","examples":[{"en":"We would only accept equipment that is safe for continued use.","zh":"我們只會接受適合繼續安全使用的設備。"},{"en":"Only accept equipment that means take only items meeting a specific condition.","zh":"只接受符合某條件的設備，是指只收取達到特定條件的物品。"},{"en":"A school should only accept equipment that has no serious damage and can be supervised safely.","zh":"學校應只接受沒有嚴重損壞並可安全監督使用的設備。"},{"en":"This phrase sets a clear limit for the donation.","zh":"這個短語為捐贈設定清晰限制。"},{"en":"It reassures the donor that the school will act responsibly.","zh":"它讓捐贈者放心，知道學校會負責任行事。"}],"source":"2014 Q2.pdf","sourcePage":13},{"front":"suitable for continued use","meaning":"適合繼續使用","examples":[{"en":"Your staff can decide which equipment is suitable for continued use.","zh":"貴中心職員可以決定哪些設備適合繼續使用。"},{"en":"Suitable for continued use means safe and proper enough to keep using.","zh":"適合繼續使用，是指安全和合適到可以繼續使用。"},{"en":"A mat with no tears may be suitable for continued use, but a broken machine may not be.","zh":"沒有破損的墊可能適合繼續使用，但壞掉的機器可能不適合。"},{"en":"Checking suitability protects students before equipment enters the school.","zh":"檢查是否適合使用，能在設備進入學校前保護學生。"},{"en":"This phrase focuses on safety after donation, not just usefulness.","zh":"這個短語著重捐贈後的安全，而不只是有用。"}],"source":"2014 Q2.pdf","sourcePage":13},{"front":"be prepared to","meaning":"準備好","examples":[{"en":"Our school is prepared to arrange collection.","zh":"我們學校準備好安排收取。"},{"en":"Be prepared to means be ready and willing to do something.","zh":"準備好做某事，是指已經有意願和能力去做。"},{"en":"The Sports Club is prepared to help move small items under teacher supervision.","zh":"體育學會準備好在老師監督下協助搬運小型物品。"},{"en":"Being prepared to arrange practical details makes the request easier for the donor.","zh":"準備好安排實際細節，可以令捐贈者更容易答應請求。"},{"en":"This phrase shows readiness and responsibility.","zh":"這個短語顯示準備程度和責任感。"}],"source":"2014 Q2.pdf","sourcePage":13},{"front":"arrange collection","meaning":"安排收取","examples":[{"en":"Our school is prepared to arrange collection at a convenient time.","zh":"我們學校準備好在方便的時間安排收取。"},{"en":"To arrange collection means to organise when and how items will be picked up.","zh":"安排收取是指組織何時和如何取走物品。"},{"en":"A school may arrange collection by sending staff or a van to collect donated equipment.","zh":"學校可能派職員或車輛收取捐贈設備。"},{"en":"Arranging collection reduces trouble for the donor.","zh":"安排收取可以減少捐贈者的麻煩。"},{"en":"This phrase shows that the writer has thought about practical logistics.","zh":"這個短語顯示作者已考慮實際物流安排。"}],"source":"2014 Q2.pdf","sourcePage":13},{"front":"at a time convenient to you","meaning":"在你方便的時間","examples":[{"en":"We can collect the equipment at a time convenient to you.","zh":"我們可以在你方便的時間收取設備。"},{"en":"At a time convenient to you means at a time that suits your schedule.","zh":"在你方便的時間，是指在配合你日程的時間。"},{"en":"A student may ask to visit a company at a time convenient to the manager.","zh":"學生可能請求在經理方便的時間到公司拜訪。"},{"en":"This phrase shows respect for the other person’s time.","zh":"這個短語顯示尊重對方的時間。"},{"en":"It makes the request sound flexible and considerate.","zh":"它令請求聽起來有彈性和體貼。"}],"source":"2014 Q2.pdf","sourcePage":13},{"front":"inspect and supervise","meaning":"檢查並監督","examples":[{"en":"Teachers will inspect and supervise the equipment carefully.","zh":"老師會仔細檢查並監督設備。"},{"en":"To inspect and supervise means to check something carefully and watch how it is used.","zh":"檢查並監督是指仔細查看某物，並觀察它如何被使用。"},{"en":"PE teachers can inspect equipment for damage and supervise students during training.","zh":"體育老師可以檢查設備是否損壞，並在訓練時監督學生。"},{"en":"Inspection and supervision reduce accidents and misuse.","zh":"檢查和監督可以減少意外和錯誤使用。"},{"en":"This phrase reassures the donor that safety will be managed.","zh":"這個短語讓捐贈者放心，知道安全會被管理。"}],"source":"2014 Q2.pdf","sourcePage":13},{"front":"before students use it","meaning":"在學生使用之前","examples":[{"en":"Teachers will inspect the equipment before students use it.","zh":"老師會在學生使用之前檢查設備。"},{"en":"Before students use it means before the equipment is made available for student activity.","zh":"在學生使用之前，是指在設備開放給學生作活動之前。"},{"en":"A school should check donated dumbbells before students use them in training.","zh":"學校應在學生訓練使用前檢查捐贈啞鈴。"},{"en":"This step helps prevent accidents caused by damaged or unsuitable equipment.","zh":"這個步驟有助防止由損壞或不合適設備造成的意外。"},{"en":"The phrase shows a clear safety procedure.","zh":"這個短語顯示清晰安全程序。"}],"source":"2014 Q2.pdf","sourcePage":13},{"front":"if you wish","meaning":"如你願意","examples":[{"en":"If you wish, we would be delighted to visit your centre.","zh":"如你願意，我們很樂意親身到訪貴中心。"},{"en":"If you wish means if you would like this to happen.","zh":"如你願意，是指如果你希望這樣做。"},{"en":"If you wish, we can send a teacher to discuss the donation details.","zh":"如你願意，我們可以派老師商討捐贈細節。"},{"en":"This phrase gives the receiver a polite choice.","zh":"這個短語給收信人一個禮貌選擇。"},{"en":"It helps the request sound respectful rather than forceful.","zh":"它幫助請求聽起來尊重，而不是強迫。"}],"source":"2014 Q2.pdf","sourcePage":13},{"front":"be delighted to","meaning":"很樂意","examples":[{"en":"We would be delighted to visit your centre in person.","zh":"我們很樂意親身到訪貴中心。"},{"en":"Be delighted to means be very pleased and willing to do something.","zh":"很樂意是指非常高興並願意做某事。"},{"en":"We would be delighted to explain how students would use the donated equipment.","zh":"我們很樂意解釋學生會如何使用捐贈設備。"},{"en":"This phrase sounds warm, polite, and enthusiastic in a formal letter.","zh":"這個短語在正式信件中聽起來親切、有禮和積極。"},{"en":"It shows appreciation for the chance to discuss the request.","zh":"它顯示對商討請求機會的感激。"}],"source":"2014 Q2.pdf","sourcePage":13},{"front":"in person","meaning":"親身","examples":[{"en":"We would be delighted to visit your centre in person.","zh":"我們很樂意親身到訪貴中心。"},{"en":"In person means physically present, not by phone, email, or video call.","zh":"親身是指實際到場，而不是透過電話、電郵或視像通話。"},{"en":"A teacher may visit a company in person to inspect donated equipment.","zh":"老師可能親身到公司檢查捐贈設備。"},{"en":"Meeting in person can make discussion clearer and more trustworthy.","zh":"親身見面可以令討論更清楚和更可信。"},{"en":"This phrase shows willingness to make a real effort.","zh":"這個短語顯示願意付出實際努力。"}],"source":"2014 Q2.pdf","sourcePage":14},{"front":"discuss which items may be available","meaning":"商討哪些物品可供捐贈","examples":[{"en":"We can discuss which items may be available for donation.","zh":"我們可以商討哪些物品可供捐贈。"},{"en":"To discuss which items may be available means to talk about what things could possibly be donated.","zh":"商討哪些物品可供捐贈，是指談論哪些東西可能可以捐出。"},{"en":"The school and fitness centre can discuss whether bikes, mats, or bands are available.","zh":"學校和健身中心可以商討單車、墊或阻力帶是否可供捐贈。"},{"en":"This discussion helps both sides avoid misunderstanding about the donation.","zh":"這項討論幫助雙方避免對捐贈產生誤解。"},{"en":"The phrase shows that the writer is open to the donor’s actual situation.","zh":"這個短語顯示作者願意配合捐贈者的實際情況。"}],"source":"2014 Q2.pdf","sourcePage":14},{"front":"thank you for considering","meaning":"感謝你考慮","examples":[{"en":"Thank you for considering our request.","zh":"感謝你考慮我們的請求。"},{"en":"Thank you for considering means the writer appreciates the receiver’s time and thought.","zh":"感謝你考慮，是指作者感激收信人花時間和心思。"},{"en":"A formal letter may end with “Thank you for considering our proposal.”","zh":"正式信件可以以「感謝你考慮我們的建議」作結。"},{"en":"This phrase is polite even before the receiver has made a decision.","zh":"即使收信人尚未作決定，這個短語仍然有禮。"},{"en":"It helps close a request respectfully.","zh":"它幫助請求信以尊重方式結束。"}],"source":"2014 Q2.pdf","sourcePage":14},{"front":"sincerely hope","meaning":"衷心希望","examples":[{"en":"I sincerely hope your renovation will be a great success.","zh":"我衷心希望貴中心的翻新會非常成功。"},{"en":"Sincerely hope means genuinely wish that something good will happen.","zh":"衷心希望是指真誠希望好事發生。"},{"en":"A student may sincerely hope a community partner’s project goes smoothly.","zh":"學生可能衷心希望社區合作夥伴的計劃順利。"},{"en":"This phrase sounds warm because it shows goodwill toward the receiver.","zh":"這個短語聽起來溫暖，因為它向收信人表示善意。"},{"en":"It is useful near the end of a polite formal letter.","zh":"它適合用於禮貌正式信件的結尾部分。"}],"source":"2014 Q2.pdf","sourcePage":14},{"front":"a great success","meaning":"非常成功；圓滿成功","examples":[{"en":"I hope your renovation will be a great success.","zh":"我希望貴中心的翻新會非常成功。"},{"en":"A great success means a result that goes very well and achieves its goals.","zh":"非常成功是指結果十分理想並達到目標。"},{"en":"A school fair is a great success if many families join and enough money is raised.","zh":"如果許多家庭參與並籌得足夠款項，學校嘉年華就是非常成功。"},{"en":"A renovation is a great success when the space becomes safer, brighter, and more useful.","zh":"當翻新後空間變得更安全、更明亮和更有用時，翻新就是圓滿成功。"},{"en":"This phrase expresses a positive wish for the receiver.","zh":"這個短語向收信人表達正面祝願。"}],"source":"2014 Q2.pdf","sourcePage":14},{"front":"let us know whether","meaning":"告知我們是否","examples":[{"en":"Please let us know whether a donation is possible.","zh":"請告知我們是否可以捐贈。"},{"en":"Let us know whether means tell us if something can or cannot happen.","zh":"告知我們是否，是指告訴我們某事能否發生。"},{"en":"Please let us know whether your centre has any safe equipment available.","zh":"請告知我們貴中心是否有任何安全設備可供捐贈。"},{"en":"This phrase politely asks for a clear reply.","zh":"這個短語禮貌地請求清楚回覆。"},{"en":"It helps the writer move from request to practical follow-up.","zh":"它幫助作者由請求轉向實際跟進。"}],"source":"2014 Q2.pdf","sourcePage":14},{"front":"donation is possible","meaning":"可以捐贈","examples":[{"en":"We would be grateful to know whether a donation is possible.","zh":"如能知道是否可以捐贈，我們將不勝感激。"},{"en":"Donation is possible means the donor may be able to give items or support.","zh":"可以捐贈是指捐贈者可能能夠提供物品或支援。"},{"en":"A donation is possible if the equipment is safe and no longer needed by the centre.","zh":"如果設備安全且中心不再需要，就可能可以捐贈。"},{"en":"Knowing whether donation is possible helps the school plan collection and use.","zh":"知道是否可以捐贈，有助學校規劃收取和使用。"},{"en":"This phrase focuses on whether the request can realistically happen.","zh":"這個短語著重請求是否能實際發生。"}],"source":"2014 Q2.pdf","sourcePage":14},{"front":"be proud to","meaning":"很榮幸能夠","examples":[{"en":"We would be proud to build a lasting partnership with your centre.","zh":"我們很榮幸能夠與貴中心建立長久合作關係。"},{"en":"Be proud to means feel honoured and pleased to do something meaningful.","zh":"很榮幸能夠是指對做一件有意義的事感到光榮和高興。"},{"en":"A school would be proud to work with a business that supports students.","zh":"學校很榮幸能與支援學生的企業合作。"},{"en":"This phrase shows respect for the potential partner.","zh":"這個短語顯示對潛在合作夥伴的尊重。"},{"en":"It makes the proposed cooperation sound valuable and dignified.","zh":"它令建議中的合作聽起來有價值和有尊嚴。"}],"source":"2014 Q2.pdf","sourcePage":14},{"front":"build a lasting partnership","meaning":"建立長久合作關係","examples":[{"en":"We hope to build a lasting partnership with your centre.","zh":"我們希望與貴中心建立長久合作關係。"},{"en":"To build a lasting partnership means to create a cooperative relationship that continues over time.","zh":"建立長久合作關係，是指創造一段能隨時間持續的合作關係。"},{"en":"A school and a local gym can build a lasting partnership through donations, workshops, and student activities.","zh":"學校和本地健身室可以透過捐贈、工作坊和學生活動建立長久合作關係。"},{"en":"Lasting partnerships are stronger than one-time help because they create ongoing support.","zh":"長久合作關係比一次性幫助更有力，因為它創造持續支援。"},{"en":"This phrase looks beyond the immediate request to future cooperation.","zh":"這個短語看得比眼前請求更遠，指向未來合作。"}],"source":"2014 Q2.pdf","sourcePage":14},{"front":"help students stand taller","meaning":"幫助學生更有自信","examples":[{"en":"The partnership could help students stand taller.","zh":"這段合作可以幫助學生更有自信。"},{"en":"To help students stand taller means to help them feel more confident, proud, and capable.","zh":"幫助學生更有自信，是指幫助他們感到更有信心、更自豪和更有能力。"},{"en":"Exercise can help students stand taller when they become stronger and less afraid to try.","zh":"當學生變得更強壯並更不害怕嘗試時，運動可以幫助他們更有自信。"},{"en":"Support from the community can make students feel valued and encouraged.","zh":"來自社區的支援可以令學生感到被重視和受鼓勵。"},{"en":"This phrase uses posture as an image for confidence.","zh":"這個短語用站姿作為信心的意象。"}],"source":"2014 Q2.pdf","sourcePage":14},{"front":"train more wisely","meaning":"更明智地訓練","examples":[{"en":"The fitness corner would help students train more wisely.","zh":"健身角會幫助學生更明智地訓練。"},{"en":"To train more wisely means to exercise with better knowledge, planning, and safety.","zh":"更明智地訓練，是指以更好的知識、計劃和安全意識做運動。"},{"en":"Students train more wisely when they warm up, choose suitable equipment, and record progress.","zh":"當學生熱身、選擇合適設備和記錄進度時，就是更明智地訓練。"},{"en":"Wise training reduces injury and helps improvement happen steadily.","zh":"明智訓練能減少受傷，並幫助進步穩定發生。"},{"en":"This phrase shows that the goal is not harder exercise only, but smarter exercise.","zh":"這個短語顯示目標不只是更辛苦運動，而是更聰明地運動。"}],"source":"2014 Q2.pdf","sourcePage":15},{"front":"live healthier lives","meaning":"過更健康的生活","examples":[{"en":"The donation would help students live healthier lives.","zh":"這項捐贈會幫助學生過更健康的生活。"},{"en":"To live healthier lives means to have daily habits that support better physical and mental health.","zh":"過更健康的生活，是指擁有支援更好身心健康的日常習慣。"},{"en":"Students live healthier lives when they exercise regularly, rest properly, and manage stress.","zh":"當學生定期運動、好好休息和管理壓力時，就是在過更健康的生活。"},{"en":"A school fitness corner can support healthier lives by making exercise easier to access.","zh":"學校健身角透過令運動更容易接觸，可以支援更健康的生活。"},{"en":"This phrase describes the long-term human benefit of the donation.","zh":"這個短語描述捐贈的長遠人本好處。"}],"source":"2014 Q2.pdf","sourcePage":15},{"front":"Yours faithfully","meaning":"此致敬禮","examples":[{"en":"A formal request letter can end with “Yours faithfully”.","zh":"正式請求信可以以「此致敬禮」結尾。"},{"en":"Yours faithfully is a formal closing used when the writer does not know the recipient personally.","zh":"「此致敬禮」是作者不熟悉收信人時使用的正式結語。"},{"en":"A student may end a letter to a manager with Yours faithfully.","zh":"學生可能以「此致敬禮」結束寫給經理的信。"},{"en":"This closing shows respect and completes the formal letter structure.","zh":"這個結語表示尊重，並完成正式信件結構。"},{"en":"It is more suitable for official requests than casual endings.","zh":"它比隨意結尾更適合正式請求。"}],"source":"2014 Q2.pdf","sourcePage":15},{"front":"Chairperson","meaning":"主席","examples":[{"en":"Chris Wong writes as Chairperson of the Sports Club.","zh":"Chris Wong 以體育學會主席身份寫信。"},{"en":"A chairperson is the person who leads a committee, club, or meeting.","zh":"主席是領導委員會、學會或會議的人。"},{"en":"The chairperson of a school club may write letters, organise meetings, and represent members.","zh":"學校學會主席可能寫信、組織會議和代表成員。"},{"en":"Signing as chairperson shows that the letter comes from an official club role.","zh":"以主席身份署名，顯示這封信來自正式學會角色。"},{"en":"This word identifies the writer’s responsibility and authority.","zh":"這個詞指出作者的責任和權限。"}],"source":"2014 Q2.pdf","sourcePage":15},{"front":"Evergreen Secondary School","meaning":"長青中學","examples":[{"en":"The request is made by the Sports Club of Evergreen Secondary School.","zh":"這項請求由長青中學體育學會提出。"},{"en":"Evergreen Secondary School is the name of the school making the request.","zh":"長青中學是提出請求的學校名稱。"},{"en":"Naming Evergreen Secondary School helps the manager know which student community would receive the donation.","zh":"說明長青中學，有助經理知道哪個學生社群會收到捐贈。"},{"en":"A clear school name makes a formal request more trustworthy and specific.","zh":"清晰的學校名稱令正式請求更可信和具體。"},{"en":"This phrase identifies the organisation that would use the donated equipment.","zh":"這個短語指出會使用捐贈設備的機構。"}],"source":"2014 Q2.pdf","sourcePage":15}],"dse/writing/part-b/2014/Q3":[{"front":"restore the good name of","meaning":"挽回……的良好名聲","examples":[{"en":"The Drama Club must restore its good name after the complaint.","zh":"戲劇學會必須在投訴後挽回良好名聲。"},{"en":"To restore the good name of a group means to rebuild its positive reputation after damage.","zh":"To restore the good name of a group 指在名聲受損後重建其正面聲譽。"},{"en":"The club can restore its good name by apologising and improving its behaviour.","zh":"學會可以透過道歉和改善行為來挽回良好名聲。"},{"en":"When people lose trust in an organisation, honest action is needed to restore its good name.","zh":"當人們對一個組織失去信任，便需要誠實行動來挽回其良好名聲。"},{"en":"This phrase is useful when reputation has been harmed and must be repaired.","zh":"當聲譽受損並需要修復時，這個短語很有用。"}],"source":"2014 Q3.pdf","sourcePage":1},{"front":"good name","meaning":"良好名聲","examples":[{"en":"The club has to protect its good name.","zh":"學會必須保護自己的良好名聲。"},{"en":"A good name means a positive reputation that people respect and trust.","zh":"Good name 指受人尊重和信任的正面聲譽。"},{"en":"A school club builds a good name through responsible behaviour and hard work.","zh":"學校學會透過負責任的行為和努力建立良好名聲。"},{"en":"One careless incident can damage a good name that took years to build.","zh":"一次粗心事件可以破壞多年建立的良好名聲。"},{"en":"This phrase connects reputation with trust.","zh":"這個短語把聲譽和信任連接起來。"}],"source":"2014 Q3.pdf","sourcePage":1},{"front":"Drama Club members","meaning":"戲劇學會會員","examples":[{"en":"The chairperson wrote to all Drama Club members.","zh":"主席寫信給所有戲劇學會會員。"},{"en":"Drama Club members are students who belong to the school’s drama group.","zh":"Drama Club members 指屬於學校戲劇小組的學生。"},{"en":"Drama Club members may act, direct, manage props or watch performances together.","zh":"戲劇學會會員可能參與演戲、導演、管理道具或一起觀看演出。"},{"en":"Members represent the club when they attend public events in school uniform.","zh":"會員穿着校服出席公開活動時，就是代表學會。"},{"en":"This phrase identifies the people who share responsibility for the club.","zh":"這個短語指出共同承擔學會責任的人。"}],"source":"2014 Q3.pdf","sourcePage":1},{"front":"formal complaint","meaning":"正式投訴","examples":[{"en":"The school has received a formal complaint from City Hall.","zh":"學校收到來自大會堂的正式投訴。"},{"en":"A formal complaint is an official written or spoken report about a problem.","zh":"Formal complaint 指關於問題的正式書面或口頭報告。"},{"en":"A theatre may send a formal complaint if audience members disturb a performance.","zh":"如果觀眾騷擾演出，劇院可能會發出正式投訴。"},{"en":"A formal complaint is serious because it becomes part of an official record.","zh":"正式投訴很嚴重，因為它會成為官方紀錄的一部分。"},{"en":"This phrase is common in school, workplace and public-service contexts.","zh":"這個短語常見於學校、工作場所和公共服務語境。"}],"source":"2014 Q3.pdf","sourcePage":1},{"front":"concerning our conduct","meaning":"關於我們的行為","examples":[{"en":"The complaint from City Hall concerned the club’s conduct.","zh":"大會堂的投訴是關於學會的行為。"},{"en":"Concerning our conduct means about the way we behaved.","zh":"Concerning our conduct 指關於我們的表現或舉止。"},{"en":"A teacher may write to students concerning their conduct during a school trip.","zh":"老師可能就學生在學校旅行中的行為寫信給他們。"},{"en":"If a complaint concerns conduct, the issue is behaviour rather than ability.","zh":"如果投訴關於行為，問題就在於舉止，而不是能力。"},{"en":"This phrase sounds formal and is suitable for official communication.","zh":"這個短語語氣正式，適合官方溝通。"}],"source":"2014 Q3.pdf","sourcePage":1},{"front":"conduct","meaning":"行為；舉止","examples":[{"en":"The complaint concerned the members’ conduct at the performance.","zh":"投訴關於會員在演出中的行為。"},{"en":"Conduct means the way a person behaves, especially in public or formal situations.","zh":"Conduct 指一個人的行為方式，特別是在公開或正式場合中的舉止。"},{"en":"Students’ conduct during a concert should be quiet and respectful.","zh":"學生在音樂會中的行為應安靜而有禮。"},{"en":"Poor conduct can damage a group’s reputation even if only a few people are involved.","zh":"即使只有少數人涉事，不當行為也可以損害整個團體的聲譽。"},{"en":"This word is useful when discussing behaviour and responsibility.","zh":"討論行為和責任時，這個詞很有用。"}],"source":"2014 Q3.pdf","sourcePage":1},{"front":"I regret to inform you that","meaning":"很遺憾通知你","examples":[{"en":"I regret to inform you that our school has received a formal complaint.","zh":"很遺憾通知你，本校收到一宗正式投訴。"},{"en":"I regret to inform you that means I am sorry to tell you bad or serious news.","zh":"I regret to inform you that 指我很抱歉要告訴你壞消息或嚴肅消息。"},{"en":"I regret to inform you that the trip has been cancelled because of safety concerns.","zh":"很遺憾通知你，由於安全考慮，旅行已取消。"},{"en":"This phrase is used when the writer must give unpleasant information politely.","zh":"當作者必須有禮地提供不愉快資訊時，會使用這個短語。"},{"en":"It sounds formal and serious.","zh":"它語氣正式而嚴肅。"}],"source":"2014 Q3.pdf","sourcePage":1},{"front":"receive a formal complaint","meaning":"收到正式投訴","examples":[{"en":"Our school has received a formal complaint from City Hall.","zh":"本校收到來自大會堂的正式投訴。"},{"en":"Receive a formal complaint means be officially told that someone is unhappy about a problem.","zh":"Receive a formal complaint 指正式得知有人對某個問題不滿。"},{"en":"A school may receive a formal complaint if students behave badly at a public venue.","zh":"如果學生在公共場地表現不當，學校可能會收到正式投訴。"},{"en":"Receiving a formal complaint usually requires a careful response.","zh":"收到正式投訴通常需要謹慎回應。"},{"en":"This phrase shows that the issue has become official.","zh":"這個短語顯示事件已變成正式問題。"}],"source":"2014 Q3.pdf","sourcePage":1},{"front":"City Hall","meaning":"大會堂","examples":[{"en":"The complaint came from City Hall.","zh":"投訴來自大會堂。"},{"en":"City Hall is a public venue where concerts, plays and official events may be held.","zh":"City Hall 指可舉行音樂會、戲劇和正式活動的公共場地。"},{"en":"Students should behave respectfully when they attend performances at City Hall.","zh":"學生在大會堂觀看演出時應有禮。"},{"en":"A complaint from City Hall matters because it affects the school’s public image.","zh":"來自大會堂的投訴很重要，因為它影響學校的公眾形象。"},{"en":"This phrase gives the incident a formal public setting.","zh":"這個短語為事件提供正式公共場景。"}],"source":"2014 Q3.pdf","sourcePage":1},{"front":"behaviour of a group of","meaning":"一群……的行為","examples":[{"en":"The complaint was about the behaviour of a group of Drama Club members.","zh":"投訴是關於一群戲劇學會會員的行為。"},{"en":"Behaviour of a group of people means how several people acted together.","zh":"Behaviour of a group of people 指幾個人一起表現出來的行為。"},{"en":"The behaviour of a group of students can affect how others judge the whole school.","zh":"一群學生的行為可以影響別人如何評價整間學校。"},{"en":"If one group is noisy, people nearby may remember the entire club negatively.","zh":"如果一群人很吵，附近的人可能會對整個學會留下負面印象。"},{"en":"This phrase focuses on shared public behaviour.","zh":"這個短語集中於共同的公共行為。"}],"source":"2014 Q3.pdf","sourcePage":1},{"front":"attend the drama performance","meaning":"觀看戲劇演出","examples":[{"en":"Several members attended the drama performance last week.","zh":"幾位會員上星期觀看了戲劇演出。"},{"en":"Attend the drama performance means go to watch a play or stage show.","zh":"Attend the drama performance 指去觀看戲劇或舞台演出。"},{"en":"Students attend drama performances to learn how actors use voice, movement and silence.","zh":"學生觀看戲劇演出，是為了學習演員如何運用聲音、動作和沉默。"},{"en":"When members attend a performance, they should behave as respectful audience members.","zh":"當會員觀看演出時，他們應以尊重的觀眾身份行事。"},{"en":"This phrase describes a theatre-related school activity.","zh":"這個短語描述與劇場有關的學校活動。"}],"source":"2014 Q3.pdf","sourcePage":2},{"front":"drama performance","meaning":"戲劇演出","examples":[{"en":"The members attended a drama performance at City Hall.","zh":"會員在大會堂觀看了一場戲劇演出。"},{"en":"A drama performance is a live stage show in which actors tell a story through acting.","zh":"Drama performance 指演員透過表演講述故事的現場舞台演出。"},{"en":"A drama performance requires concentration from both actors and audience members.","zh":"戲劇演出需要演員和觀眾都保持專注。"},{"en":"Talking during a drama performance can spoil the experience for others.","zh":"在戲劇演出期間說話會破壞別人的體驗。"},{"en":"This phrase is useful when discussing theatre events.","zh":"討論劇場活動時，這個短語很有用。"}],"source":"2014 Q3.pdf","sourcePage":2},{"front":"as the chairperson of","meaning":"作為……的主席","examples":[{"en":"As the chairperson of the Drama Club, Chris wrote to the members.","zh":"作為戲劇學會主席，Chris 寫信給會員。"},{"en":"As the chairperson of means in the role of the leader of a group.","zh":"As the chairperson of 指以某個團體領袖的身份。"},{"en":"As the chairperson of the student union, she had to explain the decision clearly.","zh":"作為學生會主席，她必須清楚解釋決定。"},{"en":"This phrase shows why the speaker has responsibility to address the issue.","zh":"這個短語顯示說話者為何有責任處理事件。"},{"en":"It is useful in formal letters from club leaders.","zh":"它適合用於學會領袖的正式信件。"}],"source":"2014 Q3.pdf","sourcePage":2},{"front":"not to embarrass anyone, but to","meaning":"不是為了令任何人難堪，而是為了","examples":[{"en":"The email was written not to embarrass anyone, but to address the matter honestly.","zh":"這封電郵不是為了令任何人難堪，而是為了坦誠處理事件。"},{"en":"Not to embarrass anyone, but to means the purpose is not to shame people, but to do something constructive.","zh":"Not to embarrass anyone, but to 指目的不是羞辱別人，而是做有建設性的事。"},{"en":"The teacher spoke to the class not to embarrass anyone, but to improve behaviour.","zh":"老師與全班談話，不是為了令任何人難堪，而是為了改善行為。"},{"en":"This phrase helps make criticism sound fair and responsible.","zh":"這個短語令批評聽起來公平而負責任。"},{"en":"It clearly separates a harmful intention from a helpful one.","zh":"它清楚分開有害意圖和有幫助的目的。"}],"source":"2014 Q3.pdf","sourcePage":2},{"front":"embarrass anyone","meaning":"令任何人難堪","examples":[{"en":"The chairperson did not want to embarrass anyone.","zh":"主席不想令任何人難堪。"},{"en":"Embarrass anyone means make someone feel ashamed, awkward or publicly uncomfortable.","zh":"Embarrass anyone 指令某人感到羞愧、尷尬或在公開場合不自在。"},{"en":"A leader should correct mistakes without trying to embarrass anyone.","zh":"領袖應糾正錯誤，而不是試圖令任何人難堪。"},{"en":"Public blame may embarrass people but not help them learn.","zh":"公開責備可能令人氣難堪，卻未必幫助他們學習。"},{"en":"This phrase is useful when discussing respectful correction.","zh":"討論有尊重的糾正時，這個短語很有用。"}],"source":"2014 Q3.pdf","sourcePage":2},{"front":"address the matter honestly","meaning":"坦誠處理事件","examples":[{"en":"The club needs to address the matter honestly.","zh":"學會需要坦誠處理事件。"},{"en":"Address the matter honestly means deal with the problem openly and truthfully.","zh":"Address the matter honestly 指公開而真實地處理問題。"},{"en":"The committee should address the matter honestly instead of hiding the complaint.","zh":"委員會應坦誠處理事件，而不是隱瞞投訴。"},{"en":"Honest discussion helps members understand what went wrong and how to improve.","zh":"坦誠討論幫助會員明白出了甚麼問題，以及如何改善。"},{"en":"This phrase shows responsibility after a problem.","zh":"這個短語顯示問題發生後的責任感。"}],"source":"2014 Q3.pdf","sourcePage":2},{"front":"remind all of us of","meaning":"提醒我們所有人","examples":[{"en":"The email reminds all of us of our responsibilities.","zh":"這封電郵提醒我們所有人的責任。"},{"en":"Remind all of us of means help everyone remember something important.","zh":"Remind all of us of 指幫助所有人記起重要事情。"},{"en":"A safety notice reminds all of us of the rules before a trip.","zh":"安全通知在旅行前提醒我們所有人遵守規則。"},{"en":"The complaint reminds all members of the importance of audience manners.","zh":"投訴提醒所有會員觀眾禮儀的重要性。"},{"en":"This phrase connects an incident with a lesson.","zh":"這個短語把事件和教訓連接起來。"}],"source":"2014 Q3.pdf","sourcePage":2},{"front":"responsibilities as audience members","meaning":"作為觀眾的責任","examples":[{"en":"Drama Club members have responsibilities as audience members.","zh":"戲劇學會會員有作為觀眾的責任。"},{"en":"Responsibilities as audience members are duties to watch quietly, respect performers and follow venue rules.","zh":"Responsibilities as audience members 指安靜觀看、尊重演員和遵守場地規則的責任。"},{"en":"Audience members should turn off phones and avoid talking during scenes.","zh":"觀眾應關掉電話，並避免在場景進行時說話。"},{"en":"Good audience behaviour protects the theatre experience for everyone.","zh":"良好的觀眾行為保護所有人的劇場體驗。"},{"en":"This phrase shows that watching a performance also requires discipline.","zh":"這個短語顯示觀看演出也需要紀律。"}],"source":"2014 Q3.pdf","sourcePage":2},{"front":"make clear","meaning":"清楚說明","examples":[{"en":"The chairperson made clear what the club must do next.","zh":"主席清楚說明學會接下來必須做甚麼。"},{"en":"Make clear means explain something so that people understand it without confusion.","zh":"Make clear 指把某事解釋清楚，令人沒有困惑。"},{"en":"The teacher made clear that phones must be turned off during the play.","zh":"老師清楚說明看戲期間必須關掉電話。"},{"en":"Clear instructions reduce mistakes because everyone knows what is expected.","zh":"清楚指示能減少錯誤，因為每個人都知道期望。"},{"en":"This phrase is useful in leadership and formal communication.","zh":"這個短語適合用於領導和正式溝通。"}],"source":"2014 Q3.pdf","sourcePage":2},{"front":"rebuild the trust","meaning":"重建已受損的信任","examples":[{"en":"The club must rebuild the trust that has been damaged.","zh":"學會必須重建已受損的信任。"},{"en":"Rebuild the trust means make people believe in the group again after disappointment.","zh":"Rebuild the trust 指在人們失望後，重新讓他們相信這個團體。"},{"en":"The club can rebuild the trust by apologising and behaving better at future events.","zh":"學會可以透過道歉和在日後活動中表現更好來重建信任。"},{"en":"Trust is rebuilt through repeated responsible actions, not only words.","zh":"信任是透過反覆負責任的行動重建的，不只是靠說話。"},{"en":"This phrase is useful after a reputation problem.","zh":"在聲譽問題之後，這個短語很有用。"}],"source":"2014 Q3.pdf","sourcePage":2},{"front":"be damaged","meaning":"受損","examples":[{"en":"The trust in the Drama Club has been damaged.","zh":"外界對戲劇學會的信任已經受損。"},{"en":"Be damaged means be harmed, weakened or made less strong.","zh":"Be damaged 指受到傷害、削弱或變得不再穩固。"},{"en":"A club’s reputation can be damaged by careless behaviour in public.","zh":"學會聲譽可能因公開場合中的粗心行為而受損。"},{"en":"Damaged trust takes time and effort to repair.","zh":"受損的信任需要時間和努力去修復。"},{"en":"This phrase shows that something valuable has been hurt.","zh":"這個短語顯示有價值的東西已受到傷害。"}],"source":"2014 Q3.pdf","sourcePage":3},{"front":"the incident","meaning":"事件","examples":[{"en":"The incident has made the school consider clearer rules.","zh":"這宗事件令學校考慮訂立更清晰的規則。"},{"en":"The incident means the particular event or problem being discussed.","zh":"The incident 指正在討論的特定事件或問題。"},{"en":"The incident at City Hall involved poor audience behaviour by some members.","zh":"大會堂事件涉及部分會員不當的觀眾行為。"},{"en":"An incident becomes serious when it affects the reputation of the whole club.","zh":"當事件影響整個學會的聲譽，它就變得嚴重。"},{"en":"This phrase helps refer to the problem without repeating every detail.","zh":"這個短語幫助指代問題，而不用重複每個細節。"}],"source":"2014 Q3.pdf","sourcePage":3},{"front":"teacher adviser","meaning":"指導老師","examples":[{"en":"The teacher adviser may help introduce clearer rules.","zh":"指導老師可能協助引入更清晰的規則。"},{"en":"A teacher adviser is a teacher who guides a school club and supports its members.","zh":"Teacher adviser 指指導學校學會並支援會員的老師。"},{"en":"The teacher adviser can explain expectations before members attend public events.","zh":"指導老師可以在會員出席公開活動前解釋期望。"},{"en":"Members should speak to the teacher adviser if they were involved in the incident.","zh":"如果會員涉事，應向指導老師交代。"},{"en":"This phrase identifies the adult responsible for guiding the club.","zh":"這個短語指出負責指導學會的成年人。"}],"source":"2014 Q3.pdf","sourcePage":3},{"front":"consider introducing","meaning":"考慮引入","examples":[{"en":"The school is considering introducing clearer rules for future outings.","zh":"學校正考慮為日後外出活動引入更清晰的規則。"},{"en":"Consider introducing means think seriously about starting or bringing in something new.","zh":"Consider introducing 指認真思考開始使用或帶入新事物。"},{"en":"The committee is considering introducing a briefing before every performance.","zh":"委員會正考慮在每次演出前引入簡介會。"},{"en":"Schools consider new rules when old arrangements are not enough.","zh":"當舊安排不足夠時，學校會考慮引入新規則。"},{"en":"This phrase shows that a change is being discussed but not necessarily final yet.","zh":"這個短語顯示改變正在討論中，但未必已成定案。"}],"source":"2014 Q3.pdf","sourcePage":3},{"front":"clearer rules","meaning":"更清晰的規則","examples":[{"en":"The club may need clearer rules for future outings.","zh":"學會可能需要為日後外出活動訂立更清晰的規則。"},{"en":"Clearer rules are instructions that are easier to understand and follow.","zh":"Clearer rules 指更容易理解和遵守的指引。"},{"en":"Clearer rules about phone use can prevent problems during performances.","zh":"關於電話使用的更清晰規則可以防止演出期間出現問題。"},{"en":"Members behave better when expectations are explained before an outing.","zh":"在外出活動前解釋期望，會員會表現得更好。"},{"en":"This phrase suggests practical improvement after confusion or mistakes.","zh":"這個短語暗示在混亂或錯誤後作出實際改善。"}],"source":"2014 Q3.pdf","sourcePage":3},{"front":"future outings","meaning":"日後外出活動","examples":[{"en":"Future outings should be organised with clearer expectations.","zh":"日後外出活動應在更清晰的期望下安排。"},{"en":"Future outings are trips or activities that will happen later outside school.","zh":"Future outings 指之後在校外舉行的旅行或活動。"},{"en":"Future outings to theatres should include rules about punctuality and silence.","zh":"日後到劇院的外出活動應包括關於準時和保持安靜的規則。"},{"en":"Good planning helps future outings run smoothly.","zh":"良好計劃能幫助日後外出活動順利進行。"},{"en":"This phrase points to later activities that can be improved.","zh":"這個短語指向可以改善的日後活動。"}],"source":"2014 Q3.pdf","sourcePage":3},{"front":"continue representing the school","meaning":"繼續代表學校","examples":[{"en":"The club should continue representing the school with maturity.","zh":"學會應以成熟態度繼續代表學校。"},{"en":"Continue representing the school means keep acting as a public face of the school.","zh":"Continue representing the school 指繼續作為學校的公開代表。"},{"en":"Students represent the school when they attend events in uniform.","zh":"學生穿校服出席活動時，就是代表學校。"},{"en":"To continue representing the school, members must show respect outside campus too.","zh":"若要繼續代表學校，會員在校外也必須表現尊重。"},{"en":"This phrase connects public behaviour with school identity.","zh":"這個短語把公共行為和學校身份連接起來。"}],"source":"2014 Q3.pdf","sourcePage":3},{"front":"maturity, respect and pride","meaning":"成熟、尊重和自豪","examples":[{"en":"The club should represent the school with maturity, respect and pride.","zh":"學會應以成熟、尊重和自豪代表學校。"},{"en":"Maturity, respect and pride mean responsible judgement, polite behaviour and positive self-respect.","zh":"Maturity, respect and pride 指負責任的判斷、有禮行為和正面的自尊。"},{"en":"Members show maturity when they admit mistakes and learn from them.","zh":"會員承認錯誤並從中學習時，就表現出成熟。"},{"en":"Respect and pride help students behave well even when teachers are not watching.","zh":"尊重和自豪能幫助學生即使老師不在場也有良好表現。"},{"en":"This phrase summarises the attitude expected from club members.","zh":"這個短語總結學會會員應有的態度。"}],"source":"2014 Q3.pdf","sourcePage":3},{"front":"according to the complaint","meaning":"根據投訴內容","examples":[{"en":"According to the complaint, several members disturbed the performance.","zh":"根據投訴內容，幾位會員騷擾了演出。"},{"en":"According to the complaint means based on what the complaint says.","zh":"According to the complaint 指根據投訴所說的內容。"},{"en":"According to the complaint, some audience members talked during important scenes.","zh":"根據投訴內容，一些觀眾在重要場景中說話。"},{"en":"This phrase reports information without saying the writer personally saw it.","zh":"這個短語報告資訊，但不表示作者親眼看見。"},{"en":"It is useful when referring to an official report.","zh":"引述正式報告時，這個短語很有用。"}],"source":"2014 Q3.pdf","sourcePage":3},{"front":"disturb the performance","meaning":"騷擾演出","examples":[{"en":"Several members disturbed the performance by talking during scenes.","zh":"幾位會員在場景進行時說話，騷擾了演出。"},{"en":"Disturb the performance means interrupt the show and make it harder for people to watch or act.","zh":"Disturb the performance 指打斷演出，令人更難觀看或表演。"},{"en":"A ringing phone can disturb the performance in a quiet theatre.","zh":"在安靜劇場中響起的電話可以騷擾演出。"},{"en":"Disturbing a performance is unfair to actors and audience members.","zh":"騷擾演出對演員和觀眾都不公平。"},{"en":"This phrase describes behaviour that damages a live event.","zh":"這個短語描述破壞現場活動的行為。"}],"source":"2014 Q3.pdf","sourcePage":3},{"front":"talking during scenes","meaning":"在場景進行時說話","examples":[{"en":"Talking during scenes can disturb both actors and audience members.","zh":"在場景進行時說話會騷擾演員和觀眾。"},{"en":"Talking during scenes means speaking while part of a play is being performed.","zh":"Talking during scenes 指戲劇某部分正在演出時說話。"},{"en":"Even quiet talking during scenes can distract people nearby.","zh":"即使很小聲，在場景進行時說話也會分散附近人的注意力。"},{"en":"Audience members should wait until the interval if they need to discuss the play.","zh":"如果觀眾需要討論劇情，應等到中場休息。"},{"en":"This phrase identifies a common form of poor theatre behaviour.","zh":"這個短語指出常見的不良劇場行為。"}],"source":"2014 Q3.pdf","sourcePage":4},{"front":"inappropriate moments","meaning":"不合適的時候","examples":[{"en":"Some members laughed at inappropriate moments.","zh":"有些會員在不合適的時候發笑。"},{"en":"Inappropriate moments are times when a reaction does not fit the situation.","zh":"Inappropriate moments 指某種反應不配合情況的時候。"},{"en":"Laughing during a serious death scene would be an inappropriate moment.","zh":"在嚴肅死亡場景中大笑，就是不合適的時候。"},{"en":"Reactions at the wrong time can hurt performers and confuse other audience members.","zh":"錯誤時間的反應可以傷害表演者，也令其他觀眾困惑。"},{"en":"This phrase helps judge whether behaviour suits the context.","zh":"這個短語幫助判斷行為是否配合語境。"}],"source":"2014 Q3.pdf","sourcePage":4},{"front":"use mobile phones","meaning":"使用手提電話","examples":[{"en":"Members should not use mobile phones during a performance.","zh":"會員不應在演出期間使用手提電話。"},{"en":"Use mobile phones means look at, type on, call with or record using phones.","zh":"Use mobile phones 指看電話、打字、通話或用電話錄影。"},{"en":"Bright phone screens can distract audience members in a dark theatre.","zh":"在黑暗劇場中，明亮的電話屏幕會分散觀眾注意力。"},{"en":"Using mobile phones during a performance shows poor theatre etiquette.","zh":"在演出期間使用手提電話顯示劇場禮儀欠佳。"},{"en":"This phrase is important in rules for live events.","zh":"這個短語在現場活動規則中很重要。"}],"source":"2014 Q3.pdf","sourcePage":4},{"front":"fail to follow instructions","meaning":"未能遵從指示","examples":[{"en":"Some members failed to follow the instructions of the venue staff.","zh":"有些會員未能遵從場地職員的指示。"},{"en":"Fail to follow instructions means not do what one has been told to do.","zh":"Fail to follow instructions 指沒有按照別人要求去做。"},{"en":"Students fail to follow instructions if they ignore staff asking them to be quiet.","zh":"如果學生無視職員要求保持安靜，就是未能遵從指示。"},{"en":"Failing to follow instructions can create disorder and safety problems.","zh":"未能遵從指示可能造成混亂和安全問題。"},{"en":"This phrase describes disobedience or carelessness.","zh":"這個短語描述不服從或粗心。"}],"source":"2014 Q3.pdf","sourcePage":4},{"front":"venue staff","meaning":"場地職員","examples":[{"en":"Audience members should follow the instructions of the venue staff.","zh":"觀眾應遵從場地職員的指示。"},{"en":"Venue staff are workers who manage a place where events are held.","zh":"Venue staff 指管理活動場地的工作人員。"},{"en":"Venue staff guide people to seats, keep order and handle emergencies.","zh":"場地職員引導觀眾入座、維持秩序並處理緊急情況。"},{"en":"Respecting venue staff helps performances run smoothly.","zh":"尊重場地職員有助演出順利進行。"},{"en":"This phrase identifies the people responsible for managing the event space.","zh":"這個短語指出負責管理活動空間的人。"}],"source":"2014 Q3.pdf","sourcePage":4},{"front":"while it would be unfair to suggest that","meaning":"雖然說……並不公平","examples":[{"en":"While it would be unfair to suggest that every member behaved poorly, the complaint is still serious.","zh":"雖然說每位會員都表現不當並不公平，但投訴仍然嚴重。"},{"en":"While it would be unfair to suggest that means although it would not be right to say something too broadly.","zh":"While it would be unfair to suggest that 指雖然作出某個過於籠統的說法並不正確。"},{"en":"While it would be unfair to blame the whole class, everyone should learn from the incident.","zh":"雖然責怪全班並不公平，但每個人都應從事件中學習。"},{"en":"This phrase helps the writer stay balanced while addressing a problem.","zh":"這個短語幫助作者在處理問題時保持平衡。"},{"en":"It separates individual responsibility from group reputation.","zh":"它把個人責任和群體聲譽分開。"}],"source":"2014 Q3.pdf","sourcePage":4},{"front":"behave poorly","meaning":"表現不當","examples":[{"en":"It would be unfair to say that every member behaved poorly.","zh":"說每位會員都表現不當並不公平。"},{"en":"Behave poorly means act in an unacceptable, rude or irresponsible way.","zh":"Behave poorly 指以不可接受、無禮或不負責任的方式行事。"},{"en":"Students behave poorly when they talk loudly during a serious performance.","zh":"學生在嚴肅演出中大聲說話，就是表現不當。"},{"en":"A few people behaving poorly can affect the image of the whole group.","zh":"少數人表現不當可以影響整個團體的形象。"},{"en":"This phrase describes behaviour that falls below expected standards.","zh":"這個短語描述低於期望標準的行為。"}],"source":"2014 Q3.pdf","sourcePage":4},{"front":"alter the fact that","meaning":"改變……這個事實","examples":[{"en":"This does not alter the fact that the complaint reflects badly on the club.","zh":"這並不改變投訴對學會造成負面形象這個事實。"},{"en":"Alter the fact that means change the truth that something is the case.","zh":"Alter the fact that 指改變某事屬實這個情況。"},{"en":"An apology is important, but it does not alter the fact that harm was caused.","zh":"道歉很重要，但這不改變已造成傷害這個事實。"},{"en":"This phrase is used when a point remains true despite other details.","zh":"當其他細節存在但某一點仍然屬實時，可以使用這個短語。"},{"en":"It helps keep attention on the main issue.","zh":"它幫助把注意力保留在主要問題上。"}],"source":"2014 Q3.pdf","sourcePage":4},{"front":"reflect badly on","meaning":"對……造成負面形象","examples":[{"en":"The complaint reflects badly on the whole Drama Club.","zh":"這宗投訴對整個戲劇學會造成負面形象。"},{"en":"Reflect badly on means make a person or group look irresponsible or negative.","zh":"Reflect badly on 指令某人或團體看起來不負責任或形象負面。"},{"en":"Noisy behaviour in public can reflect badly on a school.","zh":"在公共場合吵鬧會對學校造成負面形象。"},{"en":"Even one complaint may reflect badly on a club if it suggests poor manners.","zh":"即使只是一宗投訴，如果顯示禮貌欠佳，也可能對學會造成負面形象。"},{"en":"This phrase connects actions with reputation.","zh":"這個短語把行為和聲譽連接起來。"}],"source":"2014 Q3.pdf","sourcePage":4},{"front":"the whole Drama Club","meaning":"整個戲劇學會","examples":[{"en":"The complaint affects the reputation of the whole Drama Club.","zh":"這宗投訴影響整個戲劇學會的聲譽。"},{"en":"The whole Drama Club means all members and the club as one group.","zh":"The whole Drama Club 指所有會員以及作為一個整體的學會。"},{"en":"A few careless actions can create problems for the whole Drama Club.","zh":"少數粗心行為可以為整個戲劇學會帶來問題。"},{"en":"The whole Drama Club must learn from the incident, not only those involved.","zh":"整個戲劇學會都必須從事件中學習，不只是涉事者。"},{"en":"This phrase stresses shared reputation and responsibility.","zh":"這個短語強調共同聲譽和責任。"}],"source":"2014 Q3.pdf","sourcePage":4},{"front":"in school uniform","meaning":"穿着校服","examples":[{"en":"When students attend in school uniform, they represent the school.","zh":"當學生穿着校服出席活動，他們就代表學校。"},{"en":"In school uniform means wearing the official clothing of the school.","zh":"In school uniform 指穿着學校的正式服裝。"},{"en":"Students in school uniform are easily recognised as belonging to their school.","zh":"穿着校服的學生很容易被認出屬於某間學校。"},{"en":"Poor behaviour in school uniform can damage the school’s public image.","zh":"穿着校服時表現不當，可能損害學校的公眾形象。"},{"en":"This phrase connects clothing with public responsibility.","zh":"這個短語把服裝和公共責任連接起來。"}],"source":"2014 Q3.pdf","sourcePage":5},{"front":"no longer","meaning":"不再","examples":[{"en":"We are no longer watching as private individuals.","zh":"我們不再是以私人個體身份觀看演出。"},{"en":"No longer means not now, although it may have been true before.","zh":"No longer 指現在已不是這樣，雖然以前可能是。"},{"en":"When we wear school uniform, we are no longer just ordinary audience members.","zh":"當我們穿着校服，就不再只是普通觀眾。"},{"en":"This phrase shows a change in role or situation.","zh":"這個短語顯示身份或情況的改變。"},{"en":"It helps explain why responsibility increases in public.","zh":"它幫助解釋為何在公共場合責任會增加。"}],"source":"2014 Q3.pdf","sourcePage":5},{"front":"private individuals","meaning":"私人個體","examples":[{"en":"Students in uniform are not watching as private individuals.","zh":"穿着校服的學生不是以私人個體身份觀看演出。"},{"en":"Private individuals are people acting only for themselves, not for a group or organisation.","zh":"Private individuals 指只代表自己，而不是代表團體或機構的人。"},{"en":"Club members in uniform are seen as representatives, not private individuals.","zh":"穿着校服的學會會員被視為代表，而不是私人個體。"},{"en":"When students attend an event privately, their behaviour may not affect the school as directly.","zh":"當學生以私人身份出席活動，他們的行為未必那麼直接影響學校。"},{"en":"This phrase contrasts personal identity with public representation.","zh":"這個短語把個人身份和公共代表身份作對比。"}],"source":"2014 Q3.pdf","sourcePage":5},{"front":"represent our club","meaning":"代表我們的學會","examples":[{"en":"Members represent our club when they attend performances.","zh":"會員觀看演出時，就是代表我們的學會。"},{"en":"Represent our club means act in a way that affects how others see the club.","zh":"Represent our club 指行為會影響別人如何看待學會。"},{"en":"Members represent the club by being polite, punctual and respectful.","zh":"會員透過有禮、準時和尊重來代表學會。"},{"en":"If members behave badly in public, they represent the club poorly.","zh":"如果會員在公開場合表現差，他們就是沒有好好代表學會。"},{"en":"This phrase reminds members that their actions carry group meaning.","zh":"這個短語提醒會員，他們的行動帶有團體意義。"}],"source":"2014 Q3.pdf","sourcePage":5},{"front":"the audience around us","meaning":"我們身邊的觀眾","examples":[{"en":"The audience around us has paid for a meaningful theatre experience.","zh":"我們身邊的觀眾已付款享有有意義的劇場體驗。"},{"en":"The audience around us means the other people sitting nearby and watching the same performance.","zh":"The audience around us 指坐在附近、觀看同一場演出的其他人。"},{"en":"The audience around us deserves silence and respect during serious scenes.","zh":"我們身邊的觀眾在嚴肅場景中值得得到安靜和尊重。"},{"en":"Talking or using phones can disturb the audience around us.","zh":"說話或使用電話會騷擾我們身邊的觀眾。"},{"en":"This phrase reminds students that their behaviour affects strangers too.","zh":"這個短語提醒學生，他們的行為也會影響陌生人。"}],"source":"2014 Q3.pdf","sourcePage":5},{"front":"pay for","meaning":"付款享有","examples":[{"en":"The audience has paid for a meaningful theatre experience.","zh":"觀眾已付款享有有意義的劇場體驗。"},{"en":"Pay for means give money in exchange for a product, service or experience.","zh":"Pay for 指付錢換取產品、服務或體驗。"},{"en":"Audience members pay for tickets because they expect to enjoy the performance.","zh":"觀眾購票，因為他們期望好好欣賞演出。"},{"en":"Disturbing people who have paid for a show is unfair.","zh":"騷擾已付款觀看演出的人是不公平的。"},{"en":"This phrase connects money with the right to a proper experience.","zh":"這個短語把金錢和享有良好體驗的權利連接起來。"}],"source":"2014 Q3.pdf","sourcePage":5},{"front":"meaningful theatre experience","meaning":"有意義的劇場體驗","examples":[{"en":"Other audience members deserve a meaningful theatre experience.","zh":"其他觀眾值得擁有有意義的劇場體驗。"},{"en":"A meaningful theatre experience is a performance experience that feels valuable, focused and emotionally rich.","zh":"Meaningful theatre experience 指有價值、專注並富有情感的演出體驗。"},{"en":"Silence helps create a meaningful theatre experience for both actors and audience members.","zh":"安靜能為演員和觀眾創造有意義的劇場體驗。"},{"en":"A noisy audience can turn a meaningful experience into a frustrating one.","zh":"吵鬧的觀眾可以把有意義的體驗變成令人沮喪的體驗。"},{"en":"This phrase explains what respectful theatre behaviour protects.","zh":"這個短語解釋有禮劇場行為所保護的是甚麼。"}],"source":"2014 Q3.pdf","sourcePage":5},{"front":"spend months rehearsing","meaning":"花數月排練","examples":[{"en":"The actors have spent months rehearsing.","zh":"演員花了數月排練。"},{"en":"Spend months rehearsing means use many months practising before a performance.","zh":"Spend months rehearsing 指在演出前用很多個月練習。"},{"en":"Students may spend months rehearsing for an annual school production.","zh":"學生可能為一年一度的學校劇目花數月排練。"},{"en":"When actors spend months rehearsing, careless audience behaviour feels disrespectful.","zh":"當演員花數月排練，粗心的觀眾行為會顯得不尊重。"},{"en":"This phrase shows the effort behind a live performance.","zh":"這個短語顯示現場演出背後的努力。"}],"source":"2014 Q3.pdf","sourcePage":5},{"front":"rehearse","meaning":"排練","examples":[{"en":"Actors rehearse carefully before a performance.","zh":"演員在演出前仔細排練。"},{"en":"Rehearse means practise a play, speech, dance or performance before showing it publicly.","zh":"Rehearse 指在公開演出前練習戲劇、演講、舞蹈或表演。"},{"en":"Drama Club members rehearse lines and movements after school.","zh":"戲劇學會會員放學後排練對白和動作。"},{"en":"Rehearsing helps performers remember timing, emotion and stage positions.","zh":"排練幫助表演者記住時間、情感和舞台位置。"},{"en":"This word is important in theatre and performance contexts.","zh":"這個詞在劇場和表演語境中很重要。"}],"source":"2014 Q3.pdf","sourcePage":5},{"front":"maintain order","meaning":"維持秩序","examples":[{"en":"The venue staff have worked hard to maintain order.","zh":"場地職員努力維持秩序。"},{"en":"Maintain order means keep people calm, organised and following rules.","zh":"Maintain order 指令人保持冷靜、有組織並遵守規則。"},{"en":"Teachers maintain order during school assemblies by giving clear instructions.","zh":"老師在學校集會中透過清楚指示維持秩序。"},{"en":"Venue staff maintain order so the performance can continue without disturbance.","zh":"場地職員維持秩序，讓演出不受騷擾地繼續。"},{"en":"This phrase is useful when discussing crowd or event management.","zh":"討論人群或活動管理時，這個短語很有用。"}],"source":"2014 Q3.pdf","sourcePage":5},{"front":"treat the theatre as if","meaning":"把劇場當作","examples":[{"en":"Members should not treat the theatre as if it were a classroom corridor.","zh":"會員不應把劇場當作課室走廊。"},{"en":"Treat the theatre as if means behave toward the theatre as though it were something else.","zh":"Treat the theatre as if 指對待劇場時好像它是另一種地方。"},{"en":"Students should not treat a theatre as if it were a noisy playground.","zh":"學生不應把劇場當作吵鬧的遊樂場。"},{"en":"Treating a formal space like a casual space can lead to disrespectful behaviour.","zh":"把正式空間當作隨便空間，可能導致不尊重的行為。"},{"en":"This phrase criticises a wrong attitude toward a place.","zh":"這個短語批評對某地方的錯誤態度。"}],"source":"2014 Q3.pdf","sourcePage":6},{"front":"classroom corridor","meaning":"課室走廊","examples":[{"en":"The theatre should not be treated like a classroom corridor.","zh":"劇場不應被當作課室走廊。"},{"en":"A classroom corridor is a passage outside classrooms where students often walk and talk.","zh":"Classroom corridor 指課室外學生常行走和交談的通道。"},{"en":"Students may chat freely in a corridor, but a theatre requires silence.","zh":"學生可能在走廊自由聊天，但劇場需要安靜。"},{"en":"Comparing a theatre to a classroom corridor shows why the behaviour was inappropriate.","zh":"把劇場與課室走廊作比較，顯示那種行為為何不合適。"},{"en":"This phrase creates a clear contrast between casual and formal spaces.","zh":"這個短語在隨便和正式空間之間建立清楚對比。"}],"source":"2014 Q3.pdf","sourcePage":6},{"front":"interrupt the concentration of","meaning":"打斷……的專注","examples":[{"en":"Talking during a performance can interrupt the concentration of the actors.","zh":"演出期間說話可以打斷演員的專注。"},{"en":"Interrupt the concentration of someone means break their focus while they are trying to do something carefully.","zh":"Interrupt the concentration of someone 指在某人仔細做事時打斷其注意力。"},{"en":"A ringing phone can interrupt the concentration of performers on stage.","zh":"響起的電話可以打斷台上表演者的專注。"},{"en":"Actors need focus because live performance cannot simply be paused and restarted.","zh":"演員需要專注，因為現場演出不能簡單暫停再重來。"},{"en":"This phrase shows how audience behaviour affects performers directly.","zh":"這個短語顯示觀眾行為如何直接影響表演者。"}],"source":"2014 Q3.pdf","sourcePage":6},{"front":"concentration","meaning":"專注","examples":[{"en":"Actors need concentration during a live performance.","zh":"演員在現場演出期間需要專注。"},{"en":"Concentration means focused attention on one task.","zh":"Concentration 指把注意力集中在一項任務上。"},{"en":"Students need concentration when they perform difficult scenes.","zh":"學生表演困難場景時需要專注。"},{"en":"Noise can break concentration and cause mistakes.","zh":"噪音可以打斷專注並造成錯誤。"},{"en":"This word is useful when discussing study, work or performance.","zh":"討論學習、工作或表演時，這個詞很有用。"}],"source":"2014 Q3.pdf","sourcePage":6},{"front":"distract other audience members","meaning":"分散其他觀眾的注意力","examples":[{"en":"Using mobile phones can distract other audience members.","zh":"使用手提電話會分散其他觀眾的注意力。"},{"en":"Distract other audience members means take other viewers’ attention away from the performance.","zh":"Distract other audience members 指把其他觀眾的注意力從演出上移走。"},{"en":"A bright screen can distract other audience members in a dark theatre.","zh":"在黑暗劇場中，明亮屏幕會分散其他觀眾的注意力。"},{"en":"Distraction is unfair because others have come to enjoy the show.","zh":"分心是不公平的，因為其他人是來欣賞演出的。"},{"en":"This phrase explains why phone use affects more than the phone user.","zh":"這個短語解釋電話使用為何不只影響使用者本人。"}],"source":"2014 Q3.pdf","sourcePage":6},{"front":"show little respect for","meaning":"對……缺乏尊重","examples":[{"en":"Poor behaviour shows little respect for the art form.","zh":"不良行為顯示對這種藝術形式缺乏尊重。"},{"en":"Show little respect for means behave as if something is not important or valuable.","zh":"Show little respect for 指行為上好像某事不重要或沒有價值。"},{"en":"Talking during a play shows little respect for the actors’ effort.","zh":"在戲劇演出中說話顯示對演員努力缺乏尊重。"},{"en":"Students show respect by listening, staying quiet and following instructions.","zh":"學生透過聆聽、保持安靜和遵守指示來表現尊重。"},{"en":"This phrase criticises careless behaviour.","zh":"這個短語批評粗心行為。"}],"source":"2014 Q3.pdf","sourcePage":6},{"front":"art form","meaning":"藝術形式","examples":[{"en":"Drama is an art form that deserves respect.","zh":"戲劇是一種值得尊重的藝術形式。"},{"en":"An art form is a type of creative expression, such as drama, music, dance or painting.","zh":"Art form 指創意表達的類型，例如戲劇、音樂、舞蹈或繪畫。"},{"en":"Each art form has its own rules, skills and traditions.","zh":"每種藝術形式都有自己的規則、技巧和傳統。"},{"en":"Drama as an art form needs both performers and audience members to take it seriously.","zh":"戲劇作為藝術形式，需要表演者和觀眾都認真對待。"},{"en":"This phrase helps discuss creative work with respect.","zh":"這個短語幫助人以尊重態度討論創作。"}],"source":"2014 Q3.pdf","sourcePage":6},{"front":"claim to love","meaning":"聲稱熱愛","examples":[{"en":"We should respect the art form we claim to love.","zh":"我們應尊重自己聲稱熱愛的藝術形式。"},{"en":"Claim to love means say that we love or care about something.","zh":"Claim to love 指說自己熱愛或關心某事。"},{"en":"If students claim to love drama, they should also respect other people’s performances.","zh":"如果學生聲稱熱愛戲劇，他們也應尊重別人的演出。"},{"en":"Words mean little if behaviour does not match what people claim to love.","zh":"如果行為與聲稱熱愛的東西不一致，說話就意義不大。"},{"en":"This phrase challenges people to act according to their values.","zh":"這個短語要求人按照自己的價值行動。"}],"source":"2014 Q3.pdf","sourcePage":6},{"front":"put simply","meaning":"簡單來說","examples":[{"en":"Put simply, drama is not only about performing on stage.","zh":"簡單來說，戲劇不只是關於在台上表演。"},{"en":"Put simply means said in a clear and direct way.","zh":"Put simply 指用清楚直接的方式說。"},{"en":"Put simply, good manners matter as much as acting skills.","zh":"簡單來說，良好禮貌和演技一樣重要。"},{"en":"Writers use this phrase before giving a simple explanation of a larger idea.","zh":"作者在簡單解釋較大想法前會使用這個短語。"},{"en":"This phrase helps make an argument easy to understand.","zh":"這個短語幫助令論點容易理解。"}],"source":"2014 Q3.pdf","sourcePage":6},{"front":"not just about","meaning":"不只是關於","examples":[{"en":"Drama is not just about performing on stage.","zh":"戲劇不只是關於在台上表演。"},{"en":"Not just about means something has a deeper or wider meaning than one obvious part.","zh":"Not just about 指某事不只有一個明顯部分，而有更深或更廣的意義。"},{"en":"School is not just about marks; it is also about character and responsibility.","zh":"學校不只是關於分數，也關於品格和責任。"},{"en":"Drama includes watching, listening and respecting live performance.","zh":"戲劇包括觀看、聆聽和尊重現場演出。"},{"en":"This phrase moves from a narrow idea to a broader one.","zh":"這個短語把狹窄想法推向更廣闊想法。"}],"source":"2014 Q3.pdf","sourcePage":6},{"front":"perform on stage","meaning":"在台上表演","examples":[{"en":"Drama is not just about performing on stage.","zh":"戲劇不只是關於在台上表演。"},{"en":"Perform on stage means act, speak, sing or move in front of an audience.","zh":"Perform on stage 指在觀眾面前演戲、說話、唱歌或動作。"},{"en":"Drama Club members practise hard before they perform on stage.","zh":"戲劇學會會員在台上表演前努力排練。"},{"en":"Performing on stage requires confidence, discipline and teamwork.","zh":"在台上表演需要信心、紀律和團隊合作。"},{"en":"This phrase describes the visible part of theatre work.","zh":"這個短語描述劇場工作中可見的部分。"}],"source":"2014 Q3.pdf","sourcePage":7},{"front":"live performance","meaning":"現場演出","examples":[{"en":"Live performance should be respected by performers and audiences.","zh":"現場演出應受到表演者和觀眾尊重。"},{"en":"A live performance is a show performed in front of an audience in real time.","zh":"Live performance 指在觀眾面前即時進行的演出。"},{"en":"A live performance cannot be edited or restarted like a video.","zh":"現場演出不能像影片一樣剪輯或重新開始。"},{"en":"Audience noise can affect a live performance because actors hear and feel it immediately.","zh":"觀眾噪音會影響現場演出，因為演員會即時聽到和感受到。"},{"en":"This phrase explains why theatre etiquette matters.","zh":"這個短語解釋劇場禮儀為何重要。"}],"source":"2014 Q3.pdf","sourcePage":7},{"front":"from the audience’s side","meaning":"從觀眾一方","examples":[{"en":"Drama should be respected from the audience’s side as well.","zh":"戲劇也應從觀眾一方受到尊重。"},{"en":"From the audience’s side means from the position or responsibility of people watching.","zh":"From the audience’s side 指從觀看者的位置或責任來看。"},{"en":"Theatre succeeds not only from the actors’ side but also from the audience’s side.","zh":"劇場成功不只靠演員一方，也靠觀眾一方。"},{"en":"From the audience’s side, respect means silence, attention and patience.","zh":"從觀眾一方來看，尊重代表安靜、專注和耐性。"},{"en":"This phrase shows that viewers also shape a performance.","zh":"這個短語顯示觀眾也會塑造一場演出。"}],"source":"2014 Q3.pdf","sourcePage":7},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, the incident reminds members what the club stands for.","zh":"更重要的是，這宗事件提醒會員學會代表甚麼。"},{"en":"More importantly introduces a point that matters more than what was said before.","zh":"More importantly 用來引出比前面更重要的一點。"},{"en":"The apology is necessary; more importantly, members must change their behaviour.","zh":"道歉是必要的；更重要的是，會員必須改變行為。"},{"en":"Writers use this phrase to guide readers to the deeper issue.","zh":"作者用這個短語引導讀者看見更深層問題。"},{"en":"This phrase helps structure a serious argument.","zh":"這個短語幫助組織嚴肅論點。"}],"source":"2014 Q3.pdf","sourcePage":7},{"front":"serve as a serious reminder","meaning":"作為嚴肅提醒","examples":[{"en":"The incident should serve as a serious reminder of our responsibilities.","zh":"這宗事件應作為對我們責任的嚴肅提醒。"},{"en":"Serve as a serious reminder means act as an important warning or lesson.","zh":"Serve as a serious reminder 指作為重要警告或教訓。"},{"en":"A complaint can serve as a serious reminder that public behaviour matters.","zh":"一宗投訴可以作為嚴肅提醒，說明公共行為很重要。"},{"en":"Serious reminders help people change before a worse problem happens.","zh":"嚴肅提醒幫助人在更嚴重問題發生前改變。"},{"en":"This phrase connects a mistake with future improvement.","zh":"這個短語把錯誤和未來改善連接起來。"}],"source":"2014 Q3.pdf","sourcePage":7},{"front":"membership in the Drama Club","meaning":"戲劇學會會員身分","examples":[{"en":"Membership in the Drama Club carries responsibilities.","zh":"戲劇學會會員身分帶有責任。"},{"en":"Membership in the Drama Club means belonging to the club and sharing its duties and reputation.","zh":"Membership in the Drama Club 指屬於戲劇學會，並共同承擔其責任和聲譽。"},{"en":"Membership gives students chances to perform, but it also requires respectful behaviour.","zh":"會員身分給學生表演機會，但也要求有禮行為。"},{"en":"Being a member means representing the club both on and off stage.","zh":"成為會員代表在台上和台下都代表學會。"},{"en":"This phrase connects belonging with responsibility.","zh":"這個短語把歸屬和責任連接起來。"}],"source":"2014 Q3.pdf","sourcePage":7},{"front":"drama teaches empathy","meaning":"戲劇教導同理心","examples":[{"en":"Drama teaches empathy, discipline and teamwork.","zh":"戲劇教導同理心、紀律和團隊合作。"},{"en":"Drama teaches empathy means acting helps students understand other people’s feelings.","zh":"Drama teaches empathy 指表演幫助學生理解別人的感受。"},{"en":"When students play different characters, they practise seeing the world through others’ eyes.","zh":"當學生扮演不同角色，他們就在練習從別人的角度看世界。"},{"en":"Empathy learned through drama should continue when students become audience members.","zh":"從戲劇學到的同理心，應在學生成為觀眾時繼續存在。"},{"en":"This phrase shows the moral value of drama education.","zh":"這個短語顯示戲劇教育的道德價值。"}],"source":"2014 Q3.pdf","sourcePage":7},{"front":"empathy","meaning":"同理心","examples":[{"en":"Drama should help students develop empathy.","zh":"戲劇應幫助學生培養同理心。"},{"en":"Empathy means the ability to understand and care about another person’s feelings.","zh":"Empathy 指理解並關心別人感受的能力。"},{"en":"A student shows empathy when she thinks about how disturbed actors may feel.","zh":"當學生想到被騷擾的演員可能有何感受，她就表現出同理心。"},{"en":"Empathy helps audience members behave more respectfully.","zh":"同理心幫助觀眾表現得更尊重。"},{"en":"This word is important when discussing drama and character education.","zh":"討論戲劇和品格教育時，這個詞很重要。"}],"source":"2014 Q3.pdf","sourcePage":7},{"front":"discipline","meaning":"紀律","examples":[{"en":"Drama teaches discipline as well as creativity.","zh":"戲劇教導創意，也教導紀律。"},{"en":"Discipline means self-control and the ability to follow rules or keep working carefully.","zh":"Discipline 指自我控制，以及遵守規則或細心持續工作的能力。"},{"en":"Actors need discipline to arrive on time and remember their lines.","zh":"演員需要紀律去準時到達並記住對白。"},{"en":"Audience members also need discipline to stay quiet and attentive.","zh":"觀眾也需要紀律去保持安靜和專心。"},{"en":"This word connects theatre with responsibility.","zh":"這個詞把劇場和責任連接起來。"}],"source":"2014 Q3.pdf","sourcePage":7},{"front":"teamwork","meaning":"團隊合作","examples":[{"en":"Drama Club members should show teamwork on and off stage.","zh":"戲劇學會會員在台上和台下都應表現團隊合作。"},{"en":"Teamwork means working together responsibly to achieve a shared goal.","zh":"Teamwork 指負責任地一起工作，以達成共同目標。"},{"en":"Actors show teamwork when they listen, support and respond to one another.","zh":"演員聆聽、支持和回應彼此時，就是表現團隊合作。"},{"en":"Audience discipline is also teamwork because members protect the club’s reputation together.","zh":"觀眾紀律也是團隊合作，因為會員一起保護學會聲譽。"},{"en":"This word shows that drama is not only individual performance.","zh":"這個詞顯示戲劇不只是個人表演。"}],"source":"2014 Q3.pdf","sourcePage":7},{"front":"mean very little","meaning":"意義不大","examples":[{"en":"These values mean very little if they disappear outside school.","zh":"如果這些價值在校外消失，它們就意義不大。"},{"en":"Mean very little means have little real value or importance.","zh":"Mean very little 指沒有多少真正價值或重要性。"},{"en":"Respect means very little if members only show it when teachers are watching.","zh":"如果會員只在老師看着時才表現尊重，尊重就意義不大。"},{"en":"Values become real when people practise them in public life.","zh":"當人們在公共生活中實踐價值，價值才變得真實。"},{"en":"This phrase criticises words that are not supported by action.","zh":"這個短語批評沒有行動支持的說話。"}],"source":"2014 Q3.pdf","sourcePage":8},{"front":"the moment","meaning":"一……的時候","examples":[{"en":"Those values should not disappear the moment we leave school.","zh":"這些價值不應在我們一離開學校的時候就消失。"},{"en":"The moment means as soon as something happens.","zh":"The moment 指某事一發生就立即如此。"},{"en":"Good manners should not disappear the moment students step outside the campus.","zh":"良好禮貌不應在學生一走出校園時就消失。"},{"en":"If responsibility ends the moment no teacher is present, it is not real responsibility.","zh":"如果責任感在老師不在場的一刻就結束，那就不是真正責任感。"},{"en":"This phrase highlights an immediate change.","zh":"這個短語突出即時變化。"}],"source":"2014 Q3.pdf","sourcePage":8},{"front":"school campus","meaning":"校園","examples":[{"en":"Club values should continue beyond the school campus.","zh":"學會價值應延續到校園以外。"},{"en":"School campus means the buildings and grounds of a school.","zh":"School campus 指學校的建築和範圍。"},{"en":"Students should behave well both inside and outside the school campus.","zh":"學生在校園內外都應有良好行為。"},{"en":"A club’s reputation can be affected by what members do beyond campus.","zh":"會員在校園外的行為也可以影響學會聲譽。"},{"en":"This phrase contrasts school space with the wider public world.","zh":"這個短語把學校空間和更廣闊的公共世界作對比。"}],"source":"2014 Q3.pdf","sourcePage":8},{"front":"know when to speak","meaning":"知道何時說話","examples":[{"en":"A good performer knows when to speak and when to listen.","zh":"好表演者知道何時說話和何時聆聽。"},{"en":"Know when to speak means understand the right moment to talk.","zh":"Know when to speak 指明白甚麼時候適合說話。"},{"en":"Actors know when to speak because timing affects the meaning of a scene.","zh":"演員知道何時說話，因為時間掌握會影響場景意義。"},{"en":"Audience members also need to know when not to speak during a performance.","zh":"觀眾在演出期間也需要知道何時不應說話。"},{"en":"This phrase connects communication with judgement.","zh":"這個短語把溝通和判斷力連接起來。"}],"source":"2014 Q3.pdf","sourcePage":8},{"front":"know when to listen","meaning":"知道何時聆聽","examples":[{"en":"A good performer knows when to listen.","zh":"好表演者知道何時聆聽。"},{"en":"Know when to listen means understand the right moment to stay quiet and pay attention.","zh":"Know when to listen 指明白甚麼時候應保持安靜並專心。"},{"en":"Actors know when to listen so they can respond naturally to others on stage.","zh":"演員知道何時聆聽，才能自然回應台上的其他人。"},{"en":"Audience members show respect when they know when to listen.","zh":"觀眾知道何時聆聽，就是表現尊重。"},{"en":"This phrase teaches that silence can be active and thoughtful.","zh":"這個短語教人明白沉默也可以是主動而有思考的。"}],"source":"2014 Q3.pdf","sourcePage":8},{"front":"silence itself carries meaning","meaning":"沉默本身帶有意義","examples":[{"en":"A good performer knows when silence itself carries meaning.","zh":"好表演者知道何時沉默本身帶有意義。"},{"en":"Silence itself carries meaning means a quiet moment can express feeling or importance.","zh":"Silence itself carries meaning 指安靜時刻可以表達情感或重要性。"},{"en":"In a sad scene, silence itself may carry more meaning than a long speech.","zh":"在悲傷場景中，沉默本身可能比長篇說話更有意義。"},{"en":"Audience noise can destroy the meaning of silence in live drama.","zh":"觀眾噪音可以破壞現場戲劇中沉默的意義。"},{"en":"This phrase shows why quietness matters in theatre.","zh":"這個短語顯示安靜在劇場中為何重要。"}],"source":"2014 Q3.pdf","sourcePage":8},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, careless audience behaviour suggests a lack of respect.","zh":"相比之下，粗心失禮的觀眾行為顯示缺乏尊重。"},{"en":"By contrast means compared with the previous point, this is different.","zh":"By contrast 指與前一點相比，這裏有所不同。"},{"en":"Respectful silence supports actors; by contrast, phone use distracts them.","zh":"尊重的沉默支持演員；相比之下，使用電話會分散他們注意力。"},{"en":"Writers use this phrase to show a clear difference between two ideas.","zh":"作者用這個短語顯示兩個想法之間的清楚差異。"},{"en":"This phrase helps build a balanced argument.","zh":"這個短語幫助建立平衡論點。"}],"source":"2014 Q3.pdf","sourcePage":8},{"front":"careless audience behaviour","meaning":"粗心失禮的觀眾行為","examples":[{"en":"Careless audience behaviour damages the club’s reputation.","zh":"粗心失禮的觀眾行為損害學會聲譽。"},{"en":"Careless audience behaviour means rude or thoughtless actions by people watching a performance.","zh":"Careless audience behaviour 指觀眾在觀看演出時無禮或欠考慮的行動。"},{"en":"Talking, laughing at the wrong time and using phones are careless audience behaviours.","zh":"說話、在錯誤時間發笑和使用電話都是粗心失禮的觀眾行為。"},{"en":"Such behaviour can disturb actors and embarrass the school.","zh":"這種行為可以騷擾演員，也令學校尷尬。"},{"en":"This phrase describes the main problem in the complaint.","zh":"這個短語描述投訴中的主要問題。"}],"source":"2014 Q3.pdf","sourcePage":8},{"front":"under the spotlight","meaning":"在聚光燈下","examples":[{"en":"Drama should not matter only when we are under the spotlight.","zh":"戲劇不應只在我們站在聚光燈下時才重要。"},{"en":"Under the spotlight means being on stage, watched closely or receiving attention.","zh":"Under the spotlight 指在台上、被密切觀看或受到注意。"},{"en":"Students may behave well under the spotlight but forget manners as audience members.","zh":"學生可能在聚光燈下表現良好，卻在做觀眾時忘記禮貌。"},{"en":"True respect for drama continues even when no one is praising us.","zh":"對戲劇的真正尊重，即使沒有人稱讚我們時也會繼續。"},{"en":"This phrase can be literal in theatre and figurative in life.","zh":"這個短語在劇場中可作字面意思，也可作比喻意思。"}],"source":"2014 Q3.pdf","sourcePage":8},{"front":"the kind of club we should become","meaning":"我們應該成為的那種學會","examples":[{"en":"That is not the kind of club we should become.","zh":"那不是我們應該成為的那種學會。"},{"en":"The kind of club we should become means the type of group we ought to grow into.","zh":"The kind of club we should become 指我們應該成長為怎樣的團體。"},{"en":"The club should become a group known for respect, discipline and care.","zh":"學會應成為以尊重、紀律和關懷見稱的團體。"},{"en":"If members ignore manners, the club becomes something weaker than its values.","zh":"如果會員忽視禮貌，學會就會變得低於自己的價值。"},{"en":"This phrase asks members to think about identity and standards.","zh":"這個短語要求會員思考身份和標準。"}],"source":"2014 Q3.pdf","sourcePage":8},{"front":"consider this","meaning":"試想想","examples":[{"en":"Consider this: how would we feel if others disturbed our production?","zh":"試想想：如果別人騷擾我們的製作，我們會有何感受？"},{"en":"Consider this means think carefully about the following example or question.","zh":"Consider this 指仔細思考接下來的例子或問題。"},{"en":"Consider this: would we accept visitors talking during our own show?","zh":"試想想：如果訪客在我們自己的演出中說話，我們會接受嗎？"},{"en":"Writers use this phrase to make readers imagine another point of view.","zh":"作者用這個短語令讀者想像另一個角度。"},{"en":"This phrase introduces reflection.","zh":"這個短語引出反思。"}],"source":"2014 Q3.pdf","sourcePage":9},{"front":"visiting students","meaning":"到訪學生","examples":[{"en":"Visiting students should behave respectfully at our school production.","zh":"到訪學生在我們的學校劇目中應有禮地表現。"},{"en":"Visiting students are students from another school or place who come to attend an event.","zh":"Visiting students 指來自其他學校或地方、到訪參加活動的學生。"},{"en":"Visiting students represent their own school when they sit in our audience.","zh":"到訪學生坐在我們觀眾席時，代表他們自己的學校。"},{"en":"We expect visiting students to respect our actors and venue rules.","zh":"我們期望到訪學生尊重我們的演員和場地規則。"},{"en":"This phrase helps reverse the situation and build empathy.","zh":"這個短語幫助反轉情境並建立同理心。"}],"source":"2014 Q3.pdf","sourcePage":9},{"front":"behave noisily","meaning":"吵鬧地表現","examples":[{"en":"We would be disappointed if visiting students behaved noisily.","zh":"如果到訪學生吵鬧地表現，我們會感到失望。"},{"en":"Behave noisily means act in a loud and disturbing way.","zh":"Behave noisily 指以響亮而騷擾他人的方式行事。"},{"en":"Students behave noisily when they talk, laugh or move around during a performance.","zh":"學生在演出期間說話、大笑或走動，就是吵鬧地表現。"},{"en":"Noisy behaviour can make performers feel ignored or insulted.","zh":"吵鬧行為會令表演者感到被忽視或被冒犯。"},{"en":"This phrase describes behaviour that breaks theatre etiquette.","zh":"這個短語描述破壞劇場禮儀的行為。"}],"source":"2014 Q3.pdf","sourcePage":9},{"front":"annual school production","meaning":"一年一度的學校劇目","examples":[{"en":"Our annual school production deserves respect from visitors.","zh":"我們一年一度的學校劇目值得到訪者尊重。"},{"en":"An annual school production is a play or performance held by a school once a year.","zh":"Annual school production 指學校每年舉行一次的戲劇或表演。"},{"en":"Students may spend months preparing for the annual school production.","zh":"學生可能花數月準備一年一度的學校劇目。"},{"en":"Visitors should behave politely because the production represents many students’ hard work.","zh":"到訪者應有禮，因為劇目代表許多學生的努力。"},{"en":"This phrase describes an important repeated school event.","zh":"這個短語描述重要的定期學校活動。"}],"source":"2014 Q3.pdf","sourcePage":9},{"front":"feel disappointed","meaning":"感到失望","examples":[{"en":"Members would feel disappointed if others disturbed their performance.","zh":"如果別人騷擾他們的演出，會員會感到失望。"},{"en":"Feel disappointed means feel sad or let down because expectations were not met.","zh":"Feel disappointed 指因期望落空而感到傷心或失落。"},{"en":"Actors feel disappointed when the audience does not respect their effort.","zh":"當觀眾不尊重演員的努力，演員會感到失望。"},{"en":"Disappointment can teach people to consider how their own behaviour affects others.","zh":"失望可以教人思考自己的行為如何影響他人。"},{"en":"This phrase describes an emotional response to disrespect.","zh":"這個短語描述對不尊重的情感反應。"}],"source":"2014 Q3.pdf","sourcePage":9},{"front":"even hurt","meaning":"甚至受傷","examples":[{"en":"Performers may feel disappointed, even hurt, by noisy behaviour.","zh":"表演者可能因吵鬧行為感到失望，甚至受傷。"},{"en":"Even hurt means not only disappointed but also emotionally wounded.","zh":"Even hurt 指不只是失望，還在情感上受傷。"},{"en":"A student actor may feel even hurt if friends laugh during a serious scene.","zh":"如果朋友在嚴肅場景中發笑，學生演員可能甚至感到受傷。"},{"en":"Noisy behaviour can feel personal because performers have worked hard.","zh":"吵鬧行為可能令人覺得是針對個人，因為表演者付出了很多努力。"},{"en":"This phrase strengthens the emotional effect.","zh":"這個短語加強情感影響。"}],"source":"2014 Q3.pdf","sourcePage":9},{"front":"the same standard applies to","meaning":"同樣標準也適用於","examples":[{"en":"The same standard applies to us when we watch others perform.","zh":"當我們觀看別人表演時，同樣標準也適用於我們。"},{"en":"The same standard applies to means the same rule or expectation should be used for another person or group.","zh":"The same standard applies to 指同一規則或期望也應用於另一人或群體。"},{"en":"If we expect respect for our show, the same standard applies when we watch others.","zh":"如果我們期望別人尊重我們的演出，當我們觀看別人時，同樣標準也適用。"},{"en":"Fairness means using the same standard for ourselves and for visitors.","zh":"公平代表對自己和訪客使用同樣標準。"},{"en":"This phrase is useful when discussing consistency and fairness.","zh":"討論一致性和公平時，這個短語很有用。"}],"source":"2014 Q3.pdf","sourcePage":9},{"front":"Manners maketh man","meaning":"禮貌造就人品","examples":[{"en":"Manners maketh man, especially in the theatre.","zh":"禮貌造就人品，尤其在劇場中。"},{"en":"Manners maketh man means good manners show a person’s character.","zh":"Manners maketh man 指良好禮貌顯示一個人的品格。"},{"en":"A student’s manners in public can reveal more than their exam results.","zh":"學生在公共場合的禮貌可以比考試成績更能顯示其為人。"},{"en":"In the theatre, manners show whether audience members respect others’ effort.","zh":"在劇場中，禮貌顯示觀眾是否尊重別人的努力。"},{"en":"This saying teaches that behaviour shapes reputation.","zh":"這句諺語教人行為會塑造聲譽。"}],"source":"2014 Q3.pdf","sourcePage":9},{"front":"protect the dignity of","meaning":"維護……的尊嚴","examples":[{"en":"Good manners protect the dignity of everyone involved.","zh":"良好禮貌維護所有相關人士的尊嚴。"},{"en":"Protect the dignity of someone means help them be treated with respect and worth.","zh":"Protect the dignity of someone 指幫助某人受到有尊嚴和價值的對待。"},{"en":"Quiet audience behaviour protects the dignity of performers on stage.","zh":"安靜的觀眾行為維護台上表演者的尊嚴。"},{"en":"Rules protect dignity by preventing people from being embarrassed or disturbed.","zh":"規則透過防止人被尷尬或騷擾來維護尊嚴。"},{"en":"This phrase connects manners with human respect.","zh":"這個短語把禮貌和對人的尊重連接起來。"}],"source":"2014 Q3.pdf","sourcePage":9},{"front":"dignity","meaning":"尊嚴","examples":[{"en":"Manners protect the dignity of performers and audience members.","zh":"禮貌維護表演者和觀眾的尊嚴。"},{"en":"Dignity means the worth and respect every person deserves.","zh":"Dignity 指每個人應有的價值和尊重。"},{"en":"Performers deserve dignity because they have worked hard to share their art.","zh":"表演者值得尊嚴，因為他們努力分享藝術。"},{"en":"Audience members also deserve dignity when they pay for a meaningful experience.","zh":"觀眾付款享有有意義體驗時，也值得得到尊嚴。"},{"en":"This word is important in discussions of respect.","zh":"討論尊重時，這個詞很重要。"}],"source":"2014 Q3.pdf","sourcePage":9},{"front":"everyone involved","meaning":"所有相關人士","examples":[{"en":"Theatre manners protect everyone involved.","zh":"劇場禮儀保護所有相關人士。"},{"en":"Everyone involved means all the people taking part or affected by the event.","zh":"Everyone involved 指所有參與或受事件影響的人。"},{"en":"Everyone involved includes actors, audience members, teachers and venue staff.","zh":"所有相關人士包括演員、觀眾、老師和場地職員。"},{"en":"Good behaviour helps everyone involved enjoy a smoother experience.","zh":"良好行為幫助所有相關人士有更順利的體驗。"},{"en":"This phrase reminds readers that an event affects many people.","zh":"這個短語提醒讀者，一項活動影響很多人。"}],"source":"2014 Q3.pdf","sourcePage":10},{"front":"with this in mind","meaning":"考慮到這一點","examples":[{"en":"With this in mind, the committee will take immediate steps.","zh":"考慮到這一點，委員會會立即採取措施。"},{"en":"With this in mind means considering what has just been said.","zh":"With this in mind 指考慮到剛才所說的事情。"},{"en":"With this in mind, members should attend a briefing before the next outing.","zh":"考慮到這一點，會員應在下一次外出活動前出席簡介會。"},{"en":"Writers use this phrase to move from explanation to action.","zh":"作者用這個短語由解釋轉向行動。"},{"en":"This phrase connects reflection with practical response.","zh":"這個短語把反思和實際回應連接起來。"}],"source":"2014 Q3.pdf","sourcePage":10},{"front":"the committee","meaning":"委員會","examples":[{"en":"The committee will take several immediate steps.","zh":"委員會會立即採取幾項措施。"},{"en":"The committee is the group chosen to make decisions and organise club affairs.","zh":"Committee 指被選出來作決定並組織學會事務的團隊。"},{"en":"The committee may include the chairperson, secretary, treasurer and other student leaders.","zh":"委員會可能包括主席、秘書、財政和其他學生領袖。"},{"en":"A responsible committee responds quickly when the club’s reputation is at risk.","zh":"當學會聲譽受威脅，負責任的委員會會迅速回應。"},{"en":"This phrase identifies the group responsible for action.","zh":"這個短語指出負責行動的團體。"}],"source":"2014 Q3.pdf","sourcePage":10},{"front":"take immediate steps","meaning":"立即採取措施","examples":[{"en":"The committee will take immediate steps to repair the damage.","zh":"委員會會立即採取措施修復損害。"},{"en":"Take immediate steps means act quickly to deal with a problem.","zh":"Take immediate steps 指迅速採取行動處理問題。"},{"en":"After receiving the complaint, the club should take immediate steps to apologise.","zh":"收到投訴後，學會應立即採取措施道歉。"},{"en":"Quick action shows that the problem is being treated seriously.","zh":"快速行動顯示問題正被認真看待。"},{"en":"This phrase is useful in formal problem-solving.","zh":"這個短語適合用於正式解決問題。"}],"source":"2014 Q3.pdf","sourcePage":10},{"front":"written apology","meaning":"書面道歉","examples":[{"en":"The chairperson will send a written apology to City Hall.","zh":"主席會向大會堂發出書面道歉。"},{"en":"A written apology is an apology sent in writing, such as a letter or email.","zh":"Written apology 指以書面形式發出的道歉，例如信件或電郵。"},{"en":"A written apology should accept responsibility and explain how the problem will be fixed.","zh":"書面道歉應承擔責任，並解釋如何修正問題。"},{"en":"Sending a written apology shows respect for the people affected.","zh":"發出書面道歉顯示對受影響者的尊重。"},{"en":"This phrase is common after formal complaints.","zh":"這個短語常見於正式投訴之後。"}],"source":"2014 Q3.pdf","sourcePage":10},{"front":"on behalf of","meaning":"代表","examples":[{"en":"Chris will apologise on behalf of the Drama Club.","zh":"Chris 會代表戲劇學會道歉。"},{"en":"On behalf of means speaking or acting for a person or group.","zh":"On behalf of 指代表某人或某團體說話或行動。"},{"en":"The chairperson wrote to City Hall on behalf of all club members.","zh":"主席代表所有學會會員寫信給大會堂。"},{"en":"Apologising on behalf of a group shows shared responsibility.","zh":"代表團體道歉顯示共同責任。"},{"en":"This phrase is common in formal letters and speeches.","zh":"這個短語常見於正式信件和演講。"}],"source":"2014 Q3.pdf","sourcePage":10},{"front":"be directly involved","meaning":"直接涉事","examples":[{"en":"Members who were directly involved should come forward.","zh":"直接涉事的會員應主動站出來。"},{"en":"Be directly involved means personally take part in the incident or action.","zh":"Be directly involved 指親身參與事件或行動。"},{"en":"Students who used phones during the performance were directly involved.","zh":"在演出期間使用電話的學生就是直接涉事。"},{"en":"People directly involved should take responsibility instead of staying silent.","zh":"直接涉事的人應承擔責任，而不是保持沉默。"},{"en":"This phrase separates those who acted from those who only heard about it.","zh":"這個短語把行動者和只是聽聞事件的人分開。"}],"source":"2014 Q3.pdf","sourcePage":10},{"front":"come forward","meaning":"主動站出來","examples":[{"en":"Members who were involved should come forward and apologise.","zh":"涉事會員應主動站出來並道歉。"},{"en":"Come forward means voluntarily speak up, admit involvement or offer information.","zh":"Come forward 指自願發聲、承認涉事或提供資料。"},{"en":"A student should come forward if they know they broke the theatre rules.","zh":"如果學生知道自己違反劇場規則，就應主動站出來。"},{"en":"Coming forward shows courage because it accepts responsibility.","zh":"主動站出來顯示勇氣，因為這代表承擔責任。"},{"en":"This phrase is useful when honesty is needed after an incident.","zh":"事件發生後需要誠實時，這個短語很有用。"}],"source":"2014 Q3.pdf","sourcePage":10},{"front":"apologise to","meaning":"向……道歉","examples":[{"en":"Members should apologise to the teacher adviser.","zh":"會員應向指導老師道歉。"},{"en":"Apologise to someone means say sorry directly to the person affected or responsible.","zh":"Apologise to someone 指直接向受影響或負責的人說對不起。"},{"en":"Students should apologise to venue staff if they ignored instructions.","zh":"如果學生無視指示，應向場地職員道歉。"},{"en":"A sincere apology includes responsibility, not only the word “sorry.”","zh":"真誠道歉包括承擔責任，而不只是說「對不起」。"},{"en":"This phrase is important in repairing relationships.","zh":"這個短語對修復關係很重要。"}],"source":"2014 Q3.pdf","sourcePage":10},{"front":"by Friday","meaning":"在星期五或之前","examples":[{"en":"Members should apologise to the teacher adviser by Friday.","zh":"會員應在星期五或之前向指導老師道歉。"},{"en":"By Friday means no later than Friday.","zh":"By Friday 指不遲於星期五。"},{"en":"Students must submit their apology letters by Friday afternoon.","zh":"學生必須在星期五下午或之前提交道歉信。"},{"en":"A clear deadline helps members know when action must be completed.","zh":"清楚期限幫助會員知道何時必須完成行動。"},{"en":"This phrase is useful for instructions and formal notices.","zh":"這個短語適合用於指示和正式通知。"}],"source":"2014 Q3.pdf","sourcePage":10},{"front":"external activity","meaning":"校外活動","examples":[{"en":"All members will attend a briefing before the next external activity.","zh":"所有會員會在下一次校外活動前出席簡介會。"},{"en":"An external activity is an event held outside the school campus.","zh":"External activity 指在校園外舉行的活動。"},{"en":"Watching a play at City Hall is an external activity for the Drama Club.","zh":"到大會堂看戲是戲劇學會的一項校外活動。"},{"en":"External activities require extra care because students represent the school in public.","zh":"校外活動需要格外小心，因為學生在公共場合代表學校。"},{"en":"This phrase is useful in school event planning.","zh":"這個短語適合用於學校活動策劃。"}],"source":"2014 Q3.pdf","sourcePage":11},{"front":"attend a short briefing","meaning":"出席簡短簡介會","examples":[{"en":"Members will attend a short briefing on theatre etiquette.","zh":"會員會出席關於劇場禮儀的簡短簡介會。"},{"en":"Attend a short briefing means go to a brief meeting where important instructions are given.","zh":"Attend a short briefing 指參加一個簡短會議，以聽取重要指示。"},{"en":"Students attend a short briefing before trips so they understand the rules.","zh":"學生在旅行前出席簡短簡介會，以了解規則。"},{"en":"A briefing before a performance can prevent careless mistakes.","zh":"演出前的簡介會可以防止粗心錯誤。"},{"en":"This phrase describes practical preparation.","zh":"這個短語描述實際準備。"}],"source":"2014 Q3.pdf","sourcePage":11},{"front":"theatre etiquette","meaning":"劇場禮儀","examples":[{"en":"Members need to understand theatre etiquette.","zh":"會員需要理解劇場禮儀。"},{"en":"Theatre etiquette means the manners and rules expected when watching a live performance.","zh":"Theatre etiquette 指觀看現場演出時應有的禮貌和規則。"},{"en":"Theatre etiquette includes arriving on time, staying quiet and turning off phones.","zh":"劇場禮儀包括準時到達、保持安靜和關掉電話。"},{"en":"Good theatre etiquette protects actors’ concentration and the audience’s experience.","zh":"良好劇場禮儀保護演員的專注和觀眾的體驗。"},{"en":"This phrase is central to the complaint and future improvement.","zh":"這個短語是投訴和日後改善的核心。"}],"source":"2014 Q3.pdf","sourcePage":11},{"front":"punctuality","meaning":"準時","examples":[{"en":"The briefing will cover punctuality and phone use.","zh":"簡介會會涵蓋準時和電話使用。"},{"en":"Punctuality means arriving or doing something on time.","zh":"Punctuality 指準時到達或準時做事。"},{"en":"Punctuality matters at the theatre because late arrivals can disturb others.","zh":"準時在劇場中很重要，因為遲到會騷擾他人。"},{"en":"A club known for punctuality appears organised and respectful.","zh":"以準時見稱的學會看起來有組織並尊重他人。"},{"en":"This word is important in formal activities and performances.","zh":"這個詞在正式活動和演出中很重要。"}],"source":"2014 Q3.pdf","sourcePage":11},{"front":"phone use","meaning":"電話使用","examples":[{"en":"Theatre etiquette includes proper phone use.","zh":"劇場禮儀包括適當的電話使用。"},{"en":"Phone use means how and when people use their mobile phones.","zh":"Phone use 指人們如何及何時使用手提電話。"},{"en":"Proper phone use in a theatre means turning phones off or keeping them silent.","zh":"在劇場中，適當電話使用代表關掉電話或保持靜音。"},{"en":"Poor phone use can distract performers and audience members.","zh":"不當電話使用會分散表演者和觀眾的注意力。"},{"en":"This phrase is useful in rules for public events.","zh":"這個短語適合用於公共活動規則。"}],"source":"2014 Q3.pdf","sourcePage":11},{"front":"seating arrangements","meaning":"座位安排","examples":[{"en":"The briefing will explain seating arrangements.","zh":"簡介會會解釋座位安排。"},{"en":"Seating arrangements are plans showing where people should sit.","zh":"Seating arrangements 指說明人們應坐在哪裏的安排。"},{"en":"Clear seating arrangements help teachers and committee members supervise students.","zh":"清楚座位安排幫助老師和委員監督學生。"},{"en":"Seating arrangements can reduce confusion before a performance begins.","zh":"座位安排可以減少演出開始前的混亂。"},{"en":"This phrase is important in event organisation.","zh":"這個短語在活動組織中很重要。"}],"source":"2014 Q3.pdf","sourcePage":11},{"front":"respond to venue staff","meaning":"回應場地職員","examples":[{"en":"Members should know how to respond to venue staff.","zh":"會員應知道如何回應場地職員。"},{"en":"Respond to venue staff means answer or act properly when staff give instructions.","zh":"Respond to venue staff 指在職員給出指示時適當回答或行動。"},{"en":"If venue staff ask members to move seats, members should respond politely.","zh":"如果場地職員要求會員換座位，會員應有禮地回應。"},{"en":"Good responses prevent small problems from becoming arguments.","zh":"良好回應能防止小問題變成爭執。"},{"en":"This phrase teaches respectful cooperation with event workers.","zh":"這個短語教人尊重地與活動工作人員合作。"}],"source":"2014 Q3.pdf","sourcePage":11},{"front":"future performances","meaning":"日後演出","examples":[{"en":"Committee members will help supervise future performances.","zh":"委員會成員會協助監督日後演出。"},{"en":"Future performances are plays or shows that members will attend or join later.","zh":"Future performances 指會員之後會觀看或參與的戲劇或表演。"},{"en":"Future performances should be supported by clearer rules and better supervision.","zh":"日後演出應有更清晰規則和更好監督支持。"},{"en":"Learning from one incident can improve behaviour at future performances.","zh":"從一次事件中學習，可以改善日後演出的行為。"},{"en":"This phrase points to later chances to do better.","zh":"這個短語指向之後可以做得更好的機會。"}],"source":"2014 Q3.pdf","sourcePage":11},{"front":"at least two","meaning":"至少兩名","examples":[{"en":"At least two committee members will be assigned to each row.","zh":"每一行座位會安排至少兩名委員會成員。"},{"en":"At least two means two or more, but not fewer than two.","zh":"At least two 指兩名或以上，但不少於兩名。"},{"en":"At least two adults should be present during a large student outing.","zh":"大型學生外出活動應至少有兩名成年人在場。"},{"en":"Having at least two helpers nearby makes supervision easier.","zh":"附近至少有兩名助手，監督會較容易。"},{"en":"This phrase gives a minimum number.","zh":"這個短語給出最低數量。"}],"source":"2014 Q3.pdf","sourcePage":11},{"front":"be assigned to","meaning":"被分配到","examples":[{"en":"Two committee members will be assigned to each row.","zh":"兩名委員會成員會被分配到每一行座位。"},{"en":"Be assigned to means be given a particular duty, place or group to look after.","zh":"Be assigned to 指被安排負責某項職責、地方或群體。"},{"en":"A teacher may assign two students to help at the entrance.","zh":"老師可能安排兩名學生協助入口工作。"},{"en":"Committee members assigned to each row can notice problems quickly.","zh":"被分配到每一行的委員可以快速留意問題。"},{"en":"This phrase is useful for organising responsibilities.","zh":"這個短語適合用於組織責任。"}],"source":"2014 Q3.pdf","sourcePage":11},{"front":"each row","meaning":"每一行座位","examples":[{"en":"Each row will have committee members nearby.","zh":"每一行座位附近都會有委員會成員。"},{"en":"Each row means every line of seats in the theatre.","zh":"Each row 指劇場中每一排座位。"},{"en":"If each row has a helper nearby, problems can be handled more quickly.","zh":"如果每一行座位附近都有助手，問題可以更快處理。"},{"en":"Clear row arrangements help members know who to ask for help.","zh":"清楚的座位行安排幫助會員知道可以向誰求助。"},{"en":"This phrase gives a practical detail about supervision.","zh":"這個短語提供關於監督的實際細節。"}],"source":"2014 Q3.pdf","sourcePage":12},{"front":"deal with quietly","meaning":"低調處理","examples":[{"en":"Problems should be dealt with quietly before they escalate.","zh":"問題應在升級前被低調處理。"},{"en":"Deal with quietly means handle a problem calmly and without creating more disturbance.","zh":"Deal with quietly 指平靜地處理問題，而不製造更多騷擾。"},{"en":"A committee member can deal with noisy behaviour quietly by giving a gentle reminder.","zh":"委員可以透過輕聲提醒來低調處理吵鬧行為。"},{"en":"Quiet handling is useful in a theatre because the performance should not be interrupted.","zh":"在劇場中低調處理很有用，因為演出不應被打斷。"},{"en":"This phrase describes a careful way to manage problems.","zh":"這個短語描述謹慎管理問題的方法。"}],"source":"2014 Q3.pdf","sourcePage":12},{"front":"before they escalate","meaning":"在問題升級之前","examples":[{"en":"Problems should be dealt with before they escalate.","zh":"問題應在升級之前處理。"},{"en":"Before they escalate means before problems become more serious or harder to control.","zh":"Before they escalate 指在問題變得更嚴重或更難控制之前。"},{"en":"A quiet reminder can stop talking before it escalates into a complaint.","zh":"輕聲提醒可以在說話行為升級成投訴前阻止它。"},{"en":"Small issues are easier to solve before they grow larger.","zh":"小問題在變大前較容易解決。"},{"en":"This phrase is useful in risk management.","zh":"這個短語適合用於風險管理。"}],"source":"2014 Q3.pdf","sourcePage":12},{"front":"not meant to","meaning":"並非旨在","examples":[{"en":"This is not meant to police everyone unnecessarily.","zh":"這並非旨在不必要地監視所有人。"},{"en":"Not meant to means not intended to do something.","zh":"Not meant to 指目的並不是做某事。"},{"en":"The briefing is not meant to shame members, but to prevent future problems.","zh":"簡介會並非旨在羞辱會員，而是防止日後問題。"},{"en":"This phrase helps explain the purpose of a rule or action.","zh":"這個短語幫助解釋規則或行動的目的。"},{"en":"It reduces misunderstanding by saying what the intention is not.","zh":"它透過說明意圖不是甚麼來減少誤解。"}],"source":"2014 Q3.pdf","sourcePage":12},{"front":"police everyone","meaning":"監視所有人","examples":[{"en":"The new arrangement is not meant to police everyone.","zh":"新安排並非旨在監視所有人。"},{"en":"Police everyone means watch and control people too strictly.","zh":"Police everyone 指過分嚴格地監察和控制每個人。"},{"en":"A teacher should guide students, not police everyone all the time.","zh":"老師應指導學生，而不是一直監視所有人。"},{"en":"The row arrangement is meant to support members, not treat them like criminals.","zh":"座位行安排是為了支援會員，不是把他們當成犯錯者。"},{"en":"This phrase can sound critical of unnecessary control.","zh":"這個短語可帶有批評不必要控制的意味。"}],"source":"2014 Q3.pdf","sourcePage":12},{"front":"unnecessarily","meaning":"不必要地","examples":[{"en":"The committee does not want to police everyone unnecessarily.","zh":"委員會不想不必要地監視所有人。"},{"en":"Unnecessarily means in a way that is not needed or useful.","zh":"Unnecessarily 指以不需要或沒有用的方式。"},{"en":"Rules should protect the club without making members feel unnecessarily watched.","zh":"規則應保護學會，而不令會員覺得被不必要地監視。"},{"en":"Doing something unnecessarily can create tension instead of trust.","zh":"不必要地做某事可能製造緊張，而不是信任。"},{"en":"This word helps limit an action to what is reasonable.","zh":"這個詞幫助把行動限制在合理範圍內。"}],"source":"2014 Q3.pdf","sourcePage":12},{"front":"practical way to ensure that","meaning":"確保……的實際方法","examples":[{"en":"The arrangement is a practical way to ensure that outings can continue.","zh":"這項安排是確保外出活動能繼續的實際方法。"},{"en":"A practical way to ensure that means a realistic method for making sure something happens.","zh":"A practical way to ensure that 指確保某事發生的實際可行方法。"},{"en":"A briefing is a practical way to ensure that everyone understands theatre etiquette.","zh":"簡介會是確保每個人理解劇場禮儀的實際方法。"},{"en":"Clear rules can ensure that future outings are safer and better organised.","zh":"清晰規則能確保日後外出活動更安全和更有組織。"},{"en":"This phrase connects a method with a desired result.","zh":"這個短語把方法和理想結果連接起來。"}],"source":"2014 Q3.pdf","sourcePage":12},{"front":"irresponsible actions","meaning":"不負責任的行為","examples":[{"en":"A few irresponsible actions should not harm all members.","zh":"少數不負責任的行為不應傷害所有會員。"},{"en":"Irresponsible actions are careless behaviours that ignore duties or consequences.","zh":"Irresponsible actions 指忽視責任或後果的粗心行為。"},{"en":"Using phones during a play is an irresponsible action if it disturbs others.","zh":"如果在戲劇中使用電話騷擾他人，那就是不負責任的行為。"},{"en":"Irresponsible actions by a few people can put future outings at risk.","zh":"少數人的不負責任行為可能令日後外出活動受威脅。"},{"en":"This phrase criticises behaviour that fails to consider others.","zh":"這個短語批評沒有考慮他人的行為。"}],"source":"2014 Q3.pdf","sourcePage":12},{"front":"put future outings at risk","meaning":"令日後外出活動受威脅","examples":[{"en":"Irresponsible actions may put future outings at risk.","zh":"不負責任的行為可能令日後外出活動受威脅。"},{"en":"Put future outings at risk means make later trips or activities less likely to continue safely.","zh":"Put future outings at risk 指令之後的旅行或活動較難安全地繼續。"},{"en":"If the school loses trust in the club, future outings may be cancelled.","zh":"如果學校對學會失去信任，日後外出活動可能被取消。"},{"en":"Bad behaviour puts opportunities at risk for members who behaved well too.","zh":"不良行為也會令表現良好的會員失去機會。"},{"en":"This phrase shows the consequence of careless actions.","zh":"這個短語顯示粗心行動的後果。"}],"source":"2014 Q3.pdf","sourcePage":12},{"front":"I would appreciate it if","meaning":"如……我將不勝感激","examples":[{"en":"I would appreciate it if every member could treat this matter seriously.","zh":"如每位會員都能認真看待此事，我將不勝感激。"},{"en":"I would appreciate it if means I would be grateful if you did this.","zh":"I would appreciate it if 指如果你做某事，我會很感激。"},{"en":"I would appreciate it if members arrived early for the briefing.","zh":"如會員能提早到達簡介會，我將不勝感激。"},{"en":"This phrase makes a request sound polite and formal.","zh":"這個短語令請求聽起來有禮而正式。"},{"en":"It is useful in emails from leaders or teachers.","zh":"它適合用於領袖或老師的電郵。"}],"source":"2014 Q3.pdf","sourcePage":12},{"front":"treat this matter seriously","meaning":"認真看待此事","examples":[{"en":"Every member should treat this matter seriously.","zh":"每位會員都應認真看待此事。"},{"en":"Treat this matter seriously means understand that the issue is important and respond responsibly.","zh":"Treat this matter seriously 指明白問題重要，並負責任地回應。"},{"en":"Members treat the matter seriously by attending the briefing and following new rules.","zh":"會員透過出席簡介會和遵守新規則來認真看待此事。"},{"en":"Ignoring the complaint would show that the club has not learned from it.","zh":"忽視投訴會顯示學會沒有從中學習。"},{"en":"This phrase asks for mature attention.","zh":"這個短語要求成熟地關注事件。"}],"source":"2014 Q3.pdf","sourcePage":13},{"front":"whether or not","meaning":"不論是否","examples":[{"en":"Members should care whether or not they were personally involved.","zh":"會員不論是否親身涉事，都應關心此事。"},{"en":"Whether or not means it does not matter if something is true or false.","zh":"Whether or not 指某事是否屬實都沒有分別。"},{"en":"Whether or not a member was involved, the club’s reputation affects everyone.","zh":"不論會員是否涉事，學會聲譽都影響所有人。"},{"en":"This phrase includes both people who were involved and those who were not.","zh":"這個短語包括涉事者和沒有涉事的人。"},{"en":"It is useful when stressing shared responsibility.","zh":"強調共同責任時，這個短語很有用。"}],"source":"2014 Q3.pdf","sourcePage":13},{"front":"personally involved","meaning":"親身涉事","examples":[{"en":"Some members were not personally involved in the incident.","zh":"有些會員並沒有親身涉事。"},{"en":"Personally involved means directly taking part in an event or problem.","zh":"Personally involved 指直接參與事件或問題。"},{"en":"A member who stayed quiet throughout the play was not personally involved in the complaint.","zh":"在整場戲中保持安靜的會員並沒有親身涉事。"},{"en":"Even members not personally involved may need to help rebuild the club’s reputation.","zh":"即使沒有親身涉事的會員，也可能需要協助重建學會聲譽。"},{"en":"This phrase separates individual action from group responsibility.","zh":"這個短語把個人行動和團體責任分開。"}],"source":"2014 Q3.pdf","sourcePage":13},{"front":"there is no use","meaning":"……沒有用","examples":[{"en":"There is no use blaming one another endlessly.","zh":"無休止地互相責怪沒有用。"},{"en":"There is no use means something will not help or solve the problem.","zh":"There is no use 指某事不會有幫助或不能解決問題。"},{"en":"There is no use arguing if no one is willing to learn.","zh":"如果沒有人願意學習，爭吵也沒有用。"},{"en":"Blame alone does not repair trust or improve future conduct.","zh":"單靠責怪不能修復信任或改善日後行為。"},{"en":"This phrase directs attention from complaint to action.","zh":"這個短語把注意力由抱怨轉向行動。"}],"source":"2014 Q3.pdf","sourcePage":13},{"front":"blame one another","meaning":"互相責怪","examples":[{"en":"There is no use blaming one another endlessly.","zh":"無休止地互相責怪沒有用。"},{"en":"Blame one another means accuse each other of causing the problem.","zh":"Blame one another 指互相指責對方造成問題。"},{"en":"Members may blame one another when they feel embarrassed or afraid.","zh":"會員感到尷尬或害怕時，可能會互相責怪。"},{"en":"Blaming one another can divide a club instead of helping it improve.","zh":"互相責怪會分裂學會，而不是幫助它改善。"},{"en":"This phrase describes an unhelpful response to conflict.","zh":"這個短語描述面對衝突時沒有幫助的反應。"}],"source":"2014 Q3.pdf","sourcePage":13},{"front":"endlessly","meaning":"無休止地","examples":[{"en":"The club should not blame one another endlessly.","zh":"學會不應無休止地互相責怪。"},{"en":"Endlessly means without stopping or without reaching a useful result.","zh":"Endlessly 指不停地或沒有達到有用結果地。"},{"en":"Discussing mistakes is useful, but arguing endlessly wastes time.","zh":"討論錯誤是有用的，但無休止地爭吵會浪費時間。"},{"en":"A club cannot rebuild trust if members keep blaming one another endlessly.","zh":"如果會員無休止地互相責怪，學會就不能重建信任。"},{"en":"This word often suggests something has gone on too long.","zh":"這個詞常暗示某事持續得太久。"}],"source":"2014 Q3.pdf","sourcePage":13},{"front":"what matters now is that","meaning":"現在重要的是","examples":[{"en":"What matters now is that we face up to the complaint.","zh":"現在重要的是，我們要正視這宗投訴。"},{"en":"What matters now is that means the most important thing at this point is this.","zh":"What matters now is that 指在這一刻最重要的是這件事。"},{"en":"What matters now is that members apologise and learn from the incident.","zh":"現在重要的是，會員要道歉並從事件中學習。"},{"en":"This phrase helps move people away from blame and toward responsibility.","zh":"這個短語幫助人離開責怪，轉向責任。"},{"en":"It is useful when setting priorities after a problem.","zh":"在問題發生後設定優先次序時，它很有用。"}],"source":"2014 Q3.pdf","sourcePage":13},{"front":"face up to","meaning":"正視","examples":[{"en":"The club must face up to the complaint.","zh":"學會必須正視這宗投訴。"},{"en":"Face up to means accept and deal with a difficult truth or problem.","zh":"Face up to 指接受並處理困難真相或問題。"},{"en":"Students must face up to the fact that their behaviour affected others.","zh":"學生必須正視自己的行為影響了他人這個事實。"},{"en":"Facing up to a mistake is the first step toward rebuilding trust.","zh":"正視錯誤是重建信任的第一步。"},{"en":"This phrase shows courage and responsibility.","zh":"這個短語顯示勇氣和責任。"}],"source":"2014 Q3.pdf","sourcePage":13},{"front":"learn from it","meaning":"從中學習","examples":[{"en":"Members should learn from the incident.","zh":"會員應從事件中學習。"},{"en":"Learn from it means use a mistake or experience to improve future behaviour.","zh":"Learn from it 指利用錯誤或經驗改善日後行為。"},{"en":"The club can learn from the incident by creating clearer rules.","zh":"學會可以透過制定更清晰規則，從事件中學習。"},{"en":"A mistake becomes useful only if people change because of it.","zh":"錯誤只有在人們因此改變時才變得有用。"},{"en":"This phrase turns failure into education.","zh":"這個短語把失敗變成教育。"}],"source":"2014 Q3.pdf","sourcePage":13},{"front":"prove through our future conduct","meaning":"透過日後行為證明","examples":[{"en":"The club must prove through future conduct that it has changed.","zh":"學會必須透過日後行為證明自己已經改變。"},{"en":"Prove through our future conduct means show by later behaviour, not just promises, that improvement is real.","zh":"Prove through our future conduct 指不是只靠承諾，而是用之後的行為顯示真正改善。"},{"en":"Members can prove through future conduct that they understand theatre etiquette.","zh":"會員可以透過日後行為證明自己理解劇場禮儀。"},{"en":"Trust returns when people see better behaviour repeatedly.","zh":"當人們反覆看見更好的行為，信任才會回來。"},{"en":"This phrase stresses action over words.","zh":"這個短語強調行動勝於說話。"}],"source":"2014 Q3.pdf","sourcePage":13},{"front":"future conduct","meaning":"日後行為","examples":[{"en":"Future conduct will show whether the club has learnt its lesson.","zh":"日後行為會顯示學會是否已吸取教訓。"},{"en":"Future conduct means how people behave later after an incident or warning.","zh":"Future conduct 指人在事件或警告之後的行為。"},{"en":"The club’s future conduct should be quieter, more respectful and better organised.","zh":"學會日後行為應更安靜、更尊重和更有組織。"},{"en":"Future conduct matters because apologies must be supported by behaviour.","zh":"日後行為很重要，因為道歉必須由行動支持。"},{"en":"This phrase links present promises with later proof.","zh":"這個短語把現在的承諾和之後的證明連接起來。"}],"source":"2014 Q3.pdf","sourcePage":14},{"front":"define us","meaning":"定義我們","examples":[{"en":"This incident does not define us.","zh":"這宗事件不會定義我們。"},{"en":"Define us means decide who we are or what people should think of us completely.","zh":"Define us 指完全決定我們是誰或別人應如何看待我們。"},{"en":"One mistake should not define a student if they learn and change.","zh":"如果學生學習並改變，一次錯誤不應定義他。"},{"en":"The club can show that the incident does not define it through better behaviour.","zh":"學會可以透過更好行為，顯示事件不會定義它。"},{"en":"This phrase gives hope while still accepting responsibility.","zh":"這個短語在承擔責任的同時帶來希望。"}],"source":"2014 Q3.pdf","sourcePage":14},{"front":"should you have any concerns","meaning":"如你有任何疑慮","examples":[{"en":"Should you have any concerns, please speak to the chairperson.","zh":"如你有任何疑慮，請與主席交談。"},{"en":"Should you have any concerns means if you have any worries or questions.","zh":"Should you have any concerns 指如果你有任何擔心或問題。"},{"en":"Should you have any concerns about the new rules, please contact the committee.","zh":"如你對新規則有任何疑慮，請聯絡委員會。"},{"en":"This phrase sounds formal and polite in emails.","zh":"這個短語在電郵中聽起來正式而有禮。"},{"en":"It invites members to communicate instead of staying confused.","zh":"它邀請會員溝通，而不是保持困惑。"}],"source":"2014 Q3.pdf","sourcePage":14},{"front":"speak to","meaning":"與……交談","examples":[{"en":"Members may speak to the chairperson after school.","zh":"會員可以放學後與主席交談。"},{"en":"Speak to someone means talk with that person, often to ask, explain or discuss.","zh":"Speak to someone 指與某人談話，通常是為了詢問、解釋或討論。"},{"en":"Students should speak to the teacher adviser if they feel worried about the complaint.","zh":"如果學生對投訴感到擔心，應與指導老師交談。"},{"en":"Speaking to a leader can help solve misunderstandings early.","zh":"與領袖交談可以及早解決誤會。"},{"en":"This phrase is useful for offering support.","zh":"這個短語適合用於提供支援。"}],"source":"2014 Q3.pdf","sourcePage":14},{"front":"after school","meaning":"放學後","examples":[{"en":"Members can speak to the chairperson after school this week.","zh":"會員本星期可以放學後與主席交談。"},{"en":"After school means when classes have finished for the day.","zh":"After school 指一天課堂結束之後。"},{"en":"Students often attend club meetings after school.","zh":"學生常在放學後參加學會會議。"},{"en":"Holding discussions after school gives members time to speak without disturbing lessons.","zh":"放學後討論讓會員有時間交談，而不影響課堂。"},{"en":"This phrase describes a common time for school activities.","zh":"這個短語描述學校活動常見的時間。"}],"source":"2014 Q3.pdf","sourcePage":14},{"front":"build a good reputation","meaning":"建立良好聲譽","examples":[{"en":"The Drama Club has built a good reputation through hard work.","zh":"戲劇學會透過努力建立了良好聲譽。"},{"en":"Build a good reputation means gradually earn people’s respect and trust.","zh":"Build a good reputation 指逐漸贏得人們的尊重和信任。"},{"en":"A club builds a good reputation by performing well and behaving responsibly.","zh":"學會透過出色表演和負責任行為建立良好聲譽。"},{"en":"Reputation takes time to build but can be damaged quickly.","zh":"聲譽需要時間建立，但可以很快受損。"},{"en":"This phrase connects effort with public trust.","zh":"這個短語把努力和公眾信任連接起來。"}],"source":"2014 Q3.pdf","sourcePage":14},{"front":"reputation","meaning":"聲譽","examples":[{"en":"The club’s reputation should be protected.","zh":"學會的聲譽應受到保護。"},{"en":"Reputation means what people generally think about a person, group or organisation.","zh":"Reputation 指人們普遍如何看待某人、團體或機構。"},{"en":"A club’s reputation improves when members are known for discipline and respect.","zh":"當會員以紀律和尊重見稱，學會聲譽就會改善。"},{"en":"Poor behaviour can harm reputation even after many successful performances.","zh":"即使有很多成功演出，不良行為仍可以損害聲譽。"},{"en":"This word is important when discussing public image.","zh":"討論公眾形象時，這個詞很重要。"}],"source":"2014 Q3.pdf","sourcePage":14},{"front":"through years of hard work","meaning":"透過多年努力","examples":[{"en":"The club built its reputation through years of hard work.","zh":"學會透過多年努力建立聲譽。"},{"en":"Through years of hard work means by making effort over a long period.","zh":"Through years of hard work 指經過長時間努力。"},{"en":"A school team may win respect through years of hard work and fair play.","zh":"校隊可能透過多年努力和公平比賽贏得尊重。"},{"en":"Long effort makes a reputation valuable and worth protecting.","zh":"長時間努力令聲譽有價值並值得保護。"},{"en":"This phrase stresses that success was not quick or easy.","zh":"這個短語強調成功不是快速或容易得來的。"}],"source":"2014 Q3.pdf","sourcePage":14},{"front":"unpleasant incident","meaning":"不愉快事件","examples":[{"en":"One unpleasant incident should not destroy the club’s reputation.","zh":"一宗不愉快事件不應破壞學會聲譽。"},{"en":"An unpleasant incident is a problem or event that causes embarrassment, discomfort or harm.","zh":"Unpleasant incident 指造成尷尬、不舒服或傷害的問題或事件。"},{"en":"A complaint from a public venue is an unpleasant incident for a school club.","zh":"來自公共場地的投訴對學校學會來說是不愉快事件。"},{"en":"An unpleasant incident can still become a lesson if members respond properly.","zh":"如果會員正確回應，不愉快事件仍可以變成教訓。"},{"en":"This phrase describes a negative event without using extreme language.","zh":"這個短語用不極端的語言描述負面事件。"}],"source":"2014 Q3.pdf","sourcePage":14},{"front":"should not be allowed to","meaning":"不應被容許","examples":[{"en":"One incident should not be allowed to destroy the club’s reputation.","zh":"一宗事件不應被容許破壞學會聲譽。"},{"en":"Should not be allowed to means people must not let something happen.","zh":"Should not be allowed to 指人們不可讓某事發生。"},{"en":"A few careless actions should not be allowed to cancel all future outings.","zh":"少數粗心行動不應被容許取消所有日後外出活動。"},{"en":"Members must act so that one mistake does not control the club’s future.","zh":"會員必須行動，避免一次錯誤控制學會未來。"},{"en":"This phrase expresses firm prevention.","zh":"這個短語表達堅定的預防態度。"}],"source":"2014 Q3.pdf","sourcePage":14},{"front":"from now on","meaning":"從現在起","examples":[{"en":"Members should behave better from now on.","zh":"會員從現在起應表現得更好。"},{"en":"From now on means starting at this moment and continuing into the future.","zh":"From now on 指由這一刻開始並延續到未來。"},{"en":"From now on, members should turn off phones before a performance begins.","zh":"從現在起，會員應在演出開始前關掉電話。"},{"en":"This phrase marks a clear change after a lesson or decision.","zh":"這個短語標示在教訓或決定後的清楚改變。"},{"en":"It is useful when making a promise or rule.","zh":"它適合用於作承諾或定規則。"}],"source":"2014 Q3.pdf","sourcePage":15},{"front":"mature enough to","meaning":"足夠成熟去","examples":[{"en":"The club must show that it is mature enough to honour drama.","zh":"學會必須顯示自己足夠成熟去尊重戲劇。"},{"en":"Mature enough to means responsible and sensible enough to do something properly.","zh":"Mature enough to 指有足夠責任感和判斷力去正確做某事。"},{"en":"Members must be mature enough to admit mistakes without blaming others.","zh":"會員必須足夠成熟去承認錯誤，而不是責怪別人。"},{"en":"A club is mature enough to represent the school when it behaves well under pressure.","zh":"當學會在壓力下仍表現良好，它就足夠成熟去代表學校。"},{"en":"This phrase connects maturity with responsibility.","zh":"這個短語把成熟和責任連接起來。"}],"source":"2014 Q3.pdf","sourcePage":15},{"front":"not only to…, but also to…","meaning":"不僅……而且……","examples":[{"en":"Members should be mature enough not only to perform drama, but also to honour it.","zh":"會員應足夠成熟，不僅能表演戲劇，而且能尊重戲劇。"},{"en":"Not only to…, but also to… adds a second, deeper action to the first.","zh":"Not only to…, but also to… 在第一個行動之外加入第二個更深層行動。"},{"en":"Drama students should learn not only to act, but also to respect the theatre.","zh":"戲劇學生不僅應學會演戲，而且應學會尊重劇場。"},{"en":"This structure shows that performance skills are not enough by themselves.","zh":"這個結構顯示單有表演技巧並不足夠。"},{"en":"It is useful when expanding an idea into a fuller responsibility.","zh":"當要把想法擴展成更完整責任時，這個結構很有用。"}],"source":"2014 Q3.pdf","sourcePage":15},{"front":"honour it","meaning":"尊重它；珍視它","examples":[{"en":"Drama Club members should learn to honour drama.","zh":"戲劇學會會員應學會尊重戲劇。"},{"en":"Honour it means respect and value it through words and actions.","zh":"Honour it 指透過言語和行動尊重並珍視它。"},{"en":"Members honour drama when they behave respectfully as both performers and audience members.","zh":"會員作為表演者和觀眾都表現有禮時，就是尊重戲劇。"},{"en":"Honouring drama means protecting the silence, effort and dignity of live performance.","zh":"尊重戲劇代表保護現場演出的沉默、努力和尊嚴。"},{"en":"This phrase shows deep respect, not casual enjoyment only.","zh":"這個短語顯示深層尊重，而不只是隨便喜歡。"}],"source":"2014 Q3.pdf","sourcePage":15},{"front":"Yours sincerely","meaning":"謹啟","examples":[{"en":"The chairperson ends the email with “Yours sincerely.”","zh":"主席以 “Yours sincerely” 結束電郵。"},{"en":"Yours sincerely is a formal closing used at the end of a letter or email.","zh":"Yours sincerely 是正式信件或電郵結尾使用的署名語。"},{"en":"A student may write “Yours sincerely” before signing a formal complaint or apology letter.","zh":"學生可能在正式投訴信或道歉信簽名前寫上 “Yours sincerely”。"},{"en":"This closing shows politeness and respect for the reader.","zh":"這個結尾語顯示對讀者的禮貌和尊重。"},{"en":"This phrase is common in formal English correspondence.","zh":"這個短語常見於正式英文書信。"}],"source":"2014 Q3.pdf","sourcePage":15},{"front":"Chairperson, Drama Club","meaning":"戲劇學會主席","examples":[{"en":"Chris Wong signs the email as Chairperson of the Drama Club.","zh":"Chris Wong 以戲劇學會主席身份簽署電郵。"},{"en":"Chairperson, Drama Club means the person signing is the leader of the Drama Club.","zh":"Chairperson, Drama Club 指簽署者是戲劇學會的領袖。"},{"en":"Writing a title under a name shows the writer’s role and authority.","zh":"在姓名下寫上職銜，可以顯示作者的角色和權限。"},{"en":"The title helps readers understand why Chris is speaking for the club.","zh":"這個職銜幫助讀者理解 Chris 為何代表學會發言。"},{"en":"This phrase is useful in formal school communication.","zh":"這個短語適合用於正式學校溝通。"}],"source":"2014 Q3.pdf","sourcePage":15}],"dse/writing/part-b/2014/Q4":[{"front":"let cameras roll","meaning":"讓攝影機開拍","examples":[{"en":"The writer believes Hong Kong should let cameras roll with proper rules.","zh":"作者認為香港應在有適當規則下讓攝影機開拍。"},{"en":"To let cameras roll means to allow filming to begin or continue.","zh":"let cameras roll 意思是容許拍攝開始或繼續。"},{"en":"A city can let cameras roll if film crews follow safety rules.","zh":"如果攝製隊遵守安全規則，城市可以讓攝影機開拍。"},{"en":"Letting cameras roll does not mean ignoring residents’ daily lives.","zh":"讓攝影機開拍並不代表忽視居民日常生活。"},{"en":"This phrase suggests support for filming, but not for careless filming.","zh":"這個片語表示支持拍攝，但不是支持草率拍攝。"}],"source":"2014 Q4.pdf","sourcePage":1},{"front":"with rules, not a ban","meaning":"要有規則，而不是禁令","examples":[{"en":"City-centre filming should continue with rules, not a ban.","zh":"市中心拍攝應繼續，但要有規則，而不是禁令。"},{"en":"With rules, not a ban means controlling an activity instead of stopping it completely.","zh":"with rules, not a ban 意思是規管一項活動，而不是完全停止它。"},{"en":"A school may allow phones with rules, not a ban, during special lessons.","zh":"學校可在特別課堂容許使用手機，但要有規則，而不是禁令。"},{"en":"Filming can continue safely with rules, not a total prohibition.","zh":"拍攝可以在有規則下安全繼續，而不是全面禁止。"},{"en":"This phrase shows a balanced position between freedom and control.","zh":"這個片語顯示在自由與控制之間取得平衡的立場。"}],"source":"2014 Q4.pdf","sourcePage":1},{"front":"in response to","meaning":"回應……","examples":[{"en":"The writer is writing in response to the debate about city-centre filming.","zh":"作者寫作是為了回應關於市中心拍攝的爭議。"},{"en":"In response to means because of something that has been said, done, or discussed.","zh":"in response to 意思是因某些說法、行動或討論而作出回應。"},{"en":"A student may write a letter in response to a school policy change.","zh":"學生可能寫信回應學校政策改變。"},{"en":"The article was written in response to residents’ complaints about filming.","zh":"這篇文章是回應居民對拍攝的投訴而寫的。"},{"en":"This phrase clearly explains why the writer is speaking now.","zh":"這個片語清楚解釋作者為何現在發聲。"}],"source":"2014 Q4.pdf","sourcePage":1},{"front":"the debate over whether","meaning":"關於是否……的爭議","examples":[{"en":"There is a debate over whether filming should be prohibited.","zh":"現在有關於是否應禁止拍攝的爭議。"},{"en":"The debate over whether means disagreement about whether something should happen.","zh":"the debate over whether 指關於某事是否應發生的分歧。"},{"en":"There may be a debate over whether cars should be banned from busy streets.","zh":"人們可能就是否應禁止汽車進入繁忙街道產生爭議。"},{"en":"The debate over whether filming should continue involves residents and filmmakers.","zh":"關於拍攝是否應繼續的爭議涉及居民和電影人。"},{"en":"This phrase is useful when introducing two opposing views.","zh":"這個片語適合用來引入兩種相反觀點。"}],"source":"2014 Q4.pdf","sourcePage":1},{"front":"filming movies in the city centre","meaning":"在市中心拍攝電影","examples":[{"en":"Filming movies in the city centre can cause inconvenience.","zh":"在市中心拍攝電影可能造成不便。"},{"en":"Filming movies in the city centre means making film scenes in busy urban areas.","zh":"filming movies in the city centre 意思是在繁忙市區拍攝電影場景。"},{"en":"Filming movies in the city centre may require lights, cameras, actors, and road control.","zh":"在市中心拍攝電影可能需要燈光、攝影機、演員和道路管制。"},{"en":"Such filming can show the real character of a city.","zh":"這種拍攝可以展示城市的真實特色。"},{"en":"It should be planned carefully because many people use city-centre streets every day.","zh":"由於很多人每天使用市中心街道，拍攝應仔細規劃。"}],"source":"2014 Q4.pdf","sourcePage":1},{"front":"be prohibited","meaning":"被禁止","examples":[{"en":"Some residents think filming in the city centre should be prohibited.","zh":"有些居民認為在市中心拍攝應被禁止。"},{"en":"Be prohibited means be officially banned or not allowed.","zh":"be prohibited 意思是被正式禁止或不被容許。"},{"en":"Smoking is prohibited in many indoor public places.","zh":"許多室內公共場所禁止吸煙。"},{"en":"Filming may be prohibited in dangerous areas for safety reasons.","zh":"基於安全理由，危險地區可能禁止拍攝。"},{"en":"This phrase is stronger than “discouraged” because it means the activity cannot happen.","zh":"這個片語比「不鼓勵」更強，因為它表示活動不能進行。"}],"source":"2014 Q4.pdf","sourcePage":1},{"front":"complaints about","meaning":"關於……的投訴","examples":[{"en":"There have been complaints about blocked pavements and traffic diversions.","zh":"已有關於行人路被阻塞和交通改道的投訴。"},{"en":"Complaints about something are expressions of dissatisfaction about a problem.","zh":"complaints about 某事，是指對某問題表達不滿。"},{"en":"Residents may make complaints about noise after midnight.","zh":"居民可能就午夜後的噪音作出投訴。"},{"en":"Complaints about filming should be recorded and handled seriously.","zh":"關於拍攝的投訴應被記錄並認真處理。"},{"en":"This phrase helps identify what people are unhappy with.","zh":"這個片語有助指出人們不滿的是甚麼。"}],"source":"2014 Q4.pdf","sourcePage":1},{"front":"blocked pavements","meaning":"被阻塞的行人路","examples":[{"en":"Blocked pavements can inconvenience pedestrians.","zh":"被阻塞的行人路會令行人不便。"},{"en":"Blocked pavements are footpaths that people cannot use easily because something is in the way.","zh":"blocked pavements 指因有東西阻擋而令人難以使用的行人路。"},{"en":"Film equipment may create blocked pavements if it is placed carelessly.","zh":"如果電影器材放置不當，可能造成行人路被阻塞。"},{"en":"Blocked pavements can be dangerous for elderly people and wheelchair users.","zh":"被阻塞的行人路對長者和輪椅使用者可能有危險。"},{"en":"Keeping pavements clear helps protect daily public movement.","zh":"保持行人路暢通有助保障日常公共通行。"}],"source":"2014 Q4.pdf","sourcePage":1},{"front":"late-night lighting","meaning":"深夜燈光","examples":[{"en":"Late-night lighting from film shoots may disturb residents.","zh":"電影拍攝的深夜燈光可能滋擾居民。"},{"en":"Late-night lighting means bright lights used during the late hours of the night.","zh":"late-night lighting 指深夜時段使用的強烈燈光。"},{"en":"Strong late-night lighting outside flats can make it hard for residents to sleep.","zh":"單位外的強烈深夜燈光可能令居民難以入睡。"},{"en":"Film crews should limit late-night lighting in residential areas.","zh":"攝製隊應限制住宅區的深夜燈光。"},{"en":"This phrase shows how filming can affect people even inside their homes.","zh":"這個片語顯示拍攝如何影響在家中的人。"}],"source":"2014 Q4.pdf","sourcePage":1},{"front":"traffic diversions","meaning":"交通改道","examples":[{"en":"Traffic diversions can affect commuters and shopkeepers.","zh":"交通改道可以影響通勤人士和店主。"},{"en":"Traffic diversions are temporary route changes that move vehicles away from their usual roads.","zh":"traffic diversions 是臨時更改行車路線，使車輛離開平常道路。"},{"en":"A film shoot may require traffic diversions for safety.","zh":"電影拍攝可能基於安全需要而要求交通改道。"},{"en":"Poorly planned diversions can delay buses, taxis, and deliveries.","zh":"規劃不善的改道可能延誤巴士、的士和送貨。"},{"en":"Clear notices help people prepare for traffic diversions.","zh":"清晰告示幫助人們為交通改道作準備。"}],"source":"2014 Q4.pdf","sourcePage":1},{"front":"become more visible","meaning":"變得更明顯","examples":[{"en":"Complaints about filming have become more visible.","zh":"關於拍攝的投訴已變得更明顯。"},{"en":"Become more visible means become easier for people to notice or discuss.","zh":"become more visible 意思是變得更容易被人注意或討論。"},{"en":"A problem becomes more visible when many residents post about it online.","zh":"當很多居民在網上發帖時，問題會變得更明顯。"},{"en":"Complaints became more visible after several streets were blocked for filming.","zh":"多條街道因拍攝被封後，投訴變得更明顯。"},{"en":"This phrase suggests that an issue is gaining public attention.","zh":"這個片語表示某議題正得到公眾關注。"}],"source":"2014 Q4.pdf","sourcePage":2},{"front":"understandably","meaning":"可以理解地","examples":[{"en":"Residents are understandably concerned about noise and disruption.","zh":"居民可以理解地關注噪音和滋擾。"},{"en":"Understandably means in a way that is easy to understand or sympathise with.","zh":"understandably 意思是以容易理解或令人同情的方式。"},{"en":"Understandably, parents worry when a school trip is delayed.","zh":"學校旅行延誤時，家長感到擔心是可以理解的。"},{"en":"Residents are understandably upset if filming keeps them awake at night.","zh":"如果拍攝令居民夜晚不能入睡，他們不滿是可以理解的。"},{"en":"This word shows sympathy before presenting another viewpoint.","zh":"這個字在提出另一觀點前先顯示同理心。"}],"source":"2014 Q4.pdf","sourcePage":2},{"front":"consider a ban","meaning":"考慮禁令","examples":[{"en":"Some residents are considering a ban on city-centre filming.","zh":"有些居民正在考慮對市中心拍攝實施禁令。"},{"en":"To consider a ban means to think about stopping an activity officially.","zh":"consider a ban 意思是考慮正式停止某項活動。"},{"en":"A school may consider a ban if students misuse mobile phones repeatedly.","zh":"如果學生多次濫用手機，學校可能考慮禁令。"},{"en":"Residents may consider a ban when rules seem unable to control disruption.","zh":"當規則似乎無法控制滋擾時，居民可能考慮禁令。"},{"en":"This phrase shows that frustration has become serious.","zh":"這個片語顯示不滿已變得嚴重。"}],"source":"2014 Q4.pdf","sourcePage":2},{"front":"in order to restore","meaning":"為了恢復","examples":[{"en":"Some people want a ban in order to restore convenience and quiet.","zh":"有些人希望實施禁令，為了恢復便利和安寧。"},{"en":"In order to restore means for the purpose of bringing something back.","zh":"in order to restore 意思是為了把某事物恢復過來。"},{"en":"The school changed the timetable in order to restore order after confusion.","zh":"學校改變時間表，為了在混亂後恢復秩序。"},{"en":"Residents may support limits in order to restore quiet at night.","zh":"居民可能支持限制措施，為了恢復晚上的安寧。"},{"en":"This phrase links an action with the thing people hope to recover.","zh":"這個片語把行動與人們希望恢復的事物連接起來。"}],"source":"2014 Q4.pdf","sourcePage":2},{"front":"convenience and quiet","meaning":"便利和安寧","examples":[{"en":"Residents want to restore convenience and quiet in their neighbourhoods.","zh":"居民希望恢復社區的便利和安寧。"},{"en":"Convenience and quiet mean easy daily movement and a peaceful living environment.","zh":"convenience and quiet 指日常出行方便和寧靜的生活環境。"},{"en":"Blocked pavements reduce convenience, while late-night noise reduces quiet.","zh":"行人路被阻塞會減少便利，而深夜噪音會減少安寧。"},{"en":"Residents value convenience and quiet because they affect ordinary life.","zh":"居民重視便利和安寧，因為它們影響日常生活。"},{"en":"Filming rules should protect these needs while allowing creative work.","zh":"拍攝規則應保障這些需要，同時容許創作工作。"}],"source":"2014 Q4.pdf","sourcePage":2},{"front":"a total prohibition","meaning":"全面禁止","examples":[{"en":"A total prohibition would be an overreaction.","zh":"全面禁止會是反應過度。"},{"en":"A total prohibition means a complete ban with no exceptions.","zh":"a total prohibition 指完全禁止，沒有例外。"},{"en":"A total prohibition on filming would stop even well-managed shoots.","zh":"全面禁止拍攝會連管理良好的拍攝也停止。"},{"en":"Total prohibition may solve inconvenience but damage culture and the economy.","zh":"全面禁止可能解決不便，但會損害文化和經濟。"},{"en":"This phrase suggests a very strict response.","zh":"這個片語表示非常嚴厲的回應。"}],"source":"2014 Q4.pdf","sourcePage":2},{"front":"an overreaction","meaning":"反應過度","examples":[{"en":"Banning all filming would be an overreaction.","zh":"禁止所有拍攝會是反應過度。"},{"en":"An overreaction is a response that is stronger than the problem requires.","zh":"overreaction 指回應比問題所需更強烈。"},{"en":"Closing a whole school because one classroom is noisy may be an overreaction.","zh":"只因一間課室嘈吵就關閉整間學校，可能是反應過度。"},{"en":"A filming ban may be an overreaction if better rules can solve the problem.","zh":"如果更好規則能解決問題，拍攝禁令可能是反應過度。"},{"en":"This word criticises a solution as too extreme.","zh":"這個字批評某方案過於極端。"}],"source":"2014 Q4.pdf","sourcePage":2},{"front":"as far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, filming should be allowed under strict rules.","zh":"就我而言，拍攝應在嚴格規則下獲准進行。"},{"en":"As far as I am concerned means in my personal opinion.","zh":"as far as I am concerned 意思是以我個人看法而言。"},{"en":"As far as I am concerned, schools should teach creativity as well as exams.","zh":"就我而言，學校應教授創意，也應重視考試。"},{"en":"This phrase introduces the writer’s position clearly.","zh":"這個片語清楚引出作者立場。"},{"en":"It sounds firm but still personal and respectful.","zh":"它聽起來堅定，但仍屬個人和有禮的表達。"}],"source":"2014 Q4.pdf","sourcePage":2},{"front":"continue to allow","meaning":"繼續容許","examples":[{"en":"Hong Kong should continue to allow film crews to work in central districts.","zh":"香港應繼續容許電影攝製隊在市中心地區工作。"},{"en":"Continue to allow means keep permitting something that is already allowed.","zh":"continue to allow 意思是繼續准許已被容許的事情。"},{"en":"A library may continue to allow group study if students remain quiet.","zh":"如果學生保持安靜，圖書館可繼續容許小組溫習。"},{"en":"Hong Kong can continue to allow filming while tightening permit rules.","zh":"香港可以在收緊許可證規則的同時繼續容許拍攝。"},{"en":"This phrase supports controlled continuation rather than sudden prohibition.","zh":"這個片語支持受控延續，而不是突然禁止。"}],"source":"2014 Q4.pdf","sourcePage":2},{"front":"film crews","meaning":"電影攝製隊；劇組","examples":[{"en":"Film crews should follow strict permit conditions.","zh":"電影攝製隊應遵守嚴格許可證條件。"},{"en":"Film crews are groups of workers who make a film, including camera, lighting, sound, and production staff.","zh":"film crews 指製作電影的工作團隊，包括攝影、燈光、收音和製作人員。"},{"en":"Film crews may need to set up lights, cameras, cables, and props on location.","zh":"電影攝製隊可能需要在外景地架設燈光、攝影機、電線和道具。"},{"en":"Responsible film crews respect residents and clean up after shooting.","zh":"負責任的劇組會尊重居民，並在拍攝後清理地方。"},{"en":"This phrase refers to the people who carry out filming work.","zh":"這個片語指實際執行拍攝工作的人。"}],"source":"2014 Q4.pdf","sourcePage":2},{"front":"central districts","meaning":"市中心地區","examples":[{"en":"Film crews sometimes work in central districts.","zh":"電影攝製隊有時在市中心地區工作。"},{"en":"Central districts are busy city areas with offices, shops, transport, and many pedestrians.","zh":"central districts 指有辦公室、商店、交通和大量行人的繁忙市區。"},{"en":"Central districts often appear in films because they show the city’s energy.","zh":"市中心地區常出現在電影中，因為它們展示城市活力。"},{"en":"Filming in central districts needs careful planning because disruption spreads quickly.","zh":"在市中心地區拍攝需要仔細規劃，因為滋擾很快擴散。"},{"en":"This phrase refers to important urban areas, not quiet remote places.","zh":"這個片語指重要市區，而不是偏遠寧靜地方。"}],"source":"2014 Q4.pdf","sourcePage":3},{"front":"provided that","meaning":"只要；假如","examples":[{"en":"Filming should be allowed, provided that strict rules are enforced.","zh":"只要嚴格規則被執行，拍攝應獲准進行。"},{"en":"Provided that means only if a certain condition is met.","zh":"provided that 意思是只有在某條件符合時才可以。"},{"en":"Students may use the hall, provided that they keep it clean.","zh":"學生可以使用禮堂，前提是保持清潔。"},{"en":"Film crews may work at night, provided that residents are informed and noise is limited.","zh":"只要通知居民並限制噪音，劇組可在夜間工作。"},{"en":"This phrase adds a clear condition to permission.","zh":"這個片語為許可加入清晰條件。"}],"source":"2014 Q4.pdf","sourcePage":3},{"front":"strict permits","meaning":"嚴格許可證","examples":[{"en":"Strict permits can reduce the disruption caused by filming.","zh":"嚴格許可證可以減少拍攝造成的滋擾。"},{"en":"Strict permits are official permissions with clear and firm conditions.","zh":"strict permits 是附有清晰而嚴格條件的官方許可。"},{"en":"A strict permit may limit filming hours, noise, road use, and clean-up duties.","zh":"嚴格許可證可能限制拍攝時間、噪音、道路使用和清理責任。"},{"en":"Without strict permits, film crews may cause more disruption than necessary.","zh":"沒有嚴格許可證，劇組可能造成不必要的滋擾。"},{"en":"This phrase shows how regulation can replace a ban.","zh":"這個片語顯示規管如何取代禁令。"}],"source":"2014 Q4.pdf","sourcePage":3},{"front":"time limits","meaning":"時間限制","examples":[{"en":"Time limits should be imposed on film shoots.","zh":"電影拍攝應設時間限制。"},{"en":"Time limits are rules about when an activity may start and must end.","zh":"time limits 是關於活動何時可開始和必須結束的規則。"},{"en":"A permit may set time limits so filming does not continue all night.","zh":"許可證可設定時間限制，避免拍攝整夜持續。"},{"en":"Time limits protect residents’ sleep and commuters’ daily routines.","zh":"時間限制保障居民睡眠和通勤人士日常安排。"},{"en":"This phrase describes a practical way to control disruption.","zh":"這個片語描述控制滋擾的實際方法。"}],"source":"2014 Q4.pdf","sourcePage":3},{"front":"public notices","meaning":"公眾告示","examples":[{"en":"Public notices should inform residents before filming begins.","zh":"公眾告示應在拍攝開始前通知居民。"},{"en":"Public notices are written announcements shown to people in a public area.","zh":"public notices 是在公共地方展示給人們看的書面公告。"},{"en":"A public notice may tell residents when a road will be closed for filming.","zh":"公眾告示可告知居民某條道路何時因拍攝而封閉。"},{"en":"Clear notices help shops and commuters plan ahead.","zh":"清晰告示幫助商店和通勤人士提前安排。"},{"en":"This phrase shows the importance of informing people before disruption happens.","zh":"這個片語顯示滋擾發生前通知公眾的重要性。"}],"source":"2014 Q4.pdf","sourcePage":3},{"front":"be enforced","meaning":"被執行","examples":[{"en":"Strict permits, time limits and public notices must be enforced.","zh":"嚴格許可證、時間限制和公眾告示必須被執行。"},{"en":"Be enforced means be made effective by checking and requiring people to obey.","zh":"be enforced 意思是透過檢查和要求人們遵守，使規則生效。"},{"en":"Parking rules mean little if they are not enforced.","zh":"如果泊車規則不被執行，便意義不大。"},{"en":"Filming rules must be enforced so crews cannot ignore residents.","zh":"拍攝規則必須被執行，劇組才不能忽視居民。"},{"en":"This phrase shows that rules need action, not just words.","zh":"這個片語顯示規則需要行動，而不只是文字。"}],"source":"2014 Q4.pdf","sourcePage":3},{"front":"my view rests on three reasons","meaning":"我的觀點基於三個原因","examples":[{"en":"The writer’s view rests on three reasons.","zh":"作者的觀點基於三個原因。"},{"en":"My view rests on three reasons means my opinion is supported by three main points.","zh":"my view rests on three reasons 意思是我的意見由三個主要重點支持。"},{"en":"A debate speech may say, “My view rests on three reasons” before explaining them.","zh":"辯論演講可能在解釋前說：「我的觀點基於三個原因。」"},{"en":"This phrase helps organise an argument clearly.","zh":"這個片語幫助清楚組織論點。"},{"en":"It tells readers that the opinion is not random but reasoned.","zh":"它告訴讀者，意見不是隨意的，而是有理據的。"}],"source":"2014 Q4.pdf","sourcePage":3},{"front":"cultural identity","meaning":"文化身份","examples":[{"en":"City-centre filming can strengthen Hong Kong’s cultural identity.","zh":"市中心拍攝可以加強香港的文化身份。"},{"en":"Cultural identity is the sense of belonging created by shared language, places, history, and habits.","zh":"cultural identity 指由共同語言、地方、歷史和習慣形成的歸屬感。"},{"en":"Films can show cultural identity through streets, food, accents, and daily life.","zh":"電影可以透過街道、食物、口音和日常生活展示文化身份。"},{"en":"If local places disappear from films, cultural identity may become less visible.","zh":"如果本地地方從電影中消失，文化身份可能變得不明顯。"},{"en":"This phrase explains why filming can matter beyond entertainment.","zh":"這個片語解釋為何拍攝不只是娛樂。"}],"source":"2014 Q4.pdf","sourcePage":3},{"front":"support the local economy","meaning":"支持本地經濟","examples":[{"en":"Film production can support the local economy.","zh":"電影製作可以支持本地經濟。"},{"en":"To support the local economy means to help local jobs, shops, and businesses earn money.","zh":"support the local economy 意思是幫助本地職位、商店和企業賺取收入。"},{"en":"A film shoot may support the local economy by hiring caterers and security staff.","zh":"電影拍攝可透過聘請膳食供應商和保安人員支持本地經濟。"},{"en":"Nearby cafés can benefit when crews buy meals during filming.","zh":"劇組拍攝期間購買餐飲，附近咖啡店可以受惠。"},{"en":"This phrase shows the practical financial value of filming.","zh":"這個片語顯示拍攝的實際經濟價值。"}],"source":"2014 Q4.pdf","sourcePage":3},{"front":"be regulated without sacrificing","meaning":"可被規管而不犧牲……","examples":[{"en":"Filming can be regulated without sacrificing public order.","zh":"拍攝可以被規管，而不犧牲公共秩序。"},{"en":"Be regulated without sacrificing something means be controlled while still protecting that thing.","zh":"be regulated without sacrificing something 意思是在控制某活動的同時保護某事。"},{"en":"Outdoor events can be regulated without sacrificing public safety.","zh":"戶外活動可以被規管，而不犧牲公共安全。"},{"en":"Filming can be controlled by permits without destroying artistic freedom.","zh":"拍攝可透過許可證控制，而不破壞藝術自由。"},{"en":"This phrase shows that balance is possible.","zh":"這個片語顯示平衡是可能的。"}],"source":"2014 Q4.pdf","sourcePage":3},{"front":"public order","meaning":"公共秩序","examples":[{"en":"Clear rules can protect public order during filming.","zh":"清晰規則可以在拍攝期間保護公共秩序。"},{"en":"Public order means peace, safety, and normal behaviour in public places.","zh":"public order 指公共地方的安寧、安全和正常運作。"},{"en":"Police and transport officers help maintain public order during large events.","zh":"警方和交通人員在大型活動期間協助維持公共秩序。"},{"en":"Filming should not block emergency access or create unsafe crowds.","zh":"拍攝不應阻塞緊急通道或造成不安全人群。"},{"en":"This phrase focuses on keeping the city functioning properly.","zh":"這個片語著重令城市正常運作。"}],"source":"2014 Q4.pdf","sourcePage":4},{"front":"to begin with","meaning":"首先","examples":[{"en":"To begin with, filming helps preserve Hong Kong’s identity.","zh":"首先，拍攝有助保存香港身份。"},{"en":"To begin with means first of all, before giving other points.","zh":"to begin with 意思是首先，在提出其他重點之前。"},{"en":"To begin with, students need clear goals before choosing a course.","zh":"首先，學生選科前需要清晰目標。"},{"en":"This phrase introduces the first reason in an argument.","zh":"這個片語引出論點中的第一個原因。"},{"en":"It helps readers follow the order of the writer’s ideas.","zh":"它幫助讀者跟上作者思路次序。"}],"source":"2014 Q4.pdf","sourcePage":4},{"front":"in the heart of the city","meaning":"在城市中心","examples":[{"en":"Filming in the heart of the city shows Hong Kong’s character.","zh":"在城市中心拍攝展示香港特色。"},{"en":"In the heart of the city means in the most central and lively part of the city.","zh":"in the heart of the city 指在城市最中心和最有活力的部分。"},{"en":"A scene filmed in the heart of the city can show crowds, lights, and movement.","zh":"在城市中心拍攝的場景可以展示人群、燈光和流動。"},{"en":"The heart of the city often carries its strongest identity.","zh":"城市中心往往承載最強的身份特色。"},{"en":"This phrase makes the location sound important and symbolic.","zh":"這個片語令地點聽起來重要且有象徵意義。"}],"source":"2014 Q4.pdf","sourcePage":4},{"front":"preserve and project","meaning":"保存並展示","examples":[{"en":"Films can preserve and project Hong Kong’s identity.","zh":"電影可以保存並展示香港身份。"},{"en":"To preserve and project means to protect something and show it to others.","zh":"preserve and project 意思是保護某事，並把它展示給他人。"},{"en":"Museums preserve culture, while exhibitions project it to the public.","zh":"博物館保存文化，而展覽則向公眾展示文化。"},{"en":"Films preserve street memories and project them to overseas viewers.","zh":"電影保存街道記憶，並向海外觀眾展示它們。"},{"en":"This phrase joins protection with communication.","zh":"這個片語把保護與傳達連結起來。"}],"source":"2014 Q4.pdf","sourcePage":4},{"front":"not merely entertainment","meaning":"不僅僅是娛樂","examples":[{"en":"A film is not merely entertainment.","zh":"電影不僅僅是娛樂。"},{"en":"Not merely entertainment means not only something that amuses people.","zh":"not merely entertainment 意思是不只是令人消遣的東西。"},{"en":"A film can entertain viewers and also record a city’s way of life.","zh":"電影可以娛樂觀眾，也可以記錄城市生活方式。"},{"en":"Documentaries are not merely entertainment because they can teach and preserve memory.","zh":"紀錄片不僅僅是娛樂，因為它們可以教育人並保存記憶。"},{"en":"This phrase argues that film has cultural value.","zh":"這個片語主張電影有文化價值。"}],"source":"2014 Q4.pdf","sourcePage":4},{"front":"rather","meaning":"而是","examples":[{"en":"A film is not merely entertainment; rather, it records how a place feels.","zh":"電影不僅僅是娛樂；而是記錄一個地方的感覺。"},{"en":"Rather is used to correct or replace one idea with a more accurate one.","zh":"rather 用來修正或取代一個想法，提出更準確說法。"},{"en":"The issue is not whether filming is noisy; rather, it is whether noise can be managed.","zh":"問題不是拍攝是否嘈吵；而是噪音能否被管理。"},{"en":"This word helps shift from a weaker idea to a stronger explanation.","zh":"這個字幫助由較弱想法轉向較強解釋。"},{"en":"It is useful when clarifying what something truly means.","zh":"當澄清某事真正意思時，它很有用。"}],"source":"2014 Q4.pdf","sourcePage":4},{"front":"a visual record of","meaning":"……的視覺紀錄","examples":[{"en":"A film can be a visual record of a city.","zh":"電影可以是一個城市的視覺紀錄。"},{"en":"A visual record of something is an image-based record that preserves how it looked.","zh":"a visual record of something 指以影像保存某物外觀的紀錄。"},{"en":"Old photographs are a visual record of past street life.","zh":"舊相片是過去街道生活的視覺紀錄。"},{"en":"Films can become a visual record of Hong Kong’s buildings, crowds, and lights.","zh":"電影可以成為香港建築、人群和燈光的視覺紀錄。"},{"en":"This phrase explains how film can preserve memory.","zh":"這個片語解釋電影如何保存記憶。"}],"source":"2014 Q4.pdf","sourcePage":4},{"front":"how a place feels, moves and breathes","meaning":"一個地方的感覺、流動和生命力","examples":[{"en":"Film can show how a place feels, moves and breathes.","zh":"電影可以展示一個地方的感覺、流動和生命力。"},{"en":"This phrase means film can capture a place’s mood, activity, and life.","zh":"這個片語意思是電影能捕捉地方的氣氛、活動和生活感。"},{"en":"A market scene can show how a neighbourhood feels, moves and breathes.","zh":"街市場景可以展示社區的感覺、流動和生命力。"},{"en":"Studio sets may look similar but cannot fully show real street life.","zh":"攝影棚佈景可能看似相似，但不能完全展示真實街道生活。"},{"en":"The phrase makes a city sound alive, not just physical.","zh":"這個片語令城市聽起來有生命，而不只是實體空間。"}],"source":"2014 Q4.pdf","sourcePage":4},{"front":"be shot beside","meaning":"在……旁邊拍攝","examples":[{"en":"A scene may be shot beside a tram stop in Central.","zh":"場景可能在中環一個電車站旁邊拍攝。"},{"en":"Be shot beside means be filmed next to a particular place or object.","zh":"be shot beside 意思是在某地方或物件旁邊拍攝。"},{"en":"A scene may be shot beside a harbour to show the city’s view.","zh":"場景可能在海港旁邊拍攝，以展示城市景色。"},{"en":"Shooting beside real landmarks can make a film feel authentic.","zh":"在真實地標旁邊拍攝可以令電影更真實。"},{"en":"This phrase describes the location of a film scene.","zh":"這個片語描述電影場景的位置。"}],"source":"2014 Q4.pdf","sourcePage":4},{"front":"tram stop","meaning":"電車站","examples":[{"en":"A tram stop in Central can become part of a film scene.","zh":"中環的電車站可以成為電影場景的一部分。"},{"en":"A tram stop is a place where passengers wait for and board trams.","zh":"tram stop 是乘客等候和乘搭電車的地方。"},{"en":"A tram stop can show daily transport and local street life.","zh":"電車站可以展示日常交通和本地街道生活。"},{"en":"Filming near a tram stop may need crowd and traffic control.","zh":"在電車站附近拍攝可能需要人流和交通管制。"},{"en":"This detail gives the scene a recognisably Hong Kong feeling.","zh":"這個細節令場景帶有一眼可辨的香港感覺。"}],"source":"2014 Q4.pdf","sourcePage":4},{"front":"under the neon glow of","meaning":"在……霓虹光影下","examples":[{"en":"A scene may be filmed under the neon glow of Mong Kok.","zh":"場景可能在旺角的霓虹光影下拍攝。"},{"en":"Under the neon glow of a place means in the coloured light from its neon signs.","zh":"under the neon glow of 某地，意思是在該地霓虹招牌的彩色光線下。"},{"en":"A night scene under the neon glow of a busy street can feel energetic.","zh":"繁忙街道霓虹光影下的夜景可以感覺充滿活力。"},{"en":"Neon light can create a strong local atmosphere in films.","zh":"霓虹燈可以在電影中創造強烈本地氣氛。"},{"en":"This phrase helps readers picture the lighting and mood of a scene.","zh":"這個片語幫助讀者想像場景的燈光和氣氛。"}],"source":"2014 Q4.pdf","sourcePage":5},{"front":"the neon glow","meaning":"霓虹光影","examples":[{"en":"The neon glow of Mong Kok gives films a local atmosphere.","zh":"旺角的霓虹光影給電影帶來本地氣氛。"},{"en":"The neon glow is the colourful light produced by neon signs.","zh":"neon glow 指霓虹招牌產生的彩色光線。"},{"en":"The neon glow above shopfronts can make a street look lively at night.","zh":"店舖上方的霓虹光影可令街道在夜間顯得熱鬧。"},{"en":"Films use the neon glow to show the energy of Hong Kong streets.","zh":"電影使用霓虹光影來展示香港街道活力。"},{"en":"This phrase connects lighting with cultural mood.","zh":"這個片語把燈光與文化氣氛連接起來。"}],"source":"2014 Q4.pdf","sourcePage":5},{"front":"near the harbour","meaning":"在海港附近","examples":[{"en":"A scene may be filmed near the harbour in Tsim Sha Tsui.","zh":"場景可能在尖沙咀海港附近拍攝。"},{"en":"Near the harbour means close to the water area where boats and ships can be seen.","zh":"near the harbour 意思是在可看見船隻和海面的水域附近。"},{"en":"A harbour scene can show Hong Kong’s skyline and sea traffic.","zh":"海港場景可以展示香港天際線和海上交通。"},{"en":"Filming near the harbour may attract visitors and passers-by.","zh":"在海港附近拍攝可能吸引遊客和路人。"},{"en":"This phrase gives the film a strong sense of place.","zh":"這個片語令電影有強烈地方感。"}],"source":"2014 Q4.pdf","sourcePage":5},{"front":"become part of the story","meaning":"成為故事的一部分","examples":[{"en":"The city itself becomes part of the story.","zh":"城市本身成為故事的一部分。"},{"en":"Become part of the story means become an important element that shapes the film’s meaning.","zh":"become part of the story 意思是成為塑造電影意義的重要元素。"},{"en":"A school can become part of the story if the plot is about student life.","zh":"如果情節關於學生生活，學校可以成為故事的一部分。"},{"en":"Hong Kong’s streets become part of the story when characters move through them.","zh":"當角色穿梭香港街道時，這些街道便成為故事的一部分。"},{"en":"This phrase shows that location can be more than background.","zh":"這個片語顯示地點不只是背景。"}],"source":"2014 Q4.pdf","sourcePage":5},{"front":"studio sets","meaning":"攝影棚佈景","examples":[{"en":"Studio sets may imitate streets, but they rarely feel real.","zh":"攝影棚佈景可能模仿街道，但很少有真實感。"},{"en":"Studio sets are artificial places built indoors or in studios for filming.","zh":"studio sets 是在室內或攝影棚中為拍攝建造的人造場景。"},{"en":"A studio set can copy a street corner, café, or flat.","zh":"攝影棚佈景可以複製街角、咖啡店或單位。"},{"en":"Studio sets are useful, but they may lack the energy of real locations.","zh":"攝影棚佈景有用，但可能缺乏真實地點的活力。"},{"en":"This phrase contrasts controlled filming spaces with real city streets.","zh":"這個片語把受控拍攝空間與真實城市街道作對比。"}],"source":"2014 Q4.pdf","sourcePage":5},{"front":"imitate streets","meaning":"模仿街道","examples":[{"en":"Studio sets may imitate streets in Hong Kong.","zh":"攝影棚佈景可能模仿香港街道。"},{"en":"To imitate streets means to copy the appearance of real roads, shops, and public spaces.","zh":"imitate streets 意思是複製真實道路、商店和公共空間的外觀。"},{"en":"A film set may imitate streets by using fake signs and shopfronts.","zh":"電影佈景可透過假招牌和店面來模仿街道。"},{"en":"Imitation can look convincing, but it may miss real crowds and movement.","zh":"模仿可以看似逼真，但可能缺少真實人群和流動。"},{"en":"This phrase shows the difference between copying and truly capturing a place.","zh":"這個片語顯示複製與真正捕捉地方之間的差別。"}],"source":"2014 Q4.pdf","sourcePage":5},{"front":"rarely capture","meaning":"很少能捕捉","examples":[{"en":"Studio sets rarely capture the energy of real streets.","zh":"攝影棚佈景很少能捕捉真實街道的活力。"},{"en":"Rarely capture means usually fail to show or express something fully.","zh":"rarely capture 意思是通常未能完整展示或表達某事。"},{"en":"A photograph may rarely capture the noise and smell of a market.","zh":"相片很少能捕捉街市的聲音和氣味。"},{"en":"Fake streets rarely capture the speed and pressure of Hong Kong life.","zh":"假街道很少能捕捉香港生活的速度和壓力。"},{"en":"This phrase explains why real locations matter.","zh":"這個片語解釋為何真實地點重要。"}],"source":"2014 Q4.pdf","sourcePage":5},{"front":"impatient footsteps","meaning":"匆忙的腳步","examples":[{"en":"Real streets contain the impatient footsteps of the city.","zh":"真實街道包含城市中匆忙的腳步。"},{"en":"Impatient footsteps suggest people walking quickly because they are busy or in a hurry.","zh":"impatient footsteps 表示人們因忙碌或趕時間而快速步行。"},{"en":"Morning commuters’ impatient footsteps can show the rhythm of city life.","zh":"早上通勤人士匆忙的腳步可以展示城市生活節奏。"},{"en":"A film captures impatient footsteps better on a real street than in a studio.","zh":"電影在真實街道上比在攝影棚中更能捕捉匆忙腳步。"},{"en":"This phrase turns ordinary walking into a symbol of urban energy.","zh":"這個片語把普通步行變成城市活力的象徵。"}],"source":"2014 Q4.pdf","sourcePage":5},{"front":"crowded crossings","meaning":"擁擠的過路處","examples":[{"en":"Crowded crossings are part of Hong Kong’s street life.","zh":"擁擠的過路處是香港街道生活的一部分。"},{"en":"Crowded crossings are busy places where many pedestrians cross the road.","zh":"crowded crossings 是很多行人橫過馬路的繁忙地點。"},{"en":"A crowded crossing can show how fast and dense city life feels.","zh":"擁擠的過路處可以展示城市生活的速度和密度。"},{"en":"Filming at crowded crossings needs careful crowd and traffic control.","zh":"在擁擠的過路處拍攝需要仔細人流和交通管制。"},{"en":"This phrase creates a clear image of a busy urban centre.","zh":"這個片語創造繁忙市中心的清晰畫面。"}],"source":"2014 Q4.pdf","sourcePage":5},{"front":"vertical skyline","meaning":"垂直天際線","examples":[{"en":"Hong Kong’s vertical skyline makes the city unmistakable.","zh":"香港的垂直天際線令這座城市一眼可辨。"},{"en":"A vertical skyline is a city view shaped by many tall buildings.","zh":"vertical skyline 指由許多高樓形成的城市景觀。"},{"en":"Hong Kong’s vertical skyline can be seen from the harbour.","zh":"香港的垂直天際線可以從海港看到。"},{"en":"Films use the skyline to show the city’s density and ambition.","zh":"電影使用天際線來展示城市的密度和抱負。"},{"en":"This phrase points to one of Hong Kong’s most recognisable features.","zh":"這個片語指出香港最易辨認的特色之一。"}],"source":"2014 Q4.pdf","sourcePage":5},{"front":"make Hong Kong unmistakable","meaning":"令香港一眼可辨","examples":[{"en":"The vertical skyline makes Hong Kong unmistakable.","zh":"垂直天際線令香港一眼可辨。"},{"en":"To make Hong Kong unmistakable means to make the city clearly recognisable and impossible to confuse with another place.","zh":"make Hong Kong unmistakable 意思是令香港清楚可辨，不能與其他地方混淆。"},{"en":"Trams, harbour views, and dense streets can make Hong Kong unmistakable on screen.","zh":"電車、海港景色和密集街道可令銀幕上的香港一眼可辨。"},{"en":"Real filming locations help make Hong Kong unmistakable to overseas viewers.","zh":"真實拍攝地點幫助海外觀眾一眼辨認香港。"},{"en":"This phrase shows the value of visual identity.","zh":"這個片語顯示視覺身份的價值。"}],"source":"2014 Q4.pdf","sourcePage":6},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, these images travel beyond the cinema.","zh":"更重要的是，這些影像會傳到戲院以外。"},{"en":"More importantly introduces a point that matters even more than the previous one.","zh":"more importantly 用來引出比前一點更重要的重點。"},{"en":"Local filming is beautiful; more importantly, it shares Hong Kong with the world.","zh":"本地拍攝很美；更重要的是，它把香港分享給世界。"},{"en":"This phrase tells readers to pay special attention to the next idea.","zh":"這個片語提醒讀者特別注意下一個想法。"},{"en":"It helps the writer strengthen the argument.","zh":"它幫助作者加強論點。"}],"source":"2014 Q4.pdf","sourcePage":6},{"front":"travel far beyond","meaning":"傳到遠遠超出……的地方","examples":[{"en":"Images of Hong Kong travel far beyond the cinema.","zh":"香港影像會傳到遠遠超出戲院的地方。"},{"en":"Travel far beyond means reach places or audiences much wider than the original setting.","zh":"travel far beyond 意思是到達比原本場景更廣的地方或觀眾。"},{"en":"A film scene can travel far beyond the city when it is shared online.","zh":"電影場景在網上分享後，可以傳到遠遠超出城市的地方。"},{"en":"Images of local streets may travel beyond Hong Kong and attract overseas viewers.","zh":"本地街道影像可能傳出香港，吸引海外觀眾。"},{"en":"This phrase shows how film can spread cultural identity.","zh":"這個片語顯示電影如何傳播文化身份。"}],"source":"2014 Q4.pdf","sourcePage":6},{"front":"a viewer overseas","meaning":"海外觀眾","examples":[{"en":"A viewer overseas may become curious about Hong Kong.","zh":"海外觀眾可能對香港產生好奇。"},{"en":"A viewer overseas is someone in another country or place who watches the film.","zh":"a viewer overseas 指在另一個國家或地方觀看電影的人。"},{"en":"A viewer overseas may first learn about Hong Kong through a movie scene.","zh":"海外觀眾可能第一次透過電影場景認識香港。"},{"en":"If the city looks vivid on screen, overseas viewers may want to know more.","zh":"如果城市在銀幕上顯得生動，海外觀眾可能想了解更多。"},{"en":"This phrase shows how local filming can reach international audiences.","zh":"這個片語顯示本地拍攝如何接觸國際觀眾。"}],"source":"2014 Q4.pdf","sourcePage":6},{"front":"become curious about","meaning":"對……產生好奇","examples":[{"en":"Films can make overseas viewers curious about Hong Kong.","zh":"電影可以令海外觀眾對香港產生好奇。"},{"en":"To become curious about something means to start wanting to know more about it.","zh":"become curious about 意思是開始想了解更多關於某事的內容。"},{"en":"A food documentary may make viewers curious about another culture.","zh":"美食紀錄片可能令觀眾對另一種文化產生好奇。"},{"en":"Seeing Hong Kong’s streets in a film may make people curious about the real city.","zh":"在電影中看見香港街道，可能令人對真實城市產生好奇。"},{"en":"This phrase shows how interest can begin through images.","zh":"這個片語顯示興趣如何透過影像開始。"}],"source":"2014 Q4.pdf","sourcePage":6},{"front":"the city behind the story","meaning":"故事背後的城市","examples":[{"en":"Viewers may become curious about the city behind the story.","zh":"觀眾可能對故事背後的城市產生好奇。"},{"en":"The city behind the story means the real place that gives the film its setting and atmosphere.","zh":"the city behind the story 指給電影提供背景和氣氛的真實地方。"},{"en":"After watching a film, viewers may search for the city behind the story.","zh":"看完電影後，觀眾可能搜尋故事背後的城市。"},{"en":"A strong location can make people remember both the plot and the place.","zh":"有力地點可以令人記得情節，也記得地方。"},{"en":"This phrase links storytelling with urban identity.","zh":"這個片語把敘事與城市身份連接起來。"}],"source":"2014 Q4.pdf","sourcePage":6},{"front":"forbid filming","meaning":"禁止拍攝","examples":[{"en":"To forbid filming in these places would limit local filmmakers.","zh":"禁止在這些地方拍攝會限制本地電影人。"},{"en":"To forbid filming means to officially stop people from shooting scenes.","zh":"forbid filming 意思是正式阻止人們拍攝場景。"},{"en":"A museum may forbid filming to protect fragile objects.","zh":"博物館可能為保護易碎物品而禁止拍攝。"},{"en":"Forbidding filming in central districts would remove important local settings.","zh":"禁止在市中心地區拍攝會移除重要本地場景。"},{"en":"This phrase suggests a strict restriction on creative work.","zh":"這個片語表示對創作工作的嚴格限制。"}],"source":"2014 Q4.pdf","sourcePage":6},{"front":"in effect","meaning":"實際上","examples":[{"en":"To forbid filming is, in effect, to hide Hong Kong’s face.","zh":"禁止拍攝實際上就是隱藏香港的面貌。"},{"en":"In effect means in practical result, even if not stated directly.","zh":"in effect 意思是在實際結果上，即使沒有直接說明。"},{"en":"Closing public spaces to artists is, in effect, limiting cultural expression.","zh":"對藝術家關閉公共空間，實際上是在限制文化表達。"},{"en":"A filming ban may, in effect, reduce Hong Kong’s visibility in films.","zh":"拍攝禁令實際上可能減少香港在電影中的可見度。"},{"en":"This phrase explains the real consequence of an action.","zh":"這個片語解釋行動的真正後果。"}],"source":"2014 Q4.pdf","sourcePage":6},{"front":"tell filmmakers to hide","meaning":"叫電影人隱藏","examples":[{"en":"A ban would tell filmmakers to hide the face of Hong Kong.","zh":"禁令會叫電影人隱藏香港的面貌。"},{"en":"To tell filmmakers to hide something means to force them not to show it in their work.","zh":"tell filmmakers to hide something 意思是迫使電影人在作品中不展示某物。"},{"en":"If street filming is banned, filmmakers may have to hide real urban life.","zh":"如果街道拍攝被禁止，電影人可能不得不隱藏真實城市生活。"},{"en":"This phrase suggests that a ban limits what artists can honestly show.","zh":"這個片語表示禁令限制藝術家誠實展示的內容。"},{"en":"It makes the cultural cost of prohibition easy to understand.","zh":"它令禁止帶來的文化代價容易理解。"}],"source":"2014 Q4.pdf","sourcePage":6},{"front":"the very face of Hong Kong","meaning":"香港最具代表性的面貌","examples":[{"en":"The city centre is the very face of Hong Kong.","zh":"市中心是香港最具代表性的面貌。"},{"en":"The very face of Hong Kong means the most recognisable image or character of Hong Kong.","zh":"the very face of Hong Kong 指香港最易辨認的形象或特色。"},{"en":"The harbour, trams, neon streets, and skyline form part of Hong Kong’s face.","zh":"海港、電車、霓虹街道和天際線構成香港面貌的一部分。"},{"en":"If films cannot show these places, Hong Kong’s face becomes less visible.","zh":"如果電影不能展示這些地方，香港的面貌便變得不明顯。"},{"en":"This phrase makes the city centre sound culturally important.","zh":"這個片語令市中心聽起來具有文化重要性。"}],"source":"2014 Q4.pdf","sourcePage":6},{"front":"blank space","meaning":"空白位置","examples":[{"en":"The city centre should not become a blank space in local films.","zh":"市中心不應成為本地電影中的空白位置。"},{"en":"A blank space means an empty or missing part where something meaningful should appear.","zh":"blank space 指本應有意義地出現卻空缺或缺失的部分。"},{"en":"If real streets are absent from films, they become a blank space in cultural memory.","zh":"如果真實街道從電影中消失，它們會成為文化記憶中的空白位置。"},{"en":"A city centre should not disappear from its own stories.","zh":"城市中心不應從自己的故事中消失。"},{"en":"This phrase shows the loss caused by exclusion.","zh":"這個片語顯示排除帶來的損失。"}],"source":"2014 Q4.pdf","sourcePage":7},{"front":"in our own imagination","meaning":"在我們自己的想像中","examples":[{"en":"The city centre should not become a blank space in our own imagination.","zh":"市中心不應在我們自己的想像中成為空白位置。"},{"en":"In our own imagination means in the way we picture and understand our city.","zh":"in our own imagination 意思是在我們想像和理解自己城市的方式中。"},{"en":"Films help shape what a place looks like in our imagination.","zh":"電影幫助塑造地方在我們想像中的樣子。"},{"en":"If local places are never filmed, they may fade from our imagination.","zh":"如果本地地方從未被拍攝，它們可能從我們想像中淡去。"},{"en":"This phrase connects public space with cultural memory.","zh":"這個片語把公共空間與文化記憶連接起來。"}],"source":"2014 Q4.pdf","sourcePage":7},{"front":"practical economic benefits","meaning":"實際經濟利益","examples":[{"en":"Allowing filming brings practical economic benefits.","zh":"容許拍攝帶來實際經濟利益。"},{"en":"Practical economic benefits are real financial advantages for workers and businesses.","zh":"practical economic benefits 指給工人和企業帶來的真實財政好處。"},{"en":"A film shoot may bring practical economic benefits to cafés, taxis, and equipment suppliers.","zh":"電影拍攝可能為咖啡店、的士和器材供應商帶來實際經濟利益。"},{"en":"These benefits matter because creative workers need paid opportunities.","zh":"這些好處重要，因為創意工作者需要有薪機會。"},{"en":"This phrase shifts the argument from culture to money and jobs.","zh":"這個片語把論點由文化轉向金錢和工作。"}],"source":"2014 Q4.pdf","sourcePage":7},{"front":"a movie shoot","meaning":"電影拍攝","examples":[{"en":"A movie shoot may look like a temporary nuisance.","zh":"電影拍攝可能看起來像暫時滋擾。"},{"en":"A movie shoot is the period or event when scenes for a film are being recorded.","zh":"movie shoot 指拍攝電影場景的一段時間或活動。"},{"en":"A movie shoot may involve actors, cameras, lights, and road arrangements.","zh":"電影拍攝可能涉及演員、攝影機、燈光和道路安排。"},{"en":"Although a movie shoot can disturb people briefly, it can also create work.","zh":"雖然電影拍攝可能短暫滋擾人們，但也可以創造工作。"},{"en":"This phrase refers to the actual filming activity.","zh":"這個片語指實際拍攝活動。"}],"source":"2014 Q4.pdf","sourcePage":7},{"front":"temporary nuisance","meaning":"暫時滋擾","examples":[{"en":"A film shoot may cause temporary nuisance.","zh":"電影拍攝可能造成暫時滋擾。"},{"en":"Temporary nuisance means short-term disturbance or inconvenience.","zh":"temporary nuisance 指短期滋擾或不便。"},{"en":"Road works may be a temporary nuisance if they last only a few days.","zh":"如果道路工程只持續數天，它可能是暫時滋擾。"},{"en":"Filming can be a temporary nuisance when lights or crowds block streets.","zh":"當燈光或人群阻塞街道時，拍攝可能造成暫時滋擾。"},{"en":"This phrase admits the problem while suggesting it may be limited.","zh":"這個片語承認問題，同時表示它可能有限。"}],"source":"2014 Q4.pdf","sourcePage":7},{"front":"behind the camera stand","meaning":"鏡頭背後有……","examples":[{"en":"Behind the camera stand many workers earning a living.","zh":"鏡頭背後有許多靠此謀生的工作者。"},{"en":"Behind the camera stand means hidden behind the visible filming are real people doing work.","zh":"behind the camera stand 意思是在可見拍攝背後，有真實的人在工作。"},{"en":"Behind the camera stand technicians, drivers, caterers, and assistants.","zh":"鏡頭背後有技術員、司機、膳食供應商和助理。"},{"en":"Viewers may see actors, but behind the camera stand many workers.","zh":"觀眾可能看到演員，但鏡頭背後有許多工作者。"},{"en":"This phrase reminds readers that filming supports jobs.","zh":"這個片語提醒讀者拍攝支持就業。"}],"source":"2014 Q4.pdf","sourcePage":7},{"front":"lighting technicians","meaning":"燈光技術員","examples":[{"en":"Lighting technicians earn a living from film projects.","zh":"燈光技術員靠電影項目謀生。"},{"en":"Lighting technicians are workers who set up and control lights for filming.","zh":"lighting technicians 是為拍攝設置和控制燈光的工作者。"},{"en":"They help make actors visible and create the mood of a scene.","zh":"他們幫助演員清楚可見，並創造場景氣氛。"},{"en":"A night shoot depends on skilled lighting technicians.","zh":"夜間拍攝依賴熟練的燈光技術員。"},{"en":"This phrase names one group of workers supported by film production.","zh":"這個片語指出電影製作支持的一類工作者。"}],"source":"2014 Q4.pdf","sourcePage":7},{"front":"make-up artists","meaning":"化妝師","examples":[{"en":"Make-up artists are part of a film crew.","zh":"化妝師是劇組的一部分。"},{"en":"Make-up artists prepare actors’ faces, hair, and appearance for performance.","zh":"make-up artists 為演員準備面部、髮型和外觀。"},{"en":"A make-up artist may make an actor look older, tired, injured, or elegant.","zh":"化妝師可能令演員看起來較老、疲倦、受傷或優雅。"},{"en":"Film shoots create paid work for make-up artists.","zh":"電影拍攝為化妝師創造有薪工作。"},{"en":"This phrase shows that filmmaking involves many specialised skills.","zh":"這個片語顯示電影製作涉及許多專門技能。"}],"source":"2014 Q4.pdf","sourcePage":7},{"front":"caterers","meaning":"膳食供應商","examples":[{"en":"Caterers may provide meals for the film crew.","zh":"膳食供應商可能為劇組提供餐膳。"},{"en":"Caterers are people or businesses that prepare and deliver food for events or groups.","zh":"caterers 是為活動或團體準備和送餐的人或企業。"},{"en":"A long film shoot may need caterers to serve breakfast, lunch, and drinks.","zh":"長時間電影拍攝可能需要膳食供應商提供早餐、午餐和飲品。"},{"en":"Local caterers can earn income when productions film nearby.","zh":"當製作團隊在附近拍攝時，本地膳食供應商可以賺取收入。"},{"en":"This phrase shows how filming supports businesses beyond cinema work.","zh":"這個片語顯示拍攝如何支持電影工作以外的商業。"}],"source":"2014 Q4.pdf","sourcePage":7},{"front":"security staff","meaning":"保安人員","examples":[{"en":"Security staff help manage safety during filming.","zh":"保安人員在拍攝期間協助管理安全。"},{"en":"Security staff are workers who protect people, manage crowds, and keep order.","zh":"security staff 是保護人們、管理人群和維持秩序的工作者。"},{"en":"Film crews may hire security staff to guide pedestrians around equipment.","zh":"劇組可能聘請保安人員引導行人繞過器材。"},{"en":"Good security staff can reduce risk during busy city-centre filming.","zh":"良好保安人員可以減少繁忙市中心拍攝的風險。"},{"en":"This phrase connects filming with public safety work.","zh":"這個片語把拍攝與公共安全工作連接起來。"}],"source":"2014 Q4.pdf","sourcePage":7},{"front":"extras","meaning":"臨時演員","examples":[{"en":"Extras may be hired for crowd scenes.","zh":"群眾場面可能聘請臨時演員。"},{"en":"Extras are background performers who appear in scenes without major speaking roles.","zh":"extras 是在場景中出現、但沒有重要對白的背景演員。"},{"en":"A street scene may need extras to look like a real crowd.","zh":"街道場景可能需要臨時演員，才像真實人群。"},{"en":"Film shoots can offer short-term paid work to extras.","zh":"電影拍攝可為臨時演員提供短期有薪工作。"},{"en":"This phrase shows that even small roles contribute to film production.","zh":"這個片語顯示即使小角色也對電影製作有貢獻。"}],"source":"2014 Q4.pdf","sourcePage":8},{"front":"earn a living from","meaning":"靠……謀生","examples":[{"en":"Many workers earn a living from film production.","zh":"許多工作者靠電影製作謀生。"},{"en":"To earn a living from something means to make money from it to support daily life.","zh":"earn a living from 意思是從某事賺錢以支持日常生活。"},{"en":"A photographer may earn a living from weddings and events.","zh":"攝影師可能靠婚禮和活動攝影謀生。"},{"en":"Technicians, drivers, and caterers may earn a living from film shoots.","zh":"技術員、司機和膳食供應商可能靠電影拍攝謀生。"},{"en":"This phrase reminds readers that creative work supports real livelihoods.","zh":"這個片語提醒讀者創意工作支持真實生計。"}],"source":"2014 Q4.pdf","sourcePage":8},{"front":"nearby businesses","meaning":"附近商戶","examples":[{"en":"Nearby businesses can benefit from a movie shoot.","zh":"附近商戶可以從電影拍攝中受惠。"},{"en":"Nearby businesses are shops, restaurants, or services close to the filming location.","zh":"nearby businesses 指靠近拍攝地點的商店、餐廳或服務。"},{"en":"A café near a film shoot may sell more food to the crew.","zh":"拍攝地附近的咖啡店可能向劇組賣出更多食物。"},{"en":"Nearby businesses may suffer if access is blocked, so planning matters.","zh":"如果入口被阻塞，附近商戶可能受損，所以規劃很重要。"},{"en":"This phrase shows both the possible benefit and the need for care.","zh":"這個片語同時顯示可能好處和謹慎需要。"}],"source":"2014 Q4.pdf","sourcePage":8},{"front":"serve the crew breakfast","meaning":"為劇組供應早餐","examples":[{"en":"A café may serve the crew breakfast before filming.","zh":"咖啡店可能在拍攝前為劇組供應早餐。"},{"en":"To serve the crew breakfast means to provide morning food to the film team.","zh":"serve the crew breakfast 意思是為電影團隊提供早上食物。"},{"en":"A small café can earn extra income by serving the crew breakfast.","zh":"小咖啡店可以透過為劇組供應早餐賺取額外收入。"},{"en":"Early shoots often need nearby shops to serve food before filming starts.","zh":"清晨拍攝通常需要附近店舖在開拍前供應食物。"},{"en":"This phrase gives a concrete example of local economic benefit.","zh":"這個片語給出本地經濟利益的具體例子。"}],"source":"2014 Q4.pdf","sourcePage":8},{"front":"provide costumes","meaning":"提供戲服","examples":[{"en":"A tailor may provide costumes for the production.","zh":"裁縫可能為製作提供戲服。"},{"en":"To provide costumes means to supply clothing used by actors in a performance or film.","zh":"provide costumes 意思是供應演員在表演或電影中使用的服裝。"},{"en":"A costume shop may provide uniforms for a police scene.","zh":"戲服店可能為警察場景提供制服。"},{"en":"Local tailors can benefit when productions need special clothing.","zh":"當製作需要特別服裝時，本地裁縫可以受惠。"},{"en":"This phrase shows how filming supports skilled small businesses.","zh":"這個片語顯示拍攝如何支持有技能的小企業。"}],"source":"2014 Q4.pdf","sourcePage":8},{"front":"prepare signs or props","meaning":"準備告示牌或道具","examples":[{"en":"A printing shop may prepare signs or props for filming.","zh":"印刷店可能為拍攝準備告示牌或道具。"},{"en":"To prepare signs or props means to make objects used to create the scene.","zh":"prepare signs or props 意思是製作場景中使用的物件。"},{"en":"A film may need fake shop signs, posters, menus, or newspapers.","zh":"電影可能需要假店舖招牌、海報、餐牌或報紙。"},{"en":"Printing shops can earn work when crews need signs or props quickly.","zh":"當劇組急需告示牌或道具時，印刷店可以獲得工作。"},{"en":"This phrase shows the hidden business activity behind a shoot.","zh":"這個片語顯示拍攝背後隱藏的商業活動。"}],"source":"2014 Q4.pdf","sourcePage":8},{"front":"creative workers","meaning":"創意工作者","examples":[{"en":"Creative workers often struggle for stable opportunities.","zh":"創意工作者往往難以爭取穩定機會。"},{"en":"Creative workers are people who work in arts, media, design, film, or culture.","zh":"creative workers 指在藝術、媒體、設計、電影或文化領域工作的人。"},{"en":"Actors, editors, make-up artists, and writers can all be creative workers.","zh":"演員、剪接師、化妝師和編劇都可以是創意工作者。"},{"en":"Film shoots provide creative workers with experience and income.","zh":"電影拍攝為創意工作者提供經驗和收入。"},{"en":"This phrase highlights the human side of the creative economy.","zh":"這個片語突顯創意經濟中的人性一面。"}],"source":"2014 Q4.pdf","sourcePage":8},{"front":"struggle for stable opportunities","meaning":"難以爭取穩定機會","examples":[{"en":"Creative workers may struggle for stable opportunities in an expensive city.","zh":"在生活成本高昂的城市中，創意工作者可能難以爭取穩定機會。"},{"en":"To struggle for stable opportunities means to find it difficult to get regular and reliable work.","zh":"struggle for stable opportunities 意思是難以獲得定期而可靠的工作。"},{"en":"Young artists may struggle for stable opportunities when projects are irregular.","zh":"當項目不固定時，年輕藝術家可能難以爭取穩定機會。"},{"en":"More local productions can help reduce this struggle.","zh":"更多本地製作可以幫助減少這種困難。"},{"en":"This phrase explains why every film project can matter to workers.","zh":"這個片語解釋為何每個電影項目對工作者都重要。"}],"source":"2014 Q4.pdf","sourcePage":8},{"front":"every production matters","meaning":"每個製作都很重要","examples":[{"en":"Every production matters to people working in the industry.","zh":"對業內工作者而言，每個製作都很重要。"},{"en":"Every production matters means each project is important because it creates work and experience.","zh":"every production matters 意思是每個項目都重要，因為它創造工作和經驗。"},{"en":"For a new actor, even a small production can matter.","zh":"對新演員來說，即使小型製作也可能很重要。"},{"en":"When jobs are unstable, every production matters more.","zh":"當工作不穩定時，每個製作都更加重要。"},{"en":"This phrase shows respect for creative workers’ livelihoods.","zh":"這個片語顯示對創意工作者生計的尊重。"}],"source":"2014 Q4.pdf","sourcePage":8},{"front":"some may argue that","meaning":"有些人可能會認為","examples":[{"en":"Some may argue that filming blocks customers from entering shops.","zh":"有些人可能會認為拍攝阻礙顧客進入商店。"},{"en":"Some may argue that introduces an opposing opinion.","zh":"some may argue that 用來引出相反意見。"},{"en":"Some may argue that city filming causes more harm than benefit.","zh":"有些人可能會認為市中心拍攝害處多於好處。"},{"en":"This phrase helps the writer acknowledge the other side fairly.","zh":"這個片語幫助作者公平承認另一方觀點。"},{"en":"It prepares readers for a rebuttal.","zh":"它讓讀者準備閱讀反駁。"}],"source":"2014 Q4.pdf","sourcePage":8},{"front":"block customers from entering","meaning":"阻礙顧客進入","examples":[{"en":"Filming may block customers from entering a shop.","zh":"拍攝可能阻礙顧客進入商店。"},{"en":"To block customers from entering means to stop or make it difficult for customers to go inside.","zh":"block customers from entering 意思是阻止或令顧客難以進入。"},{"en":"Large cameras and cables may block customers from entering a small café.","zh":"大型攝影機和電線可能阻礙顧客進入小咖啡店。"},{"en":"If access is blocked, shops may lose business during filming.","zh":"如果出入口被阻塞，商店可能在拍攝期間損失生意。"},{"en":"This phrase explains one real concern of shopkeepers.","zh":"這個片語解釋店主的一個真實關注。"}],"source":"2014 Q4.pdf","sourcePage":9},{"front":"that concern is real","meaning":"這個關注是真實的","examples":[{"en":"That concern is real, but it does not justify a blanket ban.","zh":"這個關注是真實的，但不足以支持一刀切禁令。"},{"en":"That concern is real means the worry is reasonable and should not be dismissed.","zh":"that concern is real 意思是這個憂慮合理，不應被忽視。"},{"en":"Residents’ concern about noise is real, even if a ban is too extreme.","zh":"居民對噪音的關注是真實的，即使禁令過於極端。"},{"en":"Acknowledging that concern is real makes the argument more balanced.","zh":"承認關注真實，令論點更平衡。"},{"en":"This phrase shows sympathy before disagreeing with the proposed solution.","zh":"這個片語在不同意解決方案前先表達同理。"}],"source":"2014 Q4.pdf","sourcePage":9},{"front":"a blanket ban","meaning":"一刀切禁令；全面禁令","examples":[{"en":"A blanket ban would be too extreme.","zh":"一刀切禁令會過於極端。"},{"en":"A blanket ban is a rule that prohibits something in all cases, without exceptions.","zh":"blanket ban 指在所有情況下禁止某事、沒有例外的規則。"},{"en":"A blanket ban on filming would stop responsible crews as well as careless ones.","zh":"一刀切拍攝禁令會同時阻止負責任和粗心的劇組。"},{"en":"Blanket bans are simple, but they may be unfair and wasteful.","zh":"一刀切禁令簡單，但可能不公平和浪費。"},{"en":"This phrase criticises a one-size-fits-all solution.","zh":"這個片語批評一刀切的解決方案。"}],"source":"2014 Q4.pdf","sourcePage":9},{"front":"fair compensation","meaning":"公平補償","examples":[{"en":"Fair compensation can reduce the burden on affected shops.","zh":"公平補償可以減輕受影響商店的負擔。"},{"en":"Fair compensation means reasonable payment or support for loss or inconvenience.","zh":"fair compensation 指對損失或不便作出合理付款或支援。"},{"en":"A shop may receive fair compensation if filming blocks its entrance for hours.","zh":"如果拍攝數小時阻塞店舖入口，商店可能收到公平補償。"},{"en":"Compensation helps balance private inconvenience with public cultural benefit.","zh":"補償有助平衡私人不便和公共文化好處。"},{"en":"This phrase shows a practical way to protect affected people.","zh":"這個片語顯示保障受影響人士的實際方法。"}],"source":"2014 Q4.pdf","sourcePage":9},{"front":"advance notice","meaning":"預先通知","examples":[{"en":"Advance notice allows residents and shops to prepare.","zh":"預先通知讓居民和商店作準備。"},{"en":"Advance notice means information given before something happens.","zh":"advance notice 指事情發生前提供的資訊。"},{"en":"Shops need advance notice if a street will be closed for filming.","zh":"如果街道將因拍攝封閉，商店需要預先通知。"},{"en":"Advance notice helps residents change travel plans or prepare for noise.","zh":"預先通知幫助居民改變出行計劃或準備面對噪音。"},{"en":"This phrase shows how communication can reduce disruption.","zh":"這個片語顯示溝通如何減少滋擾。"}],"source":"2014 Q4.pdf","sourcePage":9},{"front":"sensible scheduling","meaning":"合理時間安排","examples":[{"en":"Sensible scheduling can reduce disruption.","zh":"合理時間安排可以減少滋擾。"},{"en":"Sensible scheduling means planning the time of an activity in a reasonable and careful way.","zh":"sensible scheduling 意思是以合理和謹慎方式安排活動時間。"},{"en":"Filming at off-peak hours is an example of sensible scheduling.","zh":"在非繁忙時段拍攝就是合理時間安排的例子。"},{"en":"Sensible scheduling avoids blocking roads during rush hour.","zh":"合理時間安排避免在繁忙時間阻塞道路。"},{"en":"This phrase shows how good planning can solve practical problems.","zh":"這個片語顯示良好規劃如何解決實際問題。"}],"source":"2014 Q4.pdf","sourcePage":9},{"front":"short-term inconvenience","meaning":"短期不便","examples":[{"en":"Short-term inconvenience can be balanced against wider economic gain.","zh":"短期不便可以與更廣泛經濟收益作平衡。"},{"en":"Short-term inconvenience means trouble that lasts for a limited period.","zh":"short-term inconvenience 指只持續有限時間的不便。"},{"en":"A road closure for two hours may be short-term inconvenience.","zh":"封路兩小時可能是短期不便。"},{"en":"Short-term inconvenience is easier to accept if people receive notice and support.","zh":"如果人們收到通知和支援，短期不便較容易接受。"},{"en":"This phrase admits the cost while keeping it in proportion.","zh":"這個片語承認代價，同時保持比例感。"}],"source":"2014 Q4.pdf","sourcePage":9},{"front":"be balanced against","meaning":"與……作平衡","examples":[{"en":"Short-term inconvenience should be balanced against economic gain.","zh":"短期不便應與經濟收益作平衡。"},{"en":"Be balanced against means be compared fairly with another factor before deciding.","zh":"be balanced against 意思是在作決定前與另一因素公平比較。"},{"en":"Noise from a festival should be balanced against its community value.","zh":"節日噪音應與其社區價值作平衡。"},{"en":"Filming inconvenience should be balanced against jobs and cultural benefits.","zh":"拍攝不便應與就業和文化好處作平衡。"},{"en":"This phrase helps make a fair judgement.","zh":"這個片語幫助作出公平判斷。"}],"source":"2014 Q4.pdf","sourcePage":9},{"front":"wider economic gain","meaning":"更廣泛的經濟收益","examples":[{"en":"Film shoots can create wider economic gain.","zh":"電影拍攝可以創造更廣泛的經濟收益。"},{"en":"Wider economic gain means financial benefit that spreads beyond one person or company.","zh":"wider economic gain 指超出一個人或一間公司的財政好處。"},{"en":"A film project may help restaurants, transport providers, and local suppliers.","zh":"電影項目可能幫助餐廳、交通服務和本地供應商。"},{"en":"Wider economic gain can justify limited inconvenience if rules are fair.","zh":"如果規則公平，更廣泛經濟收益可支持有限不便。"},{"en":"This phrase focuses on the broader effect on the economy.","zh":"這個片語著重對經濟的更廣泛影響。"}],"source":"2014 Q4.pdf","sourcePage":9},{"front":"proportionate to","meaning":"與……相稱","examples":[{"en":"The disruption should be proportionate to the value created.","zh":"滋擾應與所創造的價值相稱。"},{"en":"Proportionate to means suitable in size or seriousness compared with something else.","zh":"proportionate to 意思是與另一事物相比，在大小或嚴重程度上合適。"},{"en":"A short road closure may be proportionate to a major cultural event.","zh":"為大型文化活動短暫封路，可能與其價值相稱。"},{"en":"A whole-day closure for a small shoot may not be proportionate.","zh":"為小型拍攝封路一整天，可能並不相稱。"},{"en":"This phrase helps judge whether inconvenience is reasonable.","zh":"這個片語幫助判斷不便是否合理。"}],"source":"2014 Q4.pdf","sourcePage":9},{"front":"the value created","meaning":"所創造的價值","examples":[{"en":"The value created by filming can justify limited inconvenience.","zh":"拍攝所創造的價值可以支持有限不便。"},{"en":"The value created means the cultural, economic, or social benefit produced by an activity.","zh":"the value created 指某活動產生的文化、經濟或社會好處。"},{"en":"A film may create value by providing jobs and showing the city overseas.","zh":"電影可透過提供工作和向海外展示城市來創造價值。"},{"en":"If little value is created, major disruption is harder to justify.","zh":"如果所創造的價值很少，重大滋擾便較難支持。"},{"en":"This phrase asks people to consider both cost and benefit.","zh":"這個片語要求人們同時考慮成本和好處。"}],"source":"2014 Q4.pdf","sourcePage":10},{"front":"more often than not","meaning":"多數情況下","examples":[{"en":"More often than not, the value is worth the inconvenience.","zh":"多數情況下，這種價值值得承受不便。"},{"en":"More often than not means usually or in most cases.","zh":"more often than not 意思是通常或在大多數情況下。"},{"en":"More often than not, early planning prevents public complaints.","zh":"多數情況下，及早規劃可以防止公眾投訴。"},{"en":"More often than not, responsible crews can finish filming without serious disruption.","zh":"多數情況下，負責任的劇組可以在沒有嚴重滋擾下完成拍攝。"},{"en":"This phrase makes a general judgement without claiming it is always true.","zh":"這個片語作出一般判斷，但沒有聲稱永遠如此。"}],"source":"2014 Q4.pdf","sourcePage":10},{"front":"problems associated with","meaning":"與……相關的問題","examples":[{"en":"The problems associated with filming can be managed.","zh":"與拍攝相關的問題可以被處理。"},{"en":"Problems associated with something are difficulties connected to that activity or issue.","zh":"problems associated with 某事，指與該活動或議題有關的困難。"},{"en":"Noise and blocked pavements are problems associated with city filming.","zh":"噪音和行人路被阻塞是與市中心拍攝相關的問題。"},{"en":"Problems associated with tourism can include crowding and litter.","zh":"與旅遊相關的問題可以包括擠迫和垃圾。"},{"en":"This phrase helps group related concerns together.","zh":"這個片語有助把相關關注歸類。"}],"source":"2014 Q4.pdf","sourcePage":10},{"front":"be managed by better rules","meaning":"可透過更好的規則處理","examples":[{"en":"Filming problems can be managed by better rules.","zh":"拍攝問題可透過更好的規則處理。"},{"en":"Be managed by better rules means be controlled through clearer and stronger regulations.","zh":"be managed by better rules 意思是透過更清晰和更有力的規定控制問題。"},{"en":"Noise can be managed by better rules about filming hours.","zh":"噪音可透過關於拍攝時間的更好規則處理。"},{"en":"Traffic disruption can be managed by better rules on road closures.","zh":"交通滋擾可透過關於封路的更好規則處理。"},{"en":"This phrase supports regulation instead of prohibition.","zh":"這個片語支持規管，而不是禁止。"}],"source":"2014 Q4.pdf","sourcePage":10},{"front":"prohibition","meaning":"禁止","examples":[{"en":"The writer supports regulation rather than prohibition.","zh":"作者支持規管，而不是禁止。"},{"en":"Prohibition means officially banning something.","zh":"prohibition 意思是正式禁止某事。"},{"en":"Prohibition may be necessary for dangerous activities, but not for every inconvenience.","zh":"對危險活動而言，禁止可能有必要，但並非每種不便都要禁止。"},{"en":"In this argument, prohibition is seen as too extreme for city filming.","zh":"在這個論點中，禁止市中心拍攝被視為過於極端。"},{"en":"This word contrasts with controlled permission.","zh":"這個字與受控許可形成對比。"}],"source":"2014 Q4.pdf","sourcePage":10},{"front":"granted","meaning":"無可否認","examples":[{"en":"Granted, nobody wants a camera crew to occupy a busy road.","zh":"無可否認，沒有人想攝影隊佔用繁忙道路。"},{"en":"Granted means the writer accepts a point before explaining why it does not defeat the argument.","zh":"granted 意思是作者先承認一點，再解釋為何它不推翻論點。"},{"en":"Granted, filming can be noisy, but noise can be controlled.","zh":"無可否認，拍攝可以嘈吵，但噪音可以控制。"},{"en":"This word makes the writer sound fair and realistic.","zh":"這個字令作者聽起來公平和現實。"},{"en":"It helps introduce a concession before a rebuttal.","zh":"它幫助在反駁前引出讓步。"}],"source":"2014 Q4.pdf","sourcePage":10},{"front":"camera crew","meaning":"攝影隊","examples":[{"en":"A camera crew should not disturb residents late at night.","zh":"攝影隊不應在深夜滋擾居民。"},{"en":"A camera crew is the team responsible for filming scenes with cameras and related equipment.","zh":"camera crew 是負責用攝影機和相關器材拍攝場景的團隊。"},{"en":"A camera crew may include camera operators, assistants, and lighting workers.","zh":"攝影隊可能包括攝影師、助理和燈光工作者。"},{"en":"Responsible camera crews follow rules and avoid unnecessary disruption.","zh":"負責任的攝影隊會遵守規則並避免不必要滋擾。"},{"en":"This phrase names the group most visible during filming.","zh":"這個片語指出拍攝期間最顯眼的團隊。"}],"source":"2014 Q4.pdf","sourcePage":10},{"front":"occupy a busy road","meaning":"佔用繁忙道路","examples":[{"en":"A camera crew should not occupy a busy road during rush hour.","zh":"攝影隊不應在繁忙時間佔用繁忙道路。"},{"en":"To occupy a busy road means to take up road space so normal traffic cannot use it fully.","zh":"occupy a busy road 意思是佔據道路空間，使正常交通不能完全使用。"},{"en":"Trucks and cameras may occupy a busy road if filming is poorly planned.","zh":"如果拍攝規劃不善，貨車和攝影機可能佔用繁忙道路。"},{"en":"Occupying busy roads at the wrong time can delay many commuters.","zh":"在錯誤時間佔用繁忙道路會延誤許多通勤人士。"},{"en":"This phrase shows why filming schedules need control.","zh":"這個片語顯示為何拍攝時間表需要控制。"}],"source":"2014 Q4.pdf","sourcePage":10},{"front":"rush hour","meaning":"繁忙時間","examples":[{"en":"Filming should not block roads during rush hour.","zh":"拍攝不應在繁忙時間阻塞道路。"},{"en":"Rush hour is the busiest travel time, usually when people go to or leave work.","zh":"rush hour 是最繁忙的出行時段，通常是人們上班或下班時。"},{"en":"Road closures during rush hour can delay buses and taxis.","zh":"繁忙時間封路會延誤巴士和的士。"},{"en":"Film crews should avoid rush hour unless there is a strong reason.","zh":"除非有很強理由，劇組應避開繁忙時間。"},{"en":"This phrase highlights when disruption is most serious.","zh":"這個片語突顯滋擾最嚴重的時段。"}],"source":"2014 Q4.pdf","sourcePage":10},{"front":"blast music outside homes","meaning":"在民居外大聲播放音樂","examples":[{"en":"Crews should not blast music outside homes at midnight.","zh":"劇組不應在午夜於民居外大聲播放音樂。"},{"en":"To blast music outside homes means to play music very loudly near people’s living places.","zh":"blast music outside homes 意思是在住宅附近很大聲播放音樂。"},{"en":"Loud filming music at midnight can disturb sleep and cause complaints.","zh":"午夜的拍攝音樂太大聲，會滋擾睡眠並引起投訴。"},{"en":"Rules should stop crews from blasting music in residential areas late at night.","zh":"規則應阻止劇組深夜在住宅區大聲播放音樂。"},{"en":"This phrase gives a clear example of irresponsible filming behaviour.","zh":"這個片語給出不負責任拍攝行為的清晰例子。"}],"source":"2014 Q4.pdf","sourcePage":10},{"front":"leave rubbish behind","meaning":"留下垃圾","examples":[{"en":"Film crews should not leave rubbish behind after shooting.","zh":"劇組拍攝後不應留下垃圾。"},{"en":"To leave rubbish behind means to go away without clearing waste.","zh":"leave rubbish behind 意思是離開時沒有清理廢物。"},{"en":"A responsible crew removes food boxes, tape, cables, and packaging after filming.","zh":"負責任的劇組在拍攝後會移走飯盒、膠紙、電線和包裝。"},{"en":"Leaving rubbish behind makes residents feel disrespected.","zh":"留下垃圾會令居民覺得不被尊重。"},{"en":"This phrase shows why clean-up duties should be part of permits.","zh":"這個片語顯示為何清理責任應成為許可證條件。"}],"source":"2014 Q4.pdf","sourcePage":11},{"front":"irresponsible filming","meaning":"不負責任的拍攝","examples":[{"en":"Irresponsible filming should be punished.","zh":"不負責任的拍攝應受到懲罰。"},{"en":"Irresponsible filming means filming that ignores rules, safety, residents, or the environment.","zh":"irresponsible filming 指忽視規則、安全、居民或環境的拍攝。"},{"en":"Blocking emergency access is a form of irresponsible filming.","zh":"阻塞緊急通道是不負責任拍攝的一種。"},{"en":"Punishing irresponsible filming does not mean banning all filming.","zh":"懲罰不負責任的拍攝並不等於禁止所有拍攝。"},{"en":"This phrase separates bad behaviour from the activity itself.","zh":"這個片語把差劣行為與活動本身分開。"}],"source":"2014 Q4.pdf","sourcePage":11},{"front":"not the same as","meaning":"不等同於","examples":[{"en":"Irresponsible filming is not the same as filming itself.","zh":"不負責任的拍攝不等同於拍攝本身。"},{"en":"Not the same as means different from and should not be confused with.","zh":"not the same as 意思是與某事不同，不應混為一談。"},{"en":"Bad driving is not the same as driving itself.","zh":"差劣駕駛不等同於駕駛本身。"},{"en":"The problem is careless crews, not filming itself.","zh":"問題是粗心劇組，而不是拍攝本身。"},{"en":"This phrase helps the writer make an important distinction.","zh":"這個片語幫助作者作出重要區分。"}],"source":"2014 Q4.pdf","sourcePage":11},{"front":"apply for permits","meaning":"申請許可證","examples":[{"en":"Film crews should apply for permits before shooting.","zh":"劇組拍攝前應申請許可證。"},{"en":"To apply for permits means to request official permission before doing an activity.","zh":"apply for permits 意思是在進行活動前申請官方許可。"},{"en":"Event organisers may apply for permits before using a public park.","zh":"活動主辦者使用公園前可能需要申請許可證。"},{"en":"Applying for filming permits lets authorities check safety and timing.","zh":"申請拍攝許可證讓當局檢查安全和時間安排。"},{"en":"This phrase shows that public filming should be planned and approved.","zh":"這個片語顯示公共拍攝應經規劃和批准。"}],"source":"2014 Q4.pdf","sourcePage":11},{"front":"consult affected shops and residents","meaning":"諮詢受影響商戶和居民","examples":[{"en":"Crews should consult affected shops and residents in advance.","zh":"劇組應提前諮詢受影響商戶和居民。"},{"en":"To consult affected shops and residents means to ask those likely to be disturbed for views or information.","zh":"consult affected shops and residents 意思是向可能受滋擾的人詢問意見或資料。"},{"en":"Film crews should consult shops if entrances may be blocked.","zh":"如果店舖入口可能被阻塞，劇組應諮詢商戶。"},{"en":"Consultation helps identify problems before filming begins.","zh":"諮詢有助在拍攝開始前找出問題。"},{"en":"This phrase shows respect for people living or working near the shoot.","zh":"這個片語顯示對拍攝地附近居民和工作者的尊重。"}],"source":"2014 Q4.pdf","sourcePage":11},{"front":"display clear notices","meaning":"張貼清晰告示","examples":[{"en":"Crews should display clear notices before filming.","zh":"劇組應在拍攝前張貼清晰告示。"},{"en":"To display clear notices means to put up easy-to-read information in public.","zh":"display clear notices 意思是在公共地方貼出容易閱讀的資訊。"},{"en":"Clear notices should show filming dates, times, locations, and contact numbers.","zh":"清晰告示應顯示拍攝日期、時間、地點和聯絡電話。"},{"en":"Displaying notices helps residents prepare for temporary disruption.","zh":"張貼告示幫助居民準備面對暫時滋擾。"},{"en":"This phrase describes a simple communication duty.","zh":"這個片語描述一項簡單溝通責任。"}],"source":"2014 Q4.pdf","sourcePage":11},{"front":"several days in advance","meaning":"提前數天","examples":[{"en":"Public notices should be displayed several days in advance.","zh":"公眾告示應提前數天張貼。"},{"en":"Several days in advance means a few days before something happens.","zh":"several days in advance 意思是在某事發生前幾天。"},{"en":"Residents need notice several days in advance to plan transport or business hours.","zh":"居民需要提前數天收到通知，以安排交通或營業時間。"},{"en":"A notice posted only one hour before filming may be too late.","zh":"拍攝前一小時才張貼告示可能太遲。"},{"en":"This phrase stresses early communication.","zh":"這個片語強調及早溝通。"}],"source":"2014 Q4.pdf","sourcePage":11},{"front":"restore the area","meaning":"恢復該區原狀","examples":[{"en":"Crews should restore the area immediately after shooting.","zh":"劇組應在拍攝後立即恢復該區原狀。"},{"en":"To restore the area means to return the place to its original clean and usable condition.","zh":"restore the area 意思是把地方回復到原本清潔和可使用的狀態。"},{"en":"Crews restore the area by removing equipment, rubbish, and temporary signs.","zh":"劇組可透過移走器材、垃圾和臨時告示來恢復該區原狀。"},{"en":"If the area is not restored, residents may resent future filming.","zh":"如果地區沒有恢復原狀，居民可能反感日後拍攝。"},{"en":"This phrase shows responsibility after filming ends.","zh":"這個片語顯示拍攝結束後的責任。"}],"source":"2014 Q4.pdf","sourcePage":11},{"front":"immediately after shooting","meaning":"拍攝後立即","examples":[{"en":"The area should be cleaned immediately after shooting.","zh":"該區應在拍攝後立即清理。"},{"en":"Immediately after shooting means right after filming has finished.","zh":"immediately after shooting 意思是拍攝完成後馬上。"},{"en":"Roads should reopen immediately after shooting if they are safe.","zh":"如果安全，道路應在拍攝後立即重開。"},{"en":"Cleaning immediately after shooting reduces inconvenience for residents.","zh":"拍攝後立即清理可以減少居民不便。"},{"en":"This phrase gives a clear time requirement.","zh":"這個片語給出清晰時間要求。"}],"source":"2014 Q4.pdf","sourcePage":11},{"front":"transport officers","meaning":"交通人員","examples":[{"en":"Transport officers can help manage road arrangements.","zh":"交通人員可以協助管理道路安排。"},{"en":"Transport officers are officials or staff who help control traffic and transport flow.","zh":"transport officers 是協助控制交通和運輸流動的官員或職員。"},{"en":"Transport officers may guide buses around a filming area.","zh":"交通人員可能引導巴士繞過拍攝區域。"},{"en":"Their presence can make road closures safer and clearer.","zh":"他們在場可以令封路更安全和清晰。"},{"en":"This phrase shows who can help protect public order during filming.","zh":"這個片語顯示誰可以在拍攝期間協助保護公共秩序。"}],"source":"2014 Q4.pdf","sourcePage":11},{"front":"limit filming to","meaning":"把拍攝限制在……","examples":[{"en":"The authorities can limit filming to off-peak hours.","zh":"當局可以把拍攝限制在非繁忙時段。"},{"en":"To limit filming to certain times means to allow it only during those times.","zh":"limit filming to 某些時間，意思是只容許在那些時間拍攝。"},{"en":"A school may limit playground use to lunch hours.","zh":"學校可能把操場使用限制在午膳時間。"},{"en":"Limiting filming to quiet periods reduces disruption.","zh":"把拍攝限制在較安靜時段可以減少滋擾。"},{"en":"This phrase describes a controlled permission, not a ban.","zh":"這個片語描述受控許可，而不是禁令。"}],"source":"2014 Q4.pdf","sourcePage":12},{"front":"off-peak hours","meaning":"非繁忙時段","examples":[{"en":"Filming should be limited to off-peak hours where possible.","zh":"可行情況下，拍攝應限制在非繁忙時段。"},{"en":"Off-peak hours are times when roads, shops, or public transport are less busy.","zh":"off-peak hours 指道路、商店或公共交通較不繁忙的時間。"},{"en":"Mid-morning may be off-peak for some streets after commuters have gone to work.","zh":"通勤人士上班後，上午較後時間對某些街道可能是非繁忙時段。"},{"en":"Filming during off-peak hours can reduce traffic disruption.","zh":"在非繁忙時段拍攝可以減少交通滋擾。"},{"en":"This phrase shows how scheduling can protect daily life.","zh":"這個片語顯示時間安排如何保障日常生活。"}],"source":"2014 Q4.pdf","sourcePage":12},{"front":"penalties can be imposed on","meaning":"可對……施加罰則","examples":[{"en":"Penalties can be imposed on companies that break the conditions.","zh":"可對違反條件的公司施加罰則。"},{"en":"Penalties can be imposed on someone means punishments can be officially applied to them.","zh":"penalties can be imposed on someone 意思是可正式對某人施加懲罰。"},{"en":"Fines can be imposed on drivers who park illegally.","zh":"可對非法泊車的司機施加罰款。"},{"en":"Penalties can be imposed on film companies that ignore permit rules.","zh":"可對忽視許可證規則的電影公司施加罰則。"},{"en":"This phrase shows that rules have consequences.","zh":"這個片語顯示規則有後果。"}],"source":"2014 Q4.pdf","sourcePage":12},{"front":"break the conditions","meaning":"違反條件","examples":[{"en":"Companies that break the conditions should be punished.","zh":"違反條件的公司應受到懲罰。"},{"en":"To break the conditions means to fail to follow the rules attached to permission.","zh":"break the conditions 意思是沒有遵守許可所附帶的規則。"},{"en":"A crew breaks the conditions if it films after the approved time.","zh":"如果劇組在批准時間後繼續拍攝，就是違反條件。"},{"en":"Breaking permit conditions can damage public trust in future filming.","zh":"違反許可證條件可能損害公眾對日後拍攝的信任。"},{"en":"This phrase explains what behaviour should trigger penalties.","zh":"這個片語解釋甚麼行為應引發罰則。"}],"source":"2014 Q4.pdf","sourcePage":12},{"front":"hypothetical shoot","meaning":"假設的拍攝","examples":[{"en":"A hypothetical shoot in Causeway Bay shows how rules could work.","zh":"銅鑼灣一個假設的拍攝顯示規則可以如何運作。"},{"en":"A hypothetical shoot is an imagined filming example used to explain an idea.","zh":"hypothetical shoot 是用來解釋想法的想像拍攝例子。"},{"en":"A writer may use a hypothetical shoot to show how traffic can be managed.","zh":"作者可能使用假設的拍攝來展示交通如何管理。"},{"en":"Hypothetical examples help readers understand rules in practice.","zh":"假設例子幫助讀者理解規則在實際上如何運作。"},{"en":"This phrase signals that the example is imagined, not an actual event.","zh":"這個片語表示例子是假想的，而不是實際事件。"}],"source":"2014 Q4.pdf","sourcePage":12},{"front":"one lane is closed","meaning":"一條行車線被封閉","examples":[{"en":"One lane could be closed only late at night.","zh":"一條行車線可只在深夜被封閉。"},{"en":"One lane is closed means one part of the road is temporarily unavailable to traffic.","zh":"one lane is closed 意思是道路其中一部分暫時不能讓車輛使用。"},{"en":"If one lane is closed, drivers may need to slow down or change lanes.","zh":"如果一條行車線被封閉，司機可能需要減速或轉線。"},{"en":"Closing one lane late at night causes less disruption than closing it at rush hour.","zh":"深夜封閉一條行車線比繁忙時間封閉造成較少滋擾。"},{"en":"This phrase describes a limited road-control measure.","zh":"這個片語描述有限度的道路管制措施。"}],"source":"2014 Q4.pdf","sourcePage":12},{"front":"residents are informed","meaning":"居民獲通知","examples":[{"en":"The inconvenience is reduced if residents are informed.","zh":"如果居民獲通知，不便便會減少。"},{"en":"Residents are informed means people living nearby are told what will happen.","zh":"residents are informed 意思是附近居民被告知將會發生甚麼事。"},{"en":"Residents are informed through notices, letters, or online announcements.","zh":"居民可透過告示、信件或網上公告獲通知。"},{"en":"If residents are informed early, they can plan around filming.","zh":"如果居民及早獲通知，便可因應拍攝作安排。"},{"en":"This phrase shows that communication reduces frustration.","zh":"這個片語顯示溝通能減少不滿。"}],"source":"2014 Q4.pdf","sourcePage":12},{"front":"emergency access","meaning":"緊急通道","examples":[{"en":"Emergency access must be kept open during filming.","zh":"拍攝期間必須保持緊急通道開放。"},{"en":"Emergency access means routes that ambulances, fire engines, or police vehicles may need to use.","zh":"emergency access 指救護車、消防車或警車可能需要使用的路線。"},{"en":"Film crews must not block emergency access with equipment or vehicles.","zh":"劇組不得用器材或車輛阻塞緊急通道。"},{"en":"Keeping emergency access open protects life and public safety.","zh":"保持緊急通道開放可以保障生命和公共安全。"},{"en":"This phrase shows a non-negotiable safety requirement.","zh":"這個片語顯示不可妥協的安全要求。"}],"source":"2014 Q4.pdf","sourcePage":12},{"front":"be kept open","meaning":"保持開放","examples":[{"en":"Emergency access should be kept open at all times.","zh":"緊急通道應時刻保持開放。"},{"en":"Be kept open means remain available and not be blocked.","zh":"be kept open 意思是維持可使用，並不被阻塞。"},{"en":"Building exits must be kept open during events.","zh":"活動期間，建築物出口必須保持開放。"},{"en":"During filming, roads needed for emergency vehicles must be kept open.","zh":"拍攝期間，緊急車輛需要的道路必須保持開放。"},{"en":"This phrase stresses continuous access.","zh":"這個片語強調持續通行。"}],"source":"2014 Q4.pdf","sourcePage":12},{"front":"limited and predictable","meaning":"有限而可預計","examples":[{"en":"With rules, the inconvenience becomes limited and predictable.","zh":"有了規則，不便會變得有限而可預計。"},{"en":"Limited and predictable means controlled in size and easy to expect or plan for.","zh":"limited and predictable 意思是範圍受控制，並且容易預期或安排。"},{"en":"A planned road closure is less stressful when it is limited and predictable.","zh":"當計劃中的封路有限而可預計時，壓力會較小。"},{"en":"Residents can accept inconvenience more easily when they know its time and scale.","zh":"居民知道不便的時間和程度時，較容易接受。"},{"en":"This phrase shows the benefit of clear regulation.","zh":"這個片語顯示清晰規管的好處。"}],"source":"2014 Q4.pdf","sourcePage":12},{"front":"setting clear boundaries","meaning":"設定清晰界線","examples":[{"en":"Setting clear boundaries can protect daily life and artistic freedom.","zh":"設定清晰界線可以保護日常生活和藝術自由。"},{"en":"Setting clear boundaries means creating firm limits about what is allowed.","zh":"setting clear boundaries 意思是就甚麼被容許建立明確限制。"},{"en":"A school sets clear boundaries when it allows phones only for learning tasks.","zh":"學校只容許手機用於學習任務，就是設定清晰界線。"},{"en":"Filming boundaries may cover time, noise, traffic, and clean-up.","zh":"拍攝界線可包括時間、噪音、交通和清理。"},{"en":"This phrase shows how freedom can work with responsibility.","zh":"這個片語顯示自由如何與責任並存。"}],"source":"2014 Q4.pdf","sourcePage":13},{"front":"protect both...and...","meaning":"同時保護……和……","examples":[{"en":"Clear rules protect both daily life and artistic freedom.","zh":"清晰規則同時保護日常生活和藝術自由。"},{"en":"Protect both...and... means safeguard two important things at the same time.","zh":"protect both...and... 意思是同時保障兩件重要事情。"},{"en":"Good school rules protect both safety and creativity.","zh":"好校規同時保護安全和創意。"},{"en":"Filming regulations should protect both residents and filmmakers.","zh":"拍攝規例應同時保護居民和電影人。"},{"en":"This structure helps show that the solution need not choose only one side.","zh":"這個句式有助顯示解決方案不必只選一方。"}],"source":"2014 Q4.pdf","sourcePage":13},{"front":"daily life","meaning":"日常生活","examples":[{"en":"Filming rules should protect residents’ daily life.","zh":"拍攝規則應保護居民的日常生活。"},{"en":"Daily life means people’s ordinary routines, such as travelling, working, resting, and shopping.","zh":"daily life 指人們的日常安排，例如出行、工作、休息和購物。"},{"en":"Blocked pavements can interfere with daily life.","zh":"行人路被阻塞可能干擾日常生活。"},{"en":"Rules protect daily life when they limit noise and road closures.","zh":"規則透過限制噪音和封路來保護日常生活。"},{"en":"This phrase reminds us that public space is used by ordinary people every day.","zh":"這個片語提醒我們公共空間每天由普通人使用。"}],"source":"2014 Q4.pdf","sourcePage":13},{"front":"artistic freedom","meaning":"藝術自由","examples":[{"en":"Hong Kong should protect artistic freedom while keeping order.","zh":"香港應在維持秩序的同時保護藝術自由。"},{"en":"Artistic freedom means the ability of artists to create and express ideas.","zh":"artistic freedom 指藝術家創作和表達想法的能力。"},{"en":"Filmmakers need artistic freedom to show real streets and real stories.","zh":"電影人需要藝術自由去展示真實街道和真實故事。"},{"en":"Artistic freedom should be protected, but it should not ignore public safety.","zh":"藝術自由應受保護，但不應忽視公共安全。"},{"en":"This phrase explains why a total ban may harm culture.","zh":"這個片語解釋為何全面禁令可能傷害文化。"}],"source":"2014 Q4.pdf","sourcePage":13},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, a ban is easy to announce but unwise.","zh":"相比之下，禁令容易宣布，但並不明智。"},{"en":"By contrast is used to show a clear difference from the previous idea.","zh":"by contrast 用來顯示與前一個想法的清楚差別。"},{"en":"Rules require planning; by contrast, a ban may seem simple.","zh":"規則需要規劃；相比之下，禁令可能看似簡單。"},{"en":"This phrase helps compare regulation with prohibition.","zh":"這個片語幫助比較規管與禁止。"},{"en":"It signals that the next point will oppose what came before.","zh":"它表示下一點會與前文形成對比。"}],"source":"2014 Q4.pdf","sourcePage":13},{"front":"easy to announce","meaning":"容易宣布","examples":[{"en":"A ban is easy to announce but difficult to justify.","zh":"禁令容易宣布，但難以合理支持。"},{"en":"Easy to announce means simple to declare publicly.","zh":"easy to announce 意思是容易公開宣告。"},{"en":"A school rule can be easy to announce but hard to apply fairly.","zh":"校規可能容易宣布，但難以公平執行。"},{"en":"A filming ban may sound decisive because it is easy to announce.","zh":"拍攝禁令可能因容易宣布而聽起來果斷。"},{"en":"This phrase warns that simple statements may not be wise solutions.","zh":"這個片語提醒人簡單宣告未必是明智方案。"}],"source":"2014 Q4.pdf","sourcePage":13},{"front":"poor in judgement","meaning":"判斷欠佳","examples":[{"en":"A total ban would be poor in judgement.","zh":"全面禁令會是判斷欠佳。"},{"en":"Poor in judgement means showing bad decision-making or weak understanding of the situation.","zh":"poor in judgement 意思是決策差或對情況理解不足。"},{"en":"Punishing every student for one person’s mistake may be poor in judgement.","zh":"因一個人的錯而懲罰所有學生，可能是判斷欠佳。"},{"en":"A total filming ban is poor in judgement if better rules can solve the problem.","zh":"如果更好規則能解決問題，全面拍攝禁令就是判斷欠佳。"},{"en":"This phrase gives a strong criticism of a decision.","zh":"這個片語對決定作出強烈批評。"}],"source":"2014 Q4.pdf","sourcePage":13},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, Hong Kong should not ban city-centre filming.","zh":"總括而言，香港不應禁止市中心拍攝。"},{"en":"All things considered means after thinking about all the important points.","zh":"all things considered 意思是在考慮所有重要因素後。"},{"en":"All things considered, regulation is fairer than prohibition.","zh":"總括而言，規管比禁止更公平。"},{"en":"This phrase is useful before a final judgement.","zh":"這個片語適合在最後判斷前使用。"},{"en":"It shows the writer has weighed both benefits and problems.","zh":"它顯示作者已衡量好處和問題。"}],"source":"2014 Q4.pdf","sourcePage":13},{"front":"shut its city centre to filmmakers","meaning":"對電影人關上市中心","examples":[{"en":"Hong Kong should not shut its city centre to filmmakers.","zh":"香港不應對電影人關上市中心。"},{"en":"To shut its city centre to filmmakers means to stop filmmakers from using central urban areas.","zh":"shut its city centre to filmmakers 意思是阻止電影人使用市中心地區。"},{"en":"A city that shuts key locations to artists may reduce its cultural visibility.","zh":"對藝術家關閉重要地點的城市，可能降低其文化可見度。"},{"en":"Hong Kong can control filming without shutting filmmakers out.","zh":"香港可以控制拍攝，而不把電影人拒諸門外。"},{"en":"This phrase makes a ban sound like closing a door to creativity.","zh":"這個片語令禁令聽起來像向創意關門。"}],"source":"2014 Q4.pdf","sourcePage":13},{"front":"there is no denying that","meaning":"無可否認","examples":[{"en":"There is no denying that residents deserve respect.","zh":"無可否認，居民值得被尊重。"},{"en":"There is no denying that means it is impossible or unreasonable to deny a point.","zh":"there is no denying that 意思是某一點不能或不應被否認。"},{"en":"There is no denying that filming can cause inconvenience.","zh":"無可否認，拍攝可能造成不便。"},{"en":"This phrase accepts an important truth before giving a balanced answer.","zh":"這個片語在提出平衡答案前接受重要事實。"},{"en":"It helps the writer sound fair rather than one-sided.","zh":"它幫助作者聽起來公平，而不是片面。"}],"source":"2014 Q4.pdf","sourcePage":13},{"front":"residents, commuters and shopkeepers","meaning":"居民、通勤人士和店主","examples":[{"en":"Residents, commuters and shopkeepers deserve respect.","zh":"居民、通勤人士和店主值得被尊重。"},{"en":"Residents, commuters and shopkeepers are people who live, travel, and run businesses in the area.","zh":"residents, commuters and shopkeepers 指在該區居住、出行和經營業務的人。"},{"en":"Filming affects residents at home, commuters on roads, and shopkeepers at work.","zh":"拍攝影響在家的居民、路上的通勤人士和工作的店主。"},{"en":"Rules should consider all three groups before filming begins.","zh":"規則應在拍攝開始前考慮這三個群體。"},{"en":"This phrase names the main people affected by city-centre filming.","zh":"這個片語指出受市中心拍攝影響的主要人士。"}],"source":"2014 Q4.pdf","sourcePage":14},{"front":"deserve respect","meaning":"值得被尊重","examples":[{"en":"Residents and shopkeepers deserve respect during filming.","zh":"拍攝期間，居民和店主值得被尊重。"},{"en":"Deserve respect means should be treated with care, fairness, and dignity.","zh":"deserve respect 意思是應被關心、公平和有尊嚴地對待。"},{"en":"Residents deserve respect because they live with the disruption.","zh":"居民值得被尊重，因為他們承受滋擾。"},{"en":"Shopkeepers deserve respect if filming affects their business.","zh":"如果拍攝影響生意，店主值得被尊重。"},{"en":"This phrase shows the ethical side of the argument.","zh":"這個片語顯示論點中的道德層面。"}],"source":"2014 Q4.pdf","sourcePage":14},{"front":"be treated as background objects","meaning":"被當作背景物件","examples":[{"en":"Residents should not be treated as background objects.","zh":"居民不應被當作背景物件。"},{"en":"Be treated as background objects means be ignored as if they are only part of the scenery.","zh":"be treated as background objects 意思是被忽視，好像只是風景的一部分。"},{"en":"Residents are real people, not background objects for a film scene.","zh":"居民是真實的人，不是電影場景的背景物件。"},{"en":"Treating people this way can create resentment against filmmakers.","zh":"這樣對待人可能引起他們對電影人的反感。"},{"en":"This phrase argues for human respect during filming.","zh":"這個片語主張拍攝期間要尊重人。"}],"source":"2014 Q4.pdf","sourcePage":14},{"front":"someone else’s production","meaning":"別人的製作","examples":[{"en":"Residents should not suffer for someone else’s production.","zh":"居民不應因別人的製作而受苦。"},{"en":"Someone else’s production means a film or project made by other people, not by the residents themselves.","zh":"someone else’s production 指由其他人而非居民自己製作的電影或項目。"},{"en":"A shopkeeper should not lose business unfairly because of someone else’s production.","zh":"店主不應因別人的製作而不公平地失去生意。"},{"en":"If residents bear the cost, they should receive notice and protection.","zh":"如果居民承受代價，他們應得到通知和保護。"},{"en":"This phrase shows why fairness is needed when creative work affects others.","zh":"這個片語顯示當創作影響他人時為何需要公平。"}],"source":"2014 Q4.pdf","sourcePage":14},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, respect does not require exclusion.","zh":"然而，尊重並不需要排除。"},{"en":"Nevertheless means however, despite what has just been said.","zh":"nevertheless 意思是然而，儘管剛才所說成立。"},{"en":"Residents deserve respect; nevertheless, filming need not be banned completely.","zh":"居民值得尊重；然而，拍攝不必完全禁止。"},{"en":"This word helps the writer move from concession to argument.","zh":"這個字幫助作者由讓步轉向論證。"},{"en":"It shows that acknowledging a problem does not end the debate.","zh":"它顯示承認問題並不代表辯論結束。"}],"source":"2014 Q4.pdf","sourcePage":14},{"front":"require exclusion","meaning":"需要排除；需要拒諸門外","examples":[{"en":"Respect does not require excluding filmmakers from the city centre.","zh":"尊重並不需要把電影人排除在市中心之外。"},{"en":"Require exclusion means need someone or something to be kept out.","zh":"require exclusion 意思是需要把某人或某事拒諸門外。"},{"en":"Protecting students does not always require excluding visitors from school events.","zh":"保護學生不一定需要把訪客排除於學校活動之外。"},{"en":"Respecting residents requires rules, not necessarily excluding filmmakers.","zh":"尊重居民需要規則，但不一定需要排除電影人。"},{"en":"This phrase helps reject a solution that goes too far.","zh":"這個片語幫助拒絕過度的解決方案。"}],"source":"2014 Q4.pdf","sourcePage":14},{"front":"planning, accountability and communication","meaning":"規劃、問責和溝通","examples":[{"en":"Respect requires planning, accountability and communication.","zh":"尊重需要規劃、問責和溝通。"},{"en":"Planning, accountability and communication mean preparing carefully, taking responsibility, and informing people clearly.","zh":"planning, accountability and communication 指仔細準備、承擔責任和清楚通知人們。"},{"en":"A well-run event needs planning, accountability, and communication.","zh":"運作良好的活動需要規劃、問責和溝通。"},{"en":"Filming can respect residents if crews plan, answer for mistakes, and explain arrangements.","zh":"如果劇組規劃、為錯誤負責並解釋安排，拍攝便能尊重居民。"},{"en":"This phrase summarises what responsible filming requires.","zh":"這個片語總結負責任拍攝所需條件。"}],"source":"2014 Q4.pdf","sourcePage":14},{"front":"the authorities","meaning":"當局","examples":[{"en":"The authorities should improve the permit system.","zh":"當局應改善拍攝許可證制度。"},{"en":"The authorities are the government bodies or officials responsible for rules and public order.","zh":"the authorities 指負責規則和公共秩序的政府部門或官員。"},{"en":"The authorities may approve filming permits and manage road arrangements.","zh":"當局可能批准拍攝許可證並管理道路安排。"},{"en":"Residents expect the authorities to balance culture with daily life.","zh":"居民期望當局在文化與日常生活之間取得平衡。"},{"en":"This phrase identifies who should make and enforce public rules.","zh":"這個片語指出誰應制定和執行公共規則。"}],"source":"2014 Q4.pdf","sourcePage":14},{"front":"improve the permit system","meaning":"改善許可證制度","examples":[{"en":"The authorities should improve the permit system for filming.","zh":"當局應改善拍攝許可證制度。"},{"en":"To improve the permit system means to make the process for approval clearer and more effective.","zh":"improve the permit system 意思是令批准程序更清楚和更有效。"},{"en":"A better permit system may require notices, compensation plans, and safety checks.","zh":"更好的許可證制度可能要求告示、補償計劃和安全檢查。"},{"en":"Improving the system can reduce complaints without banning filming.","zh":"改善制度可以在不禁止拍攝下減少投訴。"},{"en":"This phrase points to reform rather than prohibition.","zh":"這個片語指向改革，而不是禁止。"}],"source":"2014 Q4.pdf","sourcePage":14},{"front":"publish filming schedules","meaning":"公布拍攝時間表","examples":[{"en":"The government should publish filming schedules in advance.","zh":"政府應提前公布拍攝時間表。"},{"en":"To publish filming schedules means to make filming times and locations publicly available.","zh":"publish filming schedules 意思是公開拍攝時間和地點。"},{"en":"Publishing schedules helps residents know when roads may be affected.","zh":"公布時間表幫助居民知道道路何時可能受影響。"},{"en":"Shops can plan deliveries better if schedules are published early.","zh":"如果時間表及早公布，商店可以更好安排送貨。"},{"en":"This phrase shows how transparency can reduce conflict.","zh":"這個片語顯示透明度如何減少衝突。"}],"source":"2014 Q4.pdf","sourcePage":14},{"front":"require compensation where appropriate","meaning":"在適當情況下要求補償","examples":[{"en":"The authorities should require compensation where appropriate.","zh":"當局應在適當情況下要求補償。"},{"en":"Require compensation where appropriate means demand payment or support when the situation justifies it.","zh":"require compensation where appropriate 意思是在情況合理時要求付款或支援。"},{"en":"If filming blocks a shop entrance for hours, compensation may be appropriate.","zh":"如果拍攝阻塞店舖入口數小時，補償可能是適當的。"},{"en":"This rule would protect affected businesses without banning film shoots.","zh":"這項規則可在不禁止拍攝下保護受影響商戶。"},{"en":"This phrase shows a fair response to real inconvenience.","zh":"這個片語顯示對真實不便的公平回應。"}],"source":"2014 Q4.pdf","sourcePage":15},{"front":"punish careless crews","meaning":"懲罰粗心大意的劇組","examples":[{"en":"The authorities should punish careless crews.","zh":"當局應懲罰粗心大意的劇組。"},{"en":"To punish careless crews means to penalise film teams that ignore rules or cause avoidable harm.","zh":"punish careless crews 意思是懲處忽視規則或造成可避免損害的電影團隊。"},{"en":"A careless crew that leaves rubbish behind should face consequences.","zh":"留下垃圾的粗心劇組應承擔後果。"},{"en":"Punishing careless crews protects responsible filmmakers from unfair criticism.","zh":"懲罰粗心劇組可以保護負責任電影人免受不公平批評。"},{"en":"This phrase focuses blame on bad conduct, not filmmaking itself.","zh":"這個片語把責任放在差劣行為上，而不是電影製作本身。"}],"source":"2014 Q4.pdf","sourcePage":15},{"front":"let them roll responsibly","meaning":"讓它們負責任地開拍","examples":[{"en":"Let cameras roll, but let them roll responsibly.","zh":"讓攝影機開拍，但要讓它們負責任地開拍。"},{"en":"Let them roll responsibly means allow filming to continue, but require careful and respectful behaviour.","zh":"let them roll responsibly 意思是容許拍攝繼續，但要求謹慎和尊重的行為。"},{"en":"A city can let crews roll responsibly by enforcing permits and time limits.","zh":"城市可透過執行許可證和時間限制，讓劇組負責任地開拍。"},{"en":"Responsible filming respects residents while preserving creative freedom.","zh":"負責任拍攝尊重居民，同時保存創作自由。"},{"en":"This phrase gives the argument a balanced final message.","zh":"這個片語為論點提供平衡的最後訊息。"}],"source":"2014 Q4.pdf","sourcePage":15},{"front":"a well-run city","meaning":"運作良好的城市","examples":[{"en":"Hong Kong can remain a well-run city.","zh":"香港可以繼續是一個運作良好的城市。"},{"en":"A well-run city is a city that is organised, safe, and managed effectively.","zh":"well-run city 指有組織、安全並有效管理的城市。"},{"en":"A well-run city can host events without letting daily life collapse.","zh":"運作良好的城市可以舉辦活動，而不讓日常生活崩潰。"},{"en":"Clear filming rules help Hong Kong remain a well-run city.","zh":"清晰拍攝規則幫助香港保持運作良好。"},{"en":"This phrase connects cultural activity with good urban management.","zh":"這個片語把文化活動與良好城市管理連接起來。"}],"source":"2014 Q4.pdf","sourcePage":15},{"front":"a city with a story worth telling","meaning":"一個有值得訴說故事的城市","examples":[{"en":"Hong Kong should remain a city with a story worth telling.","zh":"香港應繼續是一個有值得訴說故事的城市。"},{"en":"A city with a story worth telling is a place whose history, people, and streets deserve to be shown.","zh":"a city with a story worth telling 指一個其歷史、人民和街道值得被展示的地方。"},{"en":"Films can show why Hong Kong is a city with stories worth telling.","zh":"電影可以展示為何香港是一個有值得訴說故事的城市。"},{"en":"If filming is banned from central areas, some stories may be harder to tell.","zh":"如果市中心地區禁止拍攝，有些故事可能更難被訴說。"},{"en":"This phrase gives the ending emotional and cultural force.","zh":"這個片語令結尾帶有情感和文化力量。"}],"source":"2014 Q4.pdf","sourcePage":15},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"Yours faithfully is used to close a formal letter to an editor.","zh":"Yours faithfully 用於結束寫給編輯的正式信件。"},{"en":"Yours faithfully is a formal closing used when ending a polite letter, especially to someone not personally known.","zh":"Yours faithfully 是正式信件中的禮貌結尾，尤其用於寫給不熟識的人。"},{"en":"A reader may end a letter to a newspaper editor with “Yours faithfully”.","zh":"讀者可能以 “Yours faithfully” 結束寫給報章編輯的信。"},{"en":"This closing keeps the tone respectful and suitable for public writing.","zh":"這個結尾保持語氣尊重，並適合公共寫作。"},{"en":"It is more formal than casual endings such as “Best”.","zh":"它比 “Best” 等隨意結尾更正式。"}],"source":"2014 Q4.pdf","sourcePage":15}],"dse/writing/part-b/2014/Q5":[{"front":"a fairer locker policy","meaning":"更公平的儲物櫃政策","examples":[{"en":"The students are asking for a fairer locker policy.","zh":"學生正在要求一項更公平的儲物櫃政策。"},{"en":"A fairer locker policy means a set of locker rules that gives students more equal and reasonable access.","zh":"a fairer locker policy 指一套讓學生更平等、更合理使用儲物櫃的規則。"},{"en":"A school may need a fairer locker policy if only a few students can store heavy books safely.","zh":"如果只有少數學生能安全存放沉重書本，學校可能需要更公平的儲物櫃政策。"},{"en":"A fairer locker policy can reduce complaints because students understand how lockers are given out.","zh":"更公平的儲物櫃政策可以減少投訴，因為學生明白儲物櫃如何分配。"},{"en":"Fairness does not mean everyone gets everything immediately; it means the system is clear and reasonable.","zh":"公平不代表人人立即得到所有東西；而是制度清晰和合理。"}],"source":"2014 Q5.pdf","sourcePage":1},{"front":"a healthier school","meaning":"更健康的學校","examples":[{"en":"A fairer locker policy can help create a healthier school.","zh":"更公平的儲物櫃政策可以幫助建立更健康的學校。"},{"en":"A healthier school is a school environment that protects students’ bodies, minds, and learning habits.","zh":"a healthier school 指保障學生身體、心理和學習習慣的學校環境。"},{"en":"A school becomes healthier when students do not carry extremely heavy bags every day.","zh":"當學生不用每天背極重書包時，學校會變得更健康。"},{"en":"Better facilities can create a healthier school because students feel safer and less stressed.","zh":"更好的設施可以建立更健康的學校，因為學生感到更安全、壓力更少。"},{"en":"A healthier school cares not only about marks, but also about students’ daily well-being.","zh":"更健康的學校不只關心分數，也關心學生每日的身心健康。"}],"source":"2014 Q5.pdf","sourcePage":1},{"front":"chairperson of","meaning":"……的主席","examples":[{"en":"Chris Wong is the chairperson of the Student Union.","zh":"Chris Wong 是學生會的主席。"},{"en":"Chairperson of a group means the person who leads or represents that group.","zh":"chairperson of 某組織，指領導或代表該組織的人。"},{"en":"The chairperson of the debate club may organise meetings and speak to teachers.","zh":"辯論學會主席可能組織會議並與老師溝通。"},{"en":"A chairperson should listen to members before presenting a proposal.","zh":"主席在提出建議前應聆聽成員意見。"},{"en":"This title shows that Chris is writing with a representative role, not only as one student.","zh":"這個職銜顯示 Chris 是以代表身份寫信，而不只是一名學生。"}],"source":"2014 Q5.pdf","sourcePage":1},{"front":"Student Union","meaning":"學生會","examples":[{"en":"The Student Union is writing about the locker policy.","zh":"學生會正在就儲物櫃政策寫信。"},{"en":"A Student Union is a student organisation that represents students’ views and interests.","zh":"Student Union 指代表學生意見和利益的學生組織。"},{"en":"The Student Union may collect opinions before meeting the principal.","zh":"學生會可能在會見校長前收集意見。"},{"en":"A responsible Student Union raises problems respectfully and suggests realistic solutions.","zh":"負責任的學生會會尊重地提出問題，並建議實際解決方法。"},{"en":"In this letter, the Student Union speaks for students affected by the locker rules.","zh":"在這封信中，學生會代表受儲物櫃規則影響的學生發聲。"}],"source":"2014 Q5.pdf","sourcePage":1},{"front":"writing on behalf of","meaning":"代表……寫信","examples":[{"en":"I am writing on behalf of students from S1 to S6.","zh":"我代表中一至中六學生寫信。"},{"en":"Writing on behalf of someone means writing as their representative.","zh":"writing on behalf of someone 指以某人的代表身份寫信。"},{"en":"A class monitor may write on behalf of classmates to request a cleaner classroom.","zh":"班長可能代表同學寫信，要求更清潔的課室。"},{"en":"This phrase shows that the writer is not expressing only a personal opinion.","zh":"這個短語顯示作者不是只表達個人意見。"},{"en":"When writing on behalf of others, the writer should reflect their views fairly.","zh":"代表他人寫信時，作者應公平反映他們的看法。"}],"source":"2014 Q5.pdf","sourcePage":1},{"front":"from S1 to S6","meaning":"中一至中六","examples":[{"en":"The proposal represents students from S1 to S6.","zh":"這項建議代表中一至中六學生。"},{"en":"From S1 to S6 means including students from Secondary One to Secondary Six.","zh":"from S1 to S6 指包括中一至中六學生。"},{"en":"A school survey from S1 to S6 can show whether a problem affects the whole school.","zh":"一項涵蓋中一至中六的學校調查，可以顯示問題是否影響全校。"},{"en":"This phrase suggests that the issue is not limited to one year group.","zh":"這個短語暗示問題不限於某一級學生。"},{"en":"If students from S1 to S6 share similar concerns, the school should take them seriously.","zh":"如果中一至中六學生都有相似憂慮，學校應認真看待。"}],"source":"2014 Q5.pdf","sourcePage":1},{"front":"present locker policy","meaning":"現行儲物櫃政策","examples":[{"en":"The letter asks the school to review the present locker policy.","zh":"這封信要求學校檢討現行儲物櫃政策。"},{"en":"The present locker policy means the locker rules currently used by the school.","zh":"present locker policy 指學校目前使用的儲物櫃規則。"},{"en":"Students may question the present locker policy if they do not know how lockers are assigned.","zh":"如果學生不知道儲物櫃如何分配，他們可能質疑現行儲物櫃政策。"},{"en":"Reviewing the present policy helps the school see whether it still meets students’ needs.","zh":"檢討現行政策有助學校了解它是否仍符合學生需要。"},{"en":"A present policy may have been reasonable before, but unfair under new conditions.","zh":"一項現行政策以前可能合理，但在新情況下可能變得不公平。"}],"source":"2014 Q5.pdf","sourcePage":1},{"front":"at present","meaning":"目前","examples":[{"en":"At present, only a small number of students have access to lockers.","zh":"目前，只有少數學生可以使用儲物櫃。"},{"en":"At present means now or under the current situation.","zh":"at present 指現在或在目前情況下。"},{"en":"At present, the library closes before many students finish their activities.","zh":"目前，圖書館在許多學生完成活動前已關門。"},{"en":"Writers use this phrase to describe the situation before suggesting a change.","zh":"作者使用這個短語來描述建議改變前的情況。"},{"en":"At present shows that the problem exists now and needs attention.","zh":"at present 顯示問題現在存在，並需要關注。"}],"source":"2014 Q5.pdf","sourcePage":1},{"front":"have access to","meaning":"可以使用","examples":[{"en":"Only a small number of students have access to lockers.","zh":"只有少數學生可以使用儲物櫃。"},{"en":"To have access to something means to be able to use or reach it.","zh":"have access to something 指能夠使用或接觸某物。"},{"en":"Students with library cards have access to online reading resources.","zh":"有圖書證的學生可以使用網上閱讀資源。"},{"en":"If only some students have access to a useful facility, others may feel disadvantaged.","zh":"如果只有部分學生可以使用有用設施，其他人可能感到處於不利位置。"},{"en":"Access matters because a facility is helpful only when students can actually use it.","zh":"使用機會很重要，因為設施只有在學生真正能用時才有幫助。"}],"source":"2014 Q5.pdf","sourcePage":1},{"front":"led many classmates to ask whether","meaning":"令很多同學質疑是否","examples":[{"en":"The policy has led many classmates to ask whether it is fair.","zh":"這項政策令很多同學質疑它是否公平。"},{"en":"Led many classmates to ask whether means caused many students to question if something is true or reasonable.","zh":"led many classmates to ask whether 指令很多學生質疑某事是否真實或合理。"},{"en":"The sudden rule change led many classmates to ask whether students had been consulted.","zh":"突然改變規則令很多同學質疑學生是否曾被諮詢。"},{"en":"When rules are unclear, they often lead people to ask whether the system is fair.","zh":"當規則不清晰時，常會令人質疑制度是否公平。"},{"en":"This phrase shows that the policy has created doubt, not only inconvenience.","zh":"這個短語顯示政策造成的不只是麻煩，還有疑問。"}],"source":"2014 Q5.pdf","sourcePage":1},{"front":"basic school facility","meaning":"基本學校設施","examples":[{"en":"A locker is a basic school facility.","zh":"儲物櫃是一項基本學校設施。"},{"en":"A basic school facility is a simple but important resource that helps students study safely and comfortably.","zh":"basic school facility 指幫助學生安全和舒適學習的簡單但重要資源。"},{"en":"Desks, chairs, toilets, drinking water, and lockers can be basic school facilities.","zh":"書桌、椅子、洗手間、飲水機和儲物櫃都可以是基本學校設施。"},{"en":"If a basic facility is shared unfairly, students may feel the school does not understand their needs.","zh":"如果基本設施分配不公平，學生可能覺得學校不了解他們的需要。"},{"en":"Calling lockers basic suggests they are not a luxury request.","zh":"稱儲物櫃為基本設施，暗示這不是奢侈要求。"}],"source":"2014 Q5.pdf","sourcePage":2},{"front":"shared fairly","meaning":"被公平分配","examples":[{"en":"Students are asking whether lockers are being shared fairly.","zh":"學生正在問儲物櫃是否被公平分配。"},{"en":"Shared fairly means distributed or used in a way that treats people reasonably and equally.","zh":"shared fairly 指以合理和平等對待人們的方式分配或使用。"},{"en":"Group project work is shared fairly when each member has a suitable task.","zh":"當每名成員都有合適任務時，小組專題工作就是被公平分配。"},{"en":"Facilities are shared fairly when the rules are clear and needs are considered.","zh":"當規則清晰並考慮需要時，設施就是被公平分配。"},{"en":"If lockers are not shared fairly, students may feel the system favours a fortunate few.","zh":"如果儲物櫃沒有被公平分配，學生可能覺得制度偏向少數幸運的人。"}],"source":"2014 Q5.pdf","sourcePage":2},{"front":"after collecting views","meaning":"收集意見後","examples":[{"en":"After collecting views from different classes, the Student Union wrote the proposal.","zh":"收集不同班別的意見後，學生會寫了這項建議。"},{"en":"After collecting views means after gathering opinions from people.","zh":"after collecting views 指收集人們的意見之後。"},{"en":"After collecting views from parents, the school adjusted the homework policy.","zh":"收集家長意見後，學校調整了功課政策。"},{"en":"Collecting views before writing a proposal makes the suggestion more representative.","zh":"寫建議前收集意見，會令建議更具代表性。"},{"en":"This phrase shows that the Student Union listened before asking for change.","zh":"這個短語顯示學生會在要求改變前先聆聽。"}],"source":"2014 Q5.pdf","sourcePage":2},{"front":"students in different classes","meaning":"不同班別的學生","examples":[{"en":"The Student Union collected views from students in different classes.","zh":"學生會向不同班別的學生收集意見。"},{"en":"Students in different classes means students from more than one class or year group.","zh":"students in different classes 指來自不止一個班或年級的學生。"},{"en":"A survey of students in different classes can reveal whether a problem is widespread.","zh":"對不同班別學生進行調查，可以顯示問題是否普遍。"},{"en":"Students in different classes may have different needs because their subjects and activities vary.","zh":"不同班別的學生可能有不同需要，因為他們的科目和活動不同。"},{"en":"Including different classes helps the proposal sound fairer and more balanced.","zh":"包括不同班別能令建議聽起來更公平、更平衡。"}],"source":"2014 Q5.pdf","sourcePage":2},{"front":"respectfully urge","meaning":"鄭重促請","examples":[{"en":"I respectfully urge the school to review this arrangement.","zh":"我鄭重促請學校檢討這項安排。"},{"en":"To respectfully urge someone means to strongly ask them to act while keeping a polite tone.","zh":"respectfully urge someone 指以禮貌語氣強烈要求某人採取行動。"},{"en":"Students may respectfully urge the library to extend opening hours before exams.","zh":"學生可能鄭重促請圖書館在考試前延長開放時間。"},{"en":"This phrase is useful when the issue is serious but the writer wants to remain courteous.","zh":"當問題嚴重但作者想保持禮貌時，這個短語很有用。"},{"en":"It shows firmness without sounding rude.","zh":"它顯示堅定態度，但不顯得無禮。"}],"source":"2014 Q5.pdf","sourcePage":2},{"front":"review this arrangement","meaning":"檢討這項安排","examples":[{"en":"The school is urged to review this arrangement.","zh":"學校被促請檢討這項安排。"},{"en":"To review this arrangement means to examine the current plan or system again to see whether it should change.","zh":"review this arrangement 指再次檢視目前的計劃或制度，看是否需要改變。"},{"en":"A school may review a lunch arrangement if students regularly queue for too long.","zh":"如果學生經常排隊太久，學校可能檢討午膳安排。"},{"en":"Reviewing an arrangement is sensible when many people are affected by it.","zh":"當許多人受影響時，檢討安排是合理的。"},{"en":"The phrase suggests improvement, not automatic rejection.","zh":"這個短語暗示改善，而不是自動否定。"}],"source":"2014 Q5.pdf","sourcePage":2},{"front":"so that","meaning":"以便；使得","examples":[{"en":"The policy should be reviewed so that every student can study safely.","zh":"政策應被檢討，以便每位學生都能安全學習。"},{"en":"So that introduces the purpose or intended result of an action.","zh":"so that 用來引入某行動的目的或預期結果。"},{"en":"The school added more lights so that students could leave safely after activities.","zh":"學校加裝更多燈光，以便學生在活動後安全離開。"},{"en":"Writers use so that to connect a proposal with its benefit.","zh":"作者使用 so that，把建議與其好處連接起來。"},{"en":"Here, the policy should change so that students’ health and learning are protected.","zh":"在這裏，政策應改變，使學生的健康和學習受到保障。"}],"source":"2014 Q5.pdf","sourcePage":2},{"front":"safer, fairer environment","meaning":"更安全、更公平的環境","examples":[{"en":"Every student should study in a safer, fairer environment.","zh":"每位學生都應在更安全、更公平的環境中學習。"},{"en":"A safer, fairer environment is a place where people are protected and treated more equally.","zh":"safer, fairer environment 指人們受到保護並獲得更平等對待的地方。"},{"en":"A classroom becomes safer and fairer when rules are clear and everyone has the resources they need.","zh":"當規則清晰、人人有需要資源時，課室會變得更安全、更公平。"},{"en":"Heavy bags and unclear access can make a school environment feel less fair.","zh":"沉重書包和不清晰的使用機會，會令學校環境感覺較不公平。"},{"en":"A safer, fairer environment helps students focus on learning instead of daily stress.","zh":"更安全、更公平的環境幫助學生專注學習，而不是每日壓力。"}],"source":"2014 Q5.pdf","sourcePage":2},{"front":"our position is that","meaning":"我們的立場是","examples":[{"en":"Our position is that lockers should be made available to all students.","zh":"我們的立場是儲物櫃應可供所有學生使用。"},{"en":"Our position is that means this is our clear opinion or stance.","zh":"our position is that 指這是我們清楚的意見或立場。"},{"en":"Our position is that the canteen should provide healthier lunch choices.","zh":"我們的立場是飯堂應提供更健康的午餐選擇。"},{"en":"This phrase is useful in formal proposals because it states the group’s view directly.","zh":"這個短語在正式建議中很有用，因為它直接表明群體觀點。"},{"en":"It helps readers understand what the writer is asking for before the reasons are explained.","zh":"它幫助讀者在理由被解釋前，先明白作者要求甚麼。"}],"source":"2014 Q5.pdf","sourcePage":2},{"front":"be made available to","meaning":"可供……使用","examples":[{"en":"Lockers should be made available to all students.","zh":"儲物櫃應可供所有學生使用。"},{"en":"To be made available to someone means to be provided so that they can use it.","zh":"be made available to someone 指被提供給某人使用。"},{"en":"Online notes should be made available to students who are absent.","zh":"網上筆記應可供缺席學生使用。"},{"en":"A useful facility should be made available to those who need it most.","zh":"有用設施應可供最有需要的人使用。"},{"en":"Making lockers available to more students would reduce unfairness and daily burden.","zh":"讓更多學生可使用儲物櫃，可以減少不公平和每日負擔。"}],"source":"2014 Q5.pdf","sourcePage":2},{"front":"phased system","meaning":"分階段制度","examples":[{"en":"Lockers should be introduced through a phased system.","zh":"儲物櫃應透過分階段制度推出。"},{"en":"A phased system is a plan carried out in stages instead of all at once.","zh":"phased system 指分階段而不是一次過執行的計劃。"},{"en":"A school may introduce new tablets through a phased system, starting with senior forms.","zh":"學校可能透過分階段制度引入新平板電腦，先由高中開始。"},{"en":"A phased system is useful when cost, space, or management needs careful handling.","zh":"當成本、空間或管理需要小心處理時，分階段制度很有用。"},{"en":"Introducing lockers in phases makes change more realistic and manageable.","zh":"分階段推出儲物櫃，令改變更實際、更可管理。"}],"source":"2014 Q5.pdf","sourcePage":3},{"front":"transparent system","meaning":"透明制度","examples":[{"en":"The school should adopt a transparent locker system.","zh":"學校應採用透明的儲物櫃制度。"},{"en":"A transparent system is a system whose rules and decisions are clear and open to people affected by it.","zh":"transparent system 指規則和決定對受影響者清楚公開的制度。"},{"en":"A transparent scholarship system explains who can apply and how winners are chosen.","zh":"透明獎學金制度會解釋誰可以申請，以及得獎者如何選出。"},{"en":"Transparency reduces suspicion because people know how decisions are made.","zh":"透明度能減少猜疑，因為人們知道決定如何作出。"},{"en":"A transparent locker system would help students trust the allocation process.","zh":"透明儲物櫃制度會幫助學生信任分配過程。"}],"source":"2014 Q5.pdf","sourcePage":3},{"front":"need-sensitive system","meaning":"顧及需要的制度","examples":[{"en":"Lockers should be allocated through a need-sensitive system.","zh":"儲物櫃應透過顧及需要的制度分配。"},{"en":"A need-sensitive system considers people’s different levels of need before making decisions.","zh":"need-sensitive system 指在作決定前考慮人們不同需要程度的制度。"},{"en":"A school may use a need-sensitive system to support students with medical conditions first.","zh":"學校可能使用顧及需要的制度，優先支援有健康狀況的學生。"},{"en":"Such a system is fairer because equal treatment does not always mean identical treatment.","zh":"這種制度較公平，因為平等對待不一定代表完全一樣地對待。"},{"en":"A need-sensitive locker system would recognise students with heavier burdens.","zh":"顧及需要的儲物櫃制度會承認某些學生負擔較重。"}],"source":"2014 Q5.pdf","sourcePage":3},{"front":"not merely","meaning":"不只是","examples":[{"en":"This is not merely a request for convenience.","zh":"這不只是為了方便而提出的要求。"},{"en":"Not merely means not only or not simply.","zh":"not merely 指不只是或不單單是。"},{"en":"A request for quiet study space is not merely about comfort; it also affects learning.","zh":"要求安靜自修空間不只是關於舒適，也影響學習。"},{"en":"This phrase helps show that an issue has deeper importance.","zh":"這個短語有助顯示一個問題有更深重要性。"},{"en":"The locker proposal is not merely convenient because it concerns health and fairness.","zh":"儲物櫃建議不只是方便，因為它關乎健康和公平。"}],"source":"2014 Q5.pdf","sourcePage":3},{"front":"request for convenience","meaning":"為了方便而提出的要求","examples":[{"en":"The proposal is more than a request for convenience.","zh":"這項建議不只是為了方便而提出的要求。"},{"en":"A request for convenience is a request made mainly to make life easier.","zh":"request for convenience 指主要為了令生活更容易而提出的要求。"},{"en":"Asking for a water machine near classrooms may seem like a request for convenience.","zh":"要求在課室附近設飲水機，可能看似為了方便而提出的要求。"},{"en":"Some requests are convenient but also protect health, time, or dignity.","zh":"有些要求帶來方便，但也保障健康、時間或尊嚴。"},{"en":"The locker request is deeper because it affects students’ bodies and learning.","zh":"儲物櫃要求更深層，因為它影響學生的身體和學習。"}],"source":"2014 Q5.pdf","sourcePage":3},{"front":"protect well-being","meaning":"保障身心健康","examples":[{"en":"The locker policy should protect students’ well-being.","zh":"儲物櫃政策應保障學生的身心健康。"},{"en":"To protect well-being means to help keep people physically, mentally, and emotionally healthy.","zh":"protect well-being 指幫助人保持身體、心理和情緒健康。"},{"en":"Schools protect well-being by reducing unnecessary stress and physical strain.","zh":"學校透過減少不必要壓力和身體負擔來保障身心健康。"},{"en":"Heavy schoolbags can harm well-being if students carry them every day.","zh":"如果學生每天背沉重書包，身心健康可能受損。"},{"en":"A good policy protects well-being while still being practical to manage.","zh":"好政策會保障身心健康，同時仍然實際可管理。"}],"source":"2014 Q5.pdf","sourcePage":3},{"front":"improve learning efficiency","meaning":"提升學習效率","examples":[{"en":"Wider locker access can improve learning efficiency.","zh":"更廣泛的儲物櫃使用機會可以提升學習效率。"},{"en":"To improve learning efficiency means to help students learn better with less wasted time or effort.","zh":"improve learning efficiency 指幫助學生以較少浪費的時間或努力學得更好。"},{"en":"Organised notes improve learning efficiency because students find materials quickly.","zh":"有條理的筆記能提升學習效率，因為學生能快速找到材料。"},{"en":"Lockers improve efficiency when students can store books by subject instead of carrying everything.","zh":"當學生能按科目存放書本，而不是攜帶所有東西時，儲物櫃能提升效率。"},{"en":"Better preparation often leads to smoother lessons and less stress.","zh":"更充分準備常帶來更順暢課堂和較少壓力。"}],"source":"2014 Q5.pdf","sourcePage":3},{"front":"strengthen students’ trust","meaning":"加強學生對學校的信任","examples":[{"en":"A fair system can strengthen students’ trust in the school.","zh":"公平制度可以加強學生對學校的信任。"},{"en":"To strengthen students’ trust means to make students believe more strongly that the school is fair and listens to them.","zh":"strengthen students’ trust 指令學生更相信學校公平並願意聆聽他們。"},{"en":"Clear rules strengthen students’ trust because they reduce confusion.","zh":"清晰規則能加強學生信任，因為它們減少混亂。"},{"en":"Students trust a school more when decisions are explained openly.","zh":"當決定被公開解釋時，學生會更信任學校。"},{"en":"A fair locker system can show students that their daily difficulties matter.","zh":"公平儲物櫃制度可以向學生顯示，他們每日的困難很重要。"}],"source":"2014 Q5.pdf","sourcePage":3},{"front":"first and foremost","meaning":"首先；最重要的是","examples":[{"en":"First and foremost, the present policy creates unfairness.","zh":"首先，現行政策造成不公平。"},{"en":"First and foremost means most importantly, before all other points.","zh":"first and foremost 指最重要的是，在其他重點之前。"},{"en":"First and foremost, school rules should protect students’ safety.","zh":"首先，校規應保障學生安全。"},{"en":"Writers use this phrase to introduce the strongest or most basic argument.","zh":"作者使用這個短語來引入最強或最基本的論點。"},{"en":"Here, fairness is placed before cost, space, and management.","zh":"在這裏，公平被放在成本、空間和管理之前。"}],"source":"2014 Q5.pdf","sourcePage":3},{"front":"unintentionally creates","meaning":"無意中造成","examples":[{"en":"The present policy unintentionally creates a sense of unfairness.","zh":"現行政策無意中造成不公平感。"},{"en":"Unintentionally creates means causes something without meaning or planning to do so.","zh":"unintentionally creates 指不是有意或計劃地造成某結果。"},{"en":"A seating plan may unintentionally create loneliness if one student is always left alone.","zh":"如果一名學生總是被單獨安排，座位表可能無意中造成孤立感。"},{"en":"Policies can create problems even when the school did not intend harm.","zh":"即使學校無意造成傷害，政策仍可能帶來問題。"},{"en":"This phrase is polite because it criticises the result without blaming people harshly.","zh":"這個短語很有禮貌，因為它批評結果，而不嚴厲責怪人。"}],"source":"2014 Q5.pdf","sourcePage":3},{"front":"avoidable sense of unfairness","meaning":"可避免的不公平感","examples":[{"en":"The policy creates an avoidable sense of unfairness.","zh":"這項政策造成可避免的不公平感。"},{"en":"An avoidable sense of unfairness is a feeling of unfairness that could be reduced or prevented.","zh":"avoidable sense of unfairness 指本可以減少或避免的不公平感覺。"},{"en":"Students may feel avoidable unfairness when rules are unclear but could easily be explained.","zh":"當規則不清楚但其實很容易解釋時，學生可能感到可避免的不公平。"},{"en":"Avoidable unfairness is frustrating because better planning could solve it.","zh":"可避免的不公平令人不滿，因為更好規劃本可解決它。"},{"en":"A transparent locker system would reduce this unnecessary feeling.","zh":"透明的儲物櫃制度會減少這種不必要的感覺。"}],"source":"2014 Q5.pdf","sourcePage":4},{"front":"the same timetable","meaning":"相同時間表","examples":[{"en":"Students follow the same timetable but receive different treatment.","zh":"學生跟隨相同時間表，卻受到不同待遇。"},{"en":"The same timetable means students have similar school hours, lessons, and daily routines.","zh":"the same timetable 指學生有相似的上課時間、課堂和日常安排。"},{"en":"Students with the same timetable may still carry very different amounts of materials.","zh":"有相同時間表的學生，仍可能攜帶非常不同數量的材料。"},{"en":"When students follow the same timetable, unequal facility access may feel harder to accept.","zh":"當學生跟隨相同時間表時，不平等的設施使用機會可能更難接受。"},{"en":"This phrase highlights the contrast between shared duties and unequal support.","zh":"這個短語突出了共同責任與不平等支援之間的對比。"}],"source":"2014 Q5.pdf","sourcePage":4},{"front":"paying the same school fees","meaning":"繳付相同學費","examples":[{"en":"Students pay the same school fees but do not receive the same access.","zh":"學生繳付相同學費，卻沒有獲得相同使用機會。"},{"en":"Paying the same school fees means students’ families contribute the same required payment to the school.","zh":"paying the same school fees 指學生家庭向學校繳交相同所需費用。"},{"en":"Parents may question fairness if students paying the same fees receive very different services.","zh":"如果繳付相同學費的學生得到非常不同的服務，家長可能質疑公平。"},{"en":"This phrase strengthens the fairness argument by showing equal contribution but unequal benefit.","zh":"這個短語透過顯示相同付出但不同得益，加強公平論點。"},{"en":"Students feel confused when the same fees do not lead to similar access to basic facilities.","zh":"當相同學費沒有帶來相似的基本設施使用機會時，學生會感到困惑。"}],"source":"2014 Q5.pdf","sourcePage":4},{"front":"receive such different treatment","meaning":"受到如此不同的待遇","examples":[{"en":"Students cannot understand why they receive such different treatment.","zh":"學生不能理解為何他們受到如此不同的待遇。"},{"en":"To receive such different treatment means to be treated in a very different way from others.","zh":"receive such different treatment 指與其他人受到非常不同的對待。"},{"en":"Two students may feel unfairness if they do the same work but receive different treatment.","zh":"如果兩名學生做相同工作卻受到不同待遇，他們可能感到不公平。"},{"en":"Different treatment needs clear reasons, or people may suspect favouritism.","zh":"不同待遇需要清楚理由，否則人們可能懷疑偏袒。"},{"en":"The locker issue feels unfair because the reason for different treatment is unclear.","zh":"儲物櫃問題令人覺得不公平，因為不同待遇的原因不清楚。"}],"source":"2014 Q5.pdf","sourcePage":4},{"front":"the problem is not that","meaning":"問題並不是","examples":[{"en":"The problem is not that some students have lockers.","zh":"問題並不是有些學生有儲物櫃。"},{"en":"The problem is not that is used to clarify what the real issue is not.","zh":"the problem is not that 用來澄清真正問題不是甚麼。"},{"en":"The problem is not that students want activities, but that they are given too little time.","zh":"問題並不是學生想要活動，而是給他們的時間太少。"},{"en":"This pattern helps avoid blaming the wrong thing.","zh":"這個句式有助避免責怪錯誤事情。"},{"en":"In this letter, the issue is not locker users, but the unclear and limited system.","zh":"在這封信中，問題不是使用儲物櫃的學生，而是不清晰和有限的制度。"}],"source":"2014 Q5.pdf","sourcePage":4},{"front":"rather","meaning":"而是","examples":[{"en":"Rather, the problem is that most students do not understand the system.","zh":"而是，問題在於大多數學生不了解制度。"},{"en":"Rather is used to correct a previous idea and introduce the writer’s real point.","zh":"rather 用來修正前一個想法，並引入作者真正的重點。"},{"en":"The aim is not to punish students; rather, it is to help them manage time better.","zh":"目的不是懲罰學生；而是幫助他們更好管理時間。"},{"en":"This word is useful when shifting from a misunderstanding to a clearer explanation.","zh":"這個詞在由誤解轉向更清晰解釋時很有用。"},{"en":"Here, rather points readers from jealousy toward transparency.","zh":"在這裏，rather 把讀者由嫉妒引向透明度問題。"}],"source":"2014 Q5.pdf","sourcePage":4},{"front":"have little idea how","meaning":"不太知道如何","examples":[{"en":"Most students have little idea how locker places are allocated.","zh":"大多數學生不太知道儲物櫃名額如何分配。"},{"en":"Have little idea how means do not know much about the method or process.","zh":"have little idea how 指對某方法或過程知道得很少。"},{"en":"Students may have little idea how school prizes are chosen if no criteria are published.","zh":"如果沒有公布標準，學生可能不太知道學校獎項如何選出。"},{"en":"When people have little idea how decisions are made, trust becomes weaker.","zh":"當人們不太知道決定如何作出時，信任會變弱。"},{"en":"This phrase shows that the problem is lack of information.","zh":"這個短語顯示問題是缺乏資訊。"}],"source":"2014 Q5.pdf","sourcePage":4},{"front":"places are allocated","meaning":"名額如何分配","examples":[{"en":"Students do not know how locker places are allocated.","zh":"學生不知道儲物櫃名額如何分配。"},{"en":"Places are allocated means spaces or opportunities are assigned to particular people.","zh":"places are allocated 指位置或機會被分配給特定人士。"},{"en":"Dormitory places are allocated according to need and distance from home.","zh":"宿位會根據需要和離家距離分配。"},{"en":"A fair allocation process should explain who gets priority and why.","zh":"公平的分配過程應解釋誰有優先權以及原因。"},{"en":"Students can accept limits more easily when they know how places are allocated.","zh":"當學生知道名額如何分配時，較容易接受限制。"}],"source":"2014 Q5.pdf","sourcePage":4},{"front":"affects students every day","meaning":"每天影響學生","examples":[{"en":"The rule affects students every day.","zh":"這條規則每天影響學生。"},{"en":"Affects students every day means influences students’ daily routine, comfort, or learning regularly.","zh":"affects students every day 指定期影響學生的日常、舒適感或學習。"},{"en":"A timetable change affects students every day if it changes when they eat and study.","zh":"如果時間表改變學生吃飯和溫習時間，就會每天影響學生。"},{"en":"Daily effects matter because small difficulties become heavy when repeated.","zh":"日常影響很重要，因為小困難重複出現時會變得沉重。"},{"en":"The locker rule affects students every day through bags, books, and movement between rooms.","zh":"儲物櫃規則透過書包、書本和課室之間的移動每天影響學生。"}],"source":"2014 Q5.pdf","sourcePage":4},{"front":"its reasons are unclear","meaning":"其原因不清楚","examples":[{"en":"Misunderstanding grows when a rule’s reasons are unclear.","zh":"當一條規則的原因不清楚時，誤解會增加。"},{"en":"Its reasons are unclear means people do not understand why the rule exists or how it was decided.","zh":"its reasons are unclear 指人們不了解規則為何存在或如何被決定。"},{"en":"Students may complain more when a punishment’s reasons are unclear.","zh":"當懲罰原因不清楚時，學生可能投訴更多。"},{"en":"Rules are easier to accept when their reasons are explained.","zh":"當原因被解釋時，規則較容易被接受。"},{"en":"If locker rules have unclear reasons, students may assume the system is unfair.","zh":"如果儲物櫃規則原因不清楚，學生可能假設制度不公平。"}],"source":"2014 Q5.pdf","sourcePage":4},{"front":"be bound to","meaning":"必然會","examples":[{"en":"Misunderstanding is bound to grow if the policy is unclear.","zh":"如果政策不清楚，誤解必然會增加。"},{"en":"Be bound to means very likely or almost certain to happen.","zh":"be bound to 指非常可能或幾乎一定會發生。"},{"en":"If instructions are confusing, mistakes are bound to happen.","zh":"如果指示令人困惑，錯誤必然會發生。"},{"en":"This phrase shows a strong cause-and-effect expectation.","zh":"這個短語顯示強烈的因果預期。"},{"en":"Unclear locker rules are bound to create doubt because students rely on them every day.","zh":"不清晰的儲物櫃規則必然會造成疑問，因為學生每天都受其影響。"}],"source":"2014 Q5.pdf","sourcePage":5},{"front":"misunderstanding","meaning":"誤解","examples":[{"en":"Unclear rules can lead to misunderstanding.","zh":"不清楚的規則可能導致誤解。"},{"en":"Misunderstanding means a wrong idea or confusion about what something means.","zh":"misunderstanding 指對某事意思產生錯誤想法或混亂。"},{"en":"A misunderstanding may happen when students hear different versions of the same rule.","zh":"當學生聽到同一規則的不同版本時，可能出現誤解。"},{"en":"Misunderstanding grows when people do not receive clear information.","zh":"當人們沒有收到清晰資訊時，誤解會增加。"},{"en":"Transparent explanations can prevent misunderstanding before it becomes complaint.","zh":"透明解釋可以在誤解變成投訴前防止它。"}],"source":"2014 Q5.pdf","sourcePage":5},{"front":"take someone for example","meaning":"以某人為例","examples":[{"en":"Take Form Four students, for example.","zh":"以中四學生為例。"},{"en":"Take someone for example is used to introduce a specific person or group to explain a wider point.","zh":"take someone for example 用來引入具體人物或群體，以解釋更廣泛的觀點。"},{"en":"Take a student with a long journey, for example: a locker may reduce what they carry home.","zh":"以一名上學路程遙遠的學生為例：儲物櫃可能減少他帶回家的物品。"},{"en":"This phrase makes an argument clearer by using a concrete case.","zh":"這個短語透過具體個案令論點更清楚。"},{"en":"It helps readers imagine the real daily effect of a policy.","zh":"它幫助讀者想像政策的真實日常影響。"}],"source":"2014 Q5.pdf","sourcePage":5},{"front":"Form Four students","meaning":"中四學生","examples":[{"en":"Form Four students often carry many study materials.","zh":"中四學生常攜帶許多學習材料。"},{"en":"Form Four students are students in the fourth year of secondary school.","zh":"Form Four students 指中學第四年級的學生。"},{"en":"Form Four students may begin taking electives and preparing for senior-level work.","zh":"中四學生可能開始修讀選修科並準備高中程度學習。"},{"en":"Their schoolbags may become heavier because they need more subject materials.","zh":"他們的書包可能變得更重，因為他們需要更多科目材料。"},{"en":"Using Form Four students as an example shows how locker needs increase in senior forms.","zh":"以中四學生為例，顯示儲物櫃需要如何在高中增加。"}],"source":"2014 Q5.pdf","sourcePage":5},{"front":"reference materials","meaning":"參考資料","examples":[{"en":"Students carry textbooks, exercise books and reference materials.","zh":"學生攜帶課本、練習簿和參考資料。"},{"en":"Reference materials are books, notes, or resources used to look up information and support study.","zh":"reference materials 指用來查找資訊和支援學習的書本、筆記或資源。"},{"en":"Dictionaries, grammar guides, and past-paper books can be reference materials.","zh":"字典、文法指南和歷屆試題書都可以是參考資料。"},{"en":"Students may not need reference materials every lesson, but they need them when revising.","zh":"學生未必每堂都需要參考資料，但溫習時會需要。"},{"en":"Lockers allow students to keep reference materials at school without carrying them all day.","zh":"儲物櫃讓學生把參考資料留在學校，而不用整天攜帶。"}],"source":"2014 Q5.pdf","sourcePage":5},{"front":"several electives","meaning":"幾個選修科","examples":[{"en":"Senior students need materials for several electives.","zh":"高中學生需要幾個選修科的材料。"},{"en":"Several electives means more than one optional subject chosen by students.","zh":"several electives 指學生選讀的不止一個選修科目。"},{"en":"A student taking Biology, Economics and History may need books for several electives.","zh":"修讀生物、經濟和歷史的學生，可能需要幾個選修科的書本。"},{"en":"Several electives can make schoolbags heavier because each subject has separate notes.","zh":"幾個選修科會令書包更重，因為每科都有不同筆記。"},{"en":"Lockers are useful when students have different materials for different elective subjects.","zh":"當學生為不同選修科準備不同材料時，儲物櫃很有用。"}],"source":"2014 Q5.pdf","sourcePage":5},{"front":"whereas","meaning":"而","examples":[{"en":"Senior students carry textbooks, whereas junior-form students may carry art materials.","zh":"高中學生攜帶課本，而初中學生可能攜帶美術用品。"},{"en":"Whereas is used to contrast two different situations or groups.","zh":"whereas 用來對比兩種不同情況或群體。"},{"en":"Some students need laptops for projects, whereas others need sports equipment after school.","zh":"有些學生因專題需要手提電腦，而另一些學生放學後需要運動用品。"},{"en":"This word helps writers compare needs without saying one group is more important.","zh":"這個詞幫助作者比較需要，而不是說某一組更重要。"},{"en":"The sentence shows that different forms may need lockers for different reasons.","zh":"這句顯示不同年級可能因不同原因需要儲物櫃。"}],"source":"2014 Q5.pdf","sourcePage":5},{"front":"junior-form students","meaning":"初中學生","examples":[{"en":"Junior-form students may also need art materials or sports gear.","zh":"初中學生也可能需要美術用品或運動用品。"},{"en":"Junior-form students are younger secondary students, usually in the lower forms.","zh":"junior-form students 指較年輕的中學生，通常是初中年級學生。"},{"en":"Junior-form students may move between classrooms for PE, art, music, and other lessons.","zh":"初中學生可能因體育、美術、音樂和其他課堂而在課室之間移動。"},{"en":"Younger students may struggle more with heavy bags because their bodies are still growing.","zh":"年紀較小的學生可能更難承受沉重書包，因為身體仍在成長。"},{"en":"Locker access should consider junior-form students as well as senior students.","zh":"儲物櫃使用機會應考慮初中學生，也應考慮高中學生。"}],"source":"2014 Q5.pdf","sourcePage":5},{"front":"art materials","meaning":"美術用品","examples":[{"en":"Some junior-form students need art materials after school.","zh":"有些初中學生放學後需要美術用品。"},{"en":"Art materials are tools and supplies used for drawing, painting, crafting, or design.","zh":"art materials 指用於繪畫、手工、設計或創作的工具和用品。"},{"en":"Paints, brushes, sketchbooks, and coloured paper are common art materials.","zh":"顏料、畫筆、素描簿和彩色紙都是常見美術用品。"},{"en":"Art materials can be awkward to carry because they may be large, wet, or fragile.","zh":"美術用品可能難以攜帶，因為它們可能大件、濕或易損。"},{"en":"A locker helps students store art materials safely until they need them.","zh":"儲物櫃幫助學生安全存放美術用品，直到需要使用。"}],"source":"2014 Q5.pdf","sourcePage":5},{"front":"musical instruments","meaning":"樂器","examples":[{"en":"Some students need to carry musical instruments.","zh":"有些學生需要攜帶樂器。"},{"en":"Musical instruments are objects used to make music, such as violins, flutes, guitars, or drums.","zh":"musical instruments 指用來演奏音樂的物件，例如小提琴、長笛、結他或鼓。"},{"en":"A student carrying a violin may need extra storage space during the school day.","zh":"攜帶小提琴的學生在上學日可能需要額外存放空間。"},{"en":"Musical instruments can be expensive and easily damaged if carried everywhere.","zh":"樂器可能昂貴，而且如果到處攜帶，容易受損。"},{"en":"Lockers can protect musical instruments when students attend other lessons.","zh":"當學生上其他課堂時，儲物櫃可以保護樂器。"}],"source":"2014 Q5.pdf","sourcePage":5},{"front":"sports gear","meaning":"運動用品","examples":[{"en":"Some students need sports gear after school.","zh":"有些學生放學後需要運動用品。"},{"en":"Sports gear means clothes, shoes, equipment, or protective items used for sport.","zh":"sports gear 指運動時使用的衣物、鞋、器材或保護用品。"},{"en":"Football boots, rackets, knee pads, and uniforms can all be sports gear.","zh":"足球鞋、球拍、護膝和隊服都可以是運動用品。"},{"en":"Sports gear can make bags bulky even if it is not needed during lessons.","zh":"即使上課時不需要，運動用品也會令書包變得笨重。"},{"en":"Lockers allow students to keep sports gear at school until practice begins.","zh":"儲物櫃讓學生把運動用品留在學校，直到訓練開始。"}],"source":"2014 Q5.pdf","sourcePage":6},{"front":"from classroom to classroom","meaning":"從一間課室到另一間課室","examples":[{"en":"Students must carry everything from classroom to classroom.","zh":"學生必須把所有東西從一間課室帶到另一間課室。"},{"en":"From classroom to classroom means moving between different classrooms throughout the school day.","zh":"from classroom to classroom 指在上學日中不斷在不同課室之間移動。"},{"en":"Students may carry books from classroom to classroom when lessons are held in different rooms.","zh":"當課堂在不同房間進行時，學生可能要把書本從一間課室帶到另一間課室。"},{"en":"This movement becomes tiring when students have no place to store materials.","zh":"如果學生沒有地方存放物品，這種移動會變得疲累。"},{"en":"Lockers reduce the need to carry every item from room to room.","zh":"儲物櫃能減少學生把每件物品逐間課室攜帶的需要。"}],"source":"2014 Q5.pdf","sourcePage":6},{"front":"a fortunate few","meaning":"少數幸運的人","examples":[{"en":"A fortunate few can store their belongings safely.","zh":"少數幸運的人可以安全存放個人物品。"},{"en":"A fortunate few means a small number of lucky people who receive a benefit others do not.","zh":"fortunate few 指獲得其他人沒有的好處的少數幸運人士。"},{"en":"A fortunate few students may get seats in a popular workshop before it is full.","zh":"少數幸運學生可能在熱門工作坊額滿前獲得名額。"},{"en":"This phrase suggests inequality because most people are left out.","zh":"這個短語暗示不平等，因為大多數人被排除。"},{"en":"In the locker issue, a fortunate few have storage while many classmates do not.","zh":"在儲物櫃問題中，少數幸運的人有存放空間，而許多同學沒有。"}],"source":"2014 Q5.pdf","sourcePage":6},{"front":"store their belongings safely","meaning":"安全存放個人物品","examples":[{"en":"Students with lockers can store their belongings safely.","zh":"有儲物櫃的學生可以安全存放個人物品。"},{"en":"To store belongings safely means to keep personal items in a secure place where they are less likely to be lost or damaged.","zh":"store belongings safely 指把個人物品放在安全地方，減少遺失或損壞機會。"},{"en":"Students can store wallets, books, and sports shoes safely in lockers.","zh":"學生可以在儲物櫃中安全存放錢包、書本和運動鞋。"},{"en":"Safe storage reduces worry because students do not need to watch their things all day.","zh":"安全存放能減少擔心，因為學生不用整天看管物品。"},{"en":"A locker helps students protect belongings while focusing on lessons.","zh":"儲物櫃幫助學生保護物品，同時專注上課。"}],"source":"2014 Q5.pdf","sourcePage":6},{"front":"only by","meaning":"只有透過","examples":[{"en":"Only by making the policy transparent can the school show fairness.","zh":"只有透過令政策透明，學校才能顯示公平。"},{"en":"Only by means that a certain result can happen only through that action.","zh":"only by 指只有透過某行動，某結果才會發生。"},{"en":"Only by listening to students can the school understand the daily problem clearly.","zh":"只有透過聆聽學生，學校才能清楚理解日常問題。"},{"en":"This phrase strongly links the solution with the desired result.","zh":"這個短語強烈連接解決方法和想要的結果。"},{"en":"Here, fairness cannot simply be claimed; it must be shown through transparency.","zh":"在這裏，公平不能只被宣稱；必須透過透明度顯示出來。"}],"source":"2014 Q5.pdf","sourcePage":6},{"front":"making the policy transparent","meaning":"令政策透明","examples":[{"en":"The school should make the locker policy transparent.","zh":"學校應令儲物櫃政策透明。"},{"en":"Making the policy transparent means clearly explaining the rules, criteria, and decision process.","zh":"making the policy transparent 指清楚解釋規則、標準和決定過程。"},{"en":"A school makes a policy transparent by publishing who can apply and how decisions are made.","zh":"學校透過公布誰可申請以及如何作決定，令政策透明。"},{"en":"Transparency reduces rumours because students no longer have to guess.","zh":"透明度能減少謠言，因為學生不再需要猜測。"},{"en":"A transparent locker policy would help students accept even limited resources more calmly.","zh":"透明的儲物櫃政策能幫助學生更平靜地接受有限資源。"}],"source":"2014 Q5.pdf","sourcePage":6},{"front":"expanding access","meaning":"擴大使用機會","examples":[{"en":"The school can improve fairness by expanding access to lockers.","zh":"學校可以透過擴大儲物櫃使用機會來改善公平。"},{"en":"Expanding access means allowing more people to use or benefit from something.","zh":"expanding access 指讓更多人能使用或受惠於某事物。"},{"en":"A library expands access by opening earlier and offering online books.","zh":"圖書館透過提早開放和提供電子書來擴大使用機會。"},{"en":"Expanding locker access would help students who currently carry everything all day.","zh":"擴大儲物櫃使用機會，會幫助目前整天攜帶所有物品的學生。"},{"en":"Access can be expanded gradually if space and cost are limited.","zh":"如果空間和成本有限，使用機會可以逐步擴大。"}],"source":"2014 Q5.pdf","sourcePage":6},{"front":"fairness is not just preached","meaning":"公平不只是被宣講","examples":[{"en":"Fairness should not just be preached in assemblies.","zh":"公平不應只是在早會中被宣講。"},{"en":"Fairness is not just preached means fairness should not only be talked about in speeches.","zh":"fairness is not just preached 指公平不應只在演講中被談論。"},{"en":"Kindness is not just preached when students actually help one another.","zh":"當學生真正互相幫助時，善意就不只是被宣講。"},{"en":"Values become meaningful only when they appear in real decisions.","zh":"價值觀只有在真實決定中出現時，才變得有意義。"},{"en":"A fair locker policy would show that fairness is practised, not merely spoken about.","zh":"公平的儲物櫃政策會顯示公平被實踐，而不只是被說出來。"}],"source":"2014 Q5.pdf","sourcePage":6},{"front":"preached in assemblies","meaning":"在早會中宣講","examples":[{"en":"Fairness is often preached in assemblies.","zh":"公平常在早會中被宣講。"},{"en":"Preached in assemblies means spoken about formally to students during school gatherings.","zh":"preached in assemblies 指在學校集會中正式向學生講述。"},{"en":"Teachers may preach responsibility in assemblies before exam season.","zh":"老師可能在考試季前於早會中宣講責任感。"},{"en":"Assembly messages can be helpful, but they should connect with school practice.","zh":"早會訊息可以有幫助，但應與學校實踐連接。"},{"en":"If fairness is preached in assemblies but not shown in policies, students may lose trust.","zh":"如果公平在早會中被宣講，卻沒有在政策中顯示，學生可能失去信任。"}],"source":"2014 Q5.pdf","sourcePage":6},{"front":"but practised","meaning":"而是被實踐","examples":[{"en":"Fairness should be practised, not only preached.","zh":"公平應被實踐，而不只是被宣講。"},{"en":"But practised means but shown through real actions and decisions.","zh":"but practised 指而是透過實際行動和決定展示。"},{"en":"Respect should be practised by listening to students, not only mentioned in slogans.","zh":"尊重應透過聆聽學生被實踐，而不只是出現在口號中。"},{"en":"Values become real when schools practise them in daily rules.","zh":"當學校在日常規則中實踐價值觀時，價值觀才變得真實。"},{"en":"A transparent locker system is one way fairness can be practised.","zh":"透明儲物櫃制度是公平被實踐的一種方式。"}],"source":"2014 Q5.pdf","sourcePage":6},{"front":"more inclusive","meaning":"更具包容性的","examples":[{"en":"A more inclusive locker policy would benefit more students.","zh":"更具包容性的儲物櫃政策會令更多學生受惠。"},{"en":"More inclusive means designed to include and support a wider range of people.","zh":"more inclusive 指設計上包括並支援更多不同類型的人。"},{"en":"A more inclusive sports day offers activities for students with different abilities.","zh":"更具包容性的運動日會為不同能力的學生提供活動。"},{"en":"Inclusive policies consider students who may otherwise be left out.","zh":"包容性政策會考慮原本可能被遺漏的學生。"},{"en":"A more inclusive locker policy would recognise different needs across forms and subjects.","zh":"更具包容性的儲物櫃政策會承認不同年級和科目的不同需要。"}],"source":"2014 Q5.pdf","sourcePage":7},{"front":"clear health and academic benefits","meaning":"明顯的健康和學業好處","examples":[{"en":"A more inclusive policy would bring clear health and academic benefits.","zh":"更具包容性的政策會帶來明顯的健康和學業好處。"},{"en":"Clear health and academic benefits are obvious advantages for students’ physical well-being and learning.","zh":"clear health and academic benefits 指對學生身體健康和學習有明顯好處。"},{"en":"Lighter bags can bring health benefits by reducing strain on shoulders and backs.","zh":"較輕書包可以透過減少肩背負擔帶來健康好處。"},{"en":"Better access to materials brings academic benefits because students are more prepared.","zh":"更容易取得學習材料會帶來學業好處，因為學生準備更充分。"},{"en":"This phrase shows that locker access affects both bodies and learning.","zh":"這個短語顯示儲物櫃使用機會同時影響身體和學習。"}],"source":"2014 Q5.pdf","sourcePage":7},{"front":"reported that","meaning":"匯報；表示","examples":[{"en":"Several junior-form students reported that their schoolbags were too heavy.","zh":"幾名初中學生表示他們的書包太重。"},{"en":"Reported that means said or stated something, often as information gathered from others.","zh":"reported that 指說出或陳述某事，通常是作為收集到的資訊。"},{"en":"Students reported that the classroom was too hot in the afternoon.","zh":"學生表示下午課室太熱。"},{"en":"A proposal becomes stronger when it includes what students have reported from experience.","zh":"當建議包括學生根據經驗匯報的內容時，會更有力。"},{"en":"This phrase suggests the problem is based on students’ real comments.","zh":"這個短語暗示問題來自學生的真實意見。"}],"source":"2014 Q5.pdf","sourcePage":7},{"front":"so heavy that","meaning":"重得以致","examples":[{"en":"Some schoolbags are so heavy that students leave books at home.","zh":"有些書包重得以致學生把書留在家中。"},{"en":"So heavy that means heavy to such a degree that it causes a result.","zh":"so heavy that 指重到造成某個結果的程度。"},{"en":"The box was so heavy that two students had to carry it together.","zh":"那個箱子重得以致兩名學生要一起搬。"},{"en":"This pattern clearly connects the size of a problem with its consequence.","zh":"這個句式清楚連接問題程度與後果。"},{"en":"If bags are so heavy that students stop bringing books, learning is affected.","zh":"如果書包重得以致學生不帶書，學習便會受影響。"}],"source":"2014 Q5.pdf","sourcePage":7},{"front":"leave reference books at home","meaning":"把參考書留在家中","examples":[{"en":"Students sometimes leave reference books at home.","zh":"學生有時把參考書留在家中。"},{"en":"To leave reference books at home means not to bring study-support books to school.","zh":"leave reference books at home 指不把支援學習的參考書帶回學校。"},{"en":"A student may leave a dictionary at home because the bag is already full.","zh":"學生可能因書包已滿而把字典留在家中。"},{"en":"Leaving reference books at home can make students less prepared for class activities.","zh":"把參考書留在家中可能令學生在課堂活動中準備不足。"},{"en":"Lockers reduce the need to choose between health and preparation.","zh":"儲物櫃減少學生在健康和準備之間作選擇的需要。"}],"source":"2014 Q5.pdf","sourcePage":7},{"front":"only to find themselves","meaning":"結果卻發現自己","examples":[{"en":"Students leave books at home, only to find themselves unprepared.","zh":"學生把書留在家中，結果卻發現自己準備不足。"},{"en":"Only to find themselves means they later discover an unwanted or disappointing result.","zh":"only to find themselves 指他們後來發現一個不想要或令人失望的結果。"},{"en":"A student skipped revision, only to find themselves confused during the quiz.","zh":"學生跳過溫習，結果卻發現自己在小測中很困惑。"},{"en":"This phrase often shows that an action leads to an unexpected problem.","zh":"這個短語常顯示一個行動帶來意想不到的問題。"},{"en":"Here, trying to lighten the bag causes a new academic difficulty.","zh":"在這裏，想減輕書包重量反而造成新的學業困難。"}],"source":"2014 Q5.pdf","sourcePage":7},{"front":"unprepared during lessons","meaning":"上課時準備不足","examples":[{"en":"Students may find themselves unprepared during lessons.","zh":"學生可能發現自己上課時準備不足。"},{"en":"Unprepared during lessons means not having the materials, knowledge, or readiness needed for class.","zh":"unprepared during lessons 指沒有課堂所需的材料、知識或準備。"},{"en":"A student is unprepared during lessons if their textbook or notes are at home.","zh":"如果課本或筆記留在家中，學生上課時就準備不足。"},{"en":"Being unprepared can make students anxious and less able to participate.","zh":"準備不足會令學生焦慮，也較難參與課堂。"},{"en":"Lockers help students stay prepared without carrying every book all day.","zh":"儲物櫃幫助學生保持準備充分，而不用整天攜帶每本書。"}],"source":"2014 Q5.pdf","sourcePage":7},{"front":"senior students","meaning":"高中學生","examples":[{"en":"Senior students preparing for public examinations face a similar problem.","zh":"準備公開考試的高中學生面對類似問題。"},{"en":"Senior students are older students in the higher forms of secondary school.","zh":"senior students 指中學高年級學生。"},{"en":"Senior students often carry more notes because their subjects are more specialised.","zh":"高中學生常攜帶更多筆記，因為他們的科目更專門。"},{"en":"They may need lockers to manage exam materials, textbooks, and activity items.","zh":"他們可能需要儲物櫃來管理考試材料、課本和活動物品。"},{"en":"Their needs matter because academic pressure increases in senior forms.","zh":"他們的需要很重要，因為高中年級的學業壓力增加。"}],"source":"2014 Q5.pdf","sourcePage":7},{"front":"public examinations","meaning":"公開考試","examples":[{"en":"Senior students are preparing for public examinations.","zh":"高中學生正在準備公開考試。"},{"en":"Public examinations are major exams taken by many students and recognised beyond one school.","zh":"public examinations 指由許多學生參加並受校外認可的重要考試。"},{"en":"Students preparing for public examinations often need past papers and reference books.","zh":"準備公開考試的學生常需要歷屆試題和參考書。"},{"en":"Public examinations create pressure because results may affect future study choices.","zh":"公開考試造成壓力，因為成績可能影響未來升學選擇。"},{"en":"Lockers can support students preparing for these exams by keeping materials organised.","zh":"儲物櫃可以透過讓材料更有條理，支援準備公開考試的學生。"}],"source":"2014 Q5.pdf","sourcePage":7},{"front":"face a similar problem","meaning":"面對類似問題","examples":[{"en":"Senior students face a similar problem: they need many materials on the same day.","zh":"高中學生面對類似問題：他們同一天需要許多材料。"},{"en":"To face a similar problem means to experience a problem like the one already mentioned.","zh":"face a similar problem 指經歷與剛提到的問題相似的困難。"},{"en":"Junior students carry art supplies, and senior students face a similar problem with exam files.","zh":"初中學生攜帶美術用品，而高中學生在考試文件方面面對類似問題。"},{"en":"This phrase links different groups by showing their difficulties are connected.","zh":"這個短語透過顯示困難相連，把不同群體連接起來。"},{"en":"The similarity supports the argument that lockers should help more than one form level.","zh":"這種相似性支持儲物櫃應幫助不止一個年級的論點。"}],"source":"2014 Q5.pdf","sourcePage":7},{"front":"past-paper folders","meaning":"歷屆試題文件夾","examples":[{"en":"Senior students may need past-paper folders.","zh":"高中學生可能需要歷屆試題文件夾。"},{"en":"Past-paper folders are files used to keep previous exam papers and practice questions.","zh":"past-paper folders 指用來存放過往考試卷和練習題的文件夾。"},{"en":"A student may organise past-paper folders by subject before public examinations.","zh":"學生可能在公開考試前按科目整理歷屆試題文件夾。"},{"en":"Past-paper folders can become heavy when students collect many years of papers.","zh":"當學生收集多年試題時，歷屆試題文件夾可能變得很重。"},{"en":"Lockers help students keep these folders at school for revision lessons.","zh":"儲物櫃幫助學生把這些文件夾留在學校，以便溫習課使用。"}],"source":"2014 Q5.pdf","sourcePage":8},{"front":"dictionaries","meaning":"字典","examples":[{"en":"Students may need dictionaries for their studies.","zh":"學生學習時可能需要字典。"},{"en":"Dictionaries are reference books or tools that explain word meanings, pronunciation, and usage.","zh":"dictionaries 指解釋字義、發音和用法的參考書或工具。"},{"en":"English learners use dictionaries to check unfamiliar words during reading.","zh":"英文學習者閱讀時會用字典查陌生字。"},{"en":"Printed dictionaries can be heavy, but they are useful in lessons and exams.","zh":"紙本字典可能很重，但在課堂和考試中很有用。"},{"en":"Lockers give students a place to keep dictionaries without carrying them every day.","zh":"儲物櫃讓學生有地方存放字典，而不用每天攜帶。"}],"source":"2014 Q5.pdf","sourcePage":8},{"front":"laboratory manuals","meaning":"實驗手冊","examples":[{"en":"Science students may need laboratory manuals.","zh":"科學科學生可能需要實驗手冊。"},{"en":"Laboratory manuals are books or booklets that give instructions for experiments and safety procedures.","zh":"laboratory manuals 指提供實驗步驟和安全程序的書本或小冊子。"},{"en":"Students use laboratory manuals to check equipment, steps, and observations.","zh":"學生使用實驗手冊來查看器材、步驟和觀察內容。"},{"en":"A laboratory manual is important because mistakes in experiments can be unsafe.","zh":"實驗手冊很重要，因為實驗錯誤可能不安全。"},{"en":"Lockers help science students store manuals for days when experiments are scheduled.","zh":"儲物櫃幫助科學科學生為有實驗的日子存放手冊。"}],"source":"2014 Q5.pdf","sourcePage":8},{"front":"supplementary notes","meaning":"補充筆記","examples":[{"en":"Students may need supplementary notes on the same day.","zh":"學生可能同一天需要補充筆記。"},{"en":"Supplementary notes are extra notes that support textbooks or explain additional details.","zh":"supplementary notes 指支援課本或解釋額外細節的補充資料。"},{"en":"Teachers may give supplementary notes before exams to cover difficult topics.","zh":"老師可能在考試前派發補充筆記，以處理困難課題。"},{"en":"These notes can pile up quickly and make schoolbags heavier.","zh":"這些筆記會很快累積，令書包更重。"},{"en":"A locker helps students organise supplementary notes by subject.","zh":"儲物櫃幫助學生按科目整理補充筆記。"}],"source":"2014 Q5.pdf","sourcePage":8},{"front":"on the same day","meaning":"同一天","examples":[{"en":"Students may need several types of materials on the same day.","zh":"學生可能同一天需要幾種不同材料。"},{"en":"On the same day means during one particular school day, not across different days.","zh":"on the same day 指在同一個特定上學日內，而不是分散在不同日子。"},{"en":"A student may need PE clothes, art supplies, and science notes on the same day.","zh":"學生可能同一天需要體育服、美術用品和科學筆記。"},{"en":"The problem becomes harder when many heavy items are needed together.","zh":"當許多沉重物品同時需要時，問題會更困難。"},{"en":"Lockers help because students do not have to carry every possible item on the same day.","zh":"儲物櫃有幫助，因為學生不用同一天攜帶所有可能需要的物品。"}],"source":"2014 Q5.pdf","sourcePage":8},{"front":"shoulders and backs suffer","meaning":"肩膀和背部受苦","examples":[{"en":"If students carry everything, their shoulders and backs suffer.","zh":"如果學生攜帶所有東西，他們的肩膀和背部會受苦。"},{"en":"Shoulders and backs suffer means those body parts feel pain, strain, or tiredness.","zh":"shoulders and backs suffer 指這些身體部位感到疼痛、負擔或疲倦。"},{"en":"Carrying a heavy bag every day can make a student’s shoulders and back suffer.","zh":"每天背沉重書包會令學生的肩膀和背部受苦。"},{"en":"Physical strain affects learning because pain makes concentration harder.","zh":"身體負擔會影響學習，因為疼痛令專注更困難。"},{"en":"Lockers can reduce the weight students carry and protect their bodies.","zh":"儲物櫃可以減少學生攜帶的重量，保護身體。"}],"source":"2014 Q5.pdf","sourcePage":8},{"front":"neither choice is satisfactory","meaning":"兩個選擇都不理想","examples":[{"en":"Neither choice is satisfactory for students.","zh":"對學生來說，兩個選擇都不理想。"},{"en":"Neither choice is satisfactory means both options are poor or unacceptable.","zh":"neither choice is satisfactory 指兩個選項都不好或不能令人接受。"},{"en":"Carrying all books hurts health, but leaving them at home hurts preparation; neither choice is satisfactory.","zh":"帶齊所有書會傷害健康，但把書留在家中會令準備不足；兩個選擇都不理想。"},{"en":"This phrase is useful when people are forced between two bad options.","zh":"當人們被迫在兩個差選項之間選擇時，這個短語很有用。"},{"en":"A fair locker system offers a better third option.","zh":"公平儲物櫃制度提供更好的第三個選擇。"}],"source":"2014 Q5.pdf","sourcePage":8},{"front":"break this unhealthy trade-off","meaning":"打破這種不健康的取捨","examples":[{"en":"A locker can break this unhealthy trade-off.","zh":"儲物櫃可以打破這種不健康的取捨。"},{"en":"To break this unhealthy trade-off means to remove the need to choose between two harmful options.","zh":"break this unhealthy trade-off 指消除在兩個有害選項之間作選擇的需要。"},{"en":"Online notes can break the trade-off between carrying heavy files and being unprepared.","zh":"網上筆記可以打破攜帶沉重文件與準備不足之間的取捨。"},{"en":"A good solution reduces pressure on both health and learning.","zh":"好解決方法會同時減少健康和學習上的壓力。"},{"en":"Lockers break the trade-off by letting students store materials safely at school.","zh":"儲物櫃透過讓學生安全在校存放材料，打破這種取捨。"}],"source":"2014 Q5.pdf","sourcePage":8},{"front":"unhealthy trade-off","meaning":"不健康的取捨","examples":[{"en":"Students face an unhealthy trade-off between health and preparation.","zh":"學生面對健康與準備之間的不健康取捨。"},{"en":"An unhealthy trade-off is a choice where gaining one benefit means harming another important need.","zh":"unhealthy trade-off 指得到一種好處時，卻傷害另一個重要需要的選擇。"},{"en":"Skipping sleep to study creates an unhealthy trade-off between marks and health.","zh":"為溫習而不睡覺，造成成績和健康之間的不健康取捨。"},{"en":"Students should not have to choose between a lighter bag and being ready for lessons.","zh":"學生不應被迫在較輕書包和準備上課之間作選擇。"},{"en":"The phrase shows that the current system creates a harmful dilemma.","zh":"這個短語顯示現行制度造成有害兩難。"}],"source":"2014 Q5.pdf","sourcePage":8},{"front":"non-urgent books","meaning":"非急用書本","examples":[{"en":"Students could keep non-urgent books at school.","zh":"學生可以把非急用書本留在學校。"},{"en":"Non-urgent books are books that are useful but not needed immediately at home.","zh":"non-urgent books 指有用但不需要立即在家使用的書本。"},{"en":"A student may keep a dictionary or atlas as non-urgent books in a locker.","zh":"學生可能把字典或地圖冊等非急用書本放在儲物櫃。"},{"en":"Storing non-urgent books reduces bag weight without harming preparation.","zh":"存放非急用書本能減輕書包重量，而不影響準備。"},{"en":"Lockers help students separate what must go home from what can stay at school.","zh":"儲物櫃幫助學生分清甚麼必須帶回家，甚麼可以留在學校。"}],"source":"2014 Q5.pdf","sourcePage":8},{"front":"bring home only what they need","meaning":"只帶回所需物品","examples":[{"en":"Students could bring home only what they need for homework.","zh":"學生可以只帶回做功課所需的物品。"},{"en":"To bring home only what they need means to take back only the materials required for that night’s tasks.","zh":"bring home only what they need 指只把當晚任務所需的材料帶回家。"},{"en":"A student may bring home only the maths book if the homework is for maths.","zh":"如果功課是數學，學生可能只帶數學書回家。"},{"en":"This habit reduces unnecessary carrying and helps students organise work better.","zh":"這個習慣減少不必要攜帶，也幫助學生更好整理功課。"},{"en":"Lockers make this possible because extra materials can stay safely at school.","zh":"儲物櫃令這件事可行，因為額外材料可以安全留在學校。"}],"source":"2014 Q5.pdf","sourcePage":9},{"front":"organise materials by subject","meaning":"按科目整理物品","examples":[{"en":"Students could organise materials by subject.","zh":"學生可以按科目整理物品。"},{"en":"To organise materials by subject means to sort books, notes, and files according to school subjects.","zh":"organise materials by subject 指按學科分類書本、筆記和文件。"},{"en":"A student may keep English notes on one shelf and science manuals in another folder.","zh":"學生可能把英文筆記放在一層，把科學手冊放在另一個文件夾。"},{"en":"Organising by subject helps students find the right materials quickly.","zh":"按科目整理有助學生快速找到正確材料。"},{"en":"Lockers support this habit because students have a fixed storage space.","zh":"儲物櫃支援這個習慣，因為學生有固定存放空間。"}],"source":"2014 Q5.pdf","sourcePage":9},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, wider locker access improves health and learning.","zh":"換句話說，更廣泛的儲物櫃使用機會能改善健康和學習。"},{"en":"In other words is used to restate an idea more clearly or simply.","zh":"in other words 用來以更清楚或更簡單的方式重述想法。"},{"en":"The bags are too heavy; in other words, students need storage support.","zh":"書包太重；換句話說，學生需要儲物支援。"},{"en":"This phrase helps readers understand the main point after examples.","zh":"這個短語幫助讀者在例子後理解重點。"},{"en":"It connects the details about bags and books to the larger argument.","zh":"它把關於書包和書本的細節連接到更大的論點。"}],"source":"2014 Q5.pdf","sourcePage":9},{"front":"wider locker access","meaning":"更廣泛的儲物櫃使用機會","examples":[{"en":"Wider locker access translates into better preparation.","zh":"更廣泛的儲物櫃使用機會會帶來更充分準備。"},{"en":"Wider locker access means more students are able to use lockers.","zh":"wider locker access 指更多學生能使用儲物櫃。"},{"en":"Wider locker access would help students with heavy books, musical instruments, and sports gear.","zh":"更廣泛的儲物櫃使用機會會幫助有沉重書本、樂器和運動用品的學生。"},{"en":"When locker access is wider, fewer students are forced to carry everything all day.","zh":"當使用機會更廣時，較少學生被迫整天攜帶所有東西。"},{"en":"Wider access makes a school facility more useful to the whole student body.","zh":"更廣泛使用機會令學校設施對整個學生群體更有用。"}],"source":"2014 Q5.pdf","sourcePage":9},{"front":"translates into","meaning":"轉化為；帶來","examples":[{"en":"Wider locker access translates into better health and learning.","zh":"更廣泛的儲物櫃使用機會會轉化為更好的健康和學習。"},{"en":"Translates into means leads to or becomes a clear practical result.","zh":"translates into 指帶來或變成清楚的實際結果。"},{"en":"Better sleep translates into stronger concentration during morning lessons.","zh":"更好的睡眠會轉化為早上課堂中更強的專注力。"},{"en":"A clear timetable can translate into less stress for students.","zh":"清晰時間表可以帶來學生壓力減少。"},{"en":"In this case, more locker access translates into lighter bags and better preparation.","zh":"在這情況下，更多儲物櫃使用機會轉化為較輕書包和更充分準備。"}],"source":"2014 Q5.pdf","sourcePage":9},{"front":"better preparation","meaning":"更充分準備","examples":[{"en":"Lockers can help students achieve better preparation.","zh":"儲物櫃可以幫助學生做到更充分準備。"},{"en":"Better preparation means being more ready with the right materials, knowledge, and organisation.","zh":"better preparation 指在材料、知識和組織方面準備得更好。"},{"en":"A student has better preparation when all notes and textbooks are available for the lesson.","zh":"當所有筆記和課本都可供課堂使用時，學生就有更充分準備。"},{"en":"Better preparation leads to more confident participation in class.","zh":"更充分準備會帶來課堂上更有信心的參與。"},{"en":"Lockers support preparation by keeping useful materials close to students.","zh":"儲物櫃透過把有用材料放近學生，支援準備。"}],"source":"2014 Q5.pdf","sourcePage":9},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, the school may be concerned about cost and space.","zh":"誠然，學校可能擔心成本和空間。"},{"en":"Granted means the writer accepts that a point is true before explaining why it does not end the argument.","zh":"granted 指作者承認某一點是真的，然後解釋為何它不會結束論點。"},{"en":"Granted, the plan will take time, but it can still bring long-term benefits.","zh":"誠然，這項計劃需要時間，但它仍可以帶來長遠好處。"},{"en":"This word helps an argument sound balanced and reasonable.","zh":"這個詞令論點聽起來平衡而合理。"},{"en":"Here, the writer admits the school has practical concerns.","zh":"在這裏，作者承認學校有實際憂慮。"}],"source":"2014 Q5.pdf","sourcePage":9},{"front":"be concerned about","meaning":"擔心","examples":[{"en":"The school may be concerned about cost, space and management.","zh":"學校可能擔心成本、空間和管理。"},{"en":"To be concerned about something means to feel worried or careful about it.","zh":"be concerned about something 指對某事感到擔憂或小心。"},{"en":"Parents may be concerned about students carrying heavy bags every day.","zh":"家長可能擔心學生每天背沉重書包。"},{"en":"Schools are concerned about safety when placing new furniture in corridors.","zh":"學校在走廊放置新家具時會擔心安全。"},{"en":"Concern is reasonable, but it should lead to planning rather than inaction.","zh":"擔心是合理的，但應引向規劃，而不是無所作為。"}],"source":"2014 Q5.pdf","sourcePage":9},{"front":"cost, space and management","meaning":"成本、空間和管理","examples":[{"en":"The school may consider cost, space and management.","zh":"學校可能考慮成本、空間和管理。"},{"en":"Cost, space and management are practical issues involving money, physical room, and daily operation.","zh":"cost, space and management 指涉及金錢、實際地方和日常運作的實際問題。"},{"en":"A new canteen queue system must consider cost, space and management.","zh":"新飯堂排隊制度必須考慮成本、空間和管理。"},{"en":"These factors matter because even good ideas need resources and rules.","zh":"這些因素很重要，因為即使好想法也需要資源和規則。"},{"en":"The proposal accepts these concerns but argues they can be handled carefully.","zh":"這項建議承認這些憂慮，但主張它們可以被小心處理。"}],"source":"2014 Q5.pdf","sourcePage":9},{"front":"reasons for careful planning","meaning":"需要審慎規劃的理由","examples":[{"en":"These concerns are reasons for careful planning.","zh":"這些憂慮是需要審慎規劃的理由。"},{"en":"Reasons for careful planning are factors that show why a plan must be designed thoughtfully.","zh":"reasons for careful planning 指顯示計劃必須被周詳設計的因素。"},{"en":"Safety concerns are reasons for careful planning before a school trip.","zh":"安全憂慮是學校旅行前需要審慎規劃的理由。"},{"en":"Difficulties do not always mean an idea should be rejected.","zh":"困難不一定代表一個想法應被拒絕。"},{"en":"Cost and space should push the school to plan well, not to ignore the problem.","zh":"成本和空間應推動學校好好規劃，而不是忽視問題。"}],"source":"2014 Q5.pdf","sourcePage":9},{"front":"reasons for doing nothing","meaning":"無所作為的理由","examples":[{"en":"These concerns should not become reasons for doing nothing.","zh":"這些憂慮不應變成無所作為的理由。"},{"en":"Reasons for doing nothing are excuses or arguments used to avoid taking action.","zh":"reasons for doing nothing 指用來避免採取行動的藉口或論據。"},{"en":"Limited money should not become a reason for doing nothing about student safety.","zh":"資金有限不應成為不處理學生安全的理由。"},{"en":"When a problem affects students every day, inaction can also cause harm.","zh":"當問題每天影響學生時，無所作為也可能造成傷害。"},{"en":"The writer argues that concerns should lead to gradual action, not silence.","zh":"作者主張憂慮應帶來逐步行動，而不是沉默。"}],"source":"2014 Q5.pdf","sourcePage":10},{"front":"install hundreds of lockers","meaning":"安裝數百個儲物櫃","examples":[{"en":"The students are not asking the school to install hundreds of lockers overnight.","zh":"學生並不是要求學校一夜之間安裝數百個儲物櫃。"},{"en":"To install hundreds of lockers means to put in place a very large number of lockers.","zh":"install hundreds of lockers 指設置非常大量的儲物櫃。"},{"en":"A school may install lockers in corridors, near staircases, or beside special rooms.","zh":"學校可能在走廊、樓梯旁或特別室附近安裝儲物櫃。"},{"en":"Installing hundreds of lockers at once may be costly and difficult to manage.","zh":"一次過安裝數百個儲物櫃可能成本高，而且難以管理。"},{"en":"The proposal sounds reasonable because it does not demand everything immediately.","zh":"這項建議聽起來合理，因為它沒有要求立即完成所有事情。"}],"source":"2014 Q5.pdf","sourcePage":10},{"front":"overnight","meaning":"一夜之間；立即","examples":[{"en":"The school does not need to install all the lockers overnight.","zh":"學校不需要一夜之間安裝所有儲物櫃。"},{"en":"Overnight means very quickly or suddenly, often within a very short time.","zh":"overnight 指非常快速或突然地，通常是在很短時間內。"},{"en":"A school culture cannot change overnight; it needs repeated action.","zh":"學校文化不能一夜之間改變；它需要重複行動。"},{"en":"This word is useful when explaining that gradual progress is acceptable.","zh":"這個詞在解釋逐步進展是可接受時很有用。"},{"en":"The writer is not asking for an overnight solution, but a realistic plan.","zh":"作者不是要求一夜之間解決，而是要求實際計劃。"}],"source":"2014 Q5.pdf","sourcePage":10},{"front":"three-step plan","meaning":"三步計劃","examples":[{"en":"The Student Union proposes a three-step plan.","zh":"學生會提出一個三步計劃。"},{"en":"A three-step plan is a proposal divided into three clear stages or actions.","zh":"three-step plan 指分成三個清晰階段或行動的建議。"},{"en":"A study group may use a three-step plan: review, practise, and reflect.","zh":"溫習小組可能使用三步計劃：複習、練習和反思。"},{"en":"Three-step plans are easy to follow because readers can see the order.","zh":"三步計劃容易跟隨，因為讀者能看見次序。"},{"en":"The phrase makes the proposal sound organised and manageable.","zh":"這個短語令建議聽起來有組織並可管理。"}],"source":"2014 Q5.pdf","sourcePage":10},{"front":"conduct an audit","meaning":"進行審查","examples":[{"en":"The school could conduct an audit of underused spaces.","zh":"學校可以對未充分使用的空間進行審查。"},{"en":"To conduct an audit means to examine something carefully and record what is available or missing.","zh":"conduct an audit 指仔細檢查某事物，並記錄可用或缺少的東西。"},{"en":"A library may conduct an audit to see which books are rarely borrowed.","zh":"圖書館可能進行審查，以了解哪些書很少被借閱。"},{"en":"An audit helps decisions become based on facts rather than guesses.","zh":"審查幫助決定建基於事實，而不是猜測。"},{"en":"Before buying lockers, the school should audit possible storage locations.","zh":"在購買儲物櫃前，學校應審查可能的存放位置。"}],"source":"2014 Q5.pdf","sourcePage":10},{"front":"underused spaces","meaning":"未充分使用的空間","examples":[{"en":"The school could find underused spaces for lockers.","zh":"學校可以尋找未充分使用的空間放置儲物櫃。"},{"en":"Underused spaces are places that are not being used fully or effectively.","zh":"underused spaces 指沒有被充分或有效使用的地方。"},{"en":"An empty corner beside a staircase may be an underused space.","zh":"樓梯旁一個空角落可能是未充分使用的空間。"},{"en":"Schools can solve space problems by looking carefully at underused areas.","zh":"學校可以透過仔細檢視未充分使用的地方來解決空間問題。"},{"en":"Using underused spaces for lockers may improve facilities without building new rooms.","zh":"使用未充分使用的空間放儲物櫃，可能不用興建新房間也能改善設施。"}],"source":"2014 Q5.pdf","sourcePage":10},{"front":"areas beside staircases","meaning":"樓梯旁的地方","examples":[{"en":"Lockers could be placed in areas beside staircases.","zh":"儲物櫃可以放在樓梯旁的地方。"},{"en":"Areas beside staircases are spaces next to stairs that may be suitable for storage if safe.","zh":"areas beside staircases 指樓梯旁邊的空間，如安全，可能適合存放物品。"},{"en":"A school may use areas beside staircases for noticeboards or small shelves.","zh":"學校可能使用樓梯旁的地方放告示板或小書架。"},{"en":"These areas must be checked carefully so they do not block movement or exits.","zh":"這些地方必須仔細檢查，確保不會阻礙通行或出口。"},{"en":"If used safely, staircase areas can provide extra locker space.","zh":"如果安全使用，樓梯旁的地方可以提供額外儲物櫃空間。"}],"source":"2014 Q5.pdf","sourcePage":10},{"front":"covered playground walls","meaning":"有蓋操場牆邊","examples":[{"en":"Covered playground walls may provide space for lockers.","zh":"有蓋操場牆邊可能提供放置儲物櫃的空間。"},{"en":"Covered playground walls are wall areas in a sheltered playground protected from rain.","zh":"covered playground walls 指受遮蓋、避免雨水影響的操場牆邊位置。"},{"en":"Schools may place benches or sports notices along covered playground walls.","zh":"學校可能在有蓋操場牆邊放長椅或體育告示。"},{"en":"Such walls may be useful because students pass them often but do not use all the space.","zh":"這些牆邊可能有用，因為學生常經過，但空間未必全被使用。"},{"en":"The school must still check safety, weather protection, and crowd movement before adding lockers.","zh":"加設儲物櫃前，學校仍必須檢查安全、避雨和人流。"}],"source":"2014 Q5.pdf","sourcePage":10},{"front":"corners near special rooms","meaning":"特別室附近的角落","examples":[{"en":"The school could use corners near special rooms.","zh":"學校可以使用特別室附近的角落。"},{"en":"Corners near special rooms are small spaces close to rooms such as laboratories, music rooms, or art rooms.","zh":"corners near special rooms 指靠近實驗室、音樂室或美術室等房間的小角落。"},{"en":"These corners may suit lockers for students who carry special subject materials.","zh":"這些角落可能適合放置儲物櫃，供攜帶特殊科目材料的學生使用。"},{"en":"However, the school must ensure that corners do not become crowded or unsafe.","zh":"不過，學校必須確保角落不會變得擁擠或不安全。"},{"en":"Using such corners wisely can match storage space with subject needs.","zh":"善用這些角落，可以把儲物空間與科目需要配合。"}],"source":"2014 Q5.pdf","sourcePage":10},{"front":"while ensuring","meaning":"同時確保","examples":[{"en":"The school could add lockers while ensuring fire safety.","zh":"學校可以加設儲物櫃，同時確保消防安全。"},{"en":"While ensuring means doing one action and at the same time making sure another important condition is protected.","zh":"while ensuring 指做一件事時，同時確保另一個重要條件受到保護。"},{"en":"A school can add more seating while ensuring corridors remain clear.","zh":"學校可以增加座位，同時確保走廊保持暢通。"},{"en":"This phrase helps show that improvement and safety can happen together.","zh":"這個短語有助顯示改善和安全可以同時進行。"},{"en":"Locker expansion should happen while ensuring students can move safely.","zh":"擴大儲物櫃使用應在同時確保學生能安全通行下進行。"}],"source":"2014 Q5.pdf","sourcePage":10},{"front":"fire safety","meaning":"消防安全","examples":[{"en":"Fire safety must not be compromised.","zh":"消防安全絕不能受損。"},{"en":"Fire safety means rules and arrangements that reduce fire risk and help people escape safely.","zh":"fire safety 指減低火警風險並幫助人安全逃生的規則和安排。"},{"en":"Clear exits, working alarms, and open corridors are important for fire safety.","zh":"清晰出口、正常運作的警鐘和暢通走廊對消防安全很重要。"},{"en":"Lockers should not block emergency routes because fire safety is more important than convenience.","zh":"儲物櫃不應阻塞緊急通道，因為消防安全比方便更重要。"},{"en":"A good plan improves storage while protecting fire safety.","zh":"好計劃會改善儲物空間，同時保障消防安全。"}],"source":"2014 Q5.pdf","sourcePage":11},{"front":"not be compromised","meaning":"不受損害；不被削弱","examples":[{"en":"Fire safety must not be compromised.","zh":"消防安全絕不能受損害。"},{"en":"Not be compromised means not be weakened, damaged, or sacrificed.","zh":"not be compromised 指不能被削弱、損害或犧牲。"},{"en":"Student safety must not be compromised even if an event needs more space.","zh":"即使活動需要更多空間，學生安全也不能受損害。"},{"en":"This phrase is used when one important value cannot be traded away.","zh":"當某個重要價值不能被交換掉時，會使用這個短語。"},{"en":"The school can expand locker access, but safety must remain protected.","zh":"學校可以擴大儲物櫃使用機會，但安全必須繼續受保障。"}],"source":"2014 Q5.pdf","sourcePage":11},{"front":"introduced in phases","meaning":"分階段推出","examples":[{"en":"Lockers could be introduced in phases.","zh":"儲物櫃可以分階段推出。"},{"en":"Introduced in phases means brought in gradually, one stage at a time.","zh":"introduced in phases 指逐步引入，一個階段接一個階段。"},{"en":"A new lunch system may be introduced in phases, starting with two forms first.","zh":"新午膳制度可能分階段推出，先由兩個年級開始。"},{"en":"Introducing lockers in phases helps the school test the system before expanding it.","zh":"分階段推出儲物櫃，能幫助學校在擴大前測試制度。"},{"en":"Gradual introduction can reduce cost, confusion, and management pressure.","zh":"逐步推出可以減少成本、混亂和管理壓力。"}],"source":"2014 Q5.pdf","sourcePage":11},{"front":"beginning with","meaning":"由……開始","examples":[{"en":"The system could begin with students who have genuine needs.","zh":"制度可以由有真正需要的學生開始。"},{"en":"Beginning with means starting from a particular group, step, or point.","zh":"beginning with 指由某個群體、步驟或起點開始。"},{"en":"A school may begin with senior students when introducing extra study rooms.","zh":"學校引入額外自修室時，可能由高中學生開始。"},{"en":"Starting with the most urgent needs helps limited resources reach the right people first.","zh":"由最迫切需要開始，能幫助有限資源先到達合適的人。"},{"en":"This phrase supports a gradual and need-based approach.","zh":"這個短語支持逐步和按需要的做法。"}],"source":"2014 Q5.pdf","sourcePage":11},{"front":"genuine needs","meaning":"真正需要","examples":[{"en":"Some students have genuine needs for lockers.","zh":"有些學生對儲物櫃有真正需要。"},{"en":"Genuine needs are real and reasonable needs, not just preferences or wishes.","zh":"genuine needs 指真實而合理的需要，而不只是喜好或願望。"},{"en":"A student with back pain may have a genuine need for a locker.","zh":"有背痛的學生可能真正需要儲物櫃。"},{"en":"Genuine needs should be considered when resources are limited.","zh":"當資源有限時，真正需要應被考慮。"},{"en":"A need-sensitive policy gives priority to students whose daily burden is clearly heavier.","zh":"顧及需要的政策會優先照顧每日負擔明顯較重的學生。"}],"source":"2014 Q5.pdf","sourcePage":11},{"front":"medical conditions","meaning":"健康狀況；疾病","examples":[{"en":"Students with medical conditions may need lockers first.","zh":"有健康狀況的學生可能需要優先使用儲物櫃。"},{"en":"Medical conditions are health problems or illnesses that affect a person’s body or daily life.","zh":"medical conditions 指影響身體或日常生活的健康問題或疾病。"},{"en":"A student with a back condition may be unable to carry a heavy bag safely.","zh":"有背部疾病的學生可能不能安全背沉重書包。"},{"en":"Schools should consider medical conditions when deciding who needs support most urgently.","zh":"學校決定誰最迫切需要支援時，應考慮健康狀況。"},{"en":"Lockers can reduce physical strain for students with health difficulties.","zh":"儲物櫃可以為有健康困難的學生減少身體負擔。"}],"source":"2014 Q5.pdf","sourcePage":11},{"front":"long travelling distances","meaning":"遙遠上學路程","examples":[{"en":"Students with long travelling distances may need lockers.","zh":"上學路程遙遠的學生可能需要儲物櫃。"},{"en":"Long travelling distances means a long journey between home and school.","zh":"long travelling distances 指家與學校之間的長途路程。"},{"en":"A student who travels over an hour each way has a long travelling distance.","zh":"每程要坐超過一小時車的學生，就有遙遠上學路程。"},{"en":"Carrying heavy bags over long distances can be tiring and unhealthy.","zh":"長途攜帶沉重書包會令人疲倦，也不健康。"},{"en":"Lockers help these students bring fewer items home each day.","zh":"儲物櫃幫助這些學生每天帶較少物品回家。"}],"source":"2014 Q5.pdf","sourcePage":11},{"front":"heavy subject combinations","meaning":"繁重的科目組合","examples":[{"en":"Students with heavy subject combinations may carry more materials.","zh":"修讀繁重科目組合的學生可能攜帶更多材料。"},{"en":"Heavy subject combinations are sets of subjects that require many books, notes, or equipment.","zh":"heavy subject combinations 指需要許多書本、筆記或器材的科目組合。"},{"en":"A student taking three science subjects may have a heavy subject combination.","zh":"修讀三個科學科的學生可能有繁重科目組合。"},{"en":"These combinations can make schoolbags heavy even when students pack carefully.","zh":"即使學生仔細收拾，這些科目組合仍可能令書包沉重。"},{"en":"Locker priority may reasonably consider students with heavier subject demands.","zh":"儲物櫃優先安排可以合理考慮科目負擔較重的學生。"}],"source":"2014 Q5.pdf","sourcePage":11},{"front":"regular after-school activities","meaning":"恆常課後活動","examples":[{"en":"Students with regular after-school activities may need storage space.","zh":"有恆常課後活動的學生可能需要儲物空間。"},{"en":"Regular after-school activities are activities students attend repeatedly after lessons.","zh":"regular after-school activities 指學生放學後定期參加的活動。"},{"en":"Sports teams, orchestra practice, and debate training can be regular after-school activities.","zh":"運動隊、樂團練習和辯論訓練都可以是恆常課後活動。"},{"en":"Students with these activities may need to carry extra clothes, instruments, or files.","zh":"有這些活動的學生可能需要攜帶額外衣物、樂器或文件。"},{"en":"Lockers help them manage both academic materials and activity equipment.","zh":"儲物櫃幫助他們同時管理學習材料和活動用品。"}],"source":"2014 Q5.pdf","sourcePage":11},{"front":"funded partly through","meaning":"部分透過……資助","examples":[{"en":"The system could be funded partly through a refundable deposit.","zh":"這制度可以部分透過可退還按金資助。"},{"en":"Funded partly through means some of the money would come from a particular source.","zh":"funded partly through 指部分資金來自某個特定來源。"},{"en":"A school trip may be funded partly through donations and partly through student payments.","zh":"學校旅行可能部分透過捐款、部分透過學生付款資助。"},{"en":"Partial funding can make a plan more realistic when one source is not enough.","zh":"當單一資金來源不足時，部分資助能令計劃更實際。"},{"en":"A refundable deposit could help pay for management while remaining fair to students.","zh":"可退還按金可以幫助支付管理費用，同時對學生保持公平。"}],"source":"2014 Q5.pdf","sourcePage":11},{"front":"refundable deposit","meaning":"可退還按金","examples":[{"en":"Students could pay a refundable deposit for lockers.","zh":"學生可以為儲物櫃支付可退還按金。"},{"en":"A refundable deposit is money paid first and returned later if rules are followed.","zh":"refundable deposit 指先支付、如遵守規則便之後退回的金錢。"},{"en":"Students may pay a refundable deposit when borrowing expensive equipment.","zh":"學生借用昂貴器材時，可能需要支付可退還按金。"},{"en":"A deposit encourages users to take care of shared facilities.","zh":"按金鼓勵使用者好好照顧共享設施。"},{"en":"A refundable deposit can support responsibility without becoming a permanent fee.","zh":"可退還按金可以支援責任感，而不變成永久費用。"}],"source":"2014 Q5.pdf","sourcePage":12},{"front":"school resources","meaning":"學校資源","examples":[{"en":"The policy could be funded partly through school resources.","zh":"這項政策可以部分透過學校資源資助。"},{"en":"School resources are the money, space, staff, equipment, and materials available to a school.","zh":"school resources 指學校可用的金錢、空間、員工、設備和材料。"},{"en":"A school may use resources to improve classrooms, libraries, or sports facilities.","zh":"學校可能使用資源改善課室、圖書館或體育設施。"},{"en":"Resources must be planned carefully because many departments need support.","zh":"資源必須仔細規劃，因為許多部門都需要支援。"},{"en":"Using school resources for lockers shows that student well-being is a priority.","zh":"使用學校資源改善儲物櫃，顯示學生身心健康是優先事項。"}],"source":"2014 Q5.pdf","sourcePage":12},{"front":"alumni donations","meaning":"校友捐款","examples":[{"en":"Alumni donations could help fund the lockers.","zh":"校友捐款可以幫助資助儲物櫃。"},{"en":"Alumni donations are gifts of money or resources given by former students.","zh":"alumni donations 指舊生捐出的金錢或資源。"},{"en":"Alumni donations may support scholarships, library books, or new facilities.","zh":"校友捐款可能支援獎學金、圖書館書籍或新設施。"},{"en":"Former students may donate when they understand how the project helps current students.","zh":"當舊生明白項目如何幫助現時學生時，可能願意捐款。"},{"en":"Locker funding through alumni donations could connect past students with present needs.","zh":"透過校友捐款資助儲物櫃，可以把舊生與現時需要連接起來。"}],"source":"2014 Q5.pdf","sourcePage":12},{"front":"prevent misuse","meaning":"防止濫用","examples":[{"en":"The school can set rules to prevent misuse.","zh":"學校可以制定規則防止濫用。"},{"en":"To prevent misuse means to stop people from using something wrongly or irresponsibly.","zh":"prevent misuse 指阻止人們錯誤或不負責任地使用某物。"},{"en":"Clear library rules prevent misuse of computers and study rooms.","zh":"清晰圖書館規則可以防止電腦和自修室被濫用。"},{"en":"Lockers may be misused if students store banned items or damage them.","zh":"如果學生存放違禁品或損壞儲物櫃，儲物櫃可能被濫用。"},{"en":"Rules and checks can protect lockers as shared school facilities.","zh":"規則和檢查可以保護儲物櫃作為共享學校設施。"}],"source":"2014 Q5.pdf","sourcePage":12},{"front":"sign a locker agreement","meaning":"簽署儲物櫃使用協議","examples":[{"en":"Students could sign a locker agreement.","zh":"學生可以簽署儲物櫃使用協議。"},{"en":"To sign a locker agreement means to accept written rules for using a locker responsibly.","zh":"sign a locker agreement 指接受有關負責任使用儲物櫃的書面規則。"},{"en":"Students may sign an agreement before borrowing school tablets.","zh":"學生借用學校平板電腦前可能需要簽署協議。"},{"en":"A locker agreement can explain what may be stored and what behaviour is not allowed.","zh":"儲物櫃使用協議可以解釋可存放甚麼，以及哪些行為不允許。"},{"en":"Signing an agreement helps students understand that locker use carries responsibility.","zh":"簽署協議幫助學生明白使用儲物櫃帶有責任。"}],"source":"2014 Q5.pdf","sourcePage":12},{"front":"class teachers","meaning":"班主任","examples":[{"en":"Class teachers could conduct brief checks each term.","zh":"班主任可以每學期進行簡短檢查。"},{"en":"Class teachers are teachers responsible for looking after a particular class.","zh":"class teachers 指負責照顧特定班別的老師。"},{"en":"A class teacher may collect notices, check attendance, and speak with parents.","zh":"班主任可能收通告、點名和與家長溝通。"},{"en":"Class teachers understand students’ daily needs because they see them regularly.","zh":"班主任定期見到學生，因此了解他們的日常需要。"},{"en":"They could help manage lockers without creating a complicated new system.","zh":"他們可以協助管理儲物櫃，而不需要建立複雜新制度。"}],"source":"2014 Q5.pdf","sourcePage":12},{"front":"conduct brief checks","meaning":"進行簡短檢查","examples":[{"en":"Class teachers could conduct brief checks at the end of each term.","zh":"班主任可以在每個學期末進行簡短檢查。"},{"en":"To conduct brief checks means to carry out quick inspections to make sure rules are followed.","zh":"conduct brief checks 指進行快速檢查，以確保規則被遵守。"},{"en":"Teachers may conduct brief checks of classroom equipment before holidays.","zh":"老師可能在假期前簡短檢查課室設備。"},{"en":"Brief checks can prevent misuse without taking too much teaching time.","zh":"簡短檢查可以防止濫用，而不佔用太多教學時間。"},{"en":"Locker checks should be simple, respectful, and clearly explained.","zh":"儲物櫃檢查應簡單、尊重學生，並清楚解釋。"}],"source":"2014 Q5.pdf","sourcePage":12},{"front":"at the end of each term","meaning":"每個學期末","examples":[{"en":"Locker checks could be conducted at the end of each term.","zh":"儲物櫃檢查可以在每個學期末進行。"},{"en":"At the end of each term means during the final period of every school term.","zh":"at the end of each term 指每個學校學期的最後階段。"},{"en":"Students often return library books at the end of each term.","zh":"學生常在每個學期末歸還圖書館書籍。"},{"en":"This timing is useful because students can clear old materials before holidays.","zh":"這個時間很有用，因為學生可以在假期前清理舊材料。"},{"en":"Regular end-of-term checks help keep lockers clean and organised.","zh":"定期學期末檢查幫助保持儲物櫃清潔和有條理。"}],"source":"2014 Q5.pdf","sourcePage":12},{"front":"there is no getting around the fact that","meaning":"無可否認","examples":[{"en":"There is no getting around the fact that implementation requires effort.","zh":"無可否認，執行這項政策需要努力。"},{"en":"There is no getting around the fact that means something is undeniable and must be accepted.","zh":"there is no getting around the fact that 指某事不可否認，必須被接受。"},{"en":"There is no getting around the fact that exam preparation takes time.","zh":"無可否認，考試準備需要時間。"},{"en":"This phrase is useful when admitting a difficulty honestly.","zh":"當誠實承認困難時，這個短語很有用。"},{"en":"The writer accepts that the locker policy will require work, but still supports it.","zh":"作者承認儲物櫃政策需要工作，但仍然支持它。"}],"source":"2014 Q5.pdf","sourcePage":12},{"front":"implementation requires effort","meaning":"執行需要努力","examples":[{"en":"The implementation of the policy requires effort.","zh":"這項政策的執行需要努力。"},{"en":"Implementation requires effort means putting the plan into practice will need time, work, and coordination.","zh":"implementation requires effort 指把計劃付諸實行需要時間、工作和協調。"},{"en":"A new homework system requires effort from teachers, students, and parents.","zh":"新功課制度需要老師、學生和家長共同努力。"},{"en":"Effort is normal when a school changes a policy that affects many people.","zh":"當學校改變影響許多人的政策時，需要努力是正常的。"},{"en":"The need for effort should lead to planning, not rejection.","zh":"需要努力應引向規劃，而不是拒絕。"}],"source":"2014 Q5.pdf","sourcePage":12},{"front":"manageable policy","meaning":"可管理的政策","examples":[{"en":"A manageable policy should not be confused with an impossible one.","zh":"可管理的政策不應被混同為不可能實行的事情。"},{"en":"A manageable policy is a policy that can be carried out with careful planning and reasonable effort.","zh":"manageable policy 指透過審慎規劃和合理努力可以執行的政策。"},{"en":"A phased locker plan is manageable if the school starts with priority groups.","zh":"如果學校由優先群體開始，分階段儲物櫃計劃就是可管理的。"},{"en":"Manageable does not mean easy; it means possible to organise.","zh":"可管理不代表容易；而是代表可以組織和執行。"},{"en":"The writer argues that locker reform is difficult but still manageable.","zh":"作者主張儲物櫃改革困難，但仍然可管理。"}],"source":"2014 Q5.pdf","sourcePage":13},{"front":"be confused with","meaning":"被混同為","examples":[{"en":"A manageable policy should not be confused with an impossible one.","zh":"可管理的政策不應被混同為不可能實行的事情。"},{"en":"To be confused with something means to be wrongly treated as the same as that thing.","zh":"be confused with something 指被錯誤地視為與某事相同。"},{"en":"A difficult task should not be confused with an impossible task.","zh":"困難任務不應被混同為不可能任務。"},{"en":"People may reject good ideas when they confuse challenge with impossibility.","zh":"當人們把挑戰與不可能混同時，可能會拒絕好想法。"},{"en":"The locker plan should be judged as manageable if it is introduced gradually.","zh":"如果儲物櫃計劃逐步推出，就應被視為可管理。"}],"source":"2014 Q5.pdf","sourcePage":13},{"front":"impossible one","meaning":"不可能實行的事情","examples":[{"en":"The policy is manageable, not an impossible one.","zh":"這項政策是可管理的，而不是不可能實行的事情。"},{"en":"An impossible one means a plan or task that cannot realistically be done.","zh":"impossible one 指現實上不能完成的計劃或任務。"},{"en":"Building a new campus next week would be an impossible one, but adding lockers gradually is not.","zh":"下星期興建新校園是不可能實行的事，但逐步加設儲物櫃不是。"},{"en":"This phrase contrasts realistic difficulty with complete impossibility.","zh":"這個短語對比現實中的困難與完全不可能。"},{"en":"The writer wants the school to see the proposal as practical, not unrealistic.","zh":"作者希望學校把建議視為實際，而不是不切實際。"}],"source":"2014 Q5.pdf","sourcePage":13},{"front":"in conclusion","meaning":"總而言之","examples":[{"en":"In conclusion, the writer asks the school to reconsider the arrangement.","zh":"總而言之，作者請學校重新考慮這項安排。"},{"en":"In conclusion is used to introduce the final part of an argument or letter.","zh":"in conclusion 用來引入論點或信件的最後部分。"},{"en":"In conclusion, the school should improve study spaces before exam season.","zh":"總而言之，學校應在考試季前改善自修空間。"},{"en":"This phrase helps readers know that the writer is summarising the main request.","zh":"這個短語幫助讀者知道作者正在總結主要要求。"},{"en":"A conclusion should connect the reasons given with the action being requested.","zh":"結論應把已提出的理由與要求採取的行動連接起來。"}],"source":"2014 Q5.pdf","sourcePage":13},{"front":"sincerely hope","meaning":"衷心希望","examples":[{"en":"I sincerely hope you will reconsider the present arrangement.","zh":"我衷心希望你會重新考慮現行安排。"},{"en":"Sincerely hope means genuinely and respectfully wish that something will happen.","zh":"sincerely hope 指真誠而尊重地希望某事發生。"},{"en":"I sincerely hope the school will listen to students’ concerns.","zh":"我衷心希望學校會聆聽學生的憂慮。"},{"en":"This phrase sounds polite because it expresses a strong wish without demanding rudely.","zh":"這個短語聽起來有禮貌，因為它表達強烈願望，但不是無禮要求。"},{"en":"It is suitable for formal letters asking someone in authority to act.","zh":"它適合用於要求有權限人士行動的正式信件。"}],"source":"2014 Q5.pdf","sourcePage":13},{"front":"reconsider","meaning":"重新考慮","examples":[{"en":"The school is asked to reconsider the present arrangement.","zh":"學校被請求重新考慮現行安排。"},{"en":"To reconsider means to think about something again, especially after new information or concerns appear.","zh":"reconsider 指再次思考某事，尤其是在新資訊或憂慮出現後。"},{"en":"A teacher may reconsider a deadline after hearing students’ workload concerns.","zh":"老師聽到學生的工作量憂慮後，可能重新考慮截止日期。"},{"en":"Reconsidering does not mean admitting failure; it means being willing to improve.","zh":"重新考慮不代表承認失敗；而是願意改善。"},{"en":"The Student Union asks the school to reconsider because the current system affects students daily.","zh":"學生會要求學校重新考慮，因為現行制度每天影響學生。"}],"source":"2014 Q5.pdf","sourcePage":13},{"front":"not so much… as…","meaning":"與其說是……不如說是……","examples":[{"en":"The issue is not so much storage as fairness, health and dignity.","zh":"這個問題與其說是儲物空間，不如說是公平、健康和尊嚴。"},{"en":"Not so much… as… means the first idea is less important than the second idea.","zh":"not so much… as… 指第一個想法不如第二個想法重要。"},{"en":"The problem is not so much noise as the lack of respect behind it.","zh":"問題與其說是噪音，不如說是背後缺乏尊重。"},{"en":"This pattern helps show the deeper meaning of an issue.","zh":"這個句式有助顯示問題的更深意義。"},{"en":"Here, lockers are presented not just as storage, but as a matter of student well-being.","zh":"在這裏，儲物櫃不只是儲物空間，而是學生身心健康問題。"}],"source":"2014 Q5.pdf","sourcePage":13},{"front":"storage","meaning":"儲物空間","examples":[{"en":"The issue is not only about storage.","zh":"這個問題不只是關於儲物空間。"},{"en":"Storage means space or a system for keeping things safely until they are needed.","zh":"storage 指安全存放物品直到需要使用的空間或制度。"},{"en":"Lockers provide storage for books, sports gear, instruments, and notes.","zh":"儲物櫃為書本、運動用品、樂器和筆記提供儲物空間。"},{"en":"Good storage helps students stay organised and reduce unnecessary carrying.","zh":"良好儲物空間幫助學生保持有條理，並減少不必要攜帶。"},{"en":"In this letter, storage is connected with fairness, health, and dignity.","zh":"在這封信中，儲物空間與公平、健康和尊嚴相連。"}],"source":"2014 Q5.pdf","sourcePage":13},{"front":"dignity","meaning":"尊嚴","examples":[{"en":"The locker issue is also about students’ dignity.","zh":"儲物櫃問題也關乎學生的尊嚴。"},{"en":"Dignity means the feeling that people are respected and treated as valuable.","zh":"dignity 指人們感到自己受到尊重並被視為有價值。"},{"en":"Students’ dignity is affected when their real daily difficulties are ignored.","zh":"當學生真實日常困難被忽視時，他們的尊嚴會受影響。"},{"en":"Carrying too much and feeling unheard can make students feel less respected.","zh":"攜帶太多物品和感到不被聆聽，會令學生覺得較不受尊重。"},{"en":"A fair policy protects dignity by showing that students’ needs matter.","zh":"公平政策透過顯示學生需要重要，來保障尊嚴。"}],"source":"2014 Q5.pdf","sourcePage":13},{"front":"by expanding locker access","meaning":"透過擴大儲物櫃使用機會","examples":[{"en":"By expanding locker access, the school can ease students’ burden.","zh":"透過擴大儲物櫃使用機會，學校可以減輕學生負擔。"},{"en":"By expanding locker access means through allowing more students to use lockers.","zh":"by expanding locker access 指透過讓更多學生使用儲物櫃。"},{"en":"By expanding locker access gradually, the school can help students without overwhelming resources.","zh":"透過逐步擴大儲物櫃使用機會，學校可以幫助學生，而不會令資源過度受壓。"},{"en":"This phrase links the method directly to the benefit.","zh":"這個短語把方法直接連接到好處。"},{"en":"Expanding access is presented as a practical way to reduce daily strain.","zh":"擴大使用機會被呈現為減少每日負擔的實際方法。"}],"source":"2014 Q5.pdf","sourcePage":13},{"front":"ease students’ daily burden","meaning":"減輕學生每日負擔","examples":[{"en":"The school can ease students’ daily burden.","zh":"學校可以減輕學生每日負擔。"},{"en":"To ease students’ daily burden means to make their everyday load or pressure lighter.","zh":"ease students’ daily burden 指令學生每天的負重或壓力變輕。"},{"en":"A shorter queue at lunch can ease students’ daily burden during a busy school day.","zh":"較短的午膳隊伍可以在繁忙上學日減輕學生每日負擔。"},{"en":"Lockers ease the burden by reducing what students carry between home and school.","zh":"儲物櫃透過減少學生往返家校所攜帶的東西來減輕負擔。"},{"en":"Small changes to facilities can make students’ daily life much more manageable.","zh":"設施上的小改變可以令學生每日生活更容易管理。"}],"source":"2014 Q5.pdf","sourcePage":14},{"front":"support effective learning","meaning":"支持有效學習","examples":[{"en":"Lockers can support effective learning.","zh":"儲物櫃可以支持有效學習。"},{"en":"To support effective learning means to help students learn in a focused, prepared, and organised way.","zh":"support effective learning 指幫助學生以專注、準備充分和有條理的方式學習。"},{"en":"A quiet study room supports effective learning because students can concentrate.","zh":"安靜自修室支持有效學習，因為學生可以集中精神。"},{"en":"Lockers support learning by keeping the right books close and reducing physical stress.","zh":"儲物櫃透過把正確書本放近學生和減少身體壓力來支持學習。"},{"en":"Effective learning depends not only on teaching, but also on the conditions around students.","zh":"有效學習不只取決於教學，也取決於學生身邊的條件。"}],"source":"2014 Q5.pdf","sourcePage":14},{"front":"demonstrate that","meaning":"顯示；證明","examples":[{"en":"The school can demonstrate that students’ voices are taken seriously.","zh":"學校可以顯示學生的聲音受到重視。"},{"en":"To demonstrate that means to show clearly through action or evidence.","zh":"demonstrate that 指透過行動或證據清楚顯示。"},{"en":"A school demonstrates respect by explaining decisions and listening to feedback.","zh":"學校透過解釋決定和聆聽回饋來顯示尊重。"},{"en":"Actions demonstrate values more strongly than slogans.","zh":"行動比口號更有力地證明價值觀。"},{"en":"Improving the locker policy would demonstrate that the school listens to students.","zh":"改善儲物櫃政策會顯示學校聆聽學生。"}],"source":"2014 Q5.pdf","sourcePage":14},{"front":"students’ voices are taken seriously","meaning":"學生的聲音受到重視","examples":[{"en":"The policy can show that students’ voices are taken seriously.","zh":"這項政策可以顯示學生的聲音受到重視。"},{"en":"Students’ voices are taken seriously means students’ opinions are listened to and considered in real decisions.","zh":"students’ voices are taken seriously 指學生意見被聆聽，並在真實決定中被考慮。"},{"en":"Students feel respected when their voices are taken seriously after a survey.","zh":"當問卷後學生聲音受到重視時，學生會感到受尊重。"},{"en":"Taking voices seriously does not always mean agreeing with every request, but it means responding honestly.","zh":"重視學生聲音不一定代表答應每個要求，但代表誠實回應。"},{"en":"A working group would show students that their concerns matter.","zh":"工作小組會向學生顯示，他們的憂慮很重要。"}],"source":"2014 Q5.pdf","sourcePage":14},{"front":"I would be grateful if","meaning":"如能……我將不勝感激","examples":[{"en":"I would be grateful if you could meet the Student Union.","zh":"如你能會見學生會，我將不勝感激。"},{"en":"I would be grateful if is a polite formal phrase used to make a request.","zh":"I would be grateful if 是用來提出請求的禮貌正式短語。"},{"en":"I would be grateful if you could reply before Friday.","zh":"如你能在星期五前回覆，我將不勝感激。"},{"en":"This phrase sounds respectful because it asks rather than commands.","zh":"這個短語聽起來尊重，因為它是請求而不是命令。"},{"en":"It is useful when writing to a teacher, principal, or person in authority.","zh":"寫給老師、校長或有權限人士時，這個短語很有用。"}],"source":"2014 Q5.pdf","sourcePage":14},{"front":"class representatives","meaning":"班代表","examples":[{"en":"The Student Union and class representatives could discuss the proposal.","zh":"學生會和班代表可以討論這項建議。"},{"en":"Class representatives are students chosen to speak for their classmates.","zh":"class representatives 指被選出代表同班同學發言的學生。"},{"en":"Class representatives may collect opinions before a meeting with teachers.","zh":"班代表可能在與老師會面前收集意見。"},{"en":"Including class representatives helps the discussion reflect different forms and classes.","zh":"包括班代表有助討論反映不同年級和班別。"},{"en":"They can explain how locker problems affect students in their own classes.","zh":"他們可以解釋儲物櫃問題如何影響自己班的學生。"}],"source":"2014 Q5.pdf","sourcePage":14},{"front":"discuss this proposal","meaning":"討論這項建議","examples":[{"en":"The school could meet students to discuss this proposal.","zh":"學校可以會見學生，討論這項建議。"},{"en":"To discuss this proposal means to talk about the suggestion, its reasons, and possible changes.","zh":"discuss this proposal 指討論這項建議、其理由和可能改動。"},{"en":"Teachers and students may discuss a proposal before deciding whether it can work.","zh":"老師和學生可能在決定建議是否可行前討論它。"},{"en":"Discussion helps both sides understand concerns, limits, and solutions.","zh":"討論幫助雙方理解憂慮、限制和解決方法。"},{"en":"A meeting about the proposal could turn complaints into practical planning.","zh":"關於建議的會議可以把投訴轉化為實際規劃。"}],"source":"2014 Q5.pdf","sourcePage":14},{"front":"respectfully suggest","meaning":"鄭重建議","examples":[{"en":"I respectfully suggest setting up a working group.","zh":"我鄭重建議成立工作小組。"},{"en":"To respectfully suggest means to offer an idea politely and seriously.","zh":"respectfully suggest 指有禮貌而認真地提出想法。"},{"en":"Students may respectfully suggest adding more recycling bins around the campus.","zh":"學生可能鄭重建議在校園增加回收箱。"},{"en":"This phrase is useful when writing to someone with authority.","zh":"寫信給有權限人士時，這個短語很有用。"},{"en":"It shows the writer has a clear proposal but still respects the reader’s decision.","zh":"它顯示作者有清楚建議，但仍尊重讀者決定。"}],"source":"2014 Q5.pdf","sourcePage":14},{"front":"setting up a working group","meaning":"成立工作小組","examples":[{"en":"The school could set up a working group before the end of term.","zh":"學校可以在學期結束前成立工作小組。"},{"en":"Setting up a working group means creating a small team to study a problem and suggest action.","zh":"setting up a working group 指成立小組研究問題並建議行動。"},{"en":"A school may set up a working group to improve lunch arrangements.","zh":"學校可能成立工作小組改善午膳安排。"},{"en":"Working groups are useful because they bring teachers, students, and administrators together.","zh":"工作小組有用，因為它把老師、學生和行政人員聚在一起。"},{"en":"A locker working group could examine space, costs, rules, and student needs.","zh":"儲物櫃工作小組可以研究空間、成本、規則和學生需要。"}],"source":"2014 Q5.pdf","sourcePage":14},{"front":"before the end of this term","meaning":"本學期結束前","examples":[{"en":"The working group could be set up before the end of this term.","zh":"工作小組可以在本學期結束前成立。"},{"en":"Before the end of this term means before the current school term finishes.","zh":"before the end of this term 指在目前這個學校學期完結前。"},{"en":"The club hopes to finish the survey before the end of this term.","zh":"學會希望在本學期結束前完成調查。"},{"en":"A deadline helps prevent the proposal from being delayed indefinitely.","zh":"截止時間有助防止建議被無限期拖延。"},{"en":"Setting up the group this term would show students that the school is taking action.","zh":"本學期成立小組會向學生顯示學校正在採取行動。"}],"source":"2014 Q5.pdf","sourcePage":14},{"front":"with thoughtful planning","meaning":"透過周詳規劃","examples":[{"en":"With thoughtful planning, a fairer policy is possible.","zh":"透過周詳規劃，更公平的政策是可能的。"},{"en":"With thoughtful planning means if people plan carefully, responsibly, and with consideration for others.","zh":"with thoughtful planning 指如果人們細心、負責並顧及他人地規劃。"},{"en":"With thoughtful planning, a small library can still serve many students well.","zh":"透過周詳規劃，小型圖書館仍可以好好服務許多學生。"},{"en":"Thoughtful planning balances needs, limits, safety, and fairness.","zh":"周詳規劃會平衡需要、限制、安全和公平。"},{"en":"This phrase suggests hope because the problem can be solved carefully.","zh":"這個短語帶有希望，因為問題可以被仔細解決。"}],"source":"2014 Q5.pdf","sourcePage":15},{"front":"not beyond reach","meaning":"並非遙不可及","examples":[{"en":"A fairer locker policy is not beyond reach.","zh":"更公平的儲物櫃政策並非遙不可及。"},{"en":"Not beyond reach means possible to achieve, even if effort is needed.","zh":"not beyond reach 指即使需要努力，也仍然可以達成。"},{"en":"Better study habits are not beyond reach if students start with small steps.","zh":"如果學生由小步驟開始，更好的學習習慣並非遙不可及。"},{"en":"This phrase encourages people not to give up because the goal is realistic.","zh":"這個短語鼓勵人不要放棄，因為目標是實際可行的。"},{"en":"The writer believes locker reform is difficult, but still possible.","zh":"作者相信儲物櫃改革困難，但仍然可能。"}],"source":"2014 Q5.pdf","sourcePage":15},{"front":"long overdue","meaning":"早就應該實行","examples":[{"en":"A fairer locker policy is long overdue.","zh":"更公平的儲物櫃政策早就應該實行。"},{"en":"Long overdue means something should have happened much earlier and is now urgently needed.","zh":"long overdue 指某事早應發生，如今已迫切需要。"},{"en":"Repairs to the leaking classroom roof are long overdue.","zh":"漏水課室天花的維修早就應該進行。"},{"en":"This phrase shows that the writer believes the delay has lasted too long.","zh":"這個短語顯示作者認為拖延已太久。"},{"en":"Calling the policy long overdue adds urgency to the request.","zh":"稱這項政策早就應該實行，會增加請求的迫切性。"}],"source":"2014 Q5.pdf","sourcePage":15},{"front":"Yours sincerely","meaning":"謹啟；此致","examples":[{"en":"The letter ends with “Yours sincerely.”","zh":"這封信以 “Yours sincerely” 結尾。"},{"en":"Yours sincerely is a polite formal closing used when the writer knows the recipient’s name.","zh":"Yours sincerely 是在作者知道收信人姓名時使用的禮貌正式結語。"},{"en":"A student may write Yours sincerely before signing a formal letter to the principal.","zh":"學生寫正式信件給校長時，可能在簽名前寫 Yours sincerely。"},{"en":"This closing makes the letter sound respectful and complete.","zh":"這個結語令信件聽起來尊重而完整。"},{"en":"It is suitable for proposals, requests, and formal school letters.","zh":"它適合用於建議信、請求信和正式學校信件。"}],"source":"2014 Q5.pdf","sourcePage":15},{"front":"Chairperson, Student Union","meaning":"學生會主席","examples":[{"en":"Chris Wong signs as Chairperson of the Student Union.","zh":"Chris Wong 以學生會主席身份簽署。"},{"en":"Chairperson, Student Union is a signature title showing the writer’s role as the student representative leader.","zh":"Chairperson, Student Union 是簽名職銜，顯示作者作為學生代表領袖的身份。"},{"en":"A student may sign “Chairperson, English Society” after writing an official club letter.","zh":"學生寫正式學會信件後，可能簽署「英文學會主席」。"},{"en":"Adding the title helps readers understand that the writer speaks from an official student role.","zh":"加上職銜幫助讀者理解作者是以正式學生角色發言。"},{"en":"This ending supports the letter’s authority because Chris represents the Student Union.","zh":"這個結尾加強信件的權威性，因為 Chris 代表學生會。"}],"source":"2014 Q5.pdf","sourcePage":15}],"dse/writing/part-b/2014/Q6":[{"front":"inside the suit","meaning":"在服裝裏面","examples":[{"en":"The article describes what life is like inside the suit of a theme park character.","zh":"這篇文章描述主題公園角色服裝裏面的生活是怎樣的。"},{"en":"Inside the suit means inside the heavy costume worn by a performer.","zh":"inside the suit 指在表演者穿着的厚重服裝裏面。"},{"en":"Visitors see the cheerful character, but they do not know how hot it feels inside the suit.","zh":"遊客看見開朗的角色，但不知道服裝裏面有多熱。"},{"en":"Working inside the suit can be tiring because the performer cannot breathe or see easily.","zh":"在服裝裏面工作可能很疲累，因為表演者不容易呼吸或看清楚。"},{"en":"The phrase reminds readers that there is a real person behind the costume.","zh":"這個片語提醒讀者，服裝背後有一個真正的人。"}],"source":"2014 Q6.pdf","sourcePage":1},{"front":"theme park costume","meaning":"主題公園角色服裝","examples":[{"en":"The student worked in a theme park costume during the summer.","zh":"那名學生暑假期間穿着主題公園角色服裝工作。"},{"en":"A theme park costume is a special outfit worn by performers to look like a character.","zh":"theme park costume 是表演者穿着、用來扮演角色的特別服裝。"},{"en":"A theme park costume may include a large headpiece, gloves, shoes, and a furry body.","zh":"主題公園角色服裝可能包括大型頭套、手套、鞋和毛茸茸的身體部分。"},{"en":"Theme park costumes help create magic for visitors, but they can be hot and heavy.","zh":"主題公園角色服裝幫助為遊客製造魔法感，但可能又熱又重。"},{"en":"Wearing a theme park costume requires more skill and patience than many people expect.","zh":"穿着主題公園角色服裝比很多人想像中更需要技巧和耐性。"}],"source":"2014 Q6.pdf","sourcePage":1},{"front":"by a student contributor","meaning":"由學生投稿人撰寫","examples":[{"en":"The article is written by a student contributor.","zh":"這篇文章由學生投稿人撰寫。"},{"en":"By a student contributor means written or submitted by a student who contributes work to a publication.","zh":"by a student contributor 指由向刊物投稿的學生撰寫或提交。"},{"en":"A school magazine may publish an article by a student contributor about summer work.","zh":"校刊可能刊登一篇由學生投稿人撰寫、關於暑期工作的文章。"},{"en":"This phrase tells readers who produced the article.","zh":"這個片語告訴讀者文章由誰創作。"},{"en":"A student contributor often writes from personal experience rather than professional distance.","zh":"學生投稿人通常從個人經歷出發，而不是以專業旁觀者角度寫作。"}],"source":"2014 Q6.pdf","sourcePage":1},{"front":"for many students","meaning":"對很多學生來說","examples":[{"en":"For many students, a summer job means flexible hours and extra money.","zh":"對很多學生來說，暑期工意味着彈性工時和額外收入。"},{"en":"For many students means from the point of view or experience of many learners.","zh":"for many students 指從許多學生的角度或經驗來看。"},{"en":"For many students, public speaking feels frightening at first.","zh":"對很多學生來說，公開演說起初令人害怕。"},{"en":"This phrase introduces a general situation before giving one personal example.","zh":"這個片語先引出一般情況，然後再帶出個人例子。"},{"en":"For many students, work is mainly about money, but this job taught something deeper.","zh":"對很多學生來說，工作主要是為了金錢，但這份工作教會作者更深的東西。"}],"source":"2014 Q6.pdf","sourcePage":1},{"front":"a summer job","meaning":"暑期工","examples":[{"en":"For many students, a summer job means air-conditioning and flexible hours.","zh":"對很多學生來說，暑期工意味着冷氣和彈性工時。"},{"en":"A summer job is temporary work that students do during the summer holiday.","zh":"summer job 是學生在暑假期間做的臨時工作。"},{"en":"Students may take a summer job in a shop, café, library, or theme park.","zh":"學生可能在商店、咖啡店、圖書館或主題公園做暑期工。"},{"en":"A summer job can give young people money, experience, and confidence.","zh":"暑期工可以給年輕人金錢、經驗和信心。"},{"en":"This summer job was difficult, but it became more meaningful than the writer expected.","zh":"這份暑期工很辛苦，但比作者預期更有意義。"}],"source":"2014 Q6.pdf","sourcePage":1},{"front":"air-conditioning","meaning":"冷氣","examples":[{"en":"Many students prefer summer jobs with air-conditioning.","zh":"許多學生較喜歡有冷氣的暑期工。"},{"en":"Air-conditioning is a system that cools the air inside a room or building.","zh":"air-conditioning 是令房間或建築物內空氣變涼的系統。"},{"en":"Office jobs with air-conditioning can feel comfortable during hot weather.","zh":"有冷氣的辦公室工作在炎熱天氣中會較舒服。"},{"en":"Without air-conditioning, outdoor summer work can become exhausting.","zh":"沒有冷氣，戶外暑期工作可能會令人筋疲力盡。"},{"en":"The performer’s job was difficult because the costume felt much hotter than an air-conditioned room.","zh":"表演者的工作很困難，因為服裝裏比有冷氣的房間熱得多。"}],"source":"2014 Q6.pdf","sourcePage":1},{"front":"flexible hours","meaning":"彈性工時","examples":[{"en":"A summer job often offers flexible hours.","zh":"暑期工常提供彈性工時。"},{"en":"Flexible hours are working times that can be adjusted instead of being fixed every day.","zh":"flexible hours 指可以調整、不是每天固定的工作時間。"},{"en":"Students like flexible hours because they can balance work, study, and rest.","zh":"學生喜歡彈性工時，因為他們可以平衡工作、學習和休息。"},{"en":"A job with flexible hours may allow workers to choose morning or afternoon shifts.","zh":"有彈性工時的工作可能容許員工選擇早班或午班。"},{"en":"Flexible hours are attractive, but this theme park job also demanded stamina and discipline.","zh":"彈性工時很吸引，但這份主題公園工作也要求體力和紀律。"}],"source":"2014 Q6.pdf","sourcePage":1},{"front":"a little extra money","meaning":"一點額外收入","examples":[{"en":"Students often take summer jobs to earn a little extra money.","zh":"學生常做暑期工來賺一點額外收入。"},{"en":"A little extra money means a small amount of additional income.","zh":"a little extra money 指少量額外收入。"},{"en":"A teenager may work in a café to earn a little extra money for books or transport.","zh":"青少年可能在咖啡店工作，賺一點額外收入買書或支付交通費。"},{"en":"Extra money can help students feel more independent.","zh":"額外收入可以令學生感到更獨立。"},{"en":"The writer earned money, but the larger reward was the experience itself.","zh":"作者賺到了錢，但更大的收穫是經歷本身。"}],"source":"2014 Q6.pdf","sourcePage":1},{"front":"last summer","meaning":"去年暑假","examples":[{"en":"Last summer, I chose something less comfortable but far more memorable.","zh":"去年暑假，我選擇了一件較不舒服但難忘得多的事。"},{"en":"Last summer means during the summer before the present time.","zh":"last summer 指現在之前的那個夏天。"},{"en":"Last summer, many students looked for part-time jobs after exams.","zh":"去年暑假，許多學生考試後尋找兼職工作。"},{"en":"This phrase helps place a personal experience in time.","zh":"這個片語幫助把個人經歷放在明確時間中。"},{"en":"Last summer became important because the writer learned what entertainment work really involves.","zh":"去年暑假變得重要，因為作者明白娛樂工作真正包含甚麼。"}],"source":"2014 Q6.pdf","sourcePage":1},{"front":"something less comfortable but far more memorable","meaning":"較不舒服但難忘得多的事","examples":[{"en":"I chose something less comfortable but far more memorable.","zh":"我選擇了一件較不舒服但難忘得多的事。"},{"en":"Something less comfortable but far more memorable is an experience that is harder but more unforgettable.","zh":"something less comfortable but far more memorable 指一件較辛苦但更難忘的經歷。"},{"en":"Camping without air-conditioning may be less comfortable but more memorable than staying at home.","zh":"沒有冷氣的露營可能比留在家中較不舒服，但更難忘。"},{"en":"Difficult experiences often become memorable because they teach us more.","zh":"困難經歷常令人難忘，因為它們教會我們更多。"},{"en":"The theme park job was uncomfortable, but it stayed in the writer’s mind.","zh":"主題公園工作不舒服，但它深深留在作者記憶中。"}],"source":"2014 Q6.pdf","sourcePage":1},{"front":"far more memorable","meaning":"難忘得多","examples":[{"en":"The job was far more memorable than an ordinary summer job.","zh":"這份工作比普通暑期工難忘得多。"},{"en":"Far more memorable means much easier to remember because it was special or meaningful.","zh":"far more memorable 指因特別或有意義而更容易記住。"},{"en":"A school trip with real challenges can be far more memorable than a normal lesson.","zh":"一次有真正挑戰的學校旅行，可能比普通課堂難忘得多。"},{"en":"Experiences become far more memorable when they involve strong feelings and effort.","zh":"當經歷包含強烈感受和努力，它會難忘得多。"},{"en":"This job was memorable because the writer worked behind the magic visitors saw.","zh":"這份工作難忘，因為作者在遊客看見的魔法背後工作。"}],"source":"2014 Q6.pdf","sourcePage":2},{"front":"a costumed character performer","meaning":"穿着角色服裝的表演者","examples":[{"en":"I became a costumed character performer in a local theme park.","zh":"我成為本地主題公園一名穿着角色服裝的表演者。"},{"en":"A costumed character performer is a person who wears a character costume to entertain visitors.","zh":"costumed character performer 指穿着角色服裝娛樂遊客的人。"},{"en":"A costumed character performer may wave, dance, pose for photos, and greet children without speaking.","zh":"穿着角色服裝的表演者可能要揮手、跳舞、拍照和不用說話地問候孩子。"},{"en":"This job requires physical control because the costume limits sight and movement.","zh":"這份工作需要身體控制，因為服裝限制視線和動作。"},{"en":"The performer creates joy while staying hidden inside the character.","zh":"表演者創造快樂，同時隱藏在角色裏面。"}],"source":"2014 Q6.pdf","sourcePage":2},{"front":"local theme park","meaning":"本地主題公園","examples":[{"en":"I worked as a performer in a local theme park.","zh":"我在本地主題公園擔任表演者。"},{"en":"A local theme park is an amusement park in one’s own city or area.","zh":"local theme park 指自己城市或地區內的遊樂園。"},{"en":"Families visit a local theme park for rides, shows, photos, and holiday activities.","zh":"家庭會到本地主題公園玩機動遊戲、看表演、拍照和參加假期活動。"},{"en":"Local theme parks hire extra workers during busy seasons.","zh":"本地主題公園在繁忙季節會聘請額外員工。"},{"en":"The writer’s local theme park became a workplace, not just a place for fun.","zh":"作者的本地主題公園變成了工作場所，而不只是玩樂地方。"}],"source":"2014 Q6.pdf","sourcePage":2},{"front":"hired young performers","meaning":"聘請年輕表演者","examples":[{"en":"The park hired young performers like me.","zh":"公園聘請像我這樣的年輕表演者。"},{"en":"Hired young performers means employed young people to entertain visitors.","zh":"hired young performers 指聘用年輕人來娛樂遊客。"},{"en":"Theme parks hire young performers because summer crowds need more entertainment staff.","zh":"主題公園聘請年輕表演者，因為暑期人流需要更多娛樂人手。"},{"en":"Young performers may bring energy, flexibility, and enthusiasm to public events.","zh":"年輕表演者可以為公開活動帶來活力、彈性和熱情。"},{"en":"The park hired them to make the summer atmosphere livelier.","zh":"公園聘請他們，是為了令夏季氣氛更熱鬧。"}],"source":"2014 Q6.pdf","sourcePage":2},{"front":"brighten its peak-season atmosphere","meaning":"為旺季氣氛增添活力","examples":[{"en":"The park hired performers to brighten its peak-season atmosphere.","zh":"公園聘請表演者為旺季氣氛增添活力。"},{"en":"Brighten its peak-season atmosphere means make the busiest period feel more cheerful and lively.","zh":"brighten its peak-season atmosphere 指令最繁忙時期的氣氛更快樂和熱鬧。"},{"en":"Music, decorations, and performers can brighten a festival atmosphere.","zh":"音樂、裝飾和表演者可以為節日氣氛增添活力。"},{"en":"During peak season, theme parks need extra energy to impress large crowds.","zh":"旺季期間，主題公園需要額外活力來打動大量遊客。"},{"en":"Costumed performers brighten the park by giving families moments worth remembering.","zh":"穿着角色服裝的表演者透過給家庭難忘時刻，令公園更有活力。"}],"source":"2014 Q6.pdf","sourcePage":2},{"front":"peak-season atmosphere","meaning":"旺季氣氛","examples":[{"en":"Costumed performers helped brighten the park’s peak-season atmosphere.","zh":"穿着角色服裝的表演者幫助為公園旺季氣氛增添活力。"},{"en":"Peak-season atmosphere is the busy, lively feeling during the most popular time of the year.","zh":"peak-season atmosphere 指一年中最受歡迎時期那種繁忙熱鬧的氣氛。"},{"en":"A beach has a peak-season atmosphere when it is full of visitors, music, and food stalls.","zh":"當海灘充滿遊客、音樂和食物攤檔，它就有旺季氣氛。"},{"en":"In a theme park, peak-season atmosphere can be exciting but also exhausting for workers.","zh":"在主題公園中，旺季氣氛可以令人興奮，但也令員工疲累。"},{"en":"Performers help keep the atmosphere cheerful even when the park is crowded.","zh":"即使公園擠迫，表演者也幫助保持歡樂氣氛。"}],"source":"2014 Q6.pdf","sourcePage":2},{"front":"not only with photographs, but with stories","meaning":"不但帶着照片，還帶着故事","examples":[{"en":"Families could leave not only with photographs, but with stories worth retelling.","zh":"家庭離開時不但帶着照片，還帶着值得重述的故事。"},{"en":"Not only with photographs, but with stories means visitors gain memories, not just pictures.","zh":"not only with photographs, but with stories 指遊客得到的不只是相片，還有回憶。"},{"en":"A child meeting a favourite character may become a family story for years.","zh":"孩子見到最喜歡的角色，可能成為一家人多年後仍會說的故事。"},{"en":"Good entertainment gives people experiences they want to talk about later.","zh":"好的娛樂給人日後想談論的經歷。"},{"en":"The park wanted visitors to remember feelings as well as images.","zh":"公園希望遊客記住的不只是影像，還有感受。"}],"source":"2014 Q6.pdf","sourcePage":2},{"front":"stories worth retelling","meaning":"值得重述的故事","examples":[{"en":"The park wanted families to leave with stories worth retelling.","zh":"公園希望家庭離開時帶着值得重述的故事。"},{"en":"Stories worth retelling are experiences interesting or meaningful enough to be shared again.","zh":"stories worth retelling 指有趣或有意義到值得再次分享的經歷。"},{"en":"A surprise birthday hug from a mascot can become a story worth retelling.","zh":"吉祥物給生日孩子一個驚喜擁抱，可以成為值得重述的故事。"},{"en":"People remember holidays more deeply when they gain stories worth retelling.","zh":"當人們得到值得重述的故事，他們會更深刻記住假期。"},{"en":"The performer’s small gestures helped create these family stories.","zh":"表演者的小動作幫助創造這些家庭故事。"}],"source":"2014 Q6.pdf","sourcePage":2},{"front":"after two sweaty months","meaning":"經過兩個汗流浹背的月份","examples":[{"en":"After two sweaty months, I found the job meaningful.","zh":"經過兩個汗流浹背的月份，我覺得這份工作很有意義。"},{"en":"After two sweaty months means after two months of hot, tiring work.","zh":"after two sweaty months 指經過兩個月炎熱而疲累的工作。"},{"en":"After two sweaty months of training, the team finally performed on stage.","zh":"經過兩個汗流浹背的訓練月份，團隊終於上台表演。"},{"en":"Sweaty work can still feel worthwhile if it teaches patience and responsibility.","zh":"即使工作令人流汗，如果它教會耐性和責任，也可以值得。"},{"en":"The phrase shows that the writer’s respect for the job came through discomfort.","zh":"這個片語顯示作者對工作的尊重來自不舒服的經歷。"}],"source":"2014 Q6.pdf","sourcePage":2},{"front":"exhausting","meaning":"令人筋疲力盡的","examples":[{"en":"The job was exhausting, occasionally awkward, and far from glamorous.","zh":"這份工作令人筋疲力盡，偶爾尷尬，而且一點也不風光。"},{"en":"Exhausting means extremely tiring and using up a lot of energy.","zh":"exhausting 指極度疲累，消耗很多能量。"},{"en":"Carrying boxes all afternoon in hot weather can be exhausting.","zh":"在炎熱天氣中整個下午搬箱，可以令人筋疲力盡。"},{"en":"A job becomes exhausting when workers must smile even while tired.","zh":"當員工即使疲倦也必須微笑，工作就會令人筋疲力盡。"},{"en":"The performer’s job was exhausting because it required heat, movement, and constant cheerfulness.","zh":"表演者的工作令人筋疲力盡，因為它需要承受高溫、動作和持續開朗。"}],"source":"2014 Q6.pdf","sourcePage":2},{"front":"occasionally awkward","meaning":"偶爾尷尬的","examples":[{"en":"The job was occasionally awkward but meaningful.","zh":"這份工作偶爾尷尬，但很有意義。"},{"en":"Occasionally awkward means sometimes uncomfortable, embarrassing, or difficult to handle.","zh":"occasionally awkward 指有時令人不自在、尷尬或難以處理。"},{"en":"It can feel awkward when a child is afraid of the character costume.","zh":"當孩子害怕角色服裝時，情況可能會有點尷尬。"},{"en":"Public-facing jobs are occasionally awkward because visitors may behave unpredictably.","zh":"面對公眾的工作偶爾尷尬，因為遊客行為可能難以預測。"},{"en":"The writer accepted awkward moments because the job also created happiness.","zh":"作者接受尷尬時刻，因為這份工作也創造快樂。"}],"source":"2014 Q6.pdf","sourcePage":3},{"front":"far from glamorous","meaning":"一點也不風光","examples":[{"en":"The job was far from glamorous.","zh":"這份工作一點也不風光。"},{"en":"Far from glamorous means not attractive, elegant, or exciting in the way people may imagine.","zh":"far from glamorous 指不像人們想像中那樣吸引、優雅或刺激。"},{"en":"Cleaning tables in a busy restaurant is far from glamorous, but it is necessary work.","zh":"在繁忙餐廳清理桌子一點也不風光，但那是必要工作。"},{"en":"A performer’s job may look magical outside but feel far from glamorous inside the costume.","zh":"表演者的工作外表看似有魔法，但在服裝裏面可能一點也不風光。"},{"en":"The phrase helps reveal the hidden reality behind entertainment.","zh":"這個片語幫助揭示娛樂背後隱藏的現實。"}],"source":"2014 Q6.pdf","sourcePage":3},{"front":"nevertheless","meaning":"儘管如此","examples":[{"en":"Nevertheless, it was one of the most meaningful experiences I have ever had.","zh":"儘管如此，這是我曾有過最有意義的經歷之一。"},{"en":"Nevertheless means despite what has just been said, the next point is still true.","zh":"nevertheless 指儘管剛才所說的情況存在，下一點仍然成立。"},{"en":"The work was tiring; nevertheless, the student learnt a lot.","zh":"工作很疲累；儘管如此，學生學到了很多。"},{"en":"This word helps show contrast between difficulty and value.","zh":"這個詞幫助顯示困難和價值之間的對比。"},{"en":"The writer uses it to say the job was hard but still worth remembering.","zh":"作者用它表示這份工作很辛苦，但仍值得記住。"}],"source":"2014 Q6.pdf","sourcePage":3},{"front":"meaningful experiences","meaning":"有意義的經歷","examples":[{"en":"The job was one of the most meaningful experiences I have ever had.","zh":"這份工作是我曾有過最有意義的經歷之一。"},{"en":"Meaningful experiences are events that teach important lessons or affect how a person thinks.","zh":"meaningful experiences 指教會重要一課或影響一個人想法的經歷。"},{"en":"Volunteering at a care home can be a meaningful experience for students.","zh":"在護老院做義工可以成為學生有意義的經歷。"},{"en":"An experience becomes meaningful when it changes what someone understands about people or work.","zh":"當經歷改變一個人對人或工作的理解，它就變得有意義。"},{"en":"This job was meaningful because it taught discipline, empathy, and invisible labour.","zh":"這份工作有意義，因為它教會紀律、同理心和隱形勞動。"}],"source":"2014 Q6.pdf","sourcePage":3},{"front":"taught me that","meaning":"教會我","examples":[{"en":"The job taught me that entertainment involves invisible labour.","zh":"這份工作教會我，娛樂包含隱形勞動。"},{"en":"Taught me that means helped me learn or understand a particular lesson.","zh":"taught me that 指幫助我學會或理解某個道理。"},{"en":"Working in a shop taught me that patience is important when dealing with customers.","zh":"在商店工作教會我，應對顧客時耐性很重要。"},{"en":"Difficult jobs can teach students lessons that classrooms cannot easily show.","zh":"困難工作能教會學生課室不容易展示的道理。"},{"en":"The theme park job taught the writer to respect workers behind public happiness.","zh":"主題公園工作教會作者尊重公共快樂背後的工作者。"}],"source":"2014 Q6.pdf","sourcePage":3},{"front":"not just about","meaning":"不只是關於","examples":[{"en":"Entertainment is not just about smiling for the camera.","zh":"娛樂不只是關於對着鏡頭微笑。"},{"en":"Not just about means something includes more than the obvious part people notice.","zh":"not just about 指某事包含的不只是人們注意到的明顯部分。"},{"en":"Teaching is not just about explaining answers; it also requires patience.","zh":"教學不只是關於解釋答案，也需要耐性。"},{"en":"Entertainment is not just about fun because workers must prepare, protect, and recover.","zh":"娛樂不只是關於樂趣，因為工作者必須準備、保護和恢復。"},{"en":"This phrase corrects a simple view of theme park performance.","zh":"這個片語修正了對主題公園表演的簡單看法。"}],"source":"2014 Q6.pdf","sourcePage":3},{"front":"smiling for the camera","meaning":"對着鏡頭微笑","examples":[{"en":"Entertainment is not just about smiling for the camera.","zh":"娛樂不只是關於對着鏡頭微笑。"},{"en":"Smiling for the camera means posing happily for photographs.","zh":"smiling for the camera 指為拍照而開心地擺姿勢。"},{"en":"A character performer may spend hours smiling for the camera without showing tiredness.","zh":"角色表演者可能花幾小時對着鏡頭微笑，卻不能表現疲倦。"},{"en":"Visitors see the smile, but they may not see the effort behind it.","zh":"遊客看見笑容，但可能看不見背後的努力。"},{"en":"The phrase shows the visible part of entertainment, not the whole job.","zh":"這個片語顯示娛樂中可見的一面，而不是整份工作。"}],"source":"2014 Q6.pdf","sourcePage":3},{"front":"discipline","meaning":"紀律","examples":[{"en":"The job taught me discipline, empathy, and invisible labour.","zh":"這份工作教會我紀律、同理心和隱形勞動。"},{"en":"Discipline means the ability to control yourself, follow rules, and keep working carefully.","zh":"discipline 指控制自己、遵守規則並仔細工作的能力。"},{"en":"A performer shows discipline by staying in character even when tired.","zh":"表演者即使疲倦仍保持角色，就是展現紀律。"},{"en":"Discipline matters when workers must arrive on time, follow safety rules, and repeat routines.","zh":"當員工必須準時到達、遵守安全規則和重複流程時，紀律很重要。"},{"en":"This job taught discipline because fun for visitors depended on serious control.","zh":"這份工作教會紀律，因為遊客的快樂依賴認真的控制。"}],"source":"2014 Q6.pdf","sourcePage":3},{"front":"empathy","meaning":"同理心","examples":[{"en":"The job taught me empathy.","zh":"這份工作教會我同理心。"},{"en":"Empathy is the ability to understand and care about another person’s feelings.","zh":"empathy 是理解並關心他人感受的能力。"},{"en":"A performer uses empathy when calming a frightened child gently.","zh":"表演者溫柔地安撫害怕的孩子時，就是運用同理心。"},{"en":"Empathy helps workers respond kindly to visitors who are nervous, excited, or tired.","zh":"同理心幫助員工友善回應緊張、興奮或疲倦的遊客。"},{"en":"The job taught empathy because the writer had to read feelings without words.","zh":"這份工作教會同理心，因為作者必須不用言語也讀懂感受。"}],"source":"2014 Q6.pdf","sourcePage":3},{"front":"invisible labour","meaning":"隱形勞動","examples":[{"en":"The job taught me about invisible labour behind entertainment.","zh":"這份工作教會我娛樂背後的隱形勞動。"},{"en":"Invisible labour is hard work that people do not usually notice or appreciate.","zh":"invisible labour 指人們通常不會留意或欣賞的辛苦工作。"},{"en":"Cleaning staff, handlers, and performers all do invisible labour in a theme park.","zh":"清潔職員、隨行工作人員和表演者都在主題公園做隱形勞動。"},{"en":"Invisible labour keeps visitors safe and happy even when it happens behind the scenes.","zh":"隱形勞動即使在幕後發生，也能令遊客安全快樂。"},{"en":"The article helps readers see the human effort hidden inside the magic.","zh":"這篇文章幫助讀者看見魔法感中隱藏的人力。"}],"source":"2014 Q6.pdf","sourcePage":3},{"front":"a typical working day","meaning":"典型工作日","examples":[{"en":"A typical working day began before the gates opened.","zh":"典型工作日在園區開門之前開始。"},{"en":"A typical working day means a normal day at work, showing the usual routine.","zh":"a typical working day 指一個普通工作日，顯示平常流程。"},{"en":"A typical working day for a waiter may begin with setting tables.","zh":"侍應的典型工作日可能由擺放餐桌開始。"},{"en":"Describing a typical working day helps readers imagine the job clearly.","zh":"描述典型工作日能幫助讀者清楚想像這份工作。"},{"en":"The writer’s typical day began early and involved preparation before visitors arrived.","zh":"作者的典型工作日很早開始，並在遊客到來前做好準備。"}],"source":"2014 Q6.pdf","sourcePage":4},{"front":"before the gates opened","meaning":"在園區開門之前","examples":[{"en":"My working day began before the gates opened.","zh":"我的工作日在園區開門之前開始。"},{"en":"Before the gates opened means before visitors were allowed to enter the park.","zh":"before the gates opened 指在遊客被允許進入公園之前。"},{"en":"Staff arrived before the gates opened to prepare costumes, routes, and safety checks.","zh":"員工在園區開門前到達，準備服裝、路線和安全檢查。"},{"en":"Work often begins before customers see anything happening.","zh":"工作常在顧客看見任何事情發生之前已經開始。"},{"en":"This phrase shows that entertainment starts long before the public performance.","zh":"這個片語顯示娛樂在公開表演很久之前已經開始。"}],"source":"2014 Q6.pdf","sourcePage":4},{"front":"staff entrance","meaning":"職員入口","examples":[{"en":"I arrived at the staff entrance at 8:15 a.m.","zh":"我在上午八時十五分到達職員入口。"},{"en":"A staff entrance is a doorway used by employees rather than visitors.","zh":"staff entrance 是員工使用、不是遊客使用的入口。"},{"en":"Theme park workers use the staff entrance to sign in before their shifts.","zh":"主題公園員工會使用職員入口，在上班前簽到。"},{"en":"A staff entrance keeps worker preparation separate from visitor areas.","zh":"職員入口把員工準備區和遊客區分開。"},{"en":"Arriving there marked the beginning of the writer’s day behind the scenes.","zh":"到達職員入口標誌着作者幕後工作日的開始。"}],"source":"2014 Q6.pdf","sourcePage":4},{"front":"signed in","meaning":"簽到","examples":[{"en":"I signed in before changing into my base layer.","zh":"我換上底衣之前先簽到。"},{"en":"Signed in means recorded one’s arrival at work or an event.","zh":"signed in 指記錄自己已到達工作地點或活動。"},{"en":"Workers signed in at the office before starting their shift.","zh":"員工開始更次前在辦公室簽到。"},{"en":"Signing in helps managers know who is present and ready to work.","zh":"簽到幫助經理知道誰已到場並準備工作。"},{"en":"The writer signed in before becoming the character visitors would later see.","zh":"作者先簽到，然後才變成遊客稍後會看到的角色。"}],"source":"2014 Q6.pdf","sourcePage":4},{"front":"changed into","meaning":"換上","examples":[{"en":"I changed into a black base layer before the briefing.","zh":"我在簡介會前換上黑色貼身底衣。"},{"en":"Changed into means put on different clothes.","zh":"changed into 指換上不同衣服。"},{"en":"Students changed into sports uniforms before PE lessons.","zh":"學生在體育課前換上運動服。"},{"en":"Performers change into base layers before wearing heavy costumes.","zh":"表演者穿上厚重服裝前會先換上貼身底衣。"},{"en":"Changing clothes is the first step in leaving ordinary identity behind.","zh":"換衣服是放下普通身份的第一步。"}],"source":"2014 Q6.pdf","sourcePage":4},{"front":"black base layer","meaning":"黑色貼身底衣","examples":[{"en":"I changed into a black base layer before putting on the costume.","zh":"我穿上服裝前先換上黑色貼身底衣。"},{"en":"A black base layer is tight clothing worn under a costume to absorb sweat and protect the skin.","zh":"black base layer 是穿在服裝下面的貼身衣物，用來吸汗和保護皮膚。"},{"en":"Athletes may wear a base layer under uniforms during training.","zh":"運動員訓練時可能在制服裏穿貼身底衣。"},{"en":"A base layer helps performers feel more comfortable inside heavy costumes.","zh":"貼身底衣幫助表演者在厚重服裝中較舒服。"},{"en":"The black base layer shows that the job required physical preparation.","zh":"黑色貼身底衣顯示這份工作需要身體上的準備。"}],"source":"2014 Q6.pdf","sourcePage":4},{"front":"safety briefing","meaning":"安全簡介會","examples":[{"en":"I attended a safety briefing before the park opened.","zh":"我在公園開門前參加安全簡介會。"},{"en":"A safety briefing is a short meeting that explains risks, rules, and emergency procedures.","zh":"safety briefing 是解釋風險、規則和緊急程序的短會議。"},{"en":"Workers attend safety briefings before using heavy equipment or facing crowds.","zh":"員工在使用重型設備或面對人群前會參加安全簡介會。"},{"en":"Safety briefings protect both visitors and staff from accidents.","zh":"安全簡介會保護遊客和員工免於意外。"},{"en":"The briefing reminded performers that fun must be supported by careful planning.","zh":"簡介會提醒表演者，歡樂必須由仔細計劃支撐。"}],"source":"2014 Q6.pdf","sourcePage":4},{"front":"thereafter","meaning":"其後","examples":[{"en":"Thereafter, our team leader reminded us of the day’s schedule.","zh":"其後，我們的組長提醒我們當天的時間表。"},{"en":"Thereafter means after that time or after that event.","zh":"thereafter 指在那個時間或事件之後。"},{"en":"The students registered first; thereafter, they joined their activity groups.","zh":"學生先登記；其後，他們加入活動小組。"},{"en":"This word helps describe steps in a clear order.","zh":"這個詞幫助以清楚次序描述步驟。"},{"en":"The writer uses it to move from the safety briefing to the team instructions.","zh":"作者用它由安全簡介會轉到小組指示。"}],"source":"2014 Q6.pdf","sourcePage":4},{"front":"team leader","meaning":"組長","examples":[{"en":"Our team leader reminded us of the character schedule.","zh":"我們的組長提醒我們角色出場時間表。"},{"en":"A team leader is the person who guides, organises, and supports a group at work.","zh":"team leader 是在工作中引導、組織和支援小組的人。"},{"en":"A team leader may assign tasks, explain rules, and check safety.","zh":"組長可能分配任務、解釋規則和檢查安全。"},{"en":"In a theme park, a team leader helps performers follow the day’s plan.","zh":"在主題公園中，組長幫助表演者跟隨當天計劃。"},{"en":"The team leader’s instructions kept the performance organised and safe.","zh":"組長的指示令表演有組織並保持安全。"}],"source":"2014 Q6.pdf","sourcePage":4},{"front":"remind someone of","meaning":"提醒某人……","examples":[{"en":"Our team leader reminded us of the day’s character schedule.","zh":"我們的組長提醒我們當天的角色出場時間表。"},{"en":"Remind someone of means help someone remember something important.","zh":"remind someone of 指幫助某人記起重要事情。"},{"en":"A teacher may remind students of the homework deadline.","zh":"老師可能提醒學生功課截止日期。"},{"en":"Workers need reminders when schedules, routes, or safety signals change.","zh":"當時間表、路線或安全手勢改變時，員工需要提醒。"},{"en":"The team leader reminded performers so nobody missed an appearance.","zh":"組長提醒表演者，以免有人錯過出場。"}],"source":"2014 Q6.pdf","sourcePage":4},{"front":"character schedule","meaning":"角色出場時間表","examples":[{"en":"The team leader reminded us of the day’s character schedule.","zh":"組長提醒我們當天的角色出場時間表。"},{"en":"A character schedule is a timetable showing when and where each character appears.","zh":"character schedule 是顯示每個角色何時何地出現的時間表。"},{"en":"A theme park uses a character schedule to organise photo sessions and parades.","zh":"主題公園使用角色出場時間表來安排拍照時段和巡遊。"},{"en":"If performers miss the character schedule, visitors may wait in the wrong place.","zh":"如果表演者錯過角色出場時間表，遊客可能在錯誤地方等候。"},{"en":"The schedule helps the magic look effortless even though it is carefully planned.","zh":"時間表讓魔法感看似輕鬆，其實背後經過仔細安排。"}],"source":"2014 Q6.pdf","sourcePage":5},{"front":"parade route","meaning":"巡遊路線","examples":[{"en":"The team leader explained the parade route.","zh":"組長解釋巡遊路線。"},{"en":"A parade route is the path performers follow during a public procession.","zh":"parade route 指表演者在公開巡遊中跟隨的路線。"},{"en":"Workers must know the parade route so they can avoid crowding and accidents.","zh":"員工必須知道巡遊路線，才能避免擠迫和意外。"},{"en":"A clear route helps dancers, handlers, and characters move together safely.","zh":"清楚路線幫助舞蹈員、隨行工作人員和角色安全同行。"},{"en":"The parade route turns performance into organised movement through the park.","zh":"巡遊路線把表演變成有組織地穿過園區的移動。"}],"source":"2014 Q6.pdf","sourcePage":5},{"front":"emergency hand signals","meaning":"緊急手勢","examples":[{"en":"Performers had to remember emergency hand signals.","zh":"表演者必須記住緊急手勢。"},{"en":"Emergency hand signals are agreed gestures used to ask for help when speaking is difficult or impossible.","zh":"emergency hand signals 是在難以或無法說話時用來求助的約定手勢。"},{"en":"A performer may use a hand signal to show dizziness or ask to leave the area.","zh":"表演者可能用手勢表示頭暈或要求離開場地。"},{"en":"These signals matter because costumed characters often cannot speak clearly.","zh":"這些手勢很重要，因為穿着角色服裝的人通常不能清楚說話。"},{"en":"Emergency hand signals protect workers hidden inside heavy costumes.","zh":"緊急手勢保護藏在厚重服裝裏的工作者。"}],"source":"2014 Q6.pdf","sourcePage":5},{"front":"brought out","meaning":"被拿出來","examples":[{"en":"Once the costume was brought out, the transformation began.","zh":"服裝一被拿出來，轉變就開始了。"},{"en":"Brought out means taken out and presented for use.","zh":"brought out 指被拿出來並準備使用。"},{"en":"The birthday cake was brought out after everyone sang.","zh":"大家唱完生日歌後，生日蛋糕被拿出來。"},{"en":"When the costume was brought out, the ordinary student began becoming a character.","zh":"當服裝被拿出來，普通學生開始變成角色。"},{"en":"This phrase marks the moment when preparation turned into performance.","zh":"這個片語標誌着準備變成表演的一刻。"}],"source":"2014 Q6.pdf","sourcePage":5},{"front":"the real transformation began","meaning":"真正的轉變開始","examples":[{"en":"Once the costume was brought out, the real transformation began.","zh":"服裝一被拿出來，真正的轉變就開始了。"},{"en":"The real transformation began means the actual change from ordinary person to performer started.","zh":"the real transformation began 指由普通人變成表演者的實際改變開始了。"},{"en":"When an actor puts on makeup, the real transformation into the character begins.","zh":"演員化妝時，真正變成角色的轉變開始。"},{"en":"A costume can change how a person moves, sees, and is seen by others.","zh":"服裝可以改變一個人的動作、視線和別人看他的方式。"},{"en":"For the writer, transformation meant losing normal speech and becoming a cheerful figure.","zh":"對作者來說，轉變意味着失去正常說話能力，變成一個開朗角色。"}],"source":"2014 Q6.pdf","sourcePage":5},{"front":"headpiece","meaning":"頭套","examples":[{"en":"My headpiece blocked half my vision.","zh":"我的頭套擋住我一半視線。"},{"en":"A headpiece is the large part of a costume worn over the head.","zh":"headpiece 是服裝中戴在頭上的大型部分。"},{"en":"A mascot headpiece may be heavy and hot inside.","zh":"吉祥物頭套裏面可能又重又熱。"},{"en":"If a headpiece blocks vision, performers must move more carefully.","zh":"如果頭套擋住視線，表演者必須更小心移動。"},{"en":"The headpiece helped create the character but made the performer’s job harder.","zh":"頭套幫助創造角色，但令表演者工作更困難。"}],"source":"2014 Q6.pdf","sourcePage":5},{"front":"block half my vision","meaning":"擋住我一半視線","examples":[{"en":"My headpiece blocked half my vision.","zh":"我的頭套擋住我一半視線。"},{"en":"Block half my vision means stop me from seeing clearly through part of my view.","zh":"block half my vision 指阻礙我清楚看見視野中的一部分。"},{"en":"A large hat may block half your vision if it slips over your eyes.","zh":"如果大帽子滑到眼前，可能會擋住你一半視線。"},{"en":"When vision is blocked, walking through crowds becomes more dangerous.","zh":"當視線被擋住，在人群中行走會更危險。"},{"en":"The performer had to plan movements carefully because he could not see fully.","zh":"表演者必須仔細計劃動作，因為他無法完整看見。"}],"source":"2014 Q6.pdf","sourcePage":5},{"front":"simple gestures","meaning":"簡單手勢","examples":[{"en":"My gloves made simple gestures clumsy.","zh":"我的手套令簡單手勢變得笨拙。"},{"en":"Simple gestures are basic movements such as waving, pointing, or giving a thumbs-up.","zh":"simple gestures 指揮手、指向或豎拇指等基本動作。"},{"en":"Performers use simple gestures to communicate because they cannot speak in character.","zh":"表演者使用簡單手勢溝通，因為他們在角色中不能說話。"},{"en":"Large gloves can make even simple gestures difficult to control.","zh":"大手套會令即使是簡單手勢也難以控制。"},{"en":"The job required practice because small movements had to look clear and friendly.","zh":"這份工作需要練習，因為小動作必須看起來清楚而友善。"}],"source":"2014 Q6.pdf","sourcePage":5},{"front":"make gestures clumsy","meaning":"令手勢變得笨拙","examples":[{"en":"My gloves made simple gestures clumsy.","zh":"我的手套令簡單手勢變得笨拙。"},{"en":"Make gestures clumsy means make hand movements awkward, slow, or hard to control.","zh":"make gestures clumsy 指令手部動作變得笨拙、緩慢或難以控制。"},{"en":"Thick winter gloves can make writing or buttoning a coat clumsy.","zh":"厚冬天手套會令寫字或扣外套鈕扣變得笨拙。"},{"en":"When costume gloves make gestures clumsy, performers must exaggerate movements.","zh":"當角色手套令手勢變得笨拙，表演者必須誇張動作。"},{"en":"The phrase shows how the costume changed even basic body language.","zh":"這個片語顯示服裝如何改變基本肢體語言。"}],"source":"2014 Q6.pdf","sourcePage":5},{"front":"so wide that","meaning":"闊得……以致","examples":[{"en":"My shoes were so wide that every step had to be planned.","zh":"我的鞋闊得每一步都要事先想好。"},{"en":"So wide that shows something was very wide and caused a particular result.","zh":"so wide that 表示某物非常闊，並造成某個結果。"},{"en":"The box was so wide that it could not pass through the door.","zh":"那個箱子闊得不能穿過門口。"},{"en":"Costume shoes can be so wide that performers must walk slowly.","zh":"角色鞋可能闊得表演者必須慢慢走。"},{"en":"This structure clearly links the size of the shoes with careful movement.","zh":"這個結構清楚連接鞋子的大小和小心移動。"}],"source":"2014 Q6.pdf","sourcePage":5},{"front":"every step had to be planned","meaning":"每一步都要事先想好","examples":[{"en":"The shoes were so wide that every step had to be planned.","zh":"鞋子闊得每一步都要事先想好。"},{"en":"Every step had to be planned means each movement needed careful thought before walking.","zh":"every step had to be planned 指走路前每個動作都需要仔細思考。"},{"en":"On an icy path, every step has to be planned to avoid falling.","zh":"在結冰小路上，每一步都要事先想好，以免跌倒。"},{"en":"In a crowded theme park, large costume shoes make careless walking dangerous.","zh":"在擠迫主題公園中，大型角色鞋令隨便走路變得危險。"},{"en":"The performer could not simply move naturally; he had to calculate each step.","zh":"表演者不能自然地隨意移動；他必須計算每一步。"}],"source":"2014 Q6.pdf","sourcePage":6},{"front":"the first thing to know","meaning":"首先要知道的是","examples":[{"en":"The first thing to know is that a costumed performer cannot simply act cute.","zh":"首先要知道的是，穿着角色服裝的表演者不能只是扮可愛。"},{"en":"The first thing to know means the most important starting point for understanding something.","zh":"the first thing to know 指理解某事時最重要的起點。"},{"en":"The first thing to know about cooking is that sharp knives must be handled safely.","zh":"首先要知道的是，煮食時必須安全使用利刀。"},{"en":"This phrase prepares readers for a basic but important explanation.","zh":"這個片語為讀者準備一個基本但重要的解釋。"},{"en":"The writer uses it to correct the idea that the job is only about cuteness.","zh":"作者用它修正這份工作只是關於可愛的想法。"}],"source":"2014 Q6.pdf","sourcePage":6},{"front":"act cute","meaning":"扮可愛","examples":[{"en":"A costumed performer cannot simply act cute.","zh":"穿着角色服裝的表演者不能只是扮可愛。"},{"en":"Act cute means behave in a sweet, playful, or charming way to please others.","zh":"act cute 指用甜美、俏皮或討人喜歡的方式取悅他人。"},{"en":"A mascot may act cute by waving, tilting its head, or pretending to dance shyly.","zh":"吉祥物可能透過揮手、歪頭或假裝害羞跳舞來扮可愛。"},{"en":"Acting cute is only one part of the job; safety and control matter too.","zh":"扮可愛只是工作的一部分；安全和控制也很重要。"},{"en":"The performer must look cute while also avoiding accidents in a crowd.","zh":"表演者既要看起來可愛，也要在人群中避免意外。"}],"source":"2014 Q6.pdf","sourcePage":6},{"front":"slowly enough for","meaning":"慢到足以讓……","examples":[{"en":"We had to move slowly enough for children to follow us.","zh":"我們必須移動得慢到足以讓孩子跟上。"},{"en":"Slowly enough for means at a slow speed that allows someone to do something.","zh":"slowly enough for 指速度慢到能讓某人做到某事。"},{"en":"A teacher speaks slowly enough for beginners to take notes.","zh":"老師說得慢到足以讓初學者記筆記。"},{"en":"A character performer moves slowly enough so small children do not fall behind.","zh":"角色表演者走得慢到足以讓小孩子不會落後。"},{"en":"This phrase shows how performers adjust their movements for visitors.","zh":"這個片語顯示表演者如何為遊客調整動作。"}],"source":"2014 Q6.pdf","sourcePage":6},{"front":"energetically enough to","meaning":"有活力到足以……","examples":[{"en":"We had to move energetically enough to look alive.","zh":"我們必須有活力到足以看起來生動。"},{"en":"Energetically enough to means with enough energy to achieve a certain effect.","zh":"energetically enough to 指有足夠活力去達到某種效果。"},{"en":"A dancer must move energetically enough to fill a large stage.","zh":"舞蹈員必須有活力到足以撐起大舞台。"},{"en":"Costumed characters need energy because small movements may disappear inside large costumes.","zh":"角色表演者需要活力，因為小動作可能在大型服裝中看不清楚。"},{"en":"The performer had to seem lively even when the costume was heavy.","zh":"即使服裝沉重，表演者仍必須看起來生動。"}],"source":"2014 Q6.pdf","sourcePage":6},{"front":"look alive","meaning":"看起來生動","examples":[{"en":"A performer has to move energetically enough to look alive.","zh":"表演者必須動得有活力，足以看起來生動。"},{"en":"Look alive means appear lively, active, and full of energy.","zh":"look alive 指看起來有生命力、活躍和充滿能量。"},{"en":"Actors must look alive on stage even when they have repeated the scene many times.","zh":"演員即使已重複同一幕很多次，在舞台上仍必須看起來生動。"},{"en":"A mascot that moves too little may look lifeless rather than magical.","zh":"如果吉祥物動得太少，可能看起來呆板而不是有魔法感。"},{"en":"The performer used big gestures so the character looked alive to children.","zh":"表演者使用大動作，讓孩子覺得角色生動。"}],"source":"2014 Q6.pdf","sourcePage":6},{"front":"carefully enough not to","meaning":"小心到不會……","examples":[{"en":"We had to move carefully enough not to knock anyone over.","zh":"我們必須小心到不會撞倒任何人。"},{"en":"Carefully enough not to means with enough care to avoid causing a problem.","zh":"carefully enough not to 指足夠小心，以避免造成問題。"},{"en":"Workers carried the glass carefully enough not to break it.","zh":"工人搬玻璃時小心到不會弄破它。"},{"en":"Performers must move carefully enough not to frighten or hit children nearby.","zh":"表演者必須小心到不會嚇到或撞到附近孩子。"},{"en":"This phrase shows the balance between lively performance and safety.","zh":"這個片語顯示生動表演和安全之間的平衡。"}],"source":"2014 Q6.pdf","sourcePage":6},{"front":"knock anyone over","meaning":"撞倒任何人","examples":[{"en":"Performers must be careful not to knock anyone over.","zh":"表演者必須小心不要撞倒任何人。"},{"en":"Knock anyone over means accidentally hit someone so they fall down.","zh":"knock anyone over 指意外撞到某人，令對方跌倒。"},{"en":"A child running through a crowd may knock someone over.","zh":"孩子在人群中奔跑可能會撞倒別人。"},{"en":"Large costume shoes increase the risk of knocking visitors over.","zh":"大型角色鞋會增加撞倒遊客的風險。"},{"en":"Performers plan their steps carefully because safety matters more than speed.","zh":"表演者仔細計劃步伐，因為安全比速度更重要。"}],"source":"2014 Q6.pdf","sourcePage":6},{"front":"during each appearance","meaning":"每次出場期間","examples":[{"en":"During each appearance, a handler guided the queue.","zh":"每次出場期間，隨行工作人員指引排隊人龍。"},{"en":"During each appearance means while the performer is publicly present as the character.","zh":"during each appearance 指表演者以角色身份公開出現的期間。"},{"en":"During each appearance, the character waved, posed, and interacted with children.","zh":"每次出場期間，角色會揮手、擺姿勢並與孩子互動。"},{"en":"Staff must watch carefully during each appearance because crowds can become excited.","zh":"每次出場期間，員工必須仔細觀察，因為人群可能變得興奮。"},{"en":"The phrase shows that every public moment required support and organisation.","zh":"這個片語顯示每個公開時刻都需要支援和組織。"}],"source":"2014 Q6.pdf","sourcePage":6},{"front":"handler","meaning":"隨行工作人員","examples":[{"en":"A handler guided the queue and protected the performer.","zh":"隨行工作人員指引排隊人龍並保護表演者。"},{"en":"A handler is a staff member who assists a costumed performer and manages visitors around them.","zh":"handler 是協助穿着角色服裝的表演者並管理周圍遊客的員工。"},{"en":"The handler tells families where to stand for photos.","zh":"隨行工作人員會告訴家庭拍照時站在哪裏。"},{"en":"Handlers are important because performers inside costumes may not see or speak clearly.","zh":"隨行工作人員很重要，因為服裝裏的表演者未必看得清或能清楚說話。"},{"en":"The handler protects both the character’s magic and the worker’s safety.","zh":"隨行工作人員同時保護角色的魔法感和工作者的安全。"}],"source":"2014 Q6.pdf","sourcePage":6},{"front":"guide the queue","meaning":"指引排隊人龍","examples":[{"en":"The handler guided the queue during each appearance.","zh":"隨行工作人員在每次出場期間指引排隊人龍。"},{"en":"Guide the queue means organise people waiting in line and tell them where to go.","zh":"guide the queue 指組織排隊的人，並告訴他們去哪裏。"},{"en":"Staff guide the queue so visitors take turns fairly.","zh":"員工指引排隊人龍，讓遊客公平輪候。"},{"en":"A clear queue prevents pushing, confusion, and unsafe crowding.","zh":"清楚的隊伍可以避免推撞、混亂和不安全的擠迫。"},{"en":"The handler guided the queue so the performer could focus on greeting children.","zh":"隨行工作人員指引隊伍，讓表演者專心問候孩子。"}],"source":"2014 Q6.pdf","sourcePage":7},{"front":"overexcited visitors","meaning":"過度興奮的遊客","examples":[{"en":"The handler protected us from overexcited visitors.","zh":"隨行工作人員保護我們免受過度興奮的遊客影響。"},{"en":"Overexcited visitors are guests who become too enthusiastic and may act carelessly.","zh":"overexcited visitors 指變得太熱情、可能行為粗心的遊客。"},{"en":"Overexcited visitors may rush forward, pull costumes, or ignore safety rules.","zh":"過度興奮的遊客可能衝上前、拉服裝或忽視安全規則。"},{"en":"Workers need to manage excitement so fun does not become dangerous.","zh":"員工需要管理興奮情緒，讓樂趣不會變成危險。"},{"en":"The handler’s job was to protect the performer while keeping visitors happy.","zh":"隨行工作人員的工作是在保持遊客高興的同時保護表演者。"}],"source":"2014 Q6.pdf","sourcePage":7},{"front":"retreat for water","meaning":"退下來喝水","examples":[{"en":"The handler reminded us when to retreat for water.","zh":"隨行工作人員提醒我們何時退下來喝水。"},{"en":"Retreat for water means leave the performance area briefly to drink water and recover.","zh":"retreat for water 指短暫離開表演區去喝水和恢復。"},{"en":"A performer may retreat for water after dancing under the sun.","zh":"表演者在烈日下跳舞後可能要退下來喝水。"},{"en":"Regular water breaks prevent heat, dizziness, and exhaustion.","zh":"定期喝水休息可以防止中暑、頭暈和疲勞。"},{"en":"The phrase shows that recovery is part of safe performance.","zh":"這個片語顯示恢復也是安全表演的一部分。"}],"source":"2014 Q6.pdf","sourcePage":7},{"front":"photo sessions","meaning":"拍照時段","examples":[{"en":"The day included photo sessions and mini-dances.","zh":"一天中包括拍照時段和小型舞蹈。"},{"en":"Photo sessions are planned periods when visitors take pictures with performers or characters.","zh":"photo sessions 是安排讓遊客與表演者或角色拍照的時段。"},{"en":"During photo sessions, families line up and pose with the mascot.","zh":"拍照時段期間，家庭排隊與吉祥物擺姿勢拍照。"},{"en":"Photo sessions require patience because performers repeat the same cheerful gestures many times.","zh":"拍照時段需要耐性，因為表演者要多次重複同樣開朗手勢。"},{"en":"For visitors, a photo session is quick; for performers, it is careful physical work.","zh":"對遊客來說，拍照時段很短；對表演者來說，這是仔細的體力工作。"}],"source":"2014 Q6.pdf","sourcePage":7},{"front":"mini-dances","meaning":"小型舞蹈","examples":[{"en":"From photo sessions to mini-dances, the day was physically demanding.","zh":"從拍照時段到小型舞蹈，這一天在體力上要求很高。"},{"en":"Mini-dances are short dance routines performed for visitors.","zh":"mini-dances 是為遊客表演的短舞蹈。"},{"en":"A mascot may do mini-dances to entertain children waiting in line.","zh":"吉祥物可能跳小型舞蹈來娛樂排隊中的孩子。"},{"en":"Mini-dances look simple, but they are tiring inside a heavy costume.","zh":"小型舞蹈看似簡單，但在厚重服裝裏面很疲累。"},{"en":"These dances helped the character look alive during the hot summer day.","zh":"這些舞蹈幫助角色在炎熱夏日中看起來生動。"}],"source":"2014 Q6.pdf","sourcePage":7},{"front":"move in cycles of","meaning":"以……循環進行","examples":[{"en":"The day moved in cycles of performance and recovery.","zh":"一天以表演與恢復循環進行。"},{"en":"Move in cycles of means repeat a pattern of different stages again and again.","zh":"move in cycles of 指反覆重複不同階段的模式。"},{"en":"A hospital shift may move in cycles of checking patients and recording notes.","zh":"醫院更次可能以檢查病人和記錄筆記循環進行。"},{"en":"The performer’s day repeated performance, water breaks, and preparation.","zh":"表演者的一天反覆經歷表演、喝水休息和準備。"},{"en":"This pattern shows that rest was necessary for continued performance.","zh":"這種模式顯示休息對持續表演是必要的。"}],"source":"2014 Q6.pdf","sourcePage":7},{"front":"performance and recovery","meaning":"表演與恢復","examples":[{"en":"The day moved in cycles of performance and recovery.","zh":"一天以表演與恢復循環進行。"},{"en":"Performance and recovery mean active public work followed by rest and physical repair.","zh":"performance and recovery 指公開活躍工作之後接着休息和身體恢復。"},{"en":"Athletes also move between performance and recovery during long competitions.","zh":"運動員在長時間比賽中也會在表現和恢復之間轉換。"},{"en":"Without recovery, performers may become dizzy, unsafe, or unable to continue.","zh":"沒有恢復，表演者可能會頭暈、不安全或無法繼續。"},{"en":"The phrase shows that entertaining visitors requires both energy and rest.","zh":"這個片語顯示娛樂遊客需要能量，也需要休息。"}],"source":"2014 Q6.pdf","sourcePage":7},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time I clocked out, my T-shirt was soaked.","zh":"到我下班打卡的時候，我的 T 恤已經濕透。"},{"en":"By the time means when a certain moment arrived, something had already happened.","zh":"by the time 指到某個時刻時，某事已經發生。"},{"en":"By the time the lesson ended, the students had finished their group work.","zh":"到課堂結束的時候，學生已經完成小組工作。"},{"en":"This phrase often shows the result of a long process.","zh":"這個片語常用來顯示長時間過程的結果。"},{"en":"By the time the writer finished work, the heat had left his shirt wet.","zh":"到作者完成工作的時候，高溫已令他的 T 恤濕透。"}],"source":"2014 Q6.pdf","sourcePage":7},{"front":"clocked out","meaning":"下班打卡","examples":[{"en":"I clocked out after a long day in costume.","zh":"穿着服裝工作一整天後，我下班打卡。"},{"en":"Clocked out means recorded the time when work ended.","zh":"clocked out 指記錄工作結束的時間。"},{"en":"Shop assistants clocked out before leaving the store.","zh":"店員離開店舖前下班打卡。"},{"en":"Clocking out marks the official end of a worker’s shift.","zh":"下班打卡標誌着員工更次正式結束。"},{"en":"For the writer, clocking out also meant finally leaving the character behind.","zh":"對作者來說，下班打卡也代表終於離開角色。"}],"source":"2014 Q6.pdf","sourcePage":7},{"front":"soaked","meaning":"濕透","examples":[{"en":"By the time I clocked out, my T-shirt was soaked.","zh":"到我下班打卡的時候，我的 T 恤已經濕透。"},{"en":"Soaked means completely wet.","zh":"soaked 指完全濕了。"},{"en":"My shoes were soaked after walking home in heavy rain.","zh":"我在大雨中走回家後，鞋子濕透了。"},{"en":"A performer’s shirt can become soaked with sweat inside a heavy costume.","zh":"表演者在厚重服裝裏面，衣服可能被汗水濕透。"},{"en":"The soaked T-shirt showed how physically hard the job really was.","zh":"濕透的 T 恤顯示這份工作在體力上有多辛苦。"}],"source":"2014 Q6.pdf","sourcePage":7},{"front":"painted smile","meaning":"畫上去的笑容","examples":[{"en":"My character’s painted smile still looked perfect.","zh":"我角色畫上去的笑容仍然看起來完美。"},{"en":"A painted smile is a fixed smile drawn or printed on a costume face.","zh":"painted smile 是畫在或印在角色臉上的固定笑容。"},{"en":"A mascot’s painted smile can look cheerful even when the performer is tired.","zh":"即使表演者疲倦，吉祥物畫上去的笑容仍可看起來開朗。"},{"en":"The painted smile hides heat, sweat, and discomfort from visitors.","zh":"畫上去的笑容向遊客隱藏高溫、汗水和不適。"},{"en":"This contrast helps readers see the difference between appearance and reality.","zh":"這種對比幫助讀者看見外表和現實之間的差異。"}],"source":"2014 Q6.pdf","sourcePage":8},{"front":"the best part of","meaning":"最好的部分","examples":[{"en":"The best part of the job was the direct happiness it created.","zh":"這份工作最好的部分是它直接帶來的快樂。"},{"en":"The best part of means the most enjoyable or valuable aspect of something.","zh":"the best part of 指某事中最令人享受或最有價值的方面。"},{"en":"The best part of volunteering was seeing children become more confident.","zh":"做義工最好的部分是看見孩子變得更有信心。"},{"en":"This phrase helps a writer identify what made an experience worthwhile.","zh":"這個片語幫助作者指出經歷中值得的地方。"},{"en":"For the performer, the best part was making visitors genuinely happy.","zh":"對表演者來說，最好的部分是真正令遊客快樂。"}],"source":"2014 Q6.pdf","sourcePage":8},{"front":"direct happiness","meaning":"直接帶來的快樂","examples":[{"en":"The best part of the job was the direct happiness it created.","zh":"這份工作最好的部分是它直接帶來的快樂。"},{"en":"Direct happiness means clear, immediate joy that can be seen or felt at once.","zh":"direct happiness 指能立即看見或感受到的清楚快樂。"},{"en":"A child’s smile after meeting a favourite character is direct happiness.","zh":"孩子見到最喜歡的角色後露出的笑容，就是直接帶來的快樂。"},{"en":"Some jobs feel meaningful because workers can see the happiness they create.","zh":"有些工作令人覺得有意義，因為工作者能看見自己創造的快樂。"},{"en":"The writer valued direct happiness because it made the exhausting shift worthwhile.","zh":"作者重視直接快樂，因為它令疲累更次變得值得。"}],"source":"2014 Q6.pdf","sourcePage":8},{"front":"wearing a birthday badge","meaning":"戴着生日襟章","examples":[{"en":"A little boy wearing a birthday badge ran towards me.","zh":"一個戴着生日襟章的小男孩向我跑來。"},{"en":"Wearing a birthday badge means having a small pin or sign that shows it is one’s birthday.","zh":"wearing a birthday badge 指戴着顯示自己生日的小襟章或標誌。"},{"en":"Theme parks often give birthday badges to children celebrating their special day.","zh":"主題公園常給慶祝生日的孩子生日襟章。"},{"en":"A performer may give extra attention to a child wearing a birthday badge.","zh":"表演者可能會特別留意戴着生日襟章的孩子。"},{"en":"The badge helped the writer understand that the moment mattered deeply to the boy.","zh":"襟章幫助作者明白那一刻對男孩很重要。"}],"source":"2014 Q6.pdf","sourcePage":8},{"front":"ran towards me","meaning":"向我跑來","examples":[{"en":"A little boy ran towards me and hugged my furry waist.","zh":"一個小男孩向我跑來，抱住我毛茸茸的腰部。"},{"en":"Ran towards me means moved quickly in my direction.","zh":"ran towards me 指快速朝我的方向移動。"},{"en":"The child ran towards the mascot when he saw his favourite character.","zh":"孩子看見最喜歡的角色時，向吉祥物跑去。"},{"en":"Visitors may run towards performers when they are excited, so handlers must watch carefully.","zh":"遊客興奮時可能向表演者跑來，所以隨行工作人員必須小心觀察。"},{"en":"The boy running towards the writer showed pure, immediate happiness.","zh":"男孩向作者跑來，顯示出純粹而即時的快樂。"}],"source":"2014 Q6.pdf","sourcePage":8},{"front":"furry waist","meaning":"毛茸茸的腰部","examples":[{"en":"The boy hugged my furry waist.","zh":"男孩抱住我毛茸茸的腰部。"},{"en":"A furry waist is the soft, hair-covered middle part of a character costume.","zh":"furry waist 指角色服裝中柔軟、有毛的腰部位置。"},{"en":"Children often hug mascots because the furry costume feels friendly.","zh":"孩子常擁抱吉祥物，因為毛茸茸的服裝感覺友善。"},{"en":"The performer felt the hug through the costume even though he could not speak.","zh":"雖然表演者不能說話，但他透過服裝感受到那個擁抱。"},{"en":"The furry waist made the character seem warm and approachable.","zh":"毛茸茸的腰部令角色看起來溫暖而容易親近。"}],"source":"2014 Q6.pdf","sourcePage":8},{"front":"whispered","meaning":"低聲說","examples":[{"en":"The little boy whispered, “I found you!”","zh":"小男孩低聲說：「我找到你了！」"},{"en":"Whispered means spoke very softly and quietly.","zh":"whispered 指非常輕聲和安靜地說話。"},{"en":"A child may whisper when feeling shy, excited, or full of wonder.","zh":"孩子害羞、興奮或感到驚奇時，可能會低聲說話。"},{"en":"Whispering can make a moment feel private even in a crowded place.","zh":"低聲說話可以令擠迫地方中的一刻感覺很私人。"},{"en":"The boy’s whisper showed that the character felt real to him.","zh":"男孩的低語顯示這個角色對他來說像是真的。"}],"source":"2014 Q6.pdf","sourcePage":8},{"front":"could not reply","meaning":"不能回答","examples":[{"en":"Of course, I could not reply while in character.","zh":"當然，我在角色中不能回答。"},{"en":"Could not reply means was unable or not allowed to answer.","zh":"could not reply 指無法或不被允許作答。"},{"en":"A performer inside a mascot costume may not reply because the character has no speaking role.","zh":"在吉祥物服裝裏的表演者可能不能回答，因為角色沒有說話設定。"},{"en":"Not replying helps protect the illusion for children.","zh":"不回答有助保護孩子心中的幻想。"},{"en":"The writer had to answer through gestures instead of words.","zh":"作者必須用手勢而不是文字回應。"}],"source":"2014 Q6.pdf","sourcePage":8},{"front":"knelt down","meaning":"跪下；蹲下","examples":[{"en":"I knelt down and tapped my heart.","zh":"我跪下並輕拍心口。"},{"en":"Knelt down means lowered the body onto one or both knees.","zh":"knelt down 指把身體降低到單膝或雙膝着地的位置。"},{"en":"A performer may kneel down to become closer to a small child’s height.","zh":"表演者可能蹲下來接近小孩子的高度。"},{"en":"Kneeling down can make a large character look less frightening.","zh":"蹲下可以令大型角色看起來沒那麼可怕。"},{"en":"The writer knelt down to show warmth and attention without speaking.","zh":"作者跪下來，在不用說話的情況下表達溫暖和留意。"}],"source":"2014 Q6.pdf","sourcePage":8},{"front":"tapped my heart","meaning":"輕拍心口","examples":[{"en":"I tapped my heart to show warmth without speaking.","zh":"我輕拍心口，在不說話的情況下表達溫暖。"},{"en":"Tapped my heart means lightly touched the chest to express care, affection, or thanks.","zh":"tapped my heart 指輕輕碰胸口，以表達關心、喜愛或感謝。"},{"en":"A performer may tap the heart after receiving a child’s drawing.","zh":"表演者收到孩子的畫後，可能會輕拍心口。"},{"en":"This gesture can communicate feeling when words are not allowed.","zh":"當不允許說話時，這個手勢可以傳達感情。"},{"en":"The writer used it to tell the boy that the moment mattered.","zh":"作者用它告訴男孩，那一刻很重要。"}],"source":"2014 Q6.pdf","sourcePage":8},{"front":"dramatic thumbs-up","meaning":"誇張的豎拇指手勢","examples":[{"en":"I gave him the most dramatic thumbs-up I could manage.","zh":"我盡力給他一個最誇張的豎拇指手勢。"},{"en":"A dramatic thumbs-up is an exaggerated gesture showing approval, excitement, or encouragement.","zh":"dramatic thumbs-up 是表示讚同、興奮或鼓勵的誇張手勢。"},{"en":"A mascot may give a dramatic thumbs-up after a child poses for a photo.","zh":"孩子擺好姿勢拍照後，吉祥物可能給他一個誇張的豎拇指手勢。"},{"en":"Large costumes require dramatic gestures because small movements may be hard to see.","zh":"大型服裝需要誇張手勢，因為小動作可能難以看見。"},{"en":"The thumbs-up replaced spoken praise and made the boy feel noticed.","zh":"豎拇指手勢取代了口頭稱讚，令男孩感到被看見。"}],"source":"2014 Q6.pdf","sourcePage":9},{"front":"the whole shift","meaning":"整個更次","examples":[{"en":"That moment alone made the whole shift worthwhile.","zh":"單是那一刻就令整個更次值得。"},{"en":"The whole shift means the entire period of work for that day.","zh":"the whole shift 指當天整段工作時間。"},{"en":"A nurse may feel one grateful smile made the whole shift worthwhile.","zh":"護士可能覺得一個感激微笑令整個更次值得。"},{"en":"One meaningful moment can change how a worker remembers a tiring day.","zh":"一個有意義的時刻可以改變工作者如何記住疲累一天。"},{"en":"For the writer, the boy’s happiness gave value to the entire shift.","zh":"對作者來說，男孩的快樂令整個更次有了價值。"}],"source":"2014 Q6.pdf","sourcePage":9},{"front":"worthwhile","meaning":"值得的","examples":[{"en":"That moment made the whole shift worthwhile.","zh":"那一刻令整個更次變得值得。"},{"en":"Worthwhile means worth the time, effort, or discomfort spent on it.","zh":"worthwhile 指值得花時間、努力或承受不適。"},{"en":"Studying hard feels worthwhile when students understand the lesson deeply.","zh":"當學生深刻理解課堂，努力溫習就會變得值得。"},{"en":"A tiring job can be worthwhile if it teaches important lessons.","zh":"如果一份疲累工作教會重要道理，它也可以值得。"},{"en":"The writer felt the sweat was worthwhile because it created real happiness.","zh":"作者覺得流汗是值得的，因為它創造了真實快樂。"}],"source":"2014 Q6.pdf","sourcePage":9},{"front":"what I loved about","meaning":"我喜歡……的地方是","examples":[{"en":"What I loved about the job was that it forced me to communicate without words.","zh":"我喜歡這份工作的地方是，它迫使我不用言語溝通。"},{"en":"What I loved about means the part of something that I liked or valued most.","zh":"what I loved about 指某事中我最喜歡或最重視的部分。"},{"en":"What I loved about volunteering was meeting people I would not usually meet.","zh":"我喜歡做義工的地方是能遇見平時不會遇到的人。"},{"en":"This phrase introduces a personal reflection on value.","zh":"這個片語引出對價值的個人反思。"},{"en":"The writer loved that the job taught communication beyond speaking.","zh":"作者喜歡這份工作教會他語言以外的溝通。"}],"source":"2014 Q6.pdf","sourcePage":9},{"front":"forced me to","meaning":"迫使我","examples":[{"en":"The job forced me to communicate without words.","zh":"這份工作迫使我不用言語溝通。"},{"en":"Forced me to means made me do something because the situation left no easier choice.","zh":"forced me to 指情況令我不得不做某事，沒有更容易的選擇。"},{"en":"A broken lift forced us to use the stairs.","zh":"升降機壞了，迫使我們走樓梯。"},{"en":"The costume forced the performer to use gestures instead of speech.","zh":"服裝迫使表演者用手勢而不是說話。"},{"en":"Being forced to communicate differently helped the writer become more observant.","zh":"被迫以不同方式溝通，幫助作者變得更善於觀察。"}],"source":"2014 Q6.pdf","sourcePage":9},{"front":"communicate without words","meaning":"不用言語溝通","examples":[{"en":"I learnt to communicate without words.","zh":"我學會不用言語溝通。"},{"en":"Communicate without words means share meaning through gestures, movement, facial expression, or body language.","zh":"communicate without words 指透過手勢、動作、表情或身體語言傳達意思。"},{"en":"A smile or wave can communicate without words in a noisy place.","zh":"在嘈雜地方，一個微笑或揮手可以不用言語溝通。"},{"en":"Performers communicate without words when their characters are not allowed to speak.","zh":"當角色不被允許說話時，表演者就要不用言語溝通。"},{"en":"This skill helped the writer comfort children and entertain visitors.","zh":"這項技能幫助作者安慰孩子和娛樂遊客。"}],"source":"2014 Q6.pdf","sourcePage":9},{"front":"calm a crying toddler","meaning":"安撫哭泣的幼童","examples":[{"en":"I learnt how to calm a crying toddler with smaller movements.","zh":"我學會如何用較細小的動作安撫哭泣的幼童。"},{"en":"Calm a crying toddler means help a very young child stop crying and feel safe.","zh":"calm a crying toddler 指幫助年幼孩子停止哭泣並感到安全。"},{"en":"A parent may calm a crying toddler by speaking softly and moving slowly.","zh":"父母可能透過輕聲說話和慢慢移動來安撫哭泣的幼童。"},{"en":"Large gestures can frighten toddlers, so smaller movements may work better.","zh":"大動作可能嚇到幼童，所以較細小的動作可能更有效。"},{"en":"The performer used gentle body language to make the child less afraid.","zh":"表演者使用溫柔肢體語言，令孩子沒那麼害怕。"}],"source":"2014 Q6.pdf","sourcePage":9},{"front":"smaller movements","meaning":"較細小的動作","examples":[{"en":"Smaller movements helped me calm a crying toddler.","zh":"較細小的動作幫助我安撫哭泣的幼童。"},{"en":"Smaller movements are gentler, less sudden actions of the body or hands.","zh":"smaller movements 指較溫柔、不太突然的身體或手部動作。"},{"en":"A performer may wave slowly instead of jumping when a child is nervous.","zh":"當孩子緊張時，表演者可能慢慢揮手，而不是跳起來。"},{"en":"Smaller movements can make a large costume seem softer and safer.","zh":"較細小的動作可以令大型服裝看起來更柔和安全。"},{"en":"The writer learned that communication depends on reading the visitor’s feelings.","zh":"作者學會溝通取決於讀懂遊客感受。"}],"source":"2014 Q6.pdf","sourcePage":9},{"front":"bored teenagers","meaning":"感到沉悶的青少年","examples":[{"en":"I learnt how to entertain bored teenagers.","zh":"我學會如何娛樂感到沉悶的青少年。"},{"en":"Bored teenagers are young people who feel uninterested or hard to impress.","zh":"bored teenagers 指感到無聊或難以被打動的年輕人。"},{"en":"Bored teenagers may pretend not to care during a family trip.","zh":"感到沉悶的青少年可能在家庭旅行中假裝不在乎。"},{"en":"Performers need humour and quick reactions to entertain bored teenagers.","zh":"表演者需要幽默和快速反應來娛樂感到沉悶的青少年。"},{"en":"The writer used exaggerated embarrassment to make them laugh.","zh":"作者用誇張的尷尬反應令他們發笑。"}],"source":"2014 Q6.pdf","sourcePage":9},{"front":"exaggerated embarrassment","meaning":"誇張的尷尬反應","examples":[{"en":"I entertained bored teenagers with exaggerated embarrassment.","zh":"我用誇張的尷尬反應娛樂感到沉悶的青少年。"},{"en":"Exaggerated embarrassment means acting much more shy, awkward, or ashamed than one really feels.","zh":"exaggerated embarrassment 指表演出比真實感受更害羞、笨拙或不好意思的樣子。"},{"en":"A performer may cover the character’s face after missing a dance step.","zh":"表演者跳錯舞步後，可能遮住角色的臉。"},{"en":"Exaggerated embarrassment can be funny because the audience knows it is playful.","zh":"誇張的尷尬反應可以很好笑，因為觀眾知道那是玩笑式的。"},{"en":"The writer used it to connect with teenagers who were hard to impress.","zh":"作者用它與難以打動的青少年建立連繫。"}],"source":"2014 Q6.pdf","sourcePage":9},{"front":"make shy children feel seen","meaning":"令害羞的孩子感到被看見","examples":[{"en":"I learnt how to make shy children feel seen.","zh":"我學會如何令害羞的孩子感到被看見。"},{"en":"Make shy children feel seen means help quiet children feel noticed, understood, and valued.","zh":"make shy children feel seen 指幫助安靜的孩子感到被注意、被理解和被重視。"},{"en":"A performer can make a shy child feel seen by waving gently from a distance.","zh":"表演者可以從遠處溫柔揮手，令害羞孩子感到被看見。"},{"en":"Shy children may need time before they approach a large character.","zh":"害羞孩子可能需要時間才敢走近大型角色。"},{"en":"Small, patient attention can make a child feel important.","zh":"細小而耐心的注意可以令孩子感到自己很重要。"}],"source":"2014 Q6.pdf","sourcePage":10},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, the work made me a better team player.","zh":"更重要的是，這份工作令我成為更好的團隊合作者。"},{"en":"More importantly introduces a point that matters more than the previous point.","zh":"more importantly 用來引出比前一點更重要的重點。"},{"en":"The job was fun; more importantly, it taught responsibility.","zh":"這份工作有趣；更重要的是，它教會責任。"},{"en":"This phrase helps writers organise ideas by importance.","zh":"這個片語幫助作者按重要性組織想法。"},{"en":"The writer uses it to move from personal skill to teamwork.","zh":"作者用它由個人技巧轉向團隊合作。"}],"source":"2014 Q6.pdf","sourcePage":10},{"front":"team player","meaning":"團隊合作者","examples":[{"en":"The work made me a better team player.","zh":"這份工作令我成為更好的團隊合作者。"},{"en":"A team player is someone who works well with others and supports the group.","zh":"team player 指能與他人合作並支援團隊的人。"},{"en":"A good team player listens, follows instructions, and helps when problems appear.","zh":"好的團隊合作者會聆聽、跟從指示，並在問題出現時幫忙。"},{"en":"Theme park performers must be team players because safety depends on cooperation.","zh":"主題公園表演者必須是團隊合作者，因為安全依賴合作。"},{"en":"The writer became a better team player by trusting handlers and other staff.","zh":"作者透過信任隨行工作人員和其他員工，成為更好的團隊合作者。"}],"source":"2014 Q6.pdf","sourcePage":10},{"front":"parade dancers","meaning":"巡遊舞蹈員","examples":[{"en":"The handler, parade dancers, cleaning staff, and performers had to trust one another.","zh":"隨行工作人員、巡遊舞蹈員、清潔職員和表演者必須互相信任。"},{"en":"Parade dancers are performers who dance along a planned route during a parade.","zh":"parade dancers 指在巡遊中沿指定路線跳舞的表演者。"},{"en":"Parade dancers must stay aware of music, spacing, crowds, and other performers.","zh":"巡遊舞蹈員必須留意音樂、距離、人群和其他表演者。"},{"en":"If dancers and characters do not coordinate, the parade may become unsafe.","zh":"如果舞蹈員和角色沒有協調，巡遊可能變得不安全。"},{"en":"They are part of the hidden team that makes the park feel magical.","zh":"他們是令公園感覺有魔法的隱藏團隊一部分。"}],"source":"2014 Q6.pdf","sourcePage":10},{"front":"cleaning staff","meaning":"清潔職員","examples":[{"en":"Cleaning staff helped keep the park running smoothly.","zh":"清潔職員幫助公園順利運作。"},{"en":"Cleaning staff are workers who keep places clean, safe, and pleasant for visitors.","zh":"cleaning staff 指保持地方乾淨、安全和舒適的員工。"},{"en":"Cleaning staff remove rubbish, wipe surfaces, and clear spills.","zh":"清潔職員清理垃圾、擦拭表面和處理濺出的液體。"},{"en":"Visitors may not notice cleaning staff unless something goes wrong.","zh":"除非出現問題，遊客可能不會留意清潔職員。"},{"en":"Their invisible labour helps the theme park remain welcoming.","zh":"他們的隱形勞動幫助主題公園保持歡迎人的感覺。"}],"source":"2014 Q6.pdf","sourcePage":10},{"front":"trust one another","meaning":"互相信任","examples":[{"en":"The whole team had to trust one another.","zh":"整個團隊必須互相信任。"},{"en":"Trust one another means believe that each person will do their part responsibly.","zh":"trust one another 指相信每個人都會負責任地完成自己的部分。"},{"en":"Performers trust handlers to guide them when their vision is blocked.","zh":"當視線被擋住，表演者要信任隨行工作人員引導他們。"},{"en":"Team members trust one another when safety depends on shared attention.","zh":"當安全依賴共同留意，團隊成員就必須互相信任。"},{"en":"Without trust, the cheerful performance could quickly become unsafe.","zh":"沒有信任，開朗表演很快可能變得不安全。"}],"source":"2014 Q6.pdf","sourcePage":10},{"front":"if not most","meaning":"即使不是大多數，也是很多","examples":[{"en":"Many visitors, if not most, noticed only the cheerful character.","zh":"很多遊客，即使不是大多數，也只注意到開朗的角色。"},{"en":"If not most means possibly most, but at least many.","zh":"if not most 指即使不是大多數，也至少是很多。"},{"en":"Many students, if not most, feel nervous before their first interview.","zh":"很多學生，即使不是大多數，第一次面試前都會緊張。"},{"en":"This phrase makes a careful claim without sounding too absolute.","zh":"這個片語作出謹慎說法，而不會顯得太絕對。"},{"en":"The writer uses it to suggest that most visitors see the magic, not the labour.","zh":"作者用它暗示大多數遊客看見魔法感，而不是勞動。"}],"source":"2014 Q6.pdf","sourcePage":10},{"front":"cheerful character","meaning":"開朗的角色","examples":[{"en":"Visitors noticed only the cheerful character.","zh":"遊客只注意到開朗的角色。"},{"en":"A cheerful character is a happy-looking role that entertains people with bright movement and expression.","zh":"cheerful character 指看起來快樂、用明亮動作和表情娛樂人的角色。"},{"en":"A cheerful character may wave, dance, and pose for photos.","zh":"開朗的角色可能會揮手、跳舞和擺姿勢拍照。"},{"en":"Visitors may forget the performer is tired because the character always looks happy.","zh":"因為角色總是看起來快樂，遊客可能忘記表演者很疲倦。"},{"en":"The cheerful character is the public face of much hidden work.","zh":"開朗的角色是大量隱藏工作的公開面孔。"}],"source":"2014 Q6.pdf","sourcePage":10},{"front":"what they did not see","meaning":"他們看不見的是","examples":[{"en":"What they did not see was the team behind the magic.","zh":"他們看不見的是魔法背後的團隊。"},{"en":"What they did not see means the hidden part that people failed to notice.","zh":"what they did not see 指人們沒有注意到的隱藏部分。"},{"en":"What customers did not see was the kitchen team preparing food for hours.","zh":"顧客看不見的是廚房團隊花幾小時準備食物。"},{"en":"This phrase contrasts visible happiness with invisible labour.","zh":"這個片語對比可見的快樂和隱形勞動。"},{"en":"Visitors saw the character, but not the teamwork that protected the performance.","zh":"遊客看見角色，卻看不見保護表演的團隊合作。"}],"source":"2014 Q6.pdf","sourcePage":10},{"front":"well-organised team","meaning":"組織良好的團隊","examples":[{"en":"A well-organised team kept the magic alive.","zh":"組織良好的團隊讓魔法般的氣氛延續。"},{"en":"A well-organised team is a group whose members know their roles and work together smoothly.","zh":"well-organised team 指成員知道自己角色並能順暢合作的團隊。"},{"en":"A school fair needs a well-organised team to manage booths, games, and safety.","zh":"學校嘉年華需要組織良好的團隊管理攤位、遊戲和安全。"},{"en":"In a theme park, good organisation makes performances look effortless.","zh":"在主題公園中，良好組織令表演看起來毫不費力。"},{"en":"The magic visitors enjoy depends on people working clearly together.","zh":"遊客享受的魔法感依賴人們清楚合作。"}],"source":"2014 Q6.pdf","sourcePage":10},{"front":"keep the magic alive","meaning":"讓魔法般的氣氛延續","examples":[{"en":"The team worked hard to keep the magic alive.","zh":"團隊努力工作，讓魔法般的氣氛延續。"},{"en":"Keep the magic alive means maintain the joyful illusion or special atmosphere for visitors.","zh":"keep the magic alive 指維持遊客心中的快樂幻想或特別氣氛。"},{"en":"Staff keep the magic alive by hiding problems and solving them quietly.","zh":"員工透過隱藏問題並安靜解決它們，讓魔法感延續。"},{"en":"Theme park magic disappears if visitors see confusion, danger, or tired performers.","zh":"如果遊客看見混亂、危險或疲累的表演者，主題公園的魔法感就會消失。"},{"en":"Keeping the magic alive requires teamwork, patience, and invisible labour.","zh":"讓魔法般的氣氛延續需要團隊合作、耐性和隱形勞動。"}],"source":"2014 Q6.pdf","sourcePage":11},{"front":"that said","meaning":"話雖如此","examples":[{"en":"That said, the job was not without its problems.","zh":"話雖如此，這份工作並非沒有問題。"},{"en":"That said means after accepting the previous point, a different or contrasting point follows.","zh":"that said 指接受前一點後，接着提出不同或相反的重點。"},{"en":"The trip was enjoyable; that said, the weather made it difficult.","zh":"旅程很愉快；話雖如此，天氣令它變得困難。"},{"en":"This phrase helps writers stay balanced by adding a limitation.","zh":"這個片語透過加入限制，幫助作者保持平衡。"},{"en":"The writer uses it to move from the job’s value to its difficulties.","zh":"作者用它由工作的價值轉到工作的困難。"}],"source":"2014 Q6.pdf","sourcePage":11},{"front":"not without its problems","meaning":"並非沒有問題","examples":[{"en":"The job was not without its problems.","zh":"這份工作並非沒有問題。"},{"en":"Not without its problems means something has value but also has difficulties or weaknesses.","zh":"not without its problems 指某事有價值，但也有困難或弱點。"},{"en":"Online learning is useful, but it is not without its problems.","zh":"網上學習有用，但並非沒有問題。"},{"en":"This phrase sounds balanced because it does not reject the job completely.","zh":"這個片語聽起來平衡，因為它不是完全否定這份工作。"},{"en":"The writer admits the job was meaningful while still discussing its challenges.","zh":"作者承認這份工作有意義，同時仍討論它的挑戰。"}],"source":"2014 Q6.pdf","sourcePage":11},{"front":"the most obvious difficulty","meaning":"最明顯的困難","examples":[{"en":"The most obvious difficulty was the heat.","zh":"最明顯的困難是炎熱。"},{"en":"The most obvious difficulty is the problem that is easiest to notice.","zh":"the most obvious difficulty 指最容易被注意到的問題。"},{"en":"For outdoor workers in summer, the most obvious difficulty is often the weather.","zh":"對夏天戶外工作者來說，最明顯的困難通常是天氣。"},{"en":"The heat was obvious because the performer was trapped inside a thick costume.","zh":"炎熱很明顯，因為表演者被困在厚重服裝裏。"},{"en":"This phrase begins the discussion of the job’s physical challenges.","zh":"這個片語開始討論這份工作的身體挑戰。"}],"source":"2014 Q6.pdf","sourcePage":11},{"front":"less like…than…","meaning":"與其說像……不如說像……","examples":[{"en":"The costume felt less like a uniform than a private sauna.","zh":"那套服裝與其說像制服，不如說像私人桑拿房。"},{"en":"Less like A than B means it seemed more similar to B than to A.","zh":"less like A than B 指某物不像 A，而更像 B。"},{"en":"The crowded bus felt less like transport than a moving oven.","zh":"擠迫巴士與其說像交通工具，不如說像移動焗爐。"},{"en":"This structure creates a strong comparison by replacing expectation with reality.","zh":"這個結構透過以現實取代預期，製造強烈比較。"},{"en":"The costume looked like a uniform outside, but felt like a sauna inside.","zh":"服裝外表像制服，但裏面感覺像桑拿房。"}],"source":"2014 Q6.pdf","sourcePage":11},{"front":"private sauna","meaning":"私人桑拿房","examples":[{"en":"The costume felt like a private sauna on hot afternoons.","zh":"在炎熱下午，那套服裝感覺像私人桑拿房。"},{"en":"A private sauna here means a very hot enclosed space that traps the performer inside.","zh":"private sauna 在這裏指非常炎熱、把表演者困在裏面的封閉空間。"},{"en":"A small room without air-conditioning can feel like a private sauna in summer.","zh":"夏天沒有冷氣的小房間可以感覺像私人桑拿房。"},{"en":"The image helps readers understand the heat inside the costume.","zh":"這個意象幫助讀者理解服裝裏面的熱。"},{"en":"The performer’s cheerful outside hid the private sauna he was suffering inside.","zh":"表演者開朗的外表掩蓋了他在裏面承受的私人桑拿房。"}],"source":"2014 Q6.pdf","sourcePage":11},{"front":"take forever","meaning":"花很久時間","examples":[{"en":"It took forever for my breathing to settle after a dance set.","zh":"一段舞蹈表演後，我的呼吸花很久時間才平復。"},{"en":"Take forever means seem to take a very long time.","zh":"take forever 指感覺花非常長時間。"},{"en":"The lift took forever to arrive during the morning rush.","zh":"早上繁忙時間，升降機花很久才到。"},{"en":"After heavy exercise in heat, recovery can feel as if it takes forever.","zh":"在炎熱中劇烈運動後，恢復可能感覺花很久時間。"},{"en":"The phrase shows how exhausting the dance set felt to the performer.","zh":"這個片語顯示那段舞蹈令表演者多麼疲累。"}],"source":"2014 Q6.pdf","sourcePage":11},{"front":"breathing to settle","meaning":"呼吸平復","examples":[{"en":"It took time for my breathing to settle after a dance set.","zh":"一段舞蹈表演後，我的呼吸花了一段時間才平復。"},{"en":"Breathing to settle means breathing slowly returns to a normal, calm rhythm.","zh":"breathing to settle 指呼吸慢慢回到正常和平靜的節奏。"},{"en":"After running upstairs, it may take a minute for breathing to settle.","zh":"跑上樓梯後，呼吸可能要一分鐘才平復。"},{"en":"Heavy costumes make it harder for breathing to settle after movement.","zh":"厚重服裝令動作後呼吸更難平復。"},{"en":"The writer’s breathing took longer to settle because of heat and exhaustion.","zh":"因為高溫和疲勞，作者的呼吸需要更久才平復。"}],"source":"2014 Q6.pdf","sourcePage":11},{"front":"dance set","meaning":"一段舞蹈表演","examples":[{"en":"My breathing took a long time to settle after a dance set.","zh":"一段舞蹈表演後，我的呼吸花很久才平復。"},{"en":"A dance set is a short planned sequence of dance movements.","zh":"dance set 指一段安排好的短舞蹈動作。"},{"en":"Performers may repeat the same dance set several times a day.","zh":"表演者一天內可能重複同一段舞蹈表演幾次。"},{"en":"A dance set inside a heavy costume can feel much harder than it looks.","zh":"在厚重服裝裏完成一段舞蹈表演，可能比看起來困難得多。"},{"en":"The phrase helps readers understand that the job involved real physical performance.","zh":"這個片語幫助讀者理解這份工作包含真正的體力表演。"}],"source":"2014 Q6.pdf","sourcePage":11},{"front":"physical discomfort","meaning":"身體不適","examples":[{"en":"Physical discomfort was only part of the challenge.","zh":"身體不適只是挑戰的一部分。"},{"en":"Physical discomfort means unpleasant feelings in the body, such as heat, pain, sweat, or tiredness.","zh":"physical discomfort 指身體上的不舒服感，例如炎熱、疼痛、汗水或疲倦。"},{"en":"Long outdoor work can cause physical discomfort in summer.","zh":"夏天長時間戶外工作會造成身體不適。"},{"en":"Physical discomfort becomes harder when workers must still look cheerful.","zh":"當員工仍必須看起來開朗，身體不適會更難承受。"},{"en":"The writer explains that heat was difficult, but visitor behaviour was also a problem.","zh":"作者解釋炎熱很困難，但遊客行為也是問題。"}],"source":"2014 Q6.pdf","sourcePage":11},{"front":"part of the challenge","meaning":"挑戰的一部分","examples":[{"en":"Physical discomfort was only part of the challenge.","zh":"身體不適只是挑戰的一部分。"},{"en":"Part of the challenge means one difficulty among several difficulties.","zh":"part of the challenge 指幾個困難中的其中一個。"},{"en":"For new teachers, marking homework is only part of the challenge.","zh":"對新老師來說，批改功課只是挑戰的一部分。"},{"en":"A job may be hard not because of one problem but because several problems happen together.","zh":"一份工作困難，可能不是因為一個問題，而是幾個問題同時出現。"},{"en":"For the performer, heat was only one part of a larger test.","zh":"對表演者來說，炎熱只是更大考驗的一部分。"}],"source":"2014 Q6.pdf","sourcePage":12},{"front":"the more serious problem","meaning":"更嚴重的問題","examples":[{"en":"The more serious problem was that some visitors forgot there was a person inside.","zh":"更嚴重的問題是，有些遊客忘記服裝裏面有一個人。"},{"en":"The more serious problem means the difficulty that matters more or causes greater harm.","zh":"the more serious problem 指更重要或造成更大傷害的困難。"},{"en":"In a school project, late work is a problem, but unfair teamwork may be the more serious problem.","zh":"在學校專題中，遲交是問題，但不公平分工可能是更嚴重的問題。"},{"en":"Visitor behaviour became more serious because it could hurt the hidden worker.","zh":"遊客行為變得更嚴重，因為它可能傷害隱藏的工作者。"},{"en":"The phrase shifts attention from discomfort to respect.","zh":"這個片語把注意力由不適轉向尊重。"}],"source":"2014 Q6.pdf","sourcePage":12},{"front":"a person inside","meaning":"服裝裏面的人","examples":[{"en":"Some visitors forgot there was a person inside the costume.","zh":"有些遊客忘記服裝裏面有一個人。"},{"en":"A person inside means a real human being hidden within the character suit.","zh":"a person inside 指隱藏在角色服裝裏的真實人類。"},{"en":"Visitors may see only the mascot and forget the worker inside can feel pain.","zh":"遊客可能只看見吉祥物，忘記裏面的工作者會感到痛。"},{"en":"Remembering the person inside helps people treat performers with respect.","zh":"記得服裝裏面的人，能幫助人們尊重表演者。"},{"en":"The article asks readers to look beyond the costume and see the worker.","zh":"這篇文章請讀者看穿服裝，看見工作者。"}],"source":"2014 Q6.pdf","sourcePage":12},{"front":"at one point","meaning":"有一次","examples":[{"en":"At one point, a teenager slapped the character’s head as a joke.","zh":"有一次，一名青少年當作玩笑拍打角色的頭。"},{"en":"At one point means at a particular moment during a longer event or period.","zh":"at one point 指在較長事件或時段中的某一刻。"},{"en":"At one point during the hike, the students had to stop for water.","zh":"有一次在遠足期間，學生必須停下來喝水。"},{"en":"This phrase introduces a specific example from an experience.","zh":"這個片語引出經歷中的具體例子。"},{"en":"The writer uses it before describing a moment when a visitor crossed a line.","zh":"作者用它來描述一個遊客越界的時刻。"}],"source":"2014 Q6.pdf","sourcePage":12},{"front":"slap the character’s head","meaning":"拍打角色的頭","examples":[{"en":"A teenager slapped the character’s head as a joke.","zh":"一名青少年當作玩笑拍打角色的頭。"},{"en":"Slap the character’s head means hit the head of the costume with an open hand.","zh":"slap the character’s head 指用手掌拍打角色服裝的頭部。"},{"en":"Some visitors may think slapping a mascot is funny, but it can hurt the performer inside.","zh":"有些遊客可能覺得拍打吉祥物很好笑，但這會傷害裏面的表演者。"},{"en":"A large headpiece can shake painfully when someone hits it.","zh":"當有人打大型頭套時，頭套可能會痛苦地晃動。"},{"en":"This action shows why performers need handlers and protection.","zh":"這個行動顯示表演者為何需要隨行工作人員和保護。"}],"source":"2014 Q6.pdf","sourcePage":12},{"front":"as a joke","meaning":"當作玩笑","examples":[{"en":"A teenager slapped the character’s head as a joke.","zh":"一名青少年當作玩笑拍打角色的頭。"},{"en":"As a joke means done to be funny, not necessarily to cause harm.","zh":"as a joke 指為了搞笑而做，不一定是想造成傷害。"},{"en":"A student may hide a friend’s pencil as a joke, but it can still be annoying.","zh":"學生可能當作玩笑藏起朋友的鉛筆，但仍可能令人煩惱。"},{"en":"Actions meant as jokes can hurt others if people forget their feelings.","zh":"即使原意是玩笑，如果忘記別人感受，行動仍可能傷害人。"},{"en":"The teenager saw it as a joke, but the performer felt the physical impact.","zh":"青少年把它當作玩笑，但表演者感受到實際撞擊。"}],"source":"2014 Q6.pdf","sourcePage":12},{"front":"pull my tail","meaning":"拉我的尾巴","examples":[{"en":"Another guest pulled my tail to make his friends laugh.","zh":"另一名遊客拉我的尾巴來逗朋友發笑。"},{"en":"Pull my tail means grab and tug the tail attached to the character costume.","zh":"pull my tail 指抓住並拉扯角色服裝上的尾巴。"},{"en":"A costume tail may look like a toy, but it is attached to a performer’s body.","zh":"服裝尾巴可能看起來像玩具，但它連着表演者的身體。"},{"en":"Pulling it can hurt, damage the costume, or make the performer lose balance.","zh":"拉尾巴可能造成疼痛、損壞服裝或令表演者失去平衡。"},{"en":"This example shows how visitors sometimes forget the human inside.","zh":"這個例子顯示遊客有時忘記裏面的人。"}],"source":"2014 Q6.pdf","sourcePage":12},{"front":"make his friends laugh","meaning":"逗朋友發笑","examples":[{"en":"The guest pulled my tail to make his friends laugh.","zh":"那名遊客拉我的尾巴來逗朋友發笑。"},{"en":"Make his friends laugh means do something so his friends find it funny.","zh":"make his friends laugh 指做某事讓朋友覺得好笑。"},{"en":"A teenager may act silly to make friends laugh during a trip.","zh":"青少年可能在旅行中做傻事逗朋友發笑。"},{"en":"Trying to make friends laugh is not an excuse for hurting workers.","zh":"想逗朋友發笑並不是傷害工作者的藉口。"},{"en":"The guest valued the joke more than the performer’s comfort.","zh":"那名遊客重視玩笑多於表演者的舒適。"}],"source":"2014 Q6.pdf","sourcePage":12},{"front":"break character","meaning":"跳出角色","examples":[{"en":"I could not shout, argue, or break character.","zh":"我不能大叫、爭辯或跳出角色。"},{"en":"Break character means stop behaving as the role one is performing.","zh":"break character 指停止保持正在扮演的角色狀態。"},{"en":"An actor breaks character if he laughs during a serious scene.","zh":"如果演員在嚴肅場景中笑出來，就是跳出角色。"},{"en":"A mascot cannot break character easily because children may believe the character is real.","zh":"吉祥物不能輕易跳出角色，因為孩子可能相信角色是真的。"},{"en":"The writer had to stay silent even when visitors behaved badly.","zh":"即使遊客行為惡劣，作者仍必須保持沉默。"}],"source":"2014 Q6.pdf","sourcePage":12},{"front":"step back","meaning":"後退一步","examples":[{"en":"I had to step back and let my handler deal with it.","zh":"我必須後退一步，讓隨行工作人員處理這件事。"},{"en":"Step back means move away slightly or stop taking direct action.","zh":"step back 指稍微離開或停止直接行動。"},{"en":"A teacher may step back and let students solve a small disagreement.","zh":"老師可能後退一步，讓學生解決小分歧。"},{"en":"The performer stepped back because he could not argue while in character.","zh":"表演者後退一步，因為他在角色中不能爭辯。"},{"en":"Stepping back allowed the handler to manage the situation safely.","zh":"後退一步讓隨行工作人員安全處理情況。"}],"source":"2014 Q6.pdf","sourcePage":12},{"front":"deal with it","meaning":"處理這件事","examples":[{"en":"My handler had to deal with the visitor’s behaviour.","zh":"我的隨行工作人員必須處理那名遊客的行為。"},{"en":"Deal with it means handle, manage, or solve a problem.","zh":"deal with it 指處理、管理或解決問題。"},{"en":"Staff deal with rude customers by staying calm and following rules.","zh":"員工會保持冷靜並按規則處理無禮顧客。"},{"en":"The handler dealt with the problem because the performer could not speak directly.","zh":"隨行工作人員處理問題，因為表演者不能直接說話。"},{"en":"This phrase shows how teamwork protects workers in public-facing jobs.","zh":"這個片語顯示團隊合作如何保護面對公眾的工作者。"}],"source":"2014 Q6.pdf","sourcePage":13},{"front":"even when","meaning":"即使","examples":[{"en":"Even when I was tired, dizzy, or upset, I still had to look delighted.","zh":"即使我疲倦、頭暈或難過，我仍然必須看起來很高興。"},{"en":"Even when means despite the fact that a particular situation is true.","zh":"even when 指即使某種情況是真的。"},{"en":"Even when students are nervous, they may still need to give a presentation.","zh":"即使學生緊張，他們仍可能需要做匯報。"},{"en":"This phrase shows that a duty continues despite difficulty.","zh":"這個片語顯示即使有困難，責任仍然持續。"},{"en":"The performer had to show happiness even when he felt physically or emotionally weak.","zh":"表演者即使身體或情緒上虛弱，也必須表現快樂。"}],"source":"2014 Q6.pdf","sourcePage":13},{"front":"dizzy","meaning":"頭暈","examples":[{"en":"Sometimes I felt tired, dizzy, or upset.","zh":"有時我感到疲倦、頭暈或難過。"},{"en":"Dizzy means feeling as if the head is spinning or balance is weak.","zh":"dizzy 指感到頭部像在旋轉，或平衡力變弱。"},{"en":"People may feel dizzy after standing too long in hot weather.","zh":"人在炎熱天氣中站太久後可能會頭暈。"},{"en":"A performer inside a hot costume may feel dizzy after dancing.","zh":"表演者在炎熱服裝裏跳舞後可能會頭暈。"},{"en":"Dizziness is serious because it can make movement unsafe in a crowd.","zh":"頭暈很嚴重，因為在人群中移動可能變得不安全。"}],"source":"2014 Q6.pdf","sourcePage":13},{"front":"look delighted","meaning":"看起來很高興","examples":[{"en":"I still had to look delighted even when I was upset.","zh":"即使我難過，我仍然必須看起來很高興。"},{"en":"Look delighted means appear very happy, pleased, and excited.","zh":"look delighted 指看起來非常快樂、滿意和興奮。"},{"en":"Performers must look delighted when greeting visitors, even after repeating the same action many times.","zh":"表演者問候遊客時，即使同一動作重複很多次，也必須看起來很高興。"},{"en":"Looking delighted can be difficult when the body is tired or uncomfortable.","zh":"當身體疲倦或不舒服時，看起來很高興可能很困難。"},{"en":"The painted smile helped the character look delighted, but the person inside suffered.","zh":"畫上去的笑容幫助角色看起來很高興，但服裝裏的人卻在受苦。"}],"source":"2014 Q6.pdf","sourcePage":13},{"front":"the price of being magical","meaning":"製造魔法感的代價","examples":[{"en":"The price of being magical is often being invisible.","zh":"製造魔法感的代價往往是變得隱形。"},{"en":"The price of being magical means the hidden cost paid to create a wonderful illusion.","zh":"the price of being magical 指創造美好幻想所付出的隱藏代價。"},{"en":"A stage show looks magical, but the price may be hours of unseen practice.","zh":"舞台表演看似有魔法，但代價可能是數小時無人看見的練習。"},{"en":"Theme park performers create magic by hiding their heat, pain, and tiredness.","zh":"主題公園表演者透過隱藏炎熱、疼痛和疲倦來創造魔法。"},{"en":"The phrase shows that public wonder can require private sacrifice.","zh":"這個片語顯示公開驚喜可能需要私人犧牲。"}],"source":"2014 Q6.pdf","sourcePage":13},{"front":"being invisible","meaning":"變得隱形；不被看見","examples":[{"en":"The price of being magical is often being invisible.","zh":"製造魔法感的代價往往是變得隱形。"},{"en":"Being invisible means not being noticed, recognised, or treated as fully present.","zh":"being invisible 指不被注意、不被認可，或不被當成真正在場的人。"},{"en":"Workers behind a show can feel invisible when visitors only praise the performers on stage.","zh":"當遊客只讚賞台上的表演者，幕後工作者可能感到不被看見。"},{"en":"A mascot performer becomes invisible because the character receives all the attention.","zh":"吉祥物表演者變得隱形，因為所有注意力都落在角色身上。"},{"en":"The writer wants readers to see the hidden person inside the suit.","zh":"作者希望讀者看見服裝裏隱藏的人。"}],"source":"2014 Q6.pdf","sourcePage":13},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, I would still recommend this job.","zh":"總括而言，我仍然會推薦這份工作。"},{"en":"All things considered means after thinking about all the good and bad points.","zh":"all things considered 指在思考所有好處和壞處之後。"},{"en":"All things considered, the trip was tiring but worthwhile.","zh":"總括而言，這次旅行很疲累但值得。"},{"en":"This phrase is useful near the end of a balanced reflection.","zh":"這個片語在平衡反思的結尾附近很有用。"},{"en":"The writer uses it after discussing both the job’s meaning and its difficulties.","zh":"作者在討論工作的意義和困難後使用它。"}],"source":"2014 Q6.pdf","sourcePage":13},{"front":"recommend this job to","meaning":"向……推薦這份工作","examples":[{"en":"I would recommend this job to students who want more than easy pocket money.","zh":"我會向想要不只是輕鬆賺零用錢的學生推薦這份工作。"},{"en":"Recommend this job to means suggest that a particular group of people should try the job.","zh":"recommend this job to 指建議某一類人嘗試這份工作。"},{"en":"A teacher may recommend a library job to students who enjoy quiet service.","zh":"老師可能向喜歡安靜服務的學生推薦圖書館工作。"},{"en":"The writer does not recommend the job to everyone, only to students ready for challenge.","zh":"作者不是向所有人推薦這份工作，而是向準備好接受挑戰的學生推薦。"},{"en":"This phrase helps connect personal experience with advice for readers.","zh":"這個片語幫助把個人經歷連接到給讀者的建議。"}],"source":"2014 Q6.pdf","sourcePage":13},{"front":"more than easy pocket money","meaning":"不只是輕鬆賺零用錢","examples":[{"en":"This job is for students who want more than easy pocket money.","zh":"這份工作適合想要不只是輕鬆賺零用錢的學生。"},{"en":"More than easy pocket money means more than a simple, comfortable way to earn small spending money.","zh":"more than easy pocket money 指不只是用簡單舒服的方法賺少量零用錢。"},{"en":"Some summer jobs give pocket money, but difficult jobs may also give confidence and skills.","zh":"有些暑期工給人零用錢，但困難工作也可能給人信心和技能。"},{"en":"Students wanting only easy money may not enjoy a hot and demanding costume job.","zh":"只想輕鬆賺錢的學生可能不會喜歡炎熱而要求高的角色服裝工作。"},{"en":"This job suits students who want learning, challenge, and responsibility.","zh":"這份工作適合想要學習、挑戰和責任的學生。"}],"source":"2014 Q6.pdf","sourcePage":13},{"front":"demanding","meaning":"要求高的；辛苦的","examples":[{"en":"The job is demanding, but valuable.","zh":"這份工作要求高，但很有價值。"},{"en":"Demanding means requiring a lot of effort, skill, time, or patience.","zh":"demanding 指需要很多努力、技巧、時間或耐性的。"},{"en":"Caring for children can be demanding because they need constant attention.","zh":"照顧孩子要求很高，因為他們需要持續注意。"},{"en":"A demanding job may be tiring but still teach useful lessons.","zh":"要求高的工作可能很疲累，但仍能教會有用一課。"},{"en":"The costume job was demanding because it required heat tolerance, teamwork, and emotional control.","zh":"角色服裝工作要求高，因為它需要忍熱、團隊合作和情緒控制。"}],"source":"2014 Q6.pdf","sourcePage":13},{"front":"exactly why","meaning":"正正是為甚麼","examples":[{"en":"It is demanding, but that is exactly why it is valuable.","zh":"它要求高，但這正正是它有價值的原因。"},{"en":"Exactly why means this is the precise reason something is true.","zh":"exactly why 指這正是某事成立的準確原因。"},{"en":"The task is difficult, and that is exactly why students learn so much from it.","zh":"任務很困難，而這正正是學生能從中學到很多的原因。"},{"en":"Challenges can be valuable because they force people to grow.","zh":"挑戰可以有價值，因為它迫使人成長。"},{"en":"The writer argues that the job’s difficulty is the reason it teaches important lessons.","zh":"作者認為這份工作的困難正是它教會重要一課的原因。"}],"source":"2014 Q6.pdf","sourcePage":14},{"front":"take it up","meaning":"接受這份工作","examples":[{"en":"Students who take it up should be punctual and patient.","zh":"接受這份工作的學生應守時和有耐性。"},{"en":"Take it up means accept or start doing a job, activity, or offer.","zh":"take it up 指接受或開始做某份工作、活動或機會。"},{"en":"A student may take up a weekend job to gain experience.","zh":"學生可能接受週末工作來累積經驗。"},{"en":"Before taking up a demanding job, students should understand what it requires.","zh":"接受要求高的工作前，學生應明白它需要甚麼。"},{"en":"Those who take up this performer job must be ready for heat and discipline.","zh":"接受這份表演工作的人必須準備好面對炎熱和紀律。"}],"source":"2014 Q6.pdf","sourcePage":14},{"front":"punctual","meaning":"守時","examples":[{"en":"Students who take this job should be punctual.","zh":"接受這份工作的學生應守時。"},{"en":"Punctual means arriving or doing things at the agreed time.","zh":"punctual 指按約定時間到達或做事。"},{"en":"A punctual worker signs in before the shift begins.","zh":"守時的員工會在更次開始前簽到。"},{"en":"Theme park performances depend on punctual staff because schedules are strict.","zh":"主題公園表演依賴守時員工，因為時間表很嚴格。"},{"en":"Being punctual shows respect for teammates and visitors.","zh":"守時顯示對隊友和遊客的尊重。"}],"source":"2014 Q6.pdf","sourcePage":14},{"front":"prepared to sweat","meaning":"準備好流汗","examples":[{"en":"Students should be prepared to sweat.","zh":"學生應準備好流汗。"},{"en":"Prepared to sweat means ready to do hot, tiring, physical work.","zh":"prepared to sweat 指準備好做炎熱、疲累和耗體力的工作。"},{"en":"Outdoor volunteers should be prepared to sweat during summer events.","zh":"戶外義工在夏季活動中應準備好流汗。"},{"en":"A performer inside a costume must expect discomfort, heat, and effort.","zh":"在服裝裏的表演者必須預期不適、炎熱和努力。"},{"en":"This phrase warns students that the job is not easy or glamorous.","zh":"這個片語提醒學生，這份工作不輕鬆也不風光。"}],"source":"2014 Q6.pdf","sourcePage":14},{"front":"for their part","meaning":"就……而言","examples":[{"en":"Theme parks, for their part, should protect young performers.","zh":"就主題公園而言，它們應保護年輕表演者。"},{"en":"For their part means considering their responsibility or role in the situation.","zh":"for their part 指從某方的責任或角色來看。"},{"en":"Students should work hard; teachers, for their part, should give clear guidance.","zh":"學生應努力；就老師而言，他們應給予清楚指導。"},{"en":"This phrase fairly assigns responsibility to another group.","zh":"這個片語公平地把責任分配給另一方。"},{"en":"The writer says performers must be prepared, but parks must also protect them.","zh":"作者說表演者要準備好，但公園也必須保護他們。"}],"source":"2014 Q6.pdf","sourcePage":14},{"front":"provide enough breaks","meaning":"提供足夠休息","examples":[{"en":"Theme parks should provide enough breaks for young performers.","zh":"主題公園應為年輕表演者提供足夠休息。"},{"en":"Provide enough breaks means give workers sufficient rest periods during work.","zh":"provide enough breaks 指在工作中給員工足夠休息時間。"},{"en":"Outdoor workers need enough breaks to drink water and cool down.","zh":"戶外工作者需要足夠休息來喝水和降溫。"},{"en":"Without enough breaks, performers may become dizzy or unsafe.","zh":"沒有足夠休息，表演者可能會頭暈或變得不安全。"},{"en":"Providing breaks shows that visitor entertainment should not come at the cost of worker health.","zh":"提供休息顯示遊客娛樂不應以工作者健康為代價。"}],"source":"2014 Q6.pdf","sourcePage":14},{"front":"shade","meaning":"遮蔭處","examples":[{"en":"Theme parks should provide enough breaks, shade, and protection.","zh":"主題公園應提供足夠休息、遮蔭處和保護。"},{"en":"Shade is a cooler area protected from direct sunlight.","zh":"shade 指避開陽光直射、較涼的地方。"},{"en":"Workers may rest under shade after performing in the sun.","zh":"工作者在陽光下表演後，可能在遮蔭處休息。"},{"en":"Shade reduces heat stress and helps performers recover safely.","zh":"遮蔭處減少熱壓力，幫助表演者安全恢復。"},{"en":"Theme parks should provide shade because costumes trap heat.","zh":"主題公園應提供遮蔭處，因為服裝會困住熱力。"}],"source":"2014 Q6.pdf","sourcePage":14},{"front":"young performers","meaning":"年輕表演者","examples":[{"en":"Theme parks should protect young performers.","zh":"主題公園應保護年輕表演者。"},{"en":"Young performers are young people who act, dance, entertain, or appear in public performances.","zh":"young performers 指參與演戲、跳舞、娛樂或公開表演的年輕人。"},{"en":"Young performers may be energetic but still need training and protection.","zh":"年輕表演者可能充滿活力，但仍需要訓練和保護。"},{"en":"Employers should protect young performers from heat, unsafe visitors, and unreasonable schedules.","zh":"僱主應保護年輕表演者免受高溫、不安全遊客和不合理時間表影響。"},{"en":"The article argues that young workers deserve respect behind the costume.","zh":"這篇文章主張服裝背後的年輕工作者值得尊重。"}],"source":"2014 Q6.pdf","sourcePage":14},{"front":"no longer look at","meaning":"不再以同一方式看待","examples":[{"en":"I no longer look at mascots in the same way.","zh":"我不再以同一方式看待吉祥物。"},{"en":"No longer look at means stop seeing or understanding something in the old way.","zh":"no longer look at 指不再以舊方式看待或理解某事。"},{"en":"After working in a restaurant, I no longer look at waiters in the same way.","zh":"在餐廳工作後，我不再以同一方式看待侍應。"},{"en":"Experience can change how people view jobs they once thought were simple.","zh":"經驗可以改變人如何看待以前以為簡單的工作。"},{"en":"The writer now sees mascots as real workers, not just cheerful characters.","zh":"作者現在把吉祥物看成真正工作者，而不只是開朗角色。"}],"source":"2014 Q6.pdf","sourcePage":14},{"front":"mascots","meaning":"吉祥物","examples":[{"en":"I no longer look at mascots in the same way.","zh":"我不再以同一方式看待吉祥物。"},{"en":"Mascots are characters, often in costumes, used to represent a park, team, school, or brand.","zh":"mascots 是常以服裝呈現、代表公園、隊伍、學校或品牌的角色。"},{"en":"Children often take photos with mascots at theme parks and sports events.","zh":"孩子常在主題公園和體育活動中與吉祥物拍照。"},{"en":"Mascots look playful, but the performers inside may be hot and tired.","zh":"吉祥物看起來俏皮，但裏面的表演者可能又熱又累。"},{"en":"The article teaches readers to respect the worker behind every mascot.","zh":"這篇文章教讀者尊重每個吉祥物背後的工作者。"}],"source":"2014 Q6.pdf","sourcePage":14},{"front":"behind every perfect photograph stands","meaning":"每張完美照片背後都有……","examples":[{"en":"Behind every perfect photograph stands a real worker.","zh":"每張完美照片背後都有一位真正的工作者。"},{"en":"Behind every perfect photograph stands means every beautiful public image depends on hidden human effort.","zh":"behind every perfect photograph stands 指每張美麗公開影像都依賴隱藏的人力。"},{"en":"Behind every perfect wedding photo stands a team of planners, cleaners, and photographers.","zh":"每張完美婚照背後都有策劃人、清潔人員和攝影師團隊。"},{"en":"This phrase invites readers to look beyond the final image.","zh":"這個片語邀請讀者看穿最後影像。"},{"en":"The perfect theme park photo exists because a worker kept smiling through discomfort.","zh":"完美主題公園照片之所以存在，是因為有工作者忍着不適保持微笑。"}],"source":"2014 Q6.pdf","sourcePage":15},{"front":"a real worker","meaning":"真正的工作者","examples":[{"en":"Behind every perfect photograph stands a real worker.","zh":"每張完美照片背後都有一位真正的工作者。"},{"en":"A real worker means an actual person doing effortful labour, not just a character or image.","zh":"a real worker 指一個真正付出勞動的人，而不只是角色或影像。"},{"en":"A real worker may be sweating inside the costume while visitors smile outside.","zh":"真正的工作者可能在服裝裏流汗，而外面的遊客正在微笑。"},{"en":"Remembering the real worker encourages visitors to act respectfully.","zh":"記得真正的工作者，會鼓勵遊客有禮貌地行事。"},{"en":"The phrase brings humanity back to a job that often hides the person.","zh":"這個片語把人性帶回一份常常隱藏人的工作。"}],"source":"2014 Q6.pdf","sourcePage":15},{"front":"silently waving","meaning":"默默揮手","examples":[{"en":"The performer is silently waving behind the perfect photograph.","zh":"表演者在完美照片背後默默揮手。"},{"en":"Silently waving means greeting or communicating with the hand without speaking.","zh":"silently waving 指不用說話，只用手揮動來問候或溝通。"},{"en":"A mascot silently waves because the character may not be allowed to talk.","zh":"吉祥物默默揮手，因為角色可能不被允許說話。"},{"en":"Silent waving can still express welcome, excitement, and kindness.","zh":"默默揮手仍能表達歡迎、興奮和善意。"},{"en":"The phrase shows how performers communicate while remaining hidden.","zh":"這個片語顯示表演者如何在隱藏自己時溝通。"}],"source":"2014 Q6.pdf","sourcePage":15},{"front":"carefully breathing","meaning":"小心地呼吸","examples":[{"en":"The worker is carefully breathing inside the costume.","zh":"工作者在服裝裏面小心地呼吸。"},{"en":"Carefully breathing means controlling one’s breath slowly and deliberately, often because breathing is difficult.","zh":"carefully breathing 指緩慢而有意識地控制呼吸，通常因為呼吸困難。"},{"en":"A runner carefully breathes after finishing a race.","zh":"跑手完成比賽後會小心地呼吸。"},{"en":"Inside a hot costume, careful breathing helps the performer stay calm and safe.","zh":"在炎熱服裝裏，小心呼吸幫助表演者保持冷靜和安全。"},{"en":"This phrase reveals the physical effort hidden behind a cheerful photograph.","zh":"這個片語揭示開朗照片背後隱藏的體力付出。"}],"source":"2014 Q6.pdf","sourcePage":15},{"front":"one child at a time","meaning":"一次服務一個孩子","examples":[{"en":"The performer tries, one child at a time, to make summer unforgettable.","zh":"表演者努力一次服務一個孩子，令夏天難忘。"},{"en":"One child at a time means helping or focusing on each child individually, one after another.","zh":"one child at a time 指逐一專注幫助或照顧每個孩子。"},{"en":"A teacher builds confidence one student at a time through patient feedback.","zh":"老師透過耐心回饋，一次幫助一名學生建立信心。"},{"en":"A performer cannot change the whole park at once, but can create one small happy moment at a time.","zh":"表演者不能一下子改變整個公園，但可以一次創造一個小小快樂時刻。"},{"en":"This phrase makes the work feel personal and careful.","zh":"這個片語令工作感覺個人化而細心。"}],"source":"2014 Q6.pdf","sourcePage":15},{"front":"make summer unforgettable","meaning":"令夏天難忘","examples":[{"en":"The performer tries to make summer unforgettable.","zh":"表演者努力令夏天難忘。"},{"en":"Make summer unforgettable means create experiences that people will remember warmly after the season ends.","zh":"make summer unforgettable 指創造人在季節結束後仍會溫暖記住的經歷。"},{"en":"A family trip can make summer unforgettable if children feel surprised and happy.","zh":"如果孩子感到驚喜和快樂，家庭旅行可以令夏天難忘。"},{"en":"Theme park workers help make summer unforgettable through small moments of joy.","zh":"主題公園工作者透過小小快樂時刻幫助令夏天難忘。"},{"en":"The writer’s hard work mattered because it became part of children’s holiday memories.","zh":"作者的辛苦工作很重要，因為它成為孩子假期回憶的一部分。"}],"source":"2014 Q6.pdf","sourcePage":15}],"dse/writing/part-b/2014/Q7":[{"front":"more than a punchline","meaning":"不只是笑點","examples":[{"en":"The comedy show was more than a punchline.","zh":"那場喜劇表演不只是笑點。"},{"en":"More than a punchline means having deeper meaning beyond one funny final line.","zh":"“More than a punchline” 指除了有趣的結尾妙語之外，還有更深意義。"},{"en":"The speech was more than a punchline because it made the audience think about friendship.","zh":"那次演講不只是笑點，因為它令觀眾思考友誼。"},{"en":"A joke can be more than a punchline when it reveals a truth about daily life.","zh":"當一個笑話揭示日常生活中的真相時，它就不只是笑點。"},{"en":"This phrase shows that comedy can carry meaning, not only laughter.","zh":"這個說法顯示喜劇可以承載意義，而不只是笑聲。"}],"source":"2014 Q7.pdf","sourcePage":1},{"front":"taught us to listen","meaning":"教會我們聆聽","examples":[{"en":"The night comedy taught us to listen.","zh":"那晚的喜劇教會我們聆聽。"},{"en":"Taught us to listen means helped us learn to pay attention to words, pauses, feelings, and other people’s experiences.","zh":"“Taught us to listen” 指幫助我們學會留意說話、停頓、感受和別人的經歷。"},{"en":"The workshop taught us to listen before giving advice.","zh":"那個工作坊教會我們在給意見前先聆聽。"},{"en":"Comedy can teach us to listen because timing and audience reaction both matter.","zh":"喜劇可以教會我們聆聽，因為節奏和觀眾反應都很重要。"},{"en":"This phrase shows that a performance can train understanding, not only entertain.","zh":"這個說法顯示表演可以訓練理解力，而不只是娛樂。"}],"source":"2014 Q7.pdf","sourcePage":1},{"front":"English Society","meaning":"英文學會","examples":[{"en":"The English Society arranged for students to attend a comedy show.","zh":"英文學會安排學生觀看一場喜劇表演。"},{"en":"An English Society is a school group that organises English-related activities for students.","zh":"英文學會是學校中為學生舉辦英語相關活動的組織。"},{"en":"The English Society invited a speaker to help students practise public speaking.","zh":"英文學會邀請講者幫助學生練習公開演說。"},{"en":"An English Society can make language learning more lively through drama, debate, and performances.","zh":"英文學會可以透過戲劇、辯論和表演令語言學習更生動。"},{"en":"This phrase identifies the school group responsible for the activity.","zh":"這個說法指出負責活動的學校組織。"}],"source":"2014 Q7.pdf","sourcePage":1},{"front":"arrange for someone to","meaning":"安排某人去……","examples":[{"en":"Our English Society arranged for us to attend a local stand-up comedy show.","zh":"我們的英文學會安排我們去觀看本地棟篤笑表演。"},{"en":"To arrange for someone to do something means to organise the details so that person can do it.","zh":"“Arrange for someone to” 指安排好細節，讓某人能做某事。"},{"en":"The teacher arranged for the class to visit a theatre.","zh":"老師安排全班去參觀劇院。"},{"en":"A school may arrange for students to meet performers after a show.","zh":"學校可以安排學生在表演後與演出者見面。"},{"en":"This phrase shows planning done for another person’s benefit.","zh":"這個說法顯示為了別人的利益而作出的安排。"}],"source":"2014 Q7.pdf","sourcePage":1},{"front":"attend a local stand-up comedy show","meaning":"觀看本地棟篤笑表演","examples":[{"en":"Students attended a local stand-up comedy show last Friday.","zh":"學生上星期五觀看了一場本地棟篤笑表演。"},{"en":"To attend a local stand-up comedy show means to go and watch a live comedy performance by a local comedian.","zh":"“Attend a local stand-up comedy show” 指去觀看由本地喜劇演員現場演出的棟篤笑。"},{"en":"Our class attended a local stand-up comedy show to learn how humour works in English.","zh":"我們班觀看本地棟篤笑表演，以學習英語幽默如何運作。"},{"en":"Attending a local stand-up comedy show can help students hear natural rhythm and expression.","zh":"觀看本地棟篤笑表演可以幫助學生聽到自然節奏和表達方式。"},{"en":"This phrase describes a cultural activity outside normal classroom learning.","zh":"這個說法描述課室以外的文化活動。"}],"source":"2014 Q7.pdf","sourcePage":1},{"front":"stand-up comedy show","meaning":"棟篤笑表演","examples":[{"en":"The students attended a local stand-up comedy show.","zh":"學生觀看了一場本地棟篤笑表演。"},{"en":"A stand-up comedy show is a live performance in which a comedian tells jokes and stories directly to an audience.","zh":"棟篤笑表演是喜劇演員直接面向觀眾講笑話和故事的現場表演。"},{"en":"In a stand-up comedy show, one microphone and one performer can fill a room with laughter.","zh":"在棟篤笑表演中，一支麥克風和一位表演者就可以令全場大笑。"},{"en":"A stand-up comedy show depends on timing, language, and audience reaction.","zh":"棟篤笑表演依靠節奏、語言和觀眾反應。"},{"en":"This phrase refers to comedy performed live, usually without many props or actors.","zh":"這個說法指通常不依賴大量道具或演員的現場喜劇。"}],"source":"2014 Q7.pdf","sourcePage":1},{"front":"a pleasant evening of jokes","meaning":"一個充滿笑話的愉快晚上","examples":[{"en":"I expected a pleasant evening of jokes.","zh":"我原本期待一個充滿笑話的愉快晚上。"},{"en":"A pleasant evening of jokes means an enjoyable night filled mainly with funny stories or comments.","zh":"“A pleasant evening of jokes” 指一個主要充滿有趣故事或評論、令人愉快的晚上。"},{"en":"I thought the show would only be a pleasant evening of jokes after a tiring school week.","zh":"經過疲累的一星期上課後，我以為那場表演只會是一個充滿笑話的愉快晚上。"},{"en":"A pleasant evening of jokes can help people relax, but it may also make them think.","zh":"一個充滿笑話的愉快晚上可以幫助人放鬆，也可能令人思考。"},{"en":"This phrase shows the writer’s simple expectation before discovering deeper meaning.","zh":"這個說法顯示作者在發現更深意義前的簡單期望。"}],"source":"2014 Q7.pdf","sourcePage":1},{"front":"did not expect to","meaning":"沒有預期會……","examples":[{"en":"I did not expect to leave the theatre thinking about courage and language.","zh":"我沒有預期離開劇場時會思考勇氣和語言。"},{"en":"Did not expect to means did not think something would happen before it happened.","zh":"“Did not expect to” 指在事情發生前，沒有想到它會發生。"},{"en":"I did not expect to enjoy the lecture, but the speaker was very funny.","zh":"我沒有預期會喜歡那場講座，但講者非常有趣。"},{"en":"A student may not expect to learn about empathy from a comedy show.","zh":"學生可能沒有預期會從喜劇表演中學到同理心。"},{"en":"This phrase shows surprise when the result is different from the original expectation.","zh":"這個說法顯示結果與原本期望不同，令人感到意外。"}],"source":"2014 Q7.pdf","sourcePage":1},{"front":"black-box theatre","meaning":"黑盒劇場","examples":[{"en":"The show took place in a small black-box theatre.","zh":"表演在一個小型黑盒劇場舉行。"},{"en":"A black-box theatre is a simple performance space with dark walls and flexible seating.","zh":"黑盒劇場是有深色牆身和靈活座位安排的簡約表演空間。"},{"en":"A black-box theatre can make the audience feel close to the performer.","zh":"黑盒劇場可以令觀眾感覺很接近表演者。"},{"en":"Comedy works well in a black-box theatre because every pause and expression feels immediate.","zh":"喜劇很適合在黑盒劇場演出，因為每個停頓和表情都感覺即時。"},{"en":"This phrase describes an intimate theatre setting rather than a large formal stage.","zh":"這個說法描述親密的劇場環境，而不是大型正式舞台。"}],"source":"2014 Q7.pdf","sourcePage":1},{"front":"human connection","meaning":"人與人之間的連繫","examples":[{"en":"The show made me think about courage, language and human connection.","zh":"那場表演令我思考勇氣、語言和人與人之間的連繫。"},{"en":"Human connection means the feeling of understanding, care, or closeness between people.","zh":"人與人之間的連繫是人們之間理解、關心或親近的感覺。"},{"en":"A simple joke can create human connection when everyone recognises the same experience.","zh":"當每個人都認出同一種經歷時，一個簡單笑話也能建立人與人之間的連繫。"},{"en":"Live performances build human connection because performers and audiences react to one another.","zh":"現場表演能建立人與人之間的連繫，因為表演者和觀眾會互相回應。"},{"en":"This phrase shows that communication is emotional, not only linguistic.","zh":"這個說法顯示溝通不只是語言上的，也是情感上的。"}],"source":"2014 Q7.pdf","sourcePage":1},{"front":"increasingly buried under","meaning":"越來越被……壓住","examples":[{"en":"Students are increasingly buried under tests and tutorials.","zh":"學生越來越被測驗和補習壓住。"},{"en":"Increasingly buried under means gradually becoming more overwhelmed by too many duties or pressures.","zh":"“Increasingly buried under” 指逐漸被太多責任或壓力壓得喘不過氣。"},{"en":"Many teenagers are increasingly buried under homework, exams, and after-school classes.","zh":"許多青少年越來越被功課、考試和課後課程壓住。"},{"en":"When students are buried under pressure, they may have little time to think or rest.","zh":"當學生被壓力壓住，他們可能很少時間思考或休息。"},{"en":"This phrase makes stress feel like a heavy weight covering someone.","zh":"這個說法令壓力像沉重東西覆蓋在人身上一樣。"}],"source":"2014 Q7.pdf","sourcePage":2},{"front":"tests and tutorials","meaning":"測驗和補習","examples":[{"en":"Students are buried under tests, tutorials and phone screens.","zh":"學生被測驗、補習和手機屏幕壓住。"},{"en":"Tests and tutorials refer to school assessments and extra lessons for practice or exam preparation.","zh":"測驗和補習指學校評估，以及為練習或備試而上的額外課程。"},{"en":"After tests and tutorials, students may feel too tired to join creative activities.","zh":"經過測驗和補習後，學生可能太疲累而不想參加創意活動。"},{"en":"Too many tests and tutorials can make learning feel narrow and stressful.","zh":"太多測驗和補習會令學習變得狹窄而有壓力。"},{"en":"This phrase represents the academic pressure many students face.","zh":"這個說法代表許多學生面對的學業壓力。"}],"source":"2014 Q7.pdf","sourcePage":2},{"front":"glowing phone screens","meaning":"發光的手機屏幕","examples":[{"en":"Many students spend too much time in front of glowing phone screens.","zh":"許多學生花太多時間在發光的手機屏幕前。"},{"en":"Glowing phone screens are bright mobile-phone displays that attract people’s attention.","zh":"發光的手機屏幕是明亮、吸引人注意的手機顯示屏。"},{"en":"At night, glowing phone screens can keep students awake longer than they planned.","zh":"晚上，發光的手機屏幕可能令學生比原定時間更晚入睡。"},{"en":"Spending hours on glowing phone screens may reduce face-to-face conversation.","zh":"長時間看發光的手機屏幕可能減少面對面對話。"},{"en":"This phrase suggests modern distraction and digital tiredness.","zh":"這個說法暗示現代分心和數碼疲勞。"}],"source":"2014 Q7.pdf","sourcePage":2},{"front":"school community","meaning":"學校社群","examples":[{"en":"Our school community should give students more chances to watch live performances.","zh":"我們的學校社群應給學生更多觀看現場表演的機會。"},{"en":"A school community includes students, teachers, parents, staff, and others connected with the school.","zh":"學校社群包括學生、老師、家長、職員和其他與學校有關的人。"},{"en":"A strong school community supports learning inside and outside the classroom.","zh":"強大的學校社群會支持課室內外的學習。"},{"en":"When the school community values the arts, students receive richer learning experiences.","zh":"當學校社群重視藝術，學生便能得到更豐富的學習經驗。"},{"en":"This phrase shows that responsibility is shared by many people, not only teachers.","zh":"這個說法顯示責任由許多人共同承擔，而不只是老師。"}],"source":"2014 Q7.pdf","sourcePage":2},{"front":"consider giving us more chances to","meaning":"考慮給我們更多機會去……","examples":[{"en":"The school community should consider giving us more chances to watch live performances.","zh":"學校社群應考慮給我們更多機會去觀看現場表演。"},{"en":"Consider giving us more chances to means think seriously about offering us more opportunities to do something.","zh":"“Consider giving us more chances to” 指認真考慮提供更多機會讓我們做某事。"},{"en":"The school should consider giving us more chances to speak English outside lessons.","zh":"學校應考慮給我們更多機會在課堂以外說英語。"},{"en":"This phrase sounds polite because it suggests an idea rather than demanding it.","zh":"這個說法語氣有禮，因為它提出建議，而不是命令。"},{"en":"It is useful when making a respectful request in a school context.","zh":"當在學校語境中提出尊重的請求時，這個說法很有用。"}],"source":"2014 Q7.pdf","sourcePage":2},{"front":"live performances","meaning":"現場表演","examples":[{"en":"Students can learn from watching live performances.","zh":"學生可以從觀看現場表演中學習。"},{"en":"Live performances are shows performed in front of an audience in real time.","zh":"現場表演是在觀眾面前即時演出的節目。"},{"en":"Concerts, plays, debates, and comedy shows can all be live performances.","zh":"音樂會、戲劇、辯論和喜劇表演都可以是現場表演。"},{"en":"Live performances help students notice voice, timing, gesture, and audience response.","zh":"現場表演幫助學生留意聲音、節奏、手勢和觀眾反應。"},{"en":"This phrase contrasts real-time stage experience with recorded videos.","zh":"這個說法把即時舞台經驗與錄影片段作對比。"}],"source":"2014 Q7.pdf","sourcePage":2},{"front":"beyond the classroom","meaning":"課室以外","examples":[{"en":"Students can learn confidence and empathy beyond the classroom.","zh":"學生可以在課室以外學習自信和同理心。"},{"en":"Beyond the classroom means outside normal lessons or schoolroom learning.","zh":"“Beyond the classroom” 指在正常課堂或課室學習之外。"},{"en":"Students learn teamwork beyond the classroom through sports and drama.","zh":"學生透過運動和戲劇在課室以外學習團隊合作。"},{"en":"Learning beyond the classroom can feel more real because students experience ideas directly.","zh":"課室以外的學習可以更真實，因為學生直接經歷想法。"},{"en":"This phrase shows that education is wider than textbooks and exams.","zh":"這個說法顯示教育比課本和考試更廣闊。"}],"source":"2014 Q7.pdf","sourcePage":2},{"front":"confidence, empathy and expressive power","meaning":"自信、同理心和表達力","examples":[{"en":"Live performances can teach confidence, empathy and expressive power.","zh":"現場表演可以教學生自信、同理心和表達力。"},{"en":"Confidence, empathy and expressive power mean courage to speak, ability to understand others, and skill in communicating ideas.","zh":"自信、同理心和表達力，指說話的勇氣、理解他人的能力，以及傳達想法的技巧。"},{"en":"Drama activities can build confidence, empathy and expressive power in quiet students.","zh":"戲劇活動可以在害羞學生身上建立自信、同理心和表達力。"},{"en":"These qualities matter because students need both language and emotional understanding.","zh":"這些素質很重要，因為學生既需要語言，也需要情感理解。"},{"en":"This phrase shows that performances train the whole person, not only vocabulary.","zh":"這個說法顯示表演訓練的是整個人，而不只是詞彙。"}],"source":"2014 Q7.pdf","sourcePage":2},{"front":"not just about","meaning":"不只是關於……","examples":[{"en":"Stand-up comedy is not just about making people laugh.","zh":"棟篤笑不只是關於令人發笑。"},{"en":"Not just about means a subject includes more than the most obvious purpose.","zh":"“Not just about” 指一個主題包含的內容多於最明顯的目的。"},{"en":"School is not just about exams; it is also about learning how to think.","zh":"學校不只是關於考試，也關於學習如何思考。"},{"en":"Comedy is not just about jokes because it can reveal social truths.","zh":"喜劇不只是關於笑話，因為它可以揭示社會真相。"},{"en":"This phrase helps move from a simple idea to a deeper explanation.","zh":"這個說法幫助由簡單想法轉向更深解釋。"}],"source":"2014 Q7.pdf","sourcePage":2},{"front":"making people laugh","meaning":"令人發笑","examples":[{"en":"Stand-up comedy is not just about making people laugh.","zh":"棟篤笑不只是關於令人發笑。"},{"en":"Making people laugh means causing people to find something funny and respond with laughter.","zh":"“Making people laugh” 指令別人覺得有趣並以笑聲回應。"},{"en":"A comedian makes people laugh by using timing, surprise, and familiar situations.","zh":"喜劇演員透過節奏、驚喜和熟悉情境令人發笑。"},{"en":"Making people laugh is difficult because humour depends on audience reaction.","zh":"令人發笑並不容易，因為幽默取決於觀眾反應。"},{"en":"This phrase describes the visible result of comedy, but not its whole purpose.","zh":"這個說法描述喜劇可見的結果，但不是它的全部目的。"}],"source":"2014 Q7.pdf","sourcePage":2},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, comedy helps people see ordinary life differently.","zh":"更重要的是，喜劇幫助人以不同方式看平凡生活。"},{"en":"More importantly introduces a point that matters more than the previous one.","zh":"“More importantly” 用來引出比前一點更重要的觀點。"},{"en":"The show was funny; more importantly, it helped us understand one another.","zh":"那場表演很有趣；更重要的是，它幫助我們互相理解。"},{"en":"This phrase helps writers arrange ideas by importance.","zh":"這個說法幫助作者按重要性安排想法。"},{"en":"It tells the reader to pay special attention to the next idea.","zh":"它提醒讀者要特別留意下一個觀點。"}],"source":"2014 Q7.pdf","sourcePage":3},{"front":"ordinary life","meaning":"平凡生活","examples":[{"en":"Comedy can make people see ordinary life in a sharper way.","zh":"喜劇可以令人以更敏銳的方式看平凡生活。"},{"en":"Ordinary life means the normal daily experiences people usually have.","zh":"平凡生活指人們通常擁有的普通日常經驗。"},{"en":"Waiting for the bus, doing homework, and eating dinner are parts of ordinary life.","zh":"等巴士、做功課和吃晚飯都是平凡生活的一部分。"},{"en":"Comedy finds humour in ordinary life by showing familiar problems from a new angle.","zh":"喜劇透過新角度呈現熟悉問題，從平凡生活中找到幽默。"},{"en":"This phrase shows that meaningful material can come from everyday experience.","zh":"這個說法顯示有意義的素材可以來自日常經驗。"}],"source":"2014 Q7.pdf","sourcePage":3},{"front":"in a sharper, warmer and braver way","meaning":"以更敏銳、更溫暖、更勇敢的方式","examples":[{"en":"Stand-up comedy makes people see ordinary life in a sharper, warmer and braver way.","zh":"棟篤笑令人以更敏銳、更溫暖、更勇敢的方式看平凡生活。"},{"en":"In a sharper, warmer and braver way means with clearer observation, more kindness, and more courage.","zh":"“In a sharper, warmer and braver way” 指用更清晰的觀察、更善意的態度和更大的勇氣。"},{"en":"A good story can help us see family pressure in a sharper, warmer and braver way.","zh":"好故事可以幫助我們以更敏銳、更溫暖、更勇敢的方式看家庭壓力。"},{"en":"Comedy becomes powerful when it is sharp enough to notice truth, warm enough to avoid cruelty, and brave enough to speak.","zh":"當喜劇敏銳得能看見真相、溫暖得不殘酷、勇敢得敢於說出來，它就變得有力量。"},{"en":"This phrase shows the emotional and intellectual value of humour.","zh":"這個說法顯示幽默在情感和思考上的價值。"}],"source":"2014 Q7.pdf","sourcePage":3},{"front":"began almost too quietly","meaning":"開始得幾乎過於安靜","examples":[{"en":"The show began almost too quietly.","zh":"表演開始得幾乎過於安靜。"},{"en":"Began almost too quietly means started in a very calm or soft way that seemed surprising for a comedy show.","zh":"“Began almost too quietly” 指開始時非常平靜或輕柔，對喜劇表演來說顯得意外。"},{"en":"The speech began almost too quietly, so the audience leaned forward to listen.","zh":"那場演講開始得幾乎過於安靜，所以觀眾都向前傾身聆聽。"},{"en":"A performance that begins quietly can create attention before building energy.","zh":"安靜開始的表演可以先吸引注意，然後再建立能量。"},{"en":"This phrase suggests an unexpected beginning that later changes.","zh":"這個說法暗示一個意想不到、之後會改變的開端。"}],"source":"2014 Q7.pdf","sourcePage":3},{"front":"a single microphone","meaning":"一支麥克風","examples":[{"en":"A single microphone stood under a cone of yellow light.","zh":"一支麥克風立在一束黃色燈光下。"},{"en":"A single microphone means only one microphone, often highlighting a simple stage setup.","zh":"“A single microphone” 指只有一支麥克風，通常突顯舞台布置簡單。"},{"en":"On the empty stage, a single microphone waited for the speaker.","zh":"空舞台上，一支麥克風等待講者出場。"},{"en":"In stand-up comedy, a single microphone can be enough because the focus is on voice and timing.","zh":"在棟篤笑中，一支麥克風已經足夠，因為重點在聲音和節奏。"},{"en":"This phrase makes the performance space feel bare and intense.","zh":"這個說法令表演空間感覺簡潔而有張力。"}],"source":"2014 Q7.pdf","sourcePage":3},{"front":"a cone of yellow light","meaning":"一束黃色燈光","examples":[{"en":"The microphone stood under a cone of yellow light.","zh":"麥克風立在一束黃色燈光下。"},{"en":"A cone of yellow light is a narrow beam of yellow stage light shaped like a cone.","zh":"一束黃色燈光是形狀像圓錐的狹窄黃色舞台光。"},{"en":"The actor stepped into a cone of yellow light before speaking.","zh":"演員說話前走進一束黃色燈光中。"},{"en":"A cone of light can focus the audience’s attention on one person or object.","zh":"一束燈光可以把觀眾注意力集中在一個人或物件上。"},{"en":"This phrase helps readers imagine the small, dramatic stage.","zh":"這個說法幫助讀者想像細小而具戲劇感的舞台。"}],"source":"2014 Q7.pdf","sourcePage":3},{"front":"rows of folding chairs","meaning":"一排排摺椅","examples":[{"en":"Rows of folding chairs were pressed close to the stage.","zh":"一排排摺椅緊貼着舞台。"},{"en":"Rows of folding chairs are lines of movable chairs that can be folded and stored.","zh":"一排排摺椅是排成一行行、可以摺起收納的椅子。"},{"en":"The school hall had rows of folding chairs for the audience.","zh":"學校禮堂為觀眾擺放了一排排摺椅。"},{"en":"Rows of folding chairs suggest a simple, temporary, and intimate performance space.","zh":"一排排摺椅暗示簡單、臨時而親密的表演空間。"},{"en":"This phrase helps show how close the audience was to the comedian.","zh":"這個說法幫助顯示觀眾與喜劇演員有多接近。"}],"source":"2014 Q7.pdf","sourcePage":3},{"front":"pressed close to","meaning":"緊貼着","examples":[{"en":"The folding chairs were pressed close to the stage.","zh":"摺椅緊貼着舞台。"},{"en":"Pressed close to means placed very near something, with little space between.","zh":"“Pressed close to” 指被放得非常接近某物，中間幾乎沒有空間。"},{"en":"The audience seats were pressed close to the speaker’s platform.","zh":"觀眾座位緊貼着講台。"},{"en":"When chairs are pressed close to the stage, every expression becomes easy to see.","zh":"當椅子緊貼舞台時，每個表情都容易看見。"},{"en":"This phrase creates a feeling of intimacy and closeness.","zh":"這個說法營造親密和接近的感覺。"}],"source":"2014 Q7.pdf","sourcePage":3},{"front":"walk out","meaning":"走出來","examples":[{"en":"The comedian walked out and looked at the audience.","zh":"喜劇演員走出來，看着觀眾。"},{"en":"To walk out means to come onto a stage or into a space by walking.","zh":"“Walk out” 指步行走到舞台上或某個空間中。"},{"en":"The speaker walked out from behind the curtain and smiled at the crowd.","zh":"講者從布幕後走出來，向人群微笑。"},{"en":"A performer’s first walk out can set the mood for the whole show.","zh":"表演者第一次走出來，可以定下整場表演的氣氛。"},{"en":"This phrase describes the moment the audience first sees the performer.","zh":"這個說法描述觀眾第一次看見表演者的時刻。"}],"source":"2014 Q7.pdf","sourcePage":3},{"front":"the audience","meaning":"觀眾","examples":[{"en":"The comedian looked at the audience before speaking.","zh":"喜劇演員說話前看着觀眾。"},{"en":"The audience is the group of people watching or listening to a performance, speech, or event.","zh":"觀眾是觀看或聆聽表演、演講或活動的一群人。"},{"en":"The audience laughed when the comedian copied a familiar school scene.","zh":"當喜劇演員模仿熟悉的校園情景時，觀眾笑了。"},{"en":"A performer must read the audience to know whether a joke is working.","zh":"表演者必須讀懂觀眾反應，才知道笑話是否奏效。"},{"en":"This word is important because live comedy depends on audience reaction.","zh":"這個詞很重要，因為現場喜劇依賴觀眾反應。"}],"source":"2014 Q7.pdf","sourcePage":3},{"front":"mother’s expectations of me","meaning":"媽媽對我的期望","examples":[{"en":"The comedian joked that his mother’s expectations needed more space.","zh":"喜劇演員開玩笑說，媽媽對他的期望需要更多空間。"},{"en":"Mother’s expectations of me means what my mother hopes, demands, or imagines I should achieve.","zh":"“Mother’s expectations of me” 指媽媽希望、要求或想像我應該達到的事情。"},{"en":"My mother’s expectations of me include studying hard and behaving responsibly.","zh":"媽媽對我的期望包括努力讀書和負責任地行事。"},{"en":"Comedy often jokes about parents’ expectations because many students recognise that pressure.","zh":"喜劇常拿父母期望開玩笑，因為許多學生都認得這種壓力。"},{"en":"This phrase connects humour with family pressure.","zh":"這個說法把幽默與家庭壓力連接起來。"}],"source":"2014 Q7.pdf","sourcePage":4},{"front":"needed more space","meaning":"需要更多空間","examples":[{"en":"Even his mother’s expectations needed more space.","zh":"連他媽媽對他的期望也需要更多空間。"},{"en":"Needed more space means required more room, either physically or emotionally.","zh":"“Needed more space” 指需要更多位置，可以是實際空間，也可以是情感空間。"},{"en":"My desk needed more space after I covered it with books and notes.","zh":"我的書桌放滿書和筆記後，需要更多空間。"},{"en":"Saying expectations need more space is funny because an emotional pressure is described like a physical object.","zh":"說期望需要更多空間很有趣，因為情感壓力被描述成實物。"},{"en":"This phrase can show that someone feels crowded by demands.","zh":"這個說法可以顯示某人被要求壓得太滿。"}],"source":"2014 Q7.pdf","sourcePage":4},{"front":"the room exploded","meaning":"全場爆笑","examples":[{"en":"The room exploded with laughter.","zh":"全場爆笑。"},{"en":"The room exploded means everyone in the room suddenly reacted loudly and strongly.","zh":"“The room exploded” 指房間裏所有人突然有強烈而響亮的反應。"},{"en":"When the punchline arrived, the room exploded with applause.","zh":"笑點出現時，全場爆發掌聲。"},{"en":"A room can “explode” in this sense when the audience’s reaction is sudden and powerful.","zh":"當觀眾反應突然又強烈時，可以說整個房間 “exploded”。"},{"en":"This phrase makes laughter sound energetic and immediate.","zh":"這個說法令笑聲聽起來充滿能量而即時。"}],"source":"2014 Q7.pdf","sourcePage":4},{"front":"from that moment on","meaning":"從那一刻起","examples":[{"en":"From that moment on, the comedian controlled the room.","zh":"從那一刻起，喜劇演員掌控了全場。"},{"en":"From that moment on means starting at that time and continuing afterwards.","zh":"“From that moment on” 指由那個時間開始並在之後持續。"},{"en":"From that moment on, the class listened more carefully to the speaker.","zh":"從那一刻起，全班更仔細聆聽講者。"},{"en":"One successful joke can change the mood of a room from that moment on.","zh":"一個成功笑話可以從那一刻起改變整個房間的氣氛。"},{"en":"This phrase shows the point where a situation clearly changes.","zh":"這個說法顯示情況明顯轉變的起點。"}],"source":"2014 Q7.pdf","sourcePage":4},{"front":"everyday Hong Kong frustrations","meaning":"香港日常生活中的煩惱","examples":[{"en":"The comedian turned everyday Hong Kong frustrations into stories.","zh":"喜劇演員把香港日常生活中的煩惱變成故事。"},{"en":"Everyday Hong Kong frustrations are common daily annoyances experienced by people living in Hong Kong.","zh":"香港日常生活中的煩惱，是住在香港的人常遇到的普通日常不滿。"},{"en":"Crowded MTR trains and long queues can be everyday Hong Kong frustrations.","zh":"擠迫港鐵和長長人龍都可以是香港日常生活中的煩惱。"},{"en":"Comedy works when it turns everyday frustrations into something people can laugh at together.","zh":"當喜劇把日常煩惱變成大家可以一起笑的東西時，它就能奏效。"},{"en":"This phrase connects humour with local shared experience.","zh":"這個說法把幽默與本地共同經驗連接起來。"}],"source":"2014 Q7.pdf","sourcePage":4},{"front":"turn something into","meaning":"把某事變成","examples":[{"en":"He turned everyday frustrations into sparkling stories.","zh":"他把日常煩惱變成精彩生動的故事。"},{"en":"To turn something into something else means to change it into a different form or result.","zh":"“Turn something into” 指把某事物改變成另一種形式或結果。"},{"en":"The teacher turned a grammar mistake into a useful lesson.","zh":"老師把一個文法錯誤變成有用的一課。"},{"en":"A comedian can turn an embarrassing moment into a joke.","zh":"喜劇演員可以把尷尬時刻變成笑話。"},{"en":"This phrase shows transformation from one state to another.","zh":"這個說法顯示由一種狀態轉變成另一種狀態。"}],"source":"2014 Q7.pdf","sourcePage":4},{"front":"sparkling stories","meaning":"精彩生動的故事","examples":[{"en":"The comedian turned ordinary frustrations into sparkling stories.","zh":"喜劇演員把普通煩惱變成精彩生動的故事。"},{"en":"Sparkling stories are lively, bright, and entertaining stories that catch people’s attention.","zh":"精彩生動的故事是活潑、有趣並能吸引人注意的故事。"},{"en":"The speaker turned a boring bus ride into a sparkling story full of details.","zh":"講者把一程沉悶巴士旅程變成充滿細節的精彩故事。"},{"en":"A story feels sparkling when its language, rhythm, and surprises keep listeners awake.","zh":"當故事的語言、節奏和驚喜令聽眾保持專注，它就會顯得精彩生動。"},{"en":"This phrase suggests that ordinary life can become vivid through good storytelling.","zh":"這個說法暗示普通生活可以透過好敘事變得鮮明。"}],"source":"2014 Q7.pdf","sourcePage":4},{"front":"treats the pole like private property","meaning":"把扶手柱當成私人財產","examples":[{"en":"The comedian joked about an MTR passenger who treats the pole like private property.","zh":"喜劇演員拿一位把港鐵扶手柱當成私人財產的乘客開玩笑。"},{"en":"Treats the pole like private property means behaves as if the shared handrail belongs only to them.","zh":"“Treats the pole like private property” 指某人表現得好像共享扶手柱只屬於自己。"},{"en":"A passenger treats the pole like private property when he leans on it and blocks others from holding it.","zh":"當乘客靠着扶手柱，阻止其他人握住它時，就是把扶手柱當成私人財產。"},{"en":"The joke is funny because everyone knows public transport spaces are meant to be shared.","zh":"這個笑話有趣，因為大家都知道公共交通空間應該共享。"},{"en":"This phrase criticises selfish behaviour in a familiar public setting.","zh":"這個說法批評熟悉公共場景中的自私行為。"}],"source":"2014 Q7.pdf","sourcePage":4},{"front":"private property","meaning":"私人財產","examples":[{"en":"The MTR passenger treats the pole like private property.","zh":"那位港鐵乘客把扶手柱當成私人財產。"},{"en":"Private property is something owned by a particular person or group, not for everyone to use freely.","zh":"私人財產是屬於某個人或團體的東西，不是讓所有人自由使用。"},{"en":"A home is private property, but a bus handrail is not.","zh":"住宅是私人財產，但巴士扶手不是。"},{"en":"Treating public things like private property can annoy other users.","zh":"把公共物件當成私人財產，可能會令其他使用者不滿。"},{"en":"This phrase helps contrast personal ownership with shared public space.","zh":"這個說法有助對比個人擁有和共享公共空間。"}],"source":"2014 Q7.pdf","sourcePage":4},{"front":"where the other four marks went","meaning":"餘下四分去了哪裏","examples":[{"en":"The parent asks where the other four marks went when a child scores 96.","zh":"當孩子考到九十六分時，家長問餘下四分去了哪裏。"},{"en":"Where the other four marks went is a humorous way to ask why a nearly perfect score was not 100.","zh":"“Where the other four marks went” 是幽默地問為何接近滿分卻不是一百分。"},{"en":"When I got 96, my father joked, “Where did the other four marks go?”","zh":"我考到九十六分時，爸爸開玩笑說：「餘下四分去了哪裏？」"},{"en":"This phrase reflects pressure for perfection in a funny but familiar way.","zh":"這個說法以有趣但熟悉的方式反映追求完美的壓力。"},{"en":"The joke works because many students recognise this kind of parental reaction.","zh":"這個笑話奏效，因為許多學生都認得這種家長反應。"}],"source":"2014 Q7.pdf","sourcePage":4},{"front":"open a textbook like a hero","meaning":"像英雄般打開課本","examples":[{"en":"The student opens a textbook like a hero.","zh":"那名學生像英雄般打開課本。"},{"en":"Open a textbook like a hero means begin studying with dramatic confidence and determination.","zh":"“Open a textbook like a hero” 指帶着戲劇性的信心和決心開始讀書。"},{"en":"Before the exam, he opened his textbook like a hero ready for battle.","zh":"考試前，他像準備上戰場的英雄般打開課本。"},{"en":"The humour comes from treating an ordinary study moment like an epic scene.","zh":"幽默來自把普通溫習時刻當成史詩場面。"},{"en":"This phrase makes a common student habit sound exaggerated and funny.","zh":"這個說法把常見學生習慣誇張化，令它變得好笑。"}],"source":"2014 Q7.pdf","sourcePage":5},{"front":"close it like a defeated tourist","meaning":"像落敗的旅客般合上它","examples":[{"en":"The student closes the textbook five minutes later like a defeated tourist.","zh":"五分鐘後，那名學生像落敗的旅客般合上課本。"},{"en":"Close it like a defeated tourist means shut the textbook with disappointment, confusion, or exhaustion.","zh":"“Close it like a defeated tourist” 指帶着失望、困惑或疲憊合上課本。"},{"en":"After seeing the long chapter, I closed the book like a defeated tourist lost in a new city.","zh":"看見那一長章後，我像在陌生城市迷路的落敗旅客般合上書。"},{"en":"The comparison is funny because studying is described like failing at travel.","zh":"這個比喻有趣，因為它把溫習描述成旅行失敗。"},{"en":"This phrase captures how quickly confidence can disappear during revision.","zh":"這個說法捕捉溫習時信心多快消失。"}],"source":"2014 Q7.pdf","sourcePage":5},{"front":"what impressed me most","meaning":"最令我印象深刻的是","examples":[{"en":"What impressed me most was the precision behind the humour.","zh":"最令我印象深刻的是幽默背後的精準。"},{"en":"What impressed me most introduces the thing that affected or surprised the speaker most strongly.","zh":"“What impressed me most” 用來引出最強烈影響或最令說話者驚訝的事情。"},{"en":"What impressed me most about the debate was the students’ calm response to difficult questions.","zh":"那場辯論最令我印象深刻的是學生冷靜回應難題。"},{"en":"This phrase helps focus the reader on the writer’s strongest observation.","zh":"這個說法幫助讀者集中於作者最強烈的觀察。"},{"en":"It is useful when moving from general experience to personal reflection.","zh":"當由一般經歷轉向個人反思時，這個說法很有用。"}],"source":"2014 Q7.pdf","sourcePage":5},{"front":"the precision behind the humour","meaning":"幽默背後的精準","examples":[{"en":"The precision behind the humour impressed me most.","zh":"幽默背後的精準最令我印象深刻。"},{"en":"The precision behind the humour means the careful timing, wording, and control that make jokes work.","zh":"幽默背後的精準，指令笑話奏效的仔細節奏、用字和控制。"},{"en":"The comedian’s pause before the final word showed the precision behind the humour.","zh":"喜劇演員在最後一個字前的停頓，顯示幽默背後的精準。"},{"en":"Good comedy may look casual, but the precision behind the humour often takes long practice.","zh":"好喜劇看似隨意，但幽默背後的精準常需要長時間練習。"},{"en":"This phrase shows that laughter can be the result of careful craft.","zh":"這個說法顯示笑聲可以是精心技藝的成果。"}],"source":"2014 Q7.pdf","sourcePage":5},{"front":"every pause had a purpose","meaning":"每個停頓都有目的","examples":[{"en":"Every pause in the performance had a purpose.","zh":"表演中的每個停頓都有目的。"},{"en":"Every pause had a purpose means each silence was planned to create timing, suspense, or meaning.","zh":"“Every pause had a purpose” 指每段沉默都經過安排，用來製造節奏、懸念或意義。"},{"en":"In a good speech, every pause has a purpose because it gives listeners time to think.","zh":"在好的演講中，每個停頓都有目的，因為它給聽眾時間思考。"},{"en":"A comedian may pause before a punchline to make the audience expect something.","zh":"喜劇演員可能在笑點前停頓，令觀眾有所期待。"},{"en":"This phrase shows that silence can be part of communication.","zh":"這個說法顯示沉默也可以是溝通的一部分。"}],"source":"2014 Q7.pdf","sourcePage":5},{"front":"raised eyebrow","meaning":"揚起的眉毛","examples":[{"en":"Every raised eyebrow worked like punctuation.","zh":"每次揚起的眉毛都像標點符號一樣發揮作用。"},{"en":"A raised eyebrow is an eyebrow lifted upward to show surprise, doubt, irony, or emphasis.","zh":"揚起的眉毛是向上抬起的眉毛，用來表示驚訝、懷疑、諷刺或強調。"},{"en":"The teacher’s raised eyebrow told us she did not believe the excuse.","zh":"老師揚起的眉毛告訴我們，她不相信那個藉口。"},{"en":"A comedian can use a raised eyebrow to make a joke sharper without adding words.","zh":"喜劇演員可以用揚起的眉毛令笑話更尖銳，而不用加字。"},{"en":"This phrase shows how facial expressions can carry meaning.","zh":"這個說法顯示臉部表情也能承載意思。"}],"source":"2014 Q7.pdf","sourcePage":5},{"front":"worked like punctuation","meaning":"像標點符號一樣發揮作用","examples":[{"en":"Every raised eyebrow worked like punctuation.","zh":"每次揚起的眉毛都像標點符號一樣發揮作用。"},{"en":"Worked like punctuation means helped shape meaning and rhythm, like commas, full stops, or question marks in writing.","zh":"“Worked like punctuation” 指像文字中的逗號、句號或問號一樣，幫助塑造意思和節奏。"},{"en":"Her silence worked like punctuation, ending the argument more clearly than words.","zh":"她的沉默像標點符號一樣發揮作用，比說話更清楚地結束爭論。"},{"en":"In performance, a gesture can work like punctuation by marking a pause or emphasis.","zh":"在表演中，一個手勢可以像標點符號一樣標示停頓或強調。"},{"en":"This phrase compares body language with written language.","zh":"這個說法把身體語言與書面語言作比較。"}],"source":"2014 Q7.pdf","sourcePage":5},{"front":"felt spontaneous","meaning":"感覺自然即興","examples":[{"en":"The show felt spontaneous.","zh":"那場表演感覺自然即興。"},{"en":"Felt spontaneous means seemed natural, unplanned, and created in the moment.","zh":"“Felt spontaneous” 指看起來自然、沒有預先安排，像即場創作。"},{"en":"The speaker’s answer felt spontaneous because she did not read from notes.","zh":"那位講者的回答感覺很自然即興，因為她沒有讀筆記。"},{"en":"A performance can feel spontaneous even when it has been carefully rehearsed.","zh":"即使表演經過仔細排練，也可以感覺自然即興。"},{"en":"This phrase describes the audience’s impression, not necessarily the actual preparation.","zh":"這個說法描述觀眾的印象，不一定是實際準備情況。"}],"source":"2014 Q7.pdf","sourcePage":5},{"front":"yet it had clearly been","meaning":"但它明顯已經被……","examples":[{"en":"The show felt spontaneous, yet it had clearly been carefully polished.","zh":"那場表演感覺自然即興，但它明顯已經被仔細打磨。"},{"en":"Yet it had clearly been introduces a contrast between how something seemed and what was obviously true.","zh":"“Yet it had clearly been” 用來對比某事看起來的樣子和明顯真實的情況。"},{"en":"The speech sounded casual, yet it had clearly been practised many times.","zh":"那場演講聽起來很隨意，但它明顯已經練習過很多次。"},{"en":"This phrase shows that natural-looking work may still involve serious preparation.","zh":"這個說法顯示看起來自然的作品仍可能包含認真準備。"},{"en":"It helps explain the hidden effort behind an effortless result.","zh":"它幫助解釋看似輕鬆成果背後的隱藏努力。"}],"source":"2014 Q7.pdf","sourcePage":5},{"front":"built, tested and polished","meaning":"經過建立、測試和打磨","examples":[{"en":"The performance had been built, tested and polished line by line.","zh":"那場表演逐句經過建立、測試和打磨。"},{"en":"Built, tested and polished means created, tried out, improved, and refined carefully.","zh":"“Built, tested and polished” 指仔細創作、試驗、改善和修飾。"},{"en":"The student’s speech was built, tested and polished through several rehearsals.","zh":"那名學生的演講經過幾次排練後被建立、測試和打磨。"},{"en":"A joke may be built, tested and polished before it sounds natural on stage.","zh":"一個笑話在舞台上聽起來自然之前，可能已經經過建立、測試和打磨。"},{"en":"This phrase shows that creative work often develops through repeated improvement.","zh":"這個說法顯示創意作品常透過反覆改善而形成。"}],"source":"2014 Q7.pdf","sourcePage":5},{"front":"line by line","meaning":"逐句","examples":[{"en":"The show had been polished line by line.","zh":"那場表演已經逐句打磨。"},{"en":"Line by line means one sentence or small part at a time.","zh":"“Line by line” 指每次處理一句或一小部分。"},{"en":"The teacher checked the essay line by line to find unclear ideas.","zh":"老師逐句檢查文章，以找出不清楚的想法。"},{"en":"A comedian may polish a routine line by line so every word helps the joke.","zh":"喜劇演員可能逐句打磨段子，確保每個字都有助笑話。"},{"en":"This phrase suggests careful attention to detail.","zh":"這個說法暗示對細節的仔細關注。"}],"source":"2014 Q7.pdf","sourcePage":6},{"front":"effortless laughter","meaning":"看似輕鬆的笑聲","examples":[{"en":"Such effortless laughter hides enormous difficulty.","zh":"這種看似輕鬆的笑聲隱藏巨大的難度。"},{"en":"Effortless laughter means laughter that feels easy and natural to the audience.","zh":"“Effortless laughter” 指對觀眾來說感覺輕鬆自然的笑聲。"},{"en":"The comedian created effortless laughter, but every joke had been carefully prepared.","zh":"喜劇演員製造了看似輕鬆的笑聲，但每個笑話都經過仔細準備。"},{"en":"Effortless laughter often depends on difficult timing, editing, and delivery.","zh":"看似輕鬆的笑聲常取決於困難的節奏、修改和演繹。"},{"en":"This phrase shows that something easy to enjoy may be hard to create.","zh":"這個說法顯示容易享受的東西可能很難創造。"}],"source":"2014 Q7.pdf","sourcePage":6},{"front":"hides enormous difficulty","meaning":"隱藏巨大的難度","examples":[{"en":"Effortless laughter hides enormous difficulty.","zh":"看似輕鬆的笑聲隱藏巨大的難度。"},{"en":"Hides enormous difficulty means makes something very hard look easy from the outside.","zh":"“Hides enormous difficulty” 指把非常困難的事從外表上呈現得很容易。"},{"en":"A smooth dance performance hides enormous difficulty behind every step.","zh":"一場流暢的舞蹈表演在每一步背後都隱藏巨大難度。"},{"en":"Good public speaking hides enormous difficulty because the speaker must control voice, timing, and nerves.","zh":"好的公開演說隱藏巨大難度，因為講者要控制聲音、節奏和緊張。"},{"en":"This phrase reminds us not to underestimate skilled performance.","zh":"這個說法提醒我們不要低估熟練表演。"}],"source":"2014 Q7.pdf","sourcePage":6},{"front":"for one thing","meaning":"首先；其中一點是","examples":[{"en":"For one thing, stand-up performers face pressure over originality and timing.","zh":"首先，棟篤笑表演者要面對原創性和時機掌握的壓力。"},{"en":"For one thing introduces one reason or point among several.","zh":"“For one thing” 用來引出幾個理由或重點中的其中一個。"},{"en":"For one thing, live performances help students hear natural pronunciation.","zh":"首先，現場表演幫助學生聽到自然發音。"},{"en":"This phrase is useful when beginning the first supporting point in an argument.","zh":"這個說法適合在論證中開始第一個支持點。"},{"en":"It tells the reader that more reasons may follow.","zh":"它告訴讀者之後可能還有其他理由。"}],"source":"2014 Q7.pdf","sourcePage":6},{"front":"stand-up performers","meaning":"棟篤笑表演者","examples":[{"en":"Stand-up performers need originality and timing.","zh":"棟篤笑表演者需要原創性和時機掌握。"},{"en":"Stand-up performers are comedians who perform jokes and stories directly in front of an audience.","zh":"棟篤笑表演者是直接在觀眾面前講笑話和故事的喜劇演員。"},{"en":"Stand-up performers often work alone with only a microphone.","zh":"棟篤笑表演者常獨自拿着一支麥克風演出。"},{"en":"Stand-up performers must react quickly if the audience does not laugh.","zh":"如果觀眾沒有笑，棟篤笑表演者必須快速反應。"},{"en":"This phrase refers to artists whose work depends heavily on live language and presence.","zh":"這個說法指高度依靠現場語言和存在感的藝術工作者。"}],"source":"2014 Q7.pdf","sourcePage":6},{"front":"face the pressure of","meaning":"面對……的壓力","examples":[{"en":"Stand-up performers face the pressure of originality and timing.","zh":"棟篤笑表演者要面對原創性和時機掌握的壓力。"},{"en":"To face the pressure of something means to deal with stress or demands connected with it.","zh":"“Face the pressure of” 指處理與某事相關的壓力或要求。"},{"en":"Students face the pressure of exams near the end of term.","zh":"學期末時，學生要面對考試的壓力。"},{"en":"Performers face the pressure of making an audience respond immediately.","zh":"表演者要面對令觀眾即時回應的壓力。"},{"en":"This phrase shows a challenge that someone must handle directly.","zh":"這個說法顯示某人必須直接處理的挑戰。"}],"source":"2014 Q7.pdf","sourcePage":6},{"front":"originality and timing","meaning":"原創性和時機掌握","examples":[{"en":"Comedy depends on originality and timing.","zh":"喜劇依靠原創性和時機掌握。"},{"en":"Originality and timing mean fresh ideas and the ability to deliver them at the right moment.","zh":"原創性和時機掌握指新鮮想法，以及在正確時刻表達它們的能力。"},{"en":"A joke without originality feels copied, while a joke without timing may fail.","zh":"沒有原創性的笑話像抄襲，沒有時機掌握的笑話可能失敗。"},{"en":"Stand-up comedy needs originality and timing because audiences react instantly.","zh":"棟篤笑需要原創性和時機掌握，因為觀眾會即時反應。"},{"en":"This phrase names two key skills behind successful humour.","zh":"這個說法指出成功幽默背後兩項關鍵技能。"}],"source":"2014 Q7.pdf","sourcePage":6},{"front":"it is one thing to","meaning":"做……是一回事","examples":[{"en":"It is one thing to complain about homework.","zh":"抱怨功課是一回事。"},{"en":"It is one thing to means one action may be easy or ordinary compared with another harder action.","zh":"“It is one thing to” 指某個行動相比另一個較難行動，可能較容易或普通。"},{"en":"It is one thing to notice a problem; it is harder to suggest a solution.","zh":"注意到問題是一回事；提出解決方案則更困難。"},{"en":"This phrase prepares a contrast between two levels of difficulty.","zh":"這個說法為兩個不同難度層次作對比。"},{"en":"It often appears before “it is another to.”","zh":"它常出現在 “it is another to” 之前。"}],"source":"2014 Q7.pdf","sourcePage":6},{"front":"it is another to","meaning":"做到……又是另一回事","examples":[{"en":"It is another to find a fresh angle.","zh":"找到新鮮角度又是另一回事。"},{"en":"It is another to means the second action is different, usually harder or more impressive.","zh":"“It is another to” 指第二個行動不同，通常更困難或更令人佩服。"},{"en":"It is one thing to talk about kindness; it is another to practise it under pressure.","zh":"談論善良是一回事；在壓力下實踐善良又是另一回事。"},{"en":"In comedy, it is another to turn a common complaint into a fresh joke.","zh":"在喜劇中，把普通抱怨變成新鮮笑話又是另一回事。"},{"en":"This phrase completes a contrast between an easier task and a more difficult one.","zh":"這個說法完成較容易任務與較困難任務之間的對比。"}],"source":"2014 Q7.pdf","sourcePage":6},{"front":"find an angle","meaning":"找到角度","examples":[{"en":"A comedian needs to find an angle that feels fresh.","zh":"喜劇演員需要找到一個感覺新鮮的角度。"},{"en":"To find an angle means to discover a particular way of looking at or presenting a topic.","zh":"“Find an angle” 指找出一種看待或呈現主題的特定方式。"},{"en":"A student writing about friendship must find an angle beyond simply saying friends are important.","zh":"學生寫友誼時，必須找到一個角度，而不只是說朋友很重要。"},{"en":"Comedians find an angle by noticing what is strange in familiar situations.","zh":"喜劇演員透過留意熟悉情境中的奇怪之處來找到角度。"},{"en":"This phrase is useful for writing, speaking, and creative thinking.","zh":"這個說法適用於寫作、演說和創意思考。"}],"source":"2014 Q7.pdf","sourcePage":6},{"front":"feels fresh","meaning":"感覺新鮮","examples":[{"en":"A good joke needs an angle that feels fresh.","zh":"好笑話需要一個感覺新鮮的角度。"},{"en":"Feels fresh means seems new, original, lively, or not overused.","zh":"“Feels fresh” 指看起來新穎、原創、有活力或沒有被過度使用。"},{"en":"The topic was common, but her example felt fresh and personal.","zh":"那個題目很常見，但她的例子感覺新鮮而個人化。"},{"en":"A joke feels fresh when it surprises people with a new way of seeing something familiar.","zh":"當笑話以新方式看待熟悉事物而令人驚喜時，它就感覺新鮮。"},{"en":"This phrase describes the audience’s sense of originality.","zh":"這個說法描述觀眾對原創性的感覺。"}],"source":"2014 Q7.pdf","sourcePage":7},{"front":"remove anything unnecessary","meaning":"刪去不必要的東西","examples":[{"en":"A comedian must remove anything unnecessary from a joke.","zh":"喜劇演員必須從笑話中刪去不必要的東西。"},{"en":"To remove anything unnecessary means to cut words, details, or actions that do not help the main effect.","zh":"“Remove anything unnecessary” 指刪去對主要效果沒有幫助的字詞、細節或動作。"},{"en":"A writer should remove anything unnecessary so the paragraph becomes clearer.","zh":"作者應刪去不必要的東西，讓段落更清楚。"},{"en":"In comedy, unnecessary details can weaken timing and delay the punchline.","zh":"在喜劇中，不必要的細節會削弱節奏並延遲笑點。"},{"en":"This phrase shows that good communication often depends on editing.","zh":"這個說法顯示良好溝通常取決於修改。"}],"source":"2014 Q7.pdf","sourcePage":7},{"front":"deliver it","meaning":"說出它；演繹它","examples":[{"en":"The performer must deliver the joke before the moment grows cold.","zh":"表演者必須在時機冷卻前說出那個笑話。"},{"en":"To deliver it means to say or perform it clearly and effectively to an audience.","zh":"“Deliver it” 指清楚而有效地向觀眾說出或演繹某內容。"},{"en":"The speaker had a good line, but she needed confidence to deliver it well.","zh":"那位講者有一句好句子，但她需要信心把它演繹好。"},{"en":"In comedy, how you deliver a joke can matter as much as the words themselves.","zh":"在喜劇中，如何演繹一個笑話可以和字句本身一樣重要。"},{"en":"This phrase focuses on performance, not just writing.","zh":"這個說法集中於表演，而不只是寫作。"}],"source":"2014 Q7.pdf","sourcePage":7},{"front":"before the moment grows cold","meaning":"在時機冷卻之前","examples":[{"en":"A comedian must deliver the joke before the moment grows cold.","zh":"喜劇演員必須在時機冷卻之前說出笑話。"},{"en":"Before the moment grows cold means before the right timing or audience energy disappears.","zh":"“Before the moment grows cold” 指在合適時機或觀眾氣氛消失之前。"},{"en":"The student had to answer before the discussion grew cold and everyone moved on.","zh":"那名學生必須在討論冷卻、大家轉話題前回答。"},{"en":"A joke may fail if the comedian waits until the moment grows cold.","zh":"如果喜劇演員等到時機冷卻才說笑話，笑話可能失敗。"},{"en":"This phrase shows that timing can affect whether communication succeeds.","zh":"這個說法顯示時機會影響溝通是否成功。"}],"source":"2014 Q7.pdf","sourcePage":7},{"front":"dramatic lighting","meaning":"戲劇化燈光","examples":[{"en":"There is no dramatic lighting to rescue a weak joke.","zh":"沒有戲劇化燈光可以挽救一個薄弱笑話。"},{"en":"Dramatic lighting is strong or carefully designed stage lighting that creates mood or excitement.","zh":"戲劇化燈光是強烈或經精心設計、用來營造氣氛或刺激感的舞台燈光。"},{"en":"The play used dramatic lighting to make the final scene feel tense.","zh":"那齣戲用戲劇化燈光令最後一幕感覺緊張。"},{"en":"In stand-up comedy, dramatic lighting cannot replace a well-written joke.","zh":"在棟篤笑中，戲劇化燈光不能取代寫得好的笑話。"},{"en":"This phrase contrasts theatrical effects with the real strength of language.","zh":"這個說法把劇場效果與語言本身的力量作對比。"}],"source":"2014 Q7.pdf","sourcePage":7},{"front":"rescue a weak joke","meaning":"挽救一個薄弱的笑話","examples":[{"en":"No costume change can rescue a weak joke.","zh":"沒有服裝轉換可以挽救一個薄弱的笑話。"},{"en":"To rescue a weak joke means to save a joke that is not funny enough or not well written.","zh":"“Rescue a weak joke” 指挽救一個不夠好笑或寫得不夠好的笑話。"},{"en":"Loud music cannot rescue a weak joke if the idea itself is unclear.","zh":"如果笑話本身想法不清楚，大聲音樂也不能挽救它。"},{"en":"A weak joke may be improved by better timing, but sometimes it needs rewriting.","zh":"薄弱笑話可能可透過更好節奏改善，但有時需要重寫。"},{"en":"This phrase shows that surface effects cannot always fix poor content.","zh":"這個說法顯示表面效果不一定能修補差劣內容。"}],"source":"2014 Q7.pdf","sourcePage":7},{"front":"the audience falls silent","meaning":"觀眾變得沉默","examples":[{"en":"If the audience falls silent, the silence is immediate and public.","zh":"如果觀眾變得沉默，那份沉默是即時而公開的。"},{"en":"The audience falls silent means the people watching suddenly stop laughing, talking, or reacting.","zh":"“The audience falls silent” 指觀看的人突然停止笑、說話或反應。"},{"en":"The audience fell silent when the joke became too personal.","zh":"當那個笑話變得太私人時，觀眾變得沉默。"},{"en":"A silent audience can show that a joke has failed or made people uncomfortable.","zh":"沉默的觀眾可以顯示笑話失敗，或令人感到不舒服。"},{"en":"This phrase shows the pressure of performing live.","zh":"這個說法顯示現場表演的壓力。"}],"source":"2014 Q7.pdf","sourcePage":7},{"front":"immediate and public","meaning":"即時而公開","examples":[{"en":"The silence after a weak joke is immediate and public.","zh":"薄弱笑話之後的沉默是即時而公開的。"},{"en":"Immediate and public means happening at once and in front of everyone.","zh":"“Immediate and public” 指事情立刻發生，而且在所有人面前發生。"},{"en":"In a live debate, a mistake can receive an immediate and public reaction.","zh":"在現場辯論中，一個錯誤可能立即得到公開反應。"},{"en":"Stand-up comedy is risky because failure is immediate and public.","zh":"棟篤笑有風險，因為失敗是即時而公開的。"},{"en":"This phrase shows why performers need courage.","zh":"這個說法顯示為何表演者需要勇氣。"}],"source":"2014 Q7.pdf","sourcePage":7},{"front":"at one point","meaning":"在某一刻","examples":[{"en":"At one point, a joke about online lessons did not quite land.","zh":"在某一刻，一個關於網上課堂的笑話未能完全奏效。"},{"en":"At one point means at one particular moment during a longer event or story.","zh":"“At one point” 指在較長事件或故事中的某個特定時刻。"},{"en":"At one point, the audience became very quiet.","zh":"在某一刻，觀眾變得非常安靜。"},{"en":"This phrase helps describe one moment without stopping the whole narrative.","zh":"這個說法幫助描述某一個時刻，而不打斷整個敘事。"},{"en":"It is useful when referring to a specific part of an experience.","zh":"當提及一段經歷中的特定部分時，它很有用。"}],"source":"2014 Q7.pdf","sourcePage":7},{"front":"online lessons","meaning":"網上課堂","examples":[{"en":"The comedian made a joke about online lessons.","zh":"喜劇演員講了一個關於網上課堂的笑話。"},{"en":"Online lessons are classes taught through the internet rather than in a physical classroom.","zh":"網上課堂是透過互聯網而不是實體課室進行的課堂。"},{"en":"During online lessons, students may use cameras, microphones, and learning platforms.","zh":"在網上課堂中，學生可能會使用鏡頭、麥克風和學習平台。"},{"en":"Online lessons can be convenient, but they may also create distractions and awkward moments.","zh":"網上課堂可以方便，但也可能帶來分心和尷尬時刻。"},{"en":"This phrase gives a familiar school topic for comedy.","zh":"這個說法為喜劇提供熟悉的校園題材。"}],"source":"2014 Q7.pdf","sourcePage":7},{"front":"did not quite land","meaning":"未能完全奏效","examples":[{"en":"A joke about online lessons did not quite land.","zh":"一個關於網上課堂的笑話未能完全奏效。"},{"en":"Did not quite land means a joke or point did not fully succeed or get the expected reaction.","zh":"“Did not quite land” 指笑話或觀點沒有完全成功，也沒有得到預期反應。"},{"en":"Her first joke did not quite land because the audience did not understand the reference.","zh":"她的第一個笑話未能完全奏效，因為觀眾不明白那個典故。"},{"en":"When a joke does not land, the performer must decide quickly how to continue.","zh":"當笑話未能奏效時，表演者必須快速決定如何繼續。"},{"en":"This phrase is common when describing humour that almost worked but not completely.","zh":"這個說法常用來描述差點成功但不完全成功的幽默。"}],"source":"2014 Q7.pdf","sourcePage":8},{"front":"instead of panicking","meaning":"沒有驚慌失措，而是……","examples":[{"en":"Instead of panicking, the comedian used the quiet reaction creatively.","zh":"喜劇演員沒有驚慌失措，而是有創意地運用安靜反應。"},{"en":"Instead of panicking means rather than becoming frightened, confused, or unable to act.","zh":"“Instead of panicking” 指沒有變得害怕、混亂或無法行動。"},{"en":"Instead of panicking during the presentation, she took a breath and continued.","zh":"簡報時，她沒有驚慌失措，而是深呼吸後繼續。"},{"en":"A performer can recover from silence by staying calm instead of panicking.","zh":"表演者可以透過保持冷靜，而不是驚慌失措，從沉默中恢復過來。"},{"en":"This phrase contrasts a fearful reaction with a better response.","zh":"這個說法把恐懼反應與更好的回應作對比。"}],"source":"2014 Q7.pdf","sourcePage":8},{"front":"win us back","meaning":"重新贏回我們的注意","examples":[{"en":"In seconds, the comedian won us back.","zh":"幾秒之內，喜劇演員重新贏回我們的注意。"},{"en":"To win us back means to regain our attention, interest, or support after losing it.","zh":"“Win us back” 指在失去我們的注意、興趣或支持後重新取回它。"},{"en":"The speaker lost the audience for a moment, but a personal story won us back.","zh":"講者一度失去觀眾注意，但一個個人故事重新贏回我們。"},{"en":"A comedian wins the audience back by reacting honestly and confidently.","zh":"喜劇演員可以透過真誠和自信地回應，重新贏回觀眾。"},{"en":"This phrase shows recovery after a performance risk.","zh":"這個說法顯示表演風險後的恢復能力。"}],"source":"2014 Q7.pdf","sourcePage":8},{"front":"for another","meaning":"另一方面","examples":[{"en":"For another, comedians must know where to draw the line.","zh":"另一方面，喜劇演員必須知道界線在哪裏。"},{"en":"For another introduces a second reason or point after an earlier one.","zh":"“For another” 用來在前一個理由或重點後引出第二個。"},{"en":"For one thing, the activity builds confidence; for another, it teaches teamwork.","zh":"首先，這活動建立自信；另一方面，它教授團隊合作。"},{"en":"This phrase helps organise multiple arguments clearly.","zh":"這個說法幫助清楚組織多個論點。"},{"en":"It signals that the writer is adding another important consideration.","zh":"它表示作者正在加入另一項重要考慮。"}],"source":"2014 Q7.pdf","sourcePage":8},{"front":"draw the line","meaning":"知道界線在哪裏","examples":[{"en":"Comedians must know where to draw the line.","zh":"喜劇演員必須知道界線在哪裏。"},{"en":"To draw the line means to decide the limit between what is acceptable and what goes too far.","zh":"“Draw the line” 指決定甚麼是可接受的界線，甚麼是過火。"},{"en":"Teachers must draw the line between friendly joking and hurtful teasing.","zh":"老師必須在友善玩笑和傷人的取笑之間劃清界線。"},{"en":"Comedy can discuss sensitive topics, but performers must know where to draw the line.","zh":"喜劇可以討論敏感題材，但表演者必須知道界線在哪裏。"},{"en":"This phrase is about judgement, limits, and responsibility.","zh":"這個說法關乎判斷、限制和責任。"}],"source":"2014 Q7.pdf","sourcePage":8},{"front":"touch on","meaning":"觸及","examples":[{"en":"Comedy often touches on family pressure and inequality.","zh":"喜劇常觸及家庭壓力和不平等。"},{"en":"To touch on a topic means to mention or discuss it briefly or gently.","zh":"“Touch on” 指簡短或輕輕地提及或討論某個題目。"},{"en":"The talk touched on exam stress but focused mainly on sleep habits.","zh":"那場講座觸及考試壓力，但主要集中於睡眠習慣。"},{"en":"Comedy can touch on serious issues without becoming a lecture.","zh":"喜劇可以觸及嚴肅議題，而不變成說教。"},{"en":"This phrase shows that a topic is included, even if it is not discussed in full detail.","zh":"這個說法顯示某題目被包括在內，即使沒有詳細討論。"}],"source":"2014 Q7.pdf","sourcePage":8},{"front":"family pressure","meaning":"家庭壓力","examples":[{"en":"Comedy often touches on family pressure.","zh":"喜劇常觸及家庭壓力。"},{"en":"Family pressure is stress caused by relatives’ expectations, demands, or comparisons.","zh":"家庭壓力是由親人的期望、要求或比較造成的壓力。"},{"en":"A student may feel family pressure when parents expect perfect marks.","zh":"當父母期望完美分數時，學生可能感到家庭壓力。"},{"en":"Comedy about family pressure can comfort students because they realise others feel the same.","zh":"關於家庭壓力的喜劇可以安慰學生，因為他們意識到其他人也有同樣感受。"},{"en":"This phrase connects humour with a common emotional experience.","zh":"這個說法把幽默與常見情感經驗連接起來。"}],"source":"2014 Q7.pdf","sourcePage":8},{"front":"inequality","meaning":"不平等","examples":[{"en":"Comedy may touch on inequality.","zh":"喜劇可能觸及不平等。"},{"en":"Inequality means unfair difference in opportunities, treatment, wealth, power, or respect.","zh":"不平等指在機會、待遇、財富、權力或尊重方面的不公平差異。"},{"en":"Housing inequality can affect how much space students have to study at home.","zh":"住屋不平等可以影響學生在家中有多少空間溫習。"},{"en":"Comedy can discuss inequality by making unfair situations visible through humour.","zh":"喜劇可以透過幽默令不公平情況變得可見，從而討論不平等。"},{"en":"This word points to serious social differences behind everyday jokes.","zh":"這個詞指出日常笑話背後的嚴肅社會差異。"}],"source":"2014 Q7.pdf","sourcePage":8},{"front":"appearance","meaning":"外貌","examples":[{"en":"Comedy can touch on appearance and language ability.","zh":"喜劇可以觸及外貌和語言能力。"},{"en":"Appearance means the way someone or something looks.","zh":"外貌指某人或某物看起來的樣子。"},{"en":"People may feel pressure about appearance because others judge clothes, body shape, or style.","zh":"人們可能因外貌而感到壓力，因為別人會評價衣着、體形或風格。"},{"en":"Jokes about appearance can easily hurt people if they target someone personally.","zh":"關於外貌的笑話如果針對個人，很容易傷害別人。"},{"en":"This word is sensitive because it connects with confidence and self-image.","zh":"這個詞較敏感，因為它與自信和自我形象有關。"}],"source":"2014 Q7.pdf","sourcePage":8},{"front":"language ability","meaning":"語言能力","examples":[{"en":"Comedy often touches on language ability.","zh":"喜劇常觸及語言能力。"},{"en":"Language ability is the skill to understand, speak, read, or write a language.","zh":"語言能力是理解、說、讀或寫一種語言的技能。"},{"en":"Students may feel nervous about language ability during English speaking exams.","zh":"學生在英文口試中可能會因語言能力而緊張。"},{"en":"Comedy about language ability should be careful not to shame people for mistakes.","zh":"關於語言能力的喜劇應小心，不應因錯誤羞辱別人。"},{"en":"This phrase links humour with communication, confidence, and learning.","zh":"這個說法把幽默與溝通、自信和學習連接起來。"}],"source":"2014 Q7.pdf","sourcePage":8},{"front":"harmless entertainment","meaning":"無傷大雅的娛樂","examples":[{"en":"What is harmless entertainment to one person may hurt another.","zh":"對一個人來說無傷大雅的娛樂，可能會傷害另一個人。"},{"en":"Harmless entertainment means fun that seems not to cause pain, danger, or damage.","zh":"無傷大雅的娛樂指看似不會造成痛苦、危險或傷害的樂趣。"},{"en":"A joke may feel like harmless entertainment to the speaker but embarrassing to the listener.","zh":"一個笑話對說話者來說可能是無傷大雅的娛樂，但對聽者來說可能令人尷尬。"},{"en":"Comedy needs judgement because harmless entertainment for one group may be hurtful to another.","zh":"喜劇需要判斷，因為對一個群體無傷大雅的娛樂，可能對另一個群體造成傷害。"},{"en":"This phrase shows that humour depends on perspective.","zh":"這個說法顯示幽默取決於角度。"}],"source":"2014 Q7.pdf","sourcePage":9},{"front":"hurtful to another","meaning":"對另一個人造成傷害","examples":[{"en":"A joke may be hurtful to another person.","zh":"一個笑話可能對另一個人造成傷害。"},{"en":"Hurtful to another means causing emotional pain, embarrassment, or offence to someone else.","zh":"“Hurtful to another” 指對別人造成情感痛苦、尷尬或冒犯。"},{"en":"A joke about a classmate’s accent may be hurtful to another person.","zh":"關於同學口音的笑話，可能對另一個人造成傷害。"},{"en":"Words can be hurtful to another even when the speaker claims they were only joking.","zh":"即使說話者聲稱只是開玩笑，言語仍可能傷害別人。"},{"en":"This phrase reminds performers to consider the listener’s feelings.","zh":"這個說法提醒表演者考慮聽者感受。"}],"source":"2014 Q7.pdf","sourcePage":9},{"front":"laughed at exam culture","meaning":"取笑考試文化","examples":[{"en":"The performer laughed at exam culture without humiliating students.","zh":"表演者取笑考試文化，但沒有羞辱學生。"},{"en":"Laughed at exam culture means made jokes about the habits and pressures around exams.","zh":"“Laughed at exam culture” 指拿圍繞考試的習慣和壓力開玩笑。"},{"en":"The comedian laughed at exam culture by describing students who start revision too late.","zh":"喜劇演員透過描述太遲開始溫習的學生來取笑考試文化。"},{"en":"Good humour can laugh at exam culture while still respecting students’ stress.","zh":"好幽默可以取笑考試文化，同時仍尊重學生壓力。"},{"en":"This phrase shows how comedy can criticise a system, not attack individuals.","zh":"這個說法顯示喜劇可以批評制度，而不是攻擊個人。"}],"source":"2014 Q7.pdf","sourcePage":9},{"front":"exam culture","meaning":"考試文化","examples":[{"en":"The comedian joked about exam culture.","zh":"喜劇演員拿考試文化開玩笑。"},{"en":"Exam culture means the habits, values, and pressures created by a strong focus on examinations.","zh":"考試文化指由高度重視考試而形成的習慣、價值觀和壓力。"},{"en":"In exam culture, students may feel that marks decide their whole future.","zh":"在考試文化中，學生可能覺得分數決定整個未來。"},{"en":"Comedy about exam culture can help students laugh at pressure they usually hide.","zh":"關於考試文化的喜劇可以幫助學生笑看平時隱藏的壓力。"},{"en":"This phrase describes a school environment shaped heavily by tests and results.","zh":"這個說法描述一種深受測驗和成績影響的校園環境。"}],"source":"2014 Q7.pdf","sourcePage":9},{"front":"without humiliating","meaning":"沒有羞辱","examples":[{"en":"He laughed at exam culture without humiliating students.","zh":"他取笑考試文化，卻沒有羞辱學生。"},{"en":"Without humiliating means without making someone feel ashamed, small, or publicly embarrassed.","zh":"“Without humiliating” 指沒有令某人感到羞愧、渺小或公開難堪。"},{"en":"A teacher can correct mistakes without humiliating the student.","zh":"老師可以糾正錯誤，而不羞辱學生。"},{"en":"A comedian can criticise behaviour without humiliating the people involved.","zh":"喜劇演員可以批評行為，而不羞辱相關的人。"},{"en":"This phrase shows respect and emotional care in communication.","zh":"這個說法顯示溝通中的尊重和情感照顧。"}],"source":"2014 Q7.pdf","sourcePage":9},{"front":"teased parents","meaning":"打趣地取笑父母","examples":[{"en":"The comedian teased parents without making them villains.","zh":"喜劇演員打趣地取笑父母，但沒有把他們塑造成壞人。"},{"en":"Teased parents means joked about parents in a light and playful way.","zh":"“Teased parents” 指以輕鬆玩笑方式談論父母。"},{"en":"The speaker teased parents for asking too many questions before school trips.","zh":"講者打趣地取笑父母在學校旅行前問太多問題。"},{"en":"Teasing parents can be funny if it also shows understanding of their worries.","zh":"如果同時理解父母的擔心，打趣地取笑父母可以很有趣。"},{"en":"This phrase suggests gentle humour rather than cruel criticism.","zh":"這個說法暗示溫和幽默，而不是殘酷批評。"}],"source":"2014 Q7.pdf","sourcePage":9},{"front":"making them villains","meaning":"把他們塑造成壞人","examples":[{"en":"The comedian teased parents without making them villains.","zh":"喜劇演員打趣地取笑父母，但沒有把他們塑造成壞人。"},{"en":"Making them villains means presenting them as bad, cruel, or completely wrong people.","zh":"“Making them villains” 指把他們呈現成壞、殘酷或完全錯誤的人。"},{"en":"A story can discuss strict parents without making them villains.","zh":"故事可以討論嚴格父母，而不把他們塑造成壞人。"},{"en":"Good comedy can show people’s flaws without turning them into enemies.","zh":"好喜劇可以呈現人的缺點，而不把人變成敵人。"},{"en":"This phrase explains how humour can remain fair and humane.","zh":"這個說法解釋幽默如何保持公平和有人情味。"}],"source":"2014 Q7.pdf","sourcePage":9},{"front":"for all its glamour","meaning":"儘管看起來風光","examples":[{"en":"For all its glamour, stand-up is emotionally demanding work.","zh":"儘管看起來風光，棟篤笑是情緒上要求很高的工作。"},{"en":"For all its glamour means although it may look attractive, exciting, or impressive.","zh":"“For all its glamour” 指雖然它可能看起來吸引、刺激或令人羨慕。"},{"en":"For all its glamour, acting involves long hours and repeated rejection.","zh":"儘管表演看起來風光，演戲仍涉及長工時和反覆被拒。"},{"en":"This phrase contrasts the attractive outside with the difficult reality behind it.","zh":"這個說法把吸引人的外表與背後困難現實作對比。"},{"en":"It helps readers see that performance work is not as easy as it looks.","zh":"它幫助讀者看見表演工作並不像外表那麼容易。"}],"source":"2014 Q7.pdf","sourcePage":9},{"front":"emotionally demanding work","meaning":"情緒上要求很高的工作","examples":[{"en":"Stand-up is emotionally demanding work.","zh":"棟篤笑是情緒上要求很高的工作。"},{"en":"Emotionally demanding work is work that requires strong emotional control, courage, and resilience.","zh":"情緒上要求很高的工作，是需要強大情緒控制、勇氣和抗壓力的工作。"},{"en":"Teaching can be emotionally demanding work because teachers handle students’ worries and conflicts.","zh":"教學可以是情緒上要求很高的工作，因為老師要處理學生的憂慮和衝突。"},{"en":"Stand-up is emotionally demanding because performers face public silence, judgement, and pressure.","zh":"棟篤笑在情緒上要求很高，因為表演者要面對公開沉默、評價和壓力。"},{"en":"This phrase shows that comedy requires emotional strength, not only humour.","zh":"這個說法顯示喜劇需要情緒力量，而不只是幽默感。"}],"source":"2014 Q7.pdf","sourcePage":9},{"front":"requires not only…but also…","meaning":"不但需要……而且需要……","examples":[{"en":"Stand-up requires not only a sharp tongue, but also a generous heart.","zh":"棟篤笑不但需要口才尖銳，而且需要寬厚的心。"},{"en":"Requires not only…but also… means needs both the first quality and the second quality.","zh":"“Requires not only…but also…” 指同時需要第一項和第二項特質。"},{"en":"Good leadership requires not only confidence, but also patience.","zh":"好領導不但需要自信，而且需要耐性。"},{"en":"Comedy requires not only clever language, but also care for the audience.","zh":"喜劇不但需要聰明語言，而且需要照顧觀眾感受。"},{"en":"This structure shows that one quality alone is not enough.","zh":"這個結構顯示單一特質並不足夠。"}],"source":"2014 Q7.pdf","sourcePage":9},{"front":"a sharp tongue","meaning":"口才尖銳","examples":[{"en":"Stand-up comedy requires a sharp tongue.","zh":"棟篤笑需要尖銳的口才。"},{"en":"A sharp tongue means quick, clever, and sometimes cutting speech.","zh":"“A sharp tongue” 指快速、聰明，有時帶刺的說話能力。"},{"en":"A debater with a sharp tongue can answer difficult questions quickly.","zh":"口才尖銳的辯論員能快速回應難題。"},{"en":"A sharp tongue can be funny, but it may hurt people if used carelessly.","zh":"尖銳口才可以有趣，但如果使用不小心，也可能傷人。"},{"en":"This phrase shows the power and risk of strong verbal skill.","zh":"這個說法顯示強大語言能力的力量和風險。"}],"source":"2014 Q7.pdf","sourcePage":10},{"front":"a generous heart","meaning":"寬厚的心","examples":[{"en":"Good comedy also requires a generous heart.","zh":"好喜劇也需要一顆寬厚的心。"},{"en":"A generous heart means a kind and understanding attitude towards other people.","zh":"寬厚的心指對別人有善意和理解的態度。"},{"en":"A teacher with a generous heart corrects mistakes without making students feel small.","zh":"有寬厚之心的老師會糾正錯誤，而不令學生感到渺小。"},{"en":"Comedy needs a generous heart because jokes should not simply attack the weak.","zh":"喜劇需要寬厚的心，因為笑話不應只是攻擊弱者。"},{"en":"This phrase balances cleverness with compassion.","zh":"這個說法把聰明與同情心平衡起來。"}],"source":"2014 Q7.pdf","sourcePage":10},{"front":"benefit greatly from","meaning":"從……中大大受益","examples":[{"en":"Students can benefit greatly from watching live comedy.","zh":"學生可以從觀看現場喜劇中大大受益。"},{"en":"To benefit greatly from something means to gain a lot of help, learning, or value from it.","zh":"“Benefit greatly from” 指從某事中得到很多幫助、學習或價值。"},{"en":"Students benefit greatly from reading aloud because they practise pronunciation and confidence.","zh":"學生可以從朗讀中大大受益，因為他們練習發音和自信。"},{"en":"Watching live comedy can benefit students by improving listening and expression.","zh":"觀看現場喜劇可以透過改善聆聽和表達，使學生受益。"},{"en":"This phrase shows that an activity has strong positive effects.","zh":"這個說法顯示一項活動有強烈正面效果。"}],"source":"2014 Q7.pdf","sourcePage":10},{"front":"train our ear for language","meaning":"訓練我們對語言的敏感度","examples":[{"en":"Stand-up comedy trains our ear for language.","zh":"棟篤笑訓練我們對語言的敏感度。"},{"en":"To train our ear for language means to improve our ability to notice sound, rhythm, tone, and word choice.","zh":"“Train our ear for language” 指提升我們留意聲音、節奏、語氣和用字的能力。"},{"en":"Listening to poetry can train our ear for language.","zh":"聆聽詩歌可以訓練我們對語言的敏感度。"},{"en":"Comedy trains our ear because one word or pause can change the whole joke.","zh":"喜劇訓練我們的語言敏感度，因為一個字或停頓可以改變整個笑話。"},{"en":"This phrase shows that listening is an active language skill.","zh":"這個說法顯示聆聽是一種主動的語言技能。"}],"source":"2014 Q7.pdf","sourcePage":10},{"front":"a single word","meaning":"一個字詞","examples":[{"en":"A single word can change a sentence.","zh":"一個字詞可以改變一句句子。"},{"en":"A single word means one word only, often emphasising how small details matter.","zh":"“A single word” 指只有一個字，常用來強調小細節很重要。"},{"en":"In a joke, a single word at the end can create surprise.","zh":"在笑話中，結尾的一個字詞可以製造驚喜。"},{"en":"A single word can change tone from polite to rude or from serious to funny.","zh":"一個字詞可以把語氣由有禮變成無禮，或由嚴肅變成有趣。"},{"en":"This phrase reminds learners that every word choice can matter.","zh":"這個說法提醒學習者，每個用字選擇都可能重要。"}],"source":"2014 Q7.pdf","sourcePage":10},{"front":"create suspense","meaning":"製造懸念","examples":[{"en":"A pause can create suspense.","zh":"一個停頓可以製造懸念。"},{"en":"To create suspense means to make people wait with interest, curiosity, or nervousness.","zh":"“Create suspense” 指令人帶着興趣、好奇或緊張等待。"},{"en":"The speaker paused before announcing the result to create suspense.","zh":"講者在宣布結果前停頓，以製造懸念。"},{"en":"In comedy, suspense makes the punchline stronger because the audience is waiting.","zh":"在喜劇中，懸念會令笑點更有力，因為觀眾正在等待。"},{"en":"This phrase shows how timing can control attention.","zh":"這個說法顯示節奏如何控制注意力。"}],"source":"2014 Q7.pdf","sourcePage":10},{"front":"make an idea memorable","meaning":"令一個想法令人難忘","examples":[{"en":"A comparison can make an idea memorable.","zh":"一個比喻可以令一個想法令人難忘。"},{"en":"To make an idea memorable means to help people remember it clearly after hearing or reading it.","zh":"“Make an idea memorable” 指幫助人聽到或讀到後清楚記住某個想法。"},{"en":"A funny example can make a grammar rule memorable.","zh":"有趣例子可以令一條文法規則令人難忘。"},{"en":"Good speakers make ideas memorable by using stories, images, and contrast.","zh":"好講者透過故事、意象和對比令想法令人難忘。"},{"en":"This phrase shows that expression affects memory.","zh":"這個說法顯示表達方式會影響記憶。"}],"source":"2014 Q7.pdf","sourcePage":10},{"front":"English speaking exams","meaning":"英文口試","examples":[{"en":"Timing and audience awareness are useful for English speaking exams.","zh":"節奏和觀眾意識對英文口試很有用。"},{"en":"English speaking exams are assessments in which students show their ability to speak English.","zh":"英文口試是評估學生英語說話能力的考核。"},{"en":"In English speaking exams, students may need to answer questions, discuss topics, or give short speeches.","zh":"在英文口試中，學生可能需要回答問題、討論題目或作短講。"},{"en":"Good timing helps students sound natural and confident in English speaking exams.","zh":"良好節奏能幫助學生在英文口試中聽起來自然而有信心。"},{"en":"This phrase connects performance skills with school assessment.","zh":"這個說法把表演技巧與學校評核連接起來。"}],"source":"2014 Q7.pdf","sourcePage":10},{"front":"debate competitions","meaning":"辯論比賽","examples":[{"en":"Comedy skills are useful for debate competitions.","zh":"喜劇技巧對辯論比賽很有用。"},{"en":"Debate competitions are contests in which speakers argue for or against a topic using reasons and evidence.","zh":"辯論比賽是講者用理由和證據支持或反對某個題目的比賽。"},{"en":"In debate competitions, timing and audience awareness help speakers sound persuasive.","zh":"在辯論比賽中，節奏和觀眾意識能令講者更具說服力。"},{"en":"A small amount of humour can make an argument more engaging in a debate competition.","zh":"在辯論比賽中，少量幽默可以令論點更吸引。"},{"en":"This phrase shows another school activity that benefits from performance skills.","zh":"這個說法顯示另一項能受惠於表演技巧的校園活動。"}],"source":"2014 Q7.pdf","sourcePage":10},{"front":"class presentations","meaning":"課堂匯報","examples":[{"en":"Students can use timing in class presentations.","zh":"學生可以在課堂匯報中運用節奏。"},{"en":"Class presentations are short talks students give in front of classmates and teachers.","zh":"課堂匯報是學生在同學和老師面前作出的短講。"},{"en":"In class presentations, students explain ideas using voice, slides, examples, and body language.","zh":"在課堂匯報中，學生用聲音、投影片、例子和身體語言解釋想法。"},{"en":"Timing helps class presentations because students know when to pause and when to emphasise key points.","zh":"節奏能幫助課堂匯報，因為學生知道何時停頓和何時強調重點。"},{"en":"This phrase gives a familiar academic use for comedy skills.","zh":"這個說法提供喜劇技巧在學業上的熟悉用途。"}],"source":"2014 Q7.pdf","sourcePage":10},{"front":"speak with timing","meaning":"說話有節奏和時機","examples":[{"en":"A student who speaks with timing will sound more confident.","zh":"說話有節奏和時機的學生會聽起來更有信心。"},{"en":"To speak with timing means to control pauses, speed, and emphasis well while speaking.","zh":"“Speak with timing” 指說話時妥善控制停頓、速度和強調。"},{"en":"She spoke with timing by pausing before each important point.","zh":"她在每個重要觀點前停頓，因此說話很有節奏。"},{"en":"Students who speak with timing are easier to follow because their ideas have rhythm.","zh":"說話有節奏和時機的學生較容易讓人跟上，因為想法有節奏。"},{"en":"This phrase shows that good speaking is not only about correct words.","zh":"這個說法顯示好的說話不只是用字正確。"}],"source":"2014 Q7.pdf","sourcePage":11},{"front":"audience awareness","meaning":"觀眾意識","examples":[{"en":"Audience awareness helps a speaker sound more confident.","zh":"觀眾意識幫助講者聽起來更有信心。"},{"en":"Audience awareness is the ability to notice listeners’ reactions and adjust your speaking accordingly.","zh":"觀眾意識是留意聽眾反應並相應調整說話的能力。"},{"en":"A presenter with audience awareness slows down when classmates look confused.","zh":"有觀眾意識的匯報者在同學看起來困惑時會放慢。"},{"en":"Comedy requires audience awareness because laughter or silence gives immediate feedback.","zh":"喜劇需要觀眾意識，因為笑聲或沉默會提供即時回饋。"},{"en":"This phrase shows that speaking is a relationship with listeners.","zh":"這個說法顯示說話是與聽眾建立關係。"}],"source":"2014 Q7.pdf","sourcePage":11},{"front":"simply memorises","meaning":"只是背誦","examples":[{"en":"A strong speaker does more than simply memorise impressive vocabulary.","zh":"出色講者不只是背誦令人印象深刻的詞彙。"},{"en":"Simply memorises means only remembers words or lines without necessarily understanding or using them well.","zh":"“Simply memorises” 指只是記住字詞或句子，未必真正理解或用得好。"},{"en":"A student who simply memorises model answers may struggle when the question changes.","zh":"只是背誦範文答案的學生，在題目改變時可能會吃力。"},{"en":"Speaking well requires more than simply memorising; it needs timing, feeling, and response.","zh":"好好說話需要的不只是背誦，還需要節奏、感情和回應。"},{"en":"This phrase warns against learning language mechanically.","zh":"這個說法提醒我們不要機械式學語言。"}],"source":"2014 Q7.pdf","sourcePage":11},{"front":"impressive vocabulary","meaning":"令人印象深刻的詞彙","examples":[{"en":"Memorising impressive vocabulary alone is not enough.","zh":"單靠背誦令人印象深刻的詞彙並不足夠。"},{"en":"Impressive vocabulary means advanced or powerful words that may make writing or speaking sound strong.","zh":"令人印象深刻的詞彙是較高階或有力、能令寫作或說話聽起來強的字詞。"},{"en":"Impressive vocabulary is useful only when the words fit the meaning and situation.","zh":"令人印象深刻的詞彙只有在符合意思和情境時才有用。"},{"en":"A speech with impressive vocabulary can still fail if it has no clear ideas.","zh":"即使演講有令人印象深刻的詞彙，如果沒有清晰想法，仍可能失敗。"},{"en":"This phrase reminds students that word choice must serve communication.","zh":"這個說法提醒學生，用字必須服務溝通。"}],"source":"2014 Q7.pdf","sourcePage":11},{"front":"teaches us to think","meaning":"教我們思考","examples":[{"en":"Comedy teaches us to think.","zh":"喜劇教我們思考。"},{"en":"Teaches us to think means encourages us to examine ideas, habits, or situations more carefully.","zh":"“Teaches us to think” 指鼓勵我們更仔細檢視想法、習慣或情況。"},{"en":"A clever joke teaches us to think by showing how strange a normal habit can be.","zh":"聰明笑話透過顯示普通習慣多麼奇怪來教我們思考。"},{"en":"Comedy can teach us to think because laughter often begins with surprise.","zh":"喜劇可以教我們思考，因為笑聲常由驚喜開始。"},{"en":"This phrase shows that humour can sharpen the mind.","zh":"這個說法顯示幽默可以令思想更敏銳。"}],"source":"2014 Q7.pdf","sourcePage":11},{"front":"a familiar situation","meaning":"熟悉的情境","examples":[{"en":"A good joke often begins with a familiar situation.","zh":"好笑話常由一個熟悉的情境開始。"},{"en":"A familiar situation is an experience that many people recognise from daily life.","zh":"熟悉的情境是許多人從日常生活中認得的經驗。"},{"en":"Waiting for the lift with strangers is a familiar situation in many buildings.","zh":"和陌生人一起等升降機，是許多大廈中的熟悉情境。"},{"en":"Comedy begins with familiar situations because audiences understand them quickly.","zh":"喜劇從熟悉情境開始，因為觀眾能很快理解。"},{"en":"This phrase explains why ordinary life is useful material for jokes.","zh":"這個說法解釋為何普通生活是笑話的有用素材。"}],"source":"2014 Q7.pdf","sourcePage":11},{"front":"an unexpected truth","meaning":"意想不到的真相","examples":[{"en":"A good joke often ends with an unexpected truth.","zh":"好笑話常以一個意想不到的真相作結。"},{"en":"An unexpected truth is a real idea or observation that surprises people when they hear it.","zh":"意想不到的真相是一個真實想法或觀察，在人們聽到時令人驚訝。"},{"en":"The joke ended with an unexpected truth about how students pretend to be calm before exams.","zh":"那個笑話以一個關於學生考試前假裝冷靜的意想不到真相作結。"},{"en":"Humour becomes memorable when the punchline reveals an unexpected truth.","zh":"當笑點揭示意想不到的真相時，幽默會變得令人難忘。"},{"en":"This phrase shows that comedy can reveal reality through surprise.","zh":"這個說法顯示喜劇可以透過驚喜揭示現實。"}],"source":"2014 Q7.pdf","sourcePage":11},{"front":"in other words","meaning":"換言之","examples":[{"en":"In other words, comedy encourages us to question habits.","zh":"換言之，喜劇鼓勵我們質疑習慣。"},{"en":"In other words introduces the same idea again in a clearer or simpler way.","zh":"“In other words” 用來以更清楚或更簡單的方式重新表達同一個想法。"},{"en":"He speaks too quickly; in other words, the audience cannot follow him easily.","zh":"他說話太快；換言之，觀眾不容易跟上。"},{"en":"This phrase is useful when explaining a point again after giving examples.","zh":"在給出例子後重新解釋觀點時，這個說法很有用。"},{"en":"It helps readers understand the main meaning more directly.","zh":"它幫助讀者更直接理解主要意思。"}],"source":"2014 Q7.pdf","sourcePage":11},{"front":"encourages us to question","meaning":"鼓勵我們質疑","examples":[{"en":"Comedy encourages us to question habits.","zh":"喜劇鼓勵我們質疑習慣。"},{"en":"Encourages us to question means makes us more willing to examine whether something is reasonable or true.","zh":"“Encourages us to question” 指令我們更願意檢視某事是否合理或真實。"},{"en":"A good teacher encourages us to question answers instead of memorising them blindly.","zh":"好老師鼓勵我們質疑答案，而不是盲目背誦。"},{"en":"Comedy encourages us to question daily routines by making them look strange.","zh":"喜劇透過令日常習慣顯得奇怪，鼓勵我們質疑它們。"},{"en":"This phrase shows that humour can create critical thinking.","zh":"這個說法顯示幽默可以帶來批判思考。"}],"source":"2014 Q7.pdf","sourcePage":11},{"front":"accept without thinking","meaning":"不假思索地接受","examples":[{"en":"We often accept certain habits without thinking.","zh":"我們常不假思索地接受某些習慣。"},{"en":"To accept without thinking means to agree to or follow something automatically without questioning it.","zh":"“Accept without thinking” 指沒有質疑便自動同意或跟隨某事。"},{"en":"Students may accept exam pressure without thinking because everyone around them does the same.","zh":"學生可能因身邊人人都一樣，而不假思索地接受考試壓力。"},{"en":"Comedy can help people notice habits they have accepted without thinking.","zh":"喜劇可以幫助人留意自己不假思索地接受了哪些習慣。"},{"en":"This phrase warns against automatic behaviour.","zh":"這個說法提醒我們不要自動化地行事。"}],"source":"2014 Q7.pdf","sourcePage":11},{"front":"builds empathy","meaning":"建立同理心","examples":[{"en":"Comedy also builds empathy.","zh":"喜劇也建立同理心。"},{"en":"Builds empathy means helps people understand and share other people’s feelings.","zh":"“Builds empathy” 指幫助人理解和感受別人的情緒。"},{"en":"Stories about embarrassing moments can build empathy because everyone has felt awkward before.","zh":"關於尷尬時刻的故事可以建立同理心，因為每個人都曾感到不自在。"},{"en":"Comedy builds empathy when audiences laugh together at shared fears and mistakes.","zh":"當觀眾一起笑看共同恐懼和錯誤時，喜劇就能建立同理心。"},{"en":"This phrase shows the emotional value of humour.","zh":"這個說法顯示幽默的情感價值。"}],"source":"2014 Q7.pdf","sourcePage":12},{"front":"awkward friendships","meaning":"尷尬的友誼","examples":[{"en":"Students laughed at jokes about awkward friendships.","zh":"學生聽到關於尷尬友誼的笑話時笑了。"},{"en":"Awkward friendships are friendships that feel uncomfortable, uncertain, or difficult to manage.","zh":"尷尬的友誼是感覺不自在、不確定或難以處理的友誼。"},{"en":"An awkward friendship may begin when two people want to be close but do not know what to say.","zh":"當兩個人想親近卻不知道說甚麼時，尷尬的友誼可能開始。"},{"en":"Jokes about awkward friendships help students laugh at situations they secretly recognise.","zh":"關於尷尬友誼的笑話幫助學生笑看自己暗中認得的情況。"},{"en":"This phrase connects comedy with teenage social experience.","zh":"這個說法把喜劇與青少年的社交經驗連接起來。"}],"source":"2014 Q7.pdf","sourcePage":12},{"front":"admitting that","meaning":"承認","examples":[{"en":"By laughing together, we were admitting that we shared the same worries.","zh":"一起笑時，我們其實是在承認自己有相同的憂慮。"},{"en":"Admitting that means accepting or saying that something is true, often something personal or difficult.","zh":"“Admitting that” 指接受或說出某事是真實的，通常是較個人或困難的事情。"},{"en":"She was admitting that she felt nervous before speaking.","zh":"她承認自己在發言前感到緊張。"},{"en":"Laughing at a joke can be a quiet way of admitting that the problem is familiar.","zh":"對一個笑話發笑，可以是一種安靜地承認問題很熟悉的方法。"},{"en":"This phrase shows how humour can make honesty easier.","zh":"這個說法顯示幽默如何令誠實變得較容易。"}],"source":"2014 Q7.pdf","sourcePage":12},{"front":"share the same worries","meaning":"有相同的憂慮","examples":[{"en":"Many students share the same worries.","zh":"許多學生有相同的憂慮。"},{"en":"To share the same worries means to have similar fears, concerns, or anxieties.","zh":"“Share the same worries” 指擁有相似的恐懼、關注或焦慮。"},{"en":"Before exams, many classmates share the same worries about time and marks.","zh":"考試前，許多同學對時間和分數有相同的憂慮。"},{"en":"Realising that others share the same worries can make students feel less alone.","zh":"意識到其他人有相同的憂慮，可以令學生沒那麼孤單。"},{"en":"This phrase shows how comedy can create connection through common feelings.","zh":"這個說法顯示喜劇如何透過共同感受建立連繫。"}],"source":"2014 Q7.pdf","sourcePage":12},{"front":"most importantly","meaning":"最重要的是","examples":[{"en":"Most importantly, watching comedy can make school life healthier.","zh":"最重要的是，觀看喜劇可以令校園生活更健康。"},{"en":"Most importantly introduces the point the writer believes matters most.","zh":"“Most importantly” 用來引出作者認為最重要的觀點。"},{"en":"The activity was fun; most importantly, it helped students speak more bravely.","zh":"那項活動很有趣；最重要的是，它幫助學生更勇敢地說話。"},{"en":"This phrase guides the reader towards the strongest reason.","zh":"這個說法引導讀者留意最強的理由。"},{"en":"It is useful when ending a list of benefits with the key one.","zh":"當以最關鍵好處結束一系列好處時，它很有用。"}],"source":"2014 Q7.pdf","sourcePage":12},{"front":"school life","meaning":"校園生活","examples":[{"en":"Comedy can make school life healthier.","zh":"喜劇可以令校園生活更健康。"},{"en":"School life means the daily experience of studying, socialising, and growing up at school.","zh":"校園生活指在學校學習、社交和成長的日常經驗。"},{"en":"School life includes lessons, friendships, exams, clubs, and lunchtime conversations.","zh":"校園生活包括課堂、友誼、考試、學會和午膳對話。"},{"en":"School life becomes healthier when students can laugh, express feelings, and support one another.","zh":"當學生能笑、表達感受並互相支持時，校園生活會變得更健康。"},{"en":"This phrase focuses on students’ whole experience, not only academic results.","zh":"這個說法關注學生的整體經驗，而不只是學業成績。"}],"source":"2014 Q7.pdf","sourcePage":12},{"front":"an escape from reality","meaning":"逃避現實","examples":[{"en":"Laughter is not always an escape from reality.","zh":"笑聲不一定是逃避現實。"},{"en":"An escape from reality is a way to avoid thinking about real problems or difficult feelings.","zh":"逃避現實是一種避免思考真實問題或困難感受的方法。"},{"en":"Some people use games as an escape from reality after a stressful day.","zh":"有些人在壓力大的一天後用遊戲逃避現實。"},{"en":"Laughter can be an escape from reality, but it can also help people face reality.","zh":"笑聲可以是逃避現實，但也可以幫助人面對現實。"},{"en":"This phrase contrasts avoidance with deeper understanding.","zh":"這個說法把逃避與更深理解作對比。"}],"source":"2014 Q7.pdf","sourcePage":12},{"front":"facing reality together","meaning":"一起面對現實","examples":[{"en":"Sometimes laughter is a way of facing reality together.","zh":"有時，笑聲是一種一起面對現實的方法。"},{"en":"Facing reality together means looking honestly at a difficult truth with other people instead of alone.","zh":"一起面對現實指與別人一同誠實看待困難真相，而不是獨自承受。"},{"en":"Students facing exam stress together may feel stronger than dealing with it privately.","zh":"學生一起面對考試壓力，可能比私下獨自處理更有力量。"},{"en":"Comedy helps people face reality together by turning shared worries into shared laughter.","zh":"喜劇透過把共同憂慮變成共同笑聲，幫助人一起面對現實。"},{"en":"This phrase shows that humour can create courage and community.","zh":"這個說法顯示幽默可以帶來勇氣和群體感。"}],"source":"2014 Q7.pdf","sourcePage":12},{"front":"invite local comedians","meaning":"邀請本地棟篤笑演員","examples":[{"en":"The school could invite local comedians.","zh":"學校可以邀請本地棟篤笑演員。"},{"en":"To invite local comedians means to ask comedians from the local community to perform or teach.","zh":"「邀請本地棟篤笑演員」指請本地社區的喜劇演員來表演或教學。"},{"en":"The English Society could invite local comedians to speak about timing and storytelling.","zh":"英文學會可以邀請本地棟篤笑演員講解節奏和說故事技巧。"},{"en":"Inviting local comedians gives students real examples of language used creatively.","zh":"邀請本地棟篤笑演員，可以給學生真實例子，看見語言如何被創意使用。"},{"en":"This phrase suggests a practical way to connect school learning with live performance.","zh":"這個說法提出把學校學習與現場表演連接的實際方法。"}],"source":"2014 Q7.pdf","sourcePage":12},{"front":"organise student comedy workshops","meaning":"舉辦學生喜劇工作坊","examples":[{"en":"The school could organise student comedy workshops.","zh":"學校可以舉辦學生喜劇工作坊。"},{"en":"To organise student comedy workshops means to arrange sessions where students learn to write and perform comedy.","zh":"「舉辦學生喜劇工作坊」指安排課程，讓學生學習寫作和表演喜劇。"},{"en":"A student comedy workshop may teach timing, observation, and respectful humour.","zh":"學生喜劇工作坊可以教授節奏、觀察和尊重他人的幽默。"},{"en":"Such workshops can help shy students practise speaking in a supportive setting.","zh":"這類工作坊可以幫助害羞學生在支持性環境中練習說話。"},{"en":"This phrase turns appreciation of comedy into active learning.","zh":"這個說法把欣賞喜劇轉化成主動學習。"}],"source":"2014 Q7.pdf","sourcePage":12},{"front":"humorous speeches","meaning":"幽默演講","examples":[{"en":"The school could include humorous speeches in English activities.","zh":"學校可以在英文活動中加入幽默演講。"},{"en":"Humorous speeches are speeches that use appropriate jokes, funny examples, or light-hearted observations.","zh":"幽默演講是使用合適笑話、有趣例子或輕鬆觀察的演講。"},{"en":"Students can give humorous speeches about school life, homework, or friendship.","zh":"學生可以就校園生活、功課或友誼作幽默演講。"},{"en":"Humorous speeches help students practise confidence while keeping the audience interested.","zh":"幽默演講幫助學生練習自信，同時保持觀眾興趣。"},{"en":"This phrase shows how humour can become part of language education.","zh":"這個說法顯示幽默可以成為語言教育的一部分。"}],"source":"2014 Q7.pdf","sourcePage":13},{"front":"English activities","meaning":"英文活動","examples":[{"en":"Humorous speeches could be included in English activities.","zh":"幽默演講可以被加入英文活動中。"},{"en":"English activities are school activities that help students use, practise, or enjoy English.","zh":"英文活動是幫助學生使用、練習或享受英語的學校活動。"},{"en":"English activities may include drama, debate, writing contests, and speaking games.","zh":"英文活動可以包括戲劇、辯論、寫作比賽和說話遊戲。"},{"en":"Adding humour to English activities can make students less afraid of making mistakes.","zh":"在英文活動中加入幽默，可以令學生不那麼害怕犯錯。"},{"en":"This phrase refers to learning beyond normal textbook exercises.","zh":"這個說法指課本練習以外的學習。"}],"source":"2014 Q7.pdf","sourcePage":13},{"front":"laugh thoughtfully","meaning":"有思考地笑","examples":[{"en":"Students can learn to laugh thoughtfully.","zh":"學生可以學會有思考地笑。"},{"en":"To laugh thoughtfully means to enjoy humour while also thinking about its meaning and effect.","zh":"「有思考地笑」指享受幽默的同時，也思考它的意思和影響。"},{"en":"We laughed thoughtfully when the joke made us see exam pressure differently.","zh":"當那個笑話令我們以不同方式看考試壓力時，我們有思考地笑了。"},{"en":"Laughing thoughtfully helps students enjoy comedy without ignoring people’s feelings.","zh":"有思考地笑幫助學生享受喜劇，同時不忽略別人感受。"},{"en":"This phrase shows that laughter can be intelligent and responsible.","zh":"這個說法顯示笑聲可以有智慧，也可以負責任。"}],"source":"2014 Q7.pdf","sourcePage":13},{"front":"speak bravely","meaning":"勇敢地說話","examples":[{"en":"Students can learn to speak bravely.","zh":"學生可以學會勇敢地說話。"},{"en":"To speak bravely means to express ideas clearly even when you feel nervous or unsure.","zh":"「勇敢地說話」指即使感到緊張或不確定，也清楚表達想法。"},{"en":"A student speaks bravely when she shares an honest opinion during class discussion.","zh":"當學生在課堂討論中分享真誠意見時，她就是勇敢地說話。"},{"en":"Watching performers face an audience can encourage students to speak bravely.","zh":"觀看表演者面對觀眾，可以鼓勵學生勇敢地說話。"},{"en":"This phrase connects language learning with courage.","zh":"這個說法把語言學習與勇氣連接起來。"}],"source":"2014 Q7.pdf","sourcePage":13},{"front":"listen generously","meaning":"慷慨地聆聽","examples":[{"en":"Students can learn to listen generously.","zh":"學生可以學會慷慨地聆聽。"},{"en":"To listen generously means to listen with patience, kindness, and willingness to understand.","zh":"「慷慨地聆聽」指帶着耐性、善意和理解意願去聆聽。"},{"en":"A class listens generously when it gives a nervous speaker time to finish.","zh":"當全班給緊張的講者時間完成說話時，就是慷慨地聆聽。"},{"en":"Comedy teaches generous listening because audiences must follow the performer’s rhythm and intention.","zh":"喜劇教人慷慨地聆聽，因為觀眾必須跟隨表演者的節奏和意圖。"},{"en":"This phrase shows that good communication depends on the listener as well as the speaker.","zh":"這個說法顯示好溝通不只取決於講者，也取決於聽者。"}],"source":"2014 Q7.pdf","sourcePage":13},{"front":"not only…but also…","meaning":"不但……而且……","examples":[{"en":"We will become not only better English users, but also kinder classmates.","zh":"我們不但會成為更好的英文使用者，而且會成為更友善的同學。"},{"en":"Not only…but also… connects two important results and shows both are true.","zh":"“Not only…but also…” 連接兩個重要結果，並顯示兩者都成立。"},{"en":"Drama helps students not only speak clearly, but also understand others better.","zh":"戲劇不但幫助學生清楚說話，而且幫助他們更理解別人。"},{"en":"Comedy can improve not only language skills, but also classroom relationships.","zh":"喜劇不但可以改善語言能力，而且可以改善課堂關係。"},{"en":"This structure is useful when showing that one activity has more than one benefit.","zh":"當要顯示一項活動有多於一個好處時，這個結構很有用。"}],"source":"2014 Q7.pdf","sourcePage":13},{"front":"better English users","meaning":"更好的英文使用者","examples":[{"en":"Live performances can help students become better English users.","zh":"現場表演可以幫助學生成為更好的英文使用者。"},{"en":"Better English users are people who can understand and use English more clearly, naturally, and confidently.","zh":"更好的英文使用者是能更清楚、自然和有信心地理解及使用英語的人。"},{"en":"Students become better English users when they practise real listening and speaking.","zh":"當學生練習真實聆聽和說話時，他們會成為更好的英文使用者。"},{"en":"Watching comedy helps students become better English users by showing rhythm, tone, and timing.","zh":"觀看喜劇透過展示節奏、語氣和時機，幫助學生成為更好的英文使用者。"},{"en":"This phrase focuses on practical communication, not only exam marks.","zh":"這個說法關注實際溝通，而不只是考試分數。"}],"source":"2014 Q7.pdf","sourcePage":13},{"front":"kinder classmates","meaning":"更友善的同學","examples":[{"en":"Comedy may help students become kinder classmates.","zh":"喜劇可能幫助學生成為更友善的同學。"},{"en":"Kinder classmates are students who treat one another with more care, patience, and understanding.","zh":"更友善的同學是以更多關心、耐性和理解對待彼此的學生。"},{"en":"A kinder classmate listens when someone is nervous during a presentation.","zh":"更友善的同學會在別人匯報緊張時耐心聆聽。"},{"en":"Comedy can make students kinder classmates when shared laughter helps them recognise common worries.","zh":"當共同笑聲幫助學生看見彼此相同的憂慮時，喜劇可以令他們成為更友善的同學。"},{"en":"This phrase shows that language activities can improve character and relationships.","zh":"這個說法顯示語言活動可以改善品格和關係。"}],"source":"2014 Q7.pdf","sourcePage":13},{"front":"lasted just over an hour","meaning":"持續剛超過一小時","examples":[{"en":"The show lasted just over an hour.","zh":"那場表演持續剛超過一小時。"},{"en":"Lasted just over an hour means continued for a little more than sixty minutes.","zh":"“Lasted just over an hour” 指持續略多於六十分鐘。"},{"en":"The workshop lasted just over an hour, but students kept talking about it afterwards.","zh":"那個工作坊持續剛超過一小時，但學生之後仍一直討論。"},{"en":"A short performance can still have a strong effect even if it lasts just over an hour.","zh":"即使一場短表演只持續剛超過一小時，也可以有強烈影響。"},{"en":"This phrase gives a clear sense of duration.","zh":"這個說法清楚交代時間長度。"}],"source":"2014 Q7.pdf","sourcePage":13},{"front":"still echoing in my mind","meaning":"仍在我腦海中迴響","examples":[{"en":"The message of the show is still echoing in my mind.","zh":"那場表演的信息仍在我腦海中迴響。"},{"en":"Still echoing in my mind means I continue to remember and think about it after the event has ended.","zh":"“Still echoing in my mind” 指事件結束後，我仍然記得並思考它。"},{"en":"The teacher’s advice is still echoing in my mind before every presentation.","zh":"每次簡報前，老師的建議仍在我腦海中迴響。"},{"en":"A powerful performance can keep echoing in someone’s mind because it touches a real feeling.","zh":"有力量的表演可以因觸動真實感受而一直在某人腦海中迴響。"},{"en":"This phrase shows that an experience has a lasting emotional or intellectual effect.","zh":"這個說法顯示一段經歷有持久的情感或思想影響。"}],"source":"2014 Q7.pdf","sourcePage":13},{"front":"the shortest distance between people","meaning":"人與人之間最短的距離","examples":[{"en":"Sometimes, the shortest distance between people is a punchline.","zh":"有時，人與人之間最短的距離是一個笑點。"},{"en":"The shortest distance between people means the quickest way to create closeness or understanding between them.","zh":"“The shortest distance between people” 指在人與人之間建立親近或理解的最快方法。"},{"en":"A shared laugh can be the shortest distance between strangers in a quiet room.","zh":"在安靜房間中，一次共同笑聲可以成為陌生人之間最短的距離。"},{"en":"Humour can shorten the distance between people because it shows they recognise the same truth.","zh":"幽默可以縮短人與人之間的距離，因為它顯示大家認得同一個真相。"},{"en":"This phrase uses distance as a metaphor for emotional separation.","zh":"這個說法用距離比喻情感上的分隔。"}],"source":"2014 Q7.pdf","sourcePage":14},{"front":"a punchline","meaning":"笑點；妙語結尾","examples":[{"en":"A punchline can bring people closer together.","zh":"一個笑點可以拉近人與人之間的距離。"},{"en":"A punchline is the final part of a joke that creates the surprise or laughter.","zh":"笑點是笑話的最後部分，用來製造驚喜或笑聲。"},{"en":"The punchline came after a long pause, so the audience laughed even harder.","zh":"那個笑點在長停頓後出現，所以觀眾笑得更大聲。"},{"en":"A strong punchline works because it changes how listeners understand everything before it.","zh":"有力的笑點之所以奏效，是因為它改變聽眾對前面內容的理解。"},{"en":"This phrase names the moment when a joke suddenly becomes funny or meaningful.","zh":"這個說法指出笑話突然變得有趣或有意義的時刻。"}],"source":"2014 Q7.pdf","sourcePage":14}],"dse/writing/part-b/2014/Q8":[{"front":"more than a voice","meaning":"不只是一把聲音","examples":[{"en":"The Poetry Festival taught me that performance is more than a voice.","zh":"詩歌節教會我，表演不只是一把聲音。"},{"en":"More than a voice means performance needs meaning, feeling, body control, and understanding, not just sound.","zh":"不只是一把聲音，意思是表演需要意思、感情、身體控制和理解，而不只是聲音。"},{"en":"A good speech is more than a voice because the speaker must connect with listeners.","zh":"好的演講不只是一把聲音，因為講者必須與聽眾連繫。"},{"en":"If a performer only sounds loud but does not understand the text, the performance is not complete.","zh":"如果表演者只有聲音響亮，卻不理解文本，表演就不完整。"},{"en":"Poetry recitation is more than a voice because the performer must bring thought and emotion together.","zh":"詩歌朗誦不只是一把聲音，因為表演者必須把思想和情感結合起來。"}],"source":"2014 Q8.pdf","sourcePage":1},{"front":"taught me","meaning":"教會我","examples":[{"en":"The Poetry Festival taught me discipline, interpretation and courage.","zh":"詩歌節教會我紀律、演繹和勇氣。"},{"en":"Taught me means helped me learn something through experience.","zh":"教會我，意思是透過經驗幫助我學到某事。"},{"en":"Losing a debate taught me the value of preparation.","zh":"輸掉辯論教會我準備的重要性。"},{"en":"Difficult activities teach students lessons that textbooks alone cannot give.","zh":"困難活動教會學生一些單靠課本不能給予的課題。"},{"en":"The Festival taught me that careful practice can change fear into confidence.","zh":"詩歌節教會我，細心練習可以把恐懼變成信心。"}],"source":"2014 Q8.pdf","sourcePage":1},{"front":"invite someone to join","meaning":"邀請某人參加","examples":[{"en":"Our English teacher invited us to join the Hong Kong Schools Poetry Festival.","zh":"我們的英文老師邀請我們參加香港學校詩歌節。"},{"en":"To invite someone to join means to ask them to take part in an activity or group.","zh":"邀請某人參加，意思是請某人參與一項活動或加入一個群體。"},{"en":"A coach may invite a student to join the school football team.","zh":"教練可能邀請學生參加學校足球隊。"},{"en":"When teachers invite students to join new activities, students may discover hidden talents.","zh":"當老師邀請學生參加新活動，學生可能發現隱藏才能。"},{"en":"Being invited to join the Festival gave the writer a chance to grow.","zh":"被邀請參加詩歌節，給作者一個成長的機會。"}],"source":"2014 Q8.pdf","sourcePage":1},{"front":"the Hong Kong Schools Poetry Festival","meaning":"香港學校詩歌節","examples":[{"en":"Students were invited to join the Hong Kong Schools Poetry Festival.","zh":"學生被邀請參加香港學校詩歌節。"},{"en":"The Hong Kong Schools Poetry Festival is a school event where students perform poems aloud.","zh":"香港學校詩歌節，是學生朗誦詩歌的校際活動。"},{"en":"A student may prepare for the Hong Kong Schools Poetry Festival by choosing and practising a poem.","zh":"學生可能透過選詩和練習來準備香港學校詩歌節。"},{"en":"The Festival helps students learn pronunciation, interpretation, and confidence.","zh":"詩歌節幫助學生學習發音、演繹和信心。"},{"en":"Joining the Hong Kong Schools Poetry Festival can turn poetry from words on paper into performance.","zh":"參加香港學校詩歌節，可以把紙上的詩變成表演。"}],"source":"2014 Q8.pdf","sourcePage":1},{"front":"see it as","meaning":"把它視為","examples":[{"en":"I first saw it as another activity in a crowded term.","zh":"起初，我把它視為繁忙學期中的另一項活動。"},{"en":"To see it as something means to understand or treat it in that way.","zh":"把它視為某事，意思是以那種方式理解或看待它。"},{"en":"A student may see homework as practice rather than punishment.","zh":"學生可能把功課視為練習，而不是懲罰。"},{"en":"How we see an activity affects how seriously we prepare for it.","zh":"我們如何看待一項活動，會影響我們準備得多認真。"},{"en":"At first, the writer saw the Festival as extra work, but later saw it as a lesson.","zh":"起初，作者把詩歌節視為額外工作，但後來把它視為一堂課。"}],"source":"2014 Q8.pdf","sourcePage":1},{"front":"squeeze into","meaning":"擠進；勉強安排進","examples":[{"en":"I saw the Festival as another activity to squeeze into an already crowded term.","zh":"我把詩歌節視為另一項要擠進已經很忙碌學期的活動。"},{"en":"To squeeze something into a schedule means to fit it in when there is very little time.","zh":"把某事擠進時間表，意思是在時間很少的情況下把它安排進去。"},{"en":"A student may squeeze a piano lesson into a week full of tests.","zh":"學生可能把鋼琴課擠進充滿測驗的一星期。"},{"en":"When too many duties are squeezed into one day, people become tired and stressed.","zh":"當太多職責被擠進同一天，人們會疲倦和有壓力。"},{"en":"The writer had to squeeze poetry practice into a term that was already busy.","zh":"作者不得不把詩歌練習擠進已經繁忙的學期。"}],"source":"2014 Q8.pdf","sourcePage":1},{"front":"an already crowded term","meaning":"已經很忙碌的學期","examples":[{"en":"The school term was already crowded with tests and duties.","zh":"這個學期已經因測驗和職責而很忙碌。"},{"en":"An already crowded term means a school period that is full of activities before anything new is added.","zh":"已經很忙碌的學期，是指在加入新活動前已充滿事情的上學時段。"},{"en":"An already crowded term may include exams, projects, club meetings, and sports practice.","zh":"已經很忙碌的學期可能包括考試、專題、學會會議和運動練習。"},{"en":"Adding another competition to an already crowded term can feel overwhelming.","zh":"在已經很忙碌的學期再加入另一項比賽，可能令人難以承受。"},{"en":"The writer joined the Festival even though the term was already crowded.","zh":"即使學期已經很忙碌，作者仍參加詩歌節。"}],"source":"2014 Q8.pdf","sourcePage":1},{"front":"with tests approaching","meaning":"隨着測驗臨近","examples":[{"en":"With tests approaching, joining the competition felt ambitious.","zh":"隨着測驗臨近，參加比賽感覺很有挑戰性。"},{"en":"With tests approaching means tests are coming soon.","zh":"隨着測驗臨近，意思是測驗快要到來。"},{"en":"With exams approaching, students often begin to plan their revision time.","zh":"隨着考試臨近，學生通常開始規劃溫習時間。"},{"en":"When tests are approaching, extra activities may feel more stressful.","zh":"當測驗臨近，額外活動可能令人感到更大壓力。"},{"en":"The competition felt challenging because tests were approaching at the same time.","zh":"比賽感覺有挑戰性，因為測驗也同時臨近。"}],"source":"2014 Q8.pdf","sourcePage":1},{"front":"club duties piling up","meaning":"學會職務愈積愈多","examples":[{"en":"Club duties were piling up during the term.","zh":"學會職務在學期中愈積愈多。"},{"en":"Club duties piling up means club responsibilities are increasing and becoming harder to manage.","zh":"學會職務愈積愈多，意思是學會責任不斷增加，變得更難處理。"},{"en":"A committee member may feel stressed when meetings, posters, and event planning start piling up.","zh":"當會議、海報和活動策劃開始累積，幹事可能感到壓力。"},{"en":"Duties pile up when many small tasks are left unfinished.","zh":"當許多小任務未完成，職務就會愈積愈多。"},{"en":"The writer had to prepare for poetry while club duties were piling up.","zh":"作者要在學會職務愈積愈多時準備詩歌。"}],"source":"2014 Q8.pdf","sourcePage":1},{"front":"entering a poetry competition","meaning":"參加詩歌比賽","examples":[{"en":"Entering a poetry competition felt ambitious.","zh":"參加詩歌比賽感覺很有挑戰性。"},{"en":"Entering a poetry competition means signing up to perform or present a poem in a contest.","zh":"參加詩歌比賽，意思是報名在比賽中表演或呈現一首詩。"},{"en":"A shy student may feel nervous about entering a poetry competition for the first time.","zh":"害羞的學生第一次參加詩歌比賽可能會緊張。"},{"en":"Entering a competition requires time because the poem must be understood and practised.","zh":"參加比賽需要時間，因為詩必須被理解和練習。"},{"en":"Entering a poetry competition helped the writer learn courage through performance.","zh":"參加詩歌比賽幫助作者透過表演學習勇氣。"}],"source":"2014 Q8.pdf","sourcePage":1},{"front":"felt ambitious","meaning":"感覺很有挑戰性","examples":[{"en":"Entering the competition felt ambitious.","zh":"參加比賽感覺很有挑戰性。"},{"en":"Felt ambitious means seemed difficult but worth trying because the goal was high.","zh":"感覺很有挑戰性，意思是看起來困難，但因目標較高而值得嘗試。"},{"en":"Joining three activities in one month felt ambitious for a new student.","zh":"新學生一個月內參加三項活動，可能感覺很有挑戰性。"},{"en":"A plan feels ambitious when it requires more effort than usual.","zh":"當計劃需要比平常更多努力，它就會感覺很有挑戰性。"},{"en":"The Festival felt ambitious because the writer had tests, duties, and practice to manage.","zh":"詩歌節感覺很有挑戰性，因為作者要同時處理測驗、職務和練習。"}],"source":"2014 Q8.pdf","sourcePage":2},{"front":"if not slightly reckless","meaning":"甚至有點魯莽","examples":[{"en":"Joining the competition felt ambitious, if not slightly reckless.","zh":"參加比賽感覺很有挑戰性，甚至有點魯莽。"},{"en":"If not slightly reckless means perhaps even a little careless or risky.","zh":"甚至有點魯莽，意思是可能有一點不夠謹慎或有風險。"},{"en":"Taking five exams and joining a contest in the same week felt ambitious, if not slightly reckless.","zh":"同一星期考五個測驗又參加比賽，感覺很有挑戰性，甚至有點魯莽。"},{"en":"This phrase shows that a decision may be brave but also risky.","zh":"這個短語顯示一個決定可能勇敢，但也有風險。"},{"en":"The writer wondered whether joining the Festival was sensible or slightly reckless.","zh":"作者懷疑參加詩歌節到底是明智，還是有點魯莽。"}],"source":"2014 Q8.pdf","sourcePage":2},{"front":"for context","meaning":"作為背景","examples":[{"en":"For context, our school has always encouraged students to try new activities.","zh":"作為背景，我們學校一直鼓勵學生嘗試新活動。"},{"en":"For context means to give background information that helps people understand the situation.","zh":"作為背景，意思是提供幫助人們理解情況的背景資料。"},{"en":"For context, the class had already spent two weeks studying poetry.","zh":"作為背景，這個班已經用了兩星期學習詩歌。"},{"en":"Writers use this phrase before explaining why something happened.","zh":"作者使用這個短語來解釋某事為何發生。"},{"en":"The writer says “for context” to explain why joining the Festival was encouraged.","zh":"作者說「作為背景」，是為了解釋為何學校鼓勵參加詩歌節。"}],"source":"2014 Q8.pdf","sourcePage":2},{"front":"step beyond","meaning":"走出……之外","examples":[{"en":"Our school encourages students to step beyond examination routines.","zh":"我們學校鼓勵學生走出考試常規之外。"},{"en":"To step beyond something means to move outside a familiar limit or pattern.","zh":"走出某事之外，意思是離開熟悉的限制或模式。"},{"en":"Students step beyond textbooks when they join debates, performances, or service projects.","zh":"當學生參加辯論、表演或服務計劃，他們就走出課本之外。"},{"en":"Stepping beyond routine can help students discover new abilities.","zh":"走出常規可以幫助學生發現新能力。"},{"en":"The Poetry Festival allowed the writer to step beyond ordinary exam preparation.","zh":"詩歌節讓作者走出普通考試準備之外。"}],"source":"2014 Q8.pdf","sourcePage":2},{"front":"examination routines","meaning":"考試常規","examples":[{"en":"Students should step beyond examination routines.","zh":"學生應走出考試常規之外。"},{"en":"Examination routines are the repeated habits of studying, testing, and preparing for marks.","zh":"考試常規，是圍繞學習、測驗和準備分數的重複習慣。"},{"en":"Revision timetables, past papers, and quizzes can become examination routines.","zh":"溫習時間表、歷屆試題和小測都可以成為考試常規。"},{"en":"Examination routines are useful, but students also need creativity and confidence.","zh":"考試常規有用，但學生也需要創意和信心。"},{"en":"The Festival helped students learn outside ordinary examination routines.","zh":"詩歌節幫助學生在普通考試常規以外學習。"}],"source":"2014 Q8.pdf","sourcePage":2},{"front":"make me consider","meaning":"令我考慮","examples":[{"en":"This opportunity made me consider preparing seriously.","zh":"這個機會令我考慮認真準備。"},{"en":"Make me consider means cause me to think carefully about something.","zh":"令我考慮，意思是使我仔細思考某事。"},{"en":"A teacher’s advice may make a student consider joining a speech contest.","zh":"老師的建議可能令學生考慮參加演講比賽。"},{"en":"Good opportunities make people consider what they can become with effort.","zh":"好機會令人思考透過努力可以成為怎樣的人。"},{"en":"Being invited to the Festival made the writer consider taking poetry seriously.","zh":"被邀請參加詩歌節，令作者考慮認真對待詩歌。"}],"source":"2014 Q8.pdf","sourcePage":2},{"front":"prepare seriously","meaning":"認真準備","examples":[{"en":"The opportunity made me prepare seriously.","zh":"這個機會令我認真準備。"},{"en":"To prepare seriously means to practise with care, time, and clear purpose.","zh":"認真準備，意思是用心、花時間並帶着清晰目的去練習。"},{"en":"A student prepares seriously for an interview by researching the school and practising answers.","zh":"學生透過研究學校和練習回答問題來認真準備面試。"},{"en":"Serious preparation reduces panic because the task becomes more familiar.","zh":"認真準備可以減少恐慌，因為任務變得更熟悉。"},{"en":"The writer prepared seriously by annotating, recording, and rehearsing the poem.","zh":"作者透過註釋、錄音和排練來認真準備詩歌。"}],"source":"2014 Q8.pdf","sourcePage":2},{"front":"represent the school","meaning":"代表學校","examples":[{"en":"I wanted to represent the school with confidence.","zh":"我想有信心地代表學校。"},{"en":"To represent the school means to take part in an event as a student speaking or competing for the school.","zh":"代表學校，意思是以學校學生身份參與活動、發言或比賽。"},{"en":"A runner may represent the school in an inter-school athletics competition.","zh":"跑手可能在校際田徑比賽中代表學校。"},{"en":"Representing the school can make students feel responsible for their effort and behaviour.","zh":"代表學校會令學生對自己的努力和行為更有責任感。"},{"en":"The writer wanted to represent the school well at the Poetry Festival.","zh":"作者希望在詩歌節中好好代表學校。"}],"source":"2014 Q8.pdf","sourcePage":2},{"front":"with confidence","meaning":"有信心地","examples":[{"en":"I hoped to represent the school with confidence.","zh":"我希望有信心地代表學校。"},{"en":"With confidence means in a sure, calm, and positive way.","zh":"有信心地，意思是以肯定、冷靜和正面的方式。"},{"en":"A student speaks with confidence when they know the topic well.","zh":"當學生熟悉題目，就能有信心地說話。"},{"en":"Confidence grows when preparation makes a difficult task feel manageable.","zh":"當準備令困難任務變得可處理，信心就會增長。"},{"en":"The writer wanted to walk onto the stage with confidence instead of fear.","zh":"作者希望有信心地走上舞台，而不是帶着恐懼。"}],"source":"2014 Q8.pdf","sourcePage":2},{"front":"discover what a poem can become","meaning":"探索一首詩可以變成甚麼","examples":[{"en":"I wanted to discover what a poem can become when spoken aloud.","zh":"我想探索一首詩被大聲朗讀時可以變成甚麼。"},{"en":"To discover what a poem can become means to find out how poetry changes through performance.","zh":"探索一首詩可以變成甚麼，意思是發現詩歌如何透過表演而改變。"},{"en":"A student may discover that a poem becomes more emotional when read slowly.","zh":"學生可能發現詩歌慢慢朗讀時會變得更有情感。"},{"en":"Speaking a poem aloud can reveal rhythm and meaning that silent reading misses.","zh":"大聲朗讀一首詩，可以揭示默讀時錯過的節奏和意思。"},{"en":"The Festival helped the writer discover that a poem can become a living voice.","zh":"詩歌節幫助作者發現一首詩可以變成有生命力的聲音。"}],"source":"2014 Q8.pdf","sourcePage":2},{"front":"be lifted from the page","meaning":"從紙上被帶到現實中","examples":[{"en":"A poem changes when it is lifted from the page.","zh":"一首詩從紙上被帶到現實中時會改變。"},{"en":"Be lifted from the page means written words are brought into spoken, living performance.","zh":"從紙上被帶到現實中，意思是文字被轉化成有聲、有生命的表演。"},{"en":"A script is lifted from the page when actors speak it on stage.","zh":"當演員在舞台上說出台詞，劇本就從紙上被帶到現實中。"},{"en":"Words become more immediate when they are lifted from the page into voice.","zh":"當文字從紙上被帶進聲音，它們會變得更直接。"},{"en":"Recitation lifts a poem from the page and gives it breath, rhythm, and presence.","zh":"朗誦把詩從紙上帶到現實中，給它呼吸、節奏和存在感。"}],"source":"2014 Q8.pdf","sourcePage":3},{"front":"looking back","meaning":"回望起來","examples":[{"en":"Looking back, I would say the Festival taught me courage.","zh":"回望起來，我會說詩歌節教會我勇氣。"},{"en":"Looking back means thinking about a past experience after time has passed.","zh":"回望起來，意思是在時間過去後思考過去經驗。"},{"en":"Looking back, a difficult exam may seem like useful training.","zh":"回望起來，一場困難考試可能像有用的訓練。"},{"en":"People understand lessons more clearly when they look back calmly.","zh":"當人們冷靜回望，就能更清楚理解學到的課題。"},{"en":"Looking back, the writer sees the Festival as more than a competition.","zh":"回望起來，作者把詩歌節看成不只是比賽。"}],"source":"2014 Q8.pdf","sourcePage":3},{"front":"go so far as to say","meaning":"甚至可以說","examples":[{"en":"I would go so far as to say that the Festival was a lesson in courage.","zh":"我甚至可以說，詩歌節是一堂關於勇氣的課。"},{"en":"To go so far as to say something means to make a strong statement that may sound surprising.","zh":"甚至可以說某事，意思是作出一個較強烈、可能令人意外的說法。"},{"en":"I would go so far as to say that failure taught me more than success.","zh":"我甚至可以說，失敗教會我的比成功更多。"},{"en":"Writers use this phrase when they want to show that their view is strong.","zh":"作者使用這個短語，是為了顯示自己的看法很強烈。"},{"en":"The writer goes so far as to say the Festival changed how they understood performance.","zh":"作者甚至可以說，詩歌節改變了他對表演的理解。"}],"source":"2014 Q8.pdf","sourcePage":3},{"front":"not merely a contest of pronunciation","meaning":"不只是發音比賽","examples":[{"en":"The Festival was not merely a contest of pronunciation.","zh":"詩歌節不只是發音比賽。"},{"en":"Not merely a contest of pronunciation means the event tested more than saying words correctly.","zh":"不只是發音比賽，意思是活動考驗的不只是把字音讀準。"},{"en":"A speech competition is not merely a contest of volume; it also tests ideas and connection.","zh":"演講比賽不只是聲量比賽；它也考驗想法和連繫。"},{"en":"Pronunciation matters, but meaning and interpretation matter too.","zh":"發音重要，但意思和演繹也重要。"},{"en":"The Poetry Festival was not merely a pronunciation contest because it required courage and understanding.","zh":"詩歌節不只是發音比賽，因為它需要勇氣和理解。"}],"source":"2014 Q8.pdf","sourcePage":3},{"front":"a lesson in discipline","meaning":"一堂關於紀律的課","examples":[{"en":"The Festival became a lesson in discipline.","zh":"詩歌節成為一堂關於紀律的課。"},{"en":"A lesson in discipline means an experience that teaches self-control, routine, and steady effort.","zh":"一堂關於紀律的課，是教人自我控制、規律和持續努力的經驗。"},{"en":"Training for a race can become a lesson in discipline.","zh":"為賽跑訓練可以成為一堂關於紀律的課。"},{"en":"Discipline grows when students practise even when they do not feel ready.","zh":"當學生即使覺得未準備好仍然練習，紀律就會增長。"},{"en":"The Festival taught discipline because the writer had to practise every day.","zh":"詩歌節教會紀律，因為作者必須每天練習。"}],"source":"2014 Q8.pdf","sourcePage":3},{"front":"interpretation and courage","meaning":"演繹與勇氣","examples":[{"en":"The Festival taught me interpretation and courage.","zh":"詩歌節教會我演繹與勇氣。"},{"en":"Interpretation and courage mean understanding a text deeply and daring to express it honestly.","zh":"演繹與勇氣，意思是深入理解文本，並敢於真誠地表達它。"},{"en":"Drama lessons teach interpretation and courage when students explore characters on stage.","zh":"當學生在舞台上探索角色，戲劇課就教會演繹與勇氣。"},{"en":"Interpretation without courage may stay hidden; courage without interpretation may feel empty.","zh":"沒有勇氣的演繹可能留在心裏；沒有演繹的勇氣可能顯得空洞。"},{"en":"Poetry performance needs both interpretation and courage to sound truthful.","zh":"詩歌表演需要演繹與勇氣，才會聽起來真實。"}],"source":"2014 Q8.pdf","sourcePage":3},{"front":"preparation began with","meaning":"準備由……開始","examples":[{"en":"My preparation began with choosing a poem.","zh":"我的準備由選擇一首詩開始。"},{"en":"Preparation began with something means the first step in getting ready was that action.","zh":"準備由某事開始，意思是準備的第一步就是那個行動。"},{"en":"My exam preparation began with making a revision timetable.","zh":"我的考試準備由制定溫習時間表開始。"},{"en":"Good preparation often begins with one clear first task.","zh":"好的準備通常由一項清晰的第一步開始。"},{"en":"The writer’s preparation began with choosing a poem that looked simple but was not.","zh":"作者的準備由選擇一首看似簡單但其實不然的詩開始。"}],"source":"2014 Q8.pdf","sourcePage":3},{"front":"deceptively simple","meaning":"看似簡單但其實不然","examples":[{"en":"I chose a poem that looked deceptively simple.","zh":"我選了一首看似簡單但其實不然的詩。"},{"en":"Deceptively simple means something appears easy but is actually more difficult or complex.","zh":"看似簡單但其實不然，意思是某事表面容易，但其實更困難或複雜。"},{"en":"A short maths question can be deceptively simple if one small detail changes the answer.","zh":"如果一個小細節會改變答案，短數學題也可能看似簡單但其實不然。"},{"en":"Deceptively simple poems require careful reading because hidden meaning may sit in ordinary words.","zh":"看似簡單但其實不然的詩需要仔細閱讀，因為隱藏意思可能藏在普通字詞中。"},{"en":"The poem looked easy at first, but its pauses and images made it deceptively simple.","zh":"這首詩起初看似容易，但停頓和意象令它看似簡單但其實不然。"}],"source":"2014 Q8.pdf","sourcePage":3},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, the poem seemed easy to recite.","zh":"乍看之下，這首詩似乎容易朗誦。"},{"en":"At first glance means when first looking at something, before studying it carefully.","zh":"乍看之下，意思是第一次看某事時，還未仔細研究之前。"},{"en":"At first glance, the homework looked short, but it required deep thinking.","zh":"乍看之下，功課看起來很短，但它需要深入思考。"},{"en":"First impressions can be wrong when details are hidden.","zh":"當細節被隱藏，第一印象可能是錯的。"},{"en":"At first glance, the poem looked easy, but closer reading showed its difficulty.","zh":"乍看之下，這首詩看似容易，但仔細閱讀顯示它的難度。"}],"source":"2014 Q8.pdf","sourcePage":3},{"front":"clear reading","meaning":"清晰朗讀","examples":[{"en":"The poem seemed to require only clear reading.","zh":"這首詩似乎只需要清晰朗讀。"},{"en":"Clear reading means speaking words in a way that listeners can hear and understand easily.","zh":"清晰朗讀，意思是以聽眾容易聽見和理解的方式讀出文字。"},{"en":"A news report needs clear reading so the audience can follow the information.","zh":"新聞報道需要清晰朗讀，讓觀眾能跟上資訊。"},{"en":"Clear reading is important, but poetry also needs rhythm and feeling.","zh":"清晰朗讀很重要，但詩歌也需要節奏和感情。"},{"en":"The writer first thought clear reading was enough, then learned that interpretation mattered.","zh":"作者起初以為清晰朗讀已足夠，後來明白演繹也重要。"}],"source":"2014 Q8.pdf","sourcePage":3},{"front":"accurate memorisation","meaning":"準確背誦","examples":[{"en":"The competition required accurate memorisation.","zh":"比賽需要準確背誦。"},{"en":"Accurate memorisation means remembering words correctly without changing, missing, or adding them.","zh":"準確背誦，意思是正確記住文字，不改變、不遺漏或不加添。"},{"en":"Actors need accurate memorisation so they do not forget their lines on stage.","zh":"演員需要準確背誦，才不會在舞台上忘記台詞。"},{"en":"Accurate memorisation gives performers confidence because they can focus on meaning.","zh":"準確背誦給表演者信心，因為他們可以專注於意思。"},{"en":"The Poetry Festival required accurate memorisation before the writer could perform freely.","zh":"詩歌節要求準確背誦，作者才能自由地表演。"}],"source":"2014 Q8.pdf","sourcePage":4},{"front":"on closer inspection","meaning":"仔細看來","examples":[{"en":"On closer inspection, every pause carried meaning.","zh":"仔細看來，每個停頓都承載意思。"},{"en":"On closer inspection means after looking at something more carefully.","zh":"仔細看來，意思是在更仔細觀察某事之後。"},{"en":"On closer inspection, the simple painting showed many hidden details.","zh":"仔細看來，那幅簡單畫作顯示許多隱藏細節。"},{"en":"Careful inspection can change how people understand a text or problem.","zh":"仔細觀察可以改變人們對文本或問題的理解。"},{"en":"On closer inspection, the poem was not just simple words but careful movement.","zh":"仔細看來，這首詩不只是簡單文字，而是細緻的推進。"}],"source":"2014 Q8.pdf","sourcePage":4},{"front":"every pause, stress and image","meaning":"每個停頓、重音和意象","examples":[{"en":"Every pause, stress and image carried meaning.","zh":"每個停頓、重音和意象都承載意思。"},{"en":"Every pause, stress and image means each silence, emphasized word, and picture created by language.","zh":"每個停頓、重音和意象，是指每一段沉默、被強調的字詞，以及語言創造的畫面。"},{"en":"In a poem, a pause can show doubt, stress can show importance, and an image can show feeling.","zh":"在詩中，停頓可以顯示猶豫，重音可以顯示重要，意象可以顯示感情。"},{"en":"These details guide the listener through the speaker’s thoughts.","zh":"這些細節引導聽眾走進說話者的思想。"},{"en":"The writer learned that every pause, stress and image had to be performed with purpose.","zh":"作者學會每個停頓、重音和意象都必須有目的地表演。"}],"source":"2014 Q8.pdf","sourcePage":4},{"front":"carry meaning","meaning":"承載意思","examples":[{"en":"Every pause in the poem carried meaning.","zh":"詩中的每個停頓都承載意思。"},{"en":"To carry meaning means to contain or communicate an idea, feeling, or message.","zh":"承載意思，意思是包含或傳達想法、感情或訊息。"},{"en":"A smile can carry meaning when words are not enough.","zh":"當文字不足夠時，一個微笑可以承載意思。"},{"en":"In poetry, small choices carry meaning because they shape how listeners feel.","zh":"在詩歌中，小選擇承載意思，因為它們塑造聽眾的感受。"},{"en":"The pauses carried meaning because they showed the speaker’s hesitation and change.","zh":"停頓承載意思，因為它們顯示說話者的猶豫和轉變。"}],"source":"2014 Q8.pdf","sourcePage":4},{"front":"Who is speaking?","meaning":"誰在說話？","examples":[{"en":"Miss Chan asked me who was speaking in the poem.","zh":"Chan 老師問我詩中是誰在說話。"},{"en":"“Who is speaking?” asks us to identify the voice or speaker inside a poem.","zh":"「誰在說話？」要求我們辨認詩中的聲音或說話者。"},{"en":"In a story, asking who is speaking helps readers understand the point of view.","zh":"在故事中，問誰在說話能幫助讀者理解視角。"},{"en":"If we do not know who is speaking, we may perform the emotion wrongly.","zh":"如果不知道誰在說話，我們可能會錯誤演繹情感。"},{"en":"This question helped the writer see the poem as a living voice, not just printed words.","zh":"這個問題幫助作者把詩看成有生命力的聲音，而不只是印刷文字。"}],"source":"2014 Q8.pdf","sourcePage":4},{"front":"To whom?","meaning":"對誰說？","examples":[{"en":"Miss Chan asked me to whom the speaker was speaking.","zh":"Chan 老師問我說話者是在對誰說話。"},{"en":"To whom? asks who the listener or receiver of the words is.","zh":"對誰說，意思是問文字的聽者或接收者是誰。"},{"en":"A letter sounds different depending on to whom it is written.","zh":"一封信的語氣會因寫給誰而不同。"},{"en":"Knowing to whom a poem is spoken helps performers choose tone and emotion.","zh":"知道一首詩是對誰說，可以幫助表演者選擇語氣和情感。"},{"en":"The writer had to decide whether the speaker was talking to a friend, a stranger, or themselves.","zh":"作者必須判斷說話者是在對朋友、陌生人，還是自己說話。"}],"source":"2014 Q8.pdf","sourcePage":4},{"front":"from the first line to the last","meaning":"從第一行到最後一行","examples":[{"en":"She asked what changes from the first line to the last.","zh":"她問從第一行到最後一行有甚麼改變。"},{"en":"From the first line to the last means across the whole poem, from beginning to end.","zh":"從第一行到最後一行，意思是貫穿整首詩，由開始到結尾。"},{"en":"A character may change from the first page to the last in a novel.","zh":"在小說中，人物可能從第一頁到最後一頁都有改變。"},{"en":"Looking from the first line to the last helps readers see development.","zh":"從第一行看到最後一行，幫助讀者看見發展。"},{"en":"The writer studied how the poem’s voice changed from the first line to the last.","zh":"作者研究詩中的聲音如何從第一行到最後一行改變。"}],"source":"2014 Q8.pdf","sourcePage":4},{"front":"only after…did I realise","meaning":"直到……之後我才明白","examples":[{"en":"Only after answering the questions did I realise what reciting meant.","zh":"直到回答這些問題之後，我才明白朗誦的意思。"},{"en":"Only after…did I realise means I understood something only when a later action had happened.","zh":"直到……之後我才明白，意思是只有在後來某個行動發生後，我才理解某事。"},{"en":"Only after failing the test did I realise that memorising alone was not enough.","zh":"直到測驗失敗後，我才明白單靠背誦並不足夠。"},{"en":"This structure stresses that understanding came later, not at the beginning.","zh":"這個結構強調理解是後來才出現，而不是一開始就有。"},{"en":"Only after analysing the poem did the writer realise that reciting meant interpretation.","zh":"直到分析詩歌後，作者才明白朗誦意味着演繹。"}],"source":"2014 Q8.pdf","sourcePage":4},{"front":"reciting a poem","meaning":"朗誦一首詩","examples":[{"en":"Reciting a poem is not just reading words aloud.","zh":"朗誦一首詩不只是大聲讀文字。"},{"en":"Reciting a poem means speaking a poem from memory or prepared text with expression and understanding.","zh":"朗誦一首詩，意思是以表情和理解，從記憶或準備好的文本中說出詩歌。"},{"en":"A student reciting a poem must think about rhythm, pauses, and meaning.","zh":"朗誦一首詩的學生必須思考節奏、停頓和意思。"},{"en":"Reciting a poem badly can make strong words sound flat.","zh":"朗誦一首詩不佳，會令有力的文字聽起來平淡。"},{"en":"Reciting a poem well brings the printed page closer to the audience.","zh":"好好朗誦一首詩，可以把印刷頁面帶近聽眾。"}],"source":"2014 Q8.pdf","sourcePage":4},{"front":"not about decorating words with emotion","meaning":"不是用情感裝飾文字","examples":[{"en":"Reciting is not about decorating words with emotion.","zh":"朗誦不是用情感裝飾文字。"},{"en":"Not about decorating words with emotion means performance should not add fake feeling just to sound dramatic.","zh":"不是用情感裝飾文字，意思是表演不應為了戲劇效果而加入虛假的感情。"},{"en":"A speaker should not cry loudly if the text only needs quiet sadness.","zh":"如果文本只需要安靜的悲傷，講者不應大聲哭喊。"},{"en":"Forced emotion can distract listeners from the real meaning of the words.","zh":"勉強加入的情感會分散聽眾對真正意思的注意。"},{"en":"The writer learned that emotion must come from understanding, not decoration.","zh":"作者學會情感必須來自理解，而不是裝飾。"}],"source":"2014 Q8.pdf","sourcePage":4},{"front":"understand why the emotion is there","meaning":"明白情感為何存在","examples":[{"en":"A performer must understand why the emotion is there.","zh":"表演者必須明白情感為何存在。"},{"en":"To understand why the emotion is there means to know what causes the feeling in the text.","zh":"明白情感為何存在，意思是知道文本中的感受由甚麼造成。"},{"en":"An actor must understand why a character is angry before raising their voice.","zh":"演員在提高聲線前，必須明白角色為何憤怒。"},{"en":"If performers do not understand the emotion, their delivery may sound false.","zh":"如果表演者不明白情感，表達可能聽起來不真實。"},{"en":"The writer studied the poem so the emotion would feel honest.","zh":"作者研究詩歌，讓情感感覺真誠。"}],"source":"2014 Q8.pdf","sourcePage":5},{"front":"annotate the poem line by line","meaning":"逐行註釋詩歌","examples":[{"en":"I annotated the poem line by line.","zh":"我逐行註釋詩歌。"},{"en":"To annotate the poem line by line means to write notes on each line to understand meaning and performance choices.","zh":"逐行註釋詩歌，意思是在每一行寫下筆記，以理解意思和表演選擇。"},{"en":"A student may annotate a poem line by line before a literature test.","zh":"學生可能在文學測驗前逐行註釋詩歌。"},{"en":"Line-by-line annotation helps performers notice details they might miss.","zh":"逐行註釋幫助表演者注意可能錯過的細節。"},{"en":"The writer annotated the poem line by line to plan pauses, stress, and tone.","zh":"作者逐行註釋詩歌，以計劃停頓、重音和語氣。"}],"source":"2014 Q8.pdf","sourcePage":5},{"front":"underline key verbs","meaning":"在關鍵動詞下劃線","examples":[{"en":"I underlined key verbs in the poem.","zh":"我在詩中的關鍵動詞下劃線。"},{"en":"To underline key verbs means to mark important action words so they stand out.","zh":"在關鍵動詞下劃線，意思是標記重要的動作詞，讓它們突出。"},{"en":"A student may underline key verbs in exam questions, such as “compare” or “explain.”","zh":"學生可能在試題中的關鍵動詞下劃線，例如「比較」或「解釋」。"},{"en":"Key verbs often reveal movement, feeling, or change in a poem.","zh":"關鍵動詞常揭示詩中的動作、感受或改變。"},{"en":"The writer underlined key verbs to know which actions needed emphasis.","zh":"作者在關鍵動詞下劃線，以知道哪些動作需要強調。"}],"source":"2014 Q8.pdf","sourcePage":5},{"front":"circle turning points","meaning":"圈出轉折點","examples":[{"en":"I circled turning points in the poem.","zh":"我圈出詩中的轉折點。"},{"en":"To circle turning points means to mark places where the meaning, feeling, or direction changes.","zh":"圈出轉折點，意思是標記意思、感情或方向改變的位置。"},{"en":"A reader may circle a turning point when a character suddenly changes their mind.","zh":"當角色突然改變想法，讀者可能圈出轉折點。"},{"en":"Turning points help performers shift tone at the right moment.","zh":"轉折點幫助表演者在正確時刻轉換語氣。"},{"en":"The writer circled turning points so the recitation would not sound the same throughout.","zh":"作者圈出轉折點，使朗誦不會由頭到尾聽起來一樣。"}],"source":"2014 Q8.pdf","sourcePage":5},{"front":"mark where","meaning":"標記哪裏","examples":[{"en":"I marked where the voice should rise or fall.","zh":"我標記聲音應在哪裏提高或降低。"},{"en":"Mark where means note the exact place something should happen.","zh":"標記哪裏，意思是記下某事應發生的確切位置。"},{"en":"A music student may mark where to breathe in a song.","zh":"音樂學生可能標記哪裏需要換氣。"},{"en":"Marking where changes happen helps performers remember technical choices.","zh":"標記改變在哪裏發生，幫助表演者記住技巧選擇。"},{"en":"The writer marked where the voice should change so the poem would sound natural.","zh":"作者標記聲音應在哪裏改變，好讓詩聽起來自然。"}],"source":"2014 Q8.pdf","sourcePage":5},{"front":"soften, rise or fall","meaning":"放柔、提高或降低","examples":[{"en":"I marked where the voice should soften, rise or fall.","zh":"我標記聲音應在哪裏放柔、提高或降低。"},{"en":"Soften, rise or fall means become gentler, go higher, or go lower in sound.","zh":"放柔、提高或降低，意思是聲音變得較溫和、變高或變低。"},{"en":"A storyteller may soften the voice for a sad scene and raise it for surprise.","zh":"說故事的人可能在悲傷場景放柔聲音，在驚訝時提高聲音。"},{"en":"Voice changes guide listeners through emotion and meaning.","zh":"聲音變化引導聽眾理解情感和意思。"},{"en":"The writer planned where to soften, rise or fall so the poem would have shape.","zh":"作者計劃在哪裏放柔、提高或降低聲音，使詩有層次。"}],"source":"2014 Q8.pdf","sourcePage":5},{"front":"sound confident","meaning":"聽起來自信","examples":[{"en":"One stanza sounded confident.","zh":"其中一節聽起來自信。"},{"en":"To sound confident means to seem sure, steady, and unafraid in voice.","zh":"聽起來自信，意思是聲音顯得肯定、穩定和不害怕。"},{"en":"A student sounds confident when they answer clearly without rushing.","zh":"學生清楚回答而不急促時，就聽起來自信。"},{"en":"A confident sound can make listeners trust the speaker’s understanding.","zh":"自信的聲音可以令聽眾相信講者的理解。"},{"en":"The writer noticed one stanza needed to sound confident because the speaker felt sure.","zh":"作者注意到其中一節需要聽起來自信，因為說話者感到肯定。"}],"source":"2014 Q8.pdf","sourcePage":5},{"front":"sound uncertain","meaning":"聽起來不確定","examples":[{"en":"Another stanza sounded uncertain.","zh":"另一節聽起來不確定。"},{"en":"To sound uncertain means to seem unsure, hesitant, or doubtful in voice.","zh":"聽起來不確定，意思是聲音顯得不肯定、猶豫或懷疑。"},{"en":"A student sounds uncertain when they answer with many pauses and a soft voice.","zh":"學生回答時有很多停頓和聲音很輕，就聽起來不確定。"},{"en":"Uncertain tone can show fear, confusion, or inner conflict.","zh":"不確定的語氣可以顯示恐懼、困惑或內心衝突。"},{"en":"The writer made one stanza sound uncertain because the poem’s speaker was unsure.","zh":"作者令其中一節聽起來不確定，因為詩中的說話者感到不肯定。"}],"source":"2014 Q8.pdf","sourcePage":5},{"front":"quiet but firm","meaning":"平靜但堅定","examples":[{"en":"The ending sounded quiet but firm.","zh":"結尾聽起來平靜但堅定。"},{"en":"Quiet but firm means gentle in volume but strong in belief or decision.","zh":"平靜但堅定，意思是音量溫和，但信念或決定很強。"},{"en":"A teacher may speak quietly but firmly when stopping unfair behaviour.","zh":"老師阻止不公平行為時，可能平靜但堅定地說話。"},{"en":"Quiet firmness can be more powerful than shouting.","zh":"平靜的堅定可以比大叫更有力量。"},{"en":"The poem’s ending sounded quiet but firm because the speaker had found inner strength.","zh":"詩的結尾聽起來平靜但堅定，因為說話者找到了內在力量。"}],"source":"2014 Q8.pdf","sourcePage":5},{"front":"slowly but surely","meaning":"慢慢而穩定地","examples":[{"en":"Slowly but surely, the printed page became a living voice.","zh":"慢慢而穩定地，印刷頁面變成有生命力的聲音。"},{"en":"Slowly but surely means gradually but with steady progress.","zh":"慢慢而穩定地，意思是逐漸但持續地進步。"},{"en":"Slowly but surely, a shy student can become comfortable speaking in front of others.","zh":"慢慢而穩定地，害羞學生可以變得習慣在人前說話。"},{"en":"This phrase shows improvement that is not sudden but dependable.","zh":"這個短語顯示進步不是突然的，但可靠。"},{"en":"The writer’s performance improved slowly but surely through daily practice.","zh":"作者的表演透過每天練習慢慢而穩定地進步。"}],"source":"2014 Q8.pdf","sourcePage":5},{"front":"take shape as","meaning":"逐漸形成為","examples":[{"en":"The poem began to take shape as a living voice.","zh":"這首詩開始逐漸形成為有生命力的聲音。"},{"en":"To take shape as something means to gradually become clear in that form.","zh":"逐漸形成為某物，意思是慢慢以那種形式變得清晰。"},{"en":"A school project begins to take shape as a real exhibition when students arrange the displays.","zh":"當學生安排展品，學校專題開始逐漸形成為真正展覽。"},{"en":"Ideas take shape when people plan, test, and improve them.","zh":"當人們計劃、測試和改善，想法就會逐漸成形。"},{"en":"The poem took shape as a performance after the writer understood its voice.","zh":"作者理解詩中的聲音後，這首詩逐漸形成為一場表演。"}],"source":"2014 Q8.pdf","sourcePage":6},{"front":"a living voice","meaning":"有生命力的聲音","examples":[{"en":"A printed page began to take shape as a living voice.","zh":"印刷頁面開始逐漸形成為有生命力的聲音。"},{"en":"A living voice means spoken words that feel active, human, and full of meaning.","zh":"有生命力的聲音，是感覺活躍、有人情味並充滿意思的說話。"},{"en":"A story becomes a living voice when a grandparent tells it with feeling.","zh":"當祖父母有感情地講故事，故事就變成有生命力的聲音。"},{"en":"A living voice can make written language feel close to listeners.","zh":"有生命力的聲音可以令書面語言感覺貼近聽眾。"},{"en":"Through recitation, the poem changed from silent text into a living voice.","zh":"透過朗誦，詩由沉默文本變成有生命力的聲音。"}],"source":"2014 Q8.pdf","sourcePage":6},{"front":"technical training","meaning":"技術訓練","examples":[{"en":"The technical training was just as demanding.","zh":"技術訓練同樣要求很高。"},{"en":"Technical training means practice focused on skills such as breathing, pronunciation, pace, and voice control.","zh":"技術訓練，是集中於呼吸、發音、速度和聲線控制等技巧的練習。"},{"en":"Singers need technical training before they can perform safely and clearly.","zh":"歌手需要技術訓練，才能安全而清晰地表演。"},{"en":"Without technical training, strong emotion may still sound messy.","zh":"沒有技術訓練，強烈情感仍可能聽起來混亂。"},{"en":"The writer’s technical training helped the poem become clearer and more controlled.","zh":"作者的技術訓練幫助詩變得更清晰和更受控制。"}],"source":"2014 Q8.pdf","sourcePage":6},{"front":"just as demanding","meaning":"同樣要求很高","examples":[{"en":"The technical training was just as demanding as the interpretation.","zh":"技術訓練和演繹同樣要求很高。"},{"en":"Just as demanding means equally difficult and requiring equal effort.","zh":"同樣要求很高，意思是同樣困難並需要同樣努力。"},{"en":"Writing the report was hard, and presenting it was just as demanding.","zh":"寫報告很難，而匯報也同樣要求很高。"},{"en":"Something is demanding when it needs time, patience, and repeated practice.","zh":"當某事需要時間、耐性和反覆練習，它就是要求很高。"},{"en":"The writer learned that voice training was just as demanding as understanding the poem.","zh":"作者學會聲線訓練和理解詩歌同樣要求很高。"}],"source":"2014 Q8.pdf","sourcePage":6},{"front":"every afternoon for three weeks","meaning":"連續三星期的每個下午","examples":[{"en":"Every afternoon for three weeks, I practised in an empty classroom.","zh":"連續三星期的每個下午，我都在空課室練習。"},{"en":"Every afternoon for three weeks means each afternoon during a period of three weeks.","zh":"連續三星期的每個下午，意思是在三星期期間每一個下午。"},{"en":"A student may practise piano every afternoon for three weeks before a concert.","zh":"學生可能在音樂會前連續三星期的每個下午練琴。"},{"en":"Repeating practice over many afternoons builds habit and confidence.","zh":"許多下午反覆練習，可以建立習慣和信心。"},{"en":"The writer’s steady practice every afternoon for three weeks showed discipline.","zh":"作者連續三星期每個下午穩定練習，顯示出紀律。"}],"source":"2014 Q8.pdf","sourcePage":6},{"front":"practise in an empty classroom","meaning":"在空課室練習","examples":[{"en":"I practised in an empty classroom after school.","zh":"我放學後在空課室練習。"},{"en":"To practise in an empty classroom means to rehearse in a quiet classroom with no regular lesson happening.","zh":"在空課室練習，意思是在沒有正常課堂進行的安靜課室中排練。"},{"en":"A student may practise a speech in an empty classroom to avoid distractions.","zh":"學生可能在空課室練習演講，以避免分心。"},{"en":"Empty classrooms give performers privacy to make mistakes and improve.","zh":"空課室給表演者私人空間去犯錯和改善。"},{"en":"The writer practised in an empty classroom until the poem felt more natural.","zh":"作者在空課室練習，直到詩感覺更自然。"}],"source":"2014 Q8.pdf","sourcePage":6},{"front":"record myself","meaning":"錄下自己","examples":[{"en":"I used my phone to record myself.","zh":"我用手機錄下自己。"},{"en":"To record myself means to make an audio or video recording of my own performance.","zh":"錄下自己，意思是製作自己表演的聲音或影片記錄。"},{"en":"A student may record themselves reading English to check pronunciation.","zh":"學生可能錄下自己讀英文，以檢查發音。"},{"en":"Recording yourself helps you hear mistakes you did not notice while speaking.","zh":"錄下自己可以幫助你聽見說話時沒有注意到的錯誤。"},{"en":"The writer recorded themselves to improve pace, clarity, and confidence.","zh":"作者錄下自己，以改善速度、清晰度和信心。"}],"source":"2014 Q8.pdf","sourcePage":6},{"front":"imaginary adjudicator","meaning":"想像中的評判","examples":[{"en":"I treated a chair at the back as my imaginary adjudicator.","zh":"我把後方一張椅子當作想像中的評判。"},{"en":"An imaginary adjudicator is a judge you picture in your mind while practising.","zh":"想像中的評判，是練習時在腦海中想像出來的評審。"},{"en":"A student may practise a speech in front of an imaginary adjudicator to feel less nervous later.","zh":"學生可能在想像中的評判面前練習演講，好讓之後不那麼緊張。"},{"en":"Imagining a judge can make practice feel closer to the real competition.","zh":"想像有評判可以令練習更接近真正比賽。"},{"en":"The writer used a chair as an imaginary adjudicator to practise facing pressure.","zh":"作者把椅子當作想像中的評判，以練習面對壓力。"}],"source":"2014 Q8.pdf","sourcePage":6},{"front":"painful to hear","meaning":"聽起來很難受","examples":[{"en":"The first recording was painful to hear.","zh":"第一段錄音聽起來很難受。"},{"en":"Painful to hear means unpleasant or embarrassing to listen to because the performance sounds poor.","zh":"聽起來很難受，意思是因表現不佳而聽起來令人不舒服或尷尬。"},{"en":"My first English recording was painful to hear because I spoke too fast.","zh":"我的第一段英文錄音聽起來很難受，因為我說得太快。"},{"en":"Hearing weaknesses can feel painful, but it helps people improve.","zh":"聽見弱點可能令人難受，但它幫助人改善。"},{"en":"The writer’s first recording was painful to hear, but it showed what needed work.","zh":"作者的第一段錄音聽起來很難受，但顯示需要改善甚麼。"}],"source":"2014 Q8.pdf","sourcePage":6},{"front":"rush through commas","meaning":"匆匆讀過逗號","examples":[{"en":"I rushed through commas in the first recording.","zh":"我在第一段錄音中匆匆讀過逗號。"},{"en":"To rush through commas means to read past punctuation too quickly without pausing properly.","zh":"匆匆讀過逗號，意思是太快讀過標點，沒有適當停頓。"},{"en":"A reader who rushes through commas may make a sentence hard to understand.","zh":"讀者如果匆匆讀過逗號，句子可能變得難以理解。"},{"en":"Commas often show where listeners need a small pause.","zh":"逗號常顯示聽眾需要一個小停頓的位置。"},{"en":"The writer learned not to rush through commas because pauses help meaning.","zh":"作者學會不要匆匆讀過逗號，因為停頓有助意思。"}],"source":"2014 Q8.pdf","sourcePage":6},{"front":"swallow final consonants","meaning":"吞掉字尾輔音","examples":[{"en":"I swallowed final consonants when I read too quickly.","zh":"我讀得太快時吞掉字尾輔音。"},{"en":"To swallow final consonants means to pronounce the ending sounds of words unclearly or not at all.","zh":"吞掉字尾輔音，意思是把字尾聲音讀得不清楚，甚至完全沒有讀出來。"},{"en":"A student may swallow final consonants in words like “worked” or “last.”","zh":"學生可能在 worked 或 last 這類字中吞掉字尾輔音。"},{"en":"Swallowing final consonants makes speech less clear for listeners.","zh":"吞掉字尾輔音會令說話對聽眾來說較不清楚。"},{"en":"The writer slowed down to stop swallowing final consonants during recitation.","zh":"作者放慢速度，以避免在朗誦時吞掉字尾輔音。"}],"source":"2014 Q8.pdf","sourcePage":7},{"front":"stare at the floor","meaning":"盯着地板","examples":[{"en":"I stared at the floor as if the audience were my enemy.","zh":"我盯着地板，彷彿觀眾是我的敵人。"},{"en":"To stare at the floor means to keep looking down instead of facing people.","zh":"盯着地板，意思是一直向下望，而不是面向別人。"},{"en":"A nervous speaker may stare at the floor during a presentation.","zh":"緊張的講者可能在匯報時盯着地板。"},{"en":"Staring at the floor can make the audience feel disconnected from the speaker.","zh":"盯着地板會令觀眾覺得與講者沒有連繫。"},{"en":"The writer had to learn to look up instead of staring at the floor.","zh":"作者必須學會抬頭，而不是盯着地板。"}],"source":"2014 Q8.pdf","sourcePage":7},{"front":"as if the audience were my enemy","meaning":"彷彿觀眾是我的敵人","examples":[{"en":"I stared at the floor as if the audience were my enemy.","zh":"我盯着地板，彷彿觀眾是我的敵人。"},{"en":"As if the audience were my enemy means acting as though listeners are threatening rather than supportive.","zh":"彷彿觀眾是我的敵人，意思是表現得好像聽眾具威脅性，而不是支持者。"},{"en":"A shy speaker may avoid eye contact as if the audience were against them.","zh":"害羞的講者可能避免眼神接觸，彷彿觀眾反對自己。"},{"en":"Seeing the audience as an enemy increases fear and weakens connection.","zh":"把觀眾視為敵人會增加恐懼並削弱連繫。"},{"en":"The writer later learned that the audience should be treated as listeners, not enemies.","zh":"作者後來學會應把觀眾視為聽眾，而不是敵人。"}],"source":"2014 Q8.pdf","sourcePage":7},{"front":"instead of giving up","meaning":"而不是放棄","examples":[{"en":"Instead of giving up, I broke the poem into smaller units.","zh":"而不是放棄，我把詩分成較小部分。"},{"en":"Instead of giving up means choosing to keep trying rather than stop.","zh":"而不是放棄，意思是選擇繼續嘗試，而不是停止。"},{"en":"Instead of giving up after a low mark, a student may ask for feedback.","zh":"學生在低分後可以尋求回饋，而不是放棄。"},{"en":"Difficult tasks become easier when people solve them step by step instead of quitting.","zh":"當人們一步一步解決困難任務，而不是退出，事情會變得較容易。"},{"en":"The writer improved because they chose practice instead of giving up.","zh":"作者進步，是因為選擇練習而不是放棄。"}],"source":"2014 Q8.pdf","sourcePage":7},{"front":"break something into smaller units","meaning":"把……分成較小部分","examples":[{"en":"I broke the poem into smaller units.","zh":"我把詩分成較小部分。"},{"en":"To break something into smaller units means to divide a large task into manageable parts.","zh":"把某事分成較小部分，意思是把大型任務分成可處理的小部分。"},{"en":"A student can break a long chapter into smaller units before revising.","zh":"學生可以在溫習前把長章節分成較小部分。"},{"en":"Smaller units reduce pressure because each part feels easier to handle.","zh":"較小部分可以減少壓力，因為每一部分都較容易處理。"},{"en":"The writer broke the poem into smaller units to practise more carefully.","zh":"作者把詩分成較小部分，以便更仔細地練習。"}],"source":"2014 Q8.pdf","sourcePage":7},{"front":"practise breathing","meaning":"練習呼吸","examples":[{"en":"I practised breathing before long sentences.","zh":"我在長句前練習呼吸。"},{"en":"To practise breathing means to train how and when to breathe while speaking or performing.","zh":"練習呼吸，意思是訓練說話或表演時如何及何時呼吸。"},{"en":"Singers practise breathing so they can finish long phrases smoothly.","zh":"歌手練習呼吸，才能順暢完成長樂句。"},{"en":"Good breathing prevents speakers from rushing or running out of air.","zh":"良好呼吸防止講者急促或氣不夠。"},{"en":"The writer practised breathing to make the poem sound controlled.","zh":"作者練習呼吸，使詩聽起來更受控制。"}],"source":"2014 Q8.pdf","sourcePage":7},{"front":"long sentences","meaning":"長句","examples":[{"en":"I practised breathing before long sentences.","zh":"我在長句前練習呼吸。"},{"en":"Long sentences are sentences with many words, clauses, or ideas.","zh":"長句，是包含許多字、分句或想法的句子。"},{"en":"Students may need to pause carefully when reading long sentences aloud.","zh":"學生大聲朗讀長句時，可能需要小心停頓。"},{"en":"Long sentences can make speakers run out of breath if they do not plan ahead.","zh":"如果講者沒有預先計劃，長句可能令他們氣不夠。"},{"en":"The writer marked breathing points before long sentences in the poem.","zh":"作者在詩中的長句前標記呼吸點。"}],"source":"2014 Q8.pdf","sourcePage":7},{"front":"project vowels without shouting","meaning":"不用大叫也能把元音發清楚","examples":[{"en":"I practised projecting vowels without shouting.","zh":"我練習不用大叫也能把元音發清楚。"},{"en":"To project vowels without shouting means to make vowel sounds clear and strong without raising the voice harshly.","zh":"不用大叫也能把元音發清楚，意思是令元音清晰有力，而不粗暴提高聲線。"},{"en":"A drama student learns to project vowels so people at the back can hear clearly.","zh":"戲劇學生學習發清楚元音，讓後排的人也能聽見。"},{"en":"Shouting may hurt the voice, but good projection carries sound safely.","zh":"大叫可能傷害聲線，但良好發聲能安全地傳送聲音。"},{"en":"The writer practised projection so the poem would sound clear, not loud and rough.","zh":"作者練習發聲，使詩聽起來清晰，而不是又大聲又粗糙。"}],"source":"2014 Q8.pdf","sourcePage":7},{"front":"pause before important words","meaning":"在重要字詞前停頓","examples":[{"en":"I learned to pause before important words.","zh":"我學會在重要字詞前停頓。"},{"en":"To pause before important words means to stop briefly before key words so listeners notice them.","zh":"在重要字詞前停頓，意思是在關鍵字詞前短暫停下，讓聽眾注意它們。"},{"en":"A speaker may pause before the word “never” to make a warning stronger.","zh":"講者可能在 never 這個字前停頓，使警告更有力。"},{"en":"Pauses can guide attention more effectively than simply speaking louder.","zh":"停頓可以比單純提高聲量更有效地引導注意力。"},{"en":"The writer paused before important words to give the poem weight.","zh":"作者在重要字詞前停頓，讓詩更有分量。"}],"source":"2014 Q8.pdf","sourcePage":7},{"front":"rather than after every line","meaning":"而不是每行之後","examples":[{"en":"I paused before important words rather than after every line.","zh":"我在重要字詞前停頓，而不是每行之後都停頓。"},{"en":"Rather than after every line means instead of stopping automatically at the end of each line.","zh":"而不是每行之後，意思是不要在每行結尾機械式地停下。"},{"en":"In poetry, performers should follow meaning rather than pause mechanically after every line.","zh":"在詩歌中，表演者應跟隨意思，而不是每行之後機械式停頓。"},{"en":"Pausing in the wrong place can break the thought of a sentence.","zh":"在錯誤位置停頓會打斷句子的思想。"},{"en":"The writer learned to pause for meaning rather than for line endings only.","zh":"作者學會為意思而停頓，而不是只為行尾停頓。"}],"source":"2014 Q8.pdf","sourcePage":7},{"front":"better still","meaning":"更好的是","examples":[{"en":"Better still, my classmates became a mock audience.","zh":"更好的是，我的同學成為模擬觀眾。"},{"en":"Better still is used to add an even better or more helpful point.","zh":"更好的是，用來加入一個更好或更有幫助的重點。"},{"en":"The library was quiet; better still, a teacher was there to help.","zh":"圖書館很安靜；更好的是，有老師在那裏幫忙。"},{"en":"Writers use better still when the next point improves the situation further.","zh":"作者使用「更好的是」，是因為下一點令情況更加改善。"},{"en":"Better still, practising with classmates made the performance feel more realistic.","zh":"更好的是，與同學練習令表演感覺更接近現實。"}],"source":"2014 Q8.pdf","sourcePage":8},{"front":"a mock audience","meaning":"模擬觀眾","examples":[{"en":"My classmates became a mock audience during practice.","zh":"練習時，我的同學成為模擬觀眾。"},{"en":"A mock audience is a practice audience that helps someone prepare for a real performance.","zh":"模擬觀眾，是幫助某人準備真正表演的練習觀眾。"},{"en":"Students may present to a mock audience before the actual speech contest.","zh":"學生可能在正式演講比賽前向模擬觀眾匯報。"},{"en":"A mock audience helps performers notice nerves, gestures, and pacing.","zh":"模擬觀眾幫助表演者注意緊張、手勢和速度。"},{"en":"The writer’s classmates acted as a mock audience and gave useful comments.","zh":"作者的同學充當模擬觀眾，並給予有用意見。"}],"source":"2014 Q8.pdf","sourcePage":8},{"front":"note that","meaning":"指出","examples":[{"en":"They noted that my hands moved too much.","zh":"他們指出我的手動得太多。"},{"en":"To note that means to notice and point out a fact or detail.","zh":"指出，意思是注意到並說出一個事實或細節。"},{"en":"A teacher may note that a student speaks too softly during practice.","zh":"老師可能指出學生練習時說話太小聲。"},{"en":"Noting small details helps performers improve what they cannot see themselves.","zh":"指出小細節，能幫助表演者改善自己看不見的問題。"},{"en":"The classmates noted that the writer’s gestures distracted from the poem.","zh":"同學指出作者的手勢分散了聽眾對詩的注意。"}],"source":"2014 Q8.pdf","sourcePage":8},{"front":"move too much","meaning":"動得太多","examples":[{"en":"My classmates said my hands moved too much.","zh":"同學說我的手動得太多。"},{"en":"Move too much means make too many physical movements, often in a distracting way.","zh":"動得太多，意思是身體動作太多，通常會令人分心。"},{"en":"A speaker’s hands move too much when gestures do not match the message.","zh":"當手勢與訊息不配合，講者的手就會動得太多。"},{"en":"Moving too much can make an audience watch the body instead of listening to the words.","zh":"動得太多會令觀眾看着身體，而不是聆聽文字。"},{"en":"The writer learned to control their hands so the poem stayed central.","zh":"作者學會控制雙手，讓詩保持在中心位置。"}],"source":"2014 Q8.pdf","sourcePage":8},{"front":"pace was uneven","meaning":"速度不均","examples":[{"en":"They noticed that my pace was uneven.","zh":"他們注意到我的速度不均。"},{"en":"Pace was uneven means the speed was not steady, sometimes too fast and sometimes too slow.","zh":"速度不均，意思是速度不穩定，有時太快，有時太慢。"},{"en":"A presentation sounds uneven when the speaker rushes some parts and drags others.","zh":"如果講者有些部分急促、有些部分拖慢，匯報就會聽起來速度不均。"},{"en":"Uneven pace can confuse listeners because the rhythm keeps changing without reason.","zh":"速度不均會令聽眾困惑，因為節奏無故不斷改變。"},{"en":"The writer worked on pace so the poem would flow more naturally.","zh":"作者改善速度，好讓詩更自然地流動。"}],"source":"2014 Q8.pdf","sourcePage":8},{"front":"sound forced","meaning":"聽起來不自然；像硬擠出來","examples":[{"en":"One emotional line sounded forced.","zh":"其中一句有情感的詩句聽起來不自然。"},{"en":"Sound forced means seem unnatural because the feeling is pushed too hard.","zh":"聽起來不自然或像硬擠出來，意思是因感情被用力推得太過而顯得不自然。"},{"en":"An apology sounds forced if the speaker says it without real regret.","zh":"如果講者沒有真正後悔，道歉會聽起來不自然。"},{"en":"Forced emotion can make listeners trust a performance less.","zh":"勉強的情感會令聽眾較不相信表演。"},{"en":"The writer changed the emotional line so it sounded honest instead of forced.","zh":"作者修改那句有情感的詩句，讓它聽起來真誠而不是硬擠出來。"}],"source":"2014 Q8.pdf","sourcePage":8},{"front":"much as","meaning":"儘管","examples":[{"en":"Much as their comments embarrassed me, they improved my performance.","zh":"儘管他們的評語令我尷尬，它們改善了我的表演。"},{"en":"Much as means although, especially when admitting something difficult.","zh":"儘管，意思是雖然，特別是承認某件困難事情時使用。"},{"en":"Much as I dislike early mornings, morning practice helps me focus.","zh":"儘管我不喜歡早起，早上練習能幫助我專注。"},{"en":"This phrase shows that two ideas are both true but pull in different directions.","zh":"這個短語顯示兩個想法都真實，但方向不同。"},{"en":"Much as the feedback embarrassed the writer, it helped the recitation become better.","zh":"儘管回饋令作者尷尬，它幫助朗誦變得更好。"}],"source":"2014 Q8.pdf","sourcePage":8},{"front":"embarrass me","meaning":"令我尷尬","examples":[{"en":"Their comments embarrassed me at first.","zh":"他們的評語起初令我尷尬。"},{"en":"Embarrass me means make me feel shy, awkward, or ashamed.","zh":"令我尷尬，意思是令我感到害羞、不自在或難堪。"},{"en":"A student may feel embarrassed when classmates point out a mistake.","zh":"當同學指出錯誤，學生可能感到尷尬。"},{"en":"Feedback can embarrass people, but it can also help them improve.","zh":"回饋可以令人尷尬，但也可以幫助人改善。"},{"en":"The comments embarrassed the writer because they revealed weaknesses clearly.","zh":"這些評語令作者尷尬，因為它們清楚揭示弱點。"}],"source":"2014 Q8.pdf","sourcePage":8},{"front":"make the performance more honest","meaning":"令表演更真誠","examples":[{"en":"Their comments made the performance more honest.","zh":"他們的評語令表演更真誠。"},{"en":"To make the performance more honest means to help it sound more natural, truthful, and connected to meaning.","zh":"令表演更真誠，意思是幫助表演聽起來更自然、真實，並與意思連繫。"},{"en":"A teacher’s feedback can make a speech more honest by removing fake emotion.","zh":"老師的回饋可以透過移除虛假情感，令演講更真誠。"},{"en":"Honest performance grows when performers stop showing off and start understanding.","zh":"當表演者停止炫耀並開始理解，真誠表演就會增長。"},{"en":"The classmates’ comments made the poem feel less forced and more real.","zh":"同學的評語令詩感覺較少勉強，變得更真實。"}],"source":"2014 Q8.pdf","sourcePage":8},{"front":"on the day of the competition","meaning":"比賽當日","examples":[{"en":"On the day of the competition, the atmosphere was unforgettable.","zh":"比賽當日，氣氛令人難忘。"},{"en":"On the day of the competition means during the actual day when the contest happened.","zh":"比賽當日，意思是比賽真正舉行的那一天。"},{"en":"On the day of the competition, students arrived early to warm up.","zh":"比賽當日，學生提早到達熱身。"},{"en":"The real day feels different because practice becomes performance.","zh":"真正比賽那天感覺不同，因為練習變成表演。"},{"en":"On the day of the competition, the writer finally faced the stage.","zh":"比賽當日，作者終於面對舞台。"}],"source":"2014 Q8.pdf","sourcePage":8},{"front":"atmosphere was unforgettable","meaning":"氣氛令人難忘","examples":[{"en":"The atmosphere backstage was unforgettable.","zh":"後台氣氛令人難忘。"},{"en":"Atmosphere was unforgettable means the mood of the place was so strong that it stayed in memory.","zh":"氣氛令人難忘，意思是那個地方的情緒很強烈，令人記在心中。"},{"en":"The atmosphere at the graduation ceremony was unforgettable because everyone felt proud and emotional.","zh":"畢業典禮氣氛令人難忘，因為每個人都感到自豪和感動。"},{"en":"A strong atmosphere can make an ordinary place feel important.","zh":"強烈氣氛可以令普通地方感覺重要。"},{"en":"Backstage, the nervous voices and silence made the atmosphere unforgettable.","zh":"在後台，緊張的聲音和沉默令氣氛令人難忘。"}],"source":"2014 Q8.pdf","sourcePage":9},{"front":"standing backstage","meaning":"站在後台","examples":[{"en":"Standing backstage, I could hear many different voices.","zh":"站在後台，我聽見許多不同聲音。"},{"en":"Standing backstage means waiting in the area behind or near the stage before performing.","zh":"站在後台，意思是在表演前等候於舞台後方或附近的區域。"},{"en":"Actors standing backstage may hear music, footsteps, and whispers.","zh":"演員站在後台時，可能聽到音樂、腳步聲和低語。"},{"en":"Backstage waiting can make performers feel both nervous and excited.","zh":"後台等候可以令表演者既緊張又興奮。"},{"en":"Standing backstage helped the writer realise that many students shared the same fear.","zh":"站在後台幫助作者意識到很多學生都有同樣恐懼。"}],"source":"2014 Q8.pdf","sourcePage":9},{"front":"among students from different schools","meaning":"在來自不同學校的學生之中","examples":[{"en":"I stood backstage among students from different schools.","zh":"我站在後台，在來自不同學校的學生之中。"},{"en":"Among students from different schools means surrounded by students who came from other schools.","zh":"在來自不同學校的學生之中，意思是被其他學校的學生圍繞。"},{"en":"A debate finalist may wait among students from different schools before entering the hall.","zh":"辯論決賽選手可能在進入禮堂前，等候在來自不同學校的學生之中。"},{"en":"Being among unfamiliar students can make a competition feel larger and more serious.","zh":"身處不熟悉的學生之中，會令比賽感覺更大型和嚴肅。"},{"en":"The writer felt the scale of the Festival while standing among students from different schools.","zh":"作者站在來自不同學校的學生之中時，感受到詩歌節的規模。"}],"source":"2014 Q8.pdf","sourcePage":9},{"front":"all sorts of voices","meaning":"各種各樣的聲音","examples":[{"en":"I could hear all sorts of voices backstage.","zh":"我在後台聽到各種各樣的聲音。"},{"en":"All sorts of voices means many different kinds of voices.","zh":"各種各樣的聲音，意思是許多不同種類的聲音。"},{"en":"In a busy classroom, you may hear all sorts of voices asking, laughing, and reading.","zh":"在繁忙課室中，你可能聽到各種各樣的聲音，有人提問、有人笑、有人朗讀。"},{"en":"Hearing many voices backstage shows that everyone prepares differently.","zh":"在後台聽到許多聲音，顯示每個人準備方式不同。"},{"en":"The Festival gathered all sorts of voices, from nervous whispers to confident recitation.","zh":"詩歌節聚集各種各樣的聲音，從緊張低語到自信朗誦都有。"}],"source":"2014 Q8.pdf","sourcePage":9},{"front":"nervous whispers","meaning":"緊張的低語","examples":[{"en":"I heard nervous whispers backstage.","zh":"我在後台聽到緊張的低語。"},{"en":"Nervous whispers are quiet voices used by people who feel anxious.","zh":"緊張的低語，是感到焦慮的人使用的細小聲音。"},{"en":"Before an exam, nervous whispers may fill the corridor.","zh":"考試前，走廊可能充滿緊張的低語。"},{"en":"People whisper nervously when they want to speak but do not want to draw attention.","zh":"當人們想說話但不想引起注意，就會緊張地低語。"},{"en":"The nervous whispers backstage showed that many performers were afraid too.","zh":"後台緊張的低語顯示許多表演者也害怕。"}],"source":"2014 Q8.pdf","sourcePage":9},{"front":"repeated lines","meaning":"反覆背誦的句子","examples":[{"en":"I heard students practising repeated lines.","zh":"我聽到學生練習反覆背誦的句子。"},{"en":"Repeated lines are words or sentences spoken again and again for practice or emphasis.","zh":"反覆背誦的句子，是為練習或強調而一遍又一遍說出的文字或句子。"},{"en":"Actors practise repeated lines when they are trying to memorise a scene.","zh":"演員嘗試記住場景時，會練習反覆背誦的句子。"},{"en":"Repeating lines helps performers feel more secure before going on stage.","zh":"反覆背誦句子幫助表演者上台前感到更穩妥。"},{"en":"The repeated lines backstage showed how hard students had prepared.","zh":"後台反覆背誦的句子顯示學生準備得很努力。"}],"source":"2014 Q8.pdf","sourcePage":9},{"front":"sudden laughter","meaning":"突然的笑聲","examples":[{"en":"There was sudden laughter among the nervous students.","zh":"緊張的學生之間突然響起笑聲。"},{"en":"Sudden laughter is laughter that begins unexpectedly.","zh":"突然的笑聲，是出乎意料地開始的笑聲。"},{"en":"Sudden laughter may break the tension before a performance.","zh":"表演前，突然的笑聲可能打破緊張氣氛。"},{"en":"People sometimes laugh suddenly when nerves become too strong.","zh":"當緊張太強，人們有時會突然笑出來。"},{"en":"The sudden laughter backstage made the nervous atmosphere feel briefly lighter.","zh":"後台突然的笑聲令緊張氣氛短暫變得輕鬆。"}],"source":"2014 Q8.pdf","sourcePage":9},{"front":"complete silence","meaning":"一片沉默","examples":[{"en":"Some students waited in complete silence.","zh":"有些學生在一片沉默中等待。"},{"en":"Complete silence means total quiet, with no talking or noticeable sound.","zh":"一片沉默，意思是完全安靜，沒有說話或明顯聲音。"},{"en":"The library fell into complete silence before the exam began.","zh":"考試開始前，圖書館陷入一片沉默。"},{"en":"Some people choose complete silence when they need to focus or control nerves.","zh":"有些人在需要專注或控制緊張時，會選擇一片沉默。"},{"en":"Backstage, complete silence showed another way students handled fear.","zh":"在後台，一片沉默顯示學生處理恐懼的另一種方式。"}],"source":"2014 Q8.pdf","sourcePage":9},{"front":"no sooner had…than…","meaning":"一……就……","examples":[{"en":"No sooner had my number been called than my heartbeat filled the room.","zh":"我的號碼一被叫到，我的心跳聲彷彿就充滿整個房間。"},{"en":"No sooner had…than… means one thing happened immediately after another.","zh":"一……就……，意思是一件事緊接另一件事發生。"},{"en":"No sooner had the bell rung than students rushed out of the classroom.","zh":"鐘聲一響，學生就衝出課室。"},{"en":"This structure makes events feel sudden and dramatic.","zh":"這個結構令事件感覺突然和戲劇化。"},{"en":"The writer uses it to show how quickly fear arrived when their number was called.","zh":"作者使用它來顯示號碼被叫到時，恐懼多快出現。"}],"source":"2014 Q8.pdf","sourcePage":9},{"front":"my number had been called","meaning":"我的號碼被叫到","examples":[{"en":"My number had been called, and I walked towards the stage.","zh":"我的號碼被叫到，然後我走向舞台。"},{"en":"My number had been called means the competition organisers announced my turn.","zh":"我的號碼被叫到，意思是比賽主辦方宣布輪到我。"},{"en":"When a contestant’s number is called, they must be ready to perform.","zh":"當參賽者的號碼被叫到，他們就必須準備表演。"},{"en":"Hearing your number called can make practice suddenly feel real.","zh":"聽到自己的號碼被叫到，會令練習突然變得真實。"},{"en":"The writer walked towards the stage after their number had been called.","zh":"作者的號碼被叫到後，便走向舞台。"}],"source":"2014 Q8.pdf","sourcePage":9},{"front":"heartbeat seemed to fill the room","meaning":"心跳聲彷彿充滿整個房間","examples":[{"en":"My heartbeat seemed to fill the room.","zh":"我的心跳聲彷彿充滿整個房間。"},{"en":"Heartbeat seemed to fill the room means the speaker felt so nervous that their heartbeat seemed extremely loud.","zh":"心跳聲彷彿充滿整個房間，意思是講者非常緊張，覺得自己的心跳聲極大。"},{"en":"Before a speech, a student may feel their heartbeat fill the room.","zh":"演講前，學生可能覺得自己的心跳聲充滿整個房間。"},{"en":"Strong nerves can make small body sounds feel huge.","zh":"強烈緊張會令細小身體聲音感覺巨大。"},{"en":"The writer’s heartbeat seemed to fill the room because the stage felt frightening.","zh":"作者的心跳聲彷彿充滿整個房間，因為舞台感覺可怕。"}],"source":"2014 Q8.pdf","sourcePage":10},{"front":"for what felt like forever","meaning":"感覺像很久的一段時間","examples":[{"en":"For what felt like forever, the microphone looked frightening.","zh":"有一段感覺像很久的時間，咪高峰看起來很可怕。"},{"en":"For what felt like forever means for a short time that felt very long because of emotion or pressure.","zh":"感覺像很久的一段時間，意思是實際時間可能很短，但因情緒或壓力而感覺很長。"},{"en":"Waiting for exam results can feel like forever even if it lasts only a few minutes.","zh":"等待考試結果可能感覺像很久，即使只是幾分鐘。"},{"en":"Fear can stretch time and make a moment feel endless.","zh":"恐懼可以拉長時間，令一刻感覺無盡。"},{"en":"The writer stared at the microphone for what felt like forever before beginning.","zh":"作者在開始前盯着咪高峰，感覺像過了很久。"}],"source":"2014 Q8.pdf","sourcePage":10},{"front":"less like…than…","meaning":"與其說像……不如說像……","examples":[{"en":"The microphone looked less like equipment than a test of character.","zh":"咪高峰與其說像設備，不如說像對性格的考驗。"},{"en":"Less like A than B means something seemed more like B than A.","zh":"與其說像 A，不如說像 B，意思是某物看起來更像 B，而不是 A。"},{"en":"The interview felt less like a test than a conversation about my goals.","zh":"面試與其說像考試，不如說像一場關於目標的對話。"},{"en":"This structure compares surface appearance with deeper meaning.","zh":"這個結構比較表面外貌和更深層意思。"},{"en":"To the writer, the microphone seemed less like a tool than a challenge to courage.","zh":"對作者來說，咪高峰與其說像工具，不如說像對勇氣的挑戰。"}],"source":"2014 Q8.pdf","sourcePage":10},{"front":"equipment","meaning":"設備","examples":[{"en":"The microphone looked less like equipment than a test of character.","zh":"咪高峰與其說像設備，不如說像對性格的考驗。"},{"en":"Equipment means tools or objects needed for a task or activity.","zh":"設備，是完成任務或活動所需要的工具或物件。"},{"en":"A camera, microphone, and speakers are useful equipment for a performance.","zh":"相機、咪高峰和揚聲器都是表演有用的設備。"},{"en":"Equipment can feel frightening when it represents pressure or judgement.","zh":"當設備代表壓力或評價時，它可能令人害怕。"},{"en":"The microphone was ordinary equipment, but to the writer it felt much larger.","zh":"咪高峰是普通設備，但對作者來說，它感覺重要得多。"}],"source":"2014 Q8.pdf","sourcePage":10},{"front":"a test of character","meaning":"對性格的考驗","examples":[{"en":"The microphone felt like a test of character.","zh":"咪高峰感覺像對性格的考驗。"},{"en":"A test of character is a situation that shows a person’s courage, honesty, patience, or strength.","zh":"對性格的考驗，是顯示一個人的勇氣、誠實、耐性或力量的情況。"},{"en":"Admitting a mistake can be a test of character.","zh":"承認錯誤可以是對性格的考驗。"},{"en":"Pressure reveals character because people must choose how to act.","zh":"壓力會揭示性格，因為人們必須選擇如何行動。"},{"en":"For the writer, standing before the microphone tested courage more than memory.","zh":"對作者來說，站在咪高峰前考驗的不是記憶，而是勇氣。"}],"source":"2014 Q8.pdf","sourcePage":10},{"front":"the moment I began","meaning":"我一開始的那一刻","examples":[{"en":"The moment I began, the preparation took over.","zh":"我一開始的那一刻，準備便自然發揮作用。"},{"en":"The moment I began means immediately when I started.","zh":"我一開始的那一刻，意思是我開始時立即。"},{"en":"The moment the music began, the dancers remembered their steps.","zh":"音樂一開始的那一刻，舞者就記起舞步。"},{"en":"Preparation can appear naturally once the real task begins.","zh":"一旦真正任務開始，準備可以自然出現。"},{"en":"The moment the writer began reciting, weeks of practice started to guide them.","zh":"作者一開始朗誦的那一刻，數星期練習便開始引導他。"}],"source":"2014 Q8.pdf","sourcePage":10},{"front":"take over","meaning":"接管；自然發揮作用","examples":[{"en":"The weeks of preparation quietly took over.","zh":"數星期的準備靜靜地自然發揮作用。"},{"en":"To take over means to begin controlling or guiding a situation.","zh":"接管或自然發揮作用，意思是開始控制或引導情況。"},{"en":"In a fire drill, training takes over when students know exactly where to go.","zh":"在火警演習中，當學生清楚知道去哪裏，訓練就會自然發揮作用。"},{"en":"Practice takes over when actions become familiar enough to happen naturally.","zh":"當動作熟悉到能自然發生，練習就會接管。"},{"en":"The writer’s preparation took over, so fear did not control the performance.","zh":"作者的準備自然發揮作用，所以恐懼沒有控制表演。"}],"source":"2014 Q8.pdf","sourcePage":10},{"front":"remember to breathe","meaning":"記得呼吸","examples":[{"en":"I remembered to breathe when I began reciting.","zh":"我開始朗誦時記得呼吸。"},{"en":"To remember to breathe means to consciously take air in and out instead of rushing under pressure.","zh":"記得呼吸，意思是在壓力下有意識地吸氣和呼氣，而不是急促行動。"},{"en":"Before a presentation, a student should remember to breathe slowly.","zh":"匯報前，學生應記得慢慢呼吸。"},{"en":"Remembering to breathe helps speakers control pace and calm nerves.","zh":"記得呼吸幫助講者控制速度和安定情緒。"},{"en":"The writer remembered to breathe, so the opening lines became steadier.","zh":"作者記得呼吸，所以開首幾行變得更穩定。"}],"source":"2014 Q8.pdf","sourcePage":10},{"front":"find the rhythm","meaning":"找到節奏","examples":[{"en":"I found the rhythm as I continued.","zh":"我繼續朗誦時找到了節奏。"},{"en":"To find the rhythm means to discover the natural pace, pattern, or flow of words or movement.","zh":"找到節奏，意思是發現文字或動作的自然速度、模式或流動。"},{"en":"A runner finds the rhythm after the first few minutes of a race.","zh":"跑手在比賽最初幾分鐘後找到節奏。"},{"en":"Finding rhythm helps performers feel less stiff and more connected.","zh":"找到節奏幫助表演者感覺較不僵硬，並更有連繫。"},{"en":"The writer found the poem’s rhythm after breathing and listening to the lines.","zh":"作者在呼吸並聆聽詩句後，找到了詩的節奏。"}],"source":"2014 Q8.pdf","sourcePage":10},{"front":"look up","meaning":"抬頭看","examples":[{"en":"I remembered to look up at the audience.","zh":"我記得抬頭看觀眾。"},{"en":"To look up means to raise the eyes from the floor or page and face people.","zh":"抬頭看，意思是把視線從地面或紙張移開，面向別人。"},{"en":"A speaker should look up sometimes so listeners feel included.","zh":"講者應有時抬頭看，讓聽眾感到被包括在內。"},{"en":"Looking up can be frightening, but it builds connection with the audience.","zh":"抬頭看可能令人害怕，但能與觀眾建立連繫。"},{"en":"The writer learned to look up instead of hiding behind the poem.","zh":"作者學會抬頭看，而不是躲在詩後面。"}],"source":"2014 Q8.pdf","sourcePage":10},{"front":"by the final stanza","meaning":"到最後一節時","examples":[{"en":"By the final stanza, I was no longer thinking about winning.","zh":"到最後一節時，我不再想着勝出。"},{"en":"By the final stanza means when the performer reached the last section of the poem.","zh":"到最後一節時，意思是表演者到達詩的最後部分時。"},{"en":"By the final paragraph of a speech, the speaker may feel calmer.","zh":"到演講最後一段時，講者可能感覺較冷靜。"},{"en":"Reaching the final stanza can show how much the performer has settled into the poem.","zh":"到最後一節時，可以顯示表演者多麼投入詩中。"},{"en":"By the final stanza, the writer cared more about serving the poem than winning.","zh":"到最後一節時，作者更關心好好演繹詩，而不是勝出。"}],"source":"2014 Q8.pdf","sourcePage":11},{"front":"no longer asking whether","meaning":"不再問自己是否","examples":[{"en":"I was no longer asking whether I would win.","zh":"我不再問自己是否會勝出。"},{"en":"No longer asking whether means someone has stopped worrying about a particular question.","zh":"不再問自己是否，意思是某人停止擔心某個問題。"},{"en":"During the performance, the student was no longer asking whether people liked them.","zh":"表演期間，學生不再問自己別人是否喜歡自己。"},{"en":"Stopping this kind of self-questioning can make performance more sincere.","zh":"停止這種自我提問，可以令表演更真誠。"},{"en":"The writer was no longer asking whether they would win, but whether the poem was served well.","zh":"作者不再問自己是否會勝出，而是問自己是否好好演繹了詩。"}],"source":"2014 Q8.pdf","sourcePage":11},{"front":"serve the poem well","meaning":"好好演繹那首詩","examples":[{"en":"I asked whether I had served the poem well.","zh":"我問自己是否好好演繹了那首詩。"},{"en":"To serve the poem well means to perform it faithfully, thoughtfully, and with respect for its meaning.","zh":"好好演繹那首詩，意思是忠實、細心並尊重詩意地表演它。"},{"en":"An actor serves a script well when they understand the character before speaking.","zh":"演員在說台詞前理解角色，就是好好演繹劇本。"},{"en":"Serving a text well requires humility because the performer is not the centre of everything.","zh":"好好演繹文本需要謙遜，因為表演者不是一切的中心。"},{"en":"The writer wanted the audience to hear the poem, not just the performer.","zh":"作者希望觀眾聽見那首詩，而不只是聽見表演者。"}],"source":"2014 Q8.pdf","sourcePage":11},{"front":"go far beyond","meaning":"遠遠超出","examples":[{"en":"What I learned went far beyond public speaking.","zh":"我學到的遠遠超出公開演說。"},{"en":"To go far beyond something means to be much more than that one area or skill.","zh":"遠遠超出某事，意思是遠多於那一個範圍或技能。"},{"en":"Volunteering goes far beyond earning service hours because it teaches responsibility.","zh":"做義工遠遠超出賺取服務時數，因為它教導責任。"},{"en":"An experience goes beyond its surface when it changes how people think.","zh":"當經驗改變人們的想法，它就超越表面。"},{"en":"The Festival went far beyond speaking because it taught patience, empathy, and courage.","zh":"詩歌節遠遠超出演說，因為它教會耐性、同理心和勇氣。"}],"source":"2014 Q8.pdf","sourcePage":11},{"front":"public speaking","meaning":"公開演說","examples":[{"en":"The competition taught me more than public speaking.","zh":"比賽教會我的不只是公開演說。"},{"en":"Public speaking means speaking to an audience in a clear and organised way.","zh":"公開演說，意思是清晰而有組織地向觀眾說話。"},{"en":"Students practise public speaking when they present projects to the class.","zh":"學生向全班匯報專題時，就是練習公開演說。"},{"en":"Public speaking can build confidence, but performance also needs listening and interpretation.","zh":"公開演說可以建立信心，但表演也需要聆聽和演繹。"},{"en":"The Festival improved the writer’s public speaking and also deepened their understanding of language.","zh":"詩歌節改善作者的公開演說，也加深他對語言的理解。"}],"source":"2014 Q8.pdf","sourcePage":11},{"front":"the enemy of creativity","meaning":"創意的敵人","examples":[{"en":"Preparation is not the enemy of creativity.","zh":"準備不是創意的敵人。"},{"en":"The enemy of creativity means something that stops imagination, freedom, or original expression.","zh":"創意的敵人，意思是阻礙想像、自由或原創表達的事物。"},{"en":"Some students think planning is the enemy of creativity, but it can help ideas grow.","zh":"有些學生以為計劃是創意的敵人，但它可以幫助想法成長。"},{"en":"Lack of preparation can actually hurt creativity because people panic and cannot explore.","zh":"缺乏準備其實可能傷害創意，因為人們會恐慌而不能探索。"},{"en":"The writer learned that preparation supports creativity instead of destroying it.","zh":"作者學會準備支持創意，而不是破壞創意。"}],"source":"2014 Q8.pdf","sourcePage":11},{"front":"give creativity room to appear","meaning":"給創意出現的空間","examples":[{"en":"Preparation gives creativity room to appear.","zh":"準備給創意出現的空間。"},{"en":"To give creativity room to appear means to create conditions where original ideas can come out naturally.","zh":"給創意出現的空間，意思是創造條件，讓原創想法自然出現。"},{"en":"Practising basic piano skills gives creativity room to appear during performance.","zh":"練習基本鋼琴技巧，會給表演中的創意出現的空間。"},{"en":"When performers know the words well, they can explore tone and feeling more freely.","zh":"當表演者熟悉文字，他們就能更自由地探索語氣和感情。"},{"en":"The writer found that repeated practice gave creative interpretation space to grow.","zh":"作者發現反覆練習給創意演繹成長的空間。"}],"source":"2014 Q8.pdf","sourcePage":11},{"front":"repeated practice","meaning":"反覆練習","examples":[{"en":"Without repeated practice, inspiration remains a lucky accident.","zh":"沒有反覆練習，靈感仍只是幸運的偶然。"},{"en":"Repeated practice means doing something again and again to improve skill.","zh":"反覆練習，意思是一遍又一遍做某事以改善技巧。"},{"en":"A basketball player needs repeated practice before shooting confidently in a match.","zh":"籃球員需要反覆練習，才能在比賽中有信心地射球。"},{"en":"Repeated practice turns difficult actions into habits.","zh":"反覆練習把困難動作變成習慣。"},{"en":"The writer’s repeated practice made the final performance steadier and more natural.","zh":"作者的反覆練習令最後表演更穩定和自然。"}],"source":"2014 Q8.pdf","sourcePage":11},{"front":"inspiration remains a lucky accident","meaning":"靈感仍只是幸運的偶然","examples":[{"en":"Without practice, inspiration remains a lucky accident.","zh":"沒有練習，靈感仍只是幸運的偶然。"},{"en":"Inspiration remains a lucky accident means good ideas appear only by chance, not reliably.","zh":"靈感仍只是幸運的偶然，意思是好想法只靠機會出現，不能可靠地重現。"},{"en":"A student who never practises may give one good answer, but cannot depend on luck every time.","zh":"從不練習的學生可能答對一次，但不能每次都依靠運氣。"},{"en":"Practice makes inspiration easier to use when the important moment comes.","zh":"練習令人在重要時刻更容易運用靈感。"},{"en":"The writer learned that inspiration needs discipline if it is to become performance.","zh":"作者學會如果靈感要變成表演，就需要紀律。"}],"source":"2014 Q8.pdf","sourcePage":11},{"front":"nervousness can be turned into energy","meaning":"緊張可以轉化為力量","examples":[{"en":"With preparation, nervousness can be turned into energy.","zh":"有了準備，緊張可以轉化為力量。"},{"en":"Nervousness can be turned into energy means fear can become useful focus and excitement.","zh":"緊張可以轉化為力量，意思是恐懼可以變成有用的專注和興奮感。"},{"en":"Before a race, a runner can turn nervousness into energy by warming up and breathing steadily.","zh":"比賽前，跑手可以透過熱身和穩定呼吸把緊張轉化為力量。"},{"en":"Preparation helps because the body still feels nervous, but the mind knows what to do.","zh":"準備有幫助，因為身體仍會緊張，但頭腦知道該做甚麼。"},{"en":"The writer used preparation to turn stage fear into performance energy.","zh":"作者用準備把舞台恐懼轉化為表演力量。"}],"source":"2014 Q8.pdf","sourcePage":11},{"front":"turn into energy","meaning":"轉化為力量","examples":[{"en":"Preparation can turn nervousness into energy.","zh":"準備可以把緊張轉化為力量。"},{"en":"To turn into energy means to change a feeling into active strength or focus.","zh":"轉化為力量，意思是把一種感覺變成積極的力量或專注。"},{"en":"A student can turn exam stress into energy by making a clear study plan.","zh":"學生可以透過制定清晰溫習計劃，把考試壓力轉化為力量。"},{"en":"Feelings become useful when they are directed into action.","zh":"當感覺被引導到行動中，它們就變得有用。"},{"en":"The writer turned nervousness into energy by trusting the practice.","zh":"作者透過相信練習，把緊張轉化為力量。"}],"source":"2014 Q8.pdf","sourcePage":12},{"front":"teach me empathy","meaning":"教會我同理心","examples":[{"en":"Poetry taught me empathy.","zh":"詩歌教會我同理心。"},{"en":"To teach me empathy means to help me understand and care about another person’s feelings.","zh":"教會我同理心，意思是幫助我理解並關心別人的感受。"},{"en":"Reading a refugee’s story can teach students empathy.","zh":"閱讀難民故事可以教會學生同理心。"},{"en":"Poetry teaches empathy because readers must enter another person’s voice or experience.","zh":"詩歌教導同理心，因為讀者必須進入另一個人的聲音或經驗。"},{"en":"Reciting the poem taught the writer empathy by requiring careful listening.","zh":"朗誦這首詩教會作者同理心，因為它要求細心聆聽。"}],"source":"2014 Q8.pdf","sourcePage":12},{"front":"to recite is to","meaning":"朗誦就是去……","examples":[{"en":"To recite is to borrow another person’s voice responsibly.","zh":"朗誦就是負責任地借用另一個人的聲音。"},{"en":"To recite is to means reciting should be understood as doing the action that follows.","zh":"朗誦就是去……，意思是朗誦應被理解為後面所說的行動。"},{"en":"To teach is to help students grow, not just give answers.","zh":"教學就是幫助學生成長，而不只是給答案。"},{"en":"This structure gives a definition with a strong moral meaning.","zh":"這個結構用帶有強烈道德意味的方式下定義。"},{"en":"The writer says to recite is to listen, understand, and speak for the poem carefully.","zh":"作者說朗誦就是去聆聽、理解，並小心為詩發聲。"}],"source":"2014 Q8.pdf","sourcePage":12},{"front":"borrow another person’s voice","meaning":"借用另一個人的聲音","examples":[{"en":"To recite is to borrow another person’s voice.","zh":"朗誦就是借用另一個人的聲音。"},{"en":"To borrow another person’s voice means to speak words and feelings that originally belong to someone else.","zh":"借用另一個人的聲音，意思是說出原本屬於別人的文字和感情。"},{"en":"An actor borrows another person’s voice when playing a character.","zh":"演員扮演角色時，就是借用另一個人的聲音。"},{"en":"Borrowing a voice requires respect because the performer must not twist its meaning carelessly.","zh":"借用聲音需要尊重，因為表演者不能隨便扭曲其意思。"},{"en":"The writer learned to borrow the poet’s voice with care, not use it for self-display.","zh":"作者學會小心借用詩人的聲音，而不是用它來表現自己。"}],"source":"2014 Q8.pdf","sourcePage":12},{"front":"responsibly","meaning":"負責任地","examples":[{"en":"A performer must borrow another person’s voice responsibly.","zh":"表演者必須負責任地借用另一個人的聲音。"},{"en":"Responsibly means with care, respect, and awareness of possible effects.","zh":"負責任地，意思是帶着小心、尊重和對可能影響的意識。"},{"en":"Students should use online information responsibly by checking sources and avoiding copying.","zh":"學生應負責任地使用網上資料，包括核對來源和避免抄襲。"},{"en":"Acting responsibly means thinking about how your choices affect others.","zh":"負責任地行動，意思是思考自己的選擇如何影響別人。"},{"en":"The writer performed responsibly by trying to understand the poem before speaking it.","zh":"作者透過先理解詩再說出它，負責任地表演。"}],"source":"2014 Q8.pdf","sourcePage":12},{"front":"humorous, sorrowful or reflective","meaning":"幽默、悲傷或帶反思意味","examples":[{"en":"A poem may be humorous, sorrowful or reflective.","zh":"一首詩可能幽默、悲傷或帶反思意味。"},{"en":"Humorous, sorrowful or reflective describes moods that are funny, sad, or thoughtful.","zh":"幽默、悲傷或帶反思意味，是形容有趣、傷感或令人思考的情緒。"},{"en":"A story can be humorous at the beginning and sorrowful at the end.","zh":"故事開頭可以幽默，結尾可以悲傷。"},{"en":"Performers must identify the mood so they do not use the wrong tone.","zh":"表演者必須辨認情緒，才不會使用錯誤語氣。"},{"en":"The writer learned to listen for whether the poem was humorous, sorrowful or reflective.","zh":"作者學會聆聽詩到底是幽默、悲傷還是帶反思意味。"}],"source":"2014 Q8.pdf","sourcePage":12},{"front":"listen before being heard","meaning":"在被聽見之前先聆聽","examples":[{"en":"The performer has to listen before being heard.","zh":"表演者必須在被聽見之前先聆聽。"},{"en":"To listen before being heard means to understand the text deeply before trying to perform it for others.","zh":"在被聽見之前先聆聽，意思是在嘗試為別人表演之前，先深入理解文本。"},{"en":"A good speaker listens to classmates’ concerns before asking them to accept an idea.","zh":"好講者在要求同學接受想法前，會先聆聽他們的憂慮。"},{"en":"Listening first prevents performers from making the poem only about themselves.","zh":"先聆聽可以防止表演者把詩變成只關乎自己。"},{"en":"The writer learned that being heard begins with listening carefully.","zh":"作者學會，被聽見始於細心聆聽。"}],"source":"2014 Q8.pdf","sourcePage":12},{"front":"confidence does not mean","meaning":"自信並不代表","examples":[{"en":"Confidence does not mean having no fear.","zh":"自信並不代表毫無恐懼。"},{"en":"Confidence does not mean introduces a correction of a mistaken idea about confidence.","zh":"自信並不代表，用來糾正人們對自信的錯誤想法。"},{"en":"Confidence does not mean speaking loudly all the time.","zh":"自信並不代表一直大聲說話。"},{"en":"This phrase helps explain what a quality is not before saying what it truly is.","zh":"這個短語先解釋某種特質不是甚麼，再說明它真正是甚麼。"},{"en":"The writer learned that confidence does not mean fear disappears completely.","zh":"作者學會自信並不代表恐懼會完全消失。"}],"source":"2014 Q8.pdf","sourcePage":12},{"front":"having no fear","meaning":"毫無恐懼","examples":[{"en":"Confidence does not mean having no fear.","zh":"自信並不代表毫無恐懼。"},{"en":"Having no fear means feeling completely unafraid.","zh":"毫無恐懼，意思是完全不感到害怕。"},{"en":"A brave firefighter does not need to have no fear; they need to act despite danger.","zh":"勇敢的消防員不需要毫無恐懼；他們需要在危險中行動。"},{"en":"People can be confident even when fear is still present.","zh":"即使恐懼仍然存在，人們也可以有自信。"},{"en":"The writer realised that courage means performing well without needing to have no fear.","zh":"作者明白，勇氣是即使不需要毫無恐懼也能好好表演。"}],"source":"2014 Q8.pdf","sourcePage":12},{"front":"quite the contrary","meaning":"恰恰相反","examples":[{"en":"Quite the contrary, confidence means standing tall despite fear.","zh":"恰恰相反，自信是在恐懼中仍昂首站立。"},{"en":"Quite the contrary means the opposite is true.","zh":"恰恰相反，意思是事實正好相反。"},{"en":"Some people think practice kills creativity; quite the contrary, it gives creativity space.","zh":"有些人以為練習扼殺創意；恰恰相反，它給創意空間。"},{"en":"This phrase strongly corrects a previous mistaken idea.","zh":"這個短語強烈糾正先前的錯誤想法。"},{"en":"The writer uses it to show that confidence includes fear, rather than removes it.","zh":"作者使用它來顯示自信包含恐懼，而不是消除恐懼。"}],"source":"2014 Q8.pdf","sourcePage":12},{"front":"stand tall","meaning":"昂首站立；保持自信","examples":[{"en":"Confidence means standing tall while fear is still present.","zh":"自信是在恐懼仍然存在時仍昂首站立。"},{"en":"To stand tall means to behave with dignity, courage, and self-respect.","zh":"昂首站立，意思是有尊嚴、勇氣和自尊地表現。"},{"en":"A student can stand tall after making a mistake by admitting it honestly.","zh":"學生犯錯後誠實承認，也可以昂首站立。"},{"en":"Standing tall does not mean pretending to be perfect.","zh":"昂首站立不代表假裝完美。"},{"en":"The writer stood tall on stage because preparation helped them face fear.","zh":"作者在舞台上昂首站立，因為準備幫助他面對恐懼。"}],"source":"2014 Q8.pdf","sourcePage":13},{"front":"while fear is still present","meaning":"當恐懼仍然存在時","examples":[{"en":"Confidence means acting while fear is still present.","zh":"自信是在恐懼仍然存在時仍然行動。"},{"en":"While fear is still present means even though a person continues to feel afraid.","zh":"當恐懼仍然存在時，意思是即使一個人仍繼續感到害怕。"},{"en":"A student may answer a question while fear is still present in their voice.","zh":"學生可能在聲音仍帶恐懼時回答問題。"},{"en":"Courage often happens while fear is still present, not after fear disappears.","zh":"勇氣常在恐懼仍然存在時出現，而不是恐懼消失後才出現。"},{"en":"The writer performed while fear was still present, which made the moment meaningful.","zh":"作者在恐懼仍然存在時表演，這令那一刻有意義。"}],"source":"2014 Q8.pdf","sourcePage":13},{"front":"bring home the champion’s trophy","meaning":"捧回冠軍獎盃","examples":[{"en":"I did not bring home the champion’s trophy.","zh":"我沒有捧回冠軍獎盃。"},{"en":"To bring home the champion’s trophy means to win first prize and take the award back.","zh":"捧回冠軍獎盃，意思是贏得第一名並把獎項帶回來。"},{"en":"A school team may bring home the champion’s trophy after winning the final.","zh":"學校隊伍贏得決賽後，可能捧回冠軍獎盃。"},{"en":"Not bringing home a trophy does not mean the experience was wasted.","zh":"沒有捧回獎盃，不代表經驗被浪費。"},{"en":"The writer did not win the champion’s trophy, but gained lessons that lasted longer.","zh":"作者沒有捧回冠軍獎盃，但得到更持久的課題。"}],"source":"2014 Q8.pdf","sourcePage":13},{"front":"bring back something more lasting","meaning":"帶回更持久的東西","examples":[{"en":"I brought back something more lasting than a trophy.","zh":"我帶回了比獎盃更持久的東西。"},{"en":"To bring back something more lasting means to gain something from an experience that remains longer than a prize.","zh":"帶回更持久的東西，意思是從經驗中獲得比獎項更長久的收穫。"},{"en":"A student may not win a debate but bring back stronger confidence.","zh":"學生可能沒有贏得辯論，但帶回更強信心。"},{"en":"Some lessons last longer than certificates because they change how people think.","zh":"有些課題比證書更持久，因為它們改變人的想法。"},{"en":"The writer brought back discipline, empathy, and courage from the Festival.","zh":"作者從詩歌節帶回紀律、同理心和勇氣。"}],"source":"2014 Q8.pdf","sourcePage":13},{"front":"a better ear for language","meaning":"更敏銳的語感","examples":[{"en":"The Festival gave me a better ear for language.","zh":"詩歌節給了我更敏銳的語感。"},{"en":"A better ear for language means a stronger ability to hear rhythm, tone, sound, and meaning in words.","zh":"更敏銳的語感，意思是更能聽出文字中的節奏、語氣、聲音和意思。"},{"en":"Reading poems aloud can give students a better ear for English.","zh":"大聲朗讀詩歌可以給學生更敏銳的英文語感。"},{"en":"A better ear for language helps people notice why some sentences sound powerful.","zh":"更敏銳的語感幫助人們注意為何有些句子聽起來有力。"},{"en":"The writer gained a better ear for language by listening to pauses and stresses.","zh":"作者透過聆聽停頓和重音，獲得更敏銳的語感。"}],"source":"2014 Q8.pdf","sourcePage":13},{"front":"a stronger belief in","meaning":"對……有更強信念","examples":[{"en":"I gained a stronger belief in patient effort.","zh":"我對耐心努力有更強信念。"},{"en":"A stronger belief in something means deeper trust that it is valuable or true.","zh":"對某事有更強信念，意思是更深地相信它有價值或真實。"},{"en":"After improving slowly, a student may gain a stronger belief in daily practice.","zh":"慢慢進步後，學生可能對每天練習有更強信念。"},{"en":"Success after difficulty can strengthen belief in steady effort.","zh":"經歷困難後成功，可以加強人們對穩定努力的信念。"},{"en":"The Festival gave the writer a stronger belief in preparation and patience.","zh":"詩歌節令作者對準備和耐性有更強信念。"}],"source":"2014 Q8.pdf","sourcePage":13},{"front":"patient effort","meaning":"耐心努力","examples":[{"en":"The competition strengthened my belief in patient effort.","zh":"比賽加強了我對耐心努力的信念。"},{"en":"Patient effort means steady work done over time without expecting instant results.","zh":"耐心努力，意思是不期望立即有成果，而長時間穩定工作。"},{"en":"Learning a language requires patient effort because progress comes gradually.","zh":"學習語言需要耐心努力，因為進步是逐漸出現的。"},{"en":"Patient effort matters when improvement is slow but real.","zh":"當進步緩慢但真實，耐心努力就很重要。"},{"en":"The writer’s recitation improved through patient effort, not sudden talent alone.","zh":"作者的朗誦透過耐心努力改善，而不只是靠突然的天分。"}],"source":"2014 Q8.pdf","sourcePage":13},{"front":"prizes are guaranteed","meaning":"獎項有保證","examples":[{"en":"Schoolmates should join not because prizes are guaranteed.","zh":"同學應參加，不是因為獎項有保證。"},{"en":"Prizes are guaranteed means awards are certain to be won.","zh":"獎項有保證，意思是肯定能贏得獎項。"},{"en":"Students should not join a competition only because they think prizes are guaranteed.","zh":"學生不應只因為以為獎項有保證而參加比賽。"},{"en":"In real competitions, prizes are never guaranteed, but learning can still happen.","zh":"在真正比賽中，獎項從來沒有保證，但學習仍會發生。"},{"en":"The writer believes students should join for growth, not because a prize is promised.","zh":"作者認為學生應為成長而參加，而不是因為獎項被承諾。"}],"source":"2014 Q8.pdf","sourcePage":13},{"front":"the process itself","meaning":"過程本身","examples":[{"en":"The process itself can help students grow.","zh":"過程本身可以幫助學生成長。"},{"en":"The process itself means the experience and steps involved, not only the final result.","zh":"過程本身，意思是當中的經驗和步驟，而不只是最終結果。"},{"en":"Preparing for a debate can be valuable because the process itself teaches research and teamwork.","zh":"準備辯論很有價值，因為過程本身教導研究和團隊合作。"},{"en":"The process itself matters when students learn skills even without winning.","zh":"即使學生沒有勝出，但學到技能時，過程本身就很重要。"},{"en":"The Poetry Festival process itself helped the writer become more confident and thoughtful.","zh":"詩歌節的過程本身幫助作者變得更有信心和更會思考。"}],"source":"2014 Q8.pdf","sourcePage":13},{"front":"make us better listeners, speakers and thinkers","meaning":"令我們成為更好的聆聽者、說話者和思考者","examples":[{"en":"The process can make us better listeners, speakers and thinkers.","zh":"這個過程可以令我們成為更好的聆聽者、說話者和思考者。"},{"en":"To make us better listeners, speakers and thinkers means to improve how we hear, express, and understand ideas.","zh":"令我們成為更好的聆聽者、說話者和思考者，意思是改善我們聆聽、表達和理解想法的方式。"},{"en":"Reading poems aloud can make students better listeners because they must notice sound and meaning.","zh":"大聲朗讀詩歌可以令學生成為更好的聆聽者，因為他們必須注意聲音和意思。"},{"en":"Discussion makes people better thinkers when they learn to consider different interpretations.","zh":"當人們學會考慮不同演繹，討論會令人更會思考。"},{"en":"The Festival helped students grow not only in speaking, but also in listening and thinking.","zh":"詩歌節幫助學生不只在說話方面成長，也在聆聽和思考方面成長。"}],"source":"2014 Q8.pdf","sourcePage":13},{"front":"continue to make room for","meaning":"繼續為……騰出空間","examples":[{"en":"Our school should continue to make room for the arts.","zh":"我們學校應繼續為藝術騰出空間。"},{"en":"To continue to make room for something means to keep creating time, space, or support for it.","zh":"繼續為某事騰出空間，意思是持續為它創造時間、空間或支援。"},{"en":"Schools should make room for music even when exam schedules are busy.","zh":"即使考試時間表很忙，學校也應為音樂騰出空間。"},{"en":"When a school makes room for the arts, students can develop more than academic skills.","zh":"當學校為藝術騰出空間，學生可以發展學術以外的技能。"},{"en":"The writer hopes the school will continue to make room for activities like poetry.","zh":"作者希望學校繼續為詩歌等活動騰出空間。"}],"source":"2014 Q8.pdf","sourcePage":14},{"front":"the arts","meaning":"藝術","examples":[{"en":"Schools should make room for the arts.","zh":"學校應為藝術騰出空間。"},{"en":"The arts include creative subjects and activities such as music, drama, poetry, painting, and dance.","zh":"藝術包括音樂、戲劇、詩歌、繪畫和舞蹈等創意科目和活動。"},{"en":"The arts help students express feelings that ordinary homework may not reach.","zh":"藝術幫助學生表達普通功課未必能觸及的感受。"},{"en":"Schools that support the arts give students more ways to discover themselves.","zh":"支持藝術的學校，給學生更多發現自己的方式。"},{"en":"The Poetry Festival showed the writer why the arts belong in school life.","zh":"詩歌節向作者顯示，為何藝術應屬於校園生活。"}],"source":"2014 Q8.pdf","sourcePage":14},{"front":"after all","meaning":"畢竟","examples":[{"en":"After all, a poem can fill a room when spoken well.","zh":"畢竟，一首詩如果說得好，可以充滿整個房間。"},{"en":"After all is used to give a final reason or reminder that supports the point.","zh":"畢竟，用來給出支持觀點的最後理由或提醒。"},{"en":"Students should rest before exams; after all, tired minds learn poorly.","zh":"學生考試前應休息；畢竟，疲倦的頭腦學得不好。"},{"en":"Writers use after all when they want the reader to accept the conclusion.","zh":"作者使用「畢竟」，是希望讀者接受結論。"},{"en":"After all, poetry performance matters because words can change a room’s atmosphere.","zh":"畢竟，詩歌表演重要，因為文字可以改變房間的氣氛。"}],"source":"2014 Q8.pdf","sourcePage":14},{"front":"a poem on paper","meaning":"紙上的詩","examples":[{"en":"A poem on paper may be quiet.","zh":"紙上的詩可能是安靜的。"},{"en":"A poem on paper means a poem as written text before anyone reads or performs it aloud.","zh":"紙上的詩，意思是在任何人大聲朗讀或表演前，作為書面文字的詩。"},{"en":"A poem on paper may look simple until a performer gives it rhythm.","zh":"紙上的詩可能看似簡單，直到表演者給它節奏。"},{"en":"Written poems can feel silent because their sound is waiting to be discovered.","zh":"書面詩可能感覺沉默，因為其聲音等待被發現。"},{"en":"The Festival showed that a poem on paper can become powerful in the right voice.","zh":"詩歌節顯示，紙上的詩可以在合適的聲音中變得有力量。"}],"source":"2014 Q8.pdf","sourcePage":14},{"front":"in the right voice","meaning":"以合適的聲音","examples":[{"en":"In the right voice, a poem can fill a room.","zh":"以合適的聲音，一首詩可以充滿整個房間。"},{"en":"In the right voice means spoken with a tone and feeling that match the poem’s meaning.","zh":"以合適的聲音，意思是用配合詩意的語氣和感情說出來。"},{"en":"A sad poem needs the right voice, not a cheerful or careless tone.","zh":"悲傷的詩需要合適的聲音，而不是開心或隨便的語氣。"},{"en":"The right voice helps listeners feel that the performer understands the poem.","zh":"合適的聲音幫助聽眾感到表演者理解詩歌。"},{"en":"The writer learned that in the right voice, quiet words can become powerful.","zh":"作者學會，以合適的聲音，安靜文字也可以變得有力量。"}],"source":"2014 Q8.pdf","sourcePage":14},{"front":"fill a room","meaning":"充滿整個房間","examples":[{"en":"In the right voice, a poem can fill a room.","zh":"以合適的聲音，一首詩可以充滿整個房間。"},{"en":"To fill a room means to make the whole space feel full of sound, feeling, or attention.","zh":"充滿整個房間，意思是令整個空間充滿聲音、感情或注意力。"},{"en":"A singer’s voice can fill a room even without a microphone.","zh":"歌手的聲音即使沒有咪高峰，也可以充滿整個房間。"},{"en":"Strong words fill a room when everyone stops and listens.","zh":"當所有人停下來聆聽，有力量的文字就能充滿整個房間。"},{"en":"The writer discovered that a well-spoken poem can fill a room with meaning.","zh":"作者發現，一首說得好的詩可以用意思充滿整個房間。"}],"source":"2014 Q8.pdf","sourcePage":14}],"dse/writing/part-b/2014/Q9":[{"front":"the last bus home","meaning":"回家的尾班車","examples":[{"en":"The story is called “The Last Bus Home.”","zh":"這個故事名為《回家的尾班車》。"},{"en":"The last bus home is the final bus someone can take to return home at night.","zh":"回家的尾班車是晚上能乘搭回家的最後一班巴士。"},{"en":"A student may rush to catch the last bus home after a late group project.","zh":"學生完成深夜小組項目後，可能趕著乘搭回家的尾班車。"},{"en":"Missing the last bus home can make a person feel stranded and anxious.","zh":"錯過回家的尾班車可能令人感到被困和焦急。"},{"en":"In the story, the last bus home suggests both a real journey and a difficult return to family duty.","zh":"在故事中，回家的尾班車既暗示真正的旅程，也暗示回到家庭責任的艱難。"}],"source":"2014 Q9.pdf","sourcePage":1},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time I returned to Room 913, Chris had already left.","zh":"到我回到 913 號房的時候，Chris 已經離開了。"},{"en":"By the time means when a later moment arrives, something has already happened.","zh":"到……的時候意思是到了較後的時刻，某事已經發生。"},{"en":"By the time the lesson started, most students had opened their books.","zh":"到課堂開始的時候，大部分學生已經打開課本。"},{"en":"This phrase often shows that one action happened too late to change another.","zh":"這個短語常顯示一個行動發生得太遲，無法改變另一件事。"},{"en":"By the time the narrator returned, Chris’s departure was already complete.","zh":"到敘述者回來的時候，Chris 的離開已經成定局。"}],"source":"2014 Q9.pdf","sourcePage":1},{"front":"return to","meaning":"回到","examples":[{"en":"I returned to Room 913 and found Chris’s side empty.","zh":"我回到 913 號房，發現 Chris 那一邊空了。"},{"en":"To return to a place means to go back to it after leaving.","zh":"回到某地意思是離開後再回去。"},{"en":"A student may return to the library after lunch to finish studying.","zh":"學生可能午飯後回到圖書館完成溫習。"},{"en":"Returning to a familiar place can feel strange if something important has changed.","zh":"如果重要事情已經改變，回到熟悉地方也可能感覺陌生。"},{"en":"When the narrator returns to the room, the emptiness shows Chris is gone.","zh":"當敘述者回到房間時，那份空蕩顯示 Chris 已離開。"}],"source":"2014 Q9.pdf","sourcePage":1},{"front":"a bare rectangle of sunlight","meaning":"一個空蕩蕩的陽光長方形","examples":[{"en":"Chris’s bed had become a bare rectangle of sunlight.","zh":"Chris 的床位變成一個空蕩蕩的陽光長方形。"},{"en":"A bare rectangle of sunlight is an empty bright space where something used to be.","zh":"一個空蕩蕩的陽光長方形，是指某物曾經存在的位置只剩下一片明亮空位。"},{"en":"After the desk was moved away, only a bare rectangle of sunlight remained on the floor.","zh":"書桌搬走後，地上只剩下一個空蕩蕩的陽光長方形。"},{"en":"This image makes absence visible by showing light instead of belongings.","zh":"這個意象用光線而不是物品，令缺席變得可見。"},{"en":"The phrase suggests that Chris’s side of the room is clean, empty, and painfully quiet.","zh":"這個短語暗示 Chris 房間那一邊乾淨、空蕩，並令人痛心地安靜。"}],"source":"2014 Q9.pdf","sourcePage":1},{"front":"posters were gone","meaning":"海報不見了","examples":[{"en":"His posters were gone from the wall.","zh":"他的海報從牆上不見了。"},{"en":"Posters were gone means the posters had been removed and were no longer there.","zh":"海報不見了意思是海報已被移走，不再在那裏。"},{"en":"After a student moves out, the posters are gone and the wall looks blank.","zh":"學生搬走後，海報不見了，牆壁看起來空白。"},{"en":"Missing posters can show that someone has left in a serious and final way.","zh":"不見了的海報可以顯示某人以認真而決絕的方式離開。"},{"en":"In the story, the empty wall makes Chris’s departure feel real.","zh":"在故事中，空白牆壁令 Chris 的離開變得真實。"}],"source":"2014 Q9.pdf","sourcePage":1},{"front":"laundry basket","meaning":"洗衣籃","examples":[{"en":"His laundry basket was gone.","zh":"他的洗衣籃不見了。"},{"en":"A laundry basket is a container used for dirty clothes before washing.","zh":"洗衣籃是用來放洗衣前髒衣服的容器。"},{"en":"A student may carry a laundry basket to the washing machines in the hall.","zh":"學生可能拿著洗衣籃去宿舍洗衣機。"},{"en":"When even the laundry basket is gone, it shows the person has fully moved out.","zh":"連洗衣籃也不見了，顯示那個人已完全搬走。"},{"en":"Small everyday objects can make absence feel more painful.","zh":"細小的日常物件可以令缺席感更令人難受。"}],"source":"2014 Q9.pdf","sourcePage":1},{"front":"cracked cup","meaning":"有裂痕的杯","examples":[{"en":"Even the cracked cup had disappeared.","zh":"連那隻有裂痕的杯也已經消失了。"},{"en":"A cracked cup is a cup with a line or break on its surface.","zh":"有裂痕的杯是表面有裂紋或破痕的杯子。"},{"en":"A student may still use a cracked cup if it does not leak.","zh":"如果杯子不漏水，學生可能仍會使用有裂痕的杯。"},{"en":"A cracked cup can feel personal because it carries daily habits and memories.","zh":"有裂痕的杯可以感覺很私人，因為它承載日常習慣和回憶。"},{"en":"Chris’s cracked cup matters because it was part of his quiet life in the room.","zh":"Chris 的有裂痕的杯很重要，因為它是他在房間安靜生活的一部分。"}],"source":"2014 Q9.pdf","sourcePage":1},{"front":"instant coffee","meaning":"即溶咖啡","examples":[{"en":"Chris used the cracked cup for instant coffee.","zh":"Chris 用那隻有裂痕的杯喝即溶咖啡。"},{"en":"Instant coffee is coffee powder that quickly becomes a drink when hot water is added.","zh":"即溶咖啡是加入熱水後很快變成飲品的咖啡粉。"},{"en":"Busy students may drink instant coffee before late-night revision.","zh":"忙碌學生可能在深夜溫習前喝即溶咖啡。"},{"en":"Instant coffee suggests a quick, tired routine rather than a relaxed breakfast.","zh":"即溶咖啡暗示快捷而疲倦的日常，而不是悠閒早餐。"},{"en":"In the story, the cup and instant coffee show Chris’s ordinary student life.","zh":"在故事中，杯子和即溶咖啡顯示 Chris 普通的學生生活。"}],"source":"2014 Q9.pdf","sourcePage":1},{"front":"late-night noodles","meaning":"深夜杯麵","examples":[{"en":"Chris used the cup for instant coffee and late-night noodles.","zh":"Chris 用那隻杯喝即溶咖啡和吃深夜杯麵。"},{"en":"Late-night noodles are noodles eaten late at night, often by tired or busy people.","zh":"深夜杯麵是在深夜吃的麵，通常由疲倦或忙碌的人食用。"},{"en":"Students may eat late-night noodles while finishing assignments.","zh":"學生完成作業時可能會吃深夜杯麵。"},{"en":"Late-night noodles can show comfort, hunger, or exhaustion.","zh":"深夜杯麵可以顯示安慰、飢餓或疲憊。"},{"en":"Chris’s late-night noodles suggest that he was often awake when others rested.","zh":"Chris 的深夜杯麵暗示他常在別人休息時仍醒著。"}],"source":"2014 Q9.pdf","sourcePage":1},{"front":"had disappeared","meaning":"已經消失","examples":[{"en":"Even his cracked cup had disappeared.","zh":"連他有裂痕的杯也已經消失。"},{"en":"Had disappeared means something was no longer there by a certain time.","zh":"已經消失意思是到某個時間，某物已不再存在於那裏。"},{"en":"By morning, the rainwater had disappeared from the playground.","zh":"到早上時，操場上的雨水已經消失。"},{"en":"When personal objects have disappeared, people realise someone has truly left.","zh":"當私人物件已經消失，人們才意識到某人真的離開了。"},{"en":"The phrase makes Chris’s absence feel sudden and final.","zh":"這個短語令 Chris 的缺席感覺突然而決絕。"}],"source":"2014 Q9.pdf","sourcePage":1},{"front":"on my pillow lay","meaning":"在我的枕頭上放著","examples":[{"en":"On my pillow lay his key card and a note.","zh":"在我的枕頭上放著他的門卡和一張字條。"},{"en":"On my pillow lay means something was placed on the pillow, often in a noticeable way.","zh":"在我的枕頭上放著，意思是某物被放在枕頭上，通常很顯眼。"},{"en":"On my desk lay a letter I had not expected.","zh":"在我的書桌上放著一封我沒預料到的信。"},{"en":"This word order sounds literary and draws attention to the objects.","zh":"這種語序帶有文學感，並把注意力放在物件上。"},{"en":"The key card and note on the pillow become Chris’s quiet goodbye.","zh":"枕頭上的門卡和字條成為 Chris 安靜的告別。"}],"source":"2014 Q9.pdf","sourcePage":2},{"front":"key card","meaning":"門卡","examples":[{"en":"Chris left his key card on my pillow.","zh":"Chris 把門卡留在我的枕頭上。"},{"en":"A key card is a plastic card used to open a locked door electronically.","zh":"門卡是用來電子開鎖的膠卡。"},{"en":"Students in a hall may use a key card to enter their room.","zh":"宿舍學生可能用門卡進入房間。"},{"en":"Returning a key card can show that someone has moved out.","zh":"交還門卡可以顯示某人已搬走。"},{"en":"Chris’s key card on the pillow proves that he does not plan to sleep there again.","zh":"Chris 放在枕頭上的門卡證明他不打算再在那裏睡。"}],"source":"2014 Q9.pdf","sourcePage":2},{"front":"neat handwriting","meaning":"整齊的字跡","examples":[{"en":"The note was written in Chris’s neat handwriting.","zh":"那張字條以 Chris 整齊的字跡寫成。"},{"en":"Neat handwriting is writing that is tidy, clear, and easy to read.","zh":"整齊的字跡是整潔、清晰、容易閱讀的書寫。"},{"en":"A teacher can read a student’s neat handwriting without guessing the words.","zh":"老師可以不用猜字就讀懂學生整齊的字跡。"},{"en":"Neat handwriting can reveal care even in a short message.","zh":"整齊的字跡即使在短訊息中也能顯示用心。"},{"en":"Chris’s neat handwriting makes his goodbye feel controlled and painfully calm.","zh":"Chris 整齊的字跡令他的告別感覺克制而痛心地平靜。"}],"source":"2014 Q9.pdf","sourcePage":2},{"front":"go home","meaning":"回家","examples":[{"en":"Chris wrote, “I’ve gone home.”","zh":"Chris 寫道：「我回家了。」"},{"en":"To go home means to return to the place where one lives or belongs.","zh":"回家意思是回到自己生活或歸屬的地方。"},{"en":"After a long school day, students usually want to go home and rest.","zh":"漫長上學日後，學生通常想回家休息。"},{"en":"In this story, going home is not simple rest; it means returning to family responsibility.","zh":"在這個故事中，回家不只是簡單休息；它代表回到家庭責任中。"},{"en":"Chris goes home because his family needs him more than the hall does.","zh":"Chris 回家，因為他的家人比宿舍更需要他。"}],"source":"2014 Q9.pdf","sourcePage":2},{"front":"keep the kettle","meaning":"留下水煲","examples":[{"en":"Chris left a note telling me to keep the kettle.","zh":"Chris 留下一張字條，叫我留下水煲。"},{"en":"To keep the kettle means to take and continue using the kettle instead of returning it.","zh":"留下水煲意思是收下並繼續使用水煲，而不用歸還。"},{"en":"A roommate may say, “Keep the kettle,” when moving out suddenly.","zh":"室友突然搬走時，可能會說：「水煲留給你。」"},{"en":"Leaving the kettle behind makes the goodbye practical but emotional.","zh":"留下水煲令告別既實際又帶有情感。"},{"en":"The kettle becomes a reminder of Chris after he leaves.","zh":"水煲在 Chris 離開後成為他的提醒。"}],"source":"2014 Q9.pdf","sourcePage":2},{"front":"see someone’s departure coming","meaning":"預料到某人會離開","examples":[{"en":"No one on our floor saw Chris’s departure coming.","zh":"我們那一層沒有人預料到 Chris 會離開。"},{"en":"To see someone’s departure coming means to expect that the person is about to leave.","zh":"預料到某人會離開，意思是估計那個人快將離去。"},{"en":"Friends may not see a classmate’s departure coming if he hides his worries well.","zh":"如果同學把憂慮藏得很好，朋友可能預料不到他會離開。"},{"en":"People often miss signs when a quiet person is carrying heavy pressure.","zh":"當安靜的人承受沉重壓力時，人們常會錯過跡象。"},{"en":"The narrator later realises that Chris’s leaving was not truly sudden.","zh":"敘述者後來才明白，Chris 的離開其實並非真正突然。"}],"source":"2014 Q9.pdf","sourcePage":2},{"front":"departure","meaning":"離開","examples":[{"en":"No one expected Chris’s departure.","zh":"沒有人預料 Chris 的離開。"},{"en":"Departure means the act of leaving a place, job, school, or relationship.","zh":"離開是指離開一個地方、工作、學校或關係的行動。"},{"en":"A student’s sudden departure from hall can shock their friends.","zh":"學生突然離開宿舍，可能令朋友震驚。"},{"en":"Departure feels painful when there was no proper goodbye.","zh":"如果沒有好好道別，離開會令人痛苦。"},{"en":"Chris’s departure changes the room from shared space into memory.","zh":"Chris 的離開把房間由共同空間變成回憶。"}],"source":"2014 Q9.pdf","sourcePage":2},{"front":"the kind of roommate","meaning":"那種室友","examples":[{"en":"Chris was the kind of roommate every first-year wanted.","zh":"Chris 是每個大學一年級學生都想要的那種室友。"},{"en":"The kind of roommate means the type of person someone is when sharing a room.","zh":"那種室友意思是某人在同住時屬於哪一類人。"},{"en":"The kind of roommate who cleans up and listens well makes hall life easier.","zh":"會收拾和願意聆聽的那種室友，會令宿舍生活更容易。"},{"en":"This phrase helps describe Chris through the narrator’s admiration.","zh":"這個短語透過敘述者的欣賞來描述 Chris。"},{"en":"Chris is remembered not for being perfect, but for being quietly considerate.","zh":"Chris 被記住不是因為完美，而是因為安靜地體貼。"}],"source":"2014 Q9.pdf","sourcePage":2},{"front":"first-year","meaning":"大學一年級學生","examples":[{"en":"Every first-year wanted a roommate like Chris.","zh":"每個大學一年級學生都想要像 Chris 這樣的室友。"},{"en":"A first-year is a student in the first year of university or college.","zh":"大學一年級學生是大學或專上學院第一年的學生。"},{"en":"A first-year may feel nervous about living away from home.","zh":"大學一年級學生離家生活時可能感到緊張。"},{"en":"Good roommates can help first-years adjust to hall life.","zh":"好室友可以幫助大學一年級學生適應宿舍生活。"},{"en":"Chris made university life easier for first-years around him.","zh":"Chris 令身邊大學一年級學生的大學生活更容易。"}],"source":"2014 Q9.pdf","sourcePage":2},{"front":"tidy, cheerful and generous","meaning":"整潔、開朗又慷慨","examples":[{"en":"Chris was tidy, cheerful and generous.","zh":"Chris 整潔、開朗又慷慨。"},{"en":"Tidy, cheerful and generous means neat, happy in manner, and willing to share.","zh":"整潔、開朗又慷慨意思是整齊、態度愉快，並願意分享。"},{"en":"A tidy roommate keeps the room clean; a cheerful one lifts the mood.","zh":"整潔的室友會保持房間乾淨；開朗的室友會提升氣氛。"},{"en":"A generous person offers help or food without making others feel guilty.","zh":"慷慨的人會提供幫助或食物，而不令別人感到內疚。"},{"en":"These qualities explain why Chris’s absence hurts the narrator.","zh":"這些特質解釋了為何 Chris 的缺席令敘述者難受。"}],"source":"2014 Q9.pdf","sourcePage":2},{"front":"generous with","meaning":"對……很慷慨","examples":[{"en":"Chris was generous with the last biscuit in the tin.","zh":"Chris 對罐裏最後一塊餅乾也很慷慨。"},{"en":"To be generous with something means to share it willingly.","zh":"對某物很慷慨意思是願意分享它。"},{"en":"A student is generous with notes when they lend them to a sick classmate.","zh":"學生把筆記借給生病同學時，就是對筆記很慷慨。"},{"en":"Being generous with small things can show a large heart.","zh":"對小事慷慨可以顯示寬大的心。"},{"en":"Chris’s generosity appears in ordinary moments, such as sharing food.","zh":"Chris 的慷慨出現在分享食物等普通時刻中。"}],"source":"2014 Q9.pdf","sourcePage":3},{"front":"the last biscuit in the tin","meaning":"罐裏最後一塊餅乾","examples":[{"en":"Chris would share even the last biscuit in the tin.","zh":"Chris 甚至會分享罐裏最後一塊餅乾。"},{"en":"The last biscuit in the tin is the final piece of food left in a container.","zh":"罐裏最後一塊餅乾是容器中剩下的最後一塊食物。"},{"en":"Sharing the last biscuit shows generosity because there is nothing left after it.","zh":"分享最後一塊餅乾顯示慷慨，因為分享後就沒有剩下。"},{"en":"A person who shares the last biscuit may care more about friendship than comfort.","zh":"願意分享最後一塊餅乾的人，可能比舒適更重視友誼。"},{"en":"The image makes Chris’s kindness concrete and easy to remember.","zh":"這個意象令 Chris 的善良具體而容易記住。"}],"source":"2014 Q9.pdf","sourcePage":3},{"front":"during our first week","meaning":"在我們第一星期","examples":[{"en":"During our first week in hall, Chris helped me with the window.","zh":"在我們住進宿舍的第一星期，Chris 幫我處理窗戶。"},{"en":"During our first week means within the first seven days of a new experience.","zh":"在我們第一星期意思是在新經驗開始的頭七天內。"},{"en":"During our first week at university, many students felt excited and lost.","zh":"在大學第一星期，許多學生既興奮又迷茫。"},{"en":"Early kindness matters because first weeks can feel uncertain.","zh":"早期的善意很重要，因為第一星期常令人感到不確定。"},{"en":"Chris’s help during the first week made the narrator trust him.","zh":"Chris 在第一星期的幫助令敘述者信任他。"}],"source":"2014 Q9.pdf","sourcePage":3},{"front":"in hall","meaning":"在宿舍","examples":[{"en":"During our first week in hall, we became roommates.","zh":"在我們第一星期住在宿舍時，我們成為室友。"},{"en":"In hall means living in a university residence or dormitory.","zh":"在宿舍意思是住在大學宿舍或學生宿舍中。"},{"en":"Students in hall share rooms, bathrooms, common rooms, and daily routines.","zh":"在宿舍的學生會共享房間、浴室、交誼廳和日常生活。"},{"en":"Life in hall can make strangers become close very quickly.","zh":"宿舍生活可以令陌生人很快變得親近。"},{"en":"In the story, hall life contrasts with Chris’s heavy family life outside.","zh":"在故事中，宿舍生活與 Chris 在外面沉重的家庭生活形成對比。"}],"source":"2014 Q9.pdf","sourcePage":3},{"front":"stop the window from rattling","meaning":"阻止窗戶發出震動聲","examples":[{"en":"Chris taught me how to stop the window from rattling.","zh":"Chris 教我如何阻止窗戶發出震動聲。"},{"en":"To stop the window from rattling means to prevent it from shaking and making noise.","zh":"阻止窗戶發出震動聲，意思是防止窗戶搖動並製造聲音。"},{"en":"A student may use folded paper to stop a loose window from rattling.","zh":"學生可能用摺好的紙阻止鬆動窗戶發出震動聲。"},{"en":"Fixing a rattling window is a small act of practical care.","zh":"修好會響的窗戶是小小的實際關心。"},{"en":"Chris’s help shows that he noticed problems and quietly solved them.","zh":"Chris 的幫忙顯示他會注意問題，並安靜地解決它們。"}],"source":"2014 Q9.pdf","sourcePage":3},{"front":"rattle during storms","meaning":"在暴風雨中咯咯作響","examples":[{"en":"The window rattled during storms.","zh":"那扇窗在暴風雨中咯咯作響。"},{"en":"To rattle during storms means to shake noisily when strong wind and rain hit.","zh":"在暴風雨中咯咯作響，意思是在強風大雨拍打時震動並發出聲音。"},{"en":"Old windows may rattle during storms and keep students awake.","zh":"舊窗戶可能在暴風雨中咯咯作響，令學生睡不著。"},{"en":"The noise can make a room feel cold, unsafe, or lonely.","zh":"那聲音可以令房間感覺寒冷、不安全或孤單。"},{"en":"Chris’s solution made the shared room feel more comfortable.","zh":"Chris 的方法令共用房間更舒服。"}],"source":"2014 Q9.pdf","sourcePage":3},{"front":"laugh at everyone’s terrible jokes","meaning":"笑大家很爛的笑話","examples":[{"en":"Chris laughed at everyone’s terrible jokes.","zh":"Chris 會笑大家很爛的笑話。"},{"en":"To laugh at terrible jokes means to respond kindly even when the jokes are not funny.","zh":"笑很爛的笑話意思是即使笑話不好笑，也友善地回應。"},{"en":"A generous friend may laugh at a weak joke to make others feel included.","zh":"慷慨的朋友可能會笑一個薄弱笑話，令別人感到被接納。"},{"en":"Chris’s laughter helped the floor feel warmer and less awkward.","zh":"Chris 的笑聲令樓層氣氛更溫暖、不那麼尷尬。"},{"en":"This habit shows his kindness in small social moments.","zh":"這個習慣顯示他在小小社交時刻中的善良。"}],"source":"2014 Q9.pdf","sourcePage":3},{"front":"freedom with a timetable","meaning":"有時間表的自由","examples":[{"en":"Chris once said that university life was “freedom with a timetable.”","zh":"Chris 曾說大學生活是「有時間表的自由」。"},{"en":"Freedom with a timetable means having independence but still living under schedules and duties.","zh":"有時間表的自由意思是擁有獨立，但仍受日程和責任限制。"},{"en":"University gives students freedom, but lectures and deadlines still form a timetable.","zh":"大學給學生自由，但講課和期限仍形成時間表。"},{"en":"This phrase captures the mixed feeling of student life.","zh":"這個短語捕捉了學生生活的混合感覺。"},{"en":"For Chris, even that limited freedom was interrupted by family responsibility.","zh":"對 Chris 來說，連這種有限自由也被家庭責任打斷。"}],"source":"2014 Q9.pdf","sourcePage":3},{"front":"the signs had been there","meaning":"其實跡象早已存在","examples":[{"en":"Still, the signs had been there.","zh":"然而，其實跡象早已存在。"},{"en":"The signs had been there means clues existed earlier, even if people failed to notice them.","zh":"其實跡象早已存在，意思是線索之前已經出現，只是人們沒有注意。"},{"en":"The signs had been there when a quiet student stopped joining dinners.","zh":"當安靜的學生不再參加晚飯時，其實跡象早已存在。"},{"en":"Looking back, people often understand warning signs too late.","zh":"回望時，人們常太遲才明白警號。"},{"en":"The narrator realises Chris’s leaving had clues all along.","zh":"敘述者意識到 Chris 的離開一直都有線索。"}],"source":"2014 Q9.pdf","sourcePage":3},{"front":"begin with","meaning":"由……開始","examples":[{"en":"It began with the phone calls.","zh":"事情由那些電話開始。"},{"en":"To begin with something means to start from that first sign or event.","zh":"由某事開始意思是從那個最初跡象或事件開始。"},{"en":"The argument began with a small misunderstanding.","zh":"那場爭執由一個小誤會開始。"},{"en":"A story may begin with an ordinary detail that later becomes important.","zh":"故事可能由一個普通細節開始，而那細節後來變得重要。"},{"en":"Chris’s pressure began to show through the nightly phone calls.","zh":"Chris 的壓力開始透過每晚的電話顯露。"}],"source":"2014 Q9.pdf","sourcePage":3},{"front":"phone calls","meaning":"電話","examples":[{"en":"The signs began with the phone calls.","zh":"跡象由那些電話開始。"},{"en":"Phone calls are conversations made by telephone.","zh":"電話是透過電話進行的交談。"},{"en":"Late-night phone calls may worry a roommate if they happen every night.","zh":"如果深夜電話每晚都出現，室友可能會擔心。"},{"en":"Repeated phone calls can signal that someone is dealing with problems outside school.","zh":"反覆出現的電話可能顯示某人正在處理校外問題。"},{"en":"In the story, the phone calls connect Chris’s hall life to his family crisis.","zh":"在故事中，那些電話把 Chris 的宿舍生活和家庭危機連接起來。"}],"source":"2014 Q9.pdf","sourcePage":4},{"front":"at around eleven","meaning":"大約十一點","examples":[{"en":"Chris would step into the corridor at around eleven.","zh":"Chris 會在大約十一點走到走廊。"},{"en":"At around eleven means at about eleven o’clock, not exactly.","zh":"大約十一點意思是接近十一點，但不一定準確。"},{"en":"At around eleven, the hall usually became quieter.","zh":"大約十一點時，宿舍通常變得較安靜。"},{"en":"Repeated actions at the same time can become signs of hidden pressure.","zh":"同一時間反覆出現的行動，可以成為隱藏壓力的跡象。"},{"en":"Chris’s calls at around eleven suggest a nightly pattern.","zh":"Chris 大約十一點接電話，暗示一種每晚重複的模式。"}],"source":"2014 Q9.pdf","sourcePage":4},{"front":"step into the corridor","meaning":"走到走廊","examples":[{"en":"Chris would step into the corridor to answer calls.","zh":"Chris 會走到走廊接電話。"},{"en":"To step into the corridor means to leave a room and move into the hallway.","zh":"走到走廊意思是離開房間，移到走廊中。"},{"en":"A student may step into the corridor to avoid disturbing a sleeping roommate.","zh":"學生可能走到走廊，以免打擾正在睡覺的室友。"},{"en":"Chris stepped outside because the calls were private and painful.","zh":"Chris 走出去，因為那些電話既私密又痛苦。"},{"en":"The corridor becomes a place between student life and family responsibility.","zh":"走廊成為學生生活和家庭責任之間的地方。"}],"source":"2014 Q9.pdf","sourcePage":4},{"front":"speak in a voice so soft that","meaning":"用非常輕的聲音說話，以致","examples":[{"en":"Chris spoke in a voice so soft that it was almost not a voice at all.","zh":"Chris 用非常輕的聲音說話，以致那幾乎不像聲音。"},{"en":"To speak in a voice so soft that something happens means to speak extremely quietly.","zh":"用非常輕的聲音說話，以致某事發生，意思是說話極其細聲。"},{"en":"A child may speak in a voice so soft that the teacher has to bend down to hear.","zh":"孩子可能用非常輕的聲音說話，以致老師要彎下身才聽到。"},{"en":"Soft speech can show fear, exhaustion, secrecy, or sadness.","zh":"輕聲說話可以顯示恐懼、疲憊、秘密或傷心。"},{"en":"Chris’s quiet voice suggests he was trying not to disturb others or reveal too much.","zh":"Chris 的細聲暗示他不想打擾別人，也不想透露太多。"}],"source":"2014 Q9.pdf","sourcePage":4},{"front":"almost not a voice at all","meaning":"幾乎不像聲音","examples":[{"en":"His voice was so soft that it was almost not a voice at all.","zh":"他的聲音非常輕，幾乎不像聲音。"},{"en":"Almost not a voice at all means extremely quiet, weak, or barely audible.","zh":"幾乎不像聲音意思是極度細聲、虛弱，或幾乎聽不見。"},{"en":"A tired student may answer in a whisper that is almost not a voice at all.","zh":"疲倦的學生可能用幾乎不像聲音的耳語回答。"},{"en":"This phrase suggests emotional heaviness as well as low volume.","zh":"這個短語不只暗示音量低，也暗示情緒沉重。"},{"en":"Chris’s voice reveals pressure before he explains it.","zh":"Chris 的聲音在他解釋之前已透露壓力。"}],"source":"2014 Q9.pdf","sourcePage":4},{"front":"come after class","meaning":"下課後過來","examples":[{"en":"Chris told his mother that he could come after class.","zh":"Chris 告訴母親，他可以下課後過來。"},{"en":"To come after class means to arrive later, once lessons have finished.","zh":"下課後過來意思是在課堂完結後到達。"},{"en":"A student may tell a parent, “I’ll come after class,” if help is needed at home.","zh":"如果家中需要幫忙，學生可能告訴父母：「我下課後過來。」"},{"en":"This phrase shows Chris trying to fit family duty around university life.","zh":"這個短語顯示 Chris 嘗試把家庭責任塞進大學生活中。"},{"en":"His promise to come after class suggests responsibility, not freedom.","zh":"他答應下課後過來，暗示責任，而不是自由。"}],"source":"2014 Q9.pdf","sourcePage":4},{"front":"do her homework first","meaning":"先做功課","examples":[{"en":"Chris told Mary to do her homework first.","zh":"Chris 叫 Mary 先做功課。"},{"en":"To do her homework first means to finish schoolwork before doing other things.","zh":"先做功課意思是在做其他事之前完成學校作業。"},{"en":"An older brother may tell his sister to do her homework first before helping in the shop.","zh":"哥哥可能叫妹妹先做功課，再到店裏幫忙。"},{"en":"This instruction shows care for Mary’s education even during family stress.","zh":"這個指示顯示即使家庭壓力很大，他仍關心 Mary 的教育。"},{"en":"Chris wants Mary to remain a child, not only a helper.","zh":"Chris 希望 Mary 仍能做孩子，而不只是幫手。"}],"source":"2014 Q9.pdf","sourcePage":4},{"front":"whether everything was fine","meaning":"是否一切安好","examples":[{"en":"I asked whether everything was fine.","zh":"我問是否一切安好。"},{"en":"Whether everything was fine means if all things were okay or safe.","zh":"是否一切安好意思是所有事情是否沒問題或安全。"},{"en":"A roommate may ask whether everything is fine after hearing worried phone calls.","zh":"室友聽到憂心的電話後，可能問是否一切安好。"},{"en":"This question is gentle, but it may not reach a person hiding pain.","zh":"這個問題很溫和，但未必能觸及正在隱藏痛苦的人。"},{"en":"Chris’s quick smile shows that everything was not really fine.","zh":"Chris 太快露出的笑容顯示事情其實並非一切安好。"}],"source":"2014 Q9.pdf","sourcePage":4},{"front":"smile too quickly","meaning":"太快露出笑容","examples":[{"en":"Chris smiled too quickly when I asked about his family.","zh":"當我問起他的家人時，Chris 太快露出笑容。"},{"en":"To smile too quickly means to smile immediately in a way that may hide discomfort.","zh":"太快露出笑容意思是立刻微笑，方式可能隱藏不自在。"},{"en":"A student may smile too quickly when asked about a problem they do not want to explain.","zh":"當學生被問到不想解釋的問題時，可能太快露出笑容。"},{"en":"Quick smiles can be a shield when someone feels exposed.","zh":"快速的笑容可以是人在感到被看穿時的一道盾。"},{"en":"Chris’s smile suggests he is protecting both himself and the narrator from the truth.","zh":"Chris 的笑容暗示他在保護自己，也在保護敘述者免於知道真相。"}],"source":"2014 Q9.pdf","sourcePage":4},{"front":"family stuff","meaning":"家裏的事","examples":[{"en":"Chris said it was just family stuff.","zh":"Chris 說那只是家裏的事。"},{"en":"Family stuff means family matters, often described vaguely because they are private.","zh":"家裏的事是指家庭事務，通常因為私密而說得含糊。"},{"en":"A person may say “family stuff” when they do not want to explain a problem fully.","zh":"當一個人不想完整解釋問題時，可能會說「家裏的事」。"},{"en":"The phrase can hide anything from small tasks to deep pain.","zh":"這個短語可以隱藏由小任務到深層痛苦的任何事情。"},{"en":"Chris uses “family stuff” to make a heavy burden sound ordinary.","zh":"Chris 用「家裏的事」把沉重負擔說得像普通小事。"}],"source":"2014 Q9.pdf","sourcePage":4},{"front":"can mean anything from… to…","meaning":"可以指從……到……任何事","examples":[{"en":"Family stuff can mean anything from a broken tap to a breaking heart.","zh":"家裏的事可以指從壞掉的水龍頭到破碎的心之間任何事。"},{"en":"This structure shows that a phrase can cover a wide range of situations.","zh":"這個結構顯示一個短語可以涵蓋很廣泛的情況。"},{"en":"School pressure can mean anything from a quiz to a major public exam.","zh":"學業壓力可以指從小測到大型公開考試之間任何事。"},{"en":"The phrase helps explain why vague words can hide serious problems.","zh":"這個短語幫助解釋為何含糊詞語可以隱藏嚴重問題。"},{"en":"In Chris’s case, “family stuff” means much more than ordinary chores.","zh":"在 Chris 的情況中，「家裏的事」遠不只是普通雜務。"}],"source":"2014 Q9.pdf","sourcePage":5},{"front":"broken tap","meaning":"壞掉的水龍頭","examples":[{"en":"Family trouble can be as small as a broken tap.","zh":"家庭麻煩可以小至壞掉的水龍頭。"},{"en":"A broken tap is a tap that does not work properly or leaks water.","zh":"壞掉的水龍頭是不能正常運作或會漏水的水龍頭。"},{"en":"A broken tap may seem like a small household problem.","zh":"壞掉的水龍頭可能看似小小家庭問題。"},{"en":"Small problems can still add stress when a family is already tired.","zh":"當家庭已經疲倦時，小問題仍會增加壓力。"},{"en":"The phrase contrasts ordinary trouble with deeper emotional pain.","zh":"這個短語把普通麻煩和更深情感痛苦作對比。"}],"source":"2014 Q9.pdf","sourcePage":5},{"front":"breaking heart","meaning":"破碎的心","examples":[{"en":"Family trouble can also mean a breaking heart.","zh":"家庭麻煩也可以代表一顆破碎的心。"},{"en":"A breaking heart means deep emotional pain, sadness, or grief.","zh":"破碎的心意思是深層情感痛苦、悲傷或哀痛。"},{"en":"A parent’s illness can leave a child with a breaking heart.","zh":"父母生病可能令孩子有一顆破碎的心。"},{"en":"The phrase suggests pain that is invisible but heavy.","zh":"這個短語暗示看不見但沉重的痛苦。"},{"en":"Chris’s “family stuff” may include both practical problems and a breaking heart.","zh":"Chris 的「家裏的事」可能既包括實際問題，也包括一顆破碎的心。"}],"source":"2014 Q9.pdf","sourcePage":5},{"front":"hotpot night","meaning":"火鍋夜","examples":[{"en":"Then there was the hotpot night.","zh":"然後就是那個火鍋夜。"},{"en":"Hotpot night is an evening when people gather to cook and eat hotpot together.","zh":"火鍋夜是人們聚在一起煮火鍋和吃火鍋的晚上。"},{"en":"Students may organise a hotpot night in the common room to become closer.","zh":"學生可能在交誼廳舉辦火鍋夜，讓大家更親近。"},{"en":"A cheerful meal can suddenly reveal hidden tension.","zh":"一頓開心的飯局可能突然揭露隱藏壓力。"},{"en":"In the story, hotpot night exposes Chris’s sensitivity to wasted food.","zh":"在故事中，火鍋夜暴露了 Chris 對浪費食物的敏感。"}],"source":"2014 Q9.pdf","sourcePage":5},{"front":"squeeze two tables into","meaning":"把兩張枱擠進","examples":[{"en":"Our floor had squeezed two tables into the common room.","zh":"我們那一層把兩張枱擠進交誼廳。"},{"en":"To squeeze two tables into a room means to fit them into a small space with difficulty.","zh":"把兩張枱擠進房間，意思是困難地把它們放入狹小空間。"},{"en":"Students may squeeze extra chairs into a room before a party.","zh":"聚會前，學生可能把額外椅子擠進房間。"},{"en":"The phrase suggests a crowded but lively gathering.","zh":"這個短語暗示場面擁擠但熱鬧。"},{"en":"The packed common room contrasts with Chris’s private loneliness.","zh":"擠滿人的交誼廳與 Chris 私下的孤單形成對比。"}],"source":"2014 Q9.pdf","sourcePage":5},{"front":"common room","meaning":"交誼廳","examples":[{"en":"Everyone gathered in the common room for hotpot.","zh":"大家聚在交誼廳吃火鍋。"},{"en":"A common room is a shared space where residents relax, talk, or eat together.","zh":"交誼廳是住客共同放鬆、聊天或吃東西的共享空間。"},{"en":"Students may watch television or hold meetings in the common room.","zh":"學生可能在交誼廳看電視或開會。"},{"en":"Common rooms can create a sense of community in a hall.","zh":"交誼廳可以在宿舍中建立社群感。"},{"en":"In the story, the common room becomes the place where hidden pain briefly appears.","zh":"在故事中，交誼廳成為隱藏痛苦短暫浮現的地方。"}],"source":"2014 Q9.pdf","sourcePage":5},{"front":"laugh too loudly","meaning":"笑得太大聲","examples":[{"en":"Everyone was laughing too loudly over the food.","zh":"大家圍著食物笑得太大聲。"},{"en":"To laugh too loudly means to laugh in a way that feels excessive or careless.","zh":"笑得太大聲意思是笑聲過度或顯得不夠顧及別人。"},{"en":"Friends may laugh too loudly at dinner when they are excited.","zh":"朋友吃晚飯時興奮，可能笑得太大聲。"},{"en":"Loud laughter can feel harmless to some people but painful to someone under pressure.","zh":"大笑對一些人來說無害，但對承受壓力的人可能刺耳。"},{"en":"The noise at hotpot night makes Chris’s silence stand out.","zh":"火鍋夜的喧鬧令 Chris 的沉默更突出。"}],"source":"2014 Q9.pdf","sourcePage":5},{"front":"fish balls","meaning":"魚蛋","examples":[{"en":"Everyone ate fish balls, cabbage and beef slices.","zh":"大家吃魚蛋、白菜和平價肥牛片。"},{"en":"Fish balls are round pieces of processed fish often used in hotpot or noodle soup.","zh":"魚蛋是由魚肉製成的圓形食物，常用於火鍋或湯麵。"},{"en":"Students may put fish balls into boiling soup during a hotpot dinner.","zh":"學生吃火鍋時可能把魚蛋放進滾湯中。"},{"en":"Simple foods like fish balls can create warmth in shared meals.","zh":"魚蛋這類簡單食物可以在共享飯局中創造溫暖。"},{"en":"In the story, the food also reminds Chris of waste and family hardship.","zh":"在故事中，食物也令 Chris 想起浪費和家庭艱難。"}],"source":"2014 Q9.pdf","sourcePage":5},{"front":"cheap beef slices","meaning":"平價肥牛片","examples":[{"en":"The students shared fish balls, cabbage and cheap beef slices.","zh":"學生們分享魚蛋、白菜和平價肥牛片。"},{"en":"Cheap beef slices are thin pieces of beef sold at a low price.","zh":"平價肥牛片是價格較低的薄牛肉片。"},{"en":"Students may buy cheap beef slices for hotpot because they are affordable.","zh":"學生可能因價錢負擔得起而買平價肥牛片吃火鍋。"},{"en":"Cheap food still matters to someone whose family counts every bowl of rice.","zh":"對一個家裏每碗飯都重要的人來說，平價食物仍然重要。"},{"en":"The detail shows that the meal is ordinary but emotionally important.","zh":"這個細節顯示這頓飯普通，卻帶有情感重量。"}],"source":"2014 Q9.pdf","sourcePage":5},{"front":"knock over","meaning":"撞跌；打翻","examples":[{"en":"Someone knocked over a plate of food.","zh":"有人打翻了一碟食物。"},{"en":"To knock over something means to hit it accidentally so that it falls.","zh":"撞跌或打翻某物，意思是不小心碰到它，令它倒下。"},{"en":"A student may knock over a cup when reaching for a book.","zh":"學生伸手拿書時可能撞跌杯子。"},{"en":"Knocking over food can seem like a small accident during a noisy meal.","zh":"在熱鬧飯局中打翻食物可能看似小意外。"},{"en":"For Chris, the accident feels serious because food is never just food.","zh":"對 Chris 來說，這意外很嚴重，因為食物從來不只是食物。"}],"source":"2014 Q9.pdf","sourcePage":5},{"front":"never mind","meaning":"不要緊","examples":[{"en":"Someone said, “Never mind, we ordered too much anyway.”","zh":"有人說：「不要緊，反正我們點得太多。」"},{"en":"Never mind means do not worry about it or it is not important.","zh":"不要緊意思是不用擔心，或這件事不重要。"},{"en":"A friend may say “never mind” after a small mistake.","zh":"小錯誤發生後，朋友可能會說「不要緊」。"},{"en":"The phrase can comfort people, but it can also sound careless in the wrong situation.","zh":"這句話可以安慰人，但在錯誤情況下也可能顯得粗心。"},{"en":"Chris hears “never mind” differently because his family cannot afford waste.","zh":"Chris 對「不要緊」的理解不同，因為他的家庭承受不起浪費。"}],"source":"2014 Q9.pdf","sourcePage":6},{"front":"order too much","meaning":"點得太多","examples":[{"en":"The students had ordered too much food.","zh":"學生們點得太多食物。"},{"en":"To order too much means to ask for more food than people can finish.","zh":"點得太多意思是叫了超過大家能吃完的食物。"},{"en":"A group may order too much at a restaurant when everyone is excited.","zh":"大家很興奮時，可能在餐廳點得太多。"},{"en":"Ordering too much can lead to waste if people treat leftovers casually.","zh":"如果人們隨便對待剩菜，點得太多會導致浪費。"},{"en":"Chris’s reaction shows that too much food can mean guilt, not abundance.","zh":"Chris 的反應顯示太多食物可以代表內疚，而不是富足。"}],"source":"2014 Q9.pdf","sourcePage":6},{"front":"freeze","meaning":"呆住；僵住","examples":[{"en":"Chris froze when someone wasted food.","zh":"當有人浪費食物時，Chris 僵住了。"},{"en":"To freeze means to suddenly stop moving because of shock, fear, or strong emotion.","zh":"呆住或僵住意思是因震驚、恐懼或強烈情緒而突然停止動作。"},{"en":"A student may freeze when called to speak unexpectedly.","zh":"學生被突然叫起來發言時可能會呆住。"},{"en":"Chris freezes because the wasted food touches something painful in him.","zh":"Chris 僵住，是因為被浪費的食物觸碰到他內心痛處。"},{"en":"The word shows his reaction before he can explain it.","zh":"這個詞在他能解釋之前先顯示他的反應。"}],"source":"2014 Q9.pdf","sourcePage":6},{"front":"for a second","meaning":"有一秒鐘","examples":[{"en":"For a second, something hard moved across his face.","zh":"有一秒鐘，他臉上閃過一種僵硬神情。"},{"en":"For a second means for a very short moment.","zh":"有一秒鐘意思是非常短暫的一刻。"},{"en":"For a second, a smile disappeared from the teacher’s face.","zh":"有一秒鐘，老師臉上的笑容消失了。"},{"en":"Short moments can reveal feelings people usually hide.","zh":"短短一刻可以揭露人平時隱藏的情緒。"},{"en":"Chris’s expression lasts only a second, but it tells the narrator something is wrong.","zh":"Chris 的表情只維持一秒，卻告訴敘述者事情不對勁。"}],"source":"2014 Q9.pdf","sourcePage":6},{"front":"something hard moved across his face","meaning":"臉上閃過一種僵硬神情","examples":[{"en":"Something hard moved across Chris’s face.","zh":"Chris 臉上閃過一種僵硬神情。"},{"en":"This phrase means his expression briefly became tense, cold, or painful.","zh":"這個短語意思是他的表情短暫變得緊繃、冷硬或痛苦。"},{"en":"A person’s face may harden when they hear careless words about something serious.","zh":"當人聽到別人輕率談論嚴重事情時，臉色可能會變硬。"},{"en":"The phrase shows emotion without directly naming it.","zh":"這個短語顯示情緒，卻沒有直接說出情緒名稱。"},{"en":"Chris’s face reveals anger and hurt before he tries to hide them.","zh":"Chris 的臉在他試圖隱藏之前，先透露了憤怒和受傷。"}],"source":"2014 Q9.pdf","sourcePage":6},{"front":"don’t waste it","meaning":"不要浪費","examples":[{"en":"Chris told the others not to waste the food.","zh":"Chris 告訴大家不要浪費食物。"},{"en":"Don’t waste it means do not throw it away or treat it carelessly.","zh":"不要浪費意思是不要把它丟掉或隨便對待。"},{"en":"A parent may say “Don’t waste it” when a child leaves rice in a bowl.","zh":"孩子把飯剩在碗裏時，父母可能會說「不要浪費」。"},{"en":"The phrase can sound simple, but it may carry deep family experience.","zh":"這句話聽起來簡單，但可能承載深層家庭經驗。"},{"en":"Chris says it because food represents money, labour, and worry at home.","zh":"Chris 這樣說，因為食物在家裏代表金錢、勞力和憂慮。"}],"source":"2014 Q9.pdf","sourcePage":6},{"front":"fall silent","meaning":"安靜下來","examples":[{"en":"The room fell silent after Chris spoke.","zh":"Chris 說話後，房間安靜下來。"},{"en":"To fall silent means to become quiet suddenly.","zh":"安靜下來意思是突然變得沉默。"},{"en":"A classroom may fall silent when a teacher announces bad news.","zh":"老師宣布壞消息時，課室可能安靜下來。"},{"en":"Silence can show shock, guilt, or discomfort.","zh":"沉默可以顯示震驚、內疚或不自在。"},{"en":"The common room falls silent because everyone realises Chris’s anger is serious.","zh":"交誼廳安靜下來，因為大家意識到 Chris 的憤怒很認真。"}],"source":"2014 Q9.pdf","sourcePage":6},{"front":"look embarrassed at once","meaning":"立刻顯得尷尬","examples":[{"en":"Chris looked embarrassed at once.","zh":"Chris 立刻顯得尷尬。"},{"en":"To look embarrassed at once means to immediately appear ashamed or uncomfortable.","zh":"立刻顯得尷尬意思是馬上看起來羞愧或不自在。"},{"en":"A student may look embarrassed at once after speaking too sharply.","zh":"學生說話太尖銳後，可能立刻顯得尷尬。"},{"en":"Chris becomes embarrassed because his private pain has appeared in public.","zh":"Chris 變得尷尬，因為他的私人痛苦公開出現了。"},{"en":"His embarrassment shows he did not mean to hurt the cheerful mood.","zh":"他的尷尬顯示他並非想破壞熱鬧氣氛。"}],"source":"2014 Q9.pdf","sourcePage":6},{"front":"pick up the plate","meaning":"拿起碟子","examples":[{"en":"Chris picked up the plate and said he was tired.","zh":"Chris 拿起碟子，說自己累了。"},{"en":"To pick up the plate means to lift the plate from the table or floor.","zh":"拿起碟子意思是把碟子從桌上或地上提起。"},{"en":"After food falls, someone may pick up the plate to clean the mess.","zh":"食物掉下後，有人可能拿起碟子清理混亂。"},{"en":"Chris picks up the plate to repair the awkward moment with action.","zh":"Chris 拿起碟子，是用行動修補尷尬時刻。"},{"en":"The action shows his habit of taking responsibility quickly.","zh":"這個行動顯示他習慣快速承擔責任。"}],"source":"2014 Q9.pdf","sourcePage":6},{"front":"mutter","meaning":"低聲咕噥","examples":[{"en":"Chris muttered that he was tired.","zh":"Chris 低聲咕噥說自己累了。"},{"en":"To mutter means to speak quietly and unclearly, often because of embarrassment or unhappiness.","zh":"低聲咕噥意思是細聲而不清楚地說話，通常因尷尬或不開心。"},{"en":"A student may mutter an apology after making a mistake.","zh":"學生犯錯後可能低聲咕噥道歉。"},{"en":"Muttering can show that a person does not want full attention.","zh":"低聲咕噥可以顯示一個人不想被完全注意。"},{"en":"Chris mutters because he wants to escape the moment, not explain it.","zh":"Chris 低聲咕噥，是因為他想逃離那一刻，而不是解釋它。"}],"source":"2014 Q9.pdf","sourcePage":6},{"front":"pantry","meaning":"茶水間","examples":[{"en":"I found Chris washing boxes in the pantry.","zh":"我在茶水間找到 Chris 正在洗盒子。"},{"en":"A pantry is a small room or area for preparing food, drinks, or washing dishes.","zh":"茶水間是準備食物、飲品或洗碗的小房間或地方。"},{"en":"Students may make instant noodles in the pantry at night.","zh":"學生可能在晚上到茶水間煮即食麵。"},{"en":"The pantry is less public than the common room, so Chris can hide there.","zh":"茶水間比交誼廳較不公開，所以 Chris 可以躲在那裏。"},{"en":"Finding him in the pantry shows the narrator beginning to see his burden.","zh":"在茶水間找到他，顯示敘述者開始看見他的負擔。"}],"source":"2014 Q9.pdf","sourcePage":7},{"front":"reusable takeaway boxes","meaning":"可重用外賣盒","examples":[{"en":"Chris was washing reusable takeaway boxes.","zh":"Chris 正在洗可重用外賣盒。"},{"en":"Reusable takeaway boxes are food containers that can be washed and used again.","zh":"可重用外賣盒是可以清洗並再次使用的食物容器。"},{"en":"Families may keep reusable takeaway boxes to store leftovers.","zh":"家庭可能保存可重用外賣盒來裝剩菜。"},{"en":"Washing them carefully can show respect for food and resources.","zh":"仔細清洗它們可以顯示對食物和資源的尊重。"},{"en":"Chris’s care with the boxes reveals how deeply he hates waste.","zh":"Chris 對盒子的仔細，透露他多麼討厭浪費。"}],"source":"2014 Q9.pdf","sourcePage":7},{"front":"as if they were made of glass","meaning":"彷彿它們是玻璃造的","examples":[{"en":"He washed the boxes as if they were made of glass.","zh":"他清洗那些盒子時，彷彿它們是玻璃造的。"},{"en":"As if they were made of glass means treating ordinary things with extreme care.","zh":"彷彿它們是玻璃造的，意思是以極度小心的方式對待普通物件。"},{"en":"A child may hold an old family photo as if it were made of glass.","zh":"孩子可能像拿著玻璃一樣拿著舊家庭照片。"},{"en":"The phrase shows that the boxes carry emotional value beyond their price.","zh":"這個短語顯示盒子的情感價值超越其價格。"},{"en":"Chris washes them gently because waste feels serious to him.","zh":"Chris 輕柔地清洗它們，因為浪費對他來說很嚴重。"}],"source":"2014 Q9.pdf","sourcePage":7},{"front":"at last","meaning":"終於","examples":[{"en":"Chris explained his family situation at last.","zh":"Chris 終於解釋了他的家庭情況。"},{"en":"At last means finally, after waiting or after something has been delayed.","zh":"終於意思是在等待或延遲之後最後發生。"},{"en":"After weeks of silence, a student may explain the problem at last.","zh":"沉默數星期後，學生可能終於解釋問題。"},{"en":"This phrase suggests relief but also sadness because the truth was heavy.","zh":"這個短語暗示鬆一口氣，但也有悲傷，因為真相沉重。"},{"en":"Chris speaks at last because the hidden pressure can no longer stay hidden.","zh":"Chris 終於開口，因為隱藏壓力再也藏不住。"}],"source":"2014 Q9.pdf","sourcePage":7},{"front":"run a small cha chaan teng","meaning":"經營一間小茶餐廳","examples":[{"en":"Chris’s family runs a small cha chaan teng.","zh":"Chris 的家人經營一間小茶餐廳。"},{"en":"To run a small cha chaan teng means to operate a small Hong Kong-style café.","zh":"經營一間小茶餐廳意思是營運一間小型港式餐廳。"},{"en":"A family may run a cha chaan teng by cooking, serving, cleaning, and managing bills together.","zh":"一個家庭可能透過一起煮食、招待、清潔和處理帳單來經營茶餐廳。"},{"en":"Running a small restaurant takes long hours and physical effort.","zh":"經營小餐廳需要長工時和體力。"},{"en":"Chris’s family business explains why every bowl of rice matters.","zh":"Chris 的家庭生意解釋了為何每一碗飯都重要。"}],"source":"2014 Q9.pdf","sourcePage":7},{"front":"hurt his back","meaning":"弄傷背部","examples":[{"en":"Chris’s father hurt his back last month.","zh":"Chris 的父親上個月弄傷背部。"},{"en":"To hurt his back means to injure the muscles, bones, or nerves in his back.","zh":"弄傷背部意思是傷到背部肌肉、骨骼或神經。"},{"en":"A worker may hurt his back after lifting heavy boxes.","zh":"工作者搬重箱後可能弄傷背部。"},{"en":"A back injury can make standing, cooking, and carrying things painful.","zh":"背傷可以令站立、煮食和搬東西都變得痛苦。"},{"en":"Chris’s father’s injury increases the pressure on the whole family.","zh":"Chris 父親的傷勢增加了全家的壓力。"}],"source":"2014 Q9.pdf","sourcePage":7},{"front":"open the shop","meaning":"開舖","examples":[{"en":"Chris’s mother opens the shop at six.","zh":"Chris 的母親六點開舖。"},{"en":"To open the shop means to prepare a business for customers at the start of the day.","zh":"開舖意思是在一天開始時準備店舖接待顧客。"},{"en":"A shop owner opens the shop by turning on lights, preparing food, and unlocking the door.","zh":"店主開舖時會開燈、準備食物和開門。"},{"en":"Opening the shop at six shows how early Chris’s mother begins work.","zh":"六點開舖顯示 Chris 的母親多早開始工作。"},{"en":"The phrase helps readers feel the family’s long working hours.","zh":"這個短語幫助讀者感受到這家人的長工時。"}],"source":"2014 Q9.pdf","sourcePage":7},{"front":"close after midnight","meaning":"午夜後收舖","examples":[{"en":"Chris’s mother closes the shop after midnight.","zh":"Chris 的母親午夜後收舖。"},{"en":"To close after midnight means to finish business after twelve at night.","zh":"午夜後收舖意思是在晚上十二點後結束營業。"},{"en":"A restaurant that closes after midnight leaves workers with little rest.","zh":"午夜後收舖的餐廳會令員工休息時間很少。"},{"en":"Long hours can exhaust a family running a small business.","zh":"長工時會令經營小生意的家庭筋疲力竭。"},{"en":"Chris’s mother opening at six and closing after midnight shows extreme pressure.","zh":"Chris 的母親六點開舖、午夜後收舖，顯示極大壓力。"}],"source":"2014 Q9.pdf","sourcePage":7},{"front":"study properly","meaning":"好好讀書","examples":[{"en":"Chris’s mother wanted him to study properly.","zh":"Chris 的母親希望他好好讀書。"},{"en":"To study properly means to study seriously, regularly, and with enough attention.","zh":"好好讀書意思是認真、定期並有足夠專注地學習。"},{"en":"Parents may tell children to study properly so they can have better choices later.","zh":"父母可能叫孩子好好讀書，讓他們日後有更好選擇。"},{"en":"Chris’s mother wants him to study because she hopes he can leave hardship behind.","zh":"Chris 的母親希望他讀書，是因為她希望他能離開艱苦生活。"},{"en":"The tragedy is that family duty keeps interrupting his chance to study properly.","zh":"可悲的是，家庭責任不斷打斷他好好讀書的機會。"}],"source":"2014 Q9.pdf","sourcePage":7},{"front":"something has gone wrong","meaning":"出了問題","examples":[{"en":"Every night, his mother called because something had gone wrong.","zh":"每晚，他的母親都打電話來，因為出了問題。"},{"en":"Something has gone wrong means a problem has happened.","zh":"出了問題意思是發生了麻煩。"},{"en":"A shop owner may call for help when the freezer breaks and something has gone wrong.","zh":"冷藏櫃壞掉時，店主可能打電話求助，因為出了問題。"},{"en":"Repeated problems can turn ordinary phone calls into signals of crisis.","zh":"反覆出現的問題可以把普通電話變成危機訊號。"},{"en":"Chris’s nightly calls show that home is never fully stable.","zh":"Chris 每晚的電話顯示家裏從未完全穩定。"}],"source":"2014 Q9.pdf","sourcePage":7},{"front":"there was no getting around the fact that","meaning":"無法迴避……這個事實","examples":[{"en":"There was no getting around the fact that Chris had been living two lives.","zh":"無法迴避 Chris 一直過著兩種生活這個事實。"},{"en":"There was no getting around the fact that means a truth could no longer be avoided or denied.","zh":"無法迴避……這個事實，意思是某個真相再也不能被避開或否認。"},{"en":"There was no getting around the fact that the team had missed the deadline.","zh":"無法迴避團隊錯過期限這個事實。"},{"en":"This phrase introduces a painful truth that people must finally face.","zh":"這個短語引出人們最終必須面對的痛苦真相。"},{"en":"The narrator can no longer pretend Chris is just another carefree student.","zh":"敘述者再也不能假裝 Chris 只是另一個無憂無慮的學生。"}],"source":"2014 Q9.pdf","sourcePage":8},{"front":"live two lives","meaning":"過著兩種生活","examples":[{"en":"Chris had been living two lives.","zh":"Chris 一直過著兩種生活。"},{"en":"To live two lives means to carry two very different roles or worlds at the same time.","zh":"過著兩種生活意思是同時承擔兩種非常不同的角色或世界。"},{"en":"A student may live two lives if they study by day and care for family at night.","zh":"如果學生白天讀書、晚上照顧家庭，就是過著兩種生活。"},{"en":"Living two lives is exhausting because each life demands energy and attention.","zh":"過著兩種生活令人疲憊，因為每種生活都要求精力和注意。"},{"en":"Chris lives as a university student and as a family helper at once.","zh":"Chris 同時作為大學生和家庭幫手生活。"}],"source":"2014 Q9.pdf","sourcePage":8},{"front":"argue about","meaning":"為……爭論","examples":[{"en":"Students in the hall argued about laundry queues and tutorial readings.","zh":"宿舍學生為洗衣輪候隊伍和導修課閱讀材料爭論。"},{"en":"To argue about something means to disagree or complain about it.","zh":"為某事爭論意思是因某事不同意或抱怨。"},{"en":"Roommates may argue about cleaning, noise, or shared space.","zh":"室友可能為清潔、噪音或共用空間爭論。"},{"en":"Students argue about small inconveniences while Chris worries about family survival.","zh":"學生為小不便爭論，而 Chris 擔心的是家庭生計。"},{"en":"The contrast shows how different their burdens are.","zh":"這個對比顯示他們的負擔多麼不同。"}],"source":"2014 Q9.pdf","sourcePage":8},{"front":"laundry queues","meaning":"洗衣輪候隊伍","examples":[{"en":"Students argued about laundry queues in the hall.","zh":"學生在宿舍為洗衣輪候隊伍爭論。"},{"en":"Laundry queues are lines of people waiting to use washing machines or dryers.","zh":"洗衣輪候隊伍是等待使用洗衣機或乾衣機的人龍。"},{"en":"Long laundry queues can annoy students during busy weekends.","zh":"週末忙碌時，長長的洗衣輪候隊伍可能令學生煩躁。"},{"en":"Such queues are ordinary hall problems, not life-changing crises.","zh":"這類隊伍是普通宿舍問題，不是改變人生的危機。"},{"en":"The phrase shows how small student worries look beside Chris’s family burden.","zh":"這個短語顯示學生小煩惱和 Chris 家庭負擔相比多麼微小。"}],"source":"2014 Q9.pdf","sourcePage":8},{"front":"tutorial readings","meaning":"導修課閱讀材料","examples":[{"en":"Students complained about tutorial readings.","zh":"學生抱怨導修課閱讀材料。"},{"en":"Tutorial readings are texts students must read before small-group university classes.","zh":"導修課閱讀材料是學生在大學小組課前必須閱讀的文本。"},{"en":"A student may complain when tutorial readings are long and difficult.","zh":"當導修課閱讀材料又長又難時，學生可能會抱怨。"},{"en":"These readings can feel heavy, but they are still part of ordinary student life.","zh":"這些閱讀材料可能感覺沉重，但仍屬普通學生生活。"},{"en":"Chris’s problems make tutorial readings seem lighter than family survival.","zh":"Chris 的問題令導修課閱讀材料看起來比家庭生計輕得多。"}],"source":"2014 Q9.pdf","sourcePage":8},{"front":"every bowl of rice","meaning":"每一碗飯","examples":[{"en":"At home, every bowl of rice mattered.","zh":"在家裏，每一碗飯都重要。"},{"en":"Every bowl of rice means even the smallest amount of food or money is important.","zh":"每一碗飯意思是連最小份量的食物或金錢也重要。"},{"en":"In a struggling family, every bowl of rice may represent work, cost, and care.","zh":"在艱難家庭中，每一碗飯可能代表工作、成本和關心。"},{"en":"This phrase explains why Chris reacts strongly to wasted food.","zh":"這個短語解釋了為何 Chris 對浪費食物反應強烈。"},{"en":"For Chris, food is not decoration; every bowl of rice carries responsibility.","zh":"對 Chris 來說，食物不是裝飾；每一碗飯都承載責任。"}],"source":"2014 Q9.pdf","sourcePage":8},{"front":"electricity bill","meaning":"電費單","examples":[{"en":"Every electricity bill mattered to Chris’s family.","zh":"每張電費單對 Chris 的家庭都重要。"},{"en":"An electricity bill is the amount of money a household or business pays for electricity.","zh":"電費單是家庭或企業為用電支付的金額。"},{"en":"A small restaurant may worry about electricity bills if business is weak.","zh":"如果生意不好，小餐廳可能會擔心電費單。"},{"en":"Bills matter more when a family has little spare money.","zh":"當家庭沒有太多餘錢時，帳單會更加重要。"},{"en":"The electricity bill shows the practical pressure behind Chris’s quiet face.","zh":"電費單顯示 Chris 安靜表情背後的實際壓力。"}],"source":"2014 Q9.pdf","sourcePage":8},{"front":"tired customer","meaning":"疲倦的顧客","examples":[{"en":"Every tired customer mattered at the cha chaan teng.","zh":"在茶餐廳裏，每位疲倦的顧客都重要。"},{"en":"A tired customer is a customer who is weary, impatient, or in need of quick service.","zh":"疲倦的顧客是感到疲憊、不耐煩或需要快速服務的顧客。"},{"en":"A tired customer may become upset if food arrives late.","zh":"如果食物遲到，疲倦的顧客可能會不滿。"},{"en":"For a small restaurant, each customer matters because income depends on them.","zh":"對小餐廳來說，每位顧客都重要，因為收入依賴他們。"},{"en":"Chris understands that even one tired customer can affect his family’s day.","zh":"Chris 明白即使一位疲倦的顧客，也可能影響家裏一天的生意。"}],"source":"2014 Q9.pdf","sourcePage":8},{"front":"all the while","meaning":"與此同時","examples":[{"en":"All the while, Chris had been trying to manage both lives.","zh":"與此同時，Chris 一直嘗試管理兩種生活。"},{"en":"All the while means during the whole time something else was happening.","zh":"與此同時意思是在另一件事發生的整段時間中。"},{"en":"Friends laughed in the common room; all the while, Chris worried about home.","zh":"朋友在交誼廳大笑；與此同時，Chris 擔心著家裏。"},{"en":"This phrase reveals a hidden reality behind ordinary scenes.","zh":"這個短語揭示普通場景背後的隱藏現實。"},{"en":"It shows that Chris’s pressure existed even when others did not see it.","zh":"它顯示即使別人看不見，Chris 的壓力仍一直存在。"}],"source":"2014 Q9.pdf","sourcePage":8},{"front":"make both lives fit into","meaning":"將兩種生活塞進","examples":[{"en":"Chris tried to make both lives fit into one exhausted body.","zh":"Chris 嘗試將兩種生活塞進一個疲憊的身體。"},{"en":"To make both lives fit into something means to force two heavy roles into one limited space or person.","zh":"將兩種生活塞進某處，意思是把兩種沉重角色強行放進有限空間或一個人身上。"},{"en":"A working student may try to fit study and family duty into one tired day.","zh":"半工讀學生可能嘗試把學習和家庭責任塞進疲憊的一天。"},{"en":"The phrase shows how impossible Chris’s situation has become.","zh":"這個短語顯示 Chris 的處境已變得多麼不可能承受。"},{"en":"His body is exhausted because two lives are demanding more than one person can give.","zh":"他的身體疲憊，因為兩種生活要求的超過一個人能給予的。"}],"source":"2014 Q9.pdf","sourcePage":8},{"front":"exhausted body","meaning":"疲憊的身體","examples":[{"en":"Chris was carrying two lives in one exhausted body.","zh":"Chris 用一個疲憊的身體承載兩種生活。"},{"en":"An exhausted body is a body that is extremely tired from work, stress, or lack of rest.","zh":"疲憊的身體是因工作、壓力或缺乏休息而極度疲倦的身體。"},{"en":"A student may have an exhausted body after studying all night and working all day.","zh":"學生整晚溫習、整天工作後，可能有疲憊的身體。"},{"en":"Exhaustion affects not only energy but also patience and emotion.","zh":"疲憊不只影響精力，也影響耐性和情緒。"},{"en":"Chris’s exhausted body shows the cost of trying to be needed everywhere.","zh":"Chris 疲憊的身體顯示他嘗試在每個地方都被需要的代價。"}],"source":"2014 Q9.pdf","sourcePage":9},{"front":"the last straw","meaning":"最後一擊；壓垮人的最後一根稻草","examples":[{"en":"The last straw came on a rainy Thursday.","zh":"最後一擊出現在一個下雨的星期四。"},{"en":"The last straw is the final problem that makes a difficult situation impossible to continue.","zh":"最後一擊是令困難情況再也無法持續的最後一個問題。"},{"en":"A missed deadline may be the last straw after weeks of poor teamwork.","zh":"數星期團隊合作不佳後，錯過期限可能成為最後一擊。"},{"en":"The phrase suggests that many problems already existed before the final one.","zh":"這個短語暗示在最後問題之前，已有許多問題存在。"},{"en":"Chris’s mother fainting becomes the last straw that forces him to leave hall.","zh":"Chris 的母親暈倒，成為迫使他離開宿舍的最後一擊。"}],"source":"2014 Q9.pdf","sourcePage":9},{"front":"rainy Thursday","meaning":"下雨的星期四","examples":[{"en":"The last straw came on a rainy Thursday.","zh":"最後一擊出現在一個下雨的星期四。"},{"en":"A rainy Thursday is a Thursday marked by rain, often giving a scene a gloomy mood.","zh":"下雨的星期四是有雨的星期四，常令場景帶有陰沉氣氛。"},{"en":"A rainy Thursday can make bad news feel even heavier.","zh":"下雨的星期四可以令壞消息感覺更沉重。"},{"en":"Weather details help readers feel the sadness and urgency of the moment.","zh":"天氣細節幫助讀者感受那一刻的悲傷和迫切。"},{"en":"In the story, the rain matches the family crisis.","zh":"在故事中，雨水與家庭危機互相呼應。"}],"source":"2014 Q9.pdf","sourcePage":9},{"front":"revise in bed","meaning":"在床上溫習","examples":[{"en":"I was revising in bed when Chris’s phone rang.","zh":"Chris 的電話響起時，我正在床上溫習。"},{"en":"To revise in bed means to study or review lessons while sitting or lying on a bed.","zh":"在床上溫習意思是坐在或躺在床上學習或重溫課業。"},{"en":"A tired student may revise in bed before an exam.","zh":"疲倦學生可能在考試前在床上溫習。"},{"en":"Revising in bed suggests an ordinary student night before crisis interrupts it.","zh":"在床上溫習暗示普通學生夜晚，然後危機突然打斷它。"},{"en":"The narrator’s quiet study contrasts with Chris’s sudden emergency.","zh":"敘述者安靜溫習，與 Chris 的突然緊急情況形成對比。"}],"source":"2014 Q9.pdf","sourcePage":9},{"front":"phone rang","meaning":"電話響起","examples":[{"en":"Chris’s phone rang while I was revising.","zh":"我正在溫習時，Chris 的電話響起。"},{"en":"Phone rang means the telephone made a sound because someone was calling.","zh":"電話響起意思是因有人來電，電話發出聲音。"},{"en":"A phone ringing at night can create worry before anyone answers it.","zh":"夜晚電話響起，在接聽之前已可能令人擔心。"},{"en":"Repeated ringing becomes frightening when it often brings bad news.","zh":"當電話常帶來壞消息時，反覆響起會變得可怕。"},{"en":"In the story, the phone ring is almost a signal of family crisis.","zh":"在故事中，電話響聲幾乎是家庭危機的訊號。"}],"source":"2014 Q9.pdf","sourcePage":9},{"front":"listen for three seconds","meaning":"聽了三秒鐘","examples":[{"en":"Chris listened for three seconds, then stood up suddenly.","zh":"Chris 聽了三秒鐘，然後突然站起來。"},{"en":"To listen for three seconds means to hear something briefly before reacting.","zh":"聽了三秒鐘意思是短暫聽了一下，然後作出反應。"},{"en":"A person may listen for three seconds and immediately know the news is serious.","zh":"一個人可能聽了三秒鐘，就立刻知道消息很嚴重。"},{"en":"The short time shows how quickly Chris understands the emergency.","zh":"這段短時間顯示 Chris 多快理解緊急情況。"},{"en":"Three seconds are enough because he already knows his family’s situation.","zh":"三秒鐘已經足夠，因為他早已知道家裏的情況。"}],"source":"2014 Q9.pdf","sourcePage":9},{"front":"stand up so fast that","meaning":"站起來快得……","examples":[{"en":"Chris stood up so fast that his chair hit the wall.","zh":"Chris 站起來快得椅子撞到牆。"},{"en":"To stand up so fast that something happens means to rise suddenly with great urgency.","zh":"站起來快得某事發生，意思是非常急速地站起來。"},{"en":"A student may stand up so fast that books fall when hearing bad news.","zh":"學生聽到壞消息時，可能站起來快得書本掉下來。"},{"en":"The action shows panic before Chris explains anything.","zh":"這個動作在 Chris 解釋任何事情前先顯示驚慌。"},{"en":"His body reacts faster than his words because the call is urgent.","zh":"他的身體比說話反應更快，因為那通電話很緊急。"}],"source":"2014 Q9.pdf","sourcePage":9},{"front":"chair hit the wall","meaning":"椅子撞到牆","examples":[{"en":"His chair hit the wall when he stood up.","zh":"他站起來時，椅子撞到牆。"},{"en":"Chair hit the wall means the chair knocked against the wall with force.","zh":"椅子撞到牆意思是椅子用力碰到牆壁。"},{"en":"A sudden movement may make furniture hit the wall loudly.","zh":"突然動作可能令家具大聲撞到牆。"},{"en":"The sound makes the emergency feel sharp and physical.","zh":"那聲響令緊急情況變得尖銳而具體。"},{"en":"The chair hitting the wall shows that Chris has no time to act calmly.","zh":"椅子撞到牆顯示 Chris 沒有時間冷靜行動。"}],"source":"2014 Q9.pdf","sourcePage":9},{"front":"faint at the shop","meaning":"在店裏暈倒","examples":[{"en":"Chris’s mother fainted at the shop.","zh":"Chris 的母親在店裏暈倒。"},{"en":"To faint at the shop means to lose consciousness while at the workplace or store.","zh":"在店裏暈倒意思是在工作地點或店舖失去知覺。"},{"en":"A tired worker may faint at the shop after standing for too many hours.","zh":"疲倦工作者站立太多小時後，可能在店裏暈倒。"},{"en":"Fainting shows the body has reached a limit.","zh":"暈倒顯示身體已達到極限。"},{"en":"Chris’s mother fainting makes the family crisis impossible to ignore.","zh":"Chris 母親暈倒，令家庭危機無法再被忽視。"}],"source":"2014 Q9.pdf","sourcePage":9},{"front":"run through the rain","meaning":"冒雨跑過","examples":[{"en":"We ran through the rain to the bus stop.","zh":"我們冒雨跑到巴士站。"},{"en":"To run through the rain means to run while rain is falling on you.","zh":"冒雨跑過意思是在下雨時跑過去。"},{"en":"Students may run through the rain when they are late for the last bus.","zh":"學生趕尾班車時可能冒雨跑過去。"},{"en":"Running through rain suggests urgency, discomfort, and worry.","zh":"冒雨奔跑暗示迫切、不舒服和擔憂。"},{"en":"The narrator follows Chris through the rain and begins to enter his other life.","zh":"敘述者跟著 Chris 冒雨跑，開始進入他的另一種生活。"}],"source":"2014 Q9.pdf","sourcePage":9},{"front":"bus stop","meaning":"巴士站","examples":[{"en":"We ran to the bus stop in the rain.","zh":"我們在雨中跑到巴士站。"},{"en":"A bus stop is a place where buses pick up and drop off passengers.","zh":"巴士站是巴士接載和放下乘客的地方。"},{"en":"Students may wait at a bus stop after a late lecture.","zh":"學生可能在深夜課堂後於巴士站等車。"},{"en":"A bus stop can become a place of anxiety when someone is rushing to an emergency.","zh":"當某人趕往緊急情況時，巴士站可以成為焦慮之地。"},{"en":"In the story, the bus stop begins the journey from hall to family crisis.","zh":"在故事中，巴士站開始了由宿舍到家庭危機的旅程。"}],"source":"2014 Q9.pdf","sourcePage":10},{"front":"share one umbrella badly","meaning":"笨拙地共用一把傘","examples":[{"en":"We shared one umbrella badly as we ran.","zh":"我們一邊跑，一邊笨拙地共用一把傘。"},{"en":"To share one umbrella badly means two people use one umbrella awkwardly and still get wet.","zh":"笨拙地共用一把傘意思是兩個人不熟練地用同一把傘，結果仍被淋濕。"},{"en":"Friends may share one umbrella badly when the rain is heavy and the pavement is narrow.","zh":"雨很大、行人路又窄時，朋友可能笨拙地共用一把傘。"},{"en":"The phrase shows movement, closeness, and helplessness at the same time.","zh":"這個短語同時顯示行動、親近和無助。"},{"en":"Their awkward umbrella sharing makes the emergency feel real and human.","zh":"他們笨拙地共用雨傘，令緊急情況感覺真實而有人性。"}],"source":"2014 Q9.pdf","sourcePage":10},{"front":"by the time we reached","meaning":"到我們到達……時","examples":[{"en":"By the time we reached the restaurant, Mary was crying.","zh":"到我們到達餐廳時，Mary 正在哭。"},{"en":"By the time we reached means when we arrived at that place, something was already happening.","zh":"到我們到達某地時，意思是我們抵達時，某事已經在發生。"},{"en":"By the time we reached school, the assembly had already started.","zh":"到我們到達學校時，早會已經開始。"},{"en":"The phrase shows that events moved faster than the people travelling there.","zh":"這個短語顯示事件發展比趕路的人更快。"},{"en":"When they reach the restaurant, the crisis is already visible.","zh":"當他們到達餐廳時，危機已經清楚可見。"}],"source":"2014 Q9.pdf","sourcePage":10},{"front":"beside the cashier","meaning":"在收銀處旁邊","examples":[{"en":"Mary was crying beside the cashier.","zh":"Mary 在收銀處旁邊哭。"},{"en":"Beside the cashier means next to the payment counter or person handling money.","zh":"在收銀處旁邊意思是在付款櫃位或收錢的人旁邊。"},{"en":"A child may wait beside the cashier while parents pay for a meal.","zh":"父母付款時，孩子可能在收銀處旁邊等候。"},{"en":"Seeing Mary cry there shows that the family crisis has entered the public shop space.","zh":"看見 Mary 在那裏哭，顯示家庭危機已進入公開店舖空間。"},{"en":"The place makes her fear feel exposed and helpless.","zh":"這個位置令她的恐懼顯得暴露而無助。"}],"source":"2014 Q9.pdf","sourcePage":10},{"front":"pale with pain","meaning":"痛得臉色蒼白","examples":[{"en":"Chris’s father was pale with pain.","zh":"Chris 的父親痛得臉色蒼白。"},{"en":"Pale with pain means someone’s face has lost colour because they are suffering.","zh":"痛得臉色蒼白意思是因痛苦而臉上失去血色。"},{"en":"A worker may look pale with pain after injuring his back.","zh":"工作者弄傷背部後可能痛得臉色蒼白。"},{"en":"This expression lets readers see physical suffering clearly.","zh":"這個表達讓讀者清楚看見身體痛苦。"},{"en":"Chris’s father is still apologising even while pale with pain.","zh":"Chris 的父親即使痛得臉色蒼白，仍在向顧客道歉。"}],"source":"2014 Q9.pdf","sourcePage":10},{"front":"apologise to customers","meaning":"向顧客道歉","examples":[{"en":"Chris’s father was apologising to customers.","zh":"Chris 的父親正在向顧客道歉。"},{"en":"To apologise to customers means to say sorry to people who are buying or receiving service.","zh":"向顧客道歉意思是向正在購買或接受服務的人說對不起。"},{"en":"A waiter may apologise to customers when food is delayed.","zh":"食物延誤時，侍應可能向顧客道歉。"},{"en":"Apologising while injured shows the pressure of running a small restaurant.","zh":"受傷時仍道歉，顯示經營小餐廳的壓力。"},{"en":"Chris’s father puts customers first even when his body is failing.","zh":"Chris 的父親即使身體撐不住，仍把顧客放在前面。"}],"source":"2014 Q9.pdf","sourcePage":10},{"front":"steam clouded the windows","meaning":"蒸氣令窗戶變得模糊","examples":[{"en":"Steam clouded the restaurant windows.","zh":"蒸氣令餐廳窗戶變得模糊。"},{"en":"Steam clouded the windows means hot vapour made the glass look misty or unclear.","zh":"蒸氣令窗戶變得模糊，意思是熱蒸氣令玻璃看起來朦朧不清。"},{"en":"Steam can cloud kitchen windows when noodles are boiling.","zh":"煮麵時，蒸氣可能令廚房窗戶變得模糊。"},{"en":"Clouded windows make the restaurant feel hot, busy, and trapped.","zh":"模糊的窗戶令餐廳感覺炎熱、忙碌和困住。"},{"en":"The image helps readers feel the pressure inside the cha chaan teng.","zh":"這個意象幫助讀者感受茶餐廳裏的壓力。"}],"source":"2014 Q9.pdf","sourcePage":10},{"front":"orders were clipped above the stove","meaning":"菜單夾在爐上方","examples":[{"en":"Orders were clipped above the stove like small white flags.","zh":"菜單像一面面小白旗一樣夾在爐上方。"},{"en":"This means customers’ order papers were held above the cooking area with clips.","zh":"這句話意思是顧客的點餐紙用夾子固定在煮食區上方。"},{"en":"In a busy restaurant, orders may be clipped near the stove so cooks can read them quickly.","zh":"在忙碌餐廳中，訂單可能夾在爐旁，讓廚師快速閱讀。"},{"en":"The clipped orders show that the shop is still running despite crisis.","zh":"夾著的訂單顯示即使危機出現，店舖仍在運作。"},{"en":"The image turns ordinary order slips into signs of pressure and surrender.","zh":"這個意象把普通訂單變成壓力和投降的標誌。"}],"source":"2014 Q9.pdf","sourcePage":10},{"front":"above the stove","meaning":"在爐上方","examples":[{"en":"The orders were clipped above the stove.","zh":"訂單被夾在爐上方。"},{"en":"Above the stove means higher than the cooking area or cooker.","zh":"在爐上方意思是在煮食位置或爐具上面。"},{"en":"A cook may hang order slips above the stove to see them clearly.","zh":"廚師可能把訂單掛在爐上方，方便看清楚。"},{"en":"The space above the stove becomes a place where work keeps piling up.","zh":"爐上方的空間成為工作不斷堆積的地方。"},{"en":"In the story, even the position of the orders shows pressure.","zh":"在故事中，連訂單的位置也顯示壓力。"}],"source":"2014 Q9.pdf","sourcePage":10},{"front":"like small white flags","meaning":"像一面面小白旗","examples":[{"en":"The orders looked like small white flags.","zh":"那些訂單看起來像一面面小白旗。"},{"en":"Like small white flags compares order slips to little flags, suggesting surrender or distress.","zh":"像一面面小白旗把訂單紙比作小旗，暗示投降或困境。"},{"en":"Receipts hanging in a kitchen may look like small white flags during a dinner rush.","zh":"晚飯繁忙時，廚房裏掛著的收據可能像一面面小白旗。"},{"en":"The image makes ordinary paper feel symbolic.","zh":"這個意象令普通紙張帶有象徵意義。"},{"en":"It suggests the family is fighting a battle they can barely manage.","zh":"它暗示這家人正在打一場幾乎應付不來的仗。"}],"source":"2014 Q9.pdf","sourcePage":10},{"front":"did not hesitate","meaning":"毫不猶豫","examples":[{"en":"Chris did not hesitate when he saw the situation.","zh":"Chris 看見情況後毫不猶豫。"},{"en":"Did not hesitate means acted immediately without delay or uncertainty.","zh":"毫不猶豫意思是沒有延遲或不確定，立即行動。"},{"en":"A responsible student does not hesitate to help when a friend faints.","zh":"朋友暈倒時，負責任的學生會毫不猶豫地幫忙。"},{"en":"Chris’s quick action shows that this crisis is familiar to him.","zh":"Chris 快速行動，顯示這種危機對他來說很熟悉。"},{"en":"He does not ask for praise; he simply begins to work.","zh":"他沒有要求稱讚；他只是開始工作。"}],"source":"2014 Q9.pdf","sourcePage":11},{"front":"take off his wet jacket","meaning":"脫下濕外套","examples":[{"en":"Chris took off his wet jacket.","zh":"Chris 脫下濕外套。"},{"en":"To take off his wet jacket means to remove a rain-soaked coat before doing something else.","zh":"脫下濕外套意思是在做其他事前除下被雨淋濕的外衣。"},{"en":"A worker may take off a wet jacket before stepping into a kitchen.","zh":"工作者走進廚房前可能脫下濕外套。"},{"en":"This action marks Chris’s change from student to family helper.","zh":"這個行動標誌 Chris 由學生轉為家庭幫手。"},{"en":"Removing the jacket is like putting aside university life for the night.","zh":"脫下外套就像把那一晚的大學生活放到一旁。"}],"source":"2014 Q9.pdf","sourcePage":11},{"front":"tie on an apron","meaning":"繫上圍裙","examples":[{"en":"Chris tied on an apron and began to work.","zh":"Chris 繫上圍裙，開始工作。"},{"en":"To tie on an apron means to put on an apron and fasten it before cooking or serving.","zh":"繫上圍裙意思是在煮食或服務前穿上並綁好圍裙。"},{"en":"A restaurant worker ties on an apron before entering the kitchen.","zh":"餐廳員工進廚房前會繫上圍裙。"},{"en":"The apron shows that Chris knows exactly what role he must take.","zh":"圍裙顯示 Chris 清楚知道自己必須承擔甚麼角色。"},{"en":"In that moment, he becomes not a guest but part of the shop.","zh":"在那一刻，他不再是客人，而是店裏的一部分。"}],"source":"2014 Q9.pdf","sourcePage":11},{"front":"step behind the counter","meaning":"走到櫃位後面","examples":[{"en":"Chris stepped behind the counter.","zh":"Chris 走到櫃位後面。"},{"en":"To step behind the counter means to move to the staff side of a shop or restaurant.","zh":"走到櫃位後面意思是移到店舖或餐廳的員工一邊。"},{"en":"Customers usually stay in front, while workers stand behind the counter.","zh":"顧客通常站在前面，員工則站在櫃位後面。"},{"en":"Chris stepping behind the counter shows he belongs to the working side of the restaurant.","zh":"Chris 走到櫃位後面，顯示他屬於餐廳工作的那一邊。"},{"en":"The action reveals the life his hall friends rarely see.","zh":"這個動作揭示了宿舍朋友很少看見的生活。"}],"source":"2014 Q9.pdf","sourcePage":11},{"front":"chop spring onions","meaning":"切蔥","examples":[{"en":"Chris chopped spring onions behind the counter.","zh":"Chris 在櫃位後面切蔥。"},{"en":"To chop spring onions means to cut green onions into small pieces.","zh":"切蔥意思是把青蔥切成小段。"},{"en":"A cook may chop spring onions quickly before adding them to noodles.","zh":"廚師可能在把蔥加進麵之前快速切蔥。"},{"en":"This ordinary kitchen task shows Chris’s practical skill.","zh":"這個普通廚房任務顯示 Chris 的實際技能。"},{"en":"The detail makes his family role visible and specific.","zh":"這個細節令他的家庭角色變得可見而具體。"}],"source":"2014 Q9.pdf","sourcePage":11},{"front":"carry bowls","meaning":"端碗","examples":[{"en":"Chris carried bowls to customers.","zh":"Chris 把碗端給顧客。"},{"en":"To carry bowls means to bring bowls of food from the kitchen to tables.","zh":"端碗意思是把盛著食物的碗由廚房拿到餐桌。"},{"en":"A waiter carries bowls carefully so hot soup does not spill.","zh":"侍應會小心端碗，以免熱湯灑出。"},{"en":"Carrying bowls during a rush requires speed and attention.","zh":"在繁忙時段端碗需要速度和專注。"},{"en":"Chris’s actions show he has done this work many times before.","zh":"Chris 的動作顯示他以前已做過很多次這種工作。"}],"source":"2014 Q9.pdf","sourcePage":11},{"front":"wipe tables","meaning":"抹枱","examples":[{"en":"Chris wiped tables during the dinner rush.","zh":"Chris 在晚飯繁忙時段抹枱。"},{"en":"To wipe tables means to clean table surfaces with a cloth.","zh":"抹枱意思是用布清潔桌面。"},{"en":"Restaurant workers wipe tables quickly so new customers can sit down.","zh":"餐廳員工會快速抹枱，好讓新顧客坐下。"},{"en":"Wiping tables is simple, but during a rush it becomes urgent work.","zh":"抹枱很簡單，但在繁忙時段會變成急迫工作。"},{"en":"Chris wipes tables because every small task keeps the shop moving.","zh":"Chris 抹枱，因為每個小任務都能令店舖繼續運作。"}],"source":"2014 Q9.pdf","sourcePage":11},{"front":"comfort someone between orders","meaning":"在處理訂單之間安慰某人","examples":[{"en":"Chris comforted Mary between orders.","zh":"Chris 在處理訂單之間安慰 Mary。"},{"en":"To comfort someone between orders means to console a person briefly while still handling restaurant work.","zh":"在處理訂單之間安慰某人，意思是在仍要處理餐廳工作的同時短暫安慰對方。"},{"en":"A brother may comfort his sister between serving dishes and answering customers.","zh":"哥哥可能在上菜和回應顧客之間安慰妹妹。"},{"en":"This phrase shows how care and work are mixed in Chris’s family life.","zh":"這個短語顯示 Chris 的家庭生活中，關心和工作混在一起。"},{"en":"Chris has no quiet moment to comfort Mary fully, so he does it between tasks.","zh":"Chris 沒有安靜時刻完整地安慰 Mary，所以只能在任務之間做。"}],"source":"2014 Q9.pdf","sourcePage":11},{"front":"between orders","meaning":"在一道道訂單之間","examples":[{"en":"Chris comforted Mary between orders.","zh":"Chris 在一道道訂單之間安慰 Mary。"},{"en":"Between orders means in the short spaces of time between customers’ food requests.","zh":"在一道道訂單之間意思是在顧客點餐要求之間的短暫時間。"},{"en":"A waiter may drink water between orders during a busy shift.","zh":"侍應在繁忙班次中可能在一道道訂單之間喝水。"},{"en":"The phrase shows that even emotional care must fit around work.","zh":"這個短語顯示連情感關心也必須配合工作空隙。"},{"en":"Chris’s family has no pause long enough for proper rest.","zh":"Chris 的家庭沒有足夠長的停頓來真正休息。"}],"source":"2014 Q9.pdf","sourcePage":11},{"front":"stand there uselessly","meaning":"無助地站在那裏","examples":[{"en":"I stood there uselessly until Chris gave me a cloth.","zh":"我無助地站在那裏，直到 Chris 給我一塊布。"},{"en":"To stand there uselessly means to remain in place without knowing how to help.","zh":"無助地站在那裏意思是留在原地，不知道如何幫忙。"},{"en":"A person may stand there uselessly during an emergency if they have no instructions.","zh":"如果沒有指示，一個人在緊急情況中可能無助地站著。"},{"en":"The narrator feels useless because Chris belongs to this crisis and he does not.","zh":"敘述者感到無助，因為 Chris 屬於這場危機，而他不是。"},{"en":"Chris gives him a cloth so helplessness can become action.","zh":"Chris 給他一塊布，讓無助變成行動。"}],"source":"2014 Q9.pdf","sourcePage":11},{"front":"hand someone a cloth","meaning":"遞給某人一塊布","examples":[{"en":"Chris handed me a cloth and told me to wipe a table.","zh":"Chris 遞給我一塊布，叫我抹一張枱。"},{"en":"To hand someone a cloth means to give a cleaning cloth to that person.","zh":"遞給某人一塊布意思是把清潔用的布交給那個人。"},{"en":"A restaurant worker may hand a new helper a cloth and point to a dirty table.","zh":"餐廳員工可能遞給新幫手一塊布，並指向髒枱。"},{"en":"Giving a cloth is a simple way to turn someone into a useful helper.","zh":"給一塊布是把某人變成有用幫手的簡單方式。"},{"en":"Chris does not explain much because the shop needs action immediately.","zh":"Chris 沒有解釋太多，因為店裏立即需要行動。"}],"source":"2014 Q9.pdf","sourcePage":12},{"front":"table three","meaning":"三號枱","examples":[{"en":"Chris told me to wipe table three.","zh":"Chris 叫我抹三號枱。"},{"en":"Table three means the restaurant table identified by the number three.","zh":"三號枱是餐廳中以數字三標示的桌子。"},{"en":"Staff use numbers like table three to organise service quickly.","zh":"員工用三號枱這類編號快速組織服務。"},{"en":"A helper can act faster when the instruction is specific.","zh":"當指示具體時，幫手可以更快行動。"},{"en":"The phrase places the narrator inside the restaurant’s working rhythm.","zh":"這個短語把敘述者放進餐廳的工作節奏中。"}],"source":"2014 Q9.pdf","sourcePage":12},{"front":"at three in the morning","meaning":"凌晨三點","examples":[{"en":"At three in the morning, we returned to hall.","zh":"凌晨三點，我們回到宿舍。"},{"en":"At three in the morning means at 3 a.m., very late at night or very early before dawn.","zh":"凌晨三點意思是上午三時，非常深夜或天亮前很早的時間。"},{"en":"Students returning at three in the morning are usually exhausted.","zh":"凌晨三點回來的學生通常筋疲力盡。"},{"en":"The time shows how long the emergency lasted.","zh":"這個時間顯示緊急情況持續了多久。"},{"en":"Returning to hall at that hour makes Chris’s university life feel impossible.","zh":"那個時間回到宿舍，令 Chris 的大學生活顯得無法承受。"}],"source":"2014 Q9.pdf","sourcePage":12},{"front":"without turning on the light","meaning":"沒有開燈","examples":[{"en":"Chris sat on his bed without turning on the light.","zh":"Chris 坐在床上，沒有開燈。"},{"en":"Without turning on the light means leaving the room dark while doing something.","zh":"沒有開燈意思是在做某事時讓房間保持黑暗。"},{"en":"A tired person may sit in darkness without turning on the light because they have no energy.","zh":"疲倦的人可能沒有力氣開燈，只坐在黑暗中。"},{"en":"Darkness can show sadness, silence, or emotional heaviness.","zh":"黑暗可以顯示悲傷、沉默或情緒沉重。"},{"en":"Chris’s choice not to turn on the light reflects how defeated he feels.","zh":"Chris 沒有開燈，反映他感到多麼無力。"}],"source":"2014 Q9.pdf","sourcePage":12},{"front":"commute from home","meaning":"從家中通勤上學","examples":[{"en":"Chris planned to commute from home.","zh":"Chris 計劃從家中通勤上學。"},{"en":"To commute from home means to travel regularly from home to school or work.","zh":"從家中通勤上學意思是定期由家往返學校或工作地點。"},{"en":"A student may commute from home by bus instead of living in hall.","zh":"學生可能乘巴士從家中通勤上學，而不是住在宿舍。"},{"en":"Commuting from home lets Chris stay close to his family’s shop.","zh":"從家中通勤讓 Chris 能靠近家裏的店。"},{"en":"The plan shows he is choosing responsibility over convenience.","zh":"這個計劃顯示他選擇責任，而不是方便。"}],"source":"2014 Q9.pdf","sourcePage":12},{"front":"take fewer courses","meaning":"修讀較少科目","examples":[{"en":"Chris thought he might take fewer courses.","zh":"Chris 想自己可能會修讀較少科目。"},{"en":"To take fewer courses means to enrol in a smaller number of classes.","zh":"修讀較少科目意思是報讀較少課程。"},{"en":"A student may take fewer courses when family duties become too heavy.","zh":"當家庭責任太重時，學生可能會修讀較少科目。"},{"en":"Taking fewer courses can reduce pressure but may delay graduation.","zh":"修讀較少科目可以減少壓力，但可能延遲畢業。"},{"en":"Chris considers this because his life cannot hold everything at once.","zh":"Chris 考慮這樣做，因為他的生活無法同時承載所有事情。"}],"source":"2014 Q9.pdf","sourcePage":12},{"front":"that sudden","meaning":"那麼突然","examples":[{"en":"I asked Chris why he was leaving so suddenly.","zh":"我問 Chris 為何離開得那麼突然。"},{"en":"That sudden means happening in a way that seems quick or unexpected.","zh":"那麼突然意思是事情看起來很快或出乎意料地發生。"},{"en":"A roommate’s decision to move out may feel that sudden if no one knows the background.","zh":"如果沒有人知道背景，室友搬走的決定可能感覺那麼突然。"},{"en":"What looks sudden to outsiders may have been building for months.","zh":"對外人看似突然的事，可能已累積數月。"},{"en":"Chris teaches the narrator that suddenness depends on what we have noticed.","zh":"Chris 讓敘述者明白，突然與否取決於我們有沒有注意。"}],"source":"2014 Q9.pdf","sourcePage":12},{"front":"not angrily, but sadly","meaning":"不是憤怒地，而是傷心地","examples":[{"en":"Chris looked at me not angrily, but sadly.","zh":"Chris 望著我，不是憤怒地，而是傷心地。"},{"en":"Not angrily, but sadly contrasts the feeling someone might expect with the real feeling shown.","zh":"不是憤怒地，而是傷心地，把人可能預期的情緒和真正顯示的情緒作對比。"},{"en":"A teacher may look not angrily, but sadly, when a student gives up.","zh":"當學生放棄時，老師可能不是憤怒地，而是傷心地看著他。"},{"en":"The phrase shows that Chris is hurt rather than blaming the narrator.","zh":"這個短語顯示 Chris 是受傷，而不是責怪敘述者。"},{"en":"His sadness makes the explanation gentler and more painful.","zh":"他的傷心令解釋更溫柔，也更痛。"}],"source":"2014 Q9.pdf","sourcePage":12},{"front":"it only looks sudden if","meaning":"只有在……時才看似突然","examples":[{"en":"It only looks sudden if you have not been hearing the phone ring.","zh":"只有在你沒有一直聽見電話響時，它才看似突然。"},{"en":"It only looks sudden if means something seems unexpected only under a certain condition.","zh":"只有在……時才看似突然，意思是某事只有在特定條件下才顯得出乎意料。"},{"en":"A student’s silence only looks sudden if no one noticed weeks of tiredness.","zh":"如果沒有人注意數星期的疲倦，學生的沉默才看似突然。"},{"en":"The phrase explains that hidden signs can make a final action understandable.","zh":"這個短語解釋隱藏跡象可以令最後行動變得可理解。"},{"en":"Chris’s departure looks sudden only to those who missed the nightly calls.","zh":"Chris 的離開只對錯過每晚電話的人看似突然。"}],"source":"2014 Q9.pdf","sourcePage":12},{"front":"hear the phone ring","meaning":"聽見電話響","examples":[{"en":"I had not really understood what it meant to hear the phone ring every night.","zh":"我其實沒有真正明白每晚聽見電話響代表甚麼。"},{"en":"To hear the phone ring means to notice the sound of an incoming call.","zh":"聽見電話響意思是注意到來電的聲音。"},{"en":"Hearing a phone ring every night can become worrying if each call brings trouble.","zh":"如果每通電話都帶來麻煩，每晚聽見電話響會變得令人擔心。"},{"en":"The narrator heard the sound but did not understand its meaning.","zh":"敘述者聽見聲音，卻沒有理解它的意義。"},{"en":"Chris’s sentence turns an ordinary sound into a symbol of burden.","zh":"Chris 的話把普通聲音變成負擔的象徵。"}],"source":"2014 Q9.pdf","sourcePage":12},{"front":"have no answer","meaning":"無言以對","examples":[{"en":"After Chris spoke, I had no answer.","zh":"Chris 說完後，我無言以對。"},{"en":"To have no answer means to be unable to reply because the truth is too strong or painful.","zh":"無言以對意思是因真相太有力或太痛而無法回應。"},{"en":"A student may have no answer when a friend explains hidden suffering.","zh":"當朋友解釋隱藏痛苦時，學生可能會無言以對。"},{"en":"Silence can show shame, understanding, or helplessness.","zh":"沉默可以顯示羞愧、理解或無助。"},{"en":"The narrator has no answer because he finally sees what he failed to see.","zh":"敘述者無言以對，因為他終於看見自己一直未能看見的事。"}],"source":"2014 Q9.pdf","sourcePage":13},{"front":"his side of the room","meaning":"房間裏屬於他的那一邊","examples":[{"en":"Now his side of the room is empty.","zh":"現在房間裏屬於他的那一邊空了。"},{"en":"His side of the room means the half or area of the shared room that belonged to him.","zh":"房間裏屬於他的那一邊，是指共用房間中屬於他的半邊或區域。"},{"en":"In a dorm room, each roommate may have their own side of the room.","zh":"在宿舍房間中，每位室友可能有自己的一邊。"},{"en":"An empty side of the room can make absence feel physical.","zh":"空了的一邊可以令缺席感變得具體。"},{"en":"Chris’s empty side reminds the narrator that departure changes space as well as friendship.","zh":"Chris 空了的那一邊提醒敘述者，離開會改變空間，也改變友誼。"}],"source":"2014 Q9.pdf","sourcePage":13},{"front":"leave behind","meaning":"留下","examples":[{"en":"The kettle Chris left behind still whistles.","zh":"Chris 留下的水煲仍會發出聲響。"},{"en":"To leave behind something means to go away without taking it.","zh":"留下某物意思是離開時沒有把它帶走。"},{"en":"A student may leave behind books when moving out in a hurry.","zh":"學生匆忙搬走時可能留下書本。"},{"en":"Objects left behind can become reminders of the person who has gone.","zh":"被留下的物件可以成為離開者的提醒。"},{"en":"Chris leaves behind a kettle, but also leaves behind a lesson.","zh":"Chris 留下水煲，也留下了一課。"}],"source":"2014 Q9.pdf","sourcePage":13},{"front":"whistle whenever","meaning":"每當……便發出聲響","examples":[{"en":"The kettle whistles whenever the water boils.","zh":"每當水煲滾時，水煲便發出聲響。"},{"en":"Whistle whenever means to make a high sound every time a certain thing happens.","zh":"每當……便發出聲響，意思是每次某事發生時都發出高聲。"},{"en":"A kettle may whistle whenever steam pushes through its spout.","zh":"每當蒸氣從壺嘴冒出時，水煲可能便發出聲響。"},{"en":"Repeated sounds can bring back memories of a person.","zh":"反覆出現的聲音可以帶回對某人的回憶。"},{"en":"The kettle whistles whenever water boils, turning ordinary tea into remembrance.","zh":"每當水滾，水煲便響，把普通泡茶變成記憶。"}],"source":"2014 Q9.pdf","sourcePage":13},{"front":"water boils","meaning":"水煲滾","examples":[{"en":"The kettle whistles when the water boils.","zh":"水煲滾時，水煲會發出聲響。"},{"en":"Water boils when it becomes hot enough to bubble and turn into steam.","zh":"水煲滾意思是水熱到冒泡並變成蒸氣。"},{"en":"Students boil water to make tea, coffee, or instant noodles.","zh":"學生會煲水來沖茶、咖啡或杯麵。"},{"en":"Boiling water is ordinary, but in the story it carries loneliness.","zh":"水滾是普通事情，但在故事中它承載孤單。"},{"en":"The sound of water boiling reminds the narrator of Chris’s absence.","zh":"水煲滾的聲音提醒敘述者 Chris 的缺席。"}],"source":"2014 Q9.pdf","sourcePage":13},{"front":"fill the room with","meaning":"令房間充滿","examples":[{"en":"The kettle fills the room with a thin, lonely cry.","zh":"水煲令房間充滿微弱而孤單的聲音。"},{"en":"To fill the room with something means to spread a sound, smell, or feeling through the whole room.","zh":"令房間充滿某物，意思是讓聲音、氣味或感覺散佈整個房間。"},{"en":"Music can fill a room with warmth during a gathering.","zh":"聚會時，音樂可以令房間充滿溫暖。"},{"en":"The kettle’s sound fills the room because there is no longer another person’s noise.","zh":"水煲聲充滿房間，因為不再有另一個人的聲音。"},{"en":"The phrase makes loneliness feel like something that occupies space.","zh":"這個短語令孤單感覺像佔據空間的東西。"}],"source":"2014 Q9.pdf","sourcePage":13},{"front":"thin, lonely cry","meaning":"微弱而孤單的聲音","examples":[{"en":"The kettle made a thin, lonely cry.","zh":"水煲發出微弱而孤單的聲音。"},{"en":"A thin, lonely cry is a weak, high sound that suggests sadness or emptiness.","zh":"微弱而孤單的聲音是暗示悲傷或空蕩的細弱高聲。"},{"en":"A whistle in an empty room may sound like a thin, lonely cry.","zh":"空房間裏的哨聲可能聽起來像微弱而孤單的聲音。"},{"en":"The phrase gives emotion to an ordinary kettle sound.","zh":"這個短語把情感賦予普通水煲聲。"},{"en":"It shows how Chris’s absence changes the meaning of everyday noise.","zh":"它顯示 Chris 的缺席如何改變日常聲音的意義。"}],"source":"2014 Q9.pdf","sourcePage":13},{"front":"used to think","meaning":"以前以為","examples":[{"en":"I used to think people left because they had given up.","zh":"我以前以為人們離開是因為他們放棄了。"},{"en":"Used to think means believed something in the past but may not believe it now.","zh":"以前以為意思是過去相信某事，但現在可能不再相信。"},{"en":"I used to think quiet people had no worries, but I was wrong.","zh":"我以前以為安靜的人沒有憂慮，但我錯了。"},{"en":"This phrase prepares readers for a change in understanding.","zh":"這個短語讓讀者準備看到理解上的改變。"},{"en":"The narrator used to judge departure too simply.","zh":"敘述者以前把離開判斷得太簡單。"}],"source":"2014 Q9.pdf","sourcePage":13},{"front":"give up","meaning":"放棄","examples":[{"en":"I used to think people left because they had given up.","zh":"我以前以為人們離開是因為他們放棄了。"},{"en":"To give up means to stop trying because something feels too difficult.","zh":"放棄意思是因某事太困難而停止嘗試。"},{"en":"A student may feel tempted to give up after repeated failure.","zh":"學生反覆失敗後，可能想放棄。"},{"en":"Chris’s leaving is not giving up; it is choosing where he is needed most.","zh":"Chris 的離開不是放棄；而是選擇到最需要他的地方。"},{"en":"The story teaches that leaving can be responsibility, not defeat.","zh":"這個故事教我們，離開可以是責任，而不是失敗。"}],"source":"2014 Q9.pdf","sourcePage":13},{"front":"teach me otherwise","meaning":"令我明白並非如此","examples":[{"en":"Chris taught me otherwise.","zh":"Chris 令我明白並非如此。"},{"en":"To teach me otherwise means to make me understand that my earlier belief was wrong.","zh":"令我明白並非如此，意思是使我知道自己早前的想法是錯的。"},{"en":"I thought success meant high marks, but volunteering taught me otherwise.","zh":"我以為成功等於高分，但義工經驗令我明白並非如此。"},{"en":"Chris’s life teaches the narrator that departure can come from love and duty.","zh":"Chris 的生活令敘述者明白，離開可以源於愛和責任。"},{"en":"This phrase shows the narrator’s moral growth.","zh":"這個短語顯示敘述者的道德成長。"}],"source":"2014 Q9.pdf","sourcePage":13},{"front":"not because…, but because…","meaning":"不是因為……而是因為……","examples":[{"en":"Sometimes people leave not because they no longer belong, but because someone elsewhere needs them more.","zh":"有時人們離開，不是因為他們不再屬於這裏，而是因為別處有人更需要他們。"},{"en":"This structure contrasts a false reason with the real reason.","zh":"這個結構把錯誤原因和真正原因作對比。"},{"en":"A student may leave hall not because they dislike friends, but because family needs help.","zh":"學生離開宿舍，可能不是因為不喜歡朋友，而是因為家人需要幫忙。"},{"en":"The phrase helps correct a harsh judgement about leaving.","zh":"這個短語幫助糾正對離開的苛刻判斷。"},{"en":"It shows that departure can be an act of care.","zh":"它顯示離開可以是一種關心。"}],"source":"2014 Q9.pdf","sourcePage":14},{"front":"no longer belong","meaning":"不再屬於這裏","examples":[{"en":"Chris did not leave because he no longer belonged.","zh":"Chris 並不是因為不再屬於這裏而離開。"},{"en":"No longer belong means no longer feel accepted, connected, or part of a place.","zh":"不再屬於這裏意思是不再感到被接納、有連繫或是某地方的一部分。"},{"en":"A student may fear they no longer belong if friends stop inviting them.","zh":"如果朋友不再邀請自己，學生可能害怕自己不再屬於那裏。"},{"en":"Chris still belonged in the hall, but another place needed him more.","zh":"Chris 仍屬於宿舍，但另一個地方更需要他。"},{"en":"The phrase separates loss of belonging from responsibility to family.","zh":"這個短語把失去歸屬感和對家庭的責任區分開來。"}],"source":"2014 Q9.pdf","sourcePage":14},{"front":"someone elsewhere","meaning":"別處的某個人","examples":[{"en":"Someone elsewhere needed Chris more.","zh":"別處的某個人更需要 Chris。"},{"en":"Someone elsewhere means a person in another place.","zh":"別處的某個人意思是在另一個地方的人。"},{"en":"A student may leave school early because someone elsewhere in the family needs care.","zh":"學生可能提早離校，因為家中別處的某個人需要照顧。"},{"en":"The phrase keeps the focus on duty beyond the visible room.","zh":"這個短語把焦點放在可見房間以外的責任上。"},{"en":"In the story, someone elsewhere is Chris’s family at the cha chaan teng.","zh":"在故事中，別處的某個人就是 Chris 在茶餐廳的家人。"}],"source":"2014 Q9.pdf","sourcePage":14},{"front":"need them more","meaning":"更需要他們","examples":[{"en":"Sometimes people leave because someone elsewhere needs them more.","zh":"有時人們離開，是因為別處有人更需要他們。"},{"en":"Need them more means require their help, care, or presence more urgently than another place does.","zh":"更需要他們意思是比另一個地方更迫切需要他們的幫助、關心或陪伴。"},{"en":"A student may leave a party because a sick parent needs them more at home.","zh":"學生可能離開聚會，因為生病的父母在家中更需要他。"},{"en":"This phrase explains leaving as a response to greater responsibility.","zh":"這個短語把離開解釋為對更大責任的回應。"},{"en":"Chris’s departure hurts, but it also shows where his love is most needed.","zh":"Chris 的離開令人難受，但也顯示他的愛最被需要的地方。"}],"source":"2014 Q9.pdf","sourcePage":14}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
Object.assign(window.EDMUND_FLASHCARD_SEED,window.EDMUND_DSE_WRITING_PART_B_2014_SEED);
